#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
pub fn metal_pagerank_scratch_bytes(node_count: usize) -> Result<usize> {
    let workspace_words = metal_graph_pagerank_layout(node_count)
        .map_err(candle_error)?
        .words;
    let workspace_bytes = workspace_words
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal PageRank scratch estimate overflow",
            )
        })?;
    graph_components_metrics::pagerank_procedure_scratch_bytes(node_count, workspace_bytes)
}

