    fn apply_shared_temporal_deltas(
        &mut self,
        delta: &ResidentProjectDelta,
        device: &Device,
    ) -> Result<()> {
        let mut backings = self.shared_temporal.clone();
        let mut additions = BTreeMap::<(u8, u64, PropertyId), Vec<TemporalSample>>::new();
        for temporal in &delta.temporal {
            let key = (
                temporal.entity_kind as u8,
                temporal.target,
                temporal.sample.property,
            );
            additions
                .entry(key)
                .or_default()
                .push(temporal.sample.clone());
        }
        let mut affected = BTreeSet::new();
        for (key, samples) in additions {
            let backing = backings
                .iter_mut()
                .find(|backing| {
                    backing.entity_kind as u8 == key.0
                        && backing.target == key.1
                        && backing.property == key.2
                })
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "temporal delta targets a non-resident shared column",
                    )
                })?;
            backing.extend_and_sort(&samples)?;
            affected.insert(key);
        }

        let replaced_bytes = self
            .shared_temporal
            .iter()
            .filter(|backing| {
                affected.contains(&(backing.entity_kind as u8, backing.target, backing.property))
            })
            .map(shared_temporal_column_bytes)
            .fold(0_usize, usize::saturating_add);
        let mut upload = TensorUpload::new(device);
        for key in affected {
            let backing = backings
                .iter_mut()
                .find(|backing| {
                    backing.entity_kind as u8 == key.0
                        && backing.target == key.1
                        && backing.property == key.2
                })
                .ok_or_else(|| Error::internal("shared temporal backing disappeared"))?;
            let integer_value = backing.value_type == TemporalType::Integer;
            let _raw_entity_ids =
                metal_share_paged(&mut upload, &mut backing.entity_ids, DType::I64)?;
            let event_times_nanos =
                metal_share_paged(&mut upload, &mut backing.event_times_nanos, DType::I64)?;
            let _raw_sequence =
                metal_share_paged(&mut upload, &mut backing.sequence_indexes, DType::I64)?;
            let uploaded = upload_properties(&mut upload, &mut backing.values, false)?;
            let mut integers = uploaded.integer;
            let booleans = uploaded.boolean;
            if integer_value {
                let column = match integers.remove(&backing.property) {
                    Some(column) => column,
                    None => shared_null_integer_column(&mut upload, backing.len())?,
                };
                self.temporal_integer.insert(
                    key,
                    IntegerTemporalColumn {
                        rows: backing.len(),
                        entity_ids: upload.u64_order_keys(backing.entity_ids.iter().copied())?,
                        event_times_nanos,
                        sequence_indexes: upload
                            .u64_order_keys(backing.sequence_indexes.iter().copied())?,
                        values: column.values,
                        validity: column.validity,
                    },
                );
            } else {
                self.temporal_integer.remove(&key);
            }
            if !integers.is_empty() || !booleans.is_empty() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "temporal canonical column contains an unrelated integer property",
                ));
            }
        }
        self.shared_temporal = backings;
        self.allocated_bytes = self
            .allocated_bytes
            .saturating_sub(replaced_bytes)
            .saturating_add(upload.allocated_bytes);
        self._all_tensors.extend(upload.tensors);
        self.drop_named_tensor_owners();
        Ok(())
    }

    fn apply_shared_vector_deltas(
        &mut self,
        delta: &ResidentProjectDelta,
        device: &Device,
        previous_node_rows: &PersistentMap<u32>,
        previous_edge_rows: &PersistentMap<u32>,
    ) -> Result<()> {
        let mut backings = self.shared_vectors.clone();
        let mut entity_rows = self
            .vectors
            .iter()
            .map(|(property, column)| (*property, column.entity_rows.clone()))
            .collect::<BTreeMap<_, _>>();
        let mut affected = BTreeSet::new();
        let mut affected_rows = BTreeMap::<PropertyId, BTreeSet<u32>>::new();
        for mutation in &delta.vectors {
            let (property, entity) = match mutation {
                ResolvedVectorMutation::Upsert {
                    property,
                    entity_id,
                    ..
                }
                | ResolvedVectorMutation::Remove {
                    property,
                    entity_id,
                    ..
                } => (*property, *entity_id),
            };
            let backing = backings
                .iter_mut()
                .find(|backing| backing.property == property)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::EmbeddingProfileMismatch,
                        "vector delta targets a non-resident shared column",
                    )
                })?;
            let rows = entity_rows.get_mut(&property).ok_or_else(|| {
                Error::new(
                    ErrorCode::EmbeddingProfileMismatch,
                    "vector delta targets a non-resident canonical column",
                )
            })?;
            apply_shared_vector_mutation(backing, rows, mutation)?;
            if let Some(row) = stable_id_row(rows, entity).copied() {
                affected_rows.entry(property).or_default().insert(row);
            }
            affected.insert(property);
        }

        let replaced_bytes = affected.iter().try_fold(0_usize, |total, property| {
            let column = self.vectors.get(property).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "shared vector column disappeared during replacement",
                )
            })?;
            Ok::<_, Error>(
                total.saturating_add(
                    column
                        .entity_ids
                        .iter()
                        .chain(&column.node_rows)
                        .chain(&column.node_backed)
                        .chain(&column.values)
                        .chain(&column.squared_norms)
                        .chain(&column.versions)
                        .chain(&column.active)
                        .map(|tensor| {
                            tensor
                                .elem_count()
                                .saturating_mul(tensor.dtype().size_in_bytes())
                        })
                        .fold(
                            column.rows.saturating_mul(size_of::<u64>()),
                            usize::saturating_add,
                        ),
                ),
            )
        })?;
        let mut upload = TensorUpload::new(device);
        for property in affected {
            let backing = backings
                .iter_mut()
                .find(|backing| backing.property == property)
                .ok_or_else(|| Error::internal("shared vector backing disappeared"))?;
            let current = self.vectors.get(&property).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "shared vector column disappeared during upload",
                )
            })?;
            let dimension = current.dimension;
            let similarity = current.similarity;
            let dtype = current.dtype;
            let rows = backing.entity_ids.len();
            if rows != current.rows {
                metal_share_paged(&mut upload, &mut backing.entity_ids, DType::I64)?;
            } else {
                upload.allocated_bytes = upload
                    .allocated_bytes
                    .saturating_add(rows * size_of::<u64>());
            }
            let owner_rows = if property == crate::graph::SEMANTIC_RELATIONSHIP_PROPERTY {
                &self.edge_id_rows
            } else {
                &self.node_id_rows
            };
            let remapped_rows = if property == crate::graph::SEMANTIC_RELATIONSHIP_PROPERTY {
                delta
                    .graph
                    .edges
                    .iter()
                    .filter_map(|edge| {
                        (stable_id_row(previous_edge_rows, edge.id.0) != Some(&edge.dense))
                            .then(|| stable_id_row(&current.entity_rows, edge.id.0).copied())
                            .flatten()
                    })
                    .collect::<BTreeSet<_>>()
            } else {
                delta
                    .graph
                    .nodes
                    .iter()
                    .filter_map(|node| {
                        (stable_id_row(previous_node_rows, node.id.0) != Some(&node.dense))
                            .then(|| stable_id_row(&current.entity_rows, node.id.0).copied())
                            .flatten()
                    })
                    .collect::<BTreeSet<_>>()
            };
            let (resident_entity_ids, node_rows, node_backed) = patch_shared_vector_owner_mapping(
                current,
                backing,
                owner_rows,
                &remapped_rows,
                device,
            )?;
            // These allocations remain owned by the replacement, including unchanged shared
            // mappings. Account them without reading or uploading unrelated owner rows.
            for tensor in resident_entity_ids
                .iter()
                .chain(&node_rows)
                .chain(&node_backed)
            {
                upload.allocated_bytes = upload
                    .allocated_bytes
                    .saturating_add(tensor.elem_count() * tensor.dtype().size_in_bytes());
            }
            let values = metal_share_paged(
                &mut upload,
                &mut backing.values,
                match dtype {
                    EmbeddingDType::F16 => DType::F16,
                    EmbeddingDType::Bf16 => DType::BF16,
                },
            )?;
            let mut squared_norms = current
                .squared_norms
                .as_ref()
                .map(|tensor| tensor.copy().map_err(candle_error))
                .transpose()?;
            ensure_tensor_capacity(&mut squared_norms, rows.max(64), DType::F32, device)?;
            for row in affected_rows.get(&property).into_iter().flatten() {
                let start = (*row as usize).checked_mul(dimension).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "vector norm offset overflow",
                    )
                })?;
                let end = start.checked_add(dimension).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "vector norm range overflow",
                    )
                })?;
                let squared_norm = shared_vector_squared_norm(backing, start..end, dtype)?;
                scatter_rows(
                    squared_norms.as_ref().ok_or_else(|| {
                        Error::internal("non-empty vector column has no squared norms")
                    })?,
                    &[*row],
                    &Tensor::from_slice(&[squared_norm], 1, device).map_err(candle_error)?,
                )?;
            }
            upload.allocated_bytes =
                upload
                    .allocated_bytes
                    .saturating_add(squared_norms.as_ref().map_or(0, |tensor| {
                        tensor
                            .elem_count()
                            .saturating_mul(tensor.dtype().size_in_bytes())
                    }));
            let versions = metal_share_paged(&mut upload, &mut backing.versions, DType::I64)?;
            let active = metal_share_paged(&mut upload, &mut backing.active, DType::U8)?;
            self.vectors.insert(
                property,
                VectorColumn {
                    dimension,
                    similarity,
                    dtype,
                    rows,
                    entity_ids: resident_entity_ids,
                    node_rows,
                    node_backed,
                    values,
                    squared_norms,
                    versions,
                    active,
                    entity_rows: entity_rows
                        .remove(&property)
                        .ok_or_else(|| Error::internal("shared vector row map disappeared"))?,
                },
            );
            // Keep the immutable postings live and rerank changed rows from the canonical
            // device matrix. Version filtering excludes their old postings from ANN candidates.
            if let Some(index) = self.ann.get_mut(&property) {
                let old_stale_bytes = index
                    .stale_row_ids
                    .as_ref()
                    .map_or(0, |tensor| tensor.elem_count() * size_of::<u32>());
                for row in affected_rows.get(&property).into_iter().flatten() {
                    if backing.active.get(*row as usize).copied().unwrap_or(false) {
                        index.stale_row_set.insert(*row);
                    } else {
                        index.stale_row_set.remove(row);
                    }
                }
                index.stale_row_ids =
                    upload.optional(&index.stale_row_set.iter().copied().collect::<Vec<_>>())?;
                self.allocated_bytes = self.allocated_bytes.saturating_sub(old_stale_bytes);
            }
        }
        self.shared_vectors = backings;
        self.allocated_bytes = self
            .allocated_bytes
            .saturating_sub(replaced_bytes)
            .saturating_add(upload.allocated_bytes);
        self._all_tensors.extend(upload.tensors);
        self.drop_named_tensor_owners();
        Ok(())
    }

    fn drop_named_tensor_owners(&mut self) {
        let mut named = HashSet::new();
        for tensor in self
            .node_entity_ids
            .iter()
            .chain(&self.edge_entity_ids)
            .chain(&self.node_id_order_keys)
            .chain(&self.node_revisions)
            .chain(&self.node_active)
            .chain(&self.node_layers)
            .chain(std::iter::once(&self.node_label_offsets))
            .chain(&self.node_label_values)
            .chain(self.node_labels.values())
            .chain(&self.edge_active)
            .chain(&self.edge_layers)
            .chain(&self.edge_types)
            .chain(&self.edge_sources)
            .chain(&self.edge_targets)
            .chain(std::iter::once(&self.outgoing_offsets))
            .chain(&self.outgoing_neighbors)
            .chain(&self.outgoing_edges)
            .chain(std::iter::once(&self.incoming_offsets))
            .chain(&self.incoming_neighbors)
            .chain(&self.incoming_edges)
            .chain(&self.outgoing_overlay.packet)
            .chain(&self.incoming_overlay.packet)
        {
            named.insert(tensor.id());
        }
        for column in self.integer_nodes.values() {
            for tensor in column.values.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self.boolean_nodes.values() {
            for tensor in column.values.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self.float_nodes.values() {
            for tensor in column
                .values
                .iter()
                .chain(&column.order_keys)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.string_nodes.values() {
            for tensor in column.values.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self
            .date_nodes
            .values()
            .chain(self.local_time_nodes.values())
        {
            for tensor in column.values.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self.zoned_time_nodes.values() {
            for tensor in column
                .nanos
                .iter()
                .chain(&column.offsets)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.local_datetime_nodes.values() {
            for tensor in column
                .seconds
                .iter()
                .chain(&column.nanos)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.zoned_datetime_nodes.values() {
            for tensor in column
                .seconds
                .iter()
                .chain(&column.nanos)
                .chain(&column.timezones)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.duration_nodes.values() {
            for tensor in column
                .months
                .iter()
                .chain(&column.days)
                .chain(&column.seconds)
                .chain(&column.nanos)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.mixed_nodes.values() {
            named.insert(column.offsets.id());
            for tensor in column.bytes.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self.list_nodes.values().chain(self.map_nodes.values()) {
            named.insert(column.offsets.id());
            for tensor in column.bytes.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for tensor in self.opaque_node_validity.values().flatten() {
            named.insert(tensor.id());
        }
        named.insert(self.node_string_dictionary.offsets.id());
        if let Some(bytes) = &self.node_string_dictionary.bytes {
            named.insert(bytes.id());
        }
        if let Some(ranks) = &self.node_string_dictionary.ranks {
            named.insert(ranks.id());
        }
        for column in self.integer_edges.values() {
            for tensor in column.values.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self.boolean_edges.values() {
            for tensor in column.values.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self.float_edges.values() {
            for tensor in column
                .values
                .iter()
                .chain(&column.order_keys)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.string_edges.values() {
            for tensor in column.values.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self
            .date_edges
            .values()
            .chain(self.local_time_edges.values())
        {
            for tensor in column.values.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self.zoned_time_edges.values() {
            for tensor in column
                .nanos
                .iter()
                .chain(&column.offsets)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.local_datetime_edges.values() {
            for tensor in column
                .seconds
                .iter()
                .chain(&column.nanos)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.zoned_datetime_edges.values() {
            for tensor in column
                .seconds
                .iter()
                .chain(&column.nanos)
                .chain(&column.timezones)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.duration_edges.values() {
            for tensor in column
                .months
                .iter()
                .chain(&column.days)
                .chain(&column.seconds)
                .chain(&column.nanos)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.mixed_edges.values() {
            named.insert(column.offsets.id());
            for tensor in column.bytes.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for column in self.list_edges.values().chain(self.map_edges.values()) {
            named.insert(column.offsets.id());
            for tensor in column.bytes.iter().chain(&column.validity) {
                named.insert(tensor.id());
            }
        }
        for tensor in self.opaque_edge_validity.values().flatten() {
            named.insert(tensor.id());
        }
        named.insert(self.edge_string_dictionary.offsets.id());
        if let Some(bytes) = &self.edge_string_dictionary.bytes {
            named.insert(bytes.id());
        }
        if let Some(ranks) = &self.edge_string_dictionary.ranks {
            named.insert(ranks.id());
        }
        for column in self.vectors.values() {
            for tensor in column
                .entity_ids
                .iter()
                .chain(&column.node_rows)
                .chain(&column.node_backed)
                .chain(&column.values)
                .chain(&column.squared_norms)
                .chain(&column.versions)
                .chain(&column.active)
            {
                named.insert(tensor.id());
            }
        }
        for index in self.ann.values() {
            for tensor in index
                .coarse
                .iter()
                .chain(&index.rows)
                .chain(&index.built_versions)
                .chain(&index.codes)
                .chain(&index.codebook_values)
                .chain(std::iter::once(&index.list_offsets))
                .chain(&index.list_positions)
                .chain(&index.stale_row_ids)
            {
                named.insert(tensor.id());
            }
        }
        for column in self.temporal_integer.values() {
            for tensor in column
                .entity_ids
                .iter()
                .chain(&column.event_times_nanos)
                .chain(&column.sequence_indexes)
                .chain(&column.values)
                .chain(&column.validity)
            {
                named.insert(tensor.id());
            }
        }
        self._all_tensors
            .retain(|tensor| !named.contains(&tensor.id()));
    }

    fn apply_delta_in_place(
        &mut self,
        delta: &ResidentProjectDelta,
        device: &Device,
        apply_graph: bool,
        apply_temporal: bool,
        apply_vectors: bool,
    ) -> Result<()> {
        if delta.project != self.project || delta.bookmark.index <= self.bookmark.index {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident device delta has an invalid project or bookmark",
            ));
        }
        if apply_graph {
            let node_capacity = delta.graph.node_capacity;
            ensure_tensor_capacity(&mut self.node_entity_ids, node_capacity, DType::I64, device)?;
            ensure_tensor_capacity(
                &mut self.node_id_order_keys,
                node_capacity,
                DType::I64,
                device,
            )?;
            ensure_tensor_capacity(&mut self.node_active, node_capacity, DType::U8, device)?;
            ensure_tensor_capacity(&mut self.node_layers, node_capacity, DType::U8, device)?;
            for bitmap in self.node_labels.values_mut() {
                ensure_required_capacity(bitmap, node_capacity, DType::U8, device)?;
            }
            for column in self.integer_nodes.values_mut() {
                ensure_tensor_capacity(&mut column.values, node_capacity, DType::I64, device)?;
                ensure_tensor_capacity(&mut column.validity, node_capacity, DType::U8, device)?;
                column.rows = node_capacity;
            }
            for column in self.boolean_nodes.values_mut() {
                ensure_tensor_capacity(&mut column.values, node_capacity, DType::U8, device)?;
                ensure_tensor_capacity(&mut column.validity, node_capacity, DType::U8, device)?;
                column.rows = node_capacity;
            }
            for column in self.float_nodes.values_mut() {
                ensure_tensor_capacity(&mut column.values, node_capacity, DType::I64, device)?;
                ensure_tensor_capacity(&mut column.order_keys, node_capacity, DType::I64, device)?;
                ensure_tensor_capacity(&mut column.validity, node_capacity, DType::U8, device)?;
                column.rows = node_capacity;
            }
            for column in self.string_nodes.values_mut() {
                ensure_tensor_capacity(&mut column.values, node_capacity, DType::U32, device)?;
                ensure_tensor_capacity(&mut column.validity, node_capacity, DType::U8, device)?;
                column.rows = node_capacity;
            }

            let rows = delta
                .graph
                .nodes
                .iter()
                .map(|row| row.dense)
                .collect::<Vec<_>>();
            if !rows.is_empty() {
                for node in &delta.graph.nodes {
                    if stable_id_row(&self.node_id_rows, node.id.0).is_none() {
                        self.node_id_rows
                            .insert(stable_id_key(node.id.0), node.dense);
                    }
                }
                let raw_ids = Tensor::from_slice(
                    &delta
                        .graph
                        .nodes
                        .iter()
                        .map(|row| row.id.0 as i64)
                        .collect::<Vec<_>>(),
                    rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                let order_keys = Tensor::from_slice(
                    &delta
                        .graph
                        .nodes
                        .iter()
                        .map(|row| (row.id.0 ^ (1_u64 << 63)) as i64)
                        .collect::<Vec<_>>(),
                    rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                let active = Tensor::from_slice(
                    &delta
                        .graph
                        .nodes
                        .iter()
                        .map(|row| u8::from(row.active))
                        .collect::<Vec<_>>(),
                    rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                let layers = Tensor::from_slice(
                    &delta
                        .graph
                        .nodes
                        .iter()
                        .map(|row| row.layer as u8)
                        .collect::<Vec<_>>(),
                    rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                scatter_rows(
                    self.node_entity_ids
                        .as_ref()
                        .ok_or_else(|| Error::internal("raw node ID tensor is absent"))?,
                    &rows,
                    &raw_ids,
                )?;
                scatter_rows(
                    self.node_id_order_keys
                        .as_ref()
                        .ok_or_else(|| Error::internal("node ID order-key tensor is absent"))?,
                    &rows,
                    &order_keys,
                )?;
                scatter_rows(
                    self.node_active
                        .as_ref()
                        .ok_or_else(|| Error::internal("node active tensor is absent"))?,
                    &rows,
                    &active,
                )?;
                scatter_rows(
                    self.node_layers
                        .as_ref()
                        .ok_or_else(|| Error::internal("node layer tensor is absent"))?,
                    &rows,
                    &layers,
                )?;

                let labels = delta
                    .graph
                    .nodes
                    .iter()
                    .flat_map(|row| row.labels.iter().copied())
                    .collect::<std::collections::BTreeSet<_>>();
                for label in labels {
                    self.node_labels.entry(label).or_insert(
                        Tensor::zeros(node_capacity, DType::U8, device).map_err(candle_error)?,
                    );
                }
                for (label, bitmap) in &mut self.node_labels {
                    let membership = Tensor::from_slice(
                        &delta
                            .graph
                            .nodes
                            .iter()
                            .map(|row| u8::from(row.labels.contains(label)))
                            .collect::<Vec<_>>(),
                        rows.len(),
                        device,
                    )
                    .map_err(candle_error)?;
                    scatter_rows(bitmap, &rows, &membership)?;
                }

                let integer_properties = delta
                    .graph
                    .nodes
                    .iter()
                    .flat_map(|row| row.properties.iter())
                    .filter_map(|(property, value)| {
                        matches!(value, ScalarValue::Integer(_)).then_some(*property)
                    })
                    .collect::<std::collections::BTreeSet<_>>();
                for property in integer_properties {
                    self.integer_nodes
                        .entry(property)
                        .or_insert_with(|| IntegerColumn {
                            values: None,
                            validity: None,
                            rows: node_capacity,
                        });
                }
                let boolean_properties = delta
                    .graph
                    .nodes
                    .iter()
                    .flat_map(|row| row.properties.iter())
                    .filter_map(|(property, value)| {
                        matches!(value, ScalarValue::Boolean(_)).then_some(*property)
                    })
                    .collect::<std::collections::BTreeSet<_>>();
                for property in boolean_properties {
                    self.boolean_nodes
                        .entry(property)
                        .or_insert_with(|| BooleanColumn {
                            values: None,
                            validity: None,
                            rows: node_capacity,
                        });
                }
                let float_properties = delta
                    .graph
                    .nodes
                    .iter()
                    .flat_map(|row| row.properties.iter())
                    .filter_map(|(property, value)| {
                        matches!(value, ScalarValue::Float(_)).then_some(*property)
                    })
                    .collect::<std::collections::BTreeSet<_>>();
                for property in float_properties {
                    self.float_nodes
                        .entry(property)
                        .or_insert_with(|| FloatColumn {
                            values: None,
                            order_keys: None,
                            validity: None,
                            rows: node_capacity,
                        });
                }
                let string_properties = delta
                    .graph
                    .nodes
                    .iter()
                    .flat_map(|row| row.properties.iter())
                    .filter_map(|(property, value)| {
                        matches!(value, ScalarValue::String(_)).then_some(*property)
                    })
                    .collect::<std::collections::BTreeSet<_>>();
                for property in string_properties {
                    self.string_nodes
                        .entry(property)
                        .or_insert_with(|| StringColumn {
                            values: None,
                            validity: None,
                            rows: node_capacity,
                            maximum_bytes: 0,
                        });
                }
                let string_values = delta
                    .graph
                    .nodes
                    .iter()
                    .flat_map(|row| row.properties.iter())
                    .filter_map(|(_, value)| match value {
                        ScalarValue::String(value) => Some(value.as_ref()),
                        _ => None,
                    })
                    .collect::<Vec<_>>();
                // Reuses the decoded dictionary when this delta introduces no new string, which
                // is the ordinary case: re-reading a mailbox re-sees addresses and subjects it
                // already holds. Only a delta that actually appends pays to rebuild.
                let host = resident_string_dictionary_host(&mut self.node_string_dictionary)?;
                let mut dictionary_ids = host.ids.clone();
                let mut appended: Vec<String> = Vec::new();
                for value in string_values {
                    if !dictionary_ids.contains_key(value) {
                        let id = checked_u32(
                            host.entries.len().saturating_add(appended.len()),
                            "resident string dictionary ID",
                        )?;
                        appended.push(value.to_owned());
                        dictionary_ids.insert(value.to_owned(), id);
                    }
                }
                if !appended.is_empty() {
                    let mut dictionary_entries = host.entries.clone();
                    dictionary_entries.extend(appended);
                    dictionary_ids = replace_resident_string_dictionary(
                        &mut self.node_string_dictionary,
                        &dictionary_entries,
                        device,
                    )?;
                }
                for (property, column) in &mut self.integer_nodes {
                    ensure_tensor_capacity(&mut column.values, node_capacity, DType::I64, device)?;
                    ensure_tensor_capacity(&mut column.validity, node_capacity, DType::U8, device)?;
                    let mut values = Vec::with_capacity(rows.len());
                    let mut validity = Vec::with_capacity(rows.len());
                    for row in &delta.graph.nodes {
                        match row
                            .properties
                            .iter()
                            .find(|(candidate, _)| candidate == property)
                            .map(|(_, value)| value)
                        {
                            Some(ScalarValue::Integer(value)) => {
                                values.push(*value);
                                validity.push(1_u8);
                            }
                            _ => {
                                values.push(0_i64);
                                validity.push(0_u8);
                            }
                        }
                    }
                    let values =
                        Tensor::from_slice(&values, values.len(), device).map_err(candle_error)?;
                    scatter_rows(
                        column
                            .values
                            .as_ref()
                            .ok_or_else(|| Error::internal("integer value tensor is absent"))?,
                        &rows,
                        &values,
                    )?;
                    let validity = Tensor::from_slice(&validity, validity.len(), device)
                        .map_err(candle_error)?;
                    scatter_rows(
                        column
                            .validity
                            .as_ref()
                            .ok_or_else(|| Error::internal("integer validity tensor is absent"))?,
                        &rows,
                        &validity,
                    )?;
                }
                for (property, column) in &mut self.boolean_nodes {
                    ensure_tensor_capacity(&mut column.values, node_capacity, DType::U8, device)?;
                    ensure_tensor_capacity(&mut column.validity, node_capacity, DType::U8, device)?;
                    let mut values = Vec::with_capacity(rows.len());
                    let mut validity = Vec::with_capacity(rows.len());
                    for row in &delta.graph.nodes {
                        match row
                            .properties
                            .iter()
                            .find(|(candidate, _)| candidate == property)
                            .map(|(_, value)| value)
                        {
                            Some(ScalarValue::Boolean(value)) => {
                                values.push(u8::from(*value));
                                validity.push(1_u8);
                            }
                            _ => {
                                values.push(0_u8);
                                validity.push(0_u8);
                            }
                        }
                    }
                    let values =
                        Tensor::from_slice(&values, values.len(), device).map_err(candle_error)?;
                    scatter_rows(
                        column
                            .values
                            .as_ref()
                            .ok_or_else(|| Error::internal("Boolean value tensor is absent"))?,
                        &rows,
                        &values,
                    )?;
                    let validity = Tensor::from_slice(&validity, validity.len(), device)
                        .map_err(candle_error)?;
                    scatter_rows(
                        column
                            .validity
                            .as_ref()
                            .ok_or_else(|| Error::internal("Boolean validity tensor is absent"))?,
                        &rows,
                        &validity,
                    )?;
                }
                for (property, column) in &mut self.float_nodes {
                    ensure_tensor_capacity(&mut column.values, node_capacity, DType::I64, device)?;
                    ensure_tensor_capacity(
                        &mut column.order_keys,
                        node_capacity,
                        DType::I64,
                        device,
                    )?;
                    ensure_tensor_capacity(&mut column.validity, node_capacity, DType::U8, device)?;
                    let mut raw_values = Vec::with_capacity(rows.len());
                    let mut order_keys = Vec::with_capacity(rows.len());
                    let mut validity = Vec::with_capacity(rows.len());
                    for row in &delta.graph.nodes {
                        match row
                            .properties
                            .iter()
                            .find(|(candidate, _)| candidate == property)
                            .map(|(_, value)| value)
                        {
                            Some(ScalarValue::Float(value)) => {
                                raw_values.push(value.0.to_bits() as i64);
                                order_keys.push(ordered_float_sort_key(value.0));
                                validity.push(1_u8);
                            }
                            _ => {
                                raw_values.push(0_i64);
                                order_keys.push(0_i64);
                                validity.push(0_u8);
                            }
                        }
                    }
                    let raw_values = Tensor::from_slice(&raw_values, raw_values.len(), device)
                        .map_err(candle_error)?;
                    scatter_rows(
                        column
                            .values
                            .as_ref()
                            .ok_or_else(|| Error::internal("float value tensor is absent"))?,
                        &rows,
                        &raw_values,
                    )?;
                    let order_keys = Tensor::from_slice(&order_keys, order_keys.len(), device)
                        .map_err(candle_error)?;
                    scatter_rows(
                        column
                            .order_keys
                            .as_ref()
                            .ok_or_else(|| Error::internal("float order-key tensor is absent"))?,
                        &rows,
                        &order_keys,
                    )?;
                    let validity = Tensor::from_slice(&validity, validity.len(), device)
                        .map_err(candle_error)?;
                    scatter_rows(
                        column
                            .validity
                            .as_ref()
                            .ok_or_else(|| Error::internal("float validity tensor is absent"))?,
                        &rows,
                        &validity,
                    )?;
                }
                for (property, column) in &mut self.string_nodes {
                    ensure_tensor_capacity(&mut column.values, node_capacity, DType::U32, device)?;
                    ensure_tensor_capacity(&mut column.validity, node_capacity, DType::U8, device)?;
                    let mut values = Vec::with_capacity(rows.len());
                    let mut validity = Vec::with_capacity(rows.len());
                    for row in &delta.graph.nodes {
                        match row
                            .properties
                            .iter()
                            .find(|(candidate, _)| candidate == property)
                            .map(|(_, value)| value)
                        {
                            Some(ScalarValue::String(value)) => {
                                let id = dictionary_ids.get(value.as_ref()).copied().ok_or_else(
                                    || {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "resident string dictionary omitted a delta value",
                                        )
                                    },
                                )?;
                                values.push(id);
                                validity.push(1_u8);
                                column.maximum_bytes = column.maximum_bytes.max(value.len());
                            }
                            _ => {
                                values.push(0_u32);
                                validity.push(0_u8);
                            }
                        }
                    }
                    let values =
                        Tensor::from_slice(&values, values.len(), device).map_err(candle_error)?;
                    scatter_rows(
                        column
                            .values
                            .as_ref()
                            .ok_or_else(|| Error::internal("string value tensor is absent"))?,
                        &rows,
                        &values,
                    )?;
                    let validity = Tensor::from_slice(&validity, validity.len(), device)
                        .map_err(candle_error)?;
                    scatter_rows(
                        column
                            .validity
                            .as_ref()
                            .ok_or_else(|| Error::internal("string validity tensor is absent"))?,
                        &rows,
                        &validity,
                    )?;
                }
            }

            let edge_capacity = delta.graph.edge_capacity;
            ensure_tensor_capacity(&mut self.edge_entity_ids, edge_capacity, DType::I64, device)?;
            ensure_tensor_capacity(&mut self.edge_active, edge_capacity, DType::U8, device)?;
            ensure_tensor_capacity(&mut self.edge_layers, edge_capacity, DType::U8, device)?;
            ensure_tensor_capacity(&mut self.edge_types, edge_capacity, DType::I64, device)?;
            ensure_tensor_capacity(&mut self.edge_sources, edge_capacity, DType::U32, device)?;
            ensure_tensor_capacity(&mut self.edge_targets, edge_capacity, DType::U32, device)?;
            for column in self.integer_edges.values_mut() {
                ensure_tensor_capacity(&mut column.values, edge_capacity, DType::I64, device)?;
                ensure_tensor_capacity(&mut column.validity, edge_capacity, DType::U8, device)?;
                column.rows = edge_capacity;
            }
            for column in self.boolean_edges.values_mut() {
                ensure_tensor_capacity(&mut column.values, edge_capacity, DType::U8, device)?;
                ensure_tensor_capacity(&mut column.validity, edge_capacity, DType::U8, device)?;
                column.rows = edge_capacity;
            }
            for column in self.float_edges.values_mut() {
                ensure_tensor_capacity(&mut column.values, edge_capacity, DType::I64, device)?;
                ensure_tensor_capacity(&mut column.order_keys, edge_capacity, DType::I64, device)?;
                ensure_tensor_capacity(&mut column.validity, edge_capacity, DType::U8, device)?;
                column.rows = edge_capacity;
            }
            for column in self.string_edges.values_mut() {
                ensure_tensor_capacity(&mut column.values, edge_capacity, DType::U32, device)?;
                ensure_tensor_capacity(&mut column.validity, edge_capacity, DType::U8, device)?;
                column.rows = edge_capacity;
            }
            let edge_rows = delta
                .graph
                .edges
                .iter()
                .map(|row| row.dense)
                .collect::<Vec<_>>();
            if !edge_rows.is_empty() {
                for edge in &delta.graph.edges {
                    self.edge_id_rows
                        .insert_cow(stable_id_key(edge.id.0), edge.dense);
                }
                let ids = Tensor::from_slice(
                    &delta
                        .graph
                        .edges
                        .iter()
                        .map(|row| row.id.0 as i64)
                        .collect::<Vec<_>>(),
                    edge_rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                let active = Tensor::from_slice(
                    &delta
                        .graph
                        .edges
                        .iter()
                        .map(|row| u8::from(row.active))
                        .collect::<Vec<_>>(),
                    edge_rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                let layers = Tensor::from_slice(
                    &delta
                        .graph
                        .edges
                        .iter()
                        .map(|row| row.layer as u8)
                        .collect::<Vec<_>>(),
                    edge_rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                let kinds = Tensor::from_slice(
                    &delta
                        .graph
                        .edges
                        .iter()
                        .map(|row| row.relationship_type.0 as i64)
                        .collect::<Vec<_>>(),
                    edge_rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                let sources = Tensor::from_slice(
                    &delta
                        .graph
                        .edges
                        .iter()
                        .map(|row| row.source)
                        .collect::<Vec<_>>(),
                    edge_rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                let targets = Tensor::from_slice(
                    &delta
                        .graph
                        .edges
                        .iter()
                        .map(|row| row.target)
                        .collect::<Vec<_>>(),
                    edge_rows.len(),
                    device,
                )
                .map_err(candle_error)?;
                scatter_rows(
                    self.edge_entity_ids
                        .as_ref()
                        .ok_or_else(|| Error::internal("raw relationship ID tensor is absent"))?,
                    &edge_rows,
                    &ids,
                )?;
                scatter_rows(
                    self.edge_active
                        .as_ref()
                        .ok_or_else(|| Error::internal("edge active tensor is absent"))?,
                    &edge_rows,
                    &active,
                )?;
                scatter_rows(
                    self.edge_layers
                        .as_ref()
                        .ok_or_else(|| Error::internal("edge layer tensor is absent"))?,
                    &edge_rows,
                    &layers,
                )?;
                scatter_rows(
                    self.edge_types
                        .as_ref()
                        .ok_or_else(|| Error::internal("edge type tensor is absent"))?,
                    &edge_rows,
                    &kinds,
                )?;
                scatter_rows(
                    self.edge_sources
                        .as_ref()
                        .ok_or_else(|| Error::internal("edge source tensor is absent"))?,
                    &edge_rows,
                    &sources,
                )?;
                scatter_rows(
                    self.edge_targets
                        .as_ref()
                        .ok_or_else(|| Error::internal("edge target tensor is absent"))?,
                    &edge_rows,
                    &targets,
                )?;
            }

            while self.outgoing_rows.len() < node_capacity {
                self.outgoing_rows.push(None);
            }
            for row in &delta.graph.outgoing {
                let replacement = if row.neighbors.is_empty() {
                    None
                } else {
                    Some((
                        Tensor::from_slice(&row.neighbors, row.neighbors.len(), device)
                            .map_err(candle_error)?,
                        Tensor::from_slice(&row.edges, row.edges.len(), device)
                            .map_err(candle_error)?,
                    ))
                };
                self.outgoing_rows
                    .replace(row.dense as usize, replacement)
                    .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
            }
            while self.incoming_rows.len() < node_capacity {
                self.incoming_rows.push(None);
            }
            for row in &delta.graph.incoming {
                let replacement = if row.neighbors.is_empty() {
                    None
                } else {
                    Some((
                        Tensor::from_slice(&row.neighbors, row.neighbors.len(), device)
                            .map_err(candle_error)?,
                        Tensor::from_slice(&row.edges, row.edges.len(), device)
                            .map_err(candle_error)?,
                    ))
                };
                self.incoming_rows
                    .replace(row.dense as usize, replacement)
                    .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
            }
            let (offset_values, offsets, neighbors, edges) =
                pack_adjacency_rows(&self.outgoing_rows, device)?;
            self.outgoing_offsets = offsets;
            self.outgoing_neighbors = neighbors;
            self.outgoing_edges = edges;
            self.outgoing_rows = adjacency_row_views(
                &offset_values,
                self.outgoing_neighbors.as_ref(),
                self.outgoing_edges.as_ref(),
            )?;
            let (offset_values, offsets, neighbors, edges) =
                pack_adjacency_rows(&self.incoming_rows, device)?;
            self.incoming_offsets = offsets;
            self.incoming_neighbors = neighbors;
            self.incoming_edges = edges;
            self.incoming_rows = adjacency_row_views(
                &offset_values,
                self.incoming_neighbors.as_ref(),
                self.incoming_edges.as_ref(),
            )?;
        }

        if apply_temporal {
            for temporal in &delta.temporal {
                apply_integer_temporal_delta(&mut self.temporal_integer, temporal, device)?;
            }
        }
        if apply_vectors {
            for mutation in &delta.vectors {
                apply_vector_delta(
                    &mut self.vectors,
                    &mut self.ann,
                    &self.node_id_rows,
                    &self.edge_id_rows,
                    mutation,
                    device,
                )?;
            }
        }
        // Canonical vector mutations maintain a version-filtered ANN delta above. Ordinary
        // graph invalidation must preserve that searchable generation; index administration
        // replaces the complete resident image instead of using this sparse mutation path.

        self.drop_named_tensor_owners();
        self.node_count = delta.graph.node_capacity;
        self.edge_count = delta.graph.edge_capacity;
        self.revision = delta.graph.revision;
        self.bookmark = delta.bookmark;
        Ok(())
    }

    pub fn scan_nodes(
        &self,
        label: Option<LabelId>,
        layers: LayerMask,
        cancellation: &CancellationToken,
    ) -> Result<Vec<u32>> {
        ensure_not_cancelled(cancellation)?;
        if self.node_count == 0 {
            return Ok(Vec::new());
        }
        let labels = label.into_iter().collect::<Vec<_>>();
        let mask = self.node_selection_mask(&labels, layers)?;
        let mask = mask.to_vec1::<u8>().map_err(candle_error)?;
        ensure_not_cancelled(cancellation)?;
        mask.into_iter()
            .enumerate()
            .filter(|(_, selected)| *selected != 0)
            .map(|(row, _)| {
                u32::try_from(row).map_err(|_| {
                    Error::new(ErrorCode::ResultBudgetExceeded, "node row exceeds u32")
                })
            })
            .collect()
    }

    fn node_selection_mask(&self, labels: &[LabelId], layers: LayerMask) -> Result<Tensor> {
        let active = self
            .node_active
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty graph has no active-node tensor"))?;
        // The canonical activity lane is already a 0/1 selection mask. ALL layers therefore
        // needs no three equality kernels, two unions, threshold, second active comparison, or
        // final multiply; returning the immutable resident tensor is the exact same mask.
        let mut mask = if layers == LayerMask::ALL {
            active.clone()
        } else {
            let layer_values = self
                .node_layers
                .as_ref()
                .ok_or_else(|| Error::internal("non-empty graph has no node-layer tensor"))?;
            let mut layer_mask: Option<Tensor> = None;
            for layer in crate::Layer::ALL {
                if layers.contains_layer(layer) {
                    let selected = layer_values.eq(layer as u8).map_err(candle_error)?;
                    layer_mask = Some(match layer_mask {
                        Some(current) => current.broadcast_add(&selected).map_err(candle_error)?,
                        None => selected,
                    });
                }
            }
            let layer_mask = layer_mask
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "node scan layer mask is empty"))?;
            active
                .broadcast_mul(&layer_mask.gt(0_u8).map_err(candle_error)?)
                .map_err(candle_error)?
        };
        for wanted in labels {
            let membership = self.node_labels.get(wanted).ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "scan references an unknown node label",
                )
            })?;
            mask = mask.broadcast_mul(membership).map_err(candle_error)?;
        }
        Ok(mask)
    }

    /// Visibility for an already-bounded candidate relation. Building the full node-domain mask
    /// here and gathering a handful of endpoints made a selective expansion pay O(all nodes) a
    /// second time after its start predicate had reduced the relation. Every lane below is gathered
    /// first, so work tracks only the expansion candidates while preserving the identical active,
    /// layer, and conjunctive-label rules.
    fn node_selection_mask_for_rows(
        &self,
        rows: &Tensor,
        labels: &[LabelId],
        layers: LayerMask,
    ) -> Result<Tensor> {
        let active = self
            .node_active
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty graph has no active-node tensor"))?
            .index_select(rows, 0)
            .map_err(candle_error)?;
        let mut mask = if layers == LayerMask::ALL {
            active
        } else {
            let layer_values = self
                .node_layers
                .as_ref()
                .ok_or_else(|| Error::internal("non-empty graph has no node-layer tensor"))?
                .index_select(rows, 0)
                .map_err(candle_error)?;
            let mut layer_mask: Option<Tensor> = None;
            for layer in crate::Layer::ALL {
                if layers.contains_layer(layer) {
                    let selected = layer_values.eq(layer as u8).map_err(candle_error)?;
                    layer_mask = Some(match layer_mask {
                        Some(current) => current.broadcast_add(&selected).map_err(candle_error)?,
                        None => selected,
                    });
                }
            }
            let layer_mask = layer_mask
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "node scan layer mask is empty"))?;
            active
                .broadcast_mul(&layer_mask.gt(0_u8).map_err(candle_error)?)
                .map_err(candle_error)?
        };
        for wanted in labels {
            let membership = self.node_labels.get(wanted).ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "scan references an unknown node label",
                )
            })?;
            let membership = membership.index_select(rows, 0).map_err(candle_error)?;
            mask = mask.broadcast_mul(&membership).map_err(candle_error)?;
        }
        Ok(mask)
    }

    fn variable_path_node_selection_mask(
        &self,
        labels: &[LabelId],
        predicates: &[super::ResidentVariablePathStringSetPredicate],
        layers: LayerMask,
        device: &Device,
        cancellation: &CancellationToken,
    ) -> Result<Tensor> {
        let mut mask = self.node_selection_mask(labels, layers)?;
        if predicates.is_empty() {
            return Ok(mask);
        }
        let rows = Tensor::arange(
            0_u32,
            checked_u32(self.node_count, "variable-path predicate node rows")?,
            device,
        )
        .map_err(candle_error)?;
        for predicate in predicates {
            ensure_not_cancelled(cancellation)?;
            let mut membership =
                Tensor::zeros(self.node_count, DType::U8, device).map_err(candle_error)?;
            for value in &predicate.values {
                let equals = self
                    .selected_string_comparison(
                        predicate.property,
                        &rows,
                        value.as_bytes(),
                        CompareOp::Eq,
                        device,
                        cancellation,
                    )?
                    .eq(2_u8)
                    .map_err(candle_error)?;
                membership = membership
                    .broadcast_add(&equals)
                    .and_then(|sum| sum.gt(0_u8))
                    .map_err(candle_error)?;
            }
            mask = mask.broadcast_mul(&membership).map_err(candle_error)?;
        }
        Ok(mask)
    }

    pub fn filter_node_i64(
        &self,
        property: PropertyId,
        operation: CompareOp,
        operand: i64,
        cancellation: &CancellationToken,
    ) -> Result<Vec<u32>> {
        let column = self.integer_nodes.get(&property).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "resident property is not an integer column",
            )
        })?;
        if column.rows == 0 {
            return Ok(Vec::new());
        }
        let values = column
            .values
            .as_ref()
            .ok_or_else(|| Error::internal("integer column values are absent"))?;
        let validity = column
            .validity
            .as_ref()
            .ok_or_else(|| Error::internal("integer column validity is absent"))?;
        filter_tensor(values, validity, operation, operand, cancellation)
    }

    pub fn expand_out(
        &self,
        _device: &Device,
        sources: &[u32],
        cancellation: &CancellationToken,
    ) -> Result<Vec<(u32, u32, u32)>> {
        if let Some(backing) = self.shared_graph.as_ref() {
            return expand_shared_adjacency(
                &backing.outgoing,
                &self.outgoing_overlay,
                sources,
                false,
                usize::MAX,
                cancellation,
            );
        }
        expand_adjacency_rows(
            &self.outgoing_rows,
            sources,
            false,
            usize::MAX,
            cancellation,
        )
    }

    pub fn expand_in(
        &self,
        _device: &Device,
        targets: &[u32],
        cancellation: &CancellationToken,
    ) -> Result<Vec<(u32, u32, u32)>> {
        if let Some(backing) = self.shared_graph.as_ref() {
            return expand_shared_adjacency(
                &backing.incoming,
                &self.incoming_overlay,
                targets,
                true,
                usize::MAX,
                cancellation,
            );
        }
        expand_adjacency_rows(&self.incoming_rows, targets, true, usize::MAX, cancellation)
    }

