    pub fn search_vectors(
        &self,
        device: &Device,
        request: &ResidentVectorQuery,
        cancellation: &CancellationToken,
    ) -> Result<ResidentVectorResult> {
        let vector = self.vectors.get(&request.property).ok_or_else(|| {
            Error::new(ErrorCode::IndexUnavailable, "vector column is not resident")
        })?;
        super::cpu::validate_vector_queries(request, vector.dimension)?;
        let profile = self.profile.clone().ok_or_else(|| {
            Error::new(
                ErrorCode::EmbeddingProfileMismatch,
                "resident vector column has no embedding profile",
            )
        })?;
        if profile.dimension as usize != vector.dimension
            || profile.dtype != vector.dtype
            || profile.similarity != vector.similarity
        {
            return Err(Error::new(
                ErrorCode::EmbeddingProfileMismatch,
                "resident vector column and embedding profile differ",
            ));
        }
        let matrix = vector
            .values
            .as_ref()
            .map(|tensor| {
                tensor
                    .narrow(0, 0, vector.rows.saturating_mul(vector.dimension))
                    .map_err(candle_error)
            })
            .transpose()?;
        let relationship_owned = request.property == crate::graph::SEMANTIC_RELATIONSHIP_PROPERTY;
        if relationship_owned && request.selection.is_some() {
            return Err(Error::new(
                ErrorCode::QueryType,
                "relationship vector search cannot use a node selection",
            ));
        }
        let layer_candidates = if vector.rows == 0
            || self.node_count == 0
            || (relationship_owned && self.edge_count == 0)
        {
            Tensor::zeros(vector.rows, DType::U8, device).map_err(candle_error)?
        } else if relationship_owned {
            let rows = vector
                .node_rows
                .as_ref()
                .ok_or_else(|| Error::internal("relationship vector column has no owner rows"))?
                .narrow(0, 0, vector.rows)
                .map_err(candle_error)?;
            let backed = vector
                .node_backed
                .as_ref()
                .ok_or_else(|| Error::internal("relationship vector column has no owner mask"))?
                .narrow(0, 0, vector.rows)
                .map_err(candle_error)?;
            let mut visible = self
                .edge_active
                .as_ref()
                .ok_or_else(|| Error::internal("relationship vector graph has no activity tensor"))?
                .index_select(&rows, 0)
                .and_then(|active| active.broadcast_mul(&backed))
                .map_err(candle_error)?;
            if request.layers != LayerMask::ALL {
                let layers = self
                    .edge_layers
                    .as_ref()
                    .ok_or_else(|| {
                        Error::internal("relationship vector graph has no layer tensor")
                    })?
                    .index_select(&rows, 0)
                    .map_err(candle_error)?;
                let mut allowed =
                    Tensor::zeros(vector.rows, DType::U8, device).map_err(candle_error)?;
                for layer in crate::Layer::ALL {
                    if request.layers.contains_layer(layer) {
                        allowed = allowed
                            .broadcast_add(&layers.eq(layer as u8).map_err(candle_error)?)
                            .map_err(candle_error)?;
                    }
                }
                visible = visible.broadcast_mul(&allowed).map_err(candle_error)?;
            }
            for endpoints in [&self.edge_sources, &self.edge_targets] {
                let endpoints = endpoints
                    .as_ref()
                    .ok_or_else(|| {
                        Error::internal("relationship vector graph has no endpoint tensor")
                    })?
                    .index_select(&rows, 0)
                    .map_err(candle_error)?;
                visible = visible
                    .broadcast_mul(&self.node_selection_mask_for_rows(
                        &endpoints,
                        &[],
                        request.layers,
                    )?)
                    .map_err(candle_error)?;
            }
            visible
        } else {
            let visible_nodes = if let Some(selection) = &request.selection {
                if selection.project != request.project || selection.layers != request.layers {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "vector candidate stage targets a different project or layer mask",
                    ));
                }
                let rows = self.select_node_pipeline_rows(device, selection, cancellation)?;
                scatter_counts(
                    rows.binding(super::ResidentNodeBinding::Start)?,
                    self.node_count,
                    device,
                )?
                .gt(0_u32)
                .map_err(candle_error)?
            } else {
                self.node_selection_mask(&[], request.layers)?
            };
            let node_rows = vector
                .node_rows
                .as_ref()
                .ok_or_else(|| Error::internal("non-empty vector column has no node rows"))?
                .narrow(0, 0, vector.rows)
                .map_err(candle_error)?;
            let node_backed = vector
                .node_backed
                .as_ref()
                .ok_or_else(|| Error::internal("non-empty vector column has no node-kind mask"))?
                .narrow(0, 0, vector.rows)
                .map_err(candle_error)?;
            visible_nodes
                .index_select(&node_rows, 0)
                .and_then(|visible| visible.broadcast_mul(&node_backed))
                .map_err(candle_error)?
        };
        let layer_candidates = if let Some(allowed) = &request.allowed_entities {
            let rows = allowed
                .iter()
                .filter_map(|id| stable_id_row(&vector.entity_rows, *id).copied())
                .collect::<BTreeSet<_>>();
            let rows = rows.into_iter().collect::<Vec<_>>();
            if rows.is_empty() {
                Tensor::zeros(vector.rows, DType::U8, device).map_err(candle_error)?
            } else {
                let rows = Tensor::from_slice(&rows, rows.len(), device).map_err(candle_error)?;
                let allowed = scatter_counts(&rows, vector.rows, device)?
                    .gt(0_u32)
                    .map_err(candle_error)?;
                layer_candidates
                    .broadcast_mul(&allowed)
                    .map_err(candle_error)?
            }
        } else {
            layer_candidates
        };
        let selected_ann = match request.access {
            ResidentVectorAccess::Exact => None,
            ResidentVectorAccess::IvfPq => {
                let ann = self.ann.get(&request.property).ok_or_else(|| {
                    Error::new(
                        ErrorCode::IndexUnavailable,
                        "physical IVF-PQ access path is not resident",
                    )
                })?;
                if ann.build_generation == [0_u8; 32] {
                    return Err(Error::new(
                        ErrorCode::IndexUnavailable,
                        "physical IVF-PQ access path has no build generation",
                    ));
                }
                Some(ann)
            }
        };
        let exact_candidate_rows = selected_ann
            .is_none()
            .then(|| selected_positions(&layer_candidates, vector.rows, device, cancellation))
            .transpose()?;
        let mut batches = Vec::with_capacity(request.query_count);
        for query_row in 0..request.query_count {
            ensure_not_cancelled(cancellation)?;
            let start = query_row * vector.dimension;
            let mut query = request.queries[start..start + vector.dimension].to_vec();
            prepare_vector_query(vector.similarity, &mut query)?;
            let ann_candidates = selected_ann
                .map(|ann| {
                    ann_candidate_rows(
                        ann,
                        vector,
                        &layer_candidates,
                        request.limit,
                        device,
                        &query,
                        cancellation,
                    )
                })
                .transpose()?;
            batches.push(score_device_vectors(
                matrix.as_ref(),
                vector,
                &query,
                request.limit,
                ann_candidates.as_ref().or(exact_candidate_rows.as_ref()),
                device,
                cancellation,
            )?);
        }
        Ok(ResidentVectorResult {
            project: self.project,
            bookmark: self.bookmark,
            profile,
            similarity: vector.similarity,
            hits: batches,
            approximate_candidates: selected_ann.is_some(),
            access: request.access,
            candidate_budget: selected_ann.map_or(0, |ann| {
                u32::try_from(ann.config.candidate_budget.max(request.limit)).unwrap_or(u32::MAX)
            }),
            build_generation: selected_ann.map_or([0_u8; 32], |ann| ann.build_generation),
        })
    }

    pub fn sort_rows(
        &self,
        device: &Device,
        request: &ResidentSortRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentSortResult> {
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        if request.row_count == 0 {
            return Ok(ResidentSortResult {
                positions: Vec::new(),
            });
        }
        let result_count = request
            .limit
            .unwrap_or(request.row_count)
            .min(request.row_count);
        if result_count == 0 {
            return Ok(ResidentSortResult {
                positions: Vec::new(),
            });
        }
        let order = if let Ok((rows, property, key)) = request.single_node_property() {
            let (values, validity) = self.selected_integer_column(device, property, rows)?;
            stable_nullable_integer_order(
                &values,
                &validity,
                key.descending,
                key.nulls_first,
                request.limit.map(|_| result_count),
                device,
                cancellation,
            )?
        } else {
            #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
            {
                if !matches!(device, Device::Metal(_))
                    || request
                        .keys
                        .iter()
                        .any(|key| !matches!(key.source, ResidentSortSource::Materialized(_)))
                {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "selected accelerator lacks this typed resident sort path",
                    ));
                }
                let mut positions = None;
                for key in request.keys.iter().rev() {
                    let ResidentSortSource::Materialized(column) = &key.source else {
                        return Err(Error::internal(
                            "materialized sort key validation changed during dispatch",
                        ));
                    };
                    positions = Some(metal_stable_encoded_argsort(
                        column,
                        positions,
                        key.descending,
                        key.nulls_first,
                        device,
                        cancellation,
                    )?);
                }
                positions.ok_or_else(|| Error::internal("resident sort has no keys"))?
            }
            #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
            {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "selected accelerator lacks materialized resident sorting",
                ));
            }
        };
        let order = order.narrow(0, 0, result_count).map_err(candle_error)?;
        let positions = match order.dtype() {
            DType::U32 => order.to_vec1::<u32>().map_err(candle_error)?,
            DType::I64 => order
                .to_vec1::<i64>()
                .map_err(candle_error)?
                .into_iter()
                .map(|position| {
                    u32::try_from(position).map_err(|_| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident sort returned a source position outside its u32 result ABI",
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident sort returned an invalid source-position type",
                ));
            }
        };
        ensure_not_cancelled(cancellation)?;
        Ok(ResidentSortResult { positions })
    }

    pub fn join_node_i64(
        &self,
        device: &Device,
        request: &ResidentJoinRequest,
        cancellation: &CancellationToken,
    ) -> Result<Vec<ResidentJoinPair>> {
        ensure_not_cancelled(cancellation)?;
        if request.left_rows.is_empty() || request.right_rows.is_empty() {
            return Ok(Vec::new());
        }
        checked_u32(request.left_rows.len(), "join left input")?;
        checked_u32(request.right_rows.len(), "join right input")?;
        let (left_values, left_validity) =
            self.selected_integer_column(device, request.left_property, &request.left_rows)?;
        let (right_values, right_validity) =
            self.selected_integer_column(device, request.right_property, &request.right_rows)?;

        let right_order = stable_nullable_integer_order(
            &right_values,
            &right_validity,
            false,
            false,
            None,
            device,
            cancellation,
        )?;
        let sorted_right_values = right_values
            .index_select(&right_order, 0)
            .map_err(candle_error)?;
        let sorted_right_validity = device_index_select(&right_validity, &right_order, 0)?;
        let valid_right_count = sorted_right_validity
            .to_dtype(DType::U32)
            .and_then(|values| values.sum_all())
            .and_then(|value| value.to_scalar::<u32>())
            .map_err(candle_error)? as usize;
        if valid_right_count == 0 {
            return Ok(Vec::new());
        }

        let lower = sorted_integer_bound(
            &sorted_right_values,
            valid_right_count,
            &left_values,
            false,
            device,
            cancellation,
        )?;
        let upper = sorted_integer_bound(
            &sorted_right_values,
            valid_right_count,
            &left_values,
            true,
            device,
            cancellation,
        )?;
        let counts = upper
            .sub(&lower)
            .and_then(|counts| counts.broadcast_mul(&left_validity.to_dtype(DType::I64)?))
            .map_err(candle_error)?;
        let scan_cap = request
            .max_pairs
            .min(u32::MAX as usize - 1)
            .saturating_add(1) as i64;
        let cumulative = bounded_inclusive_scan_i64(&counts, scan_cap, device, cancellation)?;
        let result_count = cumulative
            .narrow(0, cumulative.elem_count() - 1, 1)
            .and_then(|count| count.to_vec1::<i64>())
            .map_err(candle_error)?;
        let result_count = *result_count
            .first()
            .ok_or_else(|| Error::internal("resident join pair count is absent"))?;
        if result_count < 0 {
            return Err(Error::internal("resident join pair count became negative"));
        }
        let result_count = usize::try_from(result_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident equality join result does not fit host address space",
            )
        })?;
        if result_count > request.max_pairs {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident equality join exceeded its pair budget",
            ));
        }
        if result_count >= u32::MAX as usize {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident equality join exceeds the bounded result-batch index space",
            ));
        }
        if result_count == 0 {
            return Ok(Vec::new());
        }
        let result_count_i64 = i64::try_from(result_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident equality join result exceeds i64 device indexing",
            )
        })?;
        let output_positions =
            Tensor::arange(0_i64, result_count_i64, device).map_err(candle_error)?;
        let left_positions = sorted_integer_bound(
            &cumulative,
            cumulative.elem_count(),
            &output_positions,
            true,
            device,
            cancellation,
        )?;
        let exclusive = cumulative.sub(&counts).map_err(candle_error)?;
        let left_offsets = exclusive
            .index_select(&left_positions, 0)
            .map_err(candle_error)?;
        let right_offsets = lower
            .index_select(&left_positions, 0)
            .and_then(|lower| lower.add(&output_positions.sub(&left_offsets)?))
            .and_then(|positions| positions.to_dtype(DType::U32))
            .map_err(candle_error)?;
        let right_positions = right_order
            .index_select(&right_offsets, 0)
            .and_then(|positions| positions.to_dtype(DType::U32))
            .and_then(|positions| positions.to_vec1::<u32>())
            .map_err(candle_error)?;
        let left_positions = left_positions
            .to_dtype(DType::U32)
            .and_then(|positions| positions.to_vec1::<u32>())
            .map_err(candle_error)?;
        ensure_not_cancelled(cancellation)?;
        Ok(left_positions
            .into_iter()
            .zip(right_positions)
            .map(|(left_position, right_position)| ResidentJoinPair {
                left_position,
                right_position,
            })
            .collect())
    }

    pub fn group_node_i64(
        &self,
        device: &Device,
        request: &ResidentGroupRequest,
        cancellation: &CancellationToken,
    ) -> Result<Vec<ResidentGroup>> {
        ensure_not_cancelled(cancellation)?;
        if request.rows.is_empty() {
            return Ok(Vec::new());
        }
        let rows =
            Tensor::from_slice(&request.rows, request.rows.len(), device).map_err(candle_error)?;
        self.group_selected_node_i64(
            &rows,
            Some((request.key_property, &rows)),
            Some((request.value_property, &rows)),
            request.aggregate,
            usize::MAX,
            device,
            cancellation,
        )
    }

    fn group_selected_node_i64(
        &self,
        rows: &Tensor,
        key_input: Option<(PropertyId, &Tensor)>,
        value_input: Option<(PropertyId, &Tensor)>,
        aggregate: ResidentAggregate,
        max_groups: usize,
        device: &Device,
        cancellation: &CancellationToken,
    ) -> Result<Vec<ResidentGroup>> {
        let row_count = rows.elem_count();
        if row_count == 0 {
            if key_input.is_none() && max_groups == 0 {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident grouping exceeded the result row budget",
                ));
            }
            return Ok(if key_input.is_none() {
                vec![ResidentGroup {
                    key: None,
                    rows: 0,
                    value: empty_integer_aggregate(aggregate),
                }]
            } else {
                Vec::new()
            });
        }
        if key_input
            .into_iter()
            .chain(value_input)
            .any(|(_, input)| input.elem_count() != row_count)
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident grouping binding columns have different lengths",
            ));
        }
        if key_input.is_none() && value_input.is_none() && aggregate == ResidentAggregate::CountAll
        {
            return Ok(vec![ResidentGroup {
                key: None,
                rows: row_count as u64,
                value: Some(ScalarValue::Integer(i64::try_from(row_count).map_err(
                    |_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "resident global count exceeds i64",
                        )
                    },
                )?)),
            }]);
        }
        let (keys, key_validity) = match key_input {
            Some((property, input)) => self.selected_integer_column_tensor(property, input)?,
            None => (
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::ones(row_count, DType::U8, device).map_err(candle_error)?,
            ),
        };
        let (values, value_validity) = match value_input {
            Some((property, input)) => self.selected_integer_column_tensor(property, input)?,
            None if aggregate == ResidentAggregate::CountAll => (
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::ones(row_count, DType::U8, device).map_err(candle_error)?,
            ),
            None => {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "resident value aggregate requires an integer input property",
                ));
            }
        };

        // A keyless aggregate has exactly one group. Sorting its complete value relation twice and
        // running a segmented prefix scan only to read the final lane made global reductions
        // O(N log N) dispatches and transient storage. Direct device reductions retain the same
        // null and conservative exact-integer overflow semantics with O(N) work and O(N) only for
        // the already-required masked value lane.
        if key_input.is_none() && !matches!(aggregate, ResidentAggregate::Dispersion { .. }) {
            let row_count_i64 = i64::try_from(row_count).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident global aggregate row count exceeds i64",
                )
            })?;
            #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
            let native_summary = if matches!(device, Device::Metal(_)) {
                let group_start = Tensor::zeros(1, DType::U32, device).map_err(candle_error)?;
                let summary = values
                    .apply_op3_no_bwd(
                        &value_validity,
                        &group_start,
                        &MetalIntegerGroupSummary {
                            row_count,
                            group_count: 1,
                        },
                    )
                    .and_then(|summary| summary.to_vec1::<i64>())
                    .map_err(candle_error)?;
                Some((summary[0], summary[1], summary[2], summary[3]))
            } else {
                None
            };
            #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
            let native_summary: Option<(i64, i64, i64, i64)> = None;

            let (value_count, sum, minimum, maximum) = if let Some(summary) = native_summary {
                summary
            } else {
                let value_count = value_validity
                    .to_dtype(DType::I64)
                    .and_then(|validity| validity.sum_all())
                    .and_then(|count| count.to_scalar::<i64>())
                    .map_err(candle_error)?;
                let needs_minimum = matches!(
                    aggregate,
                    ResidentAggregate::Sum
                        | ResidentAggregate::Average
                        | ResidentAggregate::Minimum
                );
                let needs_maximum = matches!(
                    aggregate,
                    ResidentAggregate::Sum
                        | ResidentAggregate::Average
                        | ResidentAggregate::Maximum
                );
                let minimum = if value_count == 0 || !needs_minimum {
                    0
                } else {
                    value_validity
                        .where_cond(
                            &values,
                            &Tensor::full(i64::MAX, row_count, device).map_err(candle_error)?,
                        )
                        .and_then(|values| values.min_all())
                        .and_then(|value| value.to_scalar::<i64>())
                        .map_err(candle_error)?
                };
                let maximum = if value_count == 0 || !needs_maximum {
                    0
                } else {
                    value_validity
                        .where_cond(
                            &values,
                            &Tensor::full(i64::MIN, row_count, device).map_err(candle_error)?,
                        )
                        .and_then(|values| values.max_all())
                        .and_then(|value| value.to_scalar::<i64>())
                        .map_err(candle_error)?
                };
                let sum = if matches!(
                    aggregate,
                    ResidentAggregate::Sum | ResidentAggregate::Average
                ) {
                    value_validity
                        .where_cond(
                            &values,
                            &Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                        )
                        .and_then(|values| values.sum_all())
                        .and_then(|value| value.to_scalar::<i64>())
                        .map_err(candle_error)?
                } else {
                    0
                };
                (value_count, sum, minimum, maximum)
            };
            if matches!(
                aggregate,
                ResidentAggregate::Sum | ResidentAggregate::Average
            ) {
                validate_integer_accumulator_bounds(&[value_count], &[minimum], &[maximum])?;
            }
            let [value] = finalize_integer_groups(
                &[row_count_i64],
                &[value_count],
                &[sum],
                &[minimum],
                &[maximum],
                &[],
                &[],
                aggregate,
            )?
            .try_into()
            .map_err(|_| Error::internal("global integer aggregate returned multiple groups"))?;
            ensure_not_cancelled(cancellation)?;
            return Ok(vec![ResidentGroup {
                key: None,
                rows: row_count as u64,
                value,
            }]);
        }

        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        let uses_native_integer_summary = matches!(device, Device::Metal(_))
            && !matches!(aggregate, ResidentAggregate::Dispersion { .. });
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        let uses_native_integer_summary = false;

        // Count reductions never depend on value order. The native Metal group reducer computes
        // count/sum/min/max directly inside each key run, so every non-dispersion aggregate also
        // needs only the key sort. Retaining the old value-first radix pass doubled sorting,
        // allocated another full set of order columns, and contributed nothing to the result.
        let order = if uses_native_integer_summary
            || matches!(
                aggregate,
                ResidentAggregate::CountAll | ResidentAggregate::CountValue
            ) {
            stable_nullable_integer_order(
                &keys,
                &key_validity,
                false,
                true,
                None,
                device,
                cancellation,
            )?
        } else {
            // The reference/dispersion path orders aggregate values within every eventual key run,
            // then groups keys while preserving that value order.
            let value_order = stable_nullable_integer_order(
                &values,
                &value_validity,
                false,
                false,
                None,
                device,
                cancellation,
            )?;
            let value_ordered_keys = device_index_select(&keys, &value_order, 0)?;
            let value_ordered_key_validity = device_index_select(&key_validity, &value_order, 0)?;
            let key_order = stable_nullable_integer_order(
                &value_ordered_keys,
                &value_ordered_key_validity,
                false,
                true,
                None,
                device,
                cancellation,
            )?;
            device_index_select(&value_order, &key_order, 0)?
        };
        let sorted_keys = device_index_select(&keys, &order, 0)?;
        let sorted_key_validity = device_index_select(&key_validity, &order, 0)?;
        let sorted_values = device_index_select(&values, &order, 0)?;
        let sorted_value_validity = device_index_select(&value_validity, &order, 0)?;

        // Candle Metal does not permit binary operations over an empty tensor. A single input
        // row has one group by definition, so avoid manufacturing the empty pairwise-comparison
        // tensors used by the general grouping path.
        let boundaries = if row_count == 1 {
            Tensor::ones(1, DType::U8, device).map_err(candle_error)?
        } else {
            let previous_keys = sorted_keys
                .narrow(0, 0, row_count - 1)
                .map_err(candle_error)?;
            let current_keys = sorted_keys
                .narrow(0, 1, row_count - 1)
                .map_err(candle_error)?;
            let previous_validity = sorted_key_validity
                .narrow(0, 0, row_count - 1)
                .map_err(candle_error)?;
            let current_validity = sorted_key_validity
                .narrow(0, 1, row_count - 1)
                .map_err(candle_error)?;
            let different = current_validity
                .ne(&previous_validity)
                .and_then(|different_validity| {
                    current_keys
                        .ne(&previous_keys)?
                        .broadcast_mul(&current_validity)?
                        .broadcast_mul(&previous_validity)?
                        .broadcast_add(&different_validity)
                })
                .and_then(|different| different.gt(0_u8))
                .map_err(candle_error)?;
            Tensor::cat(
                &[
                    &Tensor::ones(1, DType::U8, device).map_err(candle_error)?,
                    &different,
                ],
                0,
            )
            .map_err(candle_error)?
        };
        let group_starts = selected_positions(&boundaries, row_count, device, cancellation)?;
        let group_count = group_starts.elem_count();
        if group_count > max_groups {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident grouping exceeded the result row budget",
            ));
        }
        let terminal = Tensor::new(checked_u32(row_count, "group input")?, device)
            .and_then(|terminal| terminal.reshape(1))
            .map_err(candle_error)?;
        let group_ends = if group_count == 1 {
            terminal
        } else {
            Tensor::cat(
                &[
                    &group_starts
                        .narrow(0, 1, group_count - 1)
                        .map_err(candle_error)?,
                    &terminal,
                ],
                0,
            )
            .map_err(candle_error)?
        };
        let group_rows = group_ends
            .to_dtype(DType::I64)
            .and_then(|ends| ends.sub(&group_starts.to_dtype(DType::I64)?))
            .map_err(candle_error)?;
        let group_last = group_ends
            .sub(&Tensor::ones(group_count, DType::U32, device).map_err(candle_error)?)
            .map_err(candle_error)?;

        let key_values = sorted_keys
            .index_select(&group_starts, 0)
            .and_then(|values| values.to_vec1::<i64>())
            .map_err(candle_error)?;
        let key_validity = sorted_key_validity
            .index_select(&group_starts, 0)
            .and_then(|validity| validity.to_vec1::<u8>())
            .map_err(candle_error)?;
        let group_rows = group_rows.to_vec1::<i64>().map_err(candle_error)?;
        if aggregate == ResidentAggregate::CountAll {
            ensure_not_cancelled(cancellation)?;
            return key_values
                .into_iter()
                .zip(key_validity)
                .zip(group_rows)
                .map(|((key, valid), rows)| {
                    let count = u64::try_from(rows).map_err(|_| {
                        Error::internal("resident integer group row count became negative")
                    })?;
                    Ok(ResidentGroup {
                        key: (key_input.is_some() && valid != 0).then_some(key),
                        rows: count,
                        value: Some(ScalarValue::Integer(rows)),
                    })
                })
                .collect();
        }
        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        let native_summary = if uses_native_integer_summary {
            let summary = sorted_values
                .apply_op3_no_bwd(
                    &sorted_value_validity,
                    &group_starts,
                    &MetalIntegerGroupSummary {
                        row_count,
                        group_count,
                    },
                )
                .and_then(|summary| summary.to_vec1::<i64>())
                .map_err(candle_error)?;
            Some((
                summary[..group_count].to_vec(),
                summary[group_count..2 * group_count].to_vec(),
                summary[2 * group_count..3 * group_count].to_vec(),
                summary[3 * group_count..].to_vec(),
            ))
        } else {
            None
        };
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        let native_summary: Option<(Vec<i64>, Vec<i64>, Vec<i64>, Vec<i64>)> = None;

        let (value_counts, sums, minimums, maximums) = if let Some(summary) = native_summary {
            if matches!(
                aggregate,
                ResidentAggregate::Sum | ResidentAggregate::Average
            ) {
                validate_integer_accumulator_bounds(&summary.0, &summary.2, &summary.3)?;
            }
            summary
        } else {
            let value_count_prefix = segmented_prefix_sum_i64(
                &sorted_value_validity
                    .to_dtype(DType::I64)
                    .map_err(candle_error)?,
                &sorted_keys,
                &sorted_key_validity,
                device,
                cancellation,
            )?;
            let value_counts = value_count_prefix
                .index_select(&group_last, 0)
                .map_err(candle_error)?;
            let safe_value_counts = value_counts.maximum(1_i64).map_err(candle_error)?;
            let maximum_positions = group_starts
                .to_dtype(DType::I64)
                .and_then(|starts| starts.add(&safe_value_counts))
                .and_then(|positions| positions.broadcast_sub(&Tensor::new(1_i64, device)?))
                .and_then(|positions| positions.to_dtype(DType::U32))
                .map_err(candle_error)?;
            let value_counts = value_counts.to_vec1::<i64>().map_err(candle_error)?;
            let minimums = sorted_values
                .index_select(&group_starts, 0)
                .and_then(|values| values.to_vec1::<i64>())
                .map_err(candle_error)?;
            let maximums = sorted_values
                .index_select(&maximum_positions, 0)
                .and_then(|values| values.to_vec1::<i64>())
                .map_err(candle_error)?;
            let sums = if matches!(
                aggregate,
                ResidentAggregate::Sum | ResidentAggregate::Average
            ) {
                validate_integer_accumulator_bounds(&value_counts, &minimums, &maximums)?;
                let masked_values = sorted_value_validity
                    .where_cond(
                        &sorted_values,
                        &Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                    )
                    .map_err(candle_error)?;
                segmented_prefix_sum_i64(
                    &masked_values,
                    &sorted_keys,
                    &sorted_key_validity,
                    device,
                    cancellation,
                )?
                .index_select(&group_last, 0)
                .and_then(|sums| sums.to_vec1::<i64>())
                .map_err(candle_error)?
            } else {
                vec![0; group_count]
            };
            (value_counts, sums, minimums, maximums)
        };

        // Dispersion reduces Σx and Σx² per group in f64 (an integer Σx² would overflow), and finalizes
        // to the same variance/stdev formula the CPU backend uses.
        let (dispersion_sums, dispersion_sum_squares) =
            if matches!(aggregate, ResidentAggregate::Dispersion { .. }) {
                let masked_values = sorted_value_validity
                    .where_cond(
                        &sorted_values.to_dtype(DType::F64).map_err(candle_error)?,
                        &Tensor::zeros(row_count, DType::F64, device).map_err(candle_error)?,
                    )
                    .map_err(candle_error)?;
                let masked_squares = masked_values.mul(&masked_values).map_err(candle_error)?;
                let sums = segmented_prefix_sum_f64(
                    &masked_values,
                    &sorted_keys,
                    &sorted_key_validity,
                    device,
                    cancellation,
                )?
                .index_select(&group_last, 0)
                .and_then(|sums| sums.to_vec1::<f64>())
                .map_err(candle_error)?;
                let sum_squares = segmented_prefix_sum_f64(
                    &masked_squares,
                    &sorted_keys,
                    &sorted_key_validity,
                    device,
                    cancellation,
                )?
                .index_select(&group_last, 0)
                .and_then(|values| values.to_vec1::<f64>())
                .map_err(candle_error)?;
                (sums, sum_squares)
            } else {
                (Vec::new(), Vec::new())
            };

        let aggregate_values = finalize_integer_groups(
            &group_rows,
            &value_counts,
            &sums,
            &minimums,
            &maximums,
            &dispersion_sums,
            &dispersion_sum_squares,
            aggregate,
        )?;
        ensure_not_cancelled(cancellation)?;
        key_values
            .into_iter()
            .zip(key_validity)
            .zip(group_rows)
            .zip(aggregate_values)
            .map(|(((key, valid), rows), value)| {
                let rows = u64::try_from(rows).map_err(|_| {
                    Error::internal("resident integer group row count became negative")
                })?;
                Ok(ResidentGroup {
                    key: (key_input.is_some() && valid != 0).then_some(key),
                    rows,
                    value,
                })
            })
            .collect()
    }

    fn expand_pipeline_rows(
        &self,
        device: &Device,
        starts: &Tensor,
        expansion: &super::ResidentExpansion,
        layers: LayerMask,
        max_rows: usize,
        cancellation: &CancellationToken,
    ) -> Result<(Tensor, Tensor, Tensor)> {
        self.expand_pipeline_rows_with_deadline(
            device,
            starts,
            expansion,
            layers,
            max_rows,
            cancellation,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn expand_pipeline_rows_with_deadline(
        &self,
        device: &Device,
        starts: &Tensor,
        expansion: &super::ResidentExpansion,
        layers: LayerMask,
        max_rows: usize,
        cancellation: &CancellationToken,
        deadline: Option<std::time::Instant>,
    ) -> Result<(Tensor, Tensor, Tensor)> {
        ensure_graph_execution(cancellation, deadline)?;
        let (source_positions, edges, ends) = self.expand_pipeline_row_positions_with_deadline(
            device,
            starts,
            expansion,
            layers,
            max_rows,
            cancellation,
            deadline,
        )?;
        let expanded_starts = if source_positions.elem_count() == 0 {
            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?
        } else {
            starts
                .index_select(&source_positions, 0)
                .map_err(candle_error)?
        };
        ensure_graph_execution(cancellation, deadline)?;
        Ok((expanded_starts, edges, ends))
    }

    fn expand_pipeline_row_positions(
        &self,
        device: &Device,
        starts: &Tensor,
        expansion: &super::ResidentExpansion,
        layers: LayerMask,
        max_rows: usize,
        cancellation: &CancellationToken,
    ) -> Result<(Tensor, Tensor, Tensor)> {
        self.expand_pipeline_row_positions_with_deadline(
            device,
            starts,
            expansion,
            layers,
            max_rows,
            cancellation,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn expand_pipeline_row_positions_with_deadline(
        &self,
        device: &Device,
        starts: &Tensor,
        expansion: &super::ResidentExpansion,
        layers: LayerMask,
        max_rows: usize,
        cancellation: &CancellationToken,
        deadline: Option<std::time::Instant>,
    ) -> Result<(Tensor, Tensor, Tensor)> {
        ensure_graph_execution(cancellation, deadline)?;
        if starts.elem_count() == 0 {
            let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
            return Ok((empty.clone(), empty.clone(), empty));
        }
        if expansion.direction == super::ResidentDirection::Undirected {
            // Cypher's undirected pattern expands each non-self relationship from both
            // endpoints, but a self-loop only once. Both directional expansions and the
            // self-loop filter stay on the device; no host-side adjacency fallback is involved.
            let mut outgoing = expansion.clone();
            outgoing.direction = super::ResidentDirection::Outgoing;
            // Null extension belongs to the union of both directions. Optionalizing either
            // direction independently would fabricate a null row when only the opposite
            // direction matched, and would emit two null rows when neither direction matched.
            outgoing.optional = false;
            let (outgoing_sources, outgoing_edges, outgoing_ends) = self
                .expand_pipeline_row_positions_with_deadline(
                    device,
                    starts,
                    &outgoing,
                    layers,
                    max_rows,
                    cancellation,
                    deadline,
                )?;
            let mut incoming = expansion.clone();
            incoming.direction = super::ResidentDirection::Incoming;
            incoming.optional = false;
            let (incoming_sources, incoming_edges, incoming_ends) = self
                .expand_pipeline_row_positions_with_deadline(
                    device,
                    starts,
                    &incoming,
                    layers,
                    max_rows,
                    cancellation,
                    deadline,
                )?;
            // Candle Metal comparison kernels cannot dispatch a zero-element grid. Preserve the
            // empty directional stream before comparing endpoints; otherwise an OPTIONAL row
            // with no candidates traps in the generic `ne` launcher instead of becoming NULL.
            let (incoming_sources, incoming_edges, incoming_ends) =
                if incoming_sources.elem_count() == 0 {
                    let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                    (empty.clone(), empty.clone(), empty)
                } else {
                    let incoming_starts = starts
                        .index_select(&incoming_sources, 0)
                        .map_err(candle_error)?;
                    let incoming_keep = incoming_ends.ne(&incoming_starts).map_err(candle_error)?;
                    let incoming_positions = selected_positions_with_deadline(
                        &incoming_keep,
                        incoming_starts.elem_count(),
                        device,
                        cancellation,
                        deadline,
                    )?;
                    // Candle Metal's index_select cannot encode an empty index tensor. Preserve
                    // a self-loop-only incoming selection explicitly: its outgoing copy remains.
                    if incoming_positions.elem_count() == 0 {
                        let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                        (empty.clone(), empty.clone(), empty)
                    } else {
                        (
                            incoming_sources
                                .index_select(&incoming_positions, 0)
                                .map_err(candle_error)?,
                            incoming_edges
                                .index_select(&incoming_positions, 0)
                                .map_err(candle_error)?,
                            incoming_ends
                                .index_select(&incoming_positions, 0)
                                .map_err(candle_error)?,
                        )
                    }
                };
            let output_rows = outgoing_sources
                .elem_count()
                .checked_add(incoming_sources.elem_count())
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "undirected resident expansion row count overflow",
                    )
                })?;
            if output_rows > max_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "query row budget exceeded after undirected resident expansion",
                ));
            }
            let combine = |outgoing: &Tensor, incoming: &Tensor| -> Result<Tensor> {
                if outgoing.elem_count() == 0 {
                    return Ok(incoming.clone());
                }
                if incoming.elem_count() == 0 {
                    return Ok(outgoing.clone());
                }
                Tensor::cat(&[outgoing, incoming], 0).map_err(candle_error)
            };
            let selected_sources = combine(&outgoing_sources, &incoming_sources)?;
            let selected_edges = combine(&outgoing_edges, &incoming_edges)?;
            let selected_ends = combine(&outgoing_ends, &incoming_ends)?;
            if !expansion.optional {
                return Ok((selected_sources, selected_edges, selected_ends));
            }
            return self.optionalize_expansion_row_positions_with_deadline(
                device,
                starts,
                &selected_sources,
                &selected_edges,
                &selected_ends,
                max_rows,
                cancellation,
                deadline,
            );
        }
        let (offsets, neighbors, edges) = match expansion.direction {
            super::ResidentDirection::Outgoing => (
                &self.outgoing_offsets,
                self.outgoing_neighbors.as_ref(),
                self.outgoing_edges.as_ref(),
            ),
            super::ResidentDirection::Incoming => (
                &self.incoming_offsets,
                self.incoming_neighbors.as_ref(),
                self.incoming_edges.as_ref(),
            ),
            super::ResidentDirection::Undirected => {
                return Err(Error::internal(
                    "undirected expansion was not split into directional device pipelines",
                ));
            }
        };
        let (Some(neighbors), Some(edges)) = (neighbors, edges) else {
            let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
            if expansion.optional {
                return self.optionalize_expansion_row_positions_with_deadline(
                    device,
                    starts,
                    &empty,
                    &empty,
                    &empty,
                    max_rows,
                    cancellation,
                    deadline,
                );
            }
            return Ok((empty.clone(), empty.clone(), empty));
        };
        let next_rows = starts
            .add(&Tensor::ones(starts.shape(), DType::U32, device).map_err(candle_error)?)
            .map_err(candle_error)?;
        let adjacency_starts = offsets.index_select(starts, 0).map_err(candle_error)?;
        let adjacency_ends = offsets.index_select(&next_rows, 0).map_err(candle_error)?;
        let counts = adjacency_ends
            .to_dtype(DType::I64)
            .and_then(|ends| ends.sub(&adjacency_starts.to_dtype(DType::I64)?))
            .map_err(candle_error)?;
        let cap = i64::try_from(max_rows.saturating_add(1)).unwrap_or(i64::MAX);
        let cumulative =
            bounded_inclusive_scan_i64_with_deadline(&counts, cap, device, cancellation, deadline)?;
        let result_count = cumulative
            .narrow(0, cumulative.elem_count() - 1, 1)
            .and_then(|count| count.to_vec1::<i64>())
            .map_err(candle_error)?;
        let result_count = *result_count
            .first()
            .ok_or_else(|| Error::internal("resident expansion row count is absent"))?;
        let result_count = usize::try_from(result_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident expansion row count exceeds host address space",
            )
        })?;
        if result_count > max_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "query row budget exceeded after resident expansion",
            ));
        }
        if result_count == 0 {
            let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
            if expansion.optional {
                return self.optionalize_expansion_row_positions_with_deadline(
                    device,
                    starts,
                    &empty,
                    &empty,
                    &empty,
                    max_rows,
                    cancellation,
                    deadline,
                );
            }
            return Ok((empty.clone(), empty.clone(), empty));
        }
        let output_positions = Tensor::arange(
            0_i64,
            i64::try_from(result_count).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident expansion row count exceeds i64",
                )
            })?,
            device,
        )
        .map_err(candle_error)?;
        let source_positions = sorted_integer_bound(
            &cumulative,
            cumulative.elem_count(),
            &output_positions,
            true,
            device,
            cancellation,
        )?;
        let exclusive = cumulative.sub(&counts).map_err(candle_error)?;
        let source_output_starts = exclusive
            .index_select(&source_positions, 0)
            .map_err(candle_error)?;
        let edge_positions = adjacency_starts
            .to_dtype(DType::I64)
            .and_then(|starts| starts.index_select(&source_positions, 0))
            .and_then(|starts| starts.add(&output_positions.sub(&source_output_starts)?))
            .and_then(|positions| positions.to_dtype(DType::U32))
            .map_err(candle_error)?;
        let source_positions = source_positions
            .to_dtype(DType::U32)
            .map_err(candle_error)?;
        let expanded_starts = starts
            .index_select(&source_positions, 0)
            .map_err(candle_error)?;
        let expanded_ends = neighbors
            .index_select(&edge_positions, 0)
            .map_err(candle_error)?;
        let expanded_edges = edges
            .index_select(&edge_positions, 0)
            .map_err(candle_error)?;

        let edge_active = self
            .edge_active
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty adjacency has no edge-active tensor"))?
            .index_select(&expanded_edges, 0)
            .map_err(candle_error)?;
        let edge_layer_mask = if layers == LayerMask::ALL {
            None
        } else {
            let edge_layers = self
                .edge_layers
                .as_ref()
                .ok_or_else(|| Error::internal("non-empty adjacency has no edge-layer tensor"))?
                .index_select(&expanded_edges, 0)
                .map_err(candle_error)?;
            let mut selected: Option<Tensor> = None;
            for layer in crate::Layer::ALL {
                if layers.contains_layer(layer) {
                    let equals = edge_layers.eq(layer as u8).map_err(candle_error)?;
                    selected = Some(match selected {
                        Some(current) => current.broadcast_add(&equals).map_err(candle_error)?,
                        None => equals,
                    });
                }
            }
            Some(selected.ok_or_else(|| {
                Error::new(ErrorCode::QueryType, "relationship layer mask is empty")
            })?)
        };
        let mut edge_type_mask: Option<Tensor> = None;
        if !expansion.relationship_types.is_empty() {
            let edge_types = self
                .edge_types
                .as_ref()
                .ok_or_else(|| Error::internal("non-empty adjacency has no edge-type tensor"))?
                .index_select(&expanded_edges, 0)
                .map_err(candle_error)?;
            for relationship_type in &expansion.relationship_types {
                let equals = edge_types
                    .eq(relationship_type.0 as i64)
                    .map_err(candle_error)?;
                edge_type_mask = Some(match edge_type_mask {
                    Some(current) => current.broadcast_add(&equals).map_err(candle_error)?,
                    None => equals,
                });
            }
        }
        let end_mask =
            self.node_selection_mask_for_rows(&expanded_ends, &expansion.end_labels, layers)?;
        let mut selected_mask = edge_active.broadcast_mul(&end_mask).map_err(candle_error)?;
        if let Some(layer_mask) = edge_layer_mask {
            selected_mask = selected_mask
                .broadcast_mul(&layer_mask)
                .map_err(candle_error)?;
        }
        if let Some(type_mask) = edge_type_mask {
            let type_mask = if expansion.relationship_types.len() == 1 {
                type_mask
            } else {
                type_mask.gt(0_u8).map_err(candle_error)?
            };
            selected_mask = selected_mask
                .broadcast_mul(&type_mask)
                .map_err(candle_error)?;
        }
        if expansion.end_equals_start {
            let same_endpoint = expanded_ends.eq(&expanded_starts).map_err(candle_error)?;
            selected_mask = selected_mask
                .broadcast_mul(&same_endpoint)
                .map_err(candle_error)?;
        }
        for predicate in &expansion.end_predicates {
            if predicate.binding != super::ResidentNodeBinding::End {
                return Err(Error::internal(
                    "optional expansion contains a non-end predicate",
                ));
            }
            let (values, validity) =
                self.selected_integer_column_tensor(predicate.property, &expanded_ends)?;
            let predicate_mask = match predicate.operation {
                CompareOp::Eq => values.eq(predicate.operand),
                CompareOp::NotEq => values.ne(predicate.operand),
                CompareOp::Less => values.lt(predicate.operand),
                CompareOp::LessOrEqual => values.le(predicate.operand),
                CompareOp::Greater => values.gt(predicate.operand),
                CompareOp::GreaterOrEqual => values.ge(predicate.operand),
            }
            .and_then(|matched| matched.broadcast_mul(&validity.eq(1_u8)?))
            .map_err(candle_error)?;
            selected_mask = selected_mask
                .broadcast_mul(&predicate_mask)
                .map_err(candle_error)?;
        }
        let selected = selected_positions_with_deadline(
            &selected_mask,
            result_count,
            device,
            cancellation,
            deadline,
        )?;
        // A relationship/type/end-node predicate can remove every candidate.  Do not pass the
        // resulting zero-length index tensor to Metal's index_select; keep the empty stream on
        // device and, for OPTIONAL MATCH, produce the required null-extended source rows.
        if selected.elem_count() == 0 {
            let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
            if expansion.optional {
                return self.optionalize_expansion_row_positions_with_deadline(
                    device,
                    starts,
                    &empty,
                    &empty,
                    &empty,
                    max_rows,
                    cancellation,
                    deadline,
                );
            }
            return Ok((empty.clone(), empty.clone(), empty));
        }
        let selected_edges = expanded_edges
            .index_select(&selected, 0)
            .map_err(candle_error)?;
        let selected_ends = expanded_ends
            .index_select(&selected, 0)
            .map_err(candle_error)?;
        let selected_source_positions = source_positions
            .index_select(&selected, 0)
            .map_err(candle_error)?;
        if !expansion.optional {
            return Ok((selected_source_positions, selected_edges, selected_ends));
        }
        self.optionalize_expansion_row_positions_with_deadline(
            device,
            starts,
            &selected_source_positions,
            &selected_edges,
            &selected_ends,
            max_rows,
            cancellation,
            deadline,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn optionalize_expansion_row_positions(
        &self,
        device: &Device,
        starts: &Tensor,
        selected_source_positions: &Tensor,
        selected_edges: &Tensor,
        selected_ends: &Tensor,
        max_rows: usize,
        cancellation: &CancellationToken,
    ) -> Result<(Tensor, Tensor, Tensor)> {
        self.optionalize_expansion_row_positions_with_deadline(
            device,
            starts,
            selected_source_positions,
            selected_edges,
            selected_ends,
            max_rows,
            cancellation,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn optionalize_expansion_row_positions_with_deadline(
        &self,
        device: &Device,
        starts: &Tensor,
        selected_source_positions: &Tensor,
        selected_edges: &Tensor,
        selected_ends: &Tensor,
        max_rows: usize,
        cancellation: &CancellationToken,
        deadline: Option<std::time::Instant>,
    ) -> Result<(Tensor, Tensor, Tensor)> {
        ensure_graph_execution(cancellation, deadline)?;
        let start_count = starts.elem_count();
        if selected_source_positions.elem_count() != selected_edges.elem_count()
            || selected_edges.elem_count() != selected_ends.elem_count()
        {
            return Err(Error::internal(
                "optional expansion selected columns have different lengths",
            ));
        }
        let match_counts = scatter_counts(selected_source_positions, start_count, device)?;
        let match_counts_i64 = match_counts.to_dtype(DType::I64).map_err(candle_error)?;
        let output_counts = match_counts_i64.maximum(1_i64).map_err(candle_error)?;
        let cap = i64::try_from(max_rows.saturating_add(1)).unwrap_or(i64::MAX);
        let cumulative_output = bounded_inclusive_scan_i64_with_deadline(
            &output_counts,
            cap,
            device,
            cancellation,
            deadline,
        )?;
        let result_count = cumulative_output
            .narrow(0, start_count - 1, 1)
            .and_then(|count| count.to_vec1::<i64>())
            .map_err(candle_error)?;
        let result_count = result_count
            .first()
            .copied()
            .ok_or_else(|| Error::internal("optional expansion row count is absent"))?;
        let result_count = usize::try_from(result_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "optional expansion row count exceeds host address space",
            )
        })?;
        if result_count > max_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "query row budget exceeded after optional expansion",
            ));
        }
        let output_positions = Tensor::arange(
            0_i64,
            i64::try_from(result_count).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "optional expansion row count exceeds i64",
                )
            })?,
            device,
        )
        .map_err(candle_error)?;
        let output_sources_i64 = sorted_integer_bound(
            &cumulative_output,
            start_count,
            &output_positions,
            true,
            device,
            cancellation,
        )?;
        let output_sources = output_sources_i64
            .to_dtype(DType::U32)
            .map_err(candle_error)?;
        let exclusive_output = cumulative_output
            .sub(&output_counts)
            .map_err(candle_error)?;
        let local_positions = output_positions
            .sub(
                &exclusive_output
                    .index_select(&output_sources, 0)
                    .map_err(candle_error)?,
            )
            .map_err(candle_error)?;
        let cumulative_matches = bounded_inclusive_scan_i64_with_deadline(
            &match_counts_i64,
            cap,
            device,
            cancellation,
            deadline,
        )?;
        let exclusive_matches = cumulative_matches
            .sub(&match_counts_i64)
            .map_err(candle_error)?;
        let candidate_positions = exclusive_matches
            .index_select(&output_sources, 0)
            .and_then(|positions| positions.add(&local_positions))
            .and_then(|positions| positions.to_dtype(DType::U32))
            .map_err(candle_error)?;
        let has_match = match_counts
            .index_select(&output_sources, 0)
            .and_then(|counts| counts.gt(0_u32))
            .map_err(candle_error)?;
        let sentinel_position = checked_u32(selected_edges.elem_count(), "optional expansion")?;
        let candidate_positions = has_match
            .where_cond(
                &candidate_positions,
                &Tensor::full(sentinel_position, result_count, device).map_err(candle_error)?,
            )
            .map_err(candle_error)?;
        let null_row =
            Tensor::from_slice(&[super::RESIDENT_NULL_ROW], 1, device).map_err(candle_error)?;
        let edges_with_null = Tensor::cat(&[selected_edges, &null_row], 0).map_err(candle_error)?;
        let ends_with_null = Tensor::cat(&[selected_ends, &null_row], 0).map_err(candle_error)?;
        let result = (
            output_sources,
            edges_with_null
                .index_select(&candidate_positions, 0)
                .map_err(candle_error)?,
            ends_with_null
                .index_select(&candidate_positions, 0)
                .map_err(candle_error)?,
        );
        ensure_graph_execution(cancellation, deadline)?;
        Ok(result)
    }

    fn select_node_pipeline_rows(
        &self,
        device: &Device,
        request: &ResidentNodePipelineRequest,
        cancellation: &CancellationToken,
    ) -> Result<DeviceNodePipelineRows> {
        ensure_not_cancelled(cancellation)?;
        let has_mutation_continuation = request
            .mutation
            .as_ref()
            .is_some_and(|program| program.continuation.is_some());
        if request.project != self.project {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident node pipeline targets a different project",
            ));
        }
        let mutation_filter_stages = request.mutation_filter_stages()?;
        if request.mutation.is_some()
            && mutation_filter_stages
                .iter()
                .copied()
                .any(|stage| !stage.is_selected_row_stage())
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation receipts do not yet cover candidate-local expansion predicates",
            ));
        }
        let expansion_count = request.expansion_steps().count();
        let relationship_count = request.relationship_column_count();
        if request.limit == 0 && !has_mutation_continuation {
            return empty_device_node_pipeline_rows(device, expansion_count, relationship_count);
        }
        let push_start_predicates = request.mutation.is_none() && !request.initial_optional;
        let start_rows = if self.node_count == 0 {
            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?
        } else {
            let mut mask = self.node_selection_mask(&request.labels, request.layers)?;
            if push_start_predicates {
                for predicate in request
                    .predicates
                    .iter()
                    .filter(|predicate| predicate.binding == ResidentNodeBinding::Start)
                {
                    let column = self.integer_nodes.get(&predicate.property).ok_or_else(|| {
                        Error::new(
                            ErrorCode::QueryType,
                            "resident property is not an integer column",
                        )
                    })?;
                    let values = column
                        .values
                        .as_ref()
                        .ok_or_else(|| Error::internal("integer column values are absent"))?;
                    let validity = column
                        .validity
                        .as_ref()
                        .ok_or_else(|| Error::internal("integer column validity is absent"))?;
                    let selected = match predicate.operation {
                        CompareOp::Eq => values.eq(predicate.operand),
                        CompareOp::NotEq => values.ne(predicate.operand),
                        CompareOp::Less => values.lt(predicate.operand),
                        CompareOp::LessOrEqual => values.le(predicate.operand),
                        CompareOp::Greater => values.gt(predicate.operand),
                        CompareOp::GreaterOrEqual => values.ge(predicate.operand),
                    }
                    .and_then(|selected| selected.broadcast_mul(&validity.eq(1_u8)?))
                    .map_err(candle_error)?;
                    mask = mask.broadcast_mul(&selected).map_err(candle_error)?;
                }
            }
            selected_positions(&mask, self.node_count, device, cancellation)?
        };
        let start_rows = if start_rows.elem_count() == 0 {
            if !request.initial_optional || expansion_count != 0 {
                return empty_device_node_pipeline_rows(
                    device,
                    expansion_count,
                    relationship_count,
                );
            }
            Tensor::from_slice(&[super::RESIDENT_NULL_ROW], 1, device).map_err(candle_error)?
        } else {
            start_rows
        };
        let maximum_rows = request.maximum_pipeline_rows(self.node_count, self.edge_count)?;
        let mut rows = DeviceNodePipelineRows {
            nodes: vec![start_rows],
            relationships: Vec::new(),
            value_indices: None,
            mutation_selection_input_rows: 0,
            mutation_filter_cardinalities: Vec::with_capacity(mutation_filter_stages.len()),
        };
        for (step_index, expansion) in request.expansion_steps().enumerate() {
            if expansion.optional && step_index + 1 != expansion_count {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "only the final resident path expansion may be OPTIONAL",
                ));
            }
            let source = rows
                .nodes
                .last()
                .ok_or_else(|| Error::internal("resident device path has no source node column"))?;
            let (mut source_positions, mut edges, mut ends) = self.expand_pipeline_row_positions(
                device,
                source,
                expansion,
                request.layers,
                maximum_rows,
                cancellation,
            )?;
            if source_positions.elem_count() == 0 {
                return empty_device_node_pipeline_rows(
                    device,
                    expansion_count,
                    relationship_count,
                );
            }
            if !rows.relationships.is_empty() {
                let mut distinct = Tensor::ones(source_positions.elem_count(), DType::U8, device)
                    .map_err(candle_error)?;
                for prior in &rows.relationships {
                    let prior_edges = prior
                        .index_select(&source_positions, 0)
                        .map_err(candle_error)?;
                    distinct = distinct
                        .broadcast_mul(&edges.ne(&prior_edges).map_err(candle_error)?)
                        .map_err(candle_error)?;
                }
                let selected = selected_positions(
                    &distinct,
                    source_positions.elem_count(),
                    device,
                    cancellation,
                )?;
                if selected.elem_count() == 0 {
                    return empty_device_node_pipeline_rows(
                        device,
                        expansion_count,
                        relationship_count,
                    );
                }
                source_positions = source_positions
                    .index_select(&selected, 0)
                    .map_err(candle_error)?;
                edges = edges.index_select(&selected, 0).map_err(candle_error)?;
                ends = ends.index_select(&selected, 0).map_err(candle_error)?;
            }
            rows.select(&source_positions)?;
            rows.relationships.push(edges);
            rows.nodes.push(ends);
        }
        if let Some(correlated) = &request.correlated_optional {
            if correlated.expansion.optional {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "correlated resident expansion must defer optional null extension to its join stage",
                ));
            }
            let source = rows.binding(correlated.source)?.clone();
            let target = rows.binding(correlated.target)?.clone();
            let (candidate_sources, candidate_edges, candidate_ends) = self
                .expand_pipeline_row_positions(
                    device,
                    &source,
                    &correlated.expansion,
                    request.layers,
                    maximum_rows,
                    cancellation,
                )?;
            let (matched_sources, matched_edges, matched_ends) =
                if candidate_sources.elem_count() == 0 {
                    let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                    (empty.clone(), empty.clone(), empty)
                } else {
                    let candidate_targets = target
                        .index_select(&candidate_sources, 0)
                        .map_err(candle_error)?;
                    let matching = candidate_ends
                        .eq(&candidate_targets)
                        .map_err(candle_error)?;
                    let selected = selected_positions(
                        &matching,
                        candidate_sources.elem_count(),
                        device,
                        cancellation,
                    )?;
                    if selected.elem_count() == 0 {
                        let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                        (empty.clone(), empty.clone(), empty)
                    } else {
                        (
                            candidate_sources
                                .index_select(&selected, 0)
                                .map_err(candle_error)?,
                            candidate_edges
                                .index_select(&selected, 0)
                                .map_err(candle_error)?,
                            candidate_ends
                                .index_select(&selected, 0)
                                .map_err(candle_error)?,
                        )
                    }
                };
            let (output_sources, optional_edges, _optional_ends) = self
                .optionalize_expansion_row_positions(
                    device,
                    &source,
                    &matched_sources,
                    &matched_edges,
                    &matched_ends,
                    maximum_rows,
                    cancellation,
                )?;
            rows.select(&output_sources)?;
            rows.relationships.push(optional_edges);
        }
        rows.mutation_selection_input_rows = rows.row_count();
        if let Some(expect_null) = request.relationship_null_filter {
            let input_cardinality = rows.row_count();
            let relationships = rows.relationships.last().ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "resident relationship null filter has no relationship binding",
                )
            })?;
            let nulls = if expect_null {
                relationships.eq(super::RESIDENT_NULL_ROW)
            } else {
                relationships.ne(super::RESIDENT_NULL_ROW)
            }
            .map_err(candle_error)?;
            let selected = selected_positions(&nulls, rows.row_count(), device, cancellation)?;
            if selected.elem_count() == 0 {
                if request.mutation.is_some() {
                    rows.mutation_filter_cardinalities
                        .push((input_cardinality, 0));
                    return empty_mutation_device_node_pipeline_rows(
                        device,
                        expansion_count,
                        relationship_count,
                        rows.mutation_selection_input_rows,
                        rows.mutation_filter_cardinalities,
                        mutation_filter_stages.len(),
                    );
                }
                return empty_device_node_pipeline_rows(
                    device,
                    expansion_count,
                    relationship_count,
                );
            }
            rows.select(&selected)?;
            rows.mutation_filter_cardinalities
                .push((input_cardinality, rows.row_count()));
        }
        for predicate in request.predicates.iter().filter(|predicate| {
            !(push_start_predicates && predicate.binding == ResidentNodeBinding::Start)
        }) {
            ensure_not_cancelled(cancellation)?;
            let input_cardinality = rows.row_count();
            let binding_rows = rows.binding(predicate.binding)?;
            let (values, validity) =
                self.selected_integer_column_tensor(predicate.property, binding_rows)?;
            let predicate_mask = match predicate.operation {
                CompareOp::Eq => values.eq(predicate.operand),
                CompareOp::NotEq => values.ne(predicate.operand),
                CompareOp::Less => values.lt(predicate.operand),
                CompareOp::LessOrEqual => values.le(predicate.operand),
                CompareOp::Greater => values.gt(predicate.operand),
                CompareOp::GreaterOrEqual => values.ge(predicate.operand),
            }
            .and_then(|selected| selected.broadcast_mul(&validity.eq(1_u8)?))
            .map_err(candle_error)?;
            let selected =
                selected_positions(&predicate_mask, rows.row_count(), device, cancellation)?;
            // Candle Metal cannot encode an index_select with an empty index tensor. Once a
            // predicate has removed every row, the remaining pipeline is deterministically
            // empty, so retain that result on device without dispatching an invalid kernel.
            if selected.elem_count() == 0 {
                if request.mutation.is_some() {
                    rows.mutation_filter_cardinalities
                        .push((input_cardinality, 0));
                    return empty_mutation_device_node_pipeline_rows(
                        device,
                        expansion_count,
                        relationship_count,
                        rows.mutation_selection_input_rows,
                        rows.mutation_filter_cardinalities,
                        mutation_filter_stages.len(),
                    );
                }
                return empty_device_node_pipeline_rows(
                    device,
                    expansion_count,
                    relationship_count,
                );
            }
            rows.select(&selected)?;
            rows.mutation_filter_cardinalities
                .push((input_cardinality, rows.row_count()));
        }
        for program in &request.property_filters {
            ensure_not_cancelled(cancellation)?;
            let input_cardinality = rows.row_count();
            let values = self.evaluate_property_filter(device, &rows, program, cancellation)?;
            let selected = selected_positions(
                &values.eq(2_u8).map_err(candle_error)?,
                rows.row_count(),
                device,
                cancellation,
            )?;
            if selected.elem_count() == 0 {
                if request.mutation.is_some() {
                    rows.mutation_filter_cardinalities
                        .push((input_cardinality, 0));
                    return empty_mutation_device_node_pipeline_rows(
                        device,
                        expansion_count,
                        relationship_count,
                        rows.mutation_selection_input_rows,
                        rows.mutation_filter_cardinalities,
                        mutation_filter_stages.len(),
                    );
                }
                return empty_device_node_pipeline_rows(
                    device,
                    expansion_count,
                    relationship_count,
                );
            }
            rows.select(&selected)?;
            rows.mutation_filter_cardinalities
                .push((input_cardinality, rows.row_count()));
        }
        if let Some(program) = &request.value_matrix {
            ensure_not_cancelled(cancellation)?;
            let input_cardinality = rows.row_count();
            let (source_positions, left_indices, right_indices) =
                execute_value_matrix(program, rows.row_count(), device, cancellation)?;
            if source_positions.elem_count() == 0 {
                if request.mutation.is_some() {
                    rows.mutation_filter_cardinalities
                        .push((input_cardinality, 0));
                    return empty_mutation_device_node_pipeline_rows(
                        device,
                        expansion_count,
                        relationship_count,
                        rows.mutation_selection_input_rows,
                        rows.mutation_filter_cardinalities,
                        mutation_filter_stages.len(),
                    );
                }
                return empty_device_node_pipeline_rows(
                    device,
                    expansion_count,
                    relationship_count,
                );
            }
            rows.select(&source_positions)?;
            rows.value_indices = Some((left_indices, right_indices));
            rows.mutation_filter_cardinalities
                .push((input_cardinality, rows.row_count()));
        }
        if has_mutation_continuation {
            // The sealed offset/limit describe only the private post-write relation. Mutation
            // selection must retain every matched binding so source_row remains aligned with the
            // complete intent stream and LIMIT 0 cannot suppress side effects.
            if rows.row_count() > request.max_output_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "query row budget exceeded before resident mutation",
                ));
            }
            return Ok(rows);
        }
        for order in request.orders.iter().rev() {
            if rows.row_count() == 0 {
                break;
            }
            if self.string_nodes.contains_key(&order.property) {
                self.sort_string_binding_rows(&mut rows, order, device, cancellation)?;
                continue;
            }
            let binding_rows = rows.binding(order.binding)?;
            let (values, validity) = if self.integer_nodes.contains_key(&order.property) {
                self.selected_integer_column_tensor(order.property, binding_rows)?
            } else if self.boolean_nodes.contains_key(&order.property) {
                let (values, validity) =
                    self.selected_boolean_column_tensor(order.property, binding_rows)?;
                (values.to_dtype(DType::I64).map_err(candle_error)?, validity)
            } else if self.float_nodes.contains_key(&order.property) {
                self.selected_float_order_key_tensor(order.property, binding_rows)?
            } else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "resident sort property has no supported typed column",
                ));
            };
            // A lexicographic sort must retain every row on each least-significant stable pass.
            // Limiting individual passes would discard rows that a more-significant key can
            // later move into the result window.
            let positions = stable_nullable_integer_order(
                &values,
                &validity,
                order.descending,
                order.nulls_first,
                None,
                device,
                cancellation,
            )?;
            rows.select(&positions)?;
        }

        let start = request.offset.min(rows.row_count());
        let count = request.limit.min(rows.row_count().saturating_sub(start));
        if count > request.max_output_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "query row budget exceeded",
            ));
        }
        for column in rows.nodes.iter_mut().chain(rows.relationships.iter_mut()) {
            *column = column.narrow(0, start, count).map_err(candle_error)?;
        }
        if let Some((left, right)) = &mut rows.value_indices {
            *left = left.narrow(0, start, count).map_err(candle_error)?;
            *right = right.narrow(0, start, count).map_err(candle_error)?;
        }
        Ok(rows)
    }

    pub fn metal_nullable_relation_scratch_bytes(
        &self,
        request: &ResidentNullableRelationRequest,
    ) -> Result<usize> {
        request.validate()?;
        self.validate_nullable_relation_generation(request)?;
        let encoded = encode_metal_nullable_relation_program(request)?;
        let graph_words = metal_nullable_relation_graph_word_count(self, &encoded)?;
        let relation_cells = metal_nullable_relation_max_relation_cells(request)?;
        let output_words = metal_nullable_relation_output_words(request, relation_cells)?;
        let overflow = || {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable-relation scratch accounting overflow",
            )
        };
        let packet_private =
            metal_nullable_relation_packet_private_bytes(graph_words, output_words)?;
        // Every graph lane can own a rounded private conversion buffer while the concatenated
        // packet is built. The completed output and its `to_vec1` readback staging are two more
        // independently rounded buffers. Count that actual-byte upper bound plus the exact
        // sealed-program upload and the backend-neutral reservation required by the shared ABI.
        request
            .scratch_bytes()?
            .checked_add(packet_private)
            .and_then(|bytes| {
                encoded
                    .words
                    .len()
                    .checked_mul(std::mem::size_of::<i64>())
                    .and_then(|program| bytes.checked_add(program))
            })
            .and_then(|bytes| bytes.checked_add(4_096))
            .ok_or_else(overflow)
    }

    fn metal_row_create_candidates(
        &self,
        program: &super::ResidentRowCreateProgram,
        command: &super::ResidentRowCreateMatchNode,
        layers: LayerMask,
        device: &Device,
        cancellation: &CancellationToken,
    ) -> Result<Tensor> {
        self.metal_row_bound_node_candidates(program, &command.labels, layers, device, cancellation)
    }

    fn metal_row_bound_node_candidates(
        &self,
        program: &super::ResidentRowCreateProgram,
        command_labels: &[u16],
        layers: LayerMask,
        device: &Device,
        cancellation: &CancellationToken,
    ) -> Result<Tensor> {
        if self.node_count == 0 {
            return self.outgoing_offsets.narrow(0, 0, 0).map_err(candle_error);
        }
        let mut labels = Vec::with_capacity(command_labels.len());
        for label in command_labels {
            let Some(token) = program
                .label_tokens
                .get(usize::from(*label))
                .copied()
                .flatten()
            else {
                return self.outgoing_offsets.narrow(0, 0, 0).map_err(candle_error);
            };
            if !self.node_labels.contains_key(&token) {
                return self.outgoing_offsets.narrow(0, 0, 0).map_err(candle_error);
            }
            labels.push(token);
        }
        let mask = self.node_selection_mask(&labels, layers)?;
        selected_positions(&mask, self.node_count, device, cancellation)
    }

    /// Evaluates one bound-pattern property source without consulting graph state. Query constants
    /// and raw input maps are legal host inputs; if different source rows require different values,
    /// this first Metal tranche fails closed until the per-source byte arena is wired rather than
    /// collapsing them into one host-selected predicate.
    fn metal_row_bound_uniform_property_value(
        request: &ResidentRowMutationRequest,
        program: &super::ResidentRowCreateProgram,
        source_rows: &Tensor,
        property: &super::ResidentRowCreateProperty,
    ) -> Result<Option<ScalarValue>> {
        if source_rows.dtype() != DType::I64 || source_rows.rank() != 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal bound-relationship source lineage is not a canonical I64 vector",
            ));
        }
        if source_rows.elem_count() == 0 {
            return Ok(None);
        }
        let source_rows = source_rows.to_vec1::<i64>().map_err(candle_error)?;
        let mut value = None;
        for source_row in source_rows {
            let source_row = u64::try_from(source_row).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal bound-relationship source lineage is negative",
                )
            })?;
            let candidate = super::resident_row_bound_property_value(
                &request.input,
                program,
                source_row,
                &property.value,
            )?;
            if value.as_ref().is_some_and(|value| value != &candidate) {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal bound-relationship property predicates with different per-source values require the native source-value arena",
                ));
            }
            value = Some(candidate);
        }
        Ok(value)
    }

    fn metal_row_bound_local_node_mask(
        program: &super::ResidentRowCreateProgram,
        command_labels: &[u16],
        expected: &[super::ResidentMutationIntentEntry],
        candidates: &[MetalBoundLocalNode],
        device: &Device,
    ) -> Result<Tensor> {
        let candidate_count = candidates.len();
        if candidate_count == 0 {
            return Tensor::zeros(0, DType::U8, device).map_err(candle_error);
        }
        let live = candidates
            .iter()
            .map(|candidate| u8::from(!candidate.deleted))
            .collect::<Vec<_>>();
        let mut mask = Tensor::from_slice(&live, live.len(), device).map_err(candle_error)?;
        if !command_labels.is_empty() {
            let label_slots = program.label_tokens.len();
            if command_labels
                .iter()
                .any(|label| usize::from(*label) >= label_slots)
            {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal bound node MERGE names a foreign label slot",
                ));
            }
            let mut presence = vec![
                0_u8;
                candidate_count.checked_mul(label_slots).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal bound local-node label matrix exceeds host address space",
                    )
                },)?
            ];
            for (row, candidate) in candidates.iter().enumerate() {
                for label in &candidate.labels {
                    let label = usize::from(*label);
                    if label >= label_slots {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound local node names a foreign label slot",
                        ));
                    }
                    presence[row * label_slots + label] = 1;
                }
            }
            let required = command_labels
                .iter()
                .map(|label| u32::from(*label))
                .collect::<Vec<_>>();
            let label_matrix =
                Tensor::from_slice(&presence, (candidate_count, label_slots), device)
                    .map_err(candle_error)?;
            let required =
                Tensor::from_slice(&required, required.len(), device).map_err(candle_error)?;
            let label_mask = label_matrix
                .index_select(&required, 1)
                .and_then(|labels| labels.to_dtype(DType::U32))
                .and_then(|labels| labels.sum(1))
                .and_then(|count| count.eq(u32::try_from(command_labels.len()).unwrap_or(u32::MAX)))
                .and_then(|mask| mask.to_dtype(DType::U8))
                .map_err(candle_error)?;
            mask = mask.broadcast_mul(&label_mask).map_err(candle_error)?;
        }
        for property in expected {
            let expected_bytes = metal_row_bound_scalar_match_bytes(Some(&property.value))?;
            let actual_bytes = candidates
                .iter()
                .map(|candidate| {
                    let value = candidate
                        .properties
                        .iter()
                        .find(|entry| entry.property_name == property.property_name)
                        .map(|entry| &entry.value);
                    metal_row_bound_scalar_match_bytes(value)
                })
                .collect::<Result<Vec<_>>>()?;
            let width = actual_bytes
                .iter()
                .map(Vec::len)
                .chain(std::iter::once(expected_bytes.len()))
                .max()
                .unwrap_or(1);
            let mut actual = vec![
                0_u8;
                candidate_count.checked_mul(width).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal bound local-node property matrix exceeds host address space",
                    )
                })?
            ];
            let mut lengths = Vec::with_capacity(candidate_count);
            for (row, value) in actual_bytes.iter().enumerate() {
                actual[row * width..row * width + value.len()].copy_from_slice(value);
                lengths.push(u32::try_from(value.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal bound local-node scalar bytes exceed u32",
                    )
                })?);
            }
            let mut padded_expected = vec![0_u8; width];
            padded_expected[..expected_bytes.len()].copy_from_slice(&expected_bytes);
            let actual = Tensor::from_slice(&actual, (candidate_count, width), device)
                .map_err(candle_error)?;
            let expected_tensor =
                Tensor::from_slice(&padded_expected, (1, width), device).map_err(candle_error)?;
            let byte_mask = actual
                .broadcast_eq(&expected_tensor)
                .and_then(|equal| equal.to_dtype(DType::U32))
                .and_then(|equal| equal.sum(1))
                .and_then(|count| count.eq(u32::try_from(width).unwrap_or(u32::MAX)))
                .and_then(|mask| mask.to_dtype(DType::U8))
                .map_err(candle_error)?;
            let length_mask = Tensor::from_slice(&lengths, lengths.len(), device)
                .and_then(|lengths| {
                    lengths.eq(u32::try_from(expected_bytes.len()).unwrap_or(u32::MAX))
                })
                .and_then(|mask| mask.to_dtype(DType::U8))
                .map_err(candle_error)?;
            mask = mask
                .broadcast_mul(&byte_mask)
                .and_then(|mask| mask.broadcast_mul(&length_mask))
                .map_err(candle_error)?;
        }
        Ok(mask)
    }

    /// Builds the exact statement-local relationship candidate mask on the selected device. Host
    /// code only serializes the immutable candidate metadata; type and property membership remain
    /// tensor comparisons and are combined later with per-parent endpoint masks.
    fn metal_row_bound_local_relationship_mask(
        expected: &[super::ResidentMutationIntentEntry],
        allowed_types: &[u16],
        candidates: &[MetalBoundLocalRelationship],
        device: &Device,
    ) -> Result<Tensor> {
        let candidate_count = candidates.len();
        if candidate_count == 0 {
            return Tensor::zeros(0, DType::U8, device).map_err(candle_error);
        }
        let live = candidates
            .iter()
            .map(|candidate| u8::from(!candidate.deleted))
            .collect::<Vec<_>>();
        let mut mask = Tensor::from_slice(&live, live.len(), device).map_err(candle_error)?;
        if !allowed_types.is_empty() {
            let relationship_types = candidates
                .iter()
                .map(|candidate| u32::from(candidate.relationship_type))
                .collect::<Vec<_>>();
            let relationship_types =
                Tensor::from_slice(&relationship_types, relationship_types.len(), device)
                    .map_err(candle_error)?;
            let mut type_mask =
                Tensor::zeros(candidate_count, DType::U8, device).map_err(candle_error)?;
            for allowed in allowed_types {
                type_mask = type_mask
                    .broadcast_add(
                        &relationship_types
                            .eq(u32::from(*allowed))
                            .and_then(|equal| equal.to_dtype(DType::U8))
                            .map_err(candle_error)?,
                    )
                    .and_then(|matches| matches.gt(0_u8))
                    .and_then(|matches| matches.to_dtype(DType::U8))
                    .map_err(candle_error)?;
            }
            mask = mask.broadcast_mul(&type_mask).map_err(candle_error)?;
        }
        for property in expected {
            let expected_bytes = metal_row_bound_scalar_match_bytes(Some(&property.value))?;
            let actual_bytes = candidates
                .iter()
                .map(|candidate| {
                    let value = candidate
                        .properties
                        .iter()
                        .find(|entry| entry.property_name == property.property_name)
                        .map(|entry| &entry.value);
                    metal_row_bound_scalar_match_bytes(value)
                })
                .collect::<Result<Vec<_>>>()?;
            let width = actual_bytes
                .iter()
                .map(Vec::len)
                .chain(std::iter::once(expected_bytes.len()))
                .max()
                .unwrap_or(1);
            let byte_count = candidate_count.checked_mul(width).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound local-relationship property matrix exceeds host address space",
                )
            })?;
            let mut actual = vec![0_u8; byte_count];
            let mut lengths = Vec::with_capacity(candidate_count);
            for (row, value) in actual_bytes.iter().enumerate() {
                actual[row * width..row * width + value.len()].copy_from_slice(value);
                lengths.push(u32::try_from(value.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal bound local-relationship scalar bytes exceed u32",
                    )
                })?);
            }
            let mut padded_expected = vec![0_u8; width];
            padded_expected[..expected_bytes.len()].copy_from_slice(&expected_bytes);
            let actual = Tensor::from_slice(&actual, (candidate_count, width), device)
                .map_err(candle_error)?;
            let expected_tensor =
                Tensor::from_slice(&padded_expected, (1, width), device).map_err(candle_error)?;
            let byte_mask = actual
                .broadcast_eq(&expected_tensor)
                .and_then(|equal| equal.to_dtype(DType::U32))
                .and_then(|equal| equal.sum(1))
                .and_then(|count| count.eq(u32::try_from(width).unwrap_or(u32::MAX)))
                .and_then(|matches| matches.to_dtype(DType::U8))
                .map_err(candle_error)?;
            let length_mask = Tensor::from_slice(&lengths, lengths.len(), device)
                .and_then(|lengths| {
                    lengths.eq(u32::try_from(expected_bytes.len()).unwrap_or(u32::MAX))
                })
                .and_then(|matches| matches.to_dtype(DType::U8))
                .map_err(candle_error)?;
            mask = mask
                .broadcast_mul(&byte_mask)
                .and_then(|matches| matches.broadcast_mul(&length_mask))
                .map_err(candle_error)?;
        }
        Ok(mask)
    }

    #[allow(clippy::too_many_arguments)]
    fn metal_row_bound_exact_property_mask(
        &self,
        entity_kind: EntityKind,
        property: Option<PropertyId>,
        rows: &Tensor,
        expected: &ScalarValue,
        device: &Device,
        cancellation: &CancellationToken,
    ) -> Result<Tensor> {
        if rows.dtype() != DType::U32 || rows.rank() != 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal bound-relationship property rows are not a canonical U32 vector",
            ));
        }
        let row_count = rows.elem_count();
        if row_count == 0 || property.is_none() || matches!(expected, ScalarValue::Null) {
            return Tensor::zeros(row_count, DType::U8, device).map_err(candle_error);
        }
        let Some(property) = property else {
            return Tensor::zeros(row_count, DType::U8, device).map_err(candle_error);
        };
        let zeros = || Tensor::zeros(row_count, DType::U8, device).map_err(candle_error);
        let fixed_mask =
            |values: &Tensor, validity: &Tensor, expected: &Tensor| -> Result<Tensor> {
                let values = values.index_select(rows, 0).map_err(candle_error)?;
                let validity = validity.index_select(rows, 0).map_err(candle_error)?;
                values
                    .broadcast_eq(expected)
                    .and_then(|equal| equal.to_dtype(DType::U8))
                    .and_then(|equal| equal.broadcast_mul(&validity))
                    .map_err(candle_error)
            };
        let document_mask = |column: &DocumentColumn, expected: &[u8]| -> Result<Tensor> {
            if column.rows
                != match entity_kind {
                    EntityKind::Node => self.node_count,
                    EntityKind::Relationship => self.edge_count,
                }
            {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident document property row count changed",
                ));
            }
            let validity = column.validity.as_ref().ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident document property lost its validity tensor",
                )
            })?;
            let validity = validity.index_select(rows, 0).map_err(candle_error)?;
            let starts = column.offsets.index_select(rows, 0).map_err(candle_error)?;
            let ends = column
                .offsets
                .index_select(
                    &rows
                        .broadcast_add(&Tensor::new(1_u32, device).map_err(candle_error)?)
                        .map_err(candle_error)?,
                    0,
                )
                .map_err(candle_error)?;
            compare_utf8_ranges(
                &starts,
                &ends,
                &validity,
                column.bytes.as_ref(),
                column.maximum_bytes,
                expected,
                CompareOp::Eq,
                device,
                cancellation,
            )?
            .eq(2_u8)
            .and_then(|mask| mask.to_dtype(DType::U8))
            .map_err(candle_error)
        };
        match expected {
            ScalarValue::Integer(expected) => {
                let column = match entity_kind {
                    EntityKind::Node => self.integer_nodes.get(&property),
                    EntityKind::Relationship => self.integer_edges.get(&property),
                };
                let Some(column) = column else {
                    return zeros();
                };
                let (Some(values), Some(validity)) = (&column.values, &column.validity) else {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident integer property lost its value or validity tensor",
                    ));
                };
                fixed_mask(
                    values,
                    validity,
                    &Tensor::new(*expected, device).map_err(candle_error)?,
                )
            }
            ScalarValue::Boolean(expected) => {
                let column = match entity_kind {
                    EntityKind::Node => self.boolean_nodes.get(&property),
                    EntityKind::Relationship => self.boolean_edges.get(&property),
                };
                let Some(column) = column else {
                    return zeros();
                };
                let (Some(values), Some(validity)) = (&column.values, &column.validity) else {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident Boolean property lost its value or validity tensor",
                    ));
                };
                fixed_mask(
                    values,
                    validity,
                    &Tensor::new(u8::from(*expected), device).map_err(candle_error)?,
                )
            }
            ScalarValue::String(expected) => {
                let (column, dictionary) = match entity_kind {
                    EntityKind::Node => (
                        self.string_nodes.get(&property),
                        &self.node_string_dictionary,
                    ),
                    EntityKind::Relationship => (
                        self.string_edges.get(&property),
                        &self.edge_string_dictionary,
                    ),
                };
                let Some(column) = column else {
                    return zeros();
                };
                let (Some(ids), Some(validity)) = (&column.values, &column.validity) else {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident STRING property lost its value or validity tensor",
                    ));
                };
                let ids = ids.index_select(rows, 0).map_err(candle_error)?;
                let validity = validity.index_select(rows, 0).map_err(candle_error)?;
                let safe_ids = validity
                    .eq(1_u8)
                    .and_then(|present| {
                        present.where_cond(&ids, &Tensor::zeros(ids.shape(), DType::U32, device)?)
                    })
                    .map_err(candle_error)?;
                let starts = dictionary
                    .offsets
                    .index_select(&safe_ids, 0)
                    .map_err(candle_error)?;
                let ends = dictionary
                    .offsets
                    .index_select(
                        &safe_ids
                            .broadcast_add(&Tensor::new(1_u32, device).map_err(candle_error)?)
                            .map_err(candle_error)?,
                        0,
                    )
                    .map_err(candle_error)?;
                compare_utf8_ranges(
                    &starts,
                    &ends,
                    &validity,
                    dictionary.bytes.as_ref(),
                    dictionary.maximum_bytes,
                    expected.as_bytes(),
                    CompareOp::Eq,
                    device,
                    cancellation,
                )?
                .eq(2_u8)
                .and_then(|mask| mask.to_dtype(DType::U8))
                .map_err(candle_error)
            }
            ScalarValue::List(expected) => {
                let column = match entity_kind {
                    EntityKind::Node => self.list_nodes.get(&property),
                    EntityKind::Relationship => self.list_edges.get(&property),
                };
                let Some(column) = column else {
                    return zeros();
                };
                document_mask(column, expected.as_bytes())
            }
            ScalarValue::Map(expected) => {
                let column = match entity_kind {
                    EntityKind::Node => self.map_nodes.get(&property),
                    EntityKind::Relationship => self.map_edges.get(&property),
                };
                let Some(column) = column else {
                    return zeros();
                };
                document_mask(column, expected.as_bytes())
            }
            _ => Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal bound-relationship exact property equality does not yet own this scalar type",
            )),
        }
    }

    fn metal_row_bound_relationship_candidates(
        &self,
        program: &super::ResidentRowCreateProgram,
        command: &super::ResidentRowCreateRelationship,
        semantics: &super::ResidentRowBoundRelationshipCommand,
        layers: LayerMask,
        device: &Device,
        cancellation: &CancellationToken,
    ) -> Result<Tensor> {
        if self.edge_count == 0 {
            return self.outgoing_offsets.narrow(0, 0, 0).map_err(candle_error);
        }
        let active = self.edge_active.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "non-empty Metal graph lost its relationship-active tensor",
            )
        })?;
        let edge_layers = self.edge_layers.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "non-empty Metal graph lost its relationship-layer tensor",
            )
        })?;
        let edge_types = self.edge_types.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "non-empty Metal graph lost its relationship-type tensor",
            )
        })?;
        let mut layer_mask =
            Tensor::zeros(self.edge_count, DType::U8, device).map_err(candle_error)?;
        for layer in Layer::ALL {
            if layers.contains_layer(layer) {
                layer_mask = layer_mask
                    .broadcast_add(&edge_layers.eq(layer as u8).map_err(candle_error)?)
                    .and_then(|mask| mask.gt(0_u8))
                    .and_then(|mask| mask.to_dtype(DType::U8))
                    .map_err(candle_error)?;
            }
        }
        let relationship_types = match semantics {
            super::ResidentRowBoundRelationshipCommand::MatchRelationship {
                relationship_types,
                ..
            } => relationship_types.as_slice(),
            super::ResidentRowBoundRelationshipCommand::MergeRelationship { .. } => {
                std::slice::from_ref(&command.relationship_type)
            }
            super::ResidentRowBoundRelationshipCommand::MatchNode { .. }
            | super::ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites { .. }
            | super::ResidentRowBoundRelationshipCommand::CreateNode
            | super::ResidentRowBoundRelationshipCommand::CreateRelationship
            | super::ResidentRowBoundRelationshipCommand::MergeNode => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal relationship candidate scan received node semantics",
                ));
            }
        };
        let mut type_mask = if relationship_types.is_empty() {
            Tensor::ones(self.edge_count, DType::U8, device).map_err(candle_error)?
        } else {
            Tensor::zeros(self.edge_count, DType::U8, device).map_err(candle_error)?
        };
        for relationship_type in relationship_types {
            let Some(token) = program
                .relationship_type_tokens
                .get(usize::from(*relationship_type))
                .copied()
                .flatten()
            else {
                continue;
            };
            let bits = i64::from_ne_bytes(token.0.to_ne_bytes());
            type_mask = type_mask
                .broadcast_add(&edge_types.eq(bits).map_err(candle_error)?)
                .and_then(|mask| mask.gt(0_u8))
                .and_then(|mask| mask.to_dtype(DType::U8))
                .map_err(candle_error)?;
        }
        let mask = active
            .eq(1_u8)
            .and_then(|active| active.to_dtype(DType::U8))
            .and_then(|active| active.broadcast_mul(&layer_mask))
            .and_then(|active| active.broadcast_mul(&type_mask))
            .map_err(candle_error)?;
        selected_positions(&mask, self.edge_count, device, cancellation)
    }

    /// Returns the complete active relationship domain for an all-type post-mutation traversal.
    /// Visibility and layer selection remain device operations; callers may subsequently apply
    /// statement-local tombstones before using the same tensor for matching and read dependencies.
    fn metal_row_bound_visible_relationship_candidates(
        &self,
        layers: LayerMask,
        device: &Device,
        cancellation: &CancellationToken,
    ) -> Result<Tensor> {
        if self.edge_count == 0 {
            return self.outgoing_offsets.narrow(0, 0, 0).map_err(candle_error);
        }
        let active = self.edge_active.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "non-empty Metal graph lost its relationship-active tensor",
            )
        })?;
        let edge_layers = self.edge_layers.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "non-empty Metal graph lost its relationship-layer tensor",
            )
        })?;
        let mut layer_mask =
            Tensor::zeros(self.edge_count, DType::U8, device).map_err(candle_error)?;
        for layer in Layer::ALL {
            if layers.contains_layer(layer) {
                layer_mask = layer_mask
                    .broadcast_add(&edge_layers.eq(layer as u8).map_err(candle_error)?)
                    .and_then(|mask| mask.gt(0_u8))
                    .and_then(|mask| mask.to_dtype(DType::U8))
                    .map_err(candle_error)?;
            }
        }
        let mask = active
            .eq(1_u8)
            .and_then(|active| active.to_dtype(DType::U8))
            .and_then(|active| active.broadcast_mul(&layer_mask))
            .map_err(candle_error)?;
        selected_positions(&mask, self.edge_count, device, cancellation)
    }

    #[allow(clippy::too_many_arguments)]
    fn metal_row_bound_properties_mask(
        &self,
        request: &ResidentRowMutationRequest,
        program: &super::ResidentRowCreateProgram,
        entity_kind: EntityKind,
        properties: &[super::ResidentRowCreateProperty],
        source_rows: &Tensor,
        graph_rows: &Tensor,
        device: &Device,
        cancellation: &CancellationToken,
    ) -> Result<Tensor> {
        if source_rows.elem_count() != graph_rows.elem_count() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal bound-relationship property source and graph rows differ in length",
            ));
        }
        let row_count = source_rows.elem_count();
        if row_count == 0 {
            // Candle's Metal `ones(0)` enters its constant-fill grid helper and divides by a
            // zero threadgroup width. A zeroed empty tensor is allocation-free and carries the
            // same canonical U8 mask shape without dispatching a kernel.
            return Tensor::zeros(0, DType::U8, device).map_err(candle_error);
        }
        let mut mask = Tensor::ones(row_count, DType::U8, device).map_err(candle_error)?;
        for property in properties {
            ensure_not_cancelled(cancellation)?;
            let Some(expected) = Self::metal_row_bound_uniform_property_value(
                request,
                program,
                source_rows,
                property,
            )?
            else {
                continue;
            };
            let token = program
                .property_tokens
                .get(usize::from(property.property_name))
                .copied()
                .flatten();
            let property_mask = self.metal_row_bound_exact_property_mask(
                entity_kind,
                token,
                graph_rows,
                &expected,
                device,
                cancellation,
            )?;
            mask = mask.broadcast_mul(&property_mask).map_err(candle_error)?;
        }
        Ok(mask)
    }

    /// Materializes one final property column from the device-authored entity relation. Immutable
    /// graph lanes are gathered from the resident typed column on Metal; statement-local lanes
    /// are evaluated from their compiler-authored property source only after the device origin
    /// column proves that the lane is a creation. Unsupported resident scalar shapes fail closed.
    #[allow(clippy::too_many_arguments, clippy::too_many_lines)]
    fn metal_row_bound_output_property_values(
        &self,
        request: &ResidentRowMutationRequest,
        program: &super::ResidentRowCreateProgram,
        entity: &MetalRowCreateDeviceEntity,
        property_name: u16,
        source_rows: &Tensor,
        device: &Device,
    ) -> Result<Vec<ScalarValue>> {
        let row_count = source_rows.elem_count();
        if entity.target_ids.elem_count() != row_count
            || entity
                .dense_rows
                .as_ref()
                .is_some_and(|rows| rows.elem_count() != row_count)
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal bound-relationship property entity is not aligned with its row relation",
            ));
        }
        let synthesized_dense_rows;
        let dense_rows = if let Some(dense_rows) = entity.dense_rows.as_ref() {
            dense_rows
        } else {
            if entity.created_by.is_none() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal bound-relationship property entity omitted both dense and creation provenance",
                ));
            }
            synthesized_dense_rows = if row_count == 0 {
                Tensor::zeros(0, DType::U32, device).map_err(candle_error)?
            } else {
                Tensor::full(super::RESIDENT_NULL_ROW, row_count, device).map_err(candle_error)?
            };
            &synthesized_dense_rows
        };
        if dense_rows.dtype() != DType::U32 || dense_rows.rank() != 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal bound-relationship property dense rows are not canonical U32",
            ));
        }
        let source_lineage = if row_count == 0 {
            Vec::new()
        } else {
            source_rows.to_vec1::<i64>().map_err(candle_error)?
        }
        .into_iter()
        .map(|source| {
            u64::try_from(source).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal bound-relationship property source lineage is negative",
                )
            })
        })
        .collect::<Result<Vec<_>>>()?;
        let dense_host = if row_count == 0 {
            Vec::new()
        } else {
            dense_rows.to_vec1::<u32>().map_err(candle_error)?
        };
        let decoded_origins = entity
            .created_by
            .as_ref()
            .map(metal_row_bound_decode_origins)
            .transpose()?;
        let origins = decoded_origins.as_deref();
        if origins.is_some_and(|origins| origins.len() != row_count) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal bound-relationship property origin column changed cardinality",
            ));
        }
        for (row, dense) in dense_host.iter().copied().enumerate() {
            let created = origins.and_then(|origins| origins[row]);
            if (dense == super::RESIDENT_NULL_ROW) != created.is_some() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal bound-relationship property lane mixed dense and creation provenance",
                ));
            }
        }

        let mut output = vec![ScalarValue::Null; row_count];
        let property = program
            .property_tokens
            .get(usize::from(property_name))
            .copied()
            .flatten();
        let has_existing = dense_host
            .iter()
            .any(|dense| *dense != super::RESIDENT_NULL_ROW);
        if has_existing && let Some(property) = property {
            let safe_rows = dense_rows
                .ne(super::RESIDENT_NULL_ROW)
                .and_then(|present| {
                    present.where_cond(dense_rows, &Tensor::zeros(row_count, DType::U32, device)?)
                })
                .map_err(candle_error)?;
            let validity_and = |validity: &Option<Tensor>| -> Result<Vec<u8>> {
                let validity = validity.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident property output lost its validity tensor",
                    )
                })?;
                device_index_select(validity, &safe_rows, 0)?
                    .to_vec1::<u8>()
                    .map_err(candle_error)
            };

            let integer = match entity.kind {
                EntityKind::Node => self.integer_nodes.get(&property),
                EntityKind::Relationship => self.integer_edges.get(&property),
            };
            let boolean = match entity.kind {
                EntityKind::Node => self.boolean_nodes.get(&property),
                EntityKind::Relationship => self.boolean_edges.get(&property),
            };
            let float = match entity.kind {
                EntityKind::Node => self.float_nodes.get(&property),
                EntityKind::Relationship => self.float_edges.get(&property),
            };
            let string = match entity.kind {
                EntityKind::Node => self.string_nodes.get(&property),
                EntityKind::Relationship => self.string_edges.get(&property),
            };
            let list = match entity.kind {
                EntityKind::Node => self.list_nodes.get(&property),
                EntityKind::Relationship => self.list_edges.get(&property),
            };
            let map = match entity.kind {
                EntityKind::Node => self.map_nodes.get(&property),
                EntityKind::Relationship => self.map_edges.get(&property),
            };

            if let Some(column) = integer {
                let values = column.values.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident integer property output lost its value tensor",
                    )
                })?;
                let values = device_index_select(values, &safe_rows, 0)?
                    .to_vec1::<i64>()
                    .map_err(candle_error)?;
                let validity = validity_and(&column.validity)?;
                for row in 0..row_count {
                    if dense_host[row] != super::RESIDENT_NULL_ROW && validity[row] == 1 {
                        output[row] = ScalarValue::Integer(values[row]);
                    }
                }
            } else if let Some(column) = boolean {
                let values = column.values.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident Boolean property output lost its value tensor",
                    )
                })?;
                let values = device_index_select(values, &safe_rows, 0)?
                    .to_vec1::<u8>()
                    .map_err(candle_error)?;
                let validity = validity_and(&column.validity)?;
                for row in 0..row_count {
                    if dense_host[row] != super::RESIDENT_NULL_ROW && validity[row] == 1 {
                        output[row] = ScalarValue::Boolean(values[row] != 0);
                    }
                }
            } else if let Some(column) = float {
                let values = column.values.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident FLOAT property output lost its value tensor",
                    )
                })?;
                let values = device_index_select(values, &safe_rows, 0)?
                    .to_vec1::<i64>()
                    .map_err(candle_error)?;
                let validity = validity_and(&column.validity)?;
                for row in 0..row_count {
                    if dense_host[row] != super::RESIDENT_NULL_ROW && validity[row] == 1 {
                        output[row] = ScalarValue::Float(OrderedFloat(f64::from_bits(
                            u64::from_ne_bytes(values[row].to_ne_bytes()),
                        )));
                    }
                }
            } else if let Some(column) = string {
                let ids = column.values.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident STRING property output lost its ID tensor",
                    )
                })?;
                let ids = device_index_select(ids, &safe_rows, 0)?
                    .to_vec1::<u32>()
                    .map_err(candle_error)?;
                let validity = validity_and(&column.validity)?;
                let dictionary = match entity.kind {
                    EntityKind::Node => &self.node_string_dictionary,
                    EntityKind::Relationship => &self.edge_string_dictionary,
                };
                // Only the IDs these rows actually name. Decoding the whole dictionary here made a
                // query's cost scale with the project's distinct-string count rather than with the
                // rows it returns.
                let wanted: BTreeSet<u32> = (0..row_count)
                    .filter(|row| {
                        dense_host[*row] != super::RESIDENT_NULL_ROW && validity[*row] == 1
                    })
                    .map(|row| ids[row])
                    .collect();
                let entries = resident_string_dictionary_lookup(dictionary, &wanted)?;
                for row in 0..row_count {
                    if dense_host[row] != super::RESIDENT_NULL_ROW && validity[row] == 1 {
                        let value = entries.get(&ids[row]).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident STRING property output names a foreign dictionary ID",
                            )
                        })?;
                        output[row] =
                            ScalarValue::String(std::sync::Arc::<str>::from(value.as_str()));
                    }
                }
            } else if let Some((column, is_list)) = list
                .map(|column| (column, true))
                .or_else(|| map.map(|column| (column, false)))
            {
                let validity = validity_and(&column.validity)?;
                let starts = device_index_select(&column.offsets, &safe_rows, 0)?
                    .to_vec1::<u32>()
                    .map_err(candle_error)?;
                let offset_rows = safe_rows
                    .broadcast_add(&Tensor::new(1_u32, device).map_err(candle_error)?)
                    .map_err(candle_error)?;
                let ends = device_index_select(&column.offsets, &offset_rows, 0)?
                    .to_vec1::<u32>()
                    .map_err(candle_error)?;
                let bytes = column
                    .bytes
                    .as_ref()
                    .map(|bytes| bytes.to_vec1::<u8>().map_err(candle_error))
                    .transpose()?
                    .unwrap_or_default();
                for row in 0..row_count {
                    if dense_host[row] == super::RESIDENT_NULL_ROW || validity[row] != 1 {
                        continue;
                    }
                    let start = starts[row] as usize;
                    let end = ends[row] as usize;
                    let value = bytes.get(start..end).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident document property output has invalid byte offsets",
                        )
                    })?;
                    let canonical = std::sync::Arc::<[u8]>::from(value);
                    output[row] = if is_list {
                        ScalarValue::List(DocumentList::from_canonical(canonical))
                    } else {
                        ScalarValue::Map(DocumentMap::from_canonical(canonical))
                    };
                }
            } else {
                let unsupported = match entity.kind {
                    EntityKind::Node => {
                        self.date_nodes.contains_key(&property)
                            || self.local_time_nodes.contains_key(&property)
                            || self.zoned_time_nodes.contains_key(&property)
                            || self.local_datetime_nodes.contains_key(&property)
                            || self.zoned_datetime_nodes.contains_key(&property)
                            || self.duration_nodes.contains_key(&property)
                            || self.mixed_nodes.contains_key(&property)
                            || self.unsupported_node_properties.contains(&property)
                    }
                    EntityKind::Relationship => {
                        self.date_edges.contains_key(&property)
                            || self.local_time_edges.contains_key(&property)
                            || self.zoned_time_edges.contains_key(&property)
                            || self.local_datetime_edges.contains_key(&property)
                            || self.zoned_datetime_edges.contains_key(&property)
                            || self.duration_edges.contains_key(&property)
                            || self.mixed_edges.contains_key(&property)
                            || self.unsupported_edge_properties.contains(&property)
                    }
                };
                if unsupported {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal bound-relationship property output does not yet own this resident scalar shape",
                    ));
                }
            }
        }

        if let Some(origins) = decoded_origins {
            for (row, origin) in origins.into_iter().enumerate() {
                let Some(origin) = origin else {
                    continue;
                };
                let command = program
                    .commands
                    .get(usize::from(origin.command))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound-relationship property origin names a foreign command",
                        )
                    })?;
                let properties = match command {
                    ResidentRowCreateCommand::CreateNode(command) => &command.properties,
                    ResidentRowCreateCommand::CreateRelationship(command) => &command.properties,
                    ResidentRowCreateCommand::MatchNode(_) => {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound-relationship property origin names a MATCH command",
                        ));
                    }
                };
                let property_source = properties
                    .binary_search_by_key(&property_name, |property| property.property_name)
                    .ok()
                    .map(|index| &properties[index].value);
                output[row] = property_source.map_or(Ok(ScalarValue::Null), |source| {
                    super::resident_row_bound_property_value(
                        &request.input,
                        program,
                        source_lineage[row],
                        source,
                    )
                })?;
            }
        }
        Ok(output)
    }

    /// Resolves one conditional MERGE source against the device-authored work relation. Dynamic
    /// entity properties are gathered from the resident typed column after parent selection, so
    /// the values remain aligned with exactly the rows whose branch decision emits an action.
    fn metal_row_bound_merge_property_values(
        &self,
        request: &ResidentRowMutationRequest,
        program: &super::ResidentRowCreateProgram,
        state: &MetalRowCreateDeviceState,
        descriptor: &super::ResidentRowBoundMergePropertySet,
        device: &Device,
    ) -> Result<Vec<ScalarValue>> {
        let row_count = state.source_rows.elem_count();
        let values = match &descriptor.source {
            super::ResidentRowBoundMergePropertySource::Constant(value) => {
                vec![value.clone(); row_count]
            }
            super::ResidentRowBoundMergePropertySource::EntityProperty {
                entity,
                property_name,
                maximum_payload_bytes,
            } => {
                let source = state
                    .entities
                    .get(usize::from(*entity))
                    .and_then(Option::as_ref)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal conditional MERGE property source entity disappeared",
                        )
                    })?;
                let values = self.metal_row_bound_output_property_values(
                    request,
                    program,
                    source,
                    *property_name,
                    &state.source_rows,
                    device,
                )?;
                for value in &values {
                    if super::resident_row_bound_scalar_payload_bytes(value)?
                        > *maximum_payload_bytes
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal conditional MERGE property source exceeded its sealed payload bound",
                        ));
                    }
                }
                values
            }
        };
        if values.len() != row_count {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal conditional MERGE property source changed work-row cardinality",
            ));
        }
        Ok(values)
    }

    fn metal_row_create_scratch_bytes(request: &ResidentRowMutationRequest) -> Result<usize> {
        let body = request.create_body().ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal row CREATE scratch admission requires a CREATE body",
            )
        })?;
        usize::try_from(body.capacities.scratch_bytes).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row CREATE actual-byte scratch exceeds host address space",
            )
        })
    }

    fn metal_row_bound_relationship_scratch_bytes(
        &self,
        request: &ResidentRowMutationRequest,
    ) -> Result<usize> {
        let body = request.bound_relationship_merge_body().ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal bound-relationship scratch admission requires its discriminated body",
            )
        })?;
        let base = usize::try_from(body.capacities.scratch_bytes).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal bound-relationship actual-byte scratch exceeds host address space",
            )
        })?;
        let Some(schedule) = metal_row_bound_value_schedule(request)? else {
            return Ok(base);
        };
        let plan = MetalQuantifierPlan::build(self, &schedule.request)?;
        let output_bytes = plan
            .output
            .words
            .checked_mul(std::mem::size_of::<u64>())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound-value retained output allocation overflows usize",
                )
            })?;
        let group_words = metal_row_bound_value_group_output_words(
            plan.capacity.final_row_bound,
            plan.output.cell_capacity,
        )?;
        let group_logical_bytes = group_words
            .checked_mul(std::mem::size_of::<i64>())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound-value group allocation overflows usize",
                )
            })?;
        let group_bytes = metal_row_private_buffer_bytes(group_logical_bytes)?;
        let column_logical_bytes = schedule
            .request
            .program
            .outputs
            .len()
            .checked_mul(std::mem::size_of::<u32>())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound-value column upload overflows usize",
                )
            })?;
        let column_bytes = metal_row_shared_buffer_bytes(column_logical_bytes)?;
        let group_phase = output_bytes
            .checked_add(group_bytes)
            .and_then(|bytes| bytes.checked_add(column_bytes))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound-value group-phase admission overflows usize",
                )
            })?;
        base.checked_add(plan.admitted_bytes.max(group_phase))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound-relationship actual-byte admission overflows usize",
                )
            })
    }

    #[allow(clippy::too_many_lines)]
    fn execute_row_bound_relationship_merge_metal(
        &self,
        device: &Device,
        request: &ResidentRowMutationRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentRowMutationResult> {
        let body = request.bound_relationship_merge_body().ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal bound-relationship MERGE requires its discriminated body",
            )
        })?;
        let program = &body.program;
        let source_count = if request.input.is_empty() {
            1_usize
        } else {
            request.input.len()
        };
        let source_rows = (0..source_count)
            .map(|row| {
                i64::try_from(row).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal bound-relationship source lineage exceeds i64 tensor indexing",
                    )
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let mut state = MetalRowCreateDeviceState {
            source_rows: Tensor::from_slice(&source_rows, source_rows.len(), device)
                .map_err(candle_error)?,
            match_lineage: Vec::new(),
            entities: vec![None; usize::from(program.entity_slot_count)],
            value_rows: None,
        };
        let mut unwind_lineage = Vec::new();
        let mut node_lineage = Vec::new();
        let mut relationship_lineage = Vec::new();
        let mut command_receipts = Vec::<(u64, u64, u64)>::with_capacity(program.commands.len());
        let mut value_receipts = BTreeMap::<u16, (u64, u64)>::new();
        let mut value_schedule = metal_row_bound_value_schedule(request)?;
        let mut value_bank = None::<MetalBoundValueBank>;
        let mut delete_stages_before = vec![Vec::<usize>::new(); program.commands.len() + 1];
        let mut scheduled_commands = 0_usize;
        for (stage_index, stage) in body.schedule.stages.iter().enumerate() {
            match stage {
                super::ResidentRowBoundRelationshipStage::Command { .. } => {
                    scheduled_commands = scheduled_commands.checked_add(1).ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound schedule command count overflows usize",
                        )
                    })?;
                }
                super::ResidentRowBoundRelationshipStage::Delete { .. } => {
                    delete_stages_before
                        .get_mut(scheduled_commands)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound DELETE appears after a foreign command boundary",
                            )
                        })?
                        .push(stage_index);
                }
                super::ResidentRowBoundRelationshipStage::Unwind { .. }
                | super::ResidentRowBoundRelationshipStage::Project { .. } => {}
            }
        }
        if scheduled_commands != program.commands.len() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal bound schedule command count changed after admission",
            ));
        }
        let mut delete_state = MetalBoundDeleteState {
            node_tombstones: Tensor::zeros(self.node_count, DType::U8, device)
                .map_err(candle_error)?,
            relationship_tombstones: Tensor::zeros(self.edge_count, DType::U8, device)
                .map_err(candle_error)?,
            intents: Vec::new(),
            receipts: BTreeMap::new(),
        };
        let mut node_dependency_candidates = Vec::<Tensor>::new();
        let mut relationship_dependency_candidates = Vec::<Tensor>::new();
        let mut probe_occurrences = 0_u64;
        let mut node_id_offset = 0_u64;
        let mut relationship_id_offset = 0_u64;
        let mut intents = Vec::<ResidentRowMutationWorkIntent>::new();
        let mut merge_property_actions = Vec::<super::ResidentRowBoundMergePropertyAction>::new();
        let mut merge_label_actions = Vec::<super::ResidentRowBoundMergeLabelAction>::new();
        let mut local_nodes = Vec::<MetalBoundLocalNode>::new();
        let mut local_relationships = Vec::<MetalBoundLocalRelationship>::new();
        let first_edge_id = request.first_edge_id.ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal bound-relationship relationship-ID origin disappeared",
            )
        })?;

        for (command_index, (command, semantics)) in
            program.commands.iter().zip(&body.commands).enumerate()
        {
            ensure_not_cancelled(cancellation)?;
            for stage_index in &delete_stages_before[command_index] {
                let stage = body.schedule.stages.get(*stage_index).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal bound DELETE stage disappeared before execution",
                    )
                })?;
                let super::ResidentRowBoundRelationshipStage::Delete {
                    detach, targets, ..
                } = stage
                else {
                    return Err(Error::internal(
                        "Metal bound DELETE schedule index names a non-delete stage",
                    ));
                };
                metal_row_bound_execute_delete_stage(
                    self,
                    u16::try_from(*stage_index).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound DELETE stage index exceeds u16",
                        )
                    })?,
                    *detach,
                    targets,
                    &state,
                    &mut delete_state,
                    &mut local_nodes,
                    &mut local_relationships,
                    device,
                    cancellation,
                )?;
            }
            let command_index = u16::try_from(command_index).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound-relationship command index exceeds u16",
                )
            })?;
            if value_schedule
                .as_ref()
                .is_some_and(|schedule| schedule.activation_command == command_index)
            {
                if state.source_rows.elem_count() != 1 || state.value_rows.is_some() {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal dynamic value block lost its sealed one-row entry relation",
                    ));
                }
                let schedule = value_schedule.take().ok_or_else(|| {
                    Error::internal("Metal dynamic value schedule disappeared before execution")
                })?;
                let bank =
                    metal_row_bound_execute_value_bank(self, device, schedule, cancellation)?;
                let output_count = bank.row_count;
                let parent_rows = if output_count == 0 {
                    Tensor::zeros(0, DType::I64, device).map_err(candle_error)?
                } else {
                    Tensor::zeros(output_count, DType::I64, device).map_err(candle_error)?
                };
                let item_rows = if output_count == 0 {
                    Tensor::zeros(0, DType::I64, device).map_err(candle_error)?
                } else {
                    Tensor::arange(
                        0_i64,
                        i64::try_from(output_count).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound UNWIND item lineage exceeds i64",
                            )
                        })?,
                        device,
                    )
                    .map_err(candle_error)?
                };
                metal_row_create_select_parents(&mut state, &parent_rows)?;
                let value_rows = if output_count == 0 {
                    Tensor::zeros(0, DType::U32, device).map_err(candle_error)?
                } else {
                    Tensor::arange(
                        0_i64,
                        i64::try_from(output_count).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound value lineage exceeds i64",
                            )
                        })?,
                        device,
                    )
                    .and_then(|rows| rows.to_dtype(DType::U32))
                    .map_err(candle_error)?
                };
                state.value_rows = Some(value_rows);
                let source_rows = if output_count == 0 {
                    Vec::new()
                } else {
                    state.source_rows.to_vec1::<i64>().map_err(candle_error)?
                };
                let parent_rows_host = if output_count == 0 {
                    Vec::new()
                } else {
                    parent_rows.to_vec1::<i64>().map_err(candle_error)?
                };
                let item_rows_host = if output_count == 0 {
                    Vec::new()
                } else {
                    item_rows.to_vec1::<i64>().map_err(candle_error)?
                };
                let lineage_rows = parent_rows_host
                    .into_iter()
                    .zip(source_rows)
                    .zip(item_rows_host)
                    .map(|((parent_work_row, source_row), item_index)| {
                        Ok(super::ResidentRowBoundUnwindLineageEntry {
                            parent_work_row: u64::try_from(parent_work_row).map_err(|_| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound UNWIND emitted negative parent lineage",
                                )
                            })?,
                            source_row: u64::try_from(source_row).map_err(|_| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound UNWIND emitted negative source lineage",
                                )
                            })?,
                            item_index: u64::try_from(item_index).map_err(|_| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound UNWIND emitted negative item lineage",
                                )
                            })?,
                        })
                    })
                    .collect::<Result<Vec<_>>>()?;
                if u64::try_from(lineage_rows.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal bound UNWIND lineage exceeds u64",
                    )
                })? > body.capacities.maximum_unwind_lineage_entries
                {
                    return Err(Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal bound UNWIND lineage exceeded admitted bytes",
                    ));
                }
                if bank.schedule.value_stages.len() != bank.stage_cardinalities.len() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal bound value stage receipts lost schedule alignment",
                    ));
                }
                for ((stage, _), cardinality) in bank
                    .schedule
                    .value_stages
                    .iter()
                    .zip(&bank.stage_cardinalities)
                {
                    value_receipts.insert(*stage, *cardinality);
                }
                unwind_lineage.push(super::ResidentRowBoundUnwindLineageStage {
                    stage: bank.schedule.unwind_stage,
                    rows: lineage_rows,
                });
                value_bank = Some(bank);
            }
            match (command, semantics) {
                (
                    ResidentRowCreateCommand::MatchNode(command),
                    super::ResidentRowBoundRelationshipCommand::MatchNode { properties }
                    | super::ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites {
                        properties,
                    },
                ) => {
                    let include_statement_local_writes = matches!(
                        semantics,
                        super::ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites { .. }
                    );
                    let input_count = state.source_rows.elem_count();
                    let candidates = if input_count == 0 {
                        self.outgoing_offsets
                            .narrow(0, 0, 0)
                            .map_err(candle_error)?
                    } else {
                        self.metal_row_create_candidates(
                            program,
                            command,
                            request.read_layers,
                            device,
                            cancellation,
                        )?
                    };
                    let candidates = metal_row_bound_live_candidates(
                        &candidates,
                        &delete_state.node_tombstones,
                        device,
                        cancellation,
                    )?;
                    if input_count != 0 {
                        node_dependency_candidates.push(candidates.clone());
                    }
                    let (all_parents, all_candidate_positions) =
                        metal_row_create_cartesian_indices(
                            &state.source_rows,
                            &candidates,
                            device,
                        )?;
                    let all_dense = device_index_select(&candidates, &all_candidate_positions, 0)?;
                    let all_sources = device_index_select(&state.source_rows, &all_parents, 0)?;
                    let property_mask = self.metal_row_bound_properties_mask(
                        request,
                        program,
                        EntityKind::Node,
                        properties,
                        &all_sources,
                        &all_dense,
                        device,
                        cancellation,
                    )?;
                    let selected = selected_positions(
                        &property_mask,
                        all_dense.elem_count(),
                        device,
                        cancellation,
                    )?;
                    let immutable_parents = device_index_select(&all_parents, &selected, 0)?;
                    let immutable_dense = device_index_select(&all_dense, &selected, 0)?;
                    let node_ids = self.node_entity_ids.as_ref();
                    let candidate_ids = if candidates.elem_count() == 0 {
                        state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        device_index_select(
                            node_ids.ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound-relationship non-empty graph lost node IDs",
                                )
                            })?,
                            &candidates,
                            0,
                        )?
                    };
                    let all_ids = device_index_select(&candidate_ids, &all_candidate_positions, 0)?;
                    let immutable_ids = device_index_select(&all_ids, &selected, 0)?;
                    let immutable_origins =
                        Tensor::zeros(immutable_parents.elem_count(), DType::I64, device)
                            .map_err(candle_error)?;
                    let immutable_origin_commands =
                        Tensor::zeros(immutable_parents.elem_count(), DType::U32, device)
                            .map_err(candle_error)?;
                    let mut parents = immutable_parents;
                    let mut dense = immutable_dense;
                    let mut ids = immutable_ids;
                    let mut origin_rows = immutable_origins;
                    let mut origin_commands = immutable_origin_commands;
                    let mut has_local = false;

                    if include_statement_local_writes {
                        let local_expected = properties
                            .iter()
                            .map(|property| {
                                Ok(super::ResidentMutationIntentEntry {
                                    property_name: property.property_name,
                                    value: Self::metal_row_bound_uniform_property_value(
                                        request,
                                        program,
                                        &state.source_rows,
                                        property,
                                    )?
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "Metal ordered node MATCH lost a non-empty property source",
                                        )
                                    })?,
                                })
                            })
                            .collect::<Result<Vec<_>>>()?;
                        let local_mask = Self::metal_row_bound_local_node_mask(
                            program,
                            &command.labels,
                            &local_expected,
                            &local_nodes,
                            device,
                        )?;
                        let local_selected = selected_positions(
                            &local_mask,
                            local_nodes.len(),
                            device,
                            cancellation,
                        )?;
                        let local_ids_host = local_nodes
                            .iter()
                            .map(|candidate| candidate.entity.target_id)
                            .collect::<Vec<_>>();
                        let local_origin_rows = local_nodes
                            .iter()
                            .map(|candidate| {
                                candidate
                                    .entity
                                    .created_by
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "Metal ordered node MATCH candidate lost creation provenance",
                                        )
                                    })?
                                    .work_row
                                    .checked_add(1)
                                    .and_then(|row| i64::try_from(row).ok())
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal ordered node MATCH origin exceeds i64",
                                        )
                                    })
                            })
                            .collect::<Result<Vec<_>>>()?;
                        let local_origin_commands = local_nodes
                            .iter()
                            .map(|candidate| {
                                candidate
                                    .entity
                                    .created_by
                                    .map(|origin| u32::from(origin.command))
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "Metal ordered node MATCH candidate lost its origin command",
                                        )
                                    })
                            })
                            .collect::<Result<Vec<_>>>()?;
                        let local_id_bank =
                            metal_row_create_u64_bits(&local_ids_host, &state.source_rows, device)?;
                        let local_origin_bank = if local_origin_rows.is_empty() {
                            state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                        } else {
                            Tensor::from_slice(&local_origin_rows, local_origin_rows.len(), device)
                                .map_err(candle_error)?
                        };
                        let local_command_bank = if local_origin_commands.is_empty() {
                            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?
                        } else {
                            Tensor::from_slice(
                                &local_origin_commands,
                                local_origin_commands.len(),
                                device,
                            )
                            .map_err(candle_error)?
                        };
                        let selected_local_ids =
                            device_index_select(&local_id_bank, &local_selected, 0)?;
                        let selected_local_origins =
                            device_index_select(&local_origin_bank, &local_selected, 0)?;
                        let selected_local_commands =
                            device_index_select(&local_command_bank, &local_selected, 0)?;
                        let (local_parents, local_candidate_positions) =
                            metal_row_create_cartesian_indices(
                                &state.source_rows,
                                &local_selected,
                                device,
                            )?;
                        has_local = local_parents.elem_count() != 0;
                        let local_ids = device_index_select(
                            &selected_local_ids,
                            &local_candidate_positions,
                            0,
                        )?;
                        let local_origins = device_index_select(
                            &selected_local_origins,
                            &local_candidate_positions,
                            0,
                        )?;
                        let local_commands = device_index_select(
                            &selected_local_commands,
                            &local_candidate_positions,
                            0,
                        )?;
                        let local_dense = if local_parents.elem_count() == 0 {
                            candidates.narrow(0, 0, 0).map_err(candle_error)?
                        } else {
                            Tensor::full(
                                super::RESIDENT_NULL_ROW,
                                local_parents.elem_count(),
                                device,
                            )
                            .map_err(candle_error)?
                        };
                        parents = metal_row_cat(&parents, &local_parents)?;
                        dense = metal_row_cat(&dense, &local_dense)?;
                        ids = metal_row_cat(&ids, &local_ids)?;
                        origin_rows = metal_row_cat(&origin_rows, &local_origins)?;
                        origin_commands = metal_row_cat(&origin_commands, &local_commands)?;
                        if parents.elem_count() > 1 {
                            let order =
                                scalable_stable_argsort(&parents, true, device, cancellation)?;
                            parents = device_index_select(&parents, &order, 0)?;
                            dense = device_index_select(&dense, &order, 0)?;
                            ids = device_index_select(&ids, &order, 0)?;
                            origin_rows = device_index_select(&origin_rows, &order, 0)?;
                            origin_commands = device_index_select(&origin_commands, &order, 0)?;
                        }
                    }
                    let created_by = has_local.then_some(MetalRowCreateDeviceOrigin {
                        command: command_index,
                        command_rows: Some(origin_commands),
                        work_rows: origin_rows,
                    });
                    let output_count = dense.elem_count();
                    let output_count_u64 = u64::try_from(output_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound node MATCH output exceeds u64",
                        )
                    })?;
                    if output_count_u64 > body.capacities.maximum_rows {
                        return Err(Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound node MATCH exceeded admitted row bytes",
                        ));
                    }
                    let parent_host = if output_count == 0 {
                        Vec::new()
                    } else {
                        parents.to_vec1::<i64>().map_err(candle_error)?
                    };
                    metal_row_create_select_parents(&mut state, &parents)?;
                    let source_host = if output_count == 0 {
                        Vec::new()
                    } else {
                        state.source_rows.to_vec1::<i64>().map_err(candle_error)?
                    };
                    let dense_host = if output_count == 0 {
                        Vec::new()
                    } else {
                        dense.to_vec1::<u32>().map_err(candle_error)?
                    };
                    let id_host = metal_row_create_decode_u64_bits(&ids)?;
                    let origin_host = created_by
                        .as_ref()
                        .map(metal_row_bound_decode_origins)
                        .transpose()?
                        .unwrap_or_else(|| vec![None; output_count]);
                    if parent_host.len() != output_count
                        || source_host.len() != output_count
                        || dense_host.len() != output_count
                        || id_host.len() != output_count
                        || origin_host.len() != output_count
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal ordered node MATCH device columns changed cardinality",
                        ));
                    }
                    let stage_rows = (0..output_count)
                        .map(|row| {
                            Ok(ResidentRowBoundNodeLineageEntry {
                                parent_work_row: u64::try_from(parent_host[row]).map_err(|_| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal bound node MATCH emitted negative parent lineage",
                                    )
                                })?,
                                source_row: u64::try_from(source_host[row]).map_err(|_| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal bound node MATCH emitted negative source lineage",
                                    )
                                })?,
                                node: ResidentRowCreateEntity {
                                    kind: EntityKind::Node,
                                    target_id: id_host[row],
                                    dense_row: (dense_host[row] != super::RESIDENT_NULL_ROW)
                                        .then_some(dense_host[row]),
                                    created_by: origin_host[row],
                                },
                            })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    if state.entities[usize::from(command.output_entity)]
                        .replace(MetalRowCreateDeviceEntity {
                            kind: EntityKind::Node,
                            target_ids: ids,
                            dense_rows: Some(dense.clone()),
                            created_by,
                        })
                        .is_some()
                    {
                        return Err(Error::internal(
                            "Metal bound node MATCH rebound an entity slot",
                        ));
                    }
                    state.match_lineage.push(dense);
                    node_lineage.push(ResidentRowBoundNodeLineageStage {
                        command: command_index,
                        rows: stage_rows,
                    });
                    let input_count_u64 = u64::try_from(input_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound node MATCH input exceeds u64",
                        )
                    })?;
                    command_receipts.push((input_count_u64, output_count_u64, 0));
                    probe_occurrences = probe_occurrences
                        .checked_add(output_count_u64)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound probe occurrence count overflows u64",
                            )
                        })?;
                }
                (
                    ResidentRowCreateCommand::CreateNode(command),
                    super::ResidentRowBoundRelationshipCommand::CreateNode,
                ) => {
                    let row_count = state.source_rows.elem_count();
                    let row_count_u64 = u64::try_from(row_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound node CREATE input exceeds u64",
                        )
                    })?;
                    let ids = (0..row_count)
                        .map(|work_row| {
                            let work_row = u64::try_from(work_row).map_err(|_| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal bound node CREATE work row exceeds u64",
                                )
                            })?;
                            request
                                .first_node_id
                                .checked_add(node_id_offset)
                                .and_then(|id| id.checked_add(work_row))
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound node CREATE identity overflows u64",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let target_ids = metal_row_create_u64_bits(&ids, &state.source_rows, device)?;
                    let created_by = MetalRowCreateDeviceOrigin {
                        command: command_index,
                        command_rows: None,
                        work_rows: metal_row_create_identity_origins(
                            row_count,
                            &state.source_rows,
                            device,
                        )?,
                    };
                    let source_rows = if row_count == 0 {
                        Vec::new()
                    } else {
                        state.source_rows.to_vec1::<i64>().map_err(candle_error)?
                    };
                    let target_ids_host = metal_row_create_decode_u64_bits(&target_ids)?;
                    let (origin_command, origin_rows) =
                        metal_row_create_decode_origins(&created_by)?;
                    if origin_command != command_index
                        || source_rows.len() != row_count
                        || target_ids_host.len() != row_count
                        || origin_rows.len() != row_count
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound node CREATE device columns changed cardinality or command",
                        ));
                    }
                    for row in 0..row_count {
                        let source_row = u64::try_from(source_rows[row]).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound node CREATE emitted negative source lineage",
                            )
                        })?;
                        let work_row = origin_rows[row].ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound node CREATE omitted device creation provenance",
                            )
                        })?;
                        let expected_work_row = u64::try_from(row).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound node CREATE host work row exceeds u64",
                            )
                        })?;
                        if work_row != expected_work_row {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound node CREATE changed stable work-row provenance",
                            ));
                        }
                        let properties = command
                            .properties
                            .iter()
                            .map(|property| {
                                Ok(super::ResidentMutationIntentEntry {
                                    property_name: property.property_name,
                                    value: super::resident_row_bound_property_value(
                                        &request.input,
                                        program,
                                        source_row,
                                        &property.value,
                                    )?,
                                })
                            })
                            .collect::<Result<Vec<_>>>()?;
                        local_nodes.push(MetalBoundLocalNode {
                            labels: command.labels.clone(),
                            properties: properties.clone(),
                            entity: ResidentRowCreateEntity {
                                kind: EntityKind::Node,
                                target_id: target_ids_host[row],
                                dense_row: None,
                                created_by: Some(ResidentRowCreateEntityOrigin {
                                    command: command_index,
                                    work_row,
                                }),
                            },
                            deleted: false,
                        });
                        intents.push(ResidentRowMutationWorkIntent {
                            work_row,
                            source_row,
                            command: command_index,
                            target_id: target_ids_host[row],
                            action: ResidentRowMutationWorkIntentAction::CreateNode {
                                labels: command.labels.clone(),
                                properties,
                            },
                        });
                    }
                    if state.entities[usize::from(command.output_entity)]
                        .replace(MetalRowCreateDeviceEntity {
                            kind: EntityKind::Node,
                            target_ids,
                            dense_rows: None,
                            created_by: Some(created_by),
                        })
                        .is_some()
                    {
                        return Err(Error::internal(
                            "Metal bound node CREATE rebound an entity slot",
                        ));
                    }
                    node_id_offset =
                        node_id_offset.checked_add(row_count_u64).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound node CREATE identity offset overflows u64",
                            )
                        })?;
                    command_receipts.push((row_count_u64, row_count_u64, row_count_u64));
                }
                (
                    ResidentRowCreateCommand::CreateRelationship(command),
                    super::ResidentRowBoundRelationshipCommand::CreateRelationship,
                ) => {
                    let row_count = state.source_rows.elem_count();
                    let row_count_u64 = u64::try_from(row_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound relationship CREATE input exceeds u64",
                        )
                    })?;
                    let source_entity = state
                        .entities
                        .get(usize::from(command.source_entity))
                        .and_then(Option::as_ref)
                        .filter(|entity| entity.kind == EntityKind::Node)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::GpuAdmissionFailure,
                                "Metal bound relationship CREATE source endpoint is not a bound node",
                            )
                        })?;
                    let source_node_ids =
                        metal_row_create_decode_u64_bits(&source_entity.target_ids)?;
                    let target_entity = state
                        .entities
                        .get(usize::from(command.target_entity))
                        .and_then(Option::as_ref)
                        .filter(|entity| entity.kind == EntityKind::Node)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::GpuAdmissionFailure,
                                "Metal bound relationship CREATE target endpoint is not a bound node",
                            )
                        })?;
                    let target_node_ids =
                        metal_row_create_decode_u64_bits(&target_entity.target_ids)?;
                    let ids = (0..row_count)
                        .map(|work_row| {
                            let work_row = u64::try_from(work_row).map_err(|_| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal bound relationship CREATE work row exceeds u64",
                                )
                            })?;
                            first_edge_id
                                .checked_add(relationship_id_offset)
                                .and_then(|id| id.checked_add(work_row))
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound relationship CREATE identity overflows u64",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let relationship_ids =
                        metal_row_create_u64_bits(&ids, &state.source_rows, device)?;
                    let created_by = MetalRowCreateDeviceOrigin {
                        command: command_index,
                        command_rows: None,
                        work_rows: metal_row_create_identity_origins(
                            row_count,
                            &state.source_rows,
                            device,
                        )?,
                    };
                    let source_rows = if row_count == 0 {
                        Vec::new()
                    } else {
                        state.source_rows.to_vec1::<i64>().map_err(candle_error)?
                    };
                    let relationship_ids_host =
                        metal_row_create_decode_u64_bits(&relationship_ids)?;
                    let (origin_command, origin_rows) =
                        metal_row_create_decode_origins(&created_by)?;
                    if origin_command != command_index
                        || source_rows.len() != row_count
                        || source_node_ids.len() != row_count
                        || target_node_ids.len() != row_count
                        || relationship_ids_host.len() != row_count
                        || origin_rows.len() != row_count
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound relationship CREATE device columns changed cardinality or command",
                        ));
                    }
                    for row in 0..row_count {
                        let source_row = u64::try_from(source_rows[row]).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound relationship CREATE emitted negative source lineage",
                            )
                        })?;
                        let work_row = origin_rows[row].ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound relationship CREATE omitted device creation provenance",
                            )
                        })?;
                        let expected_work_row = u64::try_from(row).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound relationship CREATE host work row exceeds u64",
                            )
                        })?;
                        if work_row != expected_work_row {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound relationship CREATE changed stable work-row provenance",
                            ));
                        }
                        let properties = command
                            .properties
                            .iter()
                            .map(|property| {
                                Ok(super::ResidentMutationIntentEntry {
                                    property_name: property.property_name,
                                    value: super::resident_row_bound_property_value(
                                        &request.input,
                                        program,
                                        source_row,
                                        &property.value,
                                    )?,
                                })
                            })
                            .collect::<Result<Vec<_>>>()?;
                        let relationship = ResidentRowCreateEntity {
                            kind: EntityKind::Relationship,
                            target_id: relationship_ids_host[row],
                            dense_row: None,
                            created_by: Some(ResidentRowCreateEntityOrigin {
                                command: command_index,
                                work_row,
                            }),
                        };
                        local_relationships.push(MetalBoundLocalRelationship {
                            source_node_id: source_node_ids[row],
                            target_node_id: target_node_ids[row],
                            relationship_type: command.relationship_type,
                            properties: properties.clone(),
                            entity: relationship,
                            deleted: false,
                        });
                        intents.push(ResidentRowMutationWorkIntent {
                            work_row,
                            source_row,
                            command: command_index,
                            target_id: relationship.target_id,
                            action: ResidentRowMutationWorkIntentAction::CreateRelationship {
                                relationship_type: command.relationship_type,
                                source_node_id: source_node_ids[row],
                                target_node_id: target_node_ids[row],
                                properties,
                            },
                        });
                    }
                    if state.entities[usize::from(command.output_entity)]
                        .replace(MetalRowCreateDeviceEntity {
                            kind: EntityKind::Relationship,
                            target_ids: relationship_ids,
                            dense_rows: None,
                            created_by: Some(created_by),
                        })
                        .is_some()
                    {
                        return Err(Error::internal(
                            "Metal bound relationship CREATE rebound an entity slot",
                        ));
                    }
                    relationship_id_offset = relationship_id_offset
                        .checked_add(row_count_u64)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound relationship CREATE identity offset overflows u64",
                            )
                        })?;
                    command_receipts.push((row_count_u64, row_count_u64, row_count_u64));
                }
                (
                    ResidentRowCreateCommand::CreateNode(command),
                    super::ResidentRowBoundRelationshipCommand::MergeNode,
                ) => {
                    let input_count = state.source_rows.elem_count();
                    let input_count_u64 = u64::try_from(input_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound node MERGE input exceeds u64",
                        )
                    })?;
                    if input_count == 0 {
                        let empty_ids = state.source_rows.narrow(0, 0, 0).map_err(candle_error)?;
                        let empty_dense =
                            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                        if state.entities[usize::from(command.output_entity)]
                            .replace(MetalRowCreateDeviceEntity {
                                kind: EntityKind::Node,
                                target_ids: empty_ids,
                                dense_rows: Some(empty_dense),
                                created_by: None,
                            })
                            .is_some()
                        {
                            return Err(Error::internal(
                                "Metal bound node MERGE rebound an entity slot",
                            ));
                        }
                        node_lineage.push(ResidentRowBoundNodeLineageStage {
                            command: command_index,
                            rows: Vec::new(),
                        });
                        command_receipts.push((0, 0, 0));
                        continue;
                    }

                    let dynamic_bindings = body
                        .schedule
                        .property_bindings
                        .iter()
                        .filter(|binding| binding.command == command_index)
                        .collect::<Vec<_>>();
                    if !dynamic_bindings.is_empty() {
                        if !body.merge_property_sets.is_empty() || !body.merge_label_sets.is_empty()
                        {
                            return Err(Error::new(
                                ErrorCode::GpuAdmissionFailure,
                                "Metal dynamic-key node MERGE cannot carry conditional SET actions",
                            ));
                        }

                        // Resolve each compiler-authored key source against the current device row
                        // relation. The host materialization is limited to scalar values already
                        // authorized as mutation payload; candidate membership remains a Metal
                        // property-mask decision below.
                        let mut property_columns = Vec::with_capacity(command.properties.len());
                        for property in &command.properties {
                            let binding = dynamic_bindings
                                .iter()
                                .find(|binding| binding.property_name == property.property_name);
                            let values = if let Some(binding) = binding {
                                match binding.source {
                                    super::ResidentRowBoundPropertyBindingSource::EntityProperty {
                                        entity,
                                        property_name,
                                        integer_addend,
                                        maximum_payload_bytes,
                                    } => {
                                        let source = state
                                            .entities
                                            .get(usize::from(entity))
                                            .and_then(Option::as_ref)
                                            .ok_or_else(|| {
                                                Error::new(
                                                    ErrorCode::CorruptStorage,
                                                    "Metal dynamic node-MERGE key source entity disappeared",
                                                )
                                            })?;
                                        let mut values = self
                                            .metal_row_bound_output_property_values(
                                                request,
                                                program,
                                                source,
                                                property_name,
                                                &state.source_rows,
                                                device,
                                            )?;
                                        for value in &mut values {
                                            if matches!(value, ScalarValue::Null) {
                                                return Err(Error::new(
                                                    ErrorCode::QueryType,
                                                    "MERGE node key properties cannot be NULL",
                                                ));
                                            }
                                            if integer_addend != 0 {
                                                let ScalarValue::Integer(integer) = value else {
                                                    return Err(Error::new(
                                                        ErrorCode::QueryType,
                                                        "dynamic MERGE arithmetic requires an INTEGER property",
                                                    ));
                                                };
                                                *integer = integer.checked_add(integer_addend).ok_or_else(
                                                    || {
                                                        Error::new(
                                                            ErrorCode::QueryType,
                                                            "dynamic MERGE integer arithmetic overflowed",
                                                        )
                                                    },
                                                )?;
                                            }
                                            if super::resident_row_bound_scalar_payload_bytes(value)?
                                                > maximum_payload_bytes
                                            {
                                                return Err(Error::new(
                                                    ErrorCode::CorruptStorage,
                                                    "Metal dynamic node-MERGE key exceeded its sealed payload bound",
                                                ));
                                            }
                                        }
                                        values
                                    }
                                    super::ResidentRowBoundPropertyBindingSource::ValueSlot(
                                        value_slot,
                                    ) => {
                                        let bank = value_bank.as_ref().ok_or_else(|| {
                                            Error::new(
                                                ErrorCode::CorruptStorage,
                                                "Metal dynamic node-MERGE lost its value bank",
                                            )
                                        })?;
                                        let value_rows = state.value_rows.as_ref().ok_or_else(|| {
                                            Error::new(
                                                ErrorCode::CorruptStorage,
                                                "Metal dynamic node-MERGE lost value lineage",
                                            )
                                        })?;
                                        let values = metal_row_bound_value_slot_scalars(
                                            bank,
                                            value_rows,
                                            value_slot,
                                        )?;
                                        for value in &values {
                                            if matches!(value, ScalarValue::Null) {
                                                return Err(Error::new(
                                                    ErrorCode::QueryType,
                                                    "MERGE node key properties cannot be NULL",
                                                ));
                                            }
                                            super::resident_row_bound_scalar_payload_bytes(value)?;
                                        }
                                        values
                                    }
                                }
                            } else {
                                let value = Self::metal_row_bound_uniform_property_value(
                                    request,
                                    program,
                                    &state.source_rows,
                                    property,
                                )?
                                .ok_or_else(|| {
                                    Error::internal(
                                        "Metal dynamic node MERGE lost a non-empty property source",
                                    )
                                })?;
                                if matches!(value, ScalarValue::Null) {
                                    return Err(Error::new(
                                        ErrorCode::QueryType,
                                        "MERGE node key properties cannot be NULL",
                                    ));
                                }
                                vec![value; input_count]
                            };
                            if values.len() != input_count {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal dynamic node-MERGE key changed row cardinality",
                                ));
                            }
                            property_columns.push((property.property_name, values));
                        }
                        if dynamic_bindings.iter().any(|binding| {
                            !command
                                .properties
                                .iter()
                                .any(|property| property.property_name == binding.property_name)
                        }) {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal dynamic node-MERGE binding names a non-key property",
                            ));
                        }

                        let expected_rows = (0..input_count)
                            .map(|row| {
                                property_columns
                                    .iter()
                                    .map(|(property_name, values)| {
                                        super::ResidentMutationIntentEntry {
                                            property_name: *property_name,
                                            value: values[row].clone(),
                                        }
                                    })
                                    .collect::<Vec<_>>()
                            })
                            .collect::<Vec<_>>();
                        let mut groups =
                            Vec::<(Vec<super::ResidentMutationIntentEntry>, Vec<usize>)>::new();
                        for (parent, expected) in expected_rows.into_iter().enumerate() {
                            if let Some((_, parents)) = groups
                                .iter_mut()
                                .find(|(candidate, _)| candidate == &expected)
                            {
                                parents.push(parent);
                            } else {
                                groups.push((expected, vec![parent]));
                            }
                        }

                        let candidates = self.metal_row_bound_node_candidates(
                            program,
                            &command.labels,
                            request.read_layers,
                            device,
                            cancellation,
                        )?;
                        let candidates = metal_row_bound_live_candidates(
                            &candidates,
                            &delete_state.node_tombstones,
                            device,
                            cancellation,
                        )?;
                        node_dependency_candidates.push(candidates.clone());
                        let candidate_ids = if candidates.elem_count() == 0 {
                            state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                        } else {
                            device_index_select(
                                self.node_entity_ids.as_ref().ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal dynamic node MERGE lost resident node IDs",
                                    )
                                })?,
                                &candidates,
                                0,
                            )?
                        };

                        let mut parents =
                            state.source_rows.narrow(0, 0, 0).map_err(candle_error)?;
                        let mut dense_rows =
                            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                        let mut target_ids =
                            state.source_rows.narrow(0, 0, 0).map_err(candle_error)?;
                        let mut origin_rows =
                            state.source_rows.narrow(0, 0, 0).map_err(candle_error)?;
                        let mut origin_commands =
                            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                        let mut creation_groups =
                            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                        let mut created =
                            Vec::<(u32, u64, Vec<super::ResidentMutationIntentEntry>)>::new();
                        let mut has_immutable = false;
                        let mut has_local = false;

                        for (expected, parent_positions) in &groups {
                            ensure_not_cancelled(cancellation)?;
                            let parent_positions = parent_positions
                                .iter()
                                .map(|parent| i64::try_from(*parent))
                                .collect::<std::result::Result<Vec<_>, _>>()
                                .map_err(|_| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal dynamic node-MERGE parent exceeds i64",
                                    )
                                })?;
                            let group_parents = Tensor::from_slice(
                                &parent_positions,
                                parent_positions.len(),
                                device,
                            )
                            .map_err(candle_error)?;

                            // Candle's Metal constant-fill helper cannot dispatch a zero-width
                            // grid. Preserve the canonical empty mask without launching a kernel.
                            let mut immutable_mask = if candidates.elem_count() == 0 {
                                Tensor::zeros(0, DType::U8, device).map_err(candle_error)?
                            } else {
                                Tensor::ones(candidates.elem_count(), DType::U8, device)
                                    .map_err(candle_error)?
                            };
                            for property in expected {
                                let token = program
                                    .property_tokens
                                    .get(usize::from(property.property_name))
                                    .copied()
                                    .flatten();
                                let property_mask = self.metal_row_bound_exact_property_mask(
                                    EntityKind::Node,
                                    token,
                                    &candidates,
                                    &property.value,
                                    device,
                                    cancellation,
                                )?;
                                immutable_mask = immutable_mask
                                    .broadcast_mul(&property_mask)
                                    .map_err(candle_error)?;
                            }
                            let immutable_selected = selected_positions(
                                &immutable_mask,
                                candidates.elem_count(),
                                device,
                                cancellation,
                            )?;
                            let selected_dense =
                                device_index_select(&candidates, &immutable_selected, 0)?;
                            let selected_ids =
                                device_index_select(&candidate_ids, &immutable_selected, 0)?;
                            let (relative_parents, candidate_positions) =
                                metal_row_create_cartesian_indices(
                                    &group_parents,
                                    &immutable_selected,
                                    device,
                                )?;
                            let immutable_parents =
                                device_index_select(&group_parents, &relative_parents, 0)?;
                            let immutable_dense =
                                device_index_select(&selected_dense, &candidate_positions, 0)?;
                            let immutable_ids =
                                device_index_select(&selected_ids, &candidate_positions, 0)?;
                            let immutable_count = immutable_parents.elem_count();
                            if immutable_count != 0 {
                                has_immutable = true;
                                parents = metal_row_cat(&parents, &immutable_parents)?;
                                dense_rows = metal_row_cat(&dense_rows, &immutable_dense)?;
                                target_ids = metal_row_cat(&target_ids, &immutable_ids)?;
                                origin_rows = metal_row_cat(
                                    &origin_rows,
                                    &Tensor::zeros(immutable_count, DType::I64, device)
                                        .map_err(candle_error)?,
                                )?;
                                origin_commands = metal_row_cat(
                                    &origin_commands,
                                    &Tensor::zeros(immutable_count, DType::U32, device)
                                        .map_err(candle_error)?,
                                )?;
                                creation_groups = metal_row_cat(
                                    &creation_groups,
                                    &Tensor::zeros(immutable_count, DType::U32, device)
                                        .map_err(candle_error)?,
                                )?;
                            }

                            let local_mask = Self::metal_row_bound_local_node_mask(
                                program,
                                &command.labels,
                                expected,
                                &local_nodes,
                                device,
                            )?;
                            let local_selected = selected_positions(
                                &local_mask,
                                local_nodes.len(),
                                device,
                                cancellation,
                            )?;
                            let local_ids_host = local_nodes
                                .iter()
                                .map(|candidate| candidate.entity.target_id)
                                .collect::<Vec<_>>();
                            let local_origins = local_nodes
                                .iter()
                                .map(|candidate| {
                                    let origin = candidate.entity.created_by.ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "Metal dynamic local node lost creation provenance",
                                        )
                                    })?;
                                    let row = origin
                                        .work_row
                                        .checked_add(1)
                                        .and_then(|row| i64::try_from(row).ok())
                                        .ok_or_else(|| {
                                            Error::new(
                                                ErrorCode::ResultBudgetExceeded,
                                                "Metal dynamic local-node origin exceeds i64",
                                            )
                                        })?;
                                    Ok((row, u32::from(origin.command)))
                                })
                                .collect::<Result<Vec<_>>>()?;
                            let local_id_bank = metal_row_create_u64_bits(
                                &local_ids_host,
                                &state.source_rows,
                                device,
                            )?;
                            let local_origin_bank = if local_origins.is_empty() {
                                state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                            } else {
                                Tensor::from_slice(
                                    &local_origins
                                        .iter()
                                        .map(|(row, _)| *row)
                                        .collect::<Vec<_>>(),
                                    local_origins.len(),
                                    device,
                                )
                                .map_err(candle_error)?
                            };
                            let local_command_bank = if local_origins.is_empty() {
                                Tensor::zeros(0, DType::U32, device).map_err(candle_error)?
                            } else {
                                Tensor::from_slice(
                                    &local_origins
                                        .iter()
                                        .map(|(_, command)| *command)
                                        .collect::<Vec<_>>(),
                                    local_origins.len(),
                                    device,
                                )
                                .map_err(candle_error)?
                            };
                            let selected_local_ids =
                                device_index_select(&local_id_bank, &local_selected, 0)?;
                            let selected_local_origins =
                                device_index_select(&local_origin_bank, &local_selected, 0)?;
                            let selected_local_commands =
                                device_index_select(&local_command_bank, &local_selected, 0)?;
                            let (relative_parents, local_positions) =
                                metal_row_create_cartesian_indices(
                                    &group_parents,
                                    &local_selected,
                                    device,
                                )?;
                            let local_parents =
                                device_index_select(&group_parents, &relative_parents, 0)?;
                            let local_ids =
                                device_index_select(&selected_local_ids, &local_positions, 0)?;
                            let local_origin_rows =
                                device_index_select(&selected_local_origins, &local_positions, 0)?;
                            let local_origin_commands =
                                device_index_select(&selected_local_commands, &local_positions, 0)?;
                            let local_count = local_parents.elem_count();
                            if local_count != 0 {
                                has_local = true;
                                parents = metal_row_cat(&parents, &local_parents)?;
                                dense_rows = metal_row_cat(
                                    &dense_rows,
                                    &Tensor::full(super::RESIDENT_NULL_ROW, local_count, device)
                                        .map_err(candle_error)?,
                                )?;
                                target_ids = metal_row_cat(&target_ids, &local_ids)?;
                                origin_rows = metal_row_cat(&origin_rows, &local_origin_rows)?;
                                origin_commands =
                                    metal_row_cat(&origin_commands, &local_origin_commands)?;
                                creation_groups = metal_row_cat(
                                    &creation_groups,
                                    &Tensor::zeros(local_count, DType::U32, device)
                                        .map_err(candle_error)?,
                                )?;
                            }

                            if immutable_count == 0 && local_count == 0 {
                                has_local = true;
                                let created_offset =
                                    u64::try_from(created.len()).map_err(|_| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal dynamic node-MERGE creation count exceeds u64",
                                        )
                                    })?;
                                let target_id = request
                                    .first_node_id
                                    .checked_add(node_id_offset)
                                    .and_then(|id| id.checked_add(created_offset))
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal dynamic node-MERGE identity overflows u64",
                                        )
                                    })?;
                                let group_id = u32::try_from(created.len() + 1).map_err(|_| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal dynamic node-MERGE group exceeds u32",
                                    )
                                })?;
                                let group_count = group_parents.elem_count();
                                parents = metal_row_cat(&parents, &group_parents)?;
                                dense_rows = metal_row_cat(
                                    &dense_rows,
                                    &Tensor::full(super::RESIDENT_NULL_ROW, group_count, device)
                                        .map_err(candle_error)?,
                                )?;
                                target_ids = metal_row_cat(
                                    &target_ids,
                                    &Tensor::full(
                                        i64::from_ne_bytes(target_id.to_ne_bytes()),
                                        group_count,
                                        device,
                                    )
                                    .map_err(candle_error)?,
                                )?;
                                origin_rows = metal_row_cat(
                                    &origin_rows,
                                    &Tensor::zeros(group_count, DType::I64, device)
                                        .map_err(candle_error)?,
                                )?;
                                origin_commands = metal_row_cat(
                                    &origin_commands,
                                    &Tensor::full(u32::from(command_index), group_count, device)
                                        .map_err(candle_error)?,
                                )?;
                                creation_groups = metal_row_cat(
                                    &creation_groups,
                                    &Tensor::full(group_id, group_count, device)
                                        .map_err(candle_error)?,
                                )?;
                                created.push((group_id, target_id, expected.clone()));
                            }
                        }

                        let output_count = parents.elem_count();
                        if output_count > 1 {
                            let order =
                                scalable_stable_argsort(&parents, true, device, cancellation)?;
                            parents = device_index_select(&parents, &order, 0)?;
                            dense_rows = device_index_select(&dense_rows, &order, 0)?;
                            target_ids = device_index_select(&target_ids, &order, 0)?;
                            origin_rows = device_index_select(&origin_rows, &order, 0)?;
                            origin_commands = device_index_select(&origin_commands, &order, 0)?;
                            creation_groups = device_index_select(&creation_groups, &order, 0)?;
                        }
                        let output_count_u64 = u64::try_from(output_count).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal dynamic node-MERGE output exceeds u64",
                            )
                        })?;
                        if output_count_u64 > body.capacities.maximum_rows {
                            return Err(Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal dynamic node MERGE exceeded admitted row bytes",
                            ));
                        }

                        let creation_group_host =
                            creation_groups.to_vec1::<u32>().map_err(candle_error)?;
                        let mut origin_rows_host =
                            origin_rows.to_vec1::<i64>().map_err(candle_error)?;
                        let mut creation_leaders = BTreeMap::<u32, usize>::new();
                        for (row, group) in creation_group_host.iter().copied().enumerate() {
                            if group != 0 {
                                creation_leaders.entry(group).or_insert(row);
                            }
                        }
                        for (row, group) in creation_group_host.iter().copied().enumerate() {
                            if group == 0 {
                                continue;
                            }
                            let leader =
                                creation_leaders.get(&group).copied().ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal dynamic node-MERGE creation group lost its leader",
                                    )
                                })?;
                            origin_rows_host[row] = i64::try_from(leader)
                                .ok()
                                .and_then(|leader| leader.checked_add(1))
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal dynamic node-MERGE leader exceeds i64",
                                    )
                                })?;
                        }
                        origin_rows =
                            Tensor::from_slice(&origin_rows_host, origin_rows_host.len(), device)
                                .map_err(candle_error)?;
                        let created_by = has_local.then_some(MetalRowCreateDeviceOrigin {
                            command: command_index,
                            command_rows: Some(origin_commands.clone()),
                            work_rows: origin_rows.clone(),
                        });
                        let parent_host = parents.to_vec1::<i64>().map_err(candle_error)?;
                        metal_row_create_select_parents(&mut state, &parents)?;
                        let source_host =
                            state.source_rows.to_vec1::<i64>().map_err(candle_error)?;
                        let dense_host = dense_rows.to_vec1::<u32>().map_err(candle_error)?;
                        let id_host = metal_row_create_decode_u64_bits(&target_ids)?;
                        let origin_host = created_by
                            .as_ref()
                            .map(metal_row_bound_decode_origins)
                            .transpose()?
                            .unwrap_or_else(|| vec![None; output_count]);
                        if parent_host.len() != output_count
                            || source_host.len() != output_count
                            || dense_host.len() != output_count
                            || id_host.len() != output_count
                            || origin_host.len() != output_count
                        {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal dynamic node-MERGE columns changed cardinality",
                            ));
                        }

                        let mut stage_rows = Vec::with_capacity(output_count);
                        for row in 0..output_count {
                            let parent_work_row =
                                u64::try_from(parent_host[row]).map_err(|_| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal dynamic node-MERGE emitted a negative parent",
                                    )
                                })?;
                            let source_row = u64::try_from(source_host[row]).map_err(|_| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal dynamic node-MERGE emitted a negative source",
                                )
                            })?;
                            let node = ResidentRowCreateEntity {
                                kind: EntityKind::Node,
                                target_id: id_host[row],
                                dense_row: (dense_host[row] != super::RESIDENT_NULL_ROW)
                                    .then_some(dense_host[row]),
                                created_by: origin_host[row],
                            };
                            stage_rows.push(ResidentRowBoundNodeLineageEntry {
                                parent_work_row,
                                source_row,
                                node,
                            });
                        }
                        for (group, target_id, expected) in created {
                            let leader =
                                creation_leaders.get(&group).copied().ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal dynamic node-MERGE creation lost its output leader",
                                    )
                                })?;
                            let work_row = u64::try_from(leader).map_err(|_| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal dynamic node-MERGE leader exceeds u64",
                                )
                            })?;
                            let source_row = u64::try_from(source_host[leader]).map_err(|_| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal dynamic node-MERGE leader has a negative source",
                                )
                            })?;
                            let origin = ResidentRowCreateEntityOrigin {
                                command: command_index,
                                work_row,
                            };
                            intents.push(ResidentRowMutationWorkIntent {
                                work_row,
                                source_row,
                                command: command_index,
                                target_id,
                                action: ResidentRowMutationWorkIntentAction::CreateNode {
                                    labels: command.labels.clone(),
                                    properties: expected.clone(),
                                },
                            });
                            local_nodes.push(MetalBoundLocalNode {
                                labels: command.labels.clone(),
                                properties: expected,
                                entity: ResidentRowCreateEntity {
                                    kind: EntityKind::Node,
                                    target_id,
                                    dense_row: None,
                                    created_by: Some(origin),
                                },
                                deleted: false,
                            });
                        }
                        let created_count_u64 =
                            u64::try_from(creation_leaders.len()).map_err(|_| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal dynamic node-MERGE creation count exceeds u64",
                                )
                            })?;
                        if state.entities[usize::from(command.output_entity)]
                            .replace(MetalRowCreateDeviceEntity {
                                kind: EntityKind::Node,
                                target_ids,
                                dense_rows: has_immutable.then_some(dense_rows),
                                created_by,
                            })
                            .is_some()
                        {
                            return Err(Error::internal(
                                "Metal dynamic node MERGE rebound an entity slot",
                            ));
                        }
                        node_lineage.push(ResidentRowBoundNodeLineageStage {
                            command: command_index,
                            rows: stage_rows,
                        });
                        command_receipts.push((
                            input_count_u64,
                            output_count_u64,
                            created_count_u64,
                        ));
                        probe_occurrences = probe_occurrences
                            .checked_add(output_count_u64)
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal dynamic node-MERGE probe count overflowed",
                                )
                            })?;
                        node_id_offset =
                            node_id_offset
                                .checked_add(created_count_u64)
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal dynamic node-MERGE identity offset overflowed",
                                    )
                                })?;
                        continue;
                    }

                    let expected = command
                        .properties
                        .iter()
                        .map(|property| {
                            let value = Self::metal_row_bound_uniform_property_value(
                                request,
                                program,
                                &state.source_rows,
                                property,
                            )?
                            .ok_or_else(|| {
                                Error::internal(
                                    "Metal bound node MERGE lost a non-empty property source",
                                )
                            })?;
                            if matches!(value, ScalarValue::Null) {
                                return Err(Error::new(
                                    ErrorCode::QueryType,
                                    "MERGE node key properties cannot be NULL",
                                ));
                            }
                            Ok(super::ResidentMutationIntentEntry {
                                property_name: property.property_name,
                                value,
                            })
                        })
                        .collect::<Result<Vec<_>>>()?;

                    let candidates = self.metal_row_bound_node_candidates(
                        program,
                        &command.labels,
                        request.read_layers,
                        device,
                        cancellation,
                    )?;
                    let candidates = metal_row_bound_live_candidates(
                        &candidates,
                        &delete_state.node_tombstones,
                        device,
                        cancellation,
                    )?;
                    node_dependency_candidates.push(candidates.clone());
                    let (all_parents, all_candidate_positions) =
                        metal_row_create_cartesian_indices(
                            &state.source_rows,
                            &candidates,
                            device,
                        )?;
                    let all_dense = device_index_select(&candidates, &all_candidate_positions, 0)?;
                    let all_sources = device_index_select(&state.source_rows, &all_parents, 0)?;
                    let property_mask = self.metal_row_bound_properties_mask(
                        request,
                        program,
                        EntityKind::Node,
                        &command.properties,
                        &all_sources,
                        &all_dense,
                        device,
                        cancellation,
                    )?;
                    let immutable_selected = selected_positions(
                        &property_mask,
                        all_dense.elem_count(),
                        device,
                        cancellation,
                    )?;
                    let immutable_parents =
                        device_index_select(&all_parents, &immutable_selected, 0)?;
                    let immutable_dense = device_index_select(&all_dense, &immutable_selected, 0)?;
                    let candidate_ids = if candidates.elem_count() == 0 {
                        state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        device_index_select(
                            self.node_entity_ids.as_ref().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound node MERGE non-empty graph lost node IDs",
                                )
                            })?,
                            &candidates,
                            0,
                        )?
                    };
                    let all_ids = device_index_select(&candidate_ids, &all_candidate_positions, 0)?;
                    let immutable_ids = device_index_select(&all_ids, &immutable_selected, 0)?;

                    let local_mask = Self::metal_row_bound_local_node_mask(
                        program,
                        &command.labels,
                        &expected,
                        &local_nodes,
                        device,
                    )?;
                    let local_selected =
                        selected_positions(&local_mask, local_nodes.len(), device, cancellation)?;
                    let local_ids_host = local_nodes
                        .iter()
                        .map(|candidate| candidate.entity.target_id)
                        .collect::<Vec<_>>();
                    let local_origin_rows = local_nodes
                        .iter()
                        .map(|candidate| {
                            let origin = candidate.entity.created_by.ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound local node lost creation provenance",
                                )
                            })?;
                            origin
                                .work_row
                                .checked_add(1)
                                .and_then(|row| i64::try_from(row).ok())
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound local-node origin exceeds i64",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let local_origin_commands = local_nodes
                        .iter()
                        .map(|candidate| {
                            candidate
                                .entity
                                .created_by
                                .map(|origin| u32::from(origin.command))
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal bound local node lost its origin command",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let local_id_bank =
                        metal_row_create_u64_bits(&local_ids_host, &state.source_rows, device)?;
                    let local_origin_bank = if local_origin_rows.is_empty() {
                        state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        Tensor::from_slice(&local_origin_rows, local_origin_rows.len(), device)
                            .map_err(candle_error)?
                    };
                    let local_command_bank = if local_origin_commands.is_empty() {
                        Tensor::zeros(0, DType::U32, device).map_err(candle_error)?
                    } else {
                        Tensor::from_slice(
                            &local_origin_commands,
                            local_origin_commands.len(),
                            device,
                        )
                        .map_err(candle_error)?
                    };
                    let selected_local_ids =
                        device_index_select(&local_id_bank, &local_selected, 0)?;
                    let selected_local_origins =
                        device_index_select(&local_origin_bank, &local_selected, 0)?;
                    let selected_local_commands =
                        device_index_select(&local_command_bank, &local_selected, 0)?;
                    let (local_parents, local_candidate_positions) =
                        metal_row_create_cartesian_indices(
                            &state.source_rows,
                            &local_selected,
                            device,
                        )?;
                    let local_ids =
                        device_index_select(&selected_local_ids, &local_candidate_positions, 0)?;
                    let local_origins = device_index_select(
                        &selected_local_origins,
                        &local_candidate_positions,
                        0,
                    )?;
                    let local_commands = device_index_select(
                        &selected_local_commands,
                        &local_candidate_positions,
                        0,
                    )?;
                    let local_dense = if local_parents.elem_count() == 0 {
                        candidates.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        Tensor::full(super::RESIDENT_NULL_ROW, local_parents.elem_count(), device)
                            .map_err(candle_error)?
                    };

                    let immutable_origins =
                        Tensor::zeros(immutable_parents.elem_count(), DType::I64, device)
                            .map_err(candle_error)?;
                    let immutable_commands =
                        Tensor::zeros(immutable_parents.elem_count(), DType::U32, device)
                            .map_err(candle_error)?;
                    let mut parents = metal_row_cat(&immutable_parents, &local_parents)?;
                    let mut dense_rows = metal_row_cat(&immutable_dense, &local_dense)?;
                    let mut target_ids = metal_row_cat(&immutable_ids, &local_ids)?;
                    let mut origin_rows = metal_row_cat(&immutable_origins, &local_origins)?;
                    let mut origin_commands = metal_row_cat(&immutable_commands, &local_commands)?;

                    let matched_parent_rows = if parents.elem_count() == 0 {
                        candidates.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        parents.to_dtype(DType::U32).map_err(candle_error)?
                    };
                    let zero_mask = scatter_counts(&matched_parent_rows, input_count, device)?
                        .eq(0_u32)
                        .and_then(|mask| mask.to_dtype(DType::U8))
                        .map_err(candle_error)?;
                    let zero_parents =
                        selected_positions(&zero_mask, input_count, device, cancellation)?;
                    let zero_count = zero_parents.elem_count();
                    if zero_count != 0 && zero_count != input_count {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound node MERGE changed a constant-key candidate set across parents",
                        ));
                    }
                    let created_count = usize::from(zero_count != 0);
                    if zero_count != 0 {
                        if parents.elem_count() != 0 {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound node MERGE mixed zero and matched constant-key parents",
                            ));
                        }
                        let target_id = request
                            .first_node_id
                            .checked_add(node_id_offset)
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal bound node MERGE identity overflows u64",
                                )
                            })?;
                        let created_parents =
                            zero_parents.to_dtype(DType::I64).map_err(candle_error)?;
                        let created_dense =
                            Tensor::full(super::RESIDENT_NULL_ROW, zero_count, device)
                                .map_err(candle_error)?;
                        let created_ids = Tensor::full(
                            i64::from_ne_bytes(target_id.to_ne_bytes()),
                            zero_count,
                            device,
                        )
                        .map_err(candle_error)?;
                        let leader = zero_parents
                            .narrow(0, 0, 1)
                            .and_then(|leader| leader.to_dtype(DType::I64))
                            .and_then(|leader| leader.broadcast_add(&Tensor::new(1_i64, device)?))
                            .map_err(candle_error)?;
                        let created_origins = Tensor::ones(zero_count, DType::I64, device)
                            .and_then(|rows| rows.broadcast_mul(&leader))
                            .map_err(candle_error)?;
                        let created_commands =
                            Tensor::full(u32::from(command_index), zero_count, device)
                                .map_err(candle_error)?;
                        parents = metal_row_cat(&parents, &created_parents)?;
                        dense_rows = metal_row_cat(&dense_rows, &created_dense)?;
                        target_ids = metal_row_cat(&target_ids, &created_ids)?;
                        origin_rows = metal_row_cat(&origin_rows, &created_origins)?;
                        origin_commands = metal_row_cat(&origin_commands, &created_commands)?;
                    }

                    let output_count = parents.elem_count();
                    if output_count > 1 {
                        let order = scalable_stable_argsort(&parents, true, device, cancellation)?;
                        parents = device_index_select(&parents, &order, 0)?;
                        dense_rows = device_index_select(&dense_rows, &order, 0)?;
                        target_ids = device_index_select(&target_ids, &order, 0)?;
                        origin_rows = device_index_select(&origin_rows, &order, 0)?;
                        origin_commands = device_index_select(&origin_commands, &order, 0)?;
                    }
                    let output_count_u64 = u64::try_from(output_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound node MERGE output exceeds u64",
                        )
                    })?;
                    if output_count_u64 > body.capacities.maximum_rows {
                        return Err(Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound node MERGE exceeded admitted row bytes",
                        ));
                    }
                    let created_count_u64 = u64::try_from(created_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound node MERGE creation count exceeds u64",
                        )
                    })?;
                    let has_immutable = immutable_parents.elem_count() != 0;
                    let has_local = local_parents.elem_count() != 0 || zero_count != 0;
                    let created_by = has_local.then_some(MetalRowCreateDeviceOrigin {
                        command: command_index,
                        command_rows: Some(origin_commands.clone()),
                        work_rows: origin_rows.clone(),
                    });
                    let parent_host = parents.to_vec1::<i64>().map_err(candle_error)?;
                    metal_row_create_select_parents(&mut state, &parents)?;
                    let source_host = state.source_rows.to_vec1::<i64>().map_err(candle_error)?;
                    let dense_host = dense_rows.to_vec1::<u32>().map_err(candle_error)?;
                    let id_host = metal_row_create_decode_u64_bits(&target_ids)?;
                    let origin_host = created_by
                        .as_ref()
                        .map(metal_row_bound_decode_origins)
                        .transpose()?;
                    let merge_property_target_ids = body
                        .merge_property_sets
                        .iter()
                        .filter(|descriptor| descriptor.trigger_command == command_index)
                        .map(|descriptor| {
                            let ids = if descriptor.target_entity == command.output_entity {
                                id_host.clone()
                            } else {
                                let target = state.entities[usize::from(descriptor.target_entity)]
                                    .as_ref()
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "Metal conditional node-MERGE SET target disappeared",
                                        )
                                    })?;
                                metal_row_create_decode_u64_bits(&target.target_ids)?
                            };
                            let values = self.metal_row_bound_merge_property_values(
                                request, program, &state, descriptor, device,
                            )?;
                            Ok((descriptor, ids, values))
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let mut stage_rows = Vec::with_capacity(output_count);
                    let mut created_local = None;
                    for row in 0..output_count {
                        let parent_work_row = u64::try_from(parent_host[row]).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound node MERGE emitted negative parent lineage",
                            )
                        })?;
                        let source_row = u64::try_from(source_host[row]).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound node MERGE emitted negative source lineage",
                            )
                        })?;
                        let origin = origin_host.as_ref().and_then(|origins| origins[row]);
                        let node = ResidentRowCreateEntity {
                            kind: EntityKind::Node,
                            target_id: id_host[row],
                            dense_row: (dense_host[row] != super::RESIDENT_NULL_ROW)
                                .then_some(dense_host[row]),
                            created_by: origin,
                        };
                        stage_rows.push(ResidentRowBoundNodeLineageEntry {
                            parent_work_row,
                            source_row,
                            node,
                        });
                        if origin.is_some_and(|origin| {
                            origin.command == command_index
                                && origin.work_row == u64::try_from(row).unwrap_or(u64::MAX)
                        }) {
                            if created_local.is_some() || created_count != 1 {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound node MERGE emitted multiple creation leaders",
                                ));
                            }
                            intents.push(ResidentRowMutationWorkIntent {
                                work_row: u64::try_from(row).map_err(|_| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound node MERGE leader exceeds u64",
                                    )
                                })?,
                                source_row,
                                command: command_index,
                                target_id: node.target_id,
                                action: ResidentRowMutationWorkIntentAction::CreateNode {
                                    labels: command.labels.clone(),
                                    properties: expected.clone(),
                                },
                            });
                            created_local = Some(MetalBoundLocalNode {
                                labels: command.labels.clone(),
                                properties: expected.clone(),
                                entity: node,
                                deleted: false,
                            });
                        }
                        let work_row = u64::try_from(row).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal conditional node-MERGE SET row exceeds u64",
                            )
                        })?;
                        let created_here = origin
                            == Some(ResidentRowCreateEntityOrigin {
                                command: command_index,
                                work_row,
                            });
                        for (descriptor, target_ids, values) in &merge_property_target_ids {
                            let fires = match descriptor.branch {
                                super::ResidentRowBoundMergeBranch::Create => created_here,
                                super::ResidentRowBoundMergeBranch::Match => !created_here,
                            };
                            if fires {
                                merge_property_actions.push(
                                    super::ResidentRowBoundMergePropertyAction {
                                        branch: descriptor.branch,
                                        trigger_command: command_index,
                                        work_row,
                                        source_row,
                                        target_entity: descriptor.target_entity,
                                        target_id: target_ids[row],
                                        property_name: descriptor.property_name,
                                        value: values[row].clone(),
                                    },
                                );
                            }
                        }
                        for descriptor in body
                            .merge_label_sets
                            .iter()
                            .filter(|descriptor| descriptor.trigger_command == command_index)
                        {
                            if descriptor.target_entity != command.output_entity {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal conditional node-MERGE label target escaped its sealed trigger",
                                ));
                            }
                            let fires = match descriptor.branch {
                                super::ResidentRowBoundMergeBranch::Create => created_here,
                                super::ResidentRowBoundMergeBranch::Match => !created_here,
                            };
                            if fires {
                                merge_label_actions.push(super::ResidentRowBoundMergeLabelAction {
                                    branch: descriptor.branch,
                                    trigger_command: command_index,
                                    work_row,
                                    source_row,
                                    target_entity: descriptor.target_entity,
                                    target_id: id_host[row],
                                    labels: descriptor.labels.clone(),
                                });
                            }
                        }
                    }
                    if created_count == 1 && created_local.is_none() {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound node MERGE omitted its device creation leader",
                        ));
                    }
                    if let Some(created) = created_local {
                        local_nodes.push(created);
                    }
                    if state.entities[usize::from(command.output_entity)]
                        .replace(MetalRowCreateDeviceEntity {
                            kind: EntityKind::Node,
                            target_ids,
                            dense_rows: has_immutable.then_some(dense_rows),
                            created_by,
                        })
                        .is_some()
                    {
                        return Err(Error::internal(
                            "Metal bound node MERGE rebound an entity slot",
                        ));
                    }
                    node_lineage.push(ResidentRowBoundNodeLineageStage {
                        command: command_index,
                        rows: stage_rows,
                    });
                    command_receipts.push((input_count_u64, output_count_u64, created_count_u64));
                    probe_occurrences = probe_occurrences
                        .checked_add(output_count_u64)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound probe occurrence count overflows u64",
                            )
                        })?;
                    node_id_offset =
                        node_id_offset
                            .checked_add(created_count_u64)
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal bound node MERGE identity offset overflows u64",
                                )
                            })?;
                }
                (
                    ResidentRowCreateCommand::CreateRelationship(command),
                    super::ResidentRowBoundRelationshipCommand::MatchRelationship {
                        direction, ..
                    }
                    | super::ResidentRowBoundRelationshipCommand::MergeRelationship { direction },
                ) => {
                    let is_merge = matches!(
                        semantics,
                        super::ResidentRowBoundRelationshipCommand::MergeRelationship { .. }
                    );
                    let input_count = state.source_rows.elem_count();
                    let local_relationships_before = local_relationships.len();
                    let source_entity = state.entities[usize::from(command.source_entity)]
                        .as_ref()
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::GpuAdmissionFailure,
                                "Metal bound relationship source endpoint is not bound",
                            )
                        })?;
                    let target_entity = state.entities[usize::from(command.target_entity)]
                        .as_ref()
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::GpuAdmissionFailure,
                                "Metal bound relationship target endpoint is not bound",
                            )
                        })?;
                    let source_dense =
                        metal_row_bound_node_dense_rows(source_entity, input_count, device)?;
                    let target_dense =
                        metal_row_bound_node_dense_rows(target_entity, input_count, device)?;
                    if input_count == 0 {
                        let empty_ids = state.source_rows.narrow(0, 0, 0).map_err(candle_error)?;
                        let empty_dense =
                            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
                        if state.entities[usize::from(command.output_entity)]
                            .replace(MetalRowCreateDeviceEntity {
                                kind: EntityKind::Relationship,
                                target_ids: empty_ids,
                                dense_rows: Some(empty_dense),
                                created_by: None,
                            })
                            .is_some()
                        {
                            return Err(Error::internal(
                                "Metal bound relationship rebound an entity slot",
                            ));
                        }
                        relationship_lineage.push(
                            super::ResidentRowBoundRelationshipLineageStage {
                                command: command_index,
                                rows: Vec::new(),
                            },
                        );
                        command_receipts.push((0, 0, 0));
                        continue;
                    }
                    let source_live = metal_row_bound_live_node_rows(
                        source_entity,
                        &source_dense,
                        &delete_state.node_tombstones,
                        &local_nodes,
                        device,
                        cancellation,
                    )?;
                    let target_live = metal_row_bound_live_node_rows(
                        target_entity,
                        &target_dense,
                        &delete_state.node_tombstones,
                        &local_nodes,
                        device,
                        cancellation,
                    )?;
                    let endpoint_live = source_live
                        .broadcast_mul(&target_live)
                        .map_err(candle_error)?;
                    let live_parent_positions =
                        selected_positions(&endpoint_live, input_count, device, cancellation)?;
                    let live_parent_count = live_parent_positions.elem_count();
                    let live_source_rows =
                        device_index_select(&state.source_rows, &live_parent_positions, 0)?;
                    let dynamic_values = value_bank.as_ref().filter(|_| {
                        body.schedule.property_bindings.iter().any(|binding| {
                            binding.command == command_index
                                && matches!(
                                    binding.source,
                                    super::ResidentRowBoundPropertyBindingSource::ValueSlot(_)
                                )
                        })
                    });
                    let dynamic_properties = body
                        .schedule
                        .property_bindings
                        .iter()
                        .filter(|binding| binding.command == command_index)
                        .map(|binding| binding.property_name)
                        .collect::<BTreeSet<_>>();
                    let expected = if live_parent_count == 0 {
                        Vec::new()
                    } else {
                        command
                            .properties
                            .iter()
                            .filter(|property| {
                                !dynamic_properties.contains(&property.property_name)
                            })
                            .map(|property| {
                                let value = Self::metal_row_bound_uniform_property_value(
                                    request,
                                    program,
                                    &live_source_rows,
                                    property,
                                )?
                                .ok_or_else(|| {
                                    Error::internal(
                                        "Metal bound relationship lost a non-empty property source",
                                    )
                                })?;
                                if is_merge && matches!(value, ScalarValue::Null) {
                                    return Err(Error::new(
                                        ErrorCode::QueryType,
                                        "MERGE relationship key properties cannot be NULL",
                                    ));
                                }
                                Ok(super::ResidentMutationIntentEntry {
                                    property_name: property.property_name,
                                    value,
                                })
                            })
                            .collect::<Result<Vec<_>>>()?
                    };
                    let allowed_types = match semantics {
                        super::ResidentRowBoundRelationshipCommand::MatchRelationship {
                            relationship_types,
                            ..
                        } => relationship_types.as_slice(),
                        super::ResidentRowBoundRelationshipCommand::MergeRelationship {
                            ..
                        } => std::slice::from_ref(&command.relationship_type),
                        _ => unreachable!("relationship arm has relationship semantics"),
                    };
                    let immutable_possible =
                        source_entity.dense_rows.is_some() && target_entity.dense_rows.is_some();
                    if dynamic_values.is_some()
                        && (immutable_possible || !local_relationships.is_empty())
                    {
                        return Err(Error::new(
                            ErrorCode::GpuAdmissionFailure,
                            "Metal dynamic relationship key escaped its terminal local-endpoint proof",
                        ));
                    }
                    let candidates = if live_parent_count == 0 || !immutable_possible {
                        self.outgoing_offsets
                            .narrow(0, 0, 0)
                            .map_err(candle_error)?
                    } else {
                        self.metal_row_bound_relationship_candidates(
                            program,
                            command,
                            semantics,
                            request.read_layers,
                            device,
                            cancellation,
                        )?
                    };
                    let candidates = metal_row_bound_live_candidates(
                        &candidates,
                        &delete_state.relationship_tombstones,
                        device,
                        cancellation,
                    )?;
                    if live_parent_count != 0 && immutable_possible {
                        let dependency_semantics =
                            super::ResidentRowBoundRelationshipCommand::MatchRelationship {
                                direction: *direction,
                                relationship_types: Vec::new(),
                            };
                        let dependency_candidates = self.metal_row_bound_relationship_candidates(
                            program,
                            command,
                            &dependency_semantics,
                            request.read_layers,
                            device,
                            cancellation,
                        )?;
                        relationship_dependency_candidates.push(metal_row_bound_live_candidates(
                            &dependency_candidates,
                            &delete_state.relationship_tombstones,
                            device,
                            cancellation,
                        )?);
                    }
                    let candidate_count = candidates.elem_count();
                    let (all_parents, all_candidate_positions) =
                        metal_row_create_cartesian_indices(
                            &state.source_rows,
                            &candidates,
                            device,
                        )?;
                    let cartesian_pair_count = all_parents.elem_count();
                    let live_pairs = device_index_select(&endpoint_live, &all_parents, 0)?;
                    let live_pair_positions = selected_positions(
                        &live_pairs,
                        cartesian_pair_count,
                        device,
                        cancellation,
                    )?;
                    let all_parents = device_index_select(&all_parents, &live_pair_positions, 0)?;
                    let all_candidate_positions =
                        device_index_select(&all_candidate_positions, &live_pair_positions, 0)?;
                    let all_dense = device_index_select(&candidates, &all_candidate_positions, 0)?;
                    let all_sources = device_index_select(&state.source_rows, &all_parents, 0)?;
                    let pair_count = all_dense.elem_count();
                    let direction_mask = if pair_count == 0 {
                        Tensor::zeros(0, DType::U8, device).map_err(candle_error)?
                    } else {
                        let edge_sources = self.edge_sources.as_ref().ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound relationship graph lost its source rows",
                            )
                        })?;
                        let edge_targets = self.edge_targets.as_ref().ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound relationship graph lost its target rows",
                            )
                        })?;
                        let candidate_sources = device_index_select(edge_sources, &candidates, 0)?;
                        let candidate_targets = device_index_select(edge_targets, &candidates, 0)?;
                        let actual_sources =
                            device_index_select(&candidate_sources, &all_candidate_positions, 0)?;
                        let actual_targets =
                            device_index_select(&candidate_targets, &all_candidate_positions, 0)?;
                        let left = device_index_select(&source_dense, &all_parents, 0)?;
                        let right = device_index_select(&target_dense, &all_parents, 0)?;
                        let forward = actual_sources
                            .eq(&left)
                            .and_then(|mask| mask.to_dtype(DType::U8))
                            .and_then(|mask| {
                                mask.broadcast_mul(&actual_targets.eq(&right)?.to_dtype(DType::U8)?)
                            })
                            .map_err(candle_error)?;
                        match direction {
                            super::ResidentRowBoundRelationshipDirection::Directed => forward,
                            super::ResidentRowBoundRelationshipDirection::Undirected => {
                                let reverse = actual_sources
                                    .eq(&right)
                                    .and_then(|mask| mask.to_dtype(DType::U8))
                                    .and_then(|mask| {
                                        mask.broadcast_mul(
                                            &actual_targets.eq(&left)?.to_dtype(DType::U8)?,
                                        )
                                    })
                                    .map_err(candle_error)?;
                                forward
                                    .broadcast_add(&reverse)
                                    .and_then(|mask| mask.gt(0_u8))
                                    .and_then(|mask| mask.to_dtype(DType::U8))
                                    .map_err(candle_error)?
                            }
                        }
                    };
                    let property_mask = self.metal_row_bound_properties_mask(
                        request,
                        program,
                        EntityKind::Relationship,
                        &command.properties,
                        &all_sources,
                        &all_dense,
                        device,
                        cancellation,
                    )?;
                    let pair_mask = direction_mask
                        .broadcast_mul(&property_mask)
                        .map_err(candle_error)?;
                    let selected_pairs =
                        selected_positions(&pair_mask, pair_count, device, cancellation)?;
                    let immutable_parents = device_index_select(&all_parents, &selected_pairs, 0)?;
                    let immutable_dense = device_index_select(&all_dense, &selected_pairs, 0)?;
                    let edge_ids = self.edge_entity_ids.as_ref();
                    let candidate_ids = if candidate_count == 0 {
                        state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        device_index_select(
                            edge_ids.ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound-relationship non-empty graph lost edge IDs",
                                )
                            })?,
                            &candidates,
                            0,
                        )?
                    };
                    let all_ids = device_index_select(&candidate_ids, &all_candidate_positions, 0)?;
                    let immutable_ids = device_index_select(&all_ids, &selected_pairs, 0)?;
                    let immutable_count = immutable_dense.elem_count();

                    let local_candidate_count = local_relationships.len();
                    let local_mask = Self::metal_row_bound_local_relationship_mask(
                        &expected,
                        allowed_types,
                        &local_relationships,
                        device,
                    )?;
                    let local_selected = selected_positions(
                        &local_mask,
                        local_candidate_count,
                        device,
                        cancellation,
                    )?;
                    let local_ids_host = local_relationships
                        .iter()
                        .map(|candidate| candidate.entity.target_id)
                        .collect::<Vec<_>>();
                    let local_source_ids_host = local_relationships
                        .iter()
                        .map(|candidate| candidate.source_node_id)
                        .collect::<Vec<_>>();
                    let local_target_ids_host = local_relationships
                        .iter()
                        .map(|candidate| candidate.target_node_id)
                        .collect::<Vec<_>>();
                    let local_origin_rows_host = local_relationships
                        .iter()
                        .map(|candidate| {
                            candidate
                                .entity
                                .created_by
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal bound local relationship lost creation provenance",
                                    )
                                })?
                                .work_row
                                .checked_add(1)
                                .and_then(|row| i64::try_from(row).ok())
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound local relationship origin exceeds i64",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let local_origin_commands_host = local_relationships
                        .iter()
                        .map(|candidate| {
                            candidate
                                .entity
                                .created_by
                                .map(|origin| u32::from(origin.command))
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal bound local relationship lost its origin command",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let local_id_bank =
                        metal_row_create_u64_bits(&local_ids_host, &state.source_rows, device)?;
                    let local_source_bank = metal_row_create_u64_bits(
                        &local_source_ids_host,
                        &state.source_rows,
                        device,
                    )?;
                    let local_target_bank = metal_row_create_u64_bits(
                        &local_target_ids_host,
                        &state.source_rows,
                        device,
                    )?;
                    let local_origin_bank = if local_origin_rows_host.is_empty() {
                        state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        Tensor::from_slice(
                            &local_origin_rows_host,
                            local_origin_rows_host.len(),
                            device,
                        )
                        .map_err(candle_error)?
                    };
                    let local_command_bank = if local_origin_commands_host.is_empty() {
                        Tensor::zeros(0, DType::U32, device).map_err(candle_error)?
                    } else {
                        Tensor::from_slice(
                            &local_origin_commands_host,
                            local_origin_commands_host.len(),
                            device,
                        )
                        .map_err(candle_error)?
                    };
                    let selected_local_ids =
                        device_index_select(&local_id_bank, &local_selected, 0)?;
                    let selected_local_sources =
                        device_index_select(&local_source_bank, &local_selected, 0)?;
                    let selected_local_targets =
                        device_index_select(&local_target_bank, &local_selected, 0)?;
                    let selected_local_origins =
                        device_index_select(&local_origin_bank, &local_selected, 0)?;
                    let selected_local_commands =
                        device_index_select(&local_command_bank, &local_selected, 0)?;
                    let (local_all_parents, local_candidate_positions) =
                        metal_row_create_cartesian_indices(
                            &state.source_rows,
                            &local_selected,
                            device,
                        )?;
                    let local_cartesian_pair_count = local_all_parents.elem_count();
                    let live_local_pairs =
                        device_index_select(&endpoint_live, &local_all_parents, 0)?;
                    let live_local_pair_positions = selected_positions(
                        &live_local_pairs,
                        local_cartesian_pair_count,
                        device,
                        cancellation,
                    )?;
                    let local_all_parents =
                        device_index_select(&local_all_parents, &live_local_pair_positions, 0)?;
                    let local_candidate_positions = device_index_select(
                        &local_candidate_positions,
                        &live_local_pair_positions,
                        0,
                    )?;
                    let local_pair_count = local_all_parents.elem_count();
                    let local_pair_mask = if local_pair_count == 0 {
                        Tensor::zeros(0, DType::U8, device).map_err(candle_error)?
                    } else {
                        let actual_sources = device_index_select(
                            &selected_local_sources,
                            &local_candidate_positions,
                            0,
                        )?;
                        let actual_targets = device_index_select(
                            &selected_local_targets,
                            &local_candidate_positions,
                            0,
                        )?;
                        let expected_sources =
                            device_index_select(&source_entity.target_ids, &local_all_parents, 0)?;
                        let expected_targets =
                            device_index_select(&target_entity.target_ids, &local_all_parents, 0)?;
                        let forward = actual_sources
                            .eq(&expected_sources)
                            .and_then(|matches| matches.to_dtype(DType::U8))
                            .and_then(|matches| {
                                matches.broadcast_mul(
                                    &actual_targets.eq(&expected_targets)?.to_dtype(DType::U8)?,
                                )
                            })
                            .map_err(candle_error)?;
                        match direction {
                            super::ResidentRowBoundRelationshipDirection::Directed => forward,
                            super::ResidentRowBoundRelationshipDirection::Undirected => {
                                let reverse = actual_sources
                                    .eq(&expected_targets)
                                    .and_then(|matches| matches.to_dtype(DType::U8))
                                    .and_then(|matches| {
                                        matches.broadcast_mul(
                                            &actual_targets
                                                .eq(&expected_sources)?
                                                .to_dtype(DType::U8)?,
                                        )
                                    })
                                    .map_err(candle_error)?;
                                forward
                                    .broadcast_add(&reverse)
                                    .and_then(|matches| matches.gt(0_u8))
                                    .and_then(|matches| matches.to_dtype(DType::U8))
                                    .map_err(candle_error)?
                            }
                        }
                    };
                    let local_pairs = selected_positions(
                        &local_pair_mask,
                        local_pair_count,
                        device,
                        cancellation,
                    )?;
                    let local_parents = device_index_select(&local_all_parents, &local_pairs, 0)?;
                    let selected_local_positions =
                        device_index_select(&local_candidate_positions, &local_pairs, 0)?;
                    let local_ids =
                        device_index_select(&selected_local_ids, &selected_local_positions, 0)?;
                    let local_origins =
                        device_index_select(&selected_local_origins, &selected_local_positions, 0)?;
                    let local_commands = device_index_select(
                        &selected_local_commands,
                        &selected_local_positions,
                        0,
                    )?;
                    let local_count = local_parents.elem_count();
                    let local_dense = if local_count == 0 {
                        candidates.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        Tensor::full(super::RESIDENT_NULL_ROW, local_count, device)
                            .map_err(candle_error)?
                    };

                    let immutable_origins =
                        Tensor::zeros(immutable_count, DType::I64, device).map_err(candle_error)?;
                    let immutable_commands =
                        Tensor::zeros(immutable_count, DType::U32, device).map_err(candle_error)?;
                    let mut parents = metal_row_cat(&immutable_parents, &local_parents)?;
                    let mut dense_rows = metal_row_cat(&immutable_dense, &local_dense)?;
                    let mut target_ids = metal_row_cat(&immutable_ids, &local_ids)?;
                    let mut origin_rows = metal_row_cat(&immutable_origins, &local_origins)?;
                    let mut origin_commands = metal_row_cat(&immutable_commands, &local_commands)?;

                    let mut zero_count = 0_usize;
                    let mut created_count = 0_usize;
                    if is_merge {
                        let matched_parent_rows = if parents.elem_count() == 0 {
                            candidates.narrow(0, 0, 0).map_err(candle_error)?
                        } else {
                            parents.to_dtype(DType::U32).map_err(candle_error)?
                        };
                        let zero_mask = scatter_counts(&matched_parent_rows, input_count, device)?
                            .eq(0_u32)
                            .and_then(|mask| mask.to_dtype(DType::U8))
                            .and_then(|mask| mask.broadcast_mul(&endpoint_live))
                            .map_err(candle_error)?;
                        let zero_parents =
                            selected_positions(&zero_mask, input_count, device, cancellation)?;
                        zero_count = zero_parents.elem_count();
                        if zero_count != 0 {
                            let zero_sources =
                                device_index_select(&source_entity.target_ids, &zero_parents, 0)?;
                            let zero_targets =
                                device_index_select(&target_entity.target_ids, &zero_parents, 0)?;
                            let groups = if let Some(bank) = dynamic_values {
                                let value_rows = state.value_rows.as_ref().ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal dynamic relationship rows lost their value lineage",
                                    )
                                })?;
                                let zero_value_rows =
                                    device_index_select(value_rows, &zero_parents, 0)?;
                                metal_row_bound_dynamic_zero_groups(
                                    bank,
                                    &zero_parents,
                                    &zero_sources,
                                    &zero_targets,
                                    &zero_value_rows,
                                    *direction,
                                    device,
                                    cancellation,
                                )?
                            } else {
                                metal_row_bound_relationship_zero_groups(
                                    &zero_parents,
                                    &zero_sources,
                                    &zero_targets,
                                    *direction,
                                    device,
                                    cancellation,
                                )?
                            };
                            created_count = groups.group_count;
                            let created_count_u64 = u64::try_from(created_count).map_err(|_| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal bound relationship creation count exceeds u64",
                                )
                            })?;
                            let base = first_edge_id
                                .checked_add(relationship_id_offset)
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound relationship identity base overflows u64",
                                    )
                                })?;
                            base.checked_add(created_count_u64).ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal bound relationship identity range overflows u64",
                                )
                            })?;
                            let created_parents =
                                groups.parents.to_dtype(DType::I64).map_err(candle_error)?;
                            let created_dense =
                                Tensor::full(super::RESIDENT_NULL_ROW, zero_count, device)
                                    .map_err(candle_error)?;
                            let created_ids = groups
                                .ordinals
                                .sub(
                                    &Tensor::ones(zero_count, DType::I64, device)
                                        .map_err(candle_error)?,
                                )
                                .and_then(|ordinals| {
                                    ordinals.broadcast_add(&Tensor::new(
                                        i64::from_ne_bytes(base.to_ne_bytes()),
                                        device,
                                    )?)
                                })
                                .map_err(candle_error)?;

                            // Each MERGE parent has at least one output after its zero lane is
                            // appended. The inclusive parent-count prefix is therefore the
                            // one-based final work row of a zero parent's sole output. Gathering it
                            // through each equal-key leader preserves exact creation provenance.
                            let output_parents = metal_row_cat(&parents, &created_parents)?;
                            let output_parent_rows =
                                output_parents.to_dtype(DType::U32).map_err(candle_error)?;
                            let output_count = output_parents.elem_count();
                            let parent_counts =
                                scatter_counts(&output_parent_rows, input_count, device)?
                                    .to_dtype(DType::I64)
                                    .map_err(candle_error)?;
                            let parent_prefix = bounded_inclusive_scan_i64(
                                &parent_counts,
                                i64::try_from(output_count).map_err(|_| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound relationship output count exceeds i64",
                                    )
                                })?,
                                device,
                                cancellation,
                            )?;
                            let created_origins =
                                device_index_select(&parent_prefix, &groups.leader_parents, 0)?;
                            let created_commands =
                                Tensor::full(u32::from(command_index), zero_count, device)
                                    .map_err(candle_error)?;
                            parents = output_parents;
                            dense_rows = metal_row_cat(&dense_rows, &created_dense)?;
                            target_ids = metal_row_cat(&target_ids, &created_ids)?;
                            origin_rows = metal_row_cat(&origin_rows, &created_origins)?;
                            origin_commands = metal_row_cat(&origin_commands, &created_commands)?;
                        }
                    }

                    let output_count = parents.elem_count();
                    if output_count > 1 {
                        let order = scalable_stable_argsort(&parents, true, device, cancellation)?;
                        parents = device_index_select(&parents, &order, 0)?;
                        dense_rows = device_index_select(&dense_rows, &order, 0)?;
                        target_ids = device_index_select(&target_ids, &order, 0)?;
                        origin_rows = device_index_select(&origin_rows, &order, 0)?;
                        origin_commands = device_index_select(&origin_commands, &order, 0)?;
                    }
                    let output_count_u64 = u64::try_from(output_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound relationship output exceeds u64",
                        )
                    })?;
                    if output_count_u64 > body.capacities.maximum_rows {
                        return Err(Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound relationship expansion exceeded admitted row bytes",
                        ));
                    }
                    let created_count_u64 = u64::try_from(created_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound relationship creation count exceeds u64",
                        )
                    })?;
                    let created_by = (local_count != 0 || zero_count != 0).then_some(
                        MetalRowCreateDeviceOrigin {
                            command: command_index,
                            command_rows: Some(origin_commands.clone()),
                            work_rows: origin_rows.clone(),
                        },
                    );

                    let parent_host = if output_count == 0 {
                        Vec::new()
                    } else {
                        parents.to_vec1::<i64>().map_err(candle_error)?
                    };
                    metal_row_create_select_parents(&mut state, &parents)?;
                    let source_host = if output_count == 0 {
                        Vec::new()
                    } else {
                        state.source_rows.to_vec1::<i64>().map_err(candle_error)?
                    };
                    let dense_host = if output_count == 0 {
                        Vec::new()
                    } else {
                        dense_rows.to_vec1::<u32>().map_err(candle_error)?
                    };
                    let id_host = metal_row_create_decode_u64_bits(&target_ids)?;
                    let origin_host = created_by
                        .as_ref()
                        .map(metal_row_bound_decode_origins)
                        .transpose()?;
                    let source_node_ids = metal_row_create_decode_u64_bits(
                        &state.entities[usize::from(command.source_entity)]
                            .as_ref()
                            .ok_or_else(|| {
                                Error::internal(
                                    "Metal bound relationship source entity disappeared",
                                )
                            })?
                            .target_ids,
                    )?;
                    let target_node_ids = metal_row_create_decode_u64_bits(
                        &state.entities[usize::from(command.target_entity)]
                            .as_ref()
                            .ok_or_else(|| {
                                Error::internal(
                                    "Metal bound relationship target entity disappeared",
                                )
                            })?
                            .target_ids,
                    )?;
                    let merge_property_target_ids = body
                        .merge_property_sets
                        .iter()
                        .filter(|descriptor| descriptor.trigger_command == command_index)
                        .map(|descriptor| {
                            let ids = if descriptor.target_entity == command.output_entity {
                                id_host.clone()
                            } else if descriptor.target_entity == command.source_entity {
                                source_node_ids.clone()
                            } else if descriptor.target_entity == command.target_entity {
                                target_node_ids.clone()
                            } else {
                                let target = state.entities[usize::from(descriptor.target_entity)]
                                    .as_ref()
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "Metal conditional relationship-MERGE SET target disappeared",
                                        )
                                })?;
                                metal_row_create_decode_u64_bits(&target.target_ids)?
                            };
                            let values = self.metal_row_bound_merge_property_values(
                                request, program, &state, descriptor, device,
                            )?;
                            Ok((descriptor, ids, values))
                        })
                        .collect::<Result<Vec<_>>>()?;
                    // The canonical value arena crosses to the host only after device grouping
                    // has selected creation leaders. Non-leader duplicate rows never materialize
                    // a property value for intent construction.
                    let dynamic_value_rows = if dynamic_values.is_some() {
                        state
                            .value_rows
                            .as_ref()
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal dynamic relationship output lost value lineage",
                                )
                            })?
                            .to_vec1::<u32>()
                            .map_err(candle_error)?
                    } else {
                        Vec::new()
                    };
                    let dynamic_packet = if let Some(bank) = dynamic_values
                        && created_count != 0
                    {
                        Some(
                            bank.packet
                                .to_vec1::<i64>()
                                .map_err(candle_error)?
                                .into_iter()
                                .map(|word| word as u64)
                                .collect::<Vec<_>>(),
                        )
                    } else {
                        None
                    };
                    let mut stage_rows = Vec::with_capacity(output_count);
                    for row in 0..output_count {
                        let parent_work_row = u64::try_from(parent_host[row]).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound relationship emitted negative parent lineage",
                            )
                        })?;
                        let source_row = u64::try_from(source_host[row]).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound relationship emitted negative source lineage",
                            )
                        })?;
                        let origin = origin_host.as_ref().and_then(|origins| origins[row]);
                        let relationship = ResidentRowCreateEntity {
                            kind: EntityKind::Relationship,
                            target_id: id_host[row],
                            dense_row: (dense_host[row] != super::RESIDENT_NULL_ROW)
                                .then_some(dense_host[row]),
                            created_by: origin,
                        };
                        stage_rows.push(super::ResidentRowBoundRelationshipLineageEntry {
                            parent_work_row,
                            source_row,
                            relationship,
                        });
                        if let Some(origin) = origin.filter(|origin| {
                            origin.command == command_index
                                && origin.work_row == u64::try_from(row).unwrap_or(u64::MAX)
                        }) {
                            let properties = if let (Some(bank), Some(packet)) =
                                (dynamic_values, dynamic_packet.as_deref())
                            {
                                metal_row_bound_dynamic_properties(
                                    body,
                                    command_index,
                                    command,
                                    bank,
                                    packet,
                                    dynamic_value_rows[row],
                                    &expected,
                                )?
                            } else {
                                expected.clone()
                            };
                            local_relationships.push(MetalBoundLocalRelationship {
                                source_node_id: source_node_ids[row],
                                target_node_id: target_node_ids[row],
                                relationship_type: command.relationship_type,
                                properties: properties.clone(),
                                entity: relationship,
                                deleted: false,
                            });
                            intents.push(ResidentRowMutationWorkIntent {
                                work_row: origin.work_row,
                                source_row,
                                command: origin.command,
                                target_id: id_host[row],
                                action: ResidentRowMutationWorkIntentAction::CreateRelationship {
                                    relationship_type: command.relationship_type,
                                    source_node_id: source_node_ids[row],
                                    target_node_id: target_node_ids[row],
                                    properties,
                                },
                            });
                        }
                        let work_row = u64::try_from(row).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal conditional relationship-MERGE SET row exceeds u64",
                            )
                        })?;
                        let created_here = origin
                            == Some(ResidentRowCreateEntityOrigin {
                                command: command_index,
                                work_row,
                            });
                        for (descriptor, target_ids, values) in &merge_property_target_ids {
                            let fires = match descriptor.branch {
                                super::ResidentRowBoundMergeBranch::Create => created_here,
                                super::ResidentRowBoundMergeBranch::Match => !created_here,
                            };
                            if fires {
                                merge_property_actions.push(
                                    super::ResidentRowBoundMergePropertyAction {
                                        branch: descriptor.branch,
                                        trigger_command: command_index,
                                        work_row,
                                        source_row,
                                        target_entity: descriptor.target_entity,
                                        target_id: target_ids[row],
                                        property_name: descriptor.property_name,
                                        value: values[row].clone(),
                                    },
                                );
                            }
                        }
                    }
                    if local_relationships.len() - local_relationships_before != created_count {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound relationship creation leaders changed cardinality",
                        ));
                    }
                    if u64::try_from(intents.len()).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound relationship intents exceed u64",
                        )
                    })? > body.capacities.maximum_intents
                    {
                        return Err(Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound relationship intents exceeded admitted bytes",
                        ));
                    }
                    if state.entities[usize::from(command.output_entity)]
                        .replace(MetalRowCreateDeviceEntity {
                            kind: EntityKind::Relationship,
                            target_ids,
                            dense_rows: Some(dense_rows),
                            created_by,
                        })
                        .is_some()
                    {
                        return Err(Error::internal(
                            "Metal bound relationship rebound an entity slot",
                        ));
                    }
                    relationship_lineage.push(super::ResidentRowBoundRelationshipLineageStage {
                        command: command_index,
                        rows: stage_rows,
                    });
                    let input_count_u64 = u64::try_from(input_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal bound relationship input exceeds u64",
                        )
                    })?;
                    command_receipts.push((input_count_u64, output_count_u64, created_count_u64));
                    probe_occurrences = probe_occurrences
                        .checked_add(output_count_u64)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound probe occurrence count overflows u64",
                            )
                        })?;
                    relationship_id_offset = relationship_id_offset
                        .checked_add(created_count_u64)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound relationship identity offset overflows u64",
                            )
                        })?;
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal bound-relationship command alignment changed after validation",
                    ));
                }
            }
        }

        for stage_index in &delete_stages_before[program.commands.len()] {
            let stage = body.schedule.stages.get(*stage_index).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal trailing DELETE stage disappeared before execution",
                )
            })?;
            let super::ResidentRowBoundRelationshipStage::Delete {
                detach, targets, ..
            } = stage
            else {
                return Err(Error::internal(
                    "Metal trailing DELETE schedule index names a non-delete stage",
                ));
            };
            metal_row_bound_execute_delete_stage(
                self,
                u16::try_from(*stage_index).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal trailing DELETE stage index exceeds u16",
                    )
                })?,
                *detach,
                targets,
                &state,
                &mut delete_state,
                &mut local_nodes,
                &mut local_relationships,
                device,
                cancellation,
            )?;
        }

        ensure_not_cancelled(cancellation)?;
        let final_row_count = state.source_rows.elem_count();
        let final_rows_u64 = u64::try_from(final_row_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal post-MERGE OPTIONAL parent count exceeds u64",
            )
        })?;
        let mut optional_output_counts = BTreeMap::<usize, u64>::new();
        for (output_index, output) in body.outputs.iter().enumerate() {
            let super::ResidentRowBoundRelationshipOutput::CountOptionalUndirectedRelationships {
                source_entity,
                target_entity,
                ..
            } = output
            else {
                continue;
            };
            if !local_relationships.is_empty() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "post-MERGE OPTIONAL profile unexpectedly created a local relationship",
                ));
            }
            let candidates = if final_row_count == 0 {
                self.outgoing_offsets
                    .narrow(0, 0, 0)
                    .map_err(candle_error)?
            } else {
                self.metal_row_bound_visible_relationship_candidates(
                    request.read_layers,
                    device,
                    cancellation,
                )?
            };
            let candidates = metal_row_bound_live_candidates(
                &candidates,
                &delete_state.relationship_tombstones,
                device,
                cancellation,
            )?;
            relationship_dependency_candidates.push(candidates.clone());
            let source = state.entities[usize::from(*source_entity)]
                .as_ref()
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal post-MERGE OPTIONAL source binding disappeared",
                    )
                })?;
            let target = state.entities[usize::from(*target_entity)]
                .as_ref()
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal post-MERGE OPTIONAL target binding disappeared",
                    )
                })?;
            let source_rows = metal_row_bound_node_dense_rows(source, final_row_count, device)?;
            let target_rows = metal_row_bound_node_dense_rows(target, final_row_count, device)?;
            let (all_parents, candidate_positions) =
                metal_row_create_cartesian_indices(&state.source_rows, &candidates, device)?;
            let pair_count = all_parents.elem_count();
            let matched_parents = if pair_count == 0 {
                candidates.narrow(0, 0, 0).map_err(candle_error)?
            } else {
                let candidate_rows = device_index_select(&candidates, &candidate_positions, 0)?;
                let edge_sources = self.edge_sources.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal post-MERGE OPTIONAL lost relationship sources",
                    )
                })?;
                let edge_targets = self.edge_targets.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal post-MERGE OPTIONAL lost relationship targets",
                    )
                })?;
                let pair_sources = device_index_select(&source_rows, &all_parents, 0)?;
                let pair_targets = device_index_select(&target_rows, &all_parents, 0)?;
                let relationship_sources = device_index_select(edge_sources, &candidate_rows, 0)?;
                let relationship_targets = device_index_select(edge_targets, &candidate_rows, 0)?;
                let forward = pair_sources
                    .eq(&relationship_sources)
                    .and_then(|left| {
                        pair_targets
                            .eq(&relationship_targets)
                            .and_then(|right| left.broadcast_mul(&right))
                    })
                    .map_err(candle_error)?;
                let reverse = pair_sources
                    .eq(&relationship_targets)
                    .and_then(|left| {
                        pair_targets
                            .eq(&relationship_sources)
                            .and_then(|right| left.broadcast_mul(&right))
                    })
                    .map_err(candle_error)?;
                let matches = forward
                    .broadcast_add(&reverse)
                    .and_then(|matches| matches.gt(0_u8))
                    .and_then(|matches| matches.to_dtype(DType::U8))
                    .map_err(candle_error)?;
                let selected = selected_positions(&matches, pair_count, device, cancellation)?;
                device_index_select(&all_parents, &selected, 0)?
                    .to_dtype(DType::U32)
                    .map_err(candle_error)?
            };
            let match_counts = scatter_counts(&matched_parents, final_row_count, device)?;
            let null_extended = match_counts
                .eq(0_u32)
                .and_then(|zero| {
                    zero.where_cond(
                        &Tensor::ones(final_row_count, DType::U32, device)?,
                        &match_counts,
                    )
                })
                .and_then(|counts| counts.to_dtype(DType::I64))
                .and_then(|counts| counts.sum_all())
                .map_err(candle_error)?
                .to_scalar::<i64>()
                .map_err(candle_error)?;
            let optional_rows = u64::try_from(null_extended).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal post-MERGE OPTIONAL produced a negative row count",
                )
            })?;
            let maximum_candidates = body
                .capacities
                .resident_relationship_slots
                .checked_add(body.capacities.maximum_statement_local_relationships)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal post-MERGE OPTIONAL candidate bound overflows u64",
                    )
                })?
                .max(1);
            if final_rows_u64
                .checked_mul(maximum_candidates)
                .is_none_or(|maximum| optional_rows > maximum)
            {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal post-MERGE OPTIONAL exceeded admitted row capacity",
                ));
            }
            probe_occurrences = probe_occurrences
                .checked_add(final_rows_u64)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal post-MERGE OPTIONAL probe count overflows u64",
                    )
                })?;
            optional_output_counts.insert(output_index, optional_rows);
        }

        ensure_not_cancelled(cancellation)?;
        let materialize_dependencies = |candidates: &[Tensor]| -> Result<Vec<u32>> {
            let non_empty = candidates
                .iter()
                .filter(|candidate| candidate.elem_count() != 0)
                .collect::<Vec<_>>();
            if non_empty.is_empty() {
                return Ok(Vec::new());
            }
            let candidates = if non_empty.len() == 1 {
                non_empty[0].clone()
            } else {
                Tensor::cat(&non_empty, 0).map_err(candle_error)?
            };
            sorted_unique_u32_tensor(&candidates, device, cancellation)?
                .to_vec1::<u32>()
                .map_err(candle_error)
        };
        let mut read_dependencies = materialize_dependencies(&node_dependency_candidates)?
            .into_iter()
            .map(ResidentMutationReadDependency::Node)
            .collect::<Vec<_>>();
        read_dependencies.extend(
            materialize_dependencies(&relationship_dependency_candidates)?
                .into_iter()
                .map(ResidentMutationReadDependency::Relationship),
        );
        if u64::try_from(read_dependencies.len()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal bound dependency count exceeds u64",
            )
        })? > body.capacities.maximum_read_dependencies
        {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal bound dependency set exceeded admitted bytes",
            ));
        }

        let source_rows = if state.source_rows.elem_count() == 0 {
            Vec::new()
        } else {
            state.source_rows.to_vec1::<i64>().map_err(candle_error)?
        }
        .into_iter()
        .map(|source| {
            u64::try_from(source).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal bound final source lineage is negative",
                )
            })
        })
        .collect::<Result<Vec<_>>>()?;
        let lineage_columns = state
            .match_lineage
            .iter()
            .map(|lineage| {
                if lineage.elem_count() == 0 {
                    Ok(Vec::new())
                } else {
                    lineage.to_vec1::<u32>().map_err(candle_error)
                }
            })
            .collect::<Result<Vec<_>>>()?;
        let entity_columns = state
            .entities
            .iter()
            .map(|entity| {
                let entity = entity.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal bound final entity slot remained unbound",
                    )
                })?;
                Ok((
                    entity.kind,
                    metal_row_create_decode_u64_bits(&entity.target_ids)?,
                    entity
                        .dense_rows
                        .as_ref()
                        .map(|rows| {
                            if rows.elem_count() == 0 {
                                Ok(Vec::new())
                            } else {
                                rows.to_vec1::<u32>().map_err(candle_error)
                            }
                        })
                        .transpose()?,
                    entity
                        .created_by
                        .as_ref()
                        .map(metal_row_bound_decode_origins)
                        .transpose()?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        let row_count = source_rows.len();
        let mut work_rows = Vec::with_capacity(row_count);
        for (work_row, source_row) in source_rows.iter().copied().enumerate() {
            let work_row_u64 = u64::try_from(work_row).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound final work-row index exceeds u64",
                )
            })?;
            let entities = entity_columns
                .iter()
                .map(|(kind, ids, dense, created_by)| {
                    let dense_row = dense.as_ref().and_then(|rows| {
                        (rows[work_row] != super::RESIDENT_NULL_ROW).then_some(rows[work_row])
                    });
                    let created_by = created_by.as_ref().and_then(|origins| origins[work_row]);
                    if (dense_row.is_some() as u8) + (created_by.is_some() as u8) != 1 {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound final entity lane has invalid provenance",
                        ));
                    }
                    Ok(ResidentRowCreateEntity {
                        kind: *kind,
                        target_id: ids[work_row],
                        dense_row,
                        created_by,
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            work_rows.push(ResidentRowCreateWorkRow {
                work_row: work_row_u64,
                source_row,
                match_lineage: lineage_columns
                    .iter()
                    .map(|lineage| lineage[work_row])
                    .collect(),
                entities,
            });
        }

        let mut columns = Vec::with_capacity(body.outputs.len());
        for (output_index, output) in body.outputs.iter().enumerate() {
            let output_index = u16::try_from(output_index).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound output index exceeds u16",
                )
            })?;
            match output {
                super::ResidentRowBoundRelationshipOutput::CountRows { .. }
                | super::ResidentRowBoundRelationshipOutput::CountEntity { .. } => {
                    columns.push(super::ResidentRowBoundRelationshipColumn::Count {
                        output: output_index,
                        value: u64::try_from(row_count).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal bound aggregate count exceeds u64",
                            )
                        })?,
                    });
                }
                super::ResidentRowBoundRelationshipOutput::CountOptionalUndirectedRelationships {
                    ..
                } => {
                    columns.push(super::ResidentRowBoundRelationshipColumn::Count {
                        output: output_index,
                        value: optional_output_counts
                            .get(&usize::from(output_index))
                            .copied()
                            .ok_or_else(|| {
                                Error::internal(
                                    "Metal post-MERGE OPTIONAL output count disappeared",
                                )
                            })?,
                    });
                }
                super::ResidentRowBoundRelationshipOutput::Entity { entity, .. }
                | super::ResidentRowBoundRelationshipOutput::Labels { entity, .. }
                | super::ResidentRowBoundRelationshipOutput::Path {
                    relationship_entity: entity,
                    ..
                } => {
                    columns.push(super::ResidentRowBoundRelationshipColumn::Entity {
                        output: output_index,
                        values: work_rows
                            .iter()
                            .map(|row| {
                                row.entities
                                    .get(usize::from(*entity))
                                    .copied()
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "Metal bound entity output names a foreign slot",
                                        )
                                    })
                            })
                            .collect::<Result<Vec<_>>>()?,
                        work_rows: (0..row_count)
                            .map(|row| {
                                u64::try_from(row).map_err(|_| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound entity output lineage exceeds u64",
                                    )
                                })
                            })
                            .collect::<Result<Vec<_>>>()?,
                    });
                }
                super::ResidentRowBoundRelationshipOutput::Property {
                    entity,
                    property_name,
                    ..
                } => {
                    let entity_column =
                        state.entities[usize::from(*entity)]
                            .as_ref()
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound property output entity disappeared",
                                )
                            })?;
                    let mut values = self.metal_row_bound_output_property_values(
                        request,
                        program,
                        entity_column,
                        *property_name,
                        &state.source_rows,
                        device,
                    )?;
                    for action in merge_property_actions.iter().filter(|action| {
                        action.target_entity == *entity && action.property_name == *property_name
                    }) {
                        let row = usize::try_from(action.work_row).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal conditional MERGE SET output row exceeds host addressing",
                            )
                        })?;
                        let final_entity = work_rows
                            .get(row)
                            .and_then(|work_row| work_row.entities.get(usize::from(*entity)))
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal conditional MERGE SET output target disappeared",
                                )
                            })?;
                        if final_entity.target_id != action.target_id {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal conditional MERGE SET output target changed identity",
                            ));
                        }
                        values[row] = action.value.clone();
                    }
                    columns.push(super::ResidentRowBoundRelationshipColumn::Scalar {
                        output: output_index,
                        values,
                        work_rows: (0..row_count)
                            .map(|row| {
                                u64::try_from(row).map_err(|_| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal bound scalar output lineage exceeds u64",
                                    )
                                })
                            })
                            .collect::<Result<Vec<_>>>()?,
                    });
                }
            }
        }

        intents.sort_by_key(|intent| (intent.command, intent.work_row));
        merge_property_actions.sort_by_key(|action| {
            (
                action.trigger_command,
                action.work_row,
                action.branch,
                action.target_entity,
                action.property_name,
            )
        });
        merge_label_actions.sort_by(|left, right| {
            (
                left.trigger_command,
                left.work_row,
                left.branch,
                left.target_entity,
                left.labels.as_slice(),
            )
                .cmp(&(
                    right.trigger_command,
                    right.work_row,
                    right.branch,
                    right.target_entity,
                    right.labels.as_slice(),
                ))
        });
        let label_entries = merge_label_actions
            .iter()
            .try_fold(0_u64, |total, action| {
                total
                    .checked_add(u64::try_from(action.labels.len()).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal conditional MERGE label width exceeds u64",
                        )
                    })?)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal conditional MERGE label entries overflow u64",
                        )
                    })
            })?;
        if label_entries > body.capacities.maximum_label_entries {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal conditional MERGE labels exceeded admitted bytes",
            ));
        }
        delete_state.intents.sort_by_key(|intent| {
            (
                match intent.entity.kind {
                    EntityKind::Relationship => 0_u8,
                    EntityKind::Node => 1_u8,
                },
                intent.entity.target_id,
            )
        });
        if intents
            .len()
            .checked_add(delete_state.intents.len())
            .and_then(|count| u64::try_from(count).ok())
            .is_none_or(|count| count > body.capacities.maximum_intents)
        {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal bound mutation effects exceeded admitted intent bytes",
            ));
        }
        let completion = ResidentDeviceCompletion::Metal;
        let receipt =
            |obligation, input_cardinality, output_cardinality| ResidentExecutionReceipt {
                execution: request.execution,
                obligation,
                input_cardinality,
                output_cardinality,
                completion,
            };
        let final_rows = u64::try_from(row_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal bound final cardinality exceeds u64",
            )
        })?;
        let mut receipts = Vec::with_capacity(body.schedule.stages.len().saturating_mul(2) + 3);
        receipts.push(receipt(
            program.source_obligation,
            1,
            u64::try_from(source_count).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound source cardinality exceeds u64",
                )
            })?,
        ));
        for (stage_index, stage) in body.schedule.stages.iter().enumerate() {
            match stage {
                super::ResidentRowBoundRelationshipStage::Command {
                    command: command_index,
                } => {
                    let command = program
                        .commands
                        .get(usize::from(*command_index))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound receipt names a foreign command",
                            )
                        })?;
                    let semantics =
                        body.commands
                            .get(usize::from(*command_index))
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal bound receipt lost command semantics",
                                )
                            })?;
                    let (input, output, created) = command_receipts
                        .get(usize::from(*command_index))
                        .copied()
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound receipt lost command cardinality",
                            )
                        })?;
                    match (command, semantics) {
                        (
                            ResidentRowCreateCommand::MatchNode(command),
                            super::ResidentRowBoundRelationshipCommand::MatchNode { .. }
                            | super::ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites {
                                ..
                            },
                        ) => {
                            receipts.push(receipt(command.probe_obligation, input, output));
                        }
                        (
                            ResidentRowCreateCommand::CreateNode(command),
                            super::ResidentRowBoundRelationshipCommand::CreateNode
                            | super::ResidentRowBoundRelationshipCommand::MergeNode,
                        ) => {
                            receipts.push(receipt(command.expression_obligation, input, output));
                            receipts.push(receipt(command.effect_obligation, input, created));
                        }
                        (
                            ResidentRowCreateCommand::CreateRelationship(command),
                            super::ResidentRowBoundRelationshipCommand::CreateRelationship
                            | super::ResidentRowBoundRelationshipCommand::MatchRelationship {
                                ..
                            }
                            | super::ResidentRowBoundRelationshipCommand::MergeRelationship {
                                ..
                            },
                        ) => {
                            receipts.push(receipt(command.expression_obligation, input, output));
                            receipts.push(receipt(command.effect_obligation, input, created));
                        }
                        _ => {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound receipt command semantics changed after execution",
                            ));
                        }
                    }
                    for descriptor in body
                        .merge_property_sets
                        .iter()
                        .filter(|descriptor| descriptor.trigger_command == *command_index)
                    {
                        let effects = u64::try_from(
                            merge_property_actions
                                .iter()
                                .filter(|action| {
                                    action.trigger_command == *command_index
                                        && action.branch == descriptor.branch
                                        && action.target_entity == descriptor.target_entity
                                        && action.property_name == descriptor.property_name
                                })
                                .count(),
                        )
                        .map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal conditional MERGE SET count exceeds u64",
                            )
                        })?;
                        receipts.push(receipt(descriptor.rhs_obligation, effects, effects));
                        receipts.push(receipt(descriptor.effect_obligation, effects, effects));
                    }
                    for descriptor in body
                        .merge_label_sets
                        .iter()
                        .filter(|descriptor| descriptor.trigger_command == *command_index)
                    {
                        let effects = u64::try_from(
                            merge_label_actions
                                .iter()
                                .filter(|action| {
                                    action.trigger_command == *command_index
                                        && action.branch == descriptor.branch
                                        && action.target_entity == descriptor.target_entity
                                        && action.labels == descriptor.labels
                                })
                                .count(),
                        )
                        .map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal conditional MERGE label count exceeds u64",
                            )
                        })?;
                        receipts.push(receipt(descriptor.rhs_obligation, effects, effects));
                        receipts.push(receipt(descriptor.effect_obligation, effects, effects));
                    }
                }
                super::ResidentRowBoundRelationshipStage::Unwind { obligation, .. }
                | super::ResidentRowBoundRelationshipStage::Project { obligation, .. } => {
                    let stage_index = u16::try_from(stage_index).map_err(|_| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound value receipt stage exceeds u16",
                        )
                    })?;
                    let (input, output) =
                        value_receipts.get(&stage_index).copied().ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound value receipt cardinality disappeared",
                            )
                        })?;
                    receipts.push(receipt(*obligation, input, output));
                }
                super::ResidentRowBoundRelationshipStage::Delete {
                    targets,
                    effect_obligation,
                    ..
                } => {
                    let stage_index = u16::try_from(stage_index).map_err(|_| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound DELETE receipt stage exceeds u16",
                        )
                    })?;
                    let cardinalities =
                        delete_state.receipts.get(&stage_index).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal bound DELETE receipt cardinality disappeared",
                            )
                        })?;
                    if cardinalities.target_cardinalities.len() != targets.len() {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal bound DELETE target receipts lost schedule alignment",
                        ));
                    }
                    for (target, (input, output)) in
                        targets.iter().zip(&cardinalities.target_cardinalities)
                    {
                        receipts.push(receipt(target.rhs_obligation, *input, *output));
                    }
                    receipts.push(receipt(
                        *effect_obligation,
                        cardinalities.effect_cardinality.0,
                        cardinalities.effect_cardinality.1,
                    ));
                }
            }
        }
        for (output_index, output) in body.outputs.iter().enumerate() {
            let super::ResidentRowBoundRelationshipOutput::CountOptionalUndirectedRelationships {
                traversal_obligation,
                aggregate_obligation,
                ..
            } = output
            else {
                continue;
            };
            let optional_rows = optional_output_counts
                .get(&output_index)
                .copied()
                .ok_or_else(|| {
                    Error::internal("Metal post-MERGE OPTIONAL receipt count disappeared")
                })?;
            receipts.push(receipt(*traversal_obligation, final_rows, optional_rows));
            receipts.push(receipt(*aggregate_obligation, optional_rows, 1));
        }
        receipts.push(receipt(
            program.read_dependency_obligation,
            probe_occurrences,
            u64::try_from(read_dependencies.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal bound dependency receipt exceeds u64",
                )
            })?,
        ));
        receipts.push(receipt(
            program.final_relation_obligation,
            final_rows,
            match body.outputs.first() {
                None => 0,
                Some(output) if output.is_aggregate() => 1,
                Some(_) => final_rows,
            },
        ));
        ensure_not_cancelled(cancellation)?;
        Ok(
            ResidentRowMutationResult::completed_bound_relationship_merge(
                request,
                completion,
                intents,
                merge_property_actions,
                merge_label_actions,
                unwind_lineage,
                node_lineage,
                relationship_lineage,
                delete_state.intents,
                work_rows,
                read_dependencies,
                columns,
                receipts,
            ),
        )
    }

    #[allow(clippy::too_many_lines)]
    fn execute_row_create_metal(
        &self,
        device: &Device,
        request: &ResidentRowMutationRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentRowMutationResult> {
        let body = request.create_body().ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal row CREATE requires the discriminated CREATE body",
            )
        })?;
        let program = &body.program;
        let source_count = if request.input.is_empty() {
            1_usize
        } else {
            request.input.len()
        };
        let source_rows = (0..source_count)
            .map(|row| {
                i64::try_from(row).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row CREATE source lineage exceeds i64 tensor indexing",
                    )
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let mut state = MetalRowCreateDeviceState {
            source_rows: Tensor::from_slice(&source_rows, source_rows.len(), device)
                .map_err(candle_error)?,
            match_lineage: Vec::new(),
            entities: vec![None; usize::from(program.entity_slot_count)],
            value_rows: None,
        };
        let mut match_lineage = Vec::new();
        let mut match_receipts = BTreeMap::<u16, (u64, u64)>::new();
        let mut dependency_candidates = Vec::new();
        let mut match_occurrences = 0_u64;
        let mut node_id_offset = 0_u64;
        let mut relationship_id_offset = 0_u64;
        let first_edge_id = request.first_edge_id.ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal row CREATE relationship-ID origin disappeared",
            )
        })?;

        for (command_index, command) in program.commands.iter().enumerate() {
            ensure_not_cancelled(cancellation)?;
            let command_index = u16::try_from(command_index).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row CREATE command index exceeds u16",
                )
            })?;
            match command {
                ResidentRowCreateCommand::MatchNode(command) => {
                    let input_count = state.source_rows.elem_count();
                    let candidates = if input_count == 0 {
                        // MATCH over an empty incoming relation is not evaluated. Preserve the
                        // empty device relation and, critically, do not claim read dependencies
                        // for graph rows that could not contribute to any work row.
                        self.outgoing_offsets
                            .narrow(0, 0, 0)
                            .map_err(candle_error)?
                    } else {
                        self.metal_row_create_candidates(
                            program,
                            command,
                            request.read_layers,
                            device,
                            cancellation,
                        )?
                    };
                    let candidate_count = candidates.elem_count();
                    let output_count = input_count.checked_mul(candidate_count).ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal row CREATE MATCH Cartesian cardinality exceeds host address space",
                        )
                    })?;
                    if u64::try_from(output_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal row CREATE MATCH output exceeds u64",
                        )
                    })? > body.capacities.maximum_rows
                    {
                        return Err(Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal row CREATE MATCH exceeded its admitted actual-byte row capacity",
                        ));
                    }
                    let (parent_positions, candidate_positions) =
                        metal_row_create_cartesian_indices(
                            &state.source_rows,
                            &candidates,
                            device,
                        )?;
                    let expanded_dense = device_index_select(&candidates, &candidate_positions, 0)?;
                    let candidate_ids = if candidate_count == 0 {
                        state.source_rows.narrow(0, 0, 0).map_err(candle_error)?
                    } else {
                        let ids = self.node_entity_ids.as_ref().ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal row CREATE non-empty graph lost its stable node-ID tensor",
                            )
                        })?;
                        device_index_select(ids, &candidates, 0)?
                    };
                    let expanded_ids =
                        device_index_select(&candidate_ids, &candidate_positions, 0)?;
                    let expanded_sources =
                        device_index_select(&state.source_rows, &parent_positions, 0)?;
                    for lineage in &mut state.match_lineage {
                        *lineage = device_index_select(lineage, &parent_positions, 0)?;
                    }
                    for entity in state.entities.iter_mut().flatten() {
                        if entity.created_by.is_some() {
                            return Err(Error::new(
                                ErrorCode::GpuAdmissionFailure,
                                "Metal row CREATE does not admit an immutable MATCH after a write",
                            ));
                        }
                        entity.target_ids =
                            device_index_select(&entity.target_ids, &parent_positions, 0)?;
                        if let Some(dense) = &mut entity.dense_rows {
                            *dense = device_index_select(dense, &parent_positions, 0)?;
                        }
                    }
                    let stage_rows = if output_count == 0 {
                        Vec::new()
                    } else {
                        let parent_rows =
                            parent_positions.to_vec1::<i64>().map_err(candle_error)?;
                        let source_rows =
                            expanded_sources.to_vec1::<i64>().map_err(candle_error)?;
                        let dense_rows = expanded_dense.to_vec1::<u32>().map_err(candle_error)?;
                        parent_rows
                            .into_iter()
                            .zip(source_rows)
                            .zip(dense_rows)
                            .map(|((parent_work_row, source_row), node_dense)| {
                                Ok(ResidentRowCreateMatchLineageEntry {
                                    parent_work_row: u64::try_from(parent_work_row).map_err(
                                        |_| {
                                            Error::new(
                                                ErrorCode::CorruptStorage,
                                                "Metal row CREATE emitted a negative MATCH parent lineage",
                                            )
                                        },
                                    )?,
                                    source_row: u64::try_from(source_row).map_err(|_| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "Metal row CREATE emitted a negative source lineage",
                                        )
                                    })?,
                                    node_dense,
                                })
                            })
                            .collect::<Result<Vec<_>>>()?
                    };
                    let output_entity = usize::from(command.output_entity);
                    if state.entities[output_entity]
                        .replace(MetalRowCreateDeviceEntity {
                            kind: EntityKind::Node,
                            target_ids: expanded_ids,
                            dense_rows: Some(expanded_dense.clone()),
                            created_by: None,
                        })
                        .is_some()
                    {
                        return Err(Error::internal(
                            "Metal row CREATE MATCH rebound an entity slot",
                        ));
                    }
                    state.source_rows = expanded_sources;
                    state.match_lineage.push(expanded_dense);
                    dependency_candidates.push(candidates);
                    match_lineage.push(ResidentRowCreateMatchLineageStage {
                        command: command_index,
                        rows: stage_rows,
                    });
                    let input_count = u64::try_from(input_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal row CREATE MATCH input exceeds u64",
                        )
                    })?;
                    let output_count = u64::try_from(output_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal row CREATE MATCH output exceeds u64",
                        )
                    })?;
                    match_receipts.insert(command_index, (input_count, output_count));
                    match_occurrences =
                        match_occurrences.checked_add(output_count).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal row CREATE MATCH occurrence count overflows u64",
                            )
                        })?;
                }
                ResidentRowCreateCommand::CreateNode(command) => {
                    let row_count = state.source_rows.elem_count();
                    let ids = (0..row_count)
                        .map(|work_row| {
                            request
                                .first_node_id
                                .checked_add(node_id_offset)
                                .and_then(|id| id.checked_add(work_row as u64))
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal row CREATE node identity overflows u64",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let target_ids = metal_row_create_u64_bits(&ids, &state.source_rows, device)?;
                    let created_by = MetalRowCreateDeviceOrigin {
                        command: command_index,
                        command_rows: None,
                        work_rows: metal_row_create_identity_origins(
                            row_count,
                            &state.source_rows,
                            device,
                        )?,
                    };
                    if state.entities[usize::from(command.output_entity)]
                        .replace(MetalRowCreateDeviceEntity {
                            kind: EntityKind::Node,
                            target_ids,
                            dense_rows: None,
                            created_by: Some(created_by),
                        })
                        .is_some()
                    {
                        return Err(Error::internal(
                            "Metal row CREATE node rebound an entity slot",
                        ));
                    }
                    node_id_offset = node_id_offset
                        .checked_add(u64::try_from(row_count).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal row CREATE node count exceeds u64",
                            )
                        })?)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal row CREATE node identity offset overflows u64",
                            )
                        })?;
                }
                ResidentRowCreateCommand::CreateRelationship(command) => {
                    let row_count = state.source_rows.elem_count();
                    for endpoint in [command.source_entity, command.target_entity] {
                        if state
                            .entities
                            .get(usize::from(endpoint))
                            .and_then(Option::as_ref)
                            .is_none_or(|entity| entity.kind != EntityKind::Node)
                        {
                            return Err(Error::new(
                                ErrorCode::GpuAdmissionFailure,
                                "Metal row CREATE relationship endpoint is not a bound node column",
                            ));
                        }
                    }
                    let ids = (0..row_count)
                        .map(|work_row| {
                            first_edge_id
                                .checked_add(relationship_id_offset)
                                .and_then(|id| id.checked_add(work_row as u64))
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal row CREATE relationship identity overflows u64",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let target_ids = metal_row_create_u64_bits(&ids, &state.source_rows, device)?;
                    let created_by = MetalRowCreateDeviceOrigin {
                        command: command_index,
                        command_rows: None,
                        work_rows: metal_row_create_identity_origins(
                            row_count,
                            &state.source_rows,
                            device,
                        )?,
                    };
                    if state.entities[usize::from(command.output_entity)]
                        .replace(MetalRowCreateDeviceEntity {
                            kind: EntityKind::Relationship,
                            target_ids,
                            dense_rows: None,
                            created_by: Some(created_by),
                        })
                        .is_some()
                    {
                        return Err(Error::internal(
                            "Metal row CREATE relationship rebound an entity slot",
                        ));
                    }
                    relationship_id_offset = relationship_id_offset
                        .checked_add(u64::try_from(row_count).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal row CREATE relationship count exceeds u64",
                            )
                        })?)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal row CREATE relationship identity offset overflows u64",
                            )
                        })?;
                }
            }
        }

        ensure_not_cancelled(cancellation)?;
        let non_empty_dependency_candidates = dependency_candidates
            .iter()
            .filter(|candidate| candidate.elem_count() != 0)
            .collect::<Vec<_>>();
        let read_dependencies = if non_empty_dependency_candidates.is_empty() {
            Vec::new()
        } else {
            let candidates = if non_empty_dependency_candidates.len() == 1 {
                non_empty_dependency_candidates[0].clone()
            } else {
                Tensor::cat(&non_empty_dependency_candidates, 0).map_err(candle_error)?
            };
            sorted_unique_u32_tensor(&candidates, device, cancellation)?
                .to_vec1::<u32>()
                .map_err(candle_error)?
                .into_iter()
                .map(ResidentMutationReadDependency::Node)
                .collect()
        };
        let continuation_result =
            execute_metal_row_create_continuation(device, request, &state, cancellation)?;
        let source_rows = if state.source_rows.elem_count() == 0 {
            Vec::new()
        } else {
            state.source_rows.to_vec1::<i64>().map_err(candle_error)?
        }
        .into_iter()
        .map(|source| {
            u64::try_from(source).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row CREATE final source lineage is negative",
                )
            })
        })
        .collect::<Result<Vec<_>>>()?;
        let lineage_columns = state
            .match_lineage
            .iter()
            .map(|lineage| {
                if lineage.elem_count() == 0 {
                    Ok(Vec::new())
                } else {
                    lineage.to_vec1::<u32>().map_err(candle_error)
                }
            })
            .collect::<Result<Vec<_>>>()?;
        let entity_columns = state
            .entities
            .iter()
            .map(|entity| {
                let entity = entity.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal row CREATE final entity slot remained unbound",
                    )
                })?;
                Ok((
                    entity.kind,
                    metal_row_create_decode_u64_bits(&entity.target_ids)?,
                    entity
                        .dense_rows
                        .as_ref()
                        .map(|rows| {
                            if rows.elem_count() == 0 {
                                Ok(Vec::new())
                            } else {
                                rows.to_vec1::<u32>().map_err(candle_error)
                            }
                        })
                        .transpose()?,
                    entity
                        .created_by
                        .as_ref()
                        .map(metal_row_create_decode_origins)
                        .transpose()?,
                ))
            })
            .collect::<Result<Vec<_>>>()?;
        let row_count = source_rows.len();

        let mut work_rows = Vec::with_capacity(row_count);
        for (work_row, source_row) in source_rows.iter().copied().enumerate() {
            let work_row_u64 = u64::try_from(work_row).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row CREATE work-row lineage exceeds u64",
                )
            })?;
            work_rows.push(ResidentRowCreateWorkRow {
                work_row: work_row_u64,
                source_row,
                match_lineage: lineage_columns
                    .iter()
                    .map(|lineage| lineage[work_row])
                    .collect(),
                entities: entity_columns
                    .iter()
                    .map(|(kind, ids, dense, created_by)| ResidentRowCreateEntity {
                        kind: *kind,
                        target_id: ids[work_row],
                        dense_row: dense.as_ref().map(|rows| rows[work_row]),
                        created_by: created_by.as_ref().and_then(|(command, origins)| {
                            origins[work_row].map(|origin| ResidentRowCreateEntityOrigin {
                                command: *command,
                                work_row: origin,
                            })
                        }),
                    })
                    .collect(),
            });
        }

        let properties_for = |properties: &[super::ResidentRowCreateProperty], source_row: u64| {
            properties
                .iter()
                .map(|property| {
                    Ok(super::ResidentMutationIntentEntry {
                        property_name: property.property_name,
                        value: super::resident_row_create_property_value(
                            &request.input,
                            program,
                            source_row,
                            &property.value,
                        )?,
                    })
                })
                .collect::<Result<Vec<_>>>()
        };
        let is_creation_leader =
            |entity: u16, command: u16, work_row: usize, work_row_u64: u64| -> Result<bool> {
                let created_by = entity_columns
                    .get(usize::from(entity))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal row CREATE intent entity is outside the final relation",
                        )
                    })?
                    .3
                    .as_ref();
                let Some((origin_command, origins)) = created_by else {
                    return Ok(false);
                };
                if *origin_command != command {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal row CREATE entity origin names the wrong command",
                    ));
                }
                let origin = origins.get(work_row).copied().flatten();
                Ok(origin == Some(work_row_u64))
            };
        let mut intents = Vec::new();
        for (work_row, source_row) in source_rows.iter().copied().enumerate() {
            let work_row_u64 = u64::try_from(work_row).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row CREATE intent lineage exceeds u64",
                )
            })?;
            for (command_index, command) in program.commands.iter().enumerate() {
                let command_index = u16::try_from(command_index).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row CREATE intent command exceeds u16",
                    )
                })?;
                match command {
                    ResidentRowCreateCommand::MatchNode(_) => {}
                    ResidentRowCreateCommand::CreateNode(command) => {
                        if !is_creation_leader(
                            command.output_entity,
                            command_index,
                            work_row,
                            work_row_u64,
                        )? {
                            continue;
                        }
                        let target_id =
                            entity_columns[usize::from(command.output_entity)].1[work_row];
                        intents.push(ResidentRowMutationWorkIntent {
                            work_row: work_row_u64,
                            source_row,
                            command: command_index,
                            target_id,
                            action: ResidentRowMutationWorkIntentAction::CreateNode {
                                labels: command.labels.clone(),
                                properties: properties_for(&command.properties, source_row)?,
                            },
                        });
                    }
                    ResidentRowCreateCommand::CreateRelationship(command) => {
                        if !is_creation_leader(
                            command.output_entity,
                            command_index,
                            work_row,
                            work_row_u64,
                        )? {
                            continue;
                        }
                        let target_id =
                            entity_columns[usize::from(command.output_entity)].1[work_row];
                        let source_node_id =
                            entity_columns[usize::from(command.source_entity)].1[work_row];
                        let target_node_id =
                            entity_columns[usize::from(command.target_entity)].1[work_row];
                        intents.push(ResidentRowMutationWorkIntent {
                            work_row: work_row_u64,
                            source_row,
                            command: command_index,
                            target_id,
                            action: ResidentRowMutationWorkIntentAction::CreateRelationship {
                                relationship_type: command.relationship_type,
                                source_node_id,
                                target_node_id,
                                properties: properties_for(&command.properties, source_row)?,
                            },
                        });
                    }
                }
            }
        }

        let mut columns = Vec::with_capacity(program.outputs.len());
        for (output_index, output) in program.outputs.iter().enumerate() {
            let command = program
                .commands
                .iter()
                .find(|command| command.output_entity() == output.entity)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal row CREATE output entity command disappeared",
                    )
                })?;
            let properties = match command {
                ResidentRowCreateCommand::MatchNode(_) => {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal row CREATE cannot project a property from an immutable MATCH slot",
                    ));
                }
                ResidentRowCreateCommand::CreateNode(command) => &command.properties,
                ResidentRowCreateCommand::CreateRelationship(command) => &command.properties,
            };
            let source = properties
                .binary_search_by_key(&output.property_name, |property| property.property_name)
                .ok()
                .map(|index| &properties[index].value);
            let values = source_rows
                .iter()
                .map(|source_row| {
                    source.map_or(Ok(ScalarValue::Null), |source| {
                        super::resident_row_create_property_value(
                            &request.input,
                            program,
                            *source_row,
                            source,
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            columns.push(ResidentRowCreateScalarColumn {
                output: u16::try_from(output_index).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row CREATE output index exceeds u16",
                    )
                })?,
                values,
                work_rows: (0..row_count)
                    .map(|row| {
                        u64::try_from(row).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal row CREATE output lineage exceeds u64",
                            )
                        })
                    })
                    .collect::<Result<Vec<_>>>()?,
            });
        }

        let completion = ResidentDeviceCompletion::Metal;
        let receipt =
            |obligation, input_cardinality, output_cardinality| ResidentExecutionReceipt {
                execution: request.execution,
                obligation,
                input_cardinality,
                output_cardinality,
                completion,
            };
        let final_rows = u64::try_from(row_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row CREATE final cardinality exceeds u64",
            )
        })?;
        let mut receipts = Vec::with_capacity(program.obligations().len());
        receipts.push(receipt(
            program.source_obligation,
            1,
            u64::try_from(source_count).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row CREATE source cardinality exceeds u64",
                )
            })?,
        ));
        for (command_index, command) in program.commands.iter().enumerate() {
            let command_index = u16::try_from(command_index).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row CREATE receipt command exceeds u16",
                )
            })?;
            match command {
                ResidentRowCreateCommand::MatchNode(command) => {
                    let (input, output) =
                        match_receipts.get(&command_index).copied().ok_or_else(|| {
                            Error::internal(
                                "Metal row CREATE MATCH receipt cardinality disappeared",
                            )
                        })?;
                    receipts.push(receipt(command.probe_obligation, input, output));
                }
                ResidentRowCreateCommand::CreateNode(command) => {
                    receipts.push(receipt(
                        command.expression_obligation,
                        final_rows,
                        final_rows,
                    ));
                    receipts.push(receipt(command.effect_obligation, final_rows, final_rows));
                }
                ResidentRowCreateCommand::CreateRelationship(command) => {
                    receipts.push(receipt(
                        command.expression_obligation,
                        final_rows,
                        final_rows,
                    ));
                    receipts.push(receipt(command.effect_obligation, final_rows, final_rows));
                }
            }
        }
        receipts.push(receipt(
            program.read_dependency_obligation,
            match_occurrences,
            u64::try_from(read_dependencies.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row CREATE dependency count exceeds u64",
                )
            })?,
        ));
        let (continuation_lineage, final_relation) =
            if let Some((continuation_lineage, final_relation, continuation_receipts)) =
                continuation_result
            {
                receipts.extend(continuation_receipts);
                (continuation_lineage, Some(final_relation))
            } else {
                receipts.push(receipt(
                    program.final_relation_obligation,
                    final_rows,
                    final_rows,
                ));
                (Vec::new(), None)
            };
        ensure_not_cancelled(cancellation)?;
        Ok(ResidentRowMutationResult::completed_create(
            request,
            completion,
            intents,
            match_lineage,
            work_rows,
            read_dependencies,
            columns,
            continuation_lineage,
            final_relation,
            receipts,
        ))
    }

    pub fn metal_row_mutation_scratch_bytes(
        &self,
        request: &ResidentRowMutationRequest,
    ) -> Result<usize> {
        request.validate()?;
        self.validate_metal_row_mutation_generation(request)?;
        if request.bound_relationship_merge_body().is_some() {
            return self.metal_row_bound_relationship_scratch_bytes(request);
        }
        if request.create_body().is_some() {
            return Self::metal_row_create_scratch_bytes(request);
        }
        if request.match_merge_relationship.is_some() {
            return self.metal_row_match_merge_relationship_scratch_bytes(request);
        }
        let encoded = encode_metal_row_mutation_program(request)?;
        let graph = metal_row_mutation_graph_layout(self, request)?;
        let output = metal_row_mutation_output_layout(self, request)?;
        let overflow = || {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row-mutation actual-byte admission overflow",
            )
        };
        graph
            .word_count
            .checked_mul(16)
            .and_then(|bytes| {
                encoded
                    .words
                    .len()
                    .checked_mul(std::mem::size_of::<i64>())
                    .and_then(|program| bytes.checked_add(program))
            })
            .and_then(|bytes| {
                output
                    .word_count
                    .checked_mul(std::mem::size_of::<i64>())
                    .and_then(|packet| bytes.checked_add(packet))
            })
            .and_then(|bytes| bytes.checked_add(4_096))
            .ok_or_else(overflow)
    }

    pub fn execute_row_mutation_metal(
        &self,
        device: &Device,
        request: &ResidentRowMutationRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentRowMutationResult> {
        request.validate()?;
        self.validate_metal_row_mutation_generation(request)?;
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native row mutation requires the selected Metal device",
            ));
        };
        ensure_not_cancelled(cancellation)?;
        if request.bound_relationship_merge_body().is_some() {
            return self.execute_row_bound_relationship_merge_metal(device, request, cancellation);
        }
        if request.create_body().is_some() {
            return self.execute_row_create_metal(device, request, cancellation);
        }
        if request.match_merge_relationship.is_some() {
            return self.execute_row_match_merge_relationship_metal(device, request, cancellation);
        }
        let encoded = encode_metal_row_mutation_program(request)?;
        let graph_layout = metal_row_mutation_graph_layout(self, request)?;
        let output_layout = metal_row_mutation_output_layout(self, request)?;
        let graph = self.metal_row_mutation_graph_packet(device, request, graph_layout)?;
        let program_words = encoded
            .words
            .iter()
            .map(|word| *word as i64)
            .collect::<Vec<_>>();
        let program = Tensor::from_slice(&program_words, program_words.len(), device)
            .map_err(candle_error)?;
        let project = request.generation.project.0.as_u128();
        let catalog = metal_nullable_relation_hash_words(request.generation.catalog_generation);
        let fingerprint = metal_nullable_relation_hash_words(request.fingerprint.0);

        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        {
            let arguments = MetalRowMutationArgs {
                execution_high: request.execution.high,
                execution_low: request.execution.low,
                project_high: (project >> 64) as u64,
                project_low: project as u64,
                bookmark_term: request.generation.bookmark.term,
                bookmark_index: request.generation.bookmark.index,
                graph_revision: request.generation.graph_revision,
                layout_version: request.generation.layout_version,
                catalog_0: catalog[0],
                catalog_1: catalog[1],
                catalog_2: catalog[2],
                catalog_3: catalog[3],
                fingerprint_0: fingerprint[0],
                fingerprint_1: fingerprint[1],
                fingerprint_2: fingerprint[2],
                fingerprint_3: fingerprint[3],
                graph_word_count: graph_layout.word_count as u64,
                program_word_count: encoded.words.len() as u64,
                output_word_count: output_layout.word_count as u64,
                row_count: request.input.len() as u64,
                node_count: self.node_count as u64,
                label_count: request.program.merge.labels.len() as u64,
                output_count: request.program.outputs.len() as u64,
                receipt_count: request.obligations().len() as u64,
                first_node_id: request.first_node_id,
                layers: u64::from(request.read_layers.bits()),
                graph_node_active_base: graph_layout.node_active_base as u64,
                graph_node_layer_base: graph_layout.node_layer_base as u64,
                graph_node_id_base: graph_layout.node_id_base as u64,
                graph_label_base: graph_layout.label_base as u64,
                graph_property_value_base: graph_layout.property_value_base as u64,
                graph_property_validity_base: graph_layout.property_validity_base as u64,
                graph_dictionary_offset_base: graph_layout.dictionary_offset_base as u64,
                graph_dictionary_offset_count: graph_layout.dictionary_offset_count as u64,
                graph_dictionary_byte_base: graph_layout.dictionary_byte_base as u64,
                graph_dictionary_byte_count: graph_layout.dictionary_byte_count as u64,
                program_map_offset_base: encoded.map_offset_base as u64,
                program_entry_base: encoded.entry_base as u64,
                program_key_byte_base: encoded.key_byte_base as u64,
                program_key_byte_count: encoded.key_byte_count as u64,
                program_value_byte_base: encoded.value_byte_base as u64,
                program_value_byte_count: encoded.value_byte_count as u64,
                program_obligation_base: encoded.obligation_base as u64,
                program_output_source_base: encoded.output_source_base as u64,
                output_receipt_base: output_layout.receipt_base as u64,
                output_target_id_base: output_layout.target_id_base as u64,
                output_target_dense_base: output_layout.target_dense_base as u64,
                output_target_created_base: output_layout.target_created_base as u64,
                output_merge_ref_base: output_layout.merge_ref_base as u64,
                output_set_ref_base: output_layout.set_ref_base as u64,
                output_row_status_base: output_layout.row_status_base as u64,
                output_row_match_base: output_layout.row_match_base as u64,
                output_dependency_base: output_layout.dependency_base as u64,
                output_final_ref_base: output_layout.final_ref_base as u64,
                output_create_base: output_layout.create_base as u64,
                output_control_base: output_layout.control_base as u64,
            };
            let output = graph
                .apply_op2_no_bwd(
                    &program,
                    &MetalRowMutation {
                        arguments,
                        graph_storage_words: graph.elem_count(),
                    },
                )
                .map_err(candle_error)?;
            let words = output.to_vec1::<i64>().map_err(candle_error)?;
            ensure_not_cancelled(cancellation)?;
            return decode_metal_row_mutation_result(
                &words,
                request,
                &encoded,
                graph_layout,
                output_layout,
            );
        }
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        {
            let _ = (
                graph,
                program,
                encoded,
                graph_layout,
                output_layout,
                catalog,
                fingerprint,
            );
            Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal row-mutation kernels are unavailable on this build target",
            ))
        }
    }

    fn metal_row_match_merge_relationship_scratch_bytes(
        &self,
        request: &ResidentRowMutationRequest,
    ) -> Result<usize> {
        let encoded = encode_metal_row_match_merge_relationship_program(request)?;
        let graph = metal_row_match_merge_relationship_graph_layout(self, request)?;
        let output = metal_row_match_merge_relationship_output_layout(self, request)?;
        let overflow = || {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal MATCH/MERGE row-mutation actual-byte admission overflow",
            )
        };
        graph
            .word_count
            .checked_mul(16)
            .and_then(|bytes| {
                encoded
                    .words
                    .len()
                    .checked_mul(std::mem::size_of::<i64>())
                    .and_then(|program| bytes.checked_add(program))
            })
            .and_then(|bytes| {
                output
                    .word_count
                    .checked_mul(std::mem::size_of::<i64>())
                    .and_then(|packet| bytes.checked_add(packet))
            })
            .and_then(|bytes| bytes.checked_add(4_096))
            .ok_or_else(overflow)
    }

    fn execute_row_match_merge_relationship_metal(
        &self,
        device: &Device,
        request: &ResidentRowMutationRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentRowMutationResult> {
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native MATCH/MERGE row mutation requires the selected Metal device",
            ));
        };
        ensure_not_cancelled(cancellation)?;
        let extension = request.match_merge_relationship.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal generalized row mutation lost its immutable extension",
            )
        })?;
        let encoded = encode_metal_row_match_merge_relationship_program(request)?;
        let graph_layout = metal_row_match_merge_relationship_graph_layout(self, request)?;
        let output_layout = metal_row_match_merge_relationship_output_layout(self, request)?;
        let graph =
            self.metal_row_match_merge_relationship_graph_packet(device, request, graph_layout)?;
        let program_words = encoded
            .words
            .iter()
            .map(|word| *word as i64)
            .collect::<Vec<_>>();
        let program = Tensor::from_slice(&program_words, program_words.len(), device)
            .map_err(candle_error)?;
        let project = request.generation.project.0.as_u128();
        let catalog = metal_nullable_relation_hash_words(request.generation.catalog_generation);
        let fingerprint = metal_nullable_relation_hash_words(request.fingerprint.0);
        let relationship_token = extension
            .relationship_type_tokens
            .get(usize::from(extension.relationship.relationship_type))
            .copied()
            .flatten();

        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        {
            let arguments = MetalRowMatchMergeRelationshipArgs {
                execution_high: request.execution.high,
                execution_low: request.execution.low,
                project_high: (project >> 64) as u64,
                project_low: project as u64,
                bookmark_term: request.generation.bookmark.term,
                bookmark_index: request.generation.bookmark.index,
                graph_revision: request.generation.graph_revision,
                layout_version: request.generation.layout_version,
                catalog_0: catalog[0],
                catalog_1: catalog[1],
                catalog_2: catalog[2],
                catalog_3: catalog[3],
                fingerprint_0: fingerprint[0],
                fingerprint_1: fingerprint[1],
                fingerprint_2: fingerprint[2],
                fingerprint_3: fingerprint[3],
                graph_word_count: graph_layout.word_count as u64,
                program_word_count: encoded.words.len() as u64,
                output_word_count: output_layout.word_count as u64,
                source_count: request.input.len() as u64,
                node_count: self.node_count as u64,
                edge_count: self.edge_count as u64,
                pair_count: output_layout.pair_count as u64,
                maximum_work_rows: request.maximum_output_rows as u64,
                receipt_count: request.obligations().len() as u64,
                first_node_id: request.first_node_id,
                first_edge_id: request.first_edge_id.ok_or_else(|| {
                    Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal generalized row mutation requires an edge-ID origin",
                    )
                })?,
                layers: u64::from(request.read_layers.bits()),
                relationship_type_present: u64::from(relationship_token.is_some()),
                relationship_type_token: relationship_token.map_or(0, |token| token.0),
                graph_node_active_base: graph_layout.node_active_base as u64,
                graph_node_layer_base: graph_layout.node_layer_base as u64,
                graph_node_id_base: graph_layout.node_id_base as u64,
                graph_matched_label_base: graph_layout.matched_label_base as u64,
                graph_merged_label_base: graph_layout.merged_label_base as u64,
                graph_matched_value_base: graph_layout.matched_value_base as u64,
                graph_matched_validity_base: graph_layout.matched_validity_base as u64,
                graph_merged_value_base: graph_layout.merged_value_base as u64,
                graph_merged_validity_base: graph_layout.merged_validity_base as u64,
                graph_edge_active_base: graph_layout.edge_active_base as u64,
                graph_edge_layer_base: graph_layout.edge_layer_base as u64,
                graph_edge_id_base: graph_layout.edge_id_base as u64,
                graph_edge_source_base: graph_layout.edge_source_base as u64,
                graph_edge_target_base: graph_layout.edge_target_base as u64,
                graph_edge_type_base: graph_layout.edge_type_base as u64,
                program_map_offset_base: encoded.map_offset_base as u64,
                program_entry_base: encoded.entry_base as u64,
                program_key_byte_base: encoded.key_byte_base as u64,
                program_key_byte_count: encoded.key_byte_count as u64,
                program_match_key_offset: encoded.match_key_offset as u64,
                program_match_key_length: encoded.match_key_length as u64,
                program_merge_key_offset: encoded.merge_key_offset as u64,
                program_merge_key_length: encoded.merge_key_length as u64,
                program_obligation_base: encoded.obligation_base as u64,
                output_receipt_base: output_layout.receipt_base as u64,
                output_pair_active_base: output_layout.pair_active_base as u64,
                output_work_source_base: output_layout.work_source_base as u64,
                output_matched_id_base: output_layout.matched_id_base as u64,
                output_matched_dense_base: output_layout.matched_dense_base as u64,
                output_merged_id_base: output_layout.merged_id_base as u64,
                output_merged_dense_base: output_layout.merged_dense_base as u64,
                output_merged_created_base: output_layout.merged_created_base as u64,
                output_relationship_id_base: output_layout.relationship_id_base as u64,
                output_relationship_dense_base: output_layout.relationship_dense_base as u64,
                output_relationship_created_base: output_layout.relationship_created_base as u64,
                output_node_create_base: output_layout.node_create_base as u64,
                output_relationship_create_base: output_layout.relationship_create_base as u64,
                output_node_dependency_base: output_layout.node_dependency_base as u64,
                output_relationship_dependency_base: output_layout.relationship_dependency_base
                    as u64,
                output_sorted_value_base: output_layout.sorted_value_base as u64,
                output_sorted_work_base: output_layout.sorted_work_base as u64,
                output_control_base: output_layout.control_base as u64,
            };
            let output = graph
                .apply_op2_no_bwd(
                    &program,
                    &MetalRowMatchMergeRelationship {
                        arguments,
                        graph_storage_words: graph.elem_count(),
                    },
                )
                .map_err(candle_error)?;
            let words = output.to_vec1::<i64>().map_err(candle_error)?;
            ensure_not_cancelled(cancellation)?;
            return decode_metal_row_match_merge_relationship_result(
                &words,
                request,
                &encoded,
                graph_layout,
                output_layout,
            );
        }
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        {
            let _ = (
                graph,
                program,
                encoded,
                graph_layout,
                output_layout,
                relationship_token,
                catalog,
                fingerprint,
            );
            Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal generalized row-mutation kernels are unavailable on this build target",
            ))
        }
    }

    fn metal_row_match_merge_relationship_graph_packet(
        &self,
        device: &Device,
        request: &ResidentRowMutationRequest,
        layout: MetalRowMatchMergeRelationshipGraphLayout,
    ) -> Result<Tensor> {
        let extension = request.match_merge_relationship.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal generalized row mutation lost its graph program",
            )
        })?;
        let mut parts = Vec::new();
        parts.push(
            Tensor::from_slice(&[METAL_ROW_MATCH_MERGE_GRAPH_MAGIC as i64], 1, device)
                .map_err(candle_error)?,
        );
        append_metal_nullable_i64(
            &mut parts,
            self.node_active.as_ref(),
            self.node_count,
            DType::U8,
            "MATCH/MERGE node-active",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.node_layers.as_ref(),
            self.node_count,
            DType::U8,
            "MATCH/MERGE node-layer",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.node_entity_ids.as_ref(),
            self.node_count,
            DType::I64,
            "MATCH/MERGE node-ID",
        )?;
        for (label, name) in [
            (
                extension.matched_node.labels[0],
                "MATCH/MERGE matched-label",
            ),
            (request.program.merge.labels[0], "MATCH/MERGE merged-label"),
        ] {
            let membership = request
                .program
                .label_tokens
                .get(usize::from(label))
                .copied()
                .flatten()
                .and_then(|token| self.node_labels.get(&token));
            if let Some(membership) = membership {
                append_metal_nullable_i64(
                    &mut parts,
                    Some(membership),
                    self.node_count,
                    DType::U8,
                    name,
                )?;
            } else {
                parts.push(
                    Tensor::zeros(self.node_count, DType::I64, device).map_err(candle_error)?,
                );
            }
        }
        append_metal_row_match_merge_integer_lane(
            &mut parts,
            self,
            request,
            extension.matched_node.keys[0].property_name,
            device,
            "MATCH/MERGE matched integer property",
        )?;
        append_metal_row_match_merge_integer_lane(
            &mut parts,
            self,
            request,
            request.program.merge.keys[0].property_name,
            device,
            "MATCH/MERGE merged integer property",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_active.as_ref(),
            self.edge_count,
            DType::U8,
            "MATCH/MERGE edge-active",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_layers.as_ref(),
            self.edge_count,
            DType::U8,
            "MATCH/MERGE edge-layer",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_entity_ids.as_ref(),
            self.edge_count,
            DType::I64,
            "MATCH/MERGE edge-ID",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_sources.as_ref(),
            self.edge_count,
            DType::U32,
            "MATCH/MERGE edge-source",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_targets.as_ref(),
            self.edge_count,
            DType::U32,
            "MATCH/MERGE edge-target",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_types.as_ref(),
            self.edge_count,
            DType::I64,
            "MATCH/MERGE edge-type",
        )?;
        mutation_concat_i64(&parts, layout.word_count, device)
    }

    fn validate_metal_row_mutation_generation(
        &self,
        request: &ResidentRowMutationRequest,
    ) -> Result<()> {
        if request.generation.project != self.project
            || request.generation.bookmark != self.bookmark
            || request.generation.graph_revision != self.revision
            || request.generation.layout_version != self.layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal row mutation targets a different immutable resident generation",
            ));
        }
        Ok(())
    }

    fn metal_row_mutation_graph_packet(
        &self,
        device: &Device,
        request: &ResidentRowMutationRequest,
        layout: MetalRowMutationGraphLayout,
    ) -> Result<Tensor> {
        let mut parts = Vec::new();
        parts.push(
            Tensor::from_slice(&[METAL_ROW_MUTATION_GRAPH_MAGIC as i64], 1, device)
                .map_err(candle_error)?,
        );
        append_metal_nullable_i64(
            &mut parts,
            self.node_active.as_ref(),
            self.node_count,
            DType::U8,
            "row-mutation node-active",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.node_layers.as_ref(),
            self.node_count,
            DType::U8,
            "row-mutation node-layer",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.node_entity_ids.as_ref(),
            self.node_count,
            DType::I64,
            "row-mutation node-ID",
        )?;
        for label in &request.program.merge.labels {
            let token = request
                .program
                .label_tokens
                .get(usize::from(*label))
                .copied()
                .flatten();
            if let Some(membership) = token.and_then(|token| self.node_labels.get(&token)) {
                append_metal_nullable_i64(
                    &mut parts,
                    Some(membership),
                    self.node_count,
                    DType::U8,
                    "row-mutation label",
                )?;
            } else {
                parts.push(
                    Tensor::zeros(self.node_count, DType::I64, device).map_err(candle_error)?,
                );
            }
        }
        let merge = request.program.merge.keys[0];
        let property = request
            .program
            .property_tokens
            .get(usize::from(merge.property_name))
            .copied()
            .flatten();
        if let Some(property) = property {
            if let Some(column) = self.string_nodes.get(&property) {
                if column.rows != self.node_count {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal row-mutation STRING property has the wrong resident row count",
                    ));
                }
                append_metal_nullable_i64(
                    &mut parts,
                    column.values.as_ref(),
                    self.node_count,
                    DType::U32,
                    "row-mutation STRING value",
                )?;
                append_metal_nullable_i64(
                    &mut parts,
                    column.validity.as_ref(),
                    self.node_count,
                    DType::U8,
                    "row-mutation STRING validity",
                )?;
            } else if self.mixed_nodes.contains_key(&property)
                || self.unsupported_node_properties.contains(&property)
            {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal row mutation does not yet admit a mixed-shape MERGE key property",
                ));
            } else {
                parts.push(
                    Tensor::zeros(self.node_count, DType::I64, device).map_err(candle_error)?,
                );
                parts.push(
                    Tensor::zeros(self.node_count, DType::I64, device).map_err(candle_error)?,
                );
            }
        } else {
            parts.push(Tensor::zeros(self.node_count, DType::I64, device).map_err(candle_error)?);
            parts.push(Tensor::zeros(self.node_count, DType::I64, device).map_err(candle_error)?);
        }
        parts.push(
            self.node_string_dictionary
                .offsets
                .to_dtype(DType::I64)
                .map_err(candle_error)?,
        );
        if let Some(bytes) = &self.node_string_dictionary.bytes {
            parts.push(bytes.to_dtype(DType::I64).map_err(candle_error)?);
        }
        mutation_concat_i64(&parts, layout.word_count, device)
    }

    pub fn metal_delete_scratch_bytes(&self, request: &ResidentDeleteRequest) -> Result<usize> {
        request.validate()?;
        self.validate_metal_delete_generation(request)?;
        let encoded = self.encode_metal_delete_program(request)?;
        let graph = metal_delete_graph_layout(self, &encoded)?;
        let output = metal_delete_output_layout(request, &encoded)?;
        let overflow = || {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal DELETE scratch accounting overflow",
            )
        };
        request
            .scratch_bytes()?
            .checked_add(graph.word_count.checked_mul(16).ok_or_else(overflow)?)
            .and_then(|bytes| {
                encoded
                    .words
                    .len()
                    .checked_mul(std::mem::size_of::<i64>())
                    .and_then(|program| bytes.checked_add(program))
            })
            .and_then(|bytes| {
                output
                    .word_count
                    .checked_mul(std::mem::size_of::<i64>())
                    .and_then(|packet| bytes.checked_add(packet))
            })
            .and_then(|bytes| bytes.checked_add(4_096))
            .ok_or_else(overflow)
    }

    pub fn execute_delete_pipeline_metal(
        &self,
        device: &Device,
        request: &ResidentDeleteRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentDeleteResult> {
        request.validate()?;
        self.validate_metal_delete_generation(request)?;
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native DELETE requires the selected Metal device",
            ));
        };
        ensure_not_cancelled(cancellation)?;
        let encoded = self.encode_metal_delete_program(request)?;
        let graph_layout = metal_delete_graph_layout(self, &encoded)?;
        let output_layout = metal_delete_output_layout(request, &encoded)?;
        let graph = self.metal_delete_graph_packet(device, &encoded, graph_layout)?;
        ensure_not_cancelled(cancellation)?;
        let program_words = encoded
            .words
            .iter()
            .map(|word| *word as i64)
            .collect::<Vec<_>>();
        let program = Tensor::from_slice(&program_words, program_words.len(), device)
            .map_err(candle_error)?;
        let project = request.project.0.as_u128();
        let fingerprint = metal_nullable_relation_hash_words(request.fingerprint.0);

        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        {
            let variable_path_frame = request
                .variable_path_selection
                .as_ref()
                .map(|path| execute_metal_variable_path_tensor(device, self, path, cancellation))
                .transpose()?;
            let variable_path = variable_path_frame.as_ref().map_or_else(
                || Tensor::zeros(1, DType::I64, device).map_err(candle_error),
                |frame| Ok(frame.tensor.clone()),
            )?;
            let path_fingerprint = variable_path_frame
                .as_ref()
                .map_or([0; 4], |frame| frame.plan.fingerprint_words);
            let arguments = MetalDeleteArgs {
                execution_high: request.execution.high,
                execution_low: request.execution.low,
                project_high: (project >> 64) as u64,
                project_low: project as u64,
                bookmark_term: request.expected_bookmark.term,
                bookmark_index: request.expected_bookmark.index,
                graph_revision: request.expected_graph_revision,
                layout_version: request.expected_layout_version,
                fingerprint_0: fingerprint[0],
                fingerprint_1: fingerprint[1],
                fingerprint_2: fingerprint[2],
                fingerprint_3: fingerprint[3],
                scratch_bytes: u64::try_from(request.scratch_bytes()?).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal DELETE scratch proof exceeds u64",
                    )
                })?,
                graph_word_count: graph_layout.word_count as u64,
                program_word_count: program_words.len() as u64,
                output_word_count: output_layout.word_count as u64,
                node_count: self.node_count as u64,
                edge_count: self.edge_count as u64,
                label_lane_count: encoded.label_lanes.len() as u64,
                node_property_count: graph_layout.node_property_count as u64,
                edge_property_count: graph_layout.edge_property_count as u64,
                node_active_base: graph_layout.node_active_base as u64,
                node_layer_base: graph_layout.node_layer_base as u64,
                node_id_base: graph_layout.node_id_base as u64,
                label_base: graph_layout.label_base as u64,
                edge_active_base: graph_layout.edge_active_base as u64,
                edge_layer_base: graph_layout.edge_layer_base as u64,
                edge_type_base: graph_layout.edge_type_base as u64,
                edge_id_base: graph_layout.edge_id_base as u64,
                outgoing_offset_base: graph_layout.outgoing_offset_base as u64,
                outgoing_neighbor_base: graph_layout.outgoing_neighbor_base as u64,
                outgoing_edge_base: graph_layout.outgoing_edge_base as u64,
                outgoing_count: graph_layout.outgoing_count as u64,
                incoming_offset_base: graph_layout.incoming_offset_base as u64,
                incoming_neighbor_base: graph_layout.incoming_neighbor_base as u64,
                incoming_edge_base: graph_layout.incoming_edge_base as u64,
                incoming_count: graph_layout.incoming_count as u64,
                node_property_value_base: graph_layout.node_property_value_base as u64,
                node_property_validity_base: graph_layout.node_property_validity_base as u64,
                edge_property_value_base: graph_layout.edge_property_value_base as u64,
                edge_property_validity_base: graph_layout.edge_property_validity_base as u64,
                filter_count: encoded.filter_count as u64,
                command_count: encoded.command_count as u64,
                stage_count: encoded.stage_count as u64,
                receipt_count: encoded.receipt_count as u64,
                selector_capacity: request.selection.max_output_rows as u64,
                intent_capacity: request.maximum_delete_intents as u64,
                dependency_capacity: request.maximum_read_dependencies as u64,
                final_capacity: request
                    .continuation
                    .as_ref()
                    .map_or(0, |continuation| continuation.maximum_output_rows)
                    as u64,
                receipt_base: output_layout.receipt_base as u64,
                command_attempt_base: output_layout.command_attempt_base as u64,
                intent_base: output_layout.intent_base as u64,
                dependency_base: output_layout.dependency_base as u64,
                final_value_base: output_layout.final_value_base as u64,
                final_validity_base: output_layout.final_validity_base as u64,
                start_row_base: output_layout.start_row_base as u64,
                relationship_row_base: output_layout.relationship_row_base as u64,
                end_row_base: output_layout.end_row_base as u64,
                position_base: output_layout.position_base as u64,
                intent_dense_base: output_layout.intent_dense_base as u64,
                intent_processed_base: output_layout.intent_processed_base as u64,
                control_base: output_layout.control_base as u64,
                expected_static_empty: u64::from(request.selection_is_statically_empty),
                variable_path_mode: u64::from(variable_path_frame.is_some()),
                variable_path_word_count: variable_path_frame
                    .as_ref()
                    .map_or(1, |frame| frame.word_count)
                    as u64,
                variable_path_abi: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.abi_word),
                variable_path_output_header_words: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.output_header_words)
                    as u64,
                variable_path_publication_count_word: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.publication_count_word)
                    as u64,
                variable_path_publication_capacity: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.publication_capacity)
                    as u64,
                variable_path_receipt_base: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.receipt_base)
                    as u64,
                variable_path_receipt_count: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.receipt_count)
                    as u64,
                variable_path_receipt_words: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.receipt_words)
                    as u64,
                variable_path_descriptor_base: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.descriptor_base)
                    as u64,
                variable_path_descriptor_stride: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.descriptor_stride)
                    as u64,
                variable_path_edge_base: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.edge_base)
                    as u64,
                variable_path_edge_stride: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.edge_stride)
                    as u64,
                variable_path_node_base: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.node_base)
                    as u64,
                variable_path_node_stride: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.node_stride)
                    as u64,
                variable_path_segment_end_base: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.segment_end_base)
                    as u64,
                variable_path_segment_stride: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.segment_stride)
                    as u64,
                variable_path_metadata_base: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.publication_metadata_base)
                    as u64,
                variable_path_metadata_stride: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.publication_metadata_stride)
                    as u64,
                variable_path_final_relation_base: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.final_relation_base)
                    as u64,
                variable_path_final_relation_capacity: variable_path_frame
                    .as_ref()
                    .map_or(0, |frame| frame.final_relation_capacity)
                    as u64,
                variable_path_fingerprint_0: path_fingerprint[0],
                variable_path_fingerprint_1: path_fingerprint[1],
                variable_path_fingerprint_2: path_fingerprint[2],
                variable_path_fingerprint_3: path_fingerprint[3],
            };
            let output = graph
                .apply_op3_no_bwd(
                    &program,
                    &variable_path,
                    &MetalDelete {
                        arguments,
                        graph_storage_words: graph.elem_count(),
                        filter_count: encoded.filter_count,
                        stage_count: encoded.stage_count,
                    },
                )
                .map_err(candle_error)?;
            let words = output.to_vec1::<i64>().map_err(candle_error)?;
            ensure_not_cancelled(cancellation)?;
            if std::env::var_os("IRONGRAPH_DEBUG_METAL_DELETE").is_some() {
                eprintln!(
                    "Metal DELETE debug: nodes={} edges={} selector={} selected={} intents={} deps={} final={} selection={:#?}",
                    self.node_count,
                    self.edge_count,
                    words.get(16).copied().unwrap_or_default(),
                    words.get(17).copied().unwrap_or_default(),
                    words.get(19).copied().unwrap_or_default(),
                    words.get(20).copied().unwrap_or_default(),
                    words.get(22).copied().unwrap_or_default(),
                    request.selection,
                );
            }
            return decode_metal_delete_result(&words, request, &encoded, output_layout);
        }
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        {
            let _ = (graph, program, encoded, output_layout, fingerprint);
            Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal DELETE kernels are unavailable on this build target",
            ))
        }
    }

    fn validate_metal_delete_generation(&self, request: &ResidentDeleteRequest) -> Result<()> {
        if request.project != self.project
            || request.selection.project != self.project
            || request.expected_bookmark != self.bookmark
            || request.expected_graph_revision != self.revision
            || request.expected_layout_version != self.layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal DELETE targets a different immutable resident generation",
            ));
        }
        Ok(())
    }

    fn metal_delete_graph_packet(
        &self,
        device: &Device,
        encoded: &EncodedMetalDeleteProgram,
        layout: MetalDeleteGraphLayout,
    ) -> Result<Tensor> {
        let mut parts = Vec::with_capacity(
            encoded
                .label_lanes
                .len()
                .saturating_add(encoded.property_lanes.len().saturating_mul(2))
                .saturating_add(16),
        );
        append_metal_nullable_i64(
            &mut parts,
            self.node_active.as_ref(),
            self.node_count,
            DType::U8,
            "DELETE node-active",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.node_layers.as_ref(),
            self.node_count,
            DType::U8,
            "DELETE node-layer",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.node_entity_ids.as_ref(),
            self.node_count,
            DType::I64,
            "DELETE node-ID",
        )?;
        for label in &encoded.label_lanes {
            if let Some(membership) = self.node_labels.get(label) {
                append_metal_nullable_i64(
                    &mut parts,
                    Some(membership),
                    self.node_count,
                    DType::U8,
                    "DELETE node-label membership",
                )?;
            } else if self.node_count != 0 {
                let absent =
                    Tensor::zeros(self.node_count, DType::U8, device).map_err(candle_error)?;
                append_metal_nullable_i64(
                    &mut parts,
                    Some(&absent),
                    self.node_count,
                    DType::U8,
                    "DELETE absent node-label membership",
                )?;
            }
        }
        append_metal_nullable_i64(
            &mut parts,
            self.edge_active.as_ref(),
            self.edge_count,
            DType::U8,
            "DELETE edge-active",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_layers.as_ref(),
            self.edge_count,
            DType::U8,
            "DELETE edge-layer",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_types.as_ref(),
            self.edge_count,
            DType::I64,
            "DELETE edge-type",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_entity_ids.as_ref(),
            self.edge_count,
            DType::I64,
            "DELETE edge-ID",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            Some(&self.outgoing_offsets),
            self.node_count.saturating_add(1),
            DType::U32,
            "DELETE outgoing offsets",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.outgoing_neighbors.as_ref(),
            layout.outgoing_count,
            DType::U32,
            "DELETE outgoing neighbors",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.outgoing_edges.as_ref(),
            layout.outgoing_count,
            DType::U32,
            "DELETE outgoing edges",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            Some(&self.incoming_offsets),
            self.node_count.saturating_add(1),
            DType::U32,
            "DELETE incoming offsets",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.incoming_neighbors.as_ref(),
            layout.incoming_count,
            DType::U32,
            "DELETE incoming neighbors",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.incoming_edges.as_ref(),
            layout.incoming_count,
            DType::U32,
            "DELETE incoming edges",
        )?;
        for kind in [EntityKind::Node, EntityKind::Relationship] {
            for lane in encoded
                .property_lanes
                .iter()
                .filter(|lane| lane.kind == kind)
            {
                let (column, rows) = match kind {
                    EntityKind::Node => (
                        self.integer_nodes.get(&lane.property).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal DELETE node property lane disappeared",
                            )
                        })?,
                        self.node_count,
                    ),
                    EntityKind::Relationship => (
                        self.integer_edges.get(&lane.property).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal DELETE relationship property lane disappeared",
                            )
                        })?,
                        self.edge_count,
                    ),
                };
                if column.rows != rows {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal DELETE integer property lane has a wrong resident row count",
                    ));
                }
                append_metal_nullable_i64(
                    &mut parts,
                    column.values.as_ref(),
                    rows,
                    DType::I64,
                    "DELETE integer property values",
                )?;
            }
            for lane in encoded
                .property_lanes
                .iter()
                .filter(|lane| lane.kind == kind)
            {
                let (column, rows) = match kind {
                    EntityKind::Node => (
                        self.integer_nodes.get(&lane.property).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal DELETE node property validity lane disappeared",
                            )
                        })?,
                        self.node_count,
                    ),
                    EntityKind::Relationship => (
                        self.integer_edges.get(&lane.property).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal DELETE relationship property validity lane disappeared",
                            )
                        })?,
                        self.edge_count,
                    ),
                };
                append_metal_nullable_i64(
                    &mut parts,
                    column.validity.as_ref(),
                    rows,
                    DType::U8,
                    "DELETE integer property validity",
                )?;
            }
        }
        mutation_concat_i64(&parts, layout.word_count, device)
    }

    fn execute_nullable_relation_tensor(
        &self,
        device: &Device,
        request: &ResidentNullableRelationRequest,
        cancellation: &CancellationToken,
    ) -> Result<(Tensor, usize)> {
        request.validate()?;
        self.validate_nullable_relation_generation(request)?;
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native nullable relation requires the selected Metal device",
            ));
        };
        ensure_not_cancelled(cancellation)?;
        let encoded = encode_metal_nullable_relation_program(request)?;
        let graph_layout = metal_nullable_relation_graph_layout(self, &encoded)?;
        let graph = self.metal_nullable_relation_graph_packet(device, &encoded, graph_layout)?;
        let program_words = encoded
            .words
            .iter()
            .map(|word| *word as i64)
            .collect::<Vec<_>>();
        let program = Tensor::from_slice(&program_words, program_words.len(), device)
            .map_err(candle_error)?;
        let relation_cells = metal_nullable_relation_max_relation_cells(request)?;
        let output_layout = metal_nullable_relation_output_layout(request, relation_cells)?;
        let output_words = output_layout.word_count;
        let project = request.generation.project.0.as_u128();
        let catalog = metal_nullable_relation_hash_words(request.generation.catalog_generation);
        let fingerprint = metal_nullable_relation_hash_words(request.manifest.fingerprint.0);

        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        {
            let arguments = MetalNullableRelationArgs {
                execution_high: request.execution.high,
                execution_low: request.execution.low,
                project_high: (project >> 64) as u64,
                project_low: project as u64,
                bookmark_term: request.generation.bookmark.term,
                bookmark_index: request.generation.bookmark.index,
                graph_revision: request.generation.graph_revision,
                layout_version: request.generation.layout_version,
                catalog_0: catalog[0],
                catalog_1: catalog[1],
                catalog_2: catalog[2],
                catalog_3: catalog[3],
                fingerprint_0: fingerprint[0],
                fingerprint_1: fingerprint[1],
                fingerprint_2: fingerprint[2],
                fingerprint_3: fingerprint[3],
                scratch_bytes: u64::try_from(request.scratch_bytes()?).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal nullable-relation scratch proof exceeds u64",
                    )
                })?,
                graph_word_count: u64::try_from(graph_layout.word_count).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal nullable-relation graph packet exceeds u64",
                    )
                })?,
                program_word_count: u64::try_from(program_words.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal nullable-relation program packet exceeds u64",
                    )
                })?,
                output_word_count: u64::try_from(output_words).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal nullable-relation output packet exceeds u64",
                    )
                })?,
                node_count: self.node_count as u64,
                edge_count: self.edge_count as u64,
                visible_node_rows: u64::from(request.capacities.visible_node_rows),
                visible_relationship_rows: u64::from(request.capacities.visible_relationship_rows),
                label_lane_count: encoded.label_lanes.len() as u64,
                node_integer_lane_count: graph_layout.node_integer_count as u64,
                node_float_lane_count: graph_layout.node_float_count as u64,
                node_string_lane_count: graph_layout.node_string_count as u64,
                edge_integer_lane_count: graph_layout.edge_integer_count as u64,
                edge_float_lane_count: graph_layout.edge_float_count as u64,
                edge_string_lane_count: graph_layout.edge_string_count as u64,
                node_active_base: graph_layout.node_active_base as u64,
                node_layer_base: graph_layout.node_layer_base as u64,
                label_base: graph_layout.label_base as u64,
                edge_active_base: graph_layout.edge_active_base as u64,
                edge_layer_base: graph_layout.edge_layer_base as u64,
                edge_type_base: graph_layout.edge_type_base as u64,
                edge_source_base: graph_layout.edge_source_base as u64,
                edge_target_base: graph_layout.edge_target_base as u64,
                outgoing_offset_base: graph_layout.outgoing_offset_base as u64,
                outgoing_neighbor_base: graph_layout.outgoing_neighbor_base as u64,
                outgoing_edge_base: graph_layout.outgoing_edge_base as u64,
                outgoing_count: graph_layout.outgoing_count as u64,
                outgoing_overlay_base: graph_layout.outgoing_overlay_base as u64,
                outgoing_overlay_word_count: graph_layout.outgoing_overlay_word_count as u64,
                outgoing_overlay_row_count: graph_layout.outgoing_overlay_row_count as u64,
                incoming_offset_base: graph_layout.incoming_offset_base as u64,
                incoming_neighbor_base: graph_layout.incoming_neighbor_base as u64,
                incoming_edge_base: graph_layout.incoming_edge_base as u64,
                incoming_count: graph_layout.incoming_count as u64,
                incoming_overlay_base: graph_layout.incoming_overlay_base as u64,
                incoming_overlay_word_count: graph_layout.incoming_overlay_word_count as u64,
                incoming_overlay_row_count: graph_layout.incoming_overlay_row_count as u64,
                node_integer_value_base: graph_layout.node_integer_value_base as u64,
                node_integer_validity_base: graph_layout.node_integer_validity_base as u64,
                node_float_value_base: graph_layout.node_float_value_base as u64,
                node_float_validity_base: graph_layout.node_float_validity_base as u64,
                node_string_value_base: graph_layout.node_string_value_base as u64,
                node_string_validity_base: graph_layout.node_string_validity_base as u64,
                edge_integer_value_base: graph_layout.edge_integer_value_base as u64,
                edge_integer_validity_base: graph_layout.edge_integer_validity_base as u64,
                edge_float_value_base: graph_layout.edge_float_value_base as u64,
                edge_float_validity_base: graph_layout.edge_float_validity_base as u64,
                edge_string_value_base: graph_layout.edge_string_value_base as u64,
                edge_string_validity_base: graph_layout.edge_string_validity_base as u64,
                node_string_offset_base: graph_layout.node_string_offset_base as u64,
                node_string_offset_count: graph_layout.node_string_offset_count as u64,
                node_string_byte_base: graph_layout.node_string_byte_base as u64,
                node_string_byte_count: graph_layout.node_string_byte_count as u64,
                edge_string_offset_base: graph_layout.edge_string_offset_base as u64,
                edge_string_offset_count: graph_layout.edge_string_offset_count as u64,
                edge_string_byte_base: graph_layout.edge_string_byte_base as u64,
                edge_string_byte_count: graph_layout.edge_string_byte_count as u64,
                property_descriptor_base: graph_layout.property_descriptor_base as u64,
                maximum_relation_cells: relation_cells as u64,
                maximum_relation_rows: output_layout.maximum_relation_rows as u64,
                maximum_filter_rows: output_layout.maximum_filter_rows as u64,
                maximum_output_rows: output_layout.final_row_capacity as u64,
                final_output_columns: u64::from(request.capacities.final_output_columns),
                final_byte_count: output_layout.final_byte_count as u64,
                stage_count: request.program.stages.len() as u64,
                filter_count: request.predicate_program.filters.len() as u64,
                optional_group_count: request.predicate_program.optional_groups.len() as u64,
                receipt_count: request.manifest.obligations.len() as u64,
                binding_slot_count: u64::from(request.capacities.binding_slot_count),
                layers: u64::from(request.program.layers.bits()),
                column_base: output_layout.column_base as u64,
                final_base: output_layout.final_base as u64,
                relation_a_base: output_layout.relation_a_base as u64,
                relation_b_base: output_layout.relation_b_base as u64,
                parent_relation_base: output_layout.parent_relation_base as u64,
                lineage_a_base: output_layout.lineage_a_base as u64,
                lineage_b_base: output_layout.lineage_b_base as u64,
                slot_map_base: output_layout.slot_map_base as u64,
                next_slot_map_base: output_layout.next_slot_map_base as u64,
                filter_truth_base: output_layout.filter_truth_base as u64,
                filter_rank_base: output_layout.filter_rank_base as u64,
                control_base: output_layout.control_base as u64,
            };
            let encoded = graph
                .apply_op2_no_bwd(
                    &program,
                    &MetalNullableRelation {
                        arguments,
                        graph_storage_words: graph.elem_count(),
                        candidate_filters_by_stage: encoded.candidate_filters_by_stage.clone(),
                        candidate_filters_by_group: encoded.candidate_filters_by_group.clone(),
                        relation_filters_after: encoded.relation_filters_after.clone(),
                        optional_groups: encoded.optional_groups.clone(),
                        stages: request
                            .program
                            .stages
                            .iter()
                            .map(|stage| match stage {
                                ResidentNullableRelationStage::NodeScan { .. } => {
                                    MetalNullableRelationStageKernel::NodeScan
                                }
                                ResidentNullableRelationStage::Expand { .. } => {
                                    MetalNullableRelationStageKernel::Expand
                                }
                                ResidentNullableRelationStage::ScopeProject { .. } => {
                                    MetalNullableRelationStageKernel::ScopeProject
                                }
                                ResidentNullableRelationStage::FinalProject { .. } => {
                                    MetalNullableRelationStageKernel::FinalProject
                                }
                            })
                            .collect(),
                    },
                )
                .map_err(candle_error)?;
            return Ok((encoded, graph_layout.word_count));
        }
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        {
            let _ = (
                graph,
                program,
                relation_cells,
                output_words,
                catalog,
                fingerprint,
            );
            Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal nullable-relation kernels are unavailable on this build target",
            ))
        }
    }

    pub fn execute_nullable_relation(
        &self,
        device: &Device,
        request: &ResidentNullableRelationRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentNullableRelationResult> {
        let (encoded, graph_word_count) =
            self.execute_nullable_relation_tensor(device, request, cancellation)?;
        let words = encoded.to_vec1::<i64>().map_err(candle_error)?;
        ensure_not_cancelled(cancellation)?;
        decode_metal_nullable_relation(&words, request, graph_word_count)
    }

    fn validate_nullable_relation_generation(
        &self,
        request: &ResidentNullableRelationRequest,
    ) -> Result<()> {
        if request.generation.project != self.project
            || request.generation.bookmark != self.bookmark
            || request.generation.graph_revision != self.revision
            || request.generation.layout_version != self.layout_version
            || request.capacities.node_slot_count as usize != self.node_count
            || request.capacities.relationship_slot_count as usize != self.edge_count
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal nullable relation targets a different immutable resident generation",
            ));
        }
        Ok(())
    }

    fn metal_nullable_relation_graph_packet(
        &self,
        device: &Device,
        encoded: &EncodedMetalNullableRelation,
        layout: MetalNullableRelationGraphLayout,
    ) -> Result<Tensor> {
        let mut parts = Vec::with_capacity(
            encoded
                .label_lanes
                .len()
                .saturating_add(encoded.property_lanes.len().saturating_mul(2))
                .saturating_add(16),
        );
        append_metal_nullable_i64(
            &mut parts,
            self.node_active.as_ref(),
            self.node_count,
            DType::U8,
            "node-active",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.node_layers.as_ref(),
            self.node_count,
            DType::U8,
            "node-layer",
        )?;
        for label in &encoded.label_lanes {
            if let Some(membership) = self.node_labels.get(label) {
                append_metal_nullable_i64(
                    &mut parts,
                    Some(membership),
                    self.node_count,
                    DType::U8,
                    "node-label membership",
                )?;
            } else if self.node_count != 0 {
                let absent =
                    Tensor::zeros(self.node_count, DType::U8, device).map_err(candle_error)?;
                append_metal_nullable_i64(
                    &mut parts,
                    Some(&absent),
                    self.node_count,
                    DType::U8,
                    "absent node-label membership",
                )?;
            }
        }
        append_metal_nullable_i64(
            &mut parts,
            self.edge_active.as_ref(),
            self.edge_count,
            DType::U8,
            "edge-active",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_layers.as_ref(),
            self.edge_count,
            DType::U8,
            "edge-layer",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_types.as_ref(),
            self.edge_count,
            DType::I64,
            "edge-type",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_sources.as_ref(),
            self.edge_count,
            DType::U32,
            "edge-source",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.edge_targets.as_ref(),
            self.edge_count,
            DType::U32,
            "edge-target",
        )?;
        append_metal_nullable_csr_offsets(
            &mut parts,
            &self.outgoing_offsets,
            self.node_count.saturating_add(1),
            "outgoing offsets",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.outgoing_neighbors.as_ref(),
            layout.outgoing_count,
            DType::U32,
            "outgoing neighbors",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.outgoing_edges.as_ref(),
            layout.outgoing_count,
            DType::U32,
            "outgoing edges",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.outgoing_overlay.packet.as_ref(),
            layout.outgoing_overlay_word_count,
            DType::U32,
            "outgoing CSR overlay",
        )?;
        append_metal_nullable_csr_offsets(
            &mut parts,
            &self.incoming_offsets,
            self.node_count.saturating_add(1),
            "incoming offsets",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.incoming_neighbors.as_ref(),
            layout.incoming_count,
            DType::U32,
            "incoming neighbors",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.incoming_edges.as_ref(),
            layout.incoming_count,
            DType::U32,
            "incoming edges",
        )?;
        append_metal_nullable_i64(
            &mut parts,
            self.incoming_overlay.packet.as_ref(),
            layout.incoming_overlay_word_count,
            DType::U32,
            "incoming CSR overlay",
        )?;
        for (kind, shape) in [
            (
                ResidentNullableRelationBindingKind::Node,
                ResidentNullableRelationPropertyShape::Integer,
            ),
            (
                ResidentNullableRelationBindingKind::Node,
                ResidentNullableRelationPropertyShape::Float,
            ),
            (
                ResidentNullableRelationBindingKind::Node,
                ResidentNullableRelationPropertyShape::String,
            ),
            (
                ResidentNullableRelationBindingKind::Relationship,
                ResidentNullableRelationPropertyShape::Integer,
            ),
            (
                ResidentNullableRelationBindingKind::Relationship,
                ResidentNullableRelationPropertyShape::Float,
            ),
            (
                ResidentNullableRelationBindingKind::Relationship,
                ResidentNullableRelationPropertyShape::String,
            ),
        ] {
            for lane in encoded
                .property_lanes
                .iter()
                .filter(|lane| lane.kind == kind && lane.shape == shape)
            {
                let (values, rows, dtype) = match (kind, shape) {
                    (
                        ResidentNullableRelationBindingKind::Node,
                        ResidentNullableRelationPropertyShape::Integer,
                    ) => {
                        let values = if let Some(column) = self.integer_nodes.get(&lane.property) {
                            if column.rows != self.node_count {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-integer property lane has a wrong row count",
                                ));
                            }
                            column.values.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-integer values disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.node_count, DType::I64, device)
                                .map_err(candle_error)?
                        };
                        (values, self.node_count, DType::I64)
                    }
                    (
                        ResidentNullableRelationBindingKind::Node,
                        ResidentNullableRelationPropertyShape::Float,
                    ) => {
                        let values = if let Some(column) = self.float_nodes.get(&lane.property) {
                            if column.rows != self.node_count {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-float property lane has a wrong row count",
                                ));
                            }
                            column.values.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-float values disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.node_count, DType::I64, device)
                                .map_err(candle_error)?
                        };
                        (values, self.node_count, DType::I64)
                    }
                    (
                        ResidentNullableRelationBindingKind::Node,
                        ResidentNullableRelationPropertyShape::String,
                    ) => {
                        let values = if let Some(column) = self.string_nodes.get(&lane.property) {
                            if column.rows != self.node_count {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-string property lane has a wrong row count",
                                ));
                            }
                            column.values.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-string values disappeared",
                                )
                            })?
                        } else if let Some(column) = self.mixed_nodes.get(&lane.property) {
                            if column.offsets.elem_count() != self.node_count.saturating_add(1) {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable mixed node-string offsets have a wrong row count",
                                ));
                            }
                            column
                                .offsets
                                .narrow(0, 0, self.node_count)
                                .map_err(candle_error)?
                        } else {
                            Tensor::zeros(self.node_count, DType::U32, device)
                                .map_err(candle_error)?
                        };
                        (values, self.node_count, DType::U32)
                    }
                    (
                        ResidentNullableRelationBindingKind::Relationship,
                        ResidentNullableRelationPropertyShape::Integer,
                    ) => {
                        let values = if let Some(column) = self.integer_edges.get(&lane.property) {
                            if column.rows != self.edge_count {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-integer property lane has a wrong row count",
                                ));
                            }
                            column.values.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-integer values disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.edge_count, DType::I64, device)
                                .map_err(candle_error)?
                        };
                        (values, self.edge_count, DType::I64)
                    }
                    (
                        ResidentNullableRelationBindingKind::Relationship,
                        ResidentNullableRelationPropertyShape::Float,
                    ) => {
                        let values = if let Some(column) = self.float_edges.get(&lane.property) {
                            if column.rows != self.edge_count {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-float property lane has a wrong row count",
                                ));
                            }
                            column.values.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-float values disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.edge_count, DType::I64, device)
                                .map_err(candle_error)?
                        };
                        (values, self.edge_count, DType::I64)
                    }
                    (
                        ResidentNullableRelationBindingKind::Relationship,
                        ResidentNullableRelationPropertyShape::String,
                    ) => {
                        let values = if let Some(column) = self.string_edges.get(&lane.property) {
                            if column.rows != self.edge_count {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-string property lane has a wrong row count",
                                ));
                            }
                            column.values.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-string values disappeared",
                                )
                            })?
                        } else if let Some(column) = self.mixed_edges.get(&lane.property) {
                            if column.offsets.elem_count() != self.edge_count.saturating_add(1) {
                                return Err(Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable mixed relationship-string offsets have a wrong row count",
                                ));
                            }
                            column
                                .offsets
                                .narrow(0, 0, self.edge_count)
                                .map_err(candle_error)?
                        } else {
                            Tensor::zeros(self.edge_count, DType::U32, device)
                                .map_err(candle_error)?
                        };
                        (values, self.edge_count, DType::U32)
                    }
                };
                append_metal_nullable_i64(
                    &mut parts,
                    Some(&values),
                    rows,
                    dtype,
                    "predicate property values",
                )?;
            }
            for lane in encoded
                .property_lanes
                .iter()
                .filter(|lane| lane.kind == kind && lane.shape == shape)
            {
                let (validity, rows) = match (kind, shape) {
                    (
                        ResidentNullableRelationBindingKind::Node,
                        ResidentNullableRelationPropertyShape::Integer,
                    ) => {
                        let validity = if let Some(column) = self.integer_nodes.get(&lane.property)
                        {
                            column.validity.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-integer validity disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.node_count, DType::U8, device)
                                .map_err(candle_error)?
                        };
                        (validity, self.node_count)
                    }
                    (
                        ResidentNullableRelationBindingKind::Node,
                        ResidentNullableRelationPropertyShape::Float,
                    ) => {
                        let validity = if let Some(column) = self.float_nodes.get(&lane.property) {
                            column.validity.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-float validity disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.node_count, DType::U8, device)
                                .map_err(candle_error)?
                        };
                        (validity, self.node_count)
                    }
                    (
                        ResidentNullableRelationBindingKind::Node,
                        ResidentNullableRelationPropertyShape::String,
                    ) => {
                        let validity = if let Some(column) = self.string_nodes.get(&lane.property) {
                            column.validity.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable node-string validity disappeared",
                                )
                            })?
                        } else if let Some(column) = self.mixed_nodes.get(&lane.property) {
                            column.validity.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable mixed node-string validity disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.node_count, DType::U8, device)
                                .map_err(candle_error)?
                        };
                        (validity, self.node_count)
                    }
                    (
                        ResidentNullableRelationBindingKind::Relationship,
                        ResidentNullableRelationPropertyShape::Integer,
                    ) => {
                        let validity = if let Some(column) = self.integer_edges.get(&lane.property)
                        {
                            column.validity.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-integer validity disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.edge_count, DType::U8, device)
                                .map_err(candle_error)?
                        };
                        (validity, self.edge_count)
                    }
                    (
                        ResidentNullableRelationBindingKind::Relationship,
                        ResidentNullableRelationPropertyShape::Float,
                    ) => {
                        let validity = if let Some(column) = self.float_edges.get(&lane.property) {
                            column.validity.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-float validity disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.edge_count, DType::U8, device)
                                .map_err(candle_error)?
                        };
                        (validity, self.edge_count)
                    }
                    (
                        ResidentNullableRelationBindingKind::Relationship,
                        ResidentNullableRelationPropertyShape::String,
                    ) => {
                        let validity = if let Some(column) = self.string_edges.get(&lane.property) {
                            column.validity.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable relationship-string validity disappeared",
                                )
                            })?
                        } else if let Some(column) = self.mixed_edges.get(&lane.property) {
                            column.validity.as_ref().cloned().ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "Metal nullable mixed relationship-string validity disappeared",
                                )
                            })?
                        } else {
                            Tensor::zeros(self.edge_count, DType::U8, device)
                                .map_err(candle_error)?
                        };
                        (validity, self.edge_count)
                    }
                };
                append_metal_nullable_i64(
                    &mut parts,
                    Some(&validity),
                    rows,
                    DType::U8,
                    "predicate property validity",
                )?;
            }
        }
        if layout.node_string_count != 0 {
            append_metal_nullable_i64(
                &mut parts,
                Some(&self.node_string_dictionary.offsets),
                layout.node_string_offset_count,
                DType::U32,
                "node-string dictionary offsets",
            )?;
            append_metal_nullable_i64(
                &mut parts,
                self.node_string_dictionary.bytes.as_ref(),
                layout.node_string_byte_count,
                DType::U8,
                "node-string dictionary bytes",
            )?;
        }
        if layout.edge_string_count != 0 {
            append_metal_nullable_i64(
                &mut parts,
                Some(&self.edge_string_dictionary.offsets),
                layout.edge_string_offset_count,
                DType::U32,
                "relationship-string dictionary offsets",
            )?;
            append_metal_nullable_i64(
                &mut parts,
                self.edge_string_dictionary.bytes.as_ref(),
                layout.edge_string_byte_count,
                DType::U8,
                "relationship-string dictionary bytes",
            )?;
        }
        for lane in &encoded.property_lanes {
            let Some((column, rows)) = metal_nullable_relation_mixed_string_column(self, lane)
            else {
                continue;
            };
            append_metal_nullable_i64(
                &mut parts,
                Some(&column.offsets),
                rows.saturating_add(1),
                DType::U32,
                "mixed-string offsets",
            )?;
            append_metal_nullable_i64(
                &mut parts,
                column.bytes.as_ref(),
                column.bytes.as_ref().map_or(0, Tensor::elem_count),
                DType::U8,
                "mixed-string bytes",
            )?;
        }
        let property_descriptor_words =
            metal_nullable_relation_graph_property_lane_words(self, encoded, &layout)?
                .into_iter()
                .map(|word| word as i64)
                .collect::<Vec<_>>();
        let property_descriptors = (!property_descriptor_words.is_empty())
            .then(|| {
                Tensor::from_slice(
                    &property_descriptor_words,
                    property_descriptor_words.len(),
                    device,
                )
                .map_err(candle_error)
            })
            .transpose()?;
        append_metal_nullable_i64(
            &mut parts,
            property_descriptors.as_ref(),
            layout
                .property_descriptor_count
                .checked_mul(METAL_NULLABLE_RELATION_PROPERTY_LANE_WORDS)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal nullable property descriptor packet overflow",
                    )
                })?,
            DType::I64,
            "property descriptors",
        )?;
        mutation_concat_i64(&parts, layout.word_count, device)
    }

    pub fn execute_node_pipeline(
        &self,
        device: &Device,
        request: &ResidentNodePipelineRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentNodePipelineResult> {
        request.validate_mutation()?;
        let rows = self.select_node_pipeline_rows(device, request, cancellation)?;
        let mutation_read_set = request
            .mutation
            .as_ref()
            .and_then(|program| program.continuation.as_ref())
            .map(|_| self.metal_mutation_read_set(device, request, cancellation))
            .transpose()?;
        let mutation_execution = request
            .mutation
            .as_ref()
            .map(|program| {
                if program.exact_document_constant_set().is_some() {
                    self.execute_static_metal_mutation(device, request, &rows, cancellation)
                } else if program.commands.iter().all(|command| {
                    matches!(
                        command.operation,
                        super::ResidentMutationOperation::SetProperty { .. }
                    )
                }) {
                    self.execute_typed_metal_mutation(device, request, &rows, cancellation)
                } else {
                    self.execute_static_metal_mutation(device, request, &rows, cancellation)
                }
            })
            .transpose()?;
        let mutation = match mutation_execution {
            Some(execution)
                if request
                    .mutation
                    .as_ref()
                    .is_some_and(|program| program.continuation.is_some()) =>
            {
                let read_set = mutation_read_set.as_ref().ok_or_else(|| {
                    Error::internal("Metal mutation continuation omitted its device read set")
                })?;
                let (read_dependencies, final_relation, continuation_receipts) = self
                    .execute_metal_mutation_continuation(
                        device,
                        request,
                        &rows,
                        read_set,
                        &execution,
                        cancellation,
                    )?;
                let super::ResidentMutationProgramResult {
                    execution: execution_id,
                    intents,
                    mut receipts,
                    pipeline,
                } = execution.result;
                if pipeline.is_some() {
                    return Err(Error::internal(
                        "Metal mutation prefix forged a continuation completion",
                    ));
                }
                receipts.extend(continuation_receipts);
                let continuation = request
                    .mutation
                    .as_ref()
                    .and_then(|program| program.continuation.as_ref())
                    .ok_or_else(|| Error::internal("Metal continuation disappeared"))?;
                Some(
                    super::ResidentMutationProgramResult::completed_pipeline_with_read_dependencies(
                        execution_id,
                        intents,
                        receipts,
                        self.project,
                        self.bookmark,
                        self.revision,
                        self.layout_version,
                        continuation.fingerprint,
                        super::ResidentDeviceCompletion::Metal,
                        read_dependencies,
                        final_relation,
                    ),
                )
            }
            Some(execution) => Some(execution.result),
            None => None,
        };
        let boolean_columns = request
            .property_null_projections
            .iter()
            .map(|projection| {
                let values = match projection.property {
                    Some(property) => {
                        let binding_rows = rows.binding(projection.binding)?;
                        let (_, validity) =
                            self.selected_integer_column_tensor(property, binding_rows)?;
                        if projection.negated {
                            validity
                        } else {
                            validity.eq(0_u8).map_err(candle_error)?
                        }
                    }
                    None if projection.negated => {
                        Tensor::zeros(rows.row_count(), DType::U8, device).map_err(candle_error)?
                    }
                    None => {
                        Tensor::ones(rows.row_count(), DType::U8, device).map_err(candle_error)?
                    }
                };
                Ok(ResidentBooleanColumn {
                    projection: *projection,
                    values: values.to_vec1::<u8>().map_err(candle_error)?,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let integer_columns = request
            .integer_projections
            .iter()
            .map(|projection| {
                let binding_rows = rows.binding(projection.binding)?;
                let (values, validity) =
                    self.selected_integer_column_tensor(projection.property, binding_rows)?;
                let values = values.to_vec1::<i64>().map_err(candle_error)?;
                let validity = validity.to_vec1::<u8>().map_err(candle_error)?;
                Ok(ResidentI64Column {
                    binding: projection.binding,
                    property: projection.property,
                    values,
                    validity,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let (value_left_indices, value_right_indices) = match rows.value_indices {
            Some((left, right)) => (
                left.to_vec1::<u32>().map_err(candle_error)?,
                right.to_vec1::<u32>().map_err(candle_error)?,
            ),
            None => (Vec::new(), Vec::new()),
        };
        let expansion_count = request.expansion_steps().count();
        let mut node_rows = rows.nodes;
        let start_rows = node_rows
            .first()
            .ok_or_else(|| Error::internal("resident device path omitted its start node column"))?
            .to_vec1::<u32>()
            .map_err(candle_error)?;
        let end_rows = if expansion_count == 0 {
            Vec::new()
        } else {
            node_rows
                .pop()
                .ok_or_else(|| {
                    Error::internal("resident device path omitted its final node column")
                })?
                .to_vec1::<u32>()
                .map_err(candle_error)?
        };
        let intermediate_node_rows = if expansion_count == 0 {
            Vec::new()
        } else {
            node_rows
                .into_iter()
                .skip(1)
                .map(|rows| rows.to_vec1::<u32>().map_err(candle_error))
                .collect::<Result<Vec<_>>>()?
        };
        let mut relationship_rows = rows.relationships;
        let edge_rows = relationship_rows
            .pop()
            .map(|rows| rows.to_vec1::<u32>().map_err(candle_error))
            .transpose()?
            .unwrap_or_default();
        let intermediate_edge_rows = relationship_rows
            .into_iter()
            .map(|rows| rows.to_vec1::<u32>().map_err(candle_error))
            .collect::<Result<Vec<_>>>()?;
        ensure_not_cancelled(cancellation)?;
        Ok(ResidentNodePipelineResult {
            start_rows,
            intermediate_node_rows,
            intermediate_edge_rows,
            edge_rows,
            end_rows,
            integer_columns,
            boolean_columns,
            value_left_indices,
            value_right_indices,
            mutation,
        })
    }

    /// Executes the backend-neutral typed-row contract without publishing the wrapped graph row
    /// stream to the host between selection and expression/sort execution. The only host-visible
    /// values are the final bounded packet and its graph columns after the Metal queue has
    /// completed every semantic stage.
    pub fn execute_row_program(
        &self,
        device: &Device,
        request: &ResidentRowProgramRequest,
        scratch: &mut ScratchReservation,
        cancellation: &CancellationToken,
    ) -> Result<ResidentRowProgramResult> {
        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        {
            let Device::Metal(_) = device else {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "native resident typed-row programs require the selected Metal device",
                ));
            };
            ensure_not_cancelled(cancellation)?;
            request.validate()?;
            if request.project != self.project {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "resident typed-row program targets a different project image",
                ));
            }
            if self.bookmark != request.expected_bookmark
                || self.revision != request.expected_graph_revision
                || self.layout_version != request.expected_layout_version
            {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "resident typed-row program expected a different bookmark, graph revision, or layout version",
                ));
            }
            if request.input.mutation.is_some() {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "resident typed-row programs do not admit a mutation publication boundary",
                ));
            }

            let scalar_input_rows = request.scalar_input_rows()?;
            let mut rows = if scalar_input_rows.is_some() {
                None
            } else {
                Some(self.select_node_pipeline_rows(device, &request.input, cancellation)?)
            };
            // Finish a wrapped graph pipeline without reading its semantic columns. Typed literal
            // inputs have no graph selector to synchronize and are uploaded directly below.
            if rows.is_some() {
                device.synchronize().map_err(candle_error)?;
            }
            let input_rows = scalar_input_rows
                .unwrap_or_else(|| rows.as_ref().map_or(0, DeviceNodePipelineRows::row_count));
            let output_rows = request.output_cardinality(input_rows)?;
            let logical_scratch = request.scratch_bytes(input_rows)?;
            let sort_strategy = metal_row_sort_strategy(request, input_rows, output_rows)?;
            scratch.resize(metal_resident_row_program_scratch_bytes_with_strategy(
                request,
                input_rows,
                sort_strategy,
            )?)?;

            // Property gathers are command inputs, not row-program state. Keep their Rust owners
            // inside this block so they can be released as soon as the queued evaluator has
            // consumed them; the scratch calculation still covers their command-buffer lifetime.
            let (evaluated, metadata) = {
                let (property_inputs, metadata, property_load_count) =
                    self.metal_row_program_inputs(device, rows.as_ref(), request, input_rows)?;
                let evaluated = property_inputs
                    .apply_op2_no_bwd(
                        &metadata,
                        &MetalResidentRowEvaluate {
                            arguments: MetalResidentRowEvaluateArgs {
                                row_count: input_rows as u64,
                                dispatch_base: 0,
                                dispatch_count: 0,
                                output_word_count: metal_row_evaluate_words(request, input_rows)?
                                    as u64,
                                metadata_word_count: metadata.elem_count() as u64,
                                property_storage_words: property_inputs.elem_count() as u64,
                                node_string_entry_count: checked_u32(
                                    self.node_string_dictionary.offsets.elem_count() - 1,
                                    "Metal node string dictionary entries",
                                )?,
                                node_string_byte_count: checked_u32(
                                    self.node_string_dictionary
                                        .bytes
                                        .as_ref()
                                        .map_or(0, Tensor::elem_count),
                                    "Metal node string dictionary bytes",
                                )?,
                                edge_string_entry_count: checked_u32(
                                    self.edge_string_dictionary.offsets.elem_count() - 1,
                                    "Metal edge string dictionary entries",
                                )?,
                                edge_string_byte_count: checked_u32(
                                    self.edge_string_dictionary
                                        .bytes
                                        .as_ref()
                                        .map_or(0, Tensor::elem_count),
                                    "Metal edge string dictionary bytes",
                                )?,
                                instruction_count: request.program.instructions.len() as u32,
                                property_load_count: property_load_count as u32,
                                program_abi_version: METAL_ROW_PROGRAM_ABI_VERSION,
                                reserved: 0,
                            },
                            property_storage_words: property_inputs.elem_count(),
                            node_string_offsets: self.node_string_dictionary.offsets.clone(),
                            node_string_bytes: self
                                .node_string_dictionary
                                .bytes
                                .clone()
                                .unwrap_or_else(|| self.node_string_dictionary.offsets.clone()),
                            edge_string_offsets: self.edge_string_dictionary.offsets.clone(),
                            edge_string_bytes: self
                                .edge_string_dictionary
                                .bytes
                                .clone()
                                .unwrap_or_else(|| self.edge_string_dictionary.offsets.clone()),
                        },
                    )
                    .map_err(candle_error)?;
                (evaluated, metadata)
            };

            let positions = metal_row_order_positions(
                &evaluated,
                request,
                input_rows,
                sort_strategy,
                device,
                cancellation,
            )?;
            let proof_positions = if positions.elem_count() == 0 {
                Tensor::zeros(1, DType::I64, device).map_err(candle_error)?
            } else {
                positions.clone()
            };
            let selected_positions = if output_rows == 0 {
                positions.clone()
            } else {
                positions
                    .narrow(0, request.offset.min(positions.elem_count()), output_rows)
                    .map_err(candle_error)?
            };
            // Retain immutable aliases to every pre-selection graph column. Tensor clones share
            // their Metal buffers; they do not materialize graph semantics on the host.
            let proof_input_rows = rows.clone();

            if let Some(graph_rows) = &mut rows {
                if output_rows == 0 {
                    *graph_rows = empty_device_node_pipeline_rows(
                        device,
                        request.input.expansion_steps().count(),
                        request.input.relationship_column_count(),
                    )?;
                    if request.input.value_matrix.is_some() {
                        let empty = graph_rows.nodes.first().cloned().ok_or_else(|| {
                            Error::internal("empty Metal row proof omitted its start-node column")
                        })?;
                        graph_rows.value_indices = Some((empty.clone(), empty));
                    }
                } else {
                    graph_rows.select(&selected_positions)?;
                }
            }
            let proof_graph = metal_row_graph_proof_image(
                proof_input_rows.as_ref(),
                rows.as_ref(),
                request,
                input_rows,
                output_rows,
                device,
            )?;
            let proof_args = metal_row_proof_args(
                request,
                input_rows,
                output_rows,
                positions.elem_count(),
                metal_row_graph_column_count(request)?,
                sort_strategy,
            )?;
            let proof = evaluated
                .apply_op3_no_bwd(
                    &proof_positions,
                    &proof_graph,
                    &MetalResidentRowProof {
                        arguments: proof_args,
                    },
                )
                .map_err(candle_error)?;

            let finalize_args = metal_row_finalize_args(
                request,
                input_rows,
                output_rows,
                logical_scratch,
                &proof_args,
            )?;
            let packet_device = evaluated
                .apply_op3_no_bwd(
                    &metadata,
                    &proof,
                    &MetalResidentRowFinalize {
                        arguments: finalize_args,
                    },
                )
                .map_err(candle_error)?;
            let packet = packet_device.to_vec1::<i64>().map_err(candle_error)?;
            ensure_not_cancelled(cancellation)?;
            // Packet readback synchronizes the queue. None of these device owners are needed by
            // graph-column readback, so release them before accumulating host result columns.
            drop(packet_device);
            drop(evaluated);
            drop(metadata);
            drop(proof);
            drop(proof_graph);
            drop(proof_input_rows);
            drop(proof_positions);
            drop(selected_positions);
            drop(positions);
            let decoded = decode_metal_row_packet(&packet, request)?;
            drop(packet);
            let published_rows = match rows {
                Some(rows) => materialize_row_pipeline_rows(rows, request, cancellation)?,
                None => empty_row_pipeline_result(),
            };

            let result = ResidentRowProgramResult::completed(ResidentRowProgramResultParts {
                project: decoded.project,
                execution: decoded.execution,
                bookmark: decoded.bookmark,
                graph_revision: decoded.graph_revision,
                layout_version: decoded.layout_version,
                manifest_fingerprint: decoded.manifest_fingerprint,
                input_cardinality: decoded.input_cardinality,
                source_positions: decoded.source_positions,
                rows: published_rows,
                projected_columns: decoded.projected_columns,
                receipts: decoded.receipts,
                scratch_bytes: decoded.scratch_bytes,
            });
            let validated = result.validate(request, super::BackendKind::Metal)?;
            Ok(ResidentRowProgramResult::completed(validated.into_parts()))
        }
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        {
            let _ = (device, request, scratch, cancellation);
            Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal resident typed-row kernels are unavailable on this build target",
            ))
        }
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn metal_row_program_inputs(
        &self,
        device: &Device,
        rows: Option<&DeviceNodePipelineRows>,
        request: &ResidentRowProgramRequest,
        row_count: usize,
    ) -> Result<(Tensor, Tensor, usize)> {
        let property_load_total = request
            .program
            .instructions
            .iter()
            .filter(|instruction| {
                matches!(
                    &instruction.operation,
                    ResidentRowOperation::InputColumn(_)
                        | ResidentRowOperation::LoadBooleanProperty { .. }
                        | ResidentRowOperation::LoadIntegerProperty { .. }
                        | ResidentRowOperation::LoadFloatProperty { .. }
                        | ResidentRowOperation::LoadStringProperty { .. }
                        | ResidentRowOperation::LoadDateProperty { .. }
                        | ResidentRowOperation::LoadLocalTimeProperty { .. }
                        | ResidentRowOperation::LoadZonedTimeProperty { .. }
                        | ResidentRowOperation::LoadLocalDateTimeProperty { .. }
                        | ResidentRowOperation::LoadZonedDateTimeProperty { .. }
                        | ResidentRowOperation::LoadListProperty { .. }
                        | ResidentRowOperation::LoadDurationAccessor { .. }
                )
            })
            .count();
        let fixed_property_words = metal_row_checked_product(
            metal_row_checked_product(property_load_total, 2, "Metal row input width overflow")?,
            row_count,
            "Metal row input image overflow",
        )?;
        let string_slots = metal_row_string_slots(request, row_count)?;
        let temporal_slots = metal_row_temporal_slots(request, row_count)?;
        let mut property_parts = Vec::new();
        let mut extra_parts = Vec::new();
        let mut extra_cursor = fixed_property_words;
        let named_zone_table = request
            .program
            .instructions
            .iter()
            .filter_map(|instruction| match &instruction.operation {
                ResidentRowOperation::TemporalAccessor {
                    named_zone_table, ..
                } => Some(named_zone_table),
                _ => None,
            })
            .try_fold(None::<&Arc<[u8]>>, |selected, candidate| {
                if selected.is_some_and(|selected| selected.as_ref() != candidate.as_ref()) {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal temporal accessors carry different named-zone rule images",
                    ));
                }
                Ok(Some(selected.unwrap_or(candidate)))
            })?;
        let (named_zone_table_base, named_zone_table_end) = if let Some(named_zone_table) =
            named_zone_table
        {
            let base = extra_cursor;
            if !named_zone_table.is_empty() {
                let words = named_zone_table
                    .iter()
                    .map(|byte| i64::from(*byte))
                    .collect::<Vec<_>>();
                extra_parts
                    .push(Tensor::from_slice(&words, words.len(), device).map_err(candle_error)?);
                extra_cursor = extra_cursor.checked_add(words.len()).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal named-zone row table overflow",
                    )
                })?;
            }
            (base, extra_cursor)
        } else {
            (0, 0)
        };
        let mut property_load_count = 0_usize;
        let mut metadata = Vec::with_capacity(metal_row_metadata_words(request)?);
        for (register, instruction) in request.program.instructions.iter().enumerate() {
            let register = u16::try_from(register).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row register exceeds u16",
                )
            })?;
            let materialized_string = instruction.output_type == ResidentRowValueType::String
                && metal_row_string_register_is_materialized(request, register)?;
            let (slot_base, slot_capacity) = string_slots[register as usize];
            let temporal_slot = temporal_slots[register as usize];
            let (opcode, first, second, third, fourth, fifth, sixth) = match &instruction.operation
            {
                ResidentRowOperation::InputColumn(column) => {
                    if column.len() != row_count {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal resident row input column changed cardinality",
                        ));
                    }
                    if let Some(input) = metal_row_typed_temporal_input(column, device)? {
                        let (ordinal, components) = metal_row_append_temporal_property_input(
                            &mut property_parts,
                            &mut extra_parts,
                            &mut extra_cursor,
                            &mut property_load_count,
                            input,
                        )?;
                        match column {
                            ResidentRowColumn::Date { .. } => {
                                if !components.is_empty() || temporal_slot.1 != 0 {
                                    return Err(Error::internal(
                                        "Metal DATE literal row layout has unexpected sidecars",
                                    ));
                                }
                                (METAL_ROW_OPCODE_LOAD_DATE, ordinal as u64, 0, 0, 0, 0, 0)
                            }
                            ResidentRowColumn::LocalTime { .. } => {
                                if !components.is_empty() || temporal_slot.1 != 0 {
                                    return Err(Error::internal(
                                        "Metal LOCAL TIME literal row layout has unexpected sidecars",
                                    ));
                                }
                                (
                                    METAL_ROW_OPCODE_LOAD_LOCAL_TIME,
                                    ordinal as u64,
                                    0,
                                    0,
                                    0,
                                    0,
                                    0,
                                )
                            }
                            ResidentRowColumn::ZonedTime { .. } => {
                                let [offset_base] = components.as_slice() else {
                                    return Err(Error::internal(
                                        "Metal ZONED TIME literal omitted its offset component",
                                    ));
                                };
                                if temporal_slot.1 != 2 {
                                    return Err(Error::internal(
                                        "Metal ZONED TIME literal omitted its evaluated sidecar",
                                    ));
                                }
                                (
                                    METAL_ROW_OPCODE_LOAD_ZONED_TIME,
                                    ordinal as u64,
                                    *offset_base as u64,
                                    0,
                                    temporal_slot.0 as u64,
                                    0,
                                    0,
                                )
                            }
                            ResidentRowColumn::LocalDateTime { .. } => {
                                let [nanos_base] = components.as_slice() else {
                                    return Err(Error::internal(
                                        "Metal LOCAL DATETIME literal omitted its nanos component",
                                    ));
                                };
                                if temporal_slot.1 != 1 {
                                    return Err(Error::internal(
                                        "Metal LOCAL DATETIME literal omitted its evaluated sidecar",
                                    ));
                                }
                                (
                                    METAL_ROW_OPCODE_LOAD_LOCAL_DATETIME,
                                    ordinal as u64,
                                    *nanos_base as u64,
                                    0,
                                    temporal_slot.0 as u64,
                                    0,
                                    0,
                                )
                            }
                            ResidentRowColumn::ZonedDateTime {
                                timezone_offsets,
                                timezone_bytes,
                                ..
                            } => {
                                let [nanos_base] = components.as_slice() else {
                                    return Err(Error::internal(
                                        "Metal ZONED DATETIME literal omitted its nanos component",
                                    ));
                                };
                                if temporal_slot.1 != 2 {
                                    return Err(Error::internal(
                                        "Metal ZONED DATETIME literal omitted its evaluated sidecar",
                                    ));
                                }
                                let offsets_base = extra_cursor;
                                let offset_words = timezone_offsets
                                    .iter()
                                    .map(|offset| i64::from(*offset))
                                    .collect::<Vec<_>>();
                                extra_parts.push(
                                    Tensor::from_slice(&offset_words, offset_words.len(), device)
                                        .map_err(candle_error)?,
                                );
                                extra_cursor = extra_cursor
                                    .checked_add(offset_words.len())
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal timezone literal offsets overflow",
                                        )
                                    })?;
                                if !timezone_bytes.is_empty() {
                                    let byte_words = timezone_bytes
                                        .iter()
                                        .map(|byte| i64::from(*byte))
                                        .collect::<Vec<_>>();
                                    extra_parts.push(
                                        Tensor::from_slice(&byte_words, byte_words.len(), device)
                                            .map_err(candle_error)?,
                                    );
                                    extra_cursor = extra_cursor
                                        .checked_add(byte_words.len())
                                        .ok_or_else(|| {
                                            Error::new(
                                                ErrorCode::ResultBudgetExceeded,
                                                "Metal timezone literal bytes overflow",
                                            )
                                        })?;
                                }
                                let byte_count =
                                    u32::try_from(timezone_bytes.len()).map_err(|_| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal timezone literal bytes exceed u32",
                                        )
                                    })?;
                                let offsets_base = u32::try_from(offsets_base).map_err(|_| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal timezone literal offsets exceed u32",
                                    )
                                })?;
                                (
                                    METAL_ROW_OPCODE_LOAD_LITERAL_ZONED_DATETIME,
                                    ordinal as u64,
                                    *nanos_base as u64,
                                    (u64::from(byte_count) << 32) | u64::from(offsets_base),
                                    temporal_slot.0 as u64,
                                    u64::from(slot_base),
                                    u64::from(slot_capacity),
                                )
                            }
                            _ => unreachable!("typed temporal input changed after encoding"),
                        }
                    } else {
                        // A scalar continuation after LIMIT 0 owns a canonical zero-row
                        // InputColumn. Metal cannot create a zero-byte buffer, and the evaluator
                        // dispatch is authoritatively empty, so do not manufacture value/validity
                        // tensors that cannot be read. The final one-word property placeholder
                        // below remains the sole command input while the ordinal and metadata keep
                        // the manifest, receipts, and EmptyWindow proof unchanged.
                        if row_count != 0 {
                            let values = match column {
                                ResidentRowColumn::Boolean { values, .. } => values
                                    .iter()
                                    .map(|value| i64::from(*value))
                                    .collect::<Vec<_>>(),
                                ResidentRowColumn::Integer { values, .. } => values.clone(),
                                ResidentRowColumn::Float { bits, .. } => {
                                    bits.iter().map(|bits| *bits as i64).collect()
                                }
                                ResidentRowColumn::String { .. } if materialized_string => (0
                                    ..row_count)
                                    .map(|row| {
                                        i64::try_from(row).map_err(|_| {
                                            Error::new(
                                                ErrorCode::ResultBudgetExceeded,
                                                "Metal string input row exceeds i64",
                                            )
                                        })
                                    })
                                    .collect::<Result<Vec<_>>>()?,
                                ResidentRowColumn::String { .. } => {
                                    metal_row_literal_string_ranks(column)?
                                }
                                ResidentRowColumn::List { .. } => (0..row_count)
                                    .map(|row| {
                                        i64::try_from(row).map_err(|_| {
                                            Error::new(
                                                ErrorCode::ResultBudgetExceeded,
                                                "Metal list input row exceeds i64",
                                            )
                                        })
                                    })
                                    .collect::<Result<Vec<_>>>()?,
                                _ => unreachable!("typed temporal input was not encoded"),
                            };
                            let validity = column
                                .validity()
                                .iter()
                                .map(|valid| i64::from(*valid))
                                .collect::<Vec<_>>();
                            property_parts.extend([
                                Tensor::from_slice(&values, values.len(), device)
                                    .map_err(candle_error)?,
                                Tensor::from_slice(&validity, validity.len(), device)
                                    .map_err(candle_error)?,
                            ]);
                        }
                        let ordinal = property_load_count;
                        property_load_count =
                            property_load_count.checked_add(1).ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal resident row typed-input count overflow",
                                )
                            })?;
                        let opcode = match column.value_type() {
                            ResidentRowValueType::Boolean => METAL_ROW_OPCODE_LOAD_BOOLEAN,
                            ResidentRowValueType::Integer => METAL_ROW_OPCODE_LOAD_INTEGER,
                            ResidentRowValueType::Float => METAL_ROW_OPCODE_LOAD_FLOAT,
                            ResidentRowValueType::String if materialized_string => {
                                METAL_ROW_OPCODE_LOAD_STRING
                            }
                            ResidentRowValueType::String => METAL_ROW_OPCODE_LOAD_STRING_RANK,
                            ResidentRowValueType::List => METAL_ROW_OPCODE_LOAD_LIST_INPUT,
                            _ => unreachable!("typed temporal opcode was not encoded"),
                        };
                        if let ResidentRowColumn::List {
                            offsets,
                            values,
                            element_validity,
                            ..
                        } = column
                        {
                            let offsets_base = extra_cursor;
                            let offset_words = offsets
                                .iter()
                                .map(|offset| i64::from(*offset))
                                .collect::<Vec<_>>();
                            extra_parts.push(
                                Tensor::from_slice(&offset_words, offset_words.len(), device)
                                    .map_err(candle_error)?,
                            );
                            extra_cursor = extra_cursor
                                .checked_add(offset_words.len())
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal list input offsets overflow",
                                    )
                                })?;
                            let values_base = extra_cursor;
                            if !values.is_empty() {
                                extra_parts.push(
                                    Tensor::from_slice(values, values.len(), device)
                                        .map_err(candle_error)?,
                                );
                                extra_cursor =
                                    extra_cursor.checked_add(values.len()).ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal list input values overflow",
                                        )
                                    })?;
                            }
                            let element_validity_base = extra_cursor;
                            if !element_validity.is_empty() {
                                let words = element_validity
                                    .iter()
                                    .map(|valid| i64::from(*valid))
                                    .collect::<Vec<_>>();
                                extra_parts.push(
                                    Tensor::from_slice(&words, words.len(), device)
                                        .map_err(candle_error)?,
                                );
                                extra_cursor =
                                    extra_cursor.checked_add(words.len()).ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal list input validity overflow",
                                        )
                                    })?;
                            }
                            let expected_capacity = request
                                .program
                                .list_register_capacity(register)?
                                .ok_or_else(|| {
                                    Error::internal("Metal list input capacity disappeared")
                                })?
                                .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal list input byte capacity overflow",
                                    )
                                })?;
                            if slot_capacity as usize != expected_capacity {
                                return Err(Error::internal(
                                    "Metal list input slot differs from its admitted capacity",
                                ));
                            }
                            (
                                opcode,
                                ordinal as u64,
                                offsets_base as u64,
                                values_base as u64,
                                element_validity_base as u64,
                                u64::from(slot_base),
                                u64::from(slot_capacity),
                            )
                        } else if let ResidentRowColumn::String { offsets, bytes, .. } = column
                            && materialized_string
                        {
                            let offsets_base = extra_cursor;
                            let offset_words = offsets
                                .iter()
                                .map(|offset| i64::from(*offset))
                                .collect::<Vec<_>>();
                            if !offset_words.is_empty() {
                                extra_parts.push(
                                    Tensor::from_slice(&offset_words, offset_words.len(), device)
                                        .map_err(candle_error)?,
                                );
                                extra_cursor = extra_cursor
                                    .checked_add(offset_words.len())
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal string input offsets overflow",
                                        )
                                    })?;
                            }
                            let bytes_base = extra_cursor;
                            if !bytes.is_empty() {
                                let byte_words = bytes
                                    .iter()
                                    .map(|byte| i64::from(*byte))
                                    .collect::<Vec<_>>();
                                extra_parts.push(
                                    Tensor::from_slice(&byte_words, byte_words.len(), device)
                                        .map_err(candle_error)?,
                                );
                                extra_cursor = extra_cursor
                                    .checked_add(byte_words.len())
                                    .ok_or_else(|| {
                                        Error::new(
                                            ErrorCode::ResultBudgetExceeded,
                                            "Metal string input bytes overflow",
                                        )
                                    })?;
                            }
                            (
                                opcode,
                                ordinal as u64,
                                offsets_base as u64,
                                bytes_base as u64,
                                u64::from(slot_base),
                                u64::from(slot_capacity),
                                ((row_count as u64) << 32) | bytes.len() as u64,
                            )
                        } else {
                            (opcode, ordinal as u64, 0, 0, 0, 0, 0)
                        }
                    }
                }
                ResidentRowOperation::LoadBooleanProperty { binding, property } => {
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal graph-property load has no graph row source")
                    })?;
                    let (values, validity) = self.metal_row_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::Boolean,
                        false,
                        device,
                    )?;
                    property_parts.extend([values, validity]);
                    let ordinal = property_load_count;
                    property_load_count = property_load_count.checked_add(1).ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal resident row property-input count overflow",
                        )
                    })?;
                    (METAL_ROW_OPCODE_LOAD_BOOLEAN, ordinal as u64, 0, 0, 0, 0, 0)
                }
                ResidentRowOperation::LoadIntegerProperty { binding, property } => {
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal graph-property load has no graph row source")
                    })?;
                    let (values, validity) = self.metal_row_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::Integer,
                        false,
                        device,
                    )?;
                    property_parts.extend([values, validity]);
                    let ordinal = property_load_count;
                    property_load_count = property_load_count.checked_add(1).ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal resident row property-input count overflow",
                        )
                    })?;
                    (METAL_ROW_OPCODE_LOAD_INTEGER, ordinal as u64, 0, 0, 0, 0, 0)
                }
                ResidentRowOperation::LoadFloatProperty { binding, property } => {
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal graph-property load has no graph row source")
                    })?;
                    let (values, validity) = self.metal_row_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::Float,
                        false,
                        device,
                    )?;
                    property_parts.extend([values, validity]);
                    let ordinal = property_load_count;
                    property_load_count = property_load_count.checked_add(1).ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal resident row property-input count overflow",
                        )
                    })?;
                    (METAL_ROW_OPCODE_LOAD_FLOAT, ordinal as u64, 0, 0, 0, 0, 0)
                }
                ResidentRowOperation::LoadStringProperty {
                    binding,
                    property,
                    maximum_bytes,
                } => {
                    let actual_maximum = match binding {
                        super::ResidentEntityBinding::Node(_) => self.string_nodes.get(property),
                        super::ResidentEntityBinding::Relationship(_) => {
                            self.string_edges.get(property)
                        }
                    }
                    .map_or(0, |column| column.maximum_bytes);
                    if actual_maximum != *maximum_bytes as usize {
                        return Err(Error::new(
                            ErrorCode::GpuAdmissionFailure,
                            "resident row string property maximum UTF-8 width does not match the resident dictionary",
                        ));
                    }
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal graph-property load has no graph row source")
                    })?;
                    let (values, validity) = self.metal_row_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::String,
                        materialized_string,
                        device,
                    )?;
                    property_parts.extend([values, validity]);
                    let ordinal = property_load_count;
                    property_load_count = property_load_count.checked_add(1).ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal resident row property-input count overflow",
                        )
                    })?;
                    if materialized_string {
                        if slot_capacity != *maximum_bytes {
                            return Err(Error::internal(
                                "Metal string property slot differs from its admitted maximum",
                            ));
                        }
                        let opcode = match binding {
                            super::ResidentEntityBinding::Node(_) => {
                                METAL_ROW_OPCODE_LOAD_NODE_STRING
                            }
                            super::ResidentEntityBinding::Relationship(_) => {
                                METAL_ROW_OPCODE_LOAD_EDGE_STRING
                            }
                        };
                        (
                            opcode,
                            ordinal as u64,
                            0,
                            0,
                            u64::from(slot_base),
                            u64::from(slot_capacity),
                            0,
                        )
                    } else {
                        (
                            METAL_ROW_OPCODE_LOAD_STRING_RANK,
                            ordinal as u64,
                            0,
                            0,
                            0,
                            0,
                            0,
                        )
                    }
                }
                ResidentRowOperation::LoadDateProperty { binding, property } => {
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal temporal property load has no graph row source")
                    })?;
                    let input = self.metal_row_temporal_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::Date,
                        device,
                    )?;
                    let (ordinal, components) = metal_row_append_temporal_property_input(
                        &mut property_parts,
                        &mut extra_parts,
                        &mut extra_cursor,
                        &mut property_load_count,
                        input,
                    )?;
                    if !components.is_empty() || temporal_slot.1 != 0 {
                        return Err(Error::internal(
                            "Metal date row layout has unexpected sidecars",
                        ));
                    }
                    (METAL_ROW_OPCODE_LOAD_DATE, ordinal as u64, 0, 0, 0, 0, 0)
                }
                ResidentRowOperation::LoadLocalTimeProperty { binding, property } => {
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal temporal property load has no graph row source")
                    })?;
                    let input = self.metal_row_temporal_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::LocalTime,
                        device,
                    )?;
                    let (ordinal, components) = metal_row_append_temporal_property_input(
                        &mut property_parts,
                        &mut extra_parts,
                        &mut extra_cursor,
                        &mut property_load_count,
                        input,
                    )?;
                    if !components.is_empty() || temporal_slot.1 != 0 {
                        return Err(Error::internal(
                            "Metal local-time row layout has unexpected sidecars",
                        ));
                    }
                    (
                        METAL_ROW_OPCODE_LOAD_LOCAL_TIME,
                        ordinal as u64,
                        0,
                        0,
                        0,
                        0,
                        0,
                    )
                }
                ResidentRowOperation::LoadZonedTimeProperty { binding, property } => {
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal temporal property load has no graph row source")
                    })?;
                    let input = self.metal_row_temporal_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::ZonedTime,
                        device,
                    )?;
                    let (ordinal, components) = metal_row_append_temporal_property_input(
                        &mut property_parts,
                        &mut extra_parts,
                        &mut extra_cursor,
                        &mut property_load_count,
                        input,
                    )?;
                    let [offset_base] = components.as_slice() else {
                        return Err(Error::internal(
                            "Metal zoned-time row layout omitted its offset component",
                        ));
                    };
                    if temporal_slot.1 != 2 {
                        return Err(Error::internal(
                            "Metal zoned-time row layout omitted its evaluated sidecar",
                        ));
                    }
                    (
                        METAL_ROW_OPCODE_LOAD_ZONED_TIME,
                        ordinal as u64,
                        *offset_base as u64,
                        0,
                        temporal_slot.0 as u64,
                        0,
                        0,
                    )
                }
                ResidentRowOperation::LoadLocalDateTimeProperty { binding, property } => {
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal temporal property load has no graph row source")
                    })?;
                    let input = self.metal_row_temporal_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::LocalDateTime,
                        device,
                    )?;
                    let (ordinal, components) = metal_row_append_temporal_property_input(
                        &mut property_parts,
                        &mut extra_parts,
                        &mut extra_cursor,
                        &mut property_load_count,
                        input,
                    )?;
                    let [nanos_base] = components.as_slice() else {
                        return Err(Error::internal(
                            "Metal local-datetime row layout omitted its nanos component",
                        ));
                    };
                    if temporal_slot.1 != 1 {
                        return Err(Error::internal(
                            "Metal local-datetime row layout omitted its evaluated sidecar",
                        ));
                    }
                    (
                        METAL_ROW_OPCODE_LOAD_LOCAL_DATETIME,
                        ordinal as u64,
                        *nanos_base as u64,
                        0,
                        temporal_slot.0 as u64,
                        0,
                        0,
                    )
                }
                ResidentRowOperation::LoadZonedDateTimeProperty {
                    binding,
                    property,
                    maximum_timezone_bytes,
                } => {
                    let actual_maximum = match binding {
                        super::ResidentEntityBinding::Node(_) => {
                            self.zoned_datetime_nodes.get(property)
                        }
                        super::ResidentEntityBinding::Relationship(_) => {
                            self.zoned_datetime_edges.get(property)
                        }
                    }
                    .map_or(0, |column| column.maximum_timezone_bytes);
                    if actual_maximum != *maximum_timezone_bytes as usize
                        || slot_capacity != *maximum_timezone_bytes
                    {
                        return Err(Error::new(
                            ErrorCode::GpuAdmissionFailure,
                            "resident zoned-datetime timezone width does not match the resident dictionary",
                        ));
                    }
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal temporal property load has no graph row source")
                    })?;
                    let input = self.metal_row_temporal_property_input(
                        rows,
                        *binding,
                        *property,
                        ResidentRowValueType::ZonedDateTime,
                        device,
                    )?;
                    let (ordinal, components) = metal_row_append_temporal_property_input(
                        &mut property_parts,
                        &mut extra_parts,
                        &mut extra_cursor,
                        &mut property_load_count,
                        input,
                    )?;
                    let [nanos_base, timezone_id_base] = components.as_slice() else {
                        return Err(Error::internal(
                            "Metal zoned-datetime row layout omitted canonical components",
                        ));
                    };
                    if temporal_slot.1 != 2 {
                        return Err(Error::internal(
                            "Metal zoned-datetime row layout omitted its evaluated sidecar",
                        ));
                    }
                    let opcode = match binding {
                        super::ResidentEntityBinding::Node(_) => {
                            METAL_ROW_OPCODE_LOAD_NODE_ZONED_DATETIME
                        }
                        super::ResidentEntityBinding::Relationship(_) => {
                            METAL_ROW_OPCODE_LOAD_EDGE_ZONED_DATETIME
                        }
                    };
                    (
                        opcode,
                        ordinal as u64,
                        *nanos_base as u64,
                        *timezone_id_base as u64,
                        temporal_slot.0 as u64,
                        u64::from(slot_base),
                        u64::from(slot_capacity),
                    )
                }
                ResidentRowOperation::LoadListProperty {
                    binding,
                    property,
                    maximum_elements,
                } => {
                    let rows = rows.ok_or_else(|| {
                        Error::internal("Metal list property load has no graph row source")
                    })?;
                    let (values, validity, offsets, bytes, source_rows, byte_count) =
                        self.metal_row_list_property_input(rows, *binding, *property, device)?;
                    property_parts.extend([values, validity]);
                    let ordinal = property_load_count;
                    property_load_count = property_load_count.checked_add(1).ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal resident row list-input count overflow",
                        )
                    })?;
                    let offsets_base = extra_cursor;
                    extra_cursor =
                        extra_cursor
                            .checked_add(offsets.elem_count())
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal list property offsets overflow",
                                )
                            })?;
                    extra_parts.push(offsets);
                    let bytes_base = extra_cursor;
                    if let Some(bytes) = bytes {
                        extra_cursor =
                            extra_cursor
                                .checked_add(bytes.elem_count())
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::ResultBudgetExceeded,
                                        "Metal list property bytes overflow",
                                    )
                                })?;
                        extra_parts.push(bytes);
                    }
                    let expected_capacity = usize::try_from(*maximum_elements)
                        .ok()
                        .and_then(|elements| elements.checked_mul(METAL_ROW_LIST_ELEMENT_BYTES))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal list property byte capacity overflow",
                            )
                        })?;
                    if slot_capacity as usize != expected_capacity {
                        return Err(Error::internal(
                            "Metal list property slot differs from its admitted capacity",
                        ));
                    }
                    let source_rows = u32::try_from(source_rows).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal list property source rows exceed u32",
                        )
                    })?;
                    let byte_count = u32::try_from(byte_count).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal list property bytes exceed u32",
                        )
                    })?;
                    (
                        METAL_ROW_OPCODE_LOAD_LIST_PROPERTY,
                        ordinal as u64,
                        offsets_base as u64,
                        bytes_base as u64,
                        (u64::from(source_rows) << 32) | u64::from(byte_count),
                        u64::from(slot_base),
                        u64::from(slot_capacity),
                    )
                }
                ResidentRowOperation::BooleanConstant(value) => (
                    METAL_ROW_OPCODE_BOOLEAN_CONSTANT,
                    u64::from(*value),
                    0,
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::IntegerConstant(value) => (
                    METAL_ROW_OPCODE_INTEGER_CONSTANT,
                    *value as u64,
                    0,
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::FloatConstant(bits) => {
                    (METAL_ROW_OPCODE_FLOAT_CONSTANT, *bits, 0, 0, 0, 0, 0)
                }
                ResidentRowOperation::StringConstant(value) => {
                    let literal_base = extra_cursor;
                    if !value.is_empty() {
                        let words = value
                            .as_bytes()
                            .iter()
                            .map(|byte| i64::from(*byte))
                            .collect::<Vec<_>>();
                        extra_parts.push(
                            Tensor::from_slice(&words, words.len(), device)
                                .map_err(candle_error)?,
                        );
                        extra_cursor = extra_cursor.checked_add(words.len()).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal string literal bytes overflow",
                            )
                        })?;
                    }
                    (
                        METAL_ROW_OPCODE_STRING_CONSTANT,
                        literal_base as u64,
                        value.len() as u64,
                        0,
                        u64::from(slot_base),
                        u64::from(slot_capacity),
                        0,
                    )
                }
                ResidentRowOperation::BooleanNot { operand } => (
                    METAL_ROW_OPCODE_BOOLEAN_NOT,
                    u64::from(*operand),
                    0,
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::BooleanAnd { left, right } => (
                    METAL_ROW_OPCODE_BOOLEAN_AND,
                    u64::from(*left),
                    u64::from(*right),
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::NumericAdd { left, right } => (
                    METAL_ROW_OPCODE_NUMERIC_ADD,
                    u64::from(*left),
                    u64::from(*right),
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::NumericSubtract { left, right } => (
                    METAL_ROW_OPCODE_NUMERIC_SUBTRACT,
                    u64::from(*left),
                    u64::from(*right),
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::NumericMultiply { left, right } => (
                    METAL_ROW_OPCODE_NUMERIC_MULTIPLY,
                    u64::from(*left),
                    u64::from(*right),
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::IntegerModulo { left, right } => (
                    METAL_ROW_OPCODE_INTEGER_MODULO,
                    u64::from(*left),
                    u64::from(*right),
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::NumericNegate { operand } => (
                    METAL_ROW_OPCODE_NUMERIC_NEGATE,
                    u64::from(*operand),
                    0,
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::TemporalAddDuration {
                    temporal,
                    months,
                    days,
                    seconds,
                    nanos,
                } => {
                    let expected_lanes = metal_row_temporal_sidecar_lanes(instruction.output_type);
                    if temporal_slot.1 != expected_lanes {
                        return Err(Error::internal(
                            "Metal temporal-duration result has an invalid sidecar layout",
                        ));
                    }
                    let sidecar_base = u32::try_from(temporal_slot.0).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal temporal-duration sidecar exceeds u32",
                        )
                    })?;
                    let packed_sidecar = (u64::from(*nanos as u32) << 32) | u64::from(sidecar_base);
                    let timezone_capacity =
                        if instruction.output_type == ResidentRowValueType::ZonedDateTime {
                            u64::from(slot_capacity)
                        } else {
                            0
                        };
                    (
                        METAL_ROW_OPCODE_TEMPORAL_ADD_DURATION,
                        u64::from(*temporal),
                        *months as u64,
                        *days as u64,
                        packed_sidecar,
                        *seconds as u64,
                        timezone_capacity,
                    )
                }
                ResidentRowOperation::StringConcat { left, right } => {
                    if !materialized_string {
                        return Err(Error::internal(
                            "Metal string concatenation was not assigned an arena slot",
                        ));
                    }
                    (
                        METAL_ROW_OPCODE_STRING_CONCAT,
                        u64::from(*left),
                        u64::from(*right),
                        0,
                        u64::from(slot_base),
                        u64::from(slot_capacity),
                        0,
                    )
                }
                ResidentRowOperation::StringCoalesce { left, right } => {
                    if !materialized_string {
                        return Err(Error::internal(
                            "Metal string coalesce was not assigned an arena slot",
                        ));
                    }
                    (
                        METAL_ROW_OPCODE_STRING_COALESCE,
                        u64::from(*left),
                        u64::from(*right),
                        0,
                        u64::from(slot_base),
                        u64::from(slot_capacity),
                        0,
                    )
                }
                ResidentRowOperation::BooleanToString { operand } => {
                    if !materialized_string || slot_capacity != 5 {
                        return Err(Error::internal(
                            "Metal Boolean-to-string conversion was not assigned its exact arena slot",
                        ));
                    }
                    (
                        METAL_ROW_OPCODE_BOOLEAN_TO_STRING,
                        u64::from(*operand),
                        0,
                        0,
                        u64::from(slot_base),
                        u64::from(slot_capacity),
                        0,
                    )
                }
                ResidentRowOperation::List { elements } => {
                    let elements_base = extra_cursor;
                    if !elements.is_empty() {
                        let words = elements
                            .iter()
                            .map(|register| i64::from(*register))
                            .collect::<Vec<_>>();
                        extra_parts.push(
                            Tensor::from_slice(&words, words.len(), device)
                                .map_err(candle_error)?,
                        );
                        extra_cursor = extra_cursor.checked_add(words.len()).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal list-construction metadata overflow",
                            )
                        })?;
                    }
                    (
                        METAL_ROW_OPCODE_LIST_BUILD,
                        elements_base as u64,
                        elements.len() as u64,
                        0,
                        0,
                        u64::from(slot_base),
                        u64::from(slot_capacity),
                    )
                }
                ResidentRowOperation::ListIndex { list, index } => (
                    METAL_ROW_OPCODE_LIST_INDEX,
                    u64::from(*list),
                    u64::from(*index),
                    0,
                    0,
                    0,
                    0,
                ),
                ResidentRowOperation::ListConcat { left, right } => (
                    METAL_ROW_OPCODE_LIST_CONCAT,
                    u64::from(*left),
                    u64::from(*right),
                    0,
                    0,
                    u64::from(slot_base),
                    u64::from(slot_capacity),
                ),
                ResidentRowOperation::TemporalAccessor {
                    temporal,
                    accessor,
                    maximum_string_bytes,
                    ..
                } => (
                    METAL_ROW_OPCODE_TEMPORAL_ACCESSOR,
                    u64::from(*temporal),
                    u64::from(*accessor as u8),
                    named_zone_table_base as u64,
                    named_zone_table_end as u64,
                    u64::from(slot_base),
                    u64::from(*maximum_string_bytes),
                ),
                ResidentRowOperation::LoadDurationAccessor {
                    binding,
                    property,
                    accessor,
                } => {
                    let Some(rows) = rows else {
                        return Err(Error::internal(
                            "Metal duration property accessor has no graph input rows",
                        ));
                    };
                    let input =
                        self.metal_row_duration_property_input(rows, *binding, *property, device)?;
                    let (ordinal, components) = metal_row_append_temporal_property_input(
                        &mut property_parts,
                        &mut extra_parts,
                        &mut extra_cursor,
                        &mut property_load_count,
                        input,
                    )?;
                    let [days, seconds, nanos] = components.as_slice() else {
                        return Err(Error::internal(
                            "Metal duration accessor omitted canonical components",
                        ));
                    };
                    (
                        METAL_ROW_OPCODE_LOAD_DURATION_ACCESSOR,
                        ordinal as u64,
                        *days as u64,
                        *seconds as u64,
                        *nanos as u64,
                        u64::from(*accessor as u8),
                        0,
                    )
                }
            };
            metadata.extend([
                opcode as i64,
                instruction.output_type as u8 as i64,
                first as i64,
                second as i64,
                third as i64,
                fourth as i64,
                fifth as i64,
                sixth as i64,
            ]);
        }
        if property_load_count != property_load_total {
            return Err(Error::internal(
                "Metal resident row property-input count changed during encoding",
            ));
        }
        metadata.extend(
            request
                .final_registers
                .iter()
                .map(|register| i64::from(*register)),
        );
        for obligation in request.obligations() {
            let super::ResidentObligationScope::Expression(index) = obligation.scope else {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal resident row manifest uses a non-expression scope",
                ));
            };
            metadata.extend([
                obligation.id as i64,
                obligation.kind as u8 as i64,
                METAL_ROW_SCOPE_EXPRESSION as i64,
                i64::from(index),
            ]);
        }
        if metadata.len() != metal_row_metadata_words(request)? {
            return Err(Error::internal(
                "Metal resident row metadata encoder produced an invalid shape",
            ));
        }
        let metadata =
            Tensor::from_slice(&metadata, metadata.len(), device).map_err(candle_error)?;
        property_parts.extend(extra_parts);
        let property_inputs = if property_parts.is_empty() || row_count == 0 {
            Tensor::zeros(1, DType::I64, device).map_err(candle_error)?
        } else {
            let references = property_parts.iter().collect::<Vec<_>>();
            Tensor::cat(&references, 0).map_err(candle_error)?
        };
        Ok((property_inputs, metadata, property_load_count))
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn metal_row_property_input(
        &self,
        rows: &DeviceNodePipelineRows,
        binding: super::ResidentEntityBinding,
        property: PropertyId,
        expected: ResidentRowValueType,
        materialize_string: bool,
        device: &Device,
    ) -> Result<(Tensor, Tensor)> {
        let binding_rows = self.mutation_binding_rows(rows, binding)?;
        let row_count = binding_rows.elem_count();
        if row_count == 0 {
            return Ok((
                Tensor::zeros(0, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(0, DType::I64, device).map_err(candle_error)?,
            ));
        }
        let (
            integers,
            booleans,
            floats,
            strings,
            dates,
            local_times,
            zoned_times,
            local_datetimes,
            zoned_datetimes,
            mixed,
            unsupported,
            string_dictionary,
        ) = match binding {
            super::ResidentEntityBinding::Node(_) => (
                &self.integer_nodes,
                &self.boolean_nodes,
                &self.float_nodes,
                &self.string_nodes,
                &self.date_nodes,
                &self.local_time_nodes,
                &self.zoned_time_nodes,
                &self.local_datetime_nodes,
                &self.zoned_datetime_nodes,
                &self.mixed_nodes,
                &self.unsupported_node_properties,
                &self.node_string_dictionary,
            ),
            super::ResidentEntityBinding::Relationship(_) => (
                &self.integer_edges,
                &self.boolean_edges,
                &self.float_edges,
                &self.string_edges,
                &self.date_edges,
                &self.local_time_edges,
                &self.zoned_time_edges,
                &self.local_datetime_edges,
                &self.zoned_datetime_edges,
                &self.mixed_edges,
                &self.unsupported_edge_properties,
                &self.edge_string_dictionary,
            ),
        };
        let exact_present = match expected {
            ResidentRowValueType::Boolean => booleans.contains_key(&property),
            ResidentRowValueType::Integer => integers.contains_key(&property),
            ResidentRowValueType::Float => floats.contains_key(&property),
            ResidentRowValueType::String => strings.contains_key(&property),
            ResidentRowValueType::Date
            | ResidentRowValueType::LocalTime
            | ResidentRowValueType::ZonedTime
            | ResidentRowValueType::LocalDateTime
            | ResidentRowValueType::ZonedDateTime
            | ResidentRowValueType::List => false,
        };
        let any_present = integers.contains_key(&property)
            || booleans.contains_key(&property)
            || floats.contains_key(&property)
            || strings.contains_key(&property)
            || dates.contains_key(&property)
            || local_times.contains_key(&property)
            || zoned_times.contains_key(&property)
            || local_datetimes.contains_key(&property)
            || zoned_datetimes.contains_key(&property)
            || mixed.contains_key(&property)
            || unsupported.contains(&property);
        if any_present && !exact_present {
            return Err(Error::new(
                ErrorCode::QueryType,
                "resident typed-row property load does not match the canonical property shape",
            ));
        }
        if !any_present {
            return Ok((
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
            ));
        }

        let row_validity = binding_rows
            .ne(super::RESIDENT_NULL_ROW)
            .map_err(candle_error)?;
        let safe_rows = row_validity
            .where_cond(
                binding_rows,
                &Tensor::zeros(binding_rows.shape(), DType::U32, device).map_err(candle_error)?,
            )
            .map_err(candle_error)?;
        let (values, validity) = match expected {
            ResidentRowValueType::Boolean => {
                let column = booleans.get(&property).ok_or_else(|| {
                    Error::internal("validated resident Boolean property column disappeared")
                })?;
                let values = column
                    .values
                    .as_ref()
                    .ok_or_else(|| Error::internal("resident Boolean values are absent"))?
                    .index_select(&safe_rows, 0)
                    .and_then(|values| values.to_dtype(DType::I64))
                    .map_err(candle_error)?;
                let validity = column
                    .validity
                    .as_ref()
                    .ok_or_else(|| Error::internal("resident Boolean validity is absent"))?
                    .index_select(&safe_rows, 0)
                    .and_then(|validity| validity.broadcast_mul(&row_validity))
                    .and_then(|validity| validity.to_dtype(DType::I64))
                    .map_err(candle_error)?;
                (values, validity)
            }
            ResidentRowValueType::Integer => {
                let column = integers.get(&property).ok_or_else(|| {
                    Error::internal("validated resident integer property column disappeared")
                })?;
                let values = column
                    .values
                    .as_ref()
                    .ok_or_else(|| Error::internal("resident integer values are absent"))?
                    .index_select(&safe_rows, 0)
                    .map_err(candle_error)?;
                let validity = column
                    .validity
                    .as_ref()
                    .ok_or_else(|| Error::internal("resident integer validity is absent"))?
                    .index_select(&safe_rows, 0)
                    .and_then(|validity| validity.broadcast_mul(&row_validity))
                    .and_then(|validity| validity.to_dtype(DType::I64))
                    .map_err(candle_error)?;
                (values, validity)
            }
            ResidentRowValueType::Float => {
                let column = floats.get(&property).ok_or_else(|| {
                    Error::internal("validated resident float property column disappeared")
                })?;
                let values = column
                    .values
                    .as_ref()
                    .ok_or_else(|| Error::internal("resident float values are absent"))?
                    .index_select(&safe_rows, 0)
                    .map_err(candle_error)?;
                let validity = column
                    .validity
                    .as_ref()
                    .ok_or_else(|| Error::internal("resident float validity is absent"))?
                    .index_select(&safe_rows, 0)
                    .and_then(|validity| validity.broadcast_mul(&row_validity))
                    .and_then(|validity| validity.to_dtype(DType::I64))
                    .map_err(candle_error)?;
                (values, validity)
            }
            ResidentRowValueType::String => {
                let column = strings.get(&property).ok_or_else(|| {
                    Error::internal("validated resident string property column disappeared")
                })?;
                let ids = column
                    .values
                    .as_ref()
                    .ok_or_else(|| Error::internal("resident string IDs are absent"))?
                    .index_select(&safe_rows, 0)
                    .map_err(candle_error)?;
                let validity = column
                    .validity
                    .as_ref()
                    .ok_or_else(|| Error::internal("resident string validity is absent"))?
                    .index_select(&safe_rows, 0)
                    .and_then(|validity| validity.broadcast_mul(&row_validity))
                    .map_err(candle_error)?;
                let values = if materialize_string {
                    ids.to_dtype(DType::I64).map_err(candle_error)?
                } else {
                    if let Some(dictionary_ranks) = &string_dictionary.ranks {
                        let safe_ids = validity
                            .eq(1_u8)
                            .and_then(|present| {
                                present.where_cond(
                                    &ids,
                                    &Tensor::zeros(ids.shape(), DType::U32, device)?,
                                )
                            })
                            .map_err(candle_error)?;
                        dictionary_ranks
                            .index_select(&safe_ids, 0)
                            .and_then(|ranks| ranks.to_dtype(DType::I64))
                            .map_err(candle_error)?
                    } else {
                        Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?
                    }
                };
                let validity = validity.to_dtype(DType::I64).map_err(candle_error)?;
                (values, validity)
            }
            ResidentRowValueType::Date
            | ResidentRowValueType::LocalTime
            | ResidentRowValueType::ZonedTime
            | ResidentRowValueType::LocalDateTime
            | ResidentRowValueType::ZonedDateTime => {
                return Err(Error::internal(
                    "Metal temporal property reached the scalar property loader",
                ));
            }
            ResidentRowValueType::List => {
                return Err(Error::internal(
                    "Metal list property reached the scalar property loader",
                ));
            }
        };
        Ok((values, validity))
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn metal_row_list_property_input(
        &self,
        rows: &DeviceNodePipelineRows,
        binding: super::ResidentEntityBinding,
        property: PropertyId,
        device: &Device,
    ) -> Result<(Tensor, Tensor, Tensor, Option<Tensor>, usize, usize)> {
        let binding_rows = self.mutation_binding_rows(rows, binding)?;
        let row_count = binding_rows.elem_count();
        let (lists, maps, mixed, unsupported, any_scalar) = match binding {
            super::ResidentEntityBinding::Node(_) => (
                &self.list_nodes,
                &self.map_nodes,
                &self.mixed_nodes,
                &self.unsupported_node_properties,
                self.integer_nodes.contains_key(&property)
                    || self.boolean_nodes.contains_key(&property)
                    || self.float_nodes.contains_key(&property)
                    || self.string_nodes.contains_key(&property)
                    || self.date_nodes.contains_key(&property)
                    || self.local_time_nodes.contains_key(&property)
                    || self.zoned_time_nodes.contains_key(&property)
                    || self.local_datetime_nodes.contains_key(&property)
                    || self.zoned_datetime_nodes.contains_key(&property)
                    || self.duration_nodes.contains_key(&property),
            ),
            super::ResidentEntityBinding::Relationship(_) => (
                &self.list_edges,
                &self.map_edges,
                &self.mixed_edges,
                &self.unsupported_edge_properties,
                self.integer_edges.contains_key(&property)
                    || self.boolean_edges.contains_key(&property)
                    || self.float_edges.contains_key(&property)
                    || self.string_edges.contains_key(&property)
                    || self.date_edges.contains_key(&property)
                    || self.local_time_edges.contains_key(&property)
                    || self.zoned_time_edges.contains_key(&property)
                    || self.local_datetime_edges.contains_key(&property)
                    || self.zoned_datetime_edges.contains_key(&property)
                    || self.duration_edges.contains_key(&property),
            ),
        };
        let Some(column) = lists.get(&property) else {
            if any_scalar
                || maps.contains_key(&property)
                || mixed.contains_key(&property)
                || unsupported.contains(&property)
            {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "resident list property load does not match the canonical property shape",
                ));
            }
            return Ok((
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(1, DType::I64, device).map_err(candle_error)?,
                None,
                0,
                0,
            ));
        };
        if column.offsets.elem_count() != column.rows.saturating_add(1) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident list property offsets have an invalid row shape",
            ));
        }
        let row_validity = binding_rows
            .ne(super::RESIDENT_NULL_ROW)
            .map_err(candle_error)?;
        let safe_rows = row_validity
            .where_cond(
                binding_rows,
                &Tensor::zeros(binding_rows.shape(), DType::U32, device).map_err(candle_error)?,
            )
            .map_err(candle_error)?;
        let validity = column
            .validity
            .as_ref()
            .ok_or_else(|| Error::internal("resident list validity is absent"))?
            .index_select(&safe_rows, 0)
            .and_then(|validity| validity.broadcast_mul(&row_validity))
            .and_then(|validity| validity.to_dtype(DType::I64))
            .map_err(candle_error)?;
        let source_rows = safe_rows.to_dtype(DType::I64).map_err(candle_error)?;
        let offsets = column.offsets.to_dtype(DType::I64).map_err(candle_error)?;
        let bytes = column
            .bytes
            .as_ref()
            .map(|bytes| bytes.to_dtype(DType::I64).map_err(candle_error))
            .transpose()?;
        let byte_count = bytes.as_ref().map_or(0, Tensor::elem_count);
        Ok((
            source_rows,
            validity,
            offsets,
            bytes,
            column.rows,
            byte_count,
        ))
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn metal_row_temporal_property_input(
        &self,
        rows: &DeviceNodePipelineRows,
        binding: super::ResidentEntityBinding,
        property: PropertyId,
        expected: ResidentRowValueType,
        device: &Device,
    ) -> Result<MetalRowTemporalPropertyInput> {
        if !matches!(
            expected,
            ResidentRowValueType::Date
                | ResidentRowValueType::LocalTime
                | ResidentRowValueType::ZonedTime
                | ResidentRowValueType::LocalDateTime
                | ResidentRowValueType::ZonedDateTime
        ) {
            return Err(Error::internal(
                "Metal temporal property loader received a non-temporal type",
            ));
        }
        let binding_rows = self.mutation_binding_rows(rows, binding)?;
        let row_count = binding_rows.elem_count();
        let (
            integers,
            booleans,
            floats,
            strings,
            dates,
            local_times,
            zoned_times,
            local_datetimes,
            zoned_datetimes,
            mixed,
            unsupported,
        ) = match binding {
            super::ResidentEntityBinding::Node(_) => (
                &self.integer_nodes,
                &self.boolean_nodes,
                &self.float_nodes,
                &self.string_nodes,
                &self.date_nodes,
                &self.local_time_nodes,
                &self.zoned_time_nodes,
                &self.local_datetime_nodes,
                &self.zoned_datetime_nodes,
                &self.mixed_nodes,
                &self.unsupported_node_properties,
            ),
            super::ResidentEntityBinding::Relationship(_) => (
                &self.integer_edges,
                &self.boolean_edges,
                &self.float_edges,
                &self.string_edges,
                &self.date_edges,
                &self.local_time_edges,
                &self.zoned_time_edges,
                &self.local_datetime_edges,
                &self.zoned_datetime_edges,
                &self.mixed_edges,
                &self.unsupported_edge_properties,
            ),
        };
        let exact_present = match expected {
            ResidentRowValueType::Date => dates.contains_key(&property),
            ResidentRowValueType::LocalTime => local_times.contains_key(&property),
            ResidentRowValueType::ZonedTime => zoned_times.contains_key(&property),
            ResidentRowValueType::LocalDateTime => local_datetimes.contains_key(&property),
            ResidentRowValueType::ZonedDateTime => zoned_datetimes.contains_key(&property),
            _ => false,
        };
        let any_present = integers.contains_key(&property)
            || booleans.contains_key(&property)
            || floats.contains_key(&property)
            || strings.contains_key(&property)
            || dates.contains_key(&property)
            || local_times.contains_key(&property)
            || zoned_times.contains_key(&property)
            || local_datetimes.contains_key(&property)
            || zoned_datetimes.contains_key(&property)
            || mixed.contains_key(&property)
            || unsupported.contains(&property);
        if any_present && !exact_present {
            return Err(Error::new(
                ErrorCode::QueryType,
                "resident temporal row property load does not match the canonical property shape",
            ));
        }

        let component_count = match expected {
            ResidentRowValueType::Date | ResidentRowValueType::LocalTime => 0,
            ResidentRowValueType::ZonedTime | ResidentRowValueType::LocalDateTime => 1,
            ResidentRowValueType::ZonedDateTime => 2,
            _ => unreachable!("validated temporal type changed"),
        };
        if row_count == 0 || !any_present {
            let primary = Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?;
            let validity = Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?;
            let components = (0..component_count)
                .map(|_| Tensor::zeros(row_count, DType::I64, device).map_err(candle_error))
                .collect::<Result<Vec<_>>>()?;
            return Ok(MetalRowTemporalPropertyInput {
                primary,
                validity,
                components,
            });
        }

        let row_validity = binding_rows
            .ne(super::RESIDENT_NULL_ROW)
            .map_err(candle_error)?;
        let safe_rows = row_validity
            .where_cond(
                binding_rows,
                &Tensor::zeros(binding_rows.shape(), DType::U32, device).map_err(candle_error)?,
            )
            .map_err(candle_error)?;
        let gather_validity = |validity: &Option<Tensor>| -> Result<Tensor> {
            validity
                .as_ref()
                .ok_or_else(|| Error::internal("resident temporal validity is absent"))?
                .index_select(&safe_rows, 0)
                .and_then(|validity| validity.broadcast_mul(&row_validity))
                .and_then(|validity| validity.to_dtype(DType::I64))
                .map_err(candle_error)
        };
        let gather_i64 = |values: &Option<Tensor>, detail: &'static str| -> Result<Tensor> {
            values
                .as_ref()
                .ok_or_else(|| Error::internal(detail))?
                .index_select(&safe_rows, 0)
                .and_then(|values| values.to_dtype(DType::I64))
                .map_err(candle_error)
        };
        let validate_column =
            |rows: usize, tensors: &[(&Option<Tensor>, DType, &'static str)]| -> Result<()> {
                for (tensor, dtype, detail) in tensors {
                    match tensor {
                        Some(tensor)
                            if tensor.rank() == 1
                                && tensor.dtype() == *dtype
                                && tensor.elem_count() == rows => {}
                        None if rows == 0 => {}
                        _ => {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                format!("resident temporal {detail} has an invalid shape"),
                            ));
                        }
                    }
                }
                Ok(())
            };

        match expected {
            ResidentRowValueType::Date => {
                let column = dates.get(&property).ok_or_else(|| {
                    Error::internal("validated resident date property column disappeared")
                })?;
                Ok(MetalRowTemporalPropertyInput {
                    primary: gather_i64(&column.values, "resident date values are absent")?,
                    validity: gather_validity(&column.validity)?,
                    components: Vec::new(),
                })
            }
            ResidentRowValueType::LocalTime => {
                let column = local_times.get(&property).ok_or_else(|| {
                    Error::internal("validated resident local-time property column disappeared")
                })?;
                Ok(MetalRowTemporalPropertyInput {
                    primary: gather_i64(&column.values, "resident local-time values are absent")?,
                    validity: gather_validity(&column.validity)?,
                    components: Vec::new(),
                })
            }
            ResidentRowValueType::ZonedTime => {
                let column = zoned_times.get(&property).ok_or_else(|| {
                    Error::internal("validated resident zoned-time property column disappeared")
                })?;
                validate_column(
                    column.rows,
                    &[
                        (&column.nanos, DType::I64, "zoned-time nanos"),
                        (&column.offsets, DType::I64, "zoned-time offsets"),
                        (&column.validity, DType::U8, "zoned-time validity"),
                    ],
                )?;
                Ok(MetalRowTemporalPropertyInput {
                    primary: gather_i64(&column.nanos, "resident zoned-time nanos are absent")?,
                    validity: gather_validity(&column.validity)?,
                    components: vec![gather_i64(
                        &column.offsets,
                        "resident zoned-time offsets are absent",
                    )?],
                })
            }
            ResidentRowValueType::LocalDateTime => {
                let column = local_datetimes.get(&property).ok_or_else(|| {
                    Error::internal("validated resident local-datetime property column disappeared")
                })?;
                validate_column(
                    column.rows,
                    &[
                        (&column.seconds, DType::I64, "local-datetime seconds"),
                        (&column.nanos, DType::U32, "local-datetime nanos"),
                        (&column.validity, DType::U8, "local-datetime validity"),
                    ],
                )?;
                Ok(MetalRowTemporalPropertyInput {
                    primary: gather_i64(
                        &column.seconds,
                        "resident local-datetime seconds are absent",
                    )?,
                    validity: gather_validity(&column.validity)?,
                    components: vec![gather_i64(
                        &column.nanos,
                        "resident local-datetime nanos are absent",
                    )?],
                })
            }
            ResidentRowValueType::ZonedDateTime => {
                let column = zoned_datetimes.get(&property).ok_or_else(|| {
                    Error::internal("validated resident zoned-datetime property column disappeared")
                })?;
                validate_column(
                    column.rows,
                    &[
                        (&column.seconds, DType::I64, "zoned-datetime seconds"),
                        (&column.nanos, DType::U32, "zoned-datetime nanos"),
                        (&column.timezones, DType::U32, "zoned-datetime timezone IDs"),
                        (&column.validity, DType::U8, "zoned-datetime validity"),
                    ],
                )?;
                Ok(MetalRowTemporalPropertyInput {
                    primary: gather_i64(
                        &column.seconds,
                        "resident zoned-datetime seconds are absent",
                    )?,
                    validity: gather_validity(&column.validity)?,
                    components: vec![
                        gather_i64(&column.nanos, "resident zoned-datetime nanos are absent")?,
                        gather_i64(
                            &column.timezones,
                            "resident zoned-datetime timezone IDs are absent",
                        )?,
                    ],
                })
            }
            _ => Err(Error::internal(
                "validated temporal property type changed during gather",
            )),
        }
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn metal_row_duration_property_input(
        &self,
        rows: &DeviceNodePipelineRows,
        binding: super::ResidentEntityBinding,
        property: PropertyId,
        device: &Device,
    ) -> Result<MetalRowTemporalPropertyInput> {
        let binding_rows = self.mutation_binding_rows(rows, binding)?;
        let row_count = binding_rows.elem_count();
        let (durations, any_other, mixed, unsupported) = match binding {
            super::ResidentEntityBinding::Node(_) => (
                &self.duration_nodes,
                self.integer_nodes.contains_key(&property)
                    || self.boolean_nodes.contains_key(&property)
                    || self.float_nodes.contains_key(&property)
                    || self.string_nodes.contains_key(&property)
                    || self.date_nodes.contains_key(&property)
                    || self.local_time_nodes.contains_key(&property)
                    || self.zoned_time_nodes.contains_key(&property)
                    || self.local_datetime_nodes.contains_key(&property)
                    || self.zoned_datetime_nodes.contains_key(&property)
                    || self.list_nodes.contains_key(&property)
                    || self.map_nodes.contains_key(&property),
                &self.mixed_nodes,
                &self.unsupported_node_properties,
            ),
            super::ResidentEntityBinding::Relationship(_) => (
                &self.duration_edges,
                self.integer_edges.contains_key(&property)
                    || self.boolean_edges.contains_key(&property)
                    || self.float_edges.contains_key(&property)
                    || self.string_edges.contains_key(&property)
                    || self.date_edges.contains_key(&property)
                    || self.local_time_edges.contains_key(&property)
                    || self.zoned_time_edges.contains_key(&property)
                    || self.local_datetime_edges.contains_key(&property)
                    || self.zoned_datetime_edges.contains_key(&property)
                    || self.list_edges.contains_key(&property)
                    || self.map_edges.contains_key(&property),
                &self.mixed_edges,
                &self.unsupported_edge_properties,
            ),
        };
        let Some(column) = durations.get(&property) else {
            if any_other || mixed.contains_key(&property) || unsupported.contains(&property) {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "resident duration accessor does not match the canonical property shape",
                ));
            }
            return Ok(MetalRowTemporalPropertyInput {
                primary: Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                validity: Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                components: (0..3)
                    .map(|_| Tensor::zeros(row_count, DType::I64, device).map_err(candle_error))
                    .collect::<Result<Vec<_>>>()?,
            });
        };
        for (tensor, dtype, detail) in [
            (&column.months, DType::I64, "months"),
            (&column.days, DType::I64, "days"),
            (&column.seconds, DType::I64, "seconds"),
            (&column.nanos, DType::I64, "nanoseconds"),
            (&column.validity, DType::U8, "validity"),
        ] {
            if !matches!(tensor, Some(tensor) if tensor.rank() == 1
                && tensor.dtype() == dtype && tensor.elem_count() == column.rows)
            {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    format!("resident duration {detail} has an invalid shape"),
                ));
            }
        }
        let row_validity = binding_rows
            .ne(super::RESIDENT_NULL_ROW)
            .map_err(candle_error)?;
        let safe_rows = row_validity
            .where_cond(
                binding_rows,
                &Tensor::zeros(binding_rows.shape(), DType::U32, device).map_err(candle_error)?,
            )
            .map_err(candle_error)?;
        let gather = |tensor: &Option<Tensor>, detail: &'static str| -> Result<Tensor> {
            tensor
                .as_ref()
                .ok_or_else(|| Error::internal(detail))?
                .index_select(&safe_rows, 0)
                .and_then(|values| values.to_dtype(DType::I64))
                .map_err(candle_error)
        };
        let validity = column
            .validity
            .as_ref()
            .ok_or_else(|| Error::internal("resident duration validity is absent"))?
            .index_select(&safe_rows, 0)
            .and_then(|validity| validity.broadcast_mul(&row_validity))
            .and_then(|validity| validity.to_dtype(DType::I64))
            .map_err(candle_error)?;
        Ok(MetalRowTemporalPropertyInput {
            primary: gather(&column.months, "resident duration months are absent")?,
            validity,
            components: vec![
                gather(&column.days, "resident duration days are absent")?,
                gather(&column.seconds, "resident duration seconds are absent")?,
                gather(&column.nanos, "resident duration nanoseconds are absent")?,
            ],
        })
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    pub fn execute_pattern_count(
        &self,
        device: &Device,
        request: &super::ResidentPatternCountRequest,
        cancellation: &CancellationToken,
    ) -> Result<super::ResidentPatternCountResult> {
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native resident pattern counts require a Metal device",
            ));
        };
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        if request.project != self.project {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident pattern count targets a different project image",
            ));
        }
        if self.bookmark != request.expected_bookmark
            || self.revision != request.expected_graph_revision
            || self.layout_version != request.expected_layout_version
            || self.node_count != request.node_slots
            || self.edge_count != request.edge_slots
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident pattern count expected a different bookmark, graph revision, layout, or dense-row generation",
            ));
        }

        let (node_rows, counts, traversal_cardinality) =
            if let super::ResidentPatternCountStartLabels::Known(labels) = &request.start_labels {
                let visible_mask = self.node_selection_mask(labels, request.layers)?;
                let visible_rows =
                    selected_positions(&visible_mask, self.node_count, device, cancellation)?;
                if visible_rows.elem_count() > request.max_output_rows {
                    return Err(Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident pattern count exceeded its output row budget",
                    ));
                }
                let count_values = if visible_rows.elem_count() == 0
                    || matches!(
                        request.relationship_types,
                        super::ResidentPatternRelationshipTypes::Never
                    ) {
                    Vec::new()
                } else {
                    let relationship_types = match &request.relationship_types {
                        super::ResidentPatternRelationshipTypes::Any => Vec::new(),
                        super::ResidentPatternRelationshipTypes::Known(types) => types.clone(),
                        super::ResidentPatternRelationshipTypes::Never => unreachable!(
                            "known-empty relationship domain was handled before Metal expansion"
                        ),
                    };
                    let (expanded_starts, _edges, _ends) = self.expand_pipeline_rows(
                        device,
                        &visible_rows,
                        &super::ResidentExpansion {
                            direction: request.direction,
                            relationship_types,
                            end_labels: Vec::new(),
                            end_equals_start: false,
                            optional: false,
                            end_predicates: Vec::new(),
                        },
                        request.layers,
                        request.maximum_traversal_rows()?,
                        cancellation,
                    )?;
                    scatter_counts(&expanded_starts, self.node_count, device)?
                        .index_select(&visible_rows, 0)
                        .and_then(|values| values.to_vec1::<u32>())
                        .map_err(candle_error)?
                };
                let node_rows = visible_rows.to_vec1::<u32>().map_err(candle_error)?;
                let counts = if node_rows.is_empty() {
                    Vec::new()
                } else if count_values.is_empty() {
                    vec![0; node_rows.len()]
                } else {
                    count_values
                };
                let traversal_cardinality = counts.iter().try_fold(0_u64, |total, count| {
                    total.checked_add(u64::from(*count)).ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal resident pattern-count total overflow",
                        )
                    })
                })?;
                (node_rows, counts, traversal_cardinality)
            } else {
                (Vec::new(), Vec::new(), 0)
            };
        ensure_not_cancelled(cancellation)?;
        let output_cardinality = node_rows.len() as u64;
        let completion = super::ResidentDeviceCompletion::Metal;
        let receipts = vec![
            super::ResidentExecutionReceipt {
                execution: request.execution,
                obligation: request.scan_obligation,
                input_cardinality: request.node_slots as u64,
                output_cardinality,
                completion,
            },
            super::ResidentExecutionReceipt {
                execution: request.execution,
                obligation: request.traversal_obligation,
                input_cardinality: output_cardinality,
                output_cardinality: traversal_cardinality,
                completion,
            },
            super::ResidentExecutionReceipt {
                execution: request.execution,
                obligation: request.final_obligation,
                input_cardinality: output_cardinality,
                output_cardinality,
                completion,
            },
        ];
        Ok(super::ResidentPatternCountResult::completed(
            request,
            self.bookmark,
            self.revision,
            self.layout_version,
            node_rows,
            counts,
            receipts,
        ))
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    pub fn metal_pattern_predicate_scratch_bytes(
        &self,
        request: &super::ResidentPatternPredicateRequest,
    ) -> Result<usize> {
        let base = request.scratch_bytes()?;
        let property_lanes = resident_pattern_property_ids(&request.program).len();
        if property_lanes == 0 {
            return Ok(base);
        }
        let rows = self.node_count.max(1);
        let bank_values = property_lanes
            .checked_mul(rows)
            .and_then(|cells| cells.checked_mul(std::mem::size_of::<i64>()))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal pattern property-value bank shape overflow",
                )
            })?;
        let bank_validity = property_lanes.checked_mul(rows).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal pattern property-validity bank shape overflow",
            )
        })?;
        let null_values = rows
            .checked_mul(std::mem::size_of::<i64>())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal pattern null property-value lane shape overflow",
                )
            })?;
        [bank_values, bank_validity, null_values, rows]
            .into_iter()
            .try_fold(base, |total, bytes| {
                total
                    .checked_add(super::resident_pattern_private_buffer_bytes(bytes)?)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal pattern property-bank scratch shape overflow",
                        )
                    })
            })
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn metal_pattern_property_bank(
        &self,
        program: &super::ResidentPatternPredicateProgram,
        device: &Device,
        i64_dummy: &Tensor,
        u8_dummy: &Tensor,
    ) -> Result<(Tensor, Tensor, usize)> {
        let properties = resident_pattern_property_ids(program);
        if properties.is_empty() {
            return Ok((i64_dummy.clone(), u8_dummy.clone(), 0));
        }
        let rows = self.node_count.max(1);
        let null_values = Tensor::zeros(rows, DType::I64, device).map_err(candle_error)?;
        let null_validity = Tensor::zeros(rows, DType::U8, device).map_err(candle_error)?;
        let mut values = Vec::with_capacity(properties.len());
        let mut validity = Vec::with_capacity(properties.len());
        for property in &properties {
            if let Some(column) = self.integer_nodes.get(property) {
                if column.rows != self.node_count {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident pattern integer property row count changed",
                    ));
                }
                if self.node_count == 0 {
                    values.push(i64_dummy.clone());
                    validity.push(u8_dummy.clone());
                } else {
                    values.push(column.values.clone().ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident pattern integer property lost its value tensor",
                        )
                    })?);
                    validity.push(column.validity.clone().ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident pattern integer property lost its validity tensor",
                        )
                    })?);
                }
                continue;
            }
            let incompatible = self.boolean_nodes.contains_key(property)
                || self.float_nodes.contains_key(property)
                || self.string_nodes.contains_key(property)
                || self.date_nodes.contains_key(property)
                || self.local_time_nodes.contains_key(property)
                || self.zoned_time_nodes.contains_key(property)
                || self.local_datetime_nodes.contains_key(property)
                || self.zoned_datetime_nodes.contains_key(property)
                || self.duration_nodes.contains_key(property)
                || self.mixed_nodes.contains_key(property)
                || self.list_nodes.contains_key(property)
                || self.map_nodes.contains_key(property)
                || self.opaque_node_validity.contains_key(property)
                || self.unsupported_node_properties.contains(property)
                || self.vectors.contains_key(property);
            if incompatible {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "resident pattern property equality requires integer node columns",
                ));
            }
            // A catalog token with no canonical values is one all-null lane. Cypher equality
            // cannot be true for any edge, but the query remains natively executable.
            values.push(null_values.clone());
            validity.push(null_validity.clone());
        }
        let values = if values.len() == 1 {
            values[0].clone()
        } else {
            Tensor::cat(&values.iter().collect::<Vec<_>>(), 0).map_err(candle_error)?
        };
        let validity = if validity.len() == 1 {
            validity[0].clone()
        } else {
            Tensor::cat(&validity.iter().collect::<Vec<_>>(), 0).map_err(candle_error)?
        };
        Ok((values, validity, properties.len()))
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    pub fn execute_pattern_predicate(
        &self,
        device: &Device,
        request: &super::ResidentPatternPredicateRequest,
        cancellation: &CancellationToken,
    ) -> Result<super::ResidentPatternPredicateResult> {
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native resident pattern predicates require a Metal device",
            ));
        };
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        if request.project != self.project {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident pattern predicate targets a different project image",
            ));
        }
        if self.bookmark != request.expected_bookmark
            || self.revision != request.expected_graph_revision
            || self.layout_version != request.expected_layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident pattern predicate expected a different bookmark, graph revision, or layout version",
            ));
        }
        let (row_count, source_mode, scan_obligation_id) = match &request.input {
            super::ResidentPatternPredicateInput::Rows(rows) => {
                if rows.iter().any(|row| *row as usize >= self.node_count) {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "resident pattern predicate outer row is out of bounds",
                    ));
                }
                (rows.len(), 0_u32, 0_u64)
            }
            super::ResidentPatternPredicateInput::VisibleNodeScan {
                node_slots,
                obligation,
            } => {
                if *node_slots != self.node_count {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "resident pattern scan node-slot count does not match the resident image",
                    ));
                }
                (*node_slots, 1, obligation.id)
            }
        };
        if source_mode == 1 && scan_obligation_id == 0 {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident pattern scan requires a non-zero obligation ID",
            ));
        }
        let packet_words = encode_metal_pattern_predicate(&request.program)?;
        let input_rows = match &request.input {
            super::ResidentPatternPredicateInput::Rows(rows) if !rows.is_empty() => {
                Tensor::from_slice(rows, rows.len(), device).map_err(candle_error)?
            }
            super::ResidentPatternPredicateInput::Rows(_)
            | super::ResidentPatternPredicateInput::VisibleNodeScan { .. } => {
                // Fused scans never upload candidate IDs. Metal still requires one non-empty
                // placeholder buffer for the typed CustomOp input, including a zero-slot image.
                Tensor::zeros(1, DType::U32, device).map_err(candle_error)?
            }
        };
        let packet =
            Tensor::from_slice(&packet_words, packet_words.len(), device).map_err(candle_error)?;
        let u32_dummy = Tensor::zeros(1, DType::U32, device).map_err(candle_error)?;
        let u8_dummy = Tensor::zeros(1, DType::U8, device).map_err(candle_error)?;
        let i64_dummy = Tensor::zeros(1, DType::I64, device).map_err(candle_error)?;
        let node_active = resident_pattern_column(
            self.node_active.as_ref(),
            self.node_count,
            &u8_dummy,
            "node active",
        )?;
        let node_layers = resident_pattern_column(
            self.node_layers.as_ref(),
            self.node_count,
            &u8_dummy,
            "node layer",
        )?;
        let edge_active = resident_pattern_column(
            self.edge_active.as_ref(),
            self.edge_count,
            &u8_dummy,
            "relationship active",
        )?;
        let edge_layers = resident_pattern_column(
            self.edge_layers.as_ref(),
            self.edge_count,
            &u8_dummy,
            "relationship layer",
        )?;
        let edge_types = resident_pattern_column(
            self.edge_types.as_ref(),
            self.edge_count,
            &i64_dummy,
            "relationship type",
        )?;
        let (property_values, property_validity, property_lane_count) =
            self.metal_pattern_property_bank(&request.program, device, &i64_dummy, &u8_dummy)?;
        let output = input_rows
            .apply_op2_no_bwd(
                &packet,
                &MetalResidentPatternPredicate {
                    outgoing_offsets: self.outgoing_offsets.clone(),
                    outgoing_neighbors: self
                        .outgoing_neighbors
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    outgoing_edges: self
                        .outgoing_edges
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    incoming_offsets: self.incoming_offsets.clone(),
                    incoming_neighbors: self
                        .incoming_neighbors
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    incoming_edges: self
                        .incoming_edges
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    outgoing_overlay: self
                        .outgoing_overlay
                        .packet
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    incoming_overlay: self
                        .incoming_overlay
                        .packet
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    node_active,
                    node_layers,
                    edge_active,
                    edge_layers,
                    edge_types,
                    property_values,
                    property_validity,
                    execution: request.program.execution,
                    bookmark: request.expected_bookmark,
                    graph_revision: request.expected_graph_revision,
                    layout_version: request.expected_layout_version,
                    scan_obligation_id,
                    source_mode,
                    row_count,
                    node_count: self.node_count,
                    edge_count: self.edge_count,
                    outgoing_overlay_count: self.outgoing_overlay.rows.len(),
                    incoming_overlay_count: self.incoming_overlay.rows.len(),
                    leaf_count: request.program.leaves.len(),
                    instruction_count: request.program.instructions.len(),
                    packet_word_count: packet_words.len(),
                    property_lane_count,
                    layer_mask: request.layers.bits(),
                    output_capacity: request.max_output_rows,
                },
            )
            .map_err(candle_error)?;
        let words = output.to_vec1::<i64>().map_err(candle_error)?;
        ensure_not_cancelled(cancellation)?;
        decode_metal_pattern_predicate(&words, request)
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    pub fn execute_pattern_predicate_pairs(
        &self,
        device: &Device,
        request: &super::ResidentPatternPairPredicateRequest,
        cancellation: &CancellationToken,
    ) -> Result<super::ResidentPatternPairPredicateResult> {
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native resident paired pattern predicates require a Metal device",
            ));
        };
        ensure_not_cancelled(cancellation)?;
        request.validate()?;
        if request.project != self.project {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident paired pattern predicate targets a different project image",
            ));
        }
        if self.bookmark != request.expected_bookmark
            || self.revision != request.expected_graph_revision
            || self.layout_version != request.expected_layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident paired pattern predicate expected a different bookmark, graph revision, or layout version",
            ));
        }
        if request.input.node_slots != self.node_count {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident paired pattern node-slot count does not match the resident image",
            ));
        }
        let pair_count = request.logical_pair_domain()?;
        let pair_chunk_rows = request.pair_chunk_rows()?;
        let packet_words = encode_metal_pattern_pair_predicate(&request.program)?;
        let dummy = Tensor::zeros(1, DType::U32, device).map_err(candle_error)?;
        let packet =
            Tensor::from_slice(&packet_words, packet_words.len(), device).map_err(candle_error)?;
        let u32_dummy = dummy.clone();
        let u8_dummy = Tensor::zeros(1, DType::U8, device).map_err(candle_error)?;
        let i64_dummy = Tensor::zeros(1, DType::I64, device).map_err(candle_error)?;
        let node_active = resident_pattern_column(
            self.node_active.as_ref(),
            self.node_count,
            &u8_dummy,
            "paired node active",
        )?;
        let node_layers = resident_pattern_column(
            self.node_layers.as_ref(),
            self.node_count,
            &u8_dummy,
            "paired node layer",
        )?;
        let edge_active = resident_pattern_column(
            self.edge_active.as_ref(),
            self.edge_count,
            &u8_dummy,
            "paired relationship active",
        )?;
        let edge_layers = resident_pattern_column(
            self.edge_layers.as_ref(),
            self.edge_count,
            &u8_dummy,
            "paired relationship layer",
        )?;
        let edge_types = resident_pattern_column(
            self.edge_types.as_ref(),
            self.edge_count,
            &i64_dummy,
            "paired relationship type",
        )?;
        let output = dummy
            .apply_op2_no_bwd(
                &packet,
                &MetalResidentPatternPairPredicate {
                    outgoing_offsets: self.outgoing_offsets.clone(),
                    outgoing_neighbors: self
                        .outgoing_neighbors
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    outgoing_edges: self
                        .outgoing_edges
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    incoming_offsets: self.incoming_offsets.clone(),
                    incoming_neighbors: self
                        .incoming_neighbors
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    incoming_edges: self
                        .incoming_edges
                        .clone()
                        .unwrap_or_else(|| u32_dummy.clone()),
                    node_active,
                    node_layers,
                    edge_active,
                    edge_layers,
                    edge_types,
                    execution: request.program.execution,
                    bookmark: request.expected_bookmark,
                    graph_revision: request.expected_graph_revision,
                    layout_version: request.expected_layout_version,
                    n_scan_obligation_id: request.input.n_obligation.id,
                    m_scan_obligation_id: request.input.m_obligation.id,
                    cartesian_obligation_id: request.input.cartesian_obligation.id,
                    pair_count,
                    pair_chunk_rows,
                    node_count: self.node_count,
                    edge_count: self.edge_count,
                    packet_word_count: packet_words.len(),
                    layer_mask: request.layers.bits(),
                    output_capacity: request.max_output_pairs,
                    traversal_word_count: request.traversal_words_per_pair()?,
                    uses_traversal_frontier: request.program.leaf.length
                        == super::ResidentPatternPairPredicateLength::OneOrMoreReachable,
                },
            )
            .map_err(candle_error)?;
        let words = output.to_vec1::<i64>().map_err(candle_error)?;
        ensure_not_cancelled(cancellation)?;
        decode_metal_pattern_pair_predicate(&words, request)
    }

    fn mutation_binding_rows<'a>(
        &self,
        rows: &'a DeviceNodePipelineRows,
        binding: super::ResidentEntityBinding,
    ) -> Result<&'a Tensor> {
        match binding {
            super::ResidentEntityBinding::Node(binding) => rows.binding(binding),
            super::ResidentEntityBinding::Relationship(index) => rows
                .relationships
                .get(index as usize)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::QueryType,
                        "resident relationship binding is absent from the device mutation row stream",
                    )
                }),
        }
    }

    fn mutation_entity_fields(
        &self,
        rows: &DeviceNodePipelineRows,
        binding: super::ResidentEntityBinding,
        device: &Device,
    ) -> Result<MetalMutationEntityFields> {
        let binding_rows = self.mutation_binding_rows(rows, binding)?;
        let row_count = binding_rows.elem_count();
        let validity = binding_rows
            .ne(super::RESIDENT_NULL_ROW)
            .and_then(|value| value.to_dtype(DType::I64))
            .map_err(candle_error)?;
        let safe_rows = validity
            .eq(1_i64)
            .and_then(|present| {
                present.where_cond(
                    binding_rows,
                    &Tensor::zeros(binding_rows.shape(), DType::U32, device)?,
                )
            })
            .map_err(candle_error)?;
        let (kind, ids) = match binding {
            super::ResidentEntityBinding::Node(_) => {
                (EntityKind::Node as i64, self.node_entity_ids.as_ref())
            }
            super::ResidentEntityBinding::Relationship(_) => (
                EntityKind::Relationship as i64,
                self.edge_entity_ids.as_ref(),
            ),
        };
        let ids = if row_count == 0 {
            Tensor::zeros(0, DType::I64, device).map_err(candle_error)?
        } else {
            let fallback;
            let ids = match ids {
                Some(ids) => ids,
                None => {
                    fallback = Tensor::zeros(1, DType::I64, device).map_err(candle_error)?;
                    &fallback
                }
            };
            ids.index_select(&safe_rows, 0).map_err(candle_error)?
        };
        Ok(MetalMutationEntityFields {
            validity,
            kind: Tensor::full(kind, row_count, device).map_err(candle_error)?,
            ids,
            safe_rows,
        })
    }

    fn mutation_property_column(
        &self,
        binding: super::ResidentEntityBinding,
        property: PropertyId,
    ) -> Result<Option<MetalMutationPropertyColumn<'_>>> {
        let (integer, boolean, float, string, mixed, unsupported) = match binding {
            super::ResidentEntityBinding::Node(_) => (
                &self.integer_nodes,
                &self.boolean_nodes,
                &self.float_nodes,
                &self.string_nodes,
                &self.mixed_nodes,
                &self.unsupported_node_properties,
            ),
            super::ResidentEntityBinding::Relationship(_) => (
                &self.integer_edges,
                &self.boolean_edges,
                &self.float_edges,
                &self.string_edges,
                &self.mixed_edges,
                &self.unsupported_edge_properties,
            ),
        };
        if mixed.contains_key(&property) || unsupported.contains(&property) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation property reads require a homogeneous null/Boolean/integer/float/string resident column",
            ));
        }
        let temporal = match binding {
            super::ResidentEntityBinding::Node(_) => {
                self.date_nodes.contains_key(&property)
                    || self.local_time_nodes.contains_key(&property)
                    || self.zoned_time_nodes.contains_key(&property)
                    || self.local_datetime_nodes.contains_key(&property)
                    || self.zoned_datetime_nodes.contains_key(&property)
            }
            super::ResidentEntityBinding::Relationship(_) => {
                self.date_edges.contains_key(&property)
                    || self.local_time_edges.contains_key(&property)
                    || self.zoned_time_edges.contains_key(&property)
                    || self.local_datetime_edges.contains_key(&property)
                    || self.zoned_datetime_edges.contains_key(&property)
            }
        };
        if temporal {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal typed SET effect comparison does not admit temporal destination columns",
            ));
        }
        Ok(integer
            .get(&property)
            .map(MetalMutationPropertyColumn::Integer)
            .or_else(|| {
                boolean
                    .get(&property)
                    .map(MetalMutationPropertyColumn::Boolean)
            })
            .or_else(|| float.get(&property).map(MetalMutationPropertyColumn::Float))
            .or_else(|| {
                string
                    .get(&property)
                    .map(MetalMutationPropertyColumn::String)
            }))
    }

    fn mutation_property_fields(
        &self,
        rows: &DeviceNodePipelineRows,
        binding: super::ResidentEntityBinding,
        property: Option<PropertyId>,
        device: &Device,
    ) -> Result<([Tensor; METAL_MUTATION_TYPED_PROPERTY_FIELDS], bool)> {
        let entity = self.mutation_entity_fields(rows, binding, device)?;
        let row_count = entity.validity.elem_count();
        let zero = || Tensor::zeros(row_count, DType::I64, device).map_err(candle_error);
        let Some(property) = property else {
            return Ok((
                [
                    entity.validity,
                    entity.kind,
                    entity.ids,
                    zero()?,
                    zero()?,
                    zero()?,
                ],
                false,
            ));
        };
        let Some(column) = self.mutation_property_column(binding, property)? else {
            return Ok((
                [
                    entity.validity,
                    entity.kind,
                    entity.ids,
                    zero()?,
                    zero()?,
                    zero()?,
                ],
                false,
            ));
        };
        let (tag, payload, source, validity, reads_string) = match column {
            MetalMutationPropertyColumn::Integer(column) => (
                METAL_MUTATION_VALUE_INTEGER,
                mutation_gather_column(
                    column.values.as_ref(),
                    &entity.safe_rows,
                    row_count,
                    DType::I64,
                    device,
                    "integer",
                )?,
                zero()?,
                mutation_gather_validity(
                    column.validity.as_ref(),
                    &entity.safe_rows,
                    &entity.validity,
                    row_count,
                    device,
                    "integer",
                )?,
                false,
            ),
            MetalMutationPropertyColumn::Boolean(column) => (
                METAL_MUTATION_VALUE_BOOLEAN,
                mutation_gather_column(
                    column.values.as_ref(),
                    &entity.safe_rows,
                    row_count,
                    DType::U8,
                    device,
                    "Boolean",
                )?
                .to_dtype(DType::I64)
                .map_err(candle_error)?,
                zero()?,
                mutation_gather_validity(
                    column.validity.as_ref(),
                    &entity.safe_rows,
                    &entity.validity,
                    row_count,
                    device,
                    "Boolean",
                )?,
                false,
            ),
            MetalMutationPropertyColumn::Float(column) => (
                METAL_MUTATION_VALUE_FLOAT,
                mutation_gather_column(
                    column.values.as_ref(),
                    &entity.safe_rows,
                    row_count,
                    DType::I64,
                    device,
                    "float",
                )?,
                zero()?,
                mutation_gather_validity(
                    column.validity.as_ref(),
                    &entity.safe_rows,
                    &entity.validity,
                    row_count,
                    device,
                    "float",
                )?,
                false,
            ),
            MetalMutationPropertyColumn::String(column) => {
                let dictionary = match binding {
                    super::ResidentEntityBinding::Node(_) => &self.node_string_dictionary,
                    super::ResidentEntityBinding::Relationship(_) => &self.edge_string_dictionary,
                };
                if dictionary.maximum_bytes > METAL_MUTATION_TYPED_MAX_STRING_BYTES {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "resident string property exceeds the bounded Metal mutation value width",
                    ));
                }
                let source = match binding {
                    super::ResidentEntityBinding::Node(_) => METAL_MUTATION_STRING_NODE_DICTIONARY,
                    super::ResidentEntityBinding::Relationship(_) => {
                        METAL_MUTATION_STRING_EDGE_DICTIONARY
                    }
                };
                (
                    METAL_MUTATION_VALUE_STRING,
                    mutation_gather_column(
                        column.values.as_ref(),
                        &entity.safe_rows,
                        row_count,
                        DType::U32,
                        device,
                        "string",
                    )?
                    .to_dtype(DType::I64)
                    .map_err(candle_error)?,
                    Tensor::full(source as i64, row_count, device).map_err(candle_error)?,
                    mutation_gather_validity(
                        column.validity.as_ref(),
                        &entity.safe_rows,
                        &entity.validity,
                        row_count,
                        device,
                        "string",
                    )?,
                    true,
                )
            }
        };
        let tags = validity
            .eq(1_i64)
            .and_then(|present| {
                present.where_cond(
                    &Tensor::full(tag as i64, row_count, device)?,
                    &Tensor::zeros(row_count, DType::I64, device)?,
                )
            })
            .map_err(candle_error)?;
        Ok((
            [
                entity.validity,
                entity.kind,
                entity.ids,
                tags,
                payload,
                source,
            ],
            reads_string,
        ))
    }

    /// Gathers canonical property presence for a static REMOVE entirely through resident device
    /// tensors. Selecting a catalog token is host metadata work; membership remains a device lane
    /// and is never materialized for a host-side semantic decision.
    fn mutation_property_presence(
        &self,
        binding: super::ResidentEntityBinding,
        property: Option<PropertyId>,
        safe_rows: &Tensor,
        entity_validity: &Tensor,
        device: &Device,
    ) -> Result<Tensor> {
        let row_count = safe_rows.elem_count();
        let Some(property) = property else {
            return Tensor::zeros(row_count, DType::I64, device).map_err(candle_error);
        };
        let (validity, unsupported, vector_only): (
            Option<(&Option<Tensor>, &'static str)>,
            bool,
            bool,
        ) = match binding {
            super::ResidentEntityBinding::Node(_) => (
                self.integer_nodes
                    .get(&property)
                    .map(|column| (&column.validity, "integer"))
                    .or_else(|| {
                        self.boolean_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "Boolean"))
                    })
                    .or_else(|| {
                        self.float_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "float"))
                    })
                    .or_else(|| {
                        self.string_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "string"))
                    })
                    .or_else(|| {
                        self.date_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "date"))
                    })
                    .or_else(|| {
                        self.local_time_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "local time"))
                    })
                    .or_else(|| {
                        self.zoned_time_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "zoned time"))
                    })
                    .or_else(|| {
                        self.local_datetime_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "local datetime"))
                    })
                    .or_else(|| {
                        self.zoned_datetime_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "zoned datetime"))
                    })
                    .or_else(|| {
                        self.duration_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "duration"))
                    })
                    .or_else(|| {
                        self.mixed_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "mixed"))
                    })
                    .or_else(|| {
                        self.list_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "list"))
                    })
                    .or_else(|| {
                        self.map_nodes
                            .get(&property)
                            .map(|column| (&column.validity, "map"))
                    })
                    .or_else(|| {
                        self.opaque_node_validity
                            .get(&property)
                            .map(|validity| (validity, "opaque"))
                    }),
                self.unsupported_node_properties.contains(&property),
                self.vectors.contains_key(&property),
            ),
            super::ResidentEntityBinding::Relationship(_) => (
                self.integer_edges
                    .get(&property)
                    .map(|column| (&column.validity, "integer"))
                    .or_else(|| {
                        self.boolean_edges
                            .get(&property)
                            .map(|column| (&column.validity, "Boolean"))
                    })
                    .or_else(|| {
                        self.float_edges
                            .get(&property)
                            .map(|column| (&column.validity, "float"))
                    })
                    .or_else(|| {
                        self.string_edges
                            .get(&property)
                            .map(|column| (&column.validity, "string"))
                    })
                    .or_else(|| {
                        self.date_edges
                            .get(&property)
                            .map(|column| (&column.validity, "date"))
                    })
                    .or_else(|| {
                        self.local_time_edges
                            .get(&property)
                            .map(|column| (&column.validity, "local time"))
                    })
                    .or_else(|| {
                        self.zoned_time_edges
                            .get(&property)
                            .map(|column| (&column.validity, "zoned time"))
                    })
                    .or_else(|| {
                        self.local_datetime_edges
                            .get(&property)
                            .map(|column| (&column.validity, "local datetime"))
                    })
                    .or_else(|| {
                        self.zoned_datetime_edges
                            .get(&property)
                            .map(|column| (&column.validity, "zoned datetime"))
                    })
                    .or_else(|| {
                        self.duration_edges
                            .get(&property)
                            .map(|column| (&column.validity, "duration"))
                    })
                    .or_else(|| {
                        self.mixed_edges
                            .get(&property)
                            .map(|column| (&column.validity, "mixed"))
                    })
                    .or_else(|| {
                        self.list_edges
                            .get(&property)
                            .map(|column| (&column.validity, "list"))
                    })
                    .or_else(|| {
                        self.map_edges
                            .get(&property)
                            .map(|column| (&column.validity, "map"))
                    })
                    .or_else(|| {
                        self.opaque_edge_validity
                            .get(&property)
                            .map(|validity| (validity, "opaque"))
                    }),
                self.unsupported_edge_properties.contains(&property),
                false,
            ),
        };
        if validity.is_none() && (unsupported || vector_only) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal static REMOVE effect comparison does not admit this property shape",
            ));
        }
        let Some((validity, name)) = validity else {
            // The token may exist only on the other entity kind. That is a genuine local no-op.
            return Tensor::zeros(row_count, DType::I64, device).map_err(candle_error);
        };
        mutation_gather_validity(
            validity.as_ref(),
            safe_rows,
            entity_validity,
            row_count,
            device,
            name,
        )
    }

    fn mutation_property_ids(&self, binding: super::ResidentEntityBinding) -> BTreeSet<PropertyId> {
        let mut properties = BTreeSet::new();
        match binding {
            super::ResidentEntityBinding::Node(_) => {
                properties.extend(self.integer_nodes.keys().copied());
                properties.extend(self.boolean_nodes.keys().copied());
                properties.extend(self.float_nodes.keys().copied());
                properties.extend(self.string_nodes.keys().copied());
                properties.extend(self.date_nodes.keys().copied());
                properties.extend(self.local_time_nodes.keys().copied());
                properties.extend(self.zoned_time_nodes.keys().copied());
                properties.extend(self.local_datetime_nodes.keys().copied());
                properties.extend(self.zoned_datetime_nodes.keys().copied());
                properties.extend(self.duration_nodes.keys().copied());
                properties.extend(self.mixed_nodes.keys().copied());
                properties.extend(self.list_nodes.keys().copied());
                properties.extend(self.map_nodes.keys().copied());
                properties.extend(self.opaque_node_validity.keys().copied());
                properties.extend(self.unsupported_node_properties.iter().copied());
                properties.extend(self.vectors.keys().copied());
            }
            super::ResidentEntityBinding::Relationship(_) => {
                properties.extend(self.integer_edges.keys().copied());
                properties.extend(self.boolean_edges.keys().copied());
                properties.extend(self.float_edges.keys().copied());
                properties.extend(self.string_edges.keys().copied());
                properties.extend(self.date_edges.keys().copied());
                properties.extend(self.local_time_edges.keys().copied());
                properties.extend(self.zoned_time_edges.keys().copied());
                properties.extend(self.local_datetime_edges.keys().copied());
                properties.extend(self.zoned_datetime_edges.keys().copied());
                properties.extend(self.duration_edges.keys().copied());
                properties.extend(self.mixed_edges.keys().copied());
                properties.extend(self.list_edges.keys().copied());
                properties.extend(self.map_edges.keys().copied());
                properties.extend(self.opaque_edge_validity.keys().copied());
                properties.extend(self.unsupported_edge_properties.iter().copied());
            }
        }
        properties
    }

    fn mutation_continuation_value_fields(
        &self,
        rows: &DeviceNodePipelineRows,
        source: MetalMutationContinuationValueSource,
        device: &Device,
    ) -> Result<[Tensor; METAL_MUTATION_TYPED_PROPERTY_FIELDS]> {
        match source {
            MetalMutationContinuationValueSource::Property(source) => {
                let (fields, reads_string) =
                    self.mutation_property_fields(rows, source.binding, source.property, device)?;
                if reads_string {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal mutation continuation admits only integer property values",
                    ));
                }
                Ok(fields)
            }
            MetalMutationContinuationValueSource::PropertyIsNotNull(source) => {
                let entity = self.mutation_entity_fields(rows, source.binding, device)?;
                let row_count = entity.validity.elem_count();
                let presence = self.mutation_property_presence(
                    source.binding,
                    source.property,
                    &entity.safe_rows,
                    &entity.validity,
                    device,
                )?;
                Ok([
                    entity.validity,
                    entity.kind,
                    entity.ids,
                    Tensor::full(METAL_MUTATION_VALUE_INTEGER as i64, row_count, device)
                        .map_err(candle_error)?,
                    presence,
                    Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                ])
            }
            MetalMutationContinuationValueSource::PropertyCount(binding) => {
                let entity = self.mutation_entity_fields(rows, binding, device)?;
                let row_count = entity.validity.elem_count();
                let mut count =
                    Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?;
                for property in self.mutation_property_ids(binding) {
                    let presence = self.mutation_property_presence(
                        binding,
                        Some(property),
                        &entity.safe_rows,
                        &entity.validity,
                        device,
                    )?;
                    count = count.add(&presence).map_err(candle_error)?;
                }
                let tags = entity
                    .validity
                    .eq(1_i64)
                    .and_then(|present| {
                        present.where_cond(
                            &Tensor::full(METAL_MUTATION_VALUE_INTEGER as i64, row_count, device)?,
                            &Tensor::zeros(row_count, DType::I64, device)?,
                        )
                    })
                    .map_err(candle_error)?;
                Ok([
                    entity.validity,
                    entity.kind,
                    entity.ids,
                    tags,
                    count,
                    Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                ])
            }
        }
    }

    fn mutation_node_label_membership(
        &self,
        rows: &Tensor,
        label: Option<LabelId>,
        device: &Device,
    ) -> Result<Tensor> {
        let row_count = rows.elem_count();
        let Some(label) = label else {
            return Tensor::zeros(row_count, DType::I64, device).map_err(candle_error);
        };
        let Some(membership) = self.node_labels.get(&label) else {
            // A stable token with no node bitmap can only belong outside this node domain.
            return Tensor::zeros(row_count, DType::I64, device).map_err(candle_error);
        };
        if membership.dtype() != DType::U8 || membership.rank() != 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident node-label membership has an invalid tensor shape",
            ));
        }
        if row_count == 0 {
            return Tensor::zeros(0, DType::I64, device).map_err(candle_error);
        }
        membership
            .index_select(rows, 0)
            .and_then(|values| values.to_dtype(DType::I64))
            .map_err(candle_error)
    }

    fn mutation_dictionary_image(&self, device: &Device) -> Result<(Tensor, [usize; 4])> {
        let node_offsets = self
            .node_string_dictionary
            .offsets
            .to_dtype(DType::I64)
            .map_err(candle_error)?;
        let node_bytes = mutation_i64_bytes(self.node_string_dictionary.bytes.as_ref(), device)?;
        let edge_offsets = self
            .edge_string_dictionary
            .offsets
            .to_dtype(DType::I64)
            .map_err(candle_error)?;
        let edge_bytes = mutation_i64_bytes(self.edge_string_dictionary.bytes.as_ref(), device)?;
        let counts = [
            node_offsets.elem_count(),
            node_bytes.elem_count(),
            edge_offsets.elem_count(),
            edge_bytes.elem_count(),
        ];
        let image = Tensor::cat(&[&node_offsets, &node_bytes, &edge_offsets, &edge_bytes], 0)
            .map_err(candle_error)?;
        Ok((image, counts))
    }

    fn execute_typed_metal_mutation(
        &self,
        device: &Device,
        request: &ResidentNodePipelineRequest,
        rows: &DeviceNodePipelineRows,
        cancellation: &CancellationToken,
    ) -> Result<MetalMutationExecution> {
        let program = request
            .mutation
            .as_ref()
            .ok_or_else(|| Error::internal("resident mutation dispatch has no compiled program"))?;
        if !matches!(device, Device::Metal(_)) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native typed mutation program requires the selected Metal device",
            ));
        }
        if !request.orders.is_empty()
            || (program.continuation.is_none()
                && (request.offset != 0 || request.limit != usize::MAX))
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation selection must remain before result ordering, SKIP, and LIMIT",
            ));
        }
        if program.commands.len() > METAL_MUTATION_TYPED_MAX_COMMANDS
            || program.values.len() > METAL_MUTATION_TYPED_MAX_VALUES
            || !program.commands.iter().all(|command| {
                matches!(
                    command.operation,
                    super::ResidentMutationOperation::SetProperty { .. }
                )
            })
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal typed mutation supports only bounded SET-property command programs",
            ));
        }
        let filter_stages = request.mutation_filter_stages()?;
        if filter_stages
            .iter()
            .copied()
            .any(|stage| !stage.is_selected_row_stage())
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal typed mutation does not yet receipt candidate-local expansion predicates",
            ));
        }
        let filter_cardinalities =
            if rows.mutation_filter_cardinalities.len() == program.filter_obligations.len() {
                rows.mutation_filter_cardinalities.clone()
            } else if rows.row_count() == 0 && rows.mutation_filter_cardinalities.is_empty() {
                vec![(0, 0); program.filter_obligations.len()]
            } else {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal mutation filter execution did not produce an exact cardinality trace",
                ));
            };
        ensure_not_cancelled(cancellation)?;
        let selected_rows = rows.row_count();
        let intent_capacity = selected_rows
            .checked_mul(program.commands.len())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation intent cardinality overflow",
                )
            })?;
        if intent_capacity > program.max_intents || intent_capacity > u32::MAX as usize {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation intent budget exceeded",
            ));
        }

        let mut target_parts = Vec::with_capacity(
            program
                .commands
                .len()
                .saturating_mul(METAL_MUTATION_TYPED_TARGET_FIELDS),
        );
        let mut command_words = Vec::with_capacity(
            program
                .commands
                .len()
                .saturating_mul(METAL_MUTATION_TYPED_COMMAND_WORDS),
        );
        let mut string_possible = false;
        for command in &program.commands {
            let super::ResidentMutationOperation::SetProperty {
                target,
                property_name,
                value,
            } = command.operation
            else {
                return Err(Error::internal(
                    "typed Metal mutation command changed operation after admission",
                ));
            };
            let property = *program
                .property_tokens
                .get(property_name as usize)
                .ok_or_else(|| Error::internal("typed Metal destination token disappeared"))?;
            let (target_fields, reads_string) =
                self.mutation_property_fields(rows, target, property, device)?;
            string_possible |= reads_string;
            target_parts.extend(target_fields);
            let expected_kind = match target {
                super::ResidentEntityBinding::Node(_) => EntityKind::Node,
                super::ResidentEntityBinding::Relationship(_) => EntityKind::Relationship,
            };
            command_words.extend([
                METAL_MUTATION_ACTION_SET_PROPERTY,
                u64::from(property_name),
                u64::from(value),
                u64::from(command.value_start),
                u64::from(command.value_count),
                expected_kind as u64,
            ]);
        }

        let mut property_parts = Vec::new();
        let mut value_words = Vec::with_capacity(
            program
                .values
                .len()
                .saturating_mul(METAL_MUTATION_TYPED_VALUE_WORDS),
        );
        let mut constant_bytes = Vec::new();
        let mut property_input_count = 0_usize;
        for instruction in &program.values {
            match instruction {
                super::ResidentMutationValueInstruction::Constant(value) => {
                    let descriptor = encode_metal_mutation_constant(value, &mut constant_bytes)?;
                    string_possible |= descriptor[1] == METAL_MUTATION_VALUE_STRING;
                    value_words.extend(descriptor);
                }
                super::ResidentMutationValueInstruction::Property {
                    binding,
                    property_name,
                    property,
                } => {
                    let ordinal = property_input_count;
                    property_input_count =
                        property_input_count.checked_add(1).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal mutation property input count overflow",
                            )
                        })?;
                    let (fields, reads_string) =
                        self.mutation_property_fields(rows, *binding, *property, device)?;
                    string_possible |= reads_string;
                    property_parts.extend(fields);
                    value_words.extend([
                        METAL_MUTATION_VALUE_OPCODE_PROPERTY,
                        u64::try_from(ordinal).map_err(|_| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal mutation property input exceeds u64",
                            )
                        })?,
                        u64::from(*property_name),
                        0,
                        0,
                        0,
                        0,
                        0,
                    ]);
                }
                super::ResidentMutationValueInstruction::Add { left, right } => {
                    value_words.extend([
                        METAL_MUTATION_VALUE_OPCODE_ADD,
                        u64::from(*left),
                        u64::from(*right),
                        0,
                        0,
                        0,
                        0,
                        0,
                    ]);
                }
            }
        }
        if constant_bytes.len() > METAL_MUTATION_TYPED_MAX_CONSTANT_BYTES {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation constant byte image exceeds its bound",
            ));
        }

        let mut input_parts = target_parts;
        input_parts.extend(property_parts);
        let input_word_count = selected_rows
            .checked_mul(
                program
                    .commands
                    .len()
                    .checked_mul(METAL_MUTATION_TYPED_TARGET_FIELDS)
                    .and_then(|words| {
                        property_input_count
                            .checked_mul(METAL_MUTATION_TYPED_PROPERTY_FIELDS)
                            .and_then(|property_words| words.checked_add(property_words))
                    })
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal mutation input width overflow",
                        )
                    })?,
            )
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation input image overflow",
                )
            })?;
        let input = mutation_concat_i64(&input_parts, input_word_count, device)?;
        let (dictionary, dictionary_counts) = self.mutation_dictionary_image(device)?;

        let receipt_count = 1_usize
            .checked_add(program.filter_obligations.len())
            .and_then(|count| count.checked_add(program.expression_obligations.len()))
            .and_then(|count| {
                program
                    .commands
                    .len()
                    .checked_mul(2)
                    .and_then(|commands| count.checked_add(commands))
            })
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation receipt count overflow",
                )
            })?;
        let mut receipt_words = Vec::with_capacity(
            receipt_count.saturating_mul(METAL_MUTATION_TYPED_RECEIPT_DESCRIPTOR_WORDS),
        );
        push_metal_mutation_receipt_descriptor(
            &mut receipt_words,
            program.selection_obligation,
            u64::try_from(rows.mutation_selection_input_rows).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation selection input exceeds u64",
                )
            })?,
            u64::try_from(selected_rows).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation selection output exceeds u64",
                )
            })?,
        );
        for (obligation, (input, output)) in program
            .filter_obligations
            .iter()
            .copied()
            .zip(filter_cardinalities)
        {
            push_metal_mutation_receipt_descriptor(
                &mut receipt_words,
                obligation,
                u64::try_from(input).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation filter input exceeds u64",
                    )
                })?,
                u64::try_from(output).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation filter output exceeds u64",
                    )
                })?,
            );
        }
        for obligation in &program.expression_obligations {
            push_metal_mutation_receipt_descriptor(&mut receipt_words, *obligation, 0, 0);
        }
        for command in &program.commands {
            push_metal_mutation_receipt_descriptor(
                &mut receipt_words,
                command.rhs_obligation,
                0,
                0,
            );
            push_metal_mutation_receipt_descriptor(
                &mut receipt_words,
                command.effect_obligation,
                0,
                0,
            );
        }

        let mut program_words = command_words;
        program_words.extend(value_words);
        program_words.extend(receipt_words);
        program_words.extend(constant_bytes.iter().map(|byte| u64::from(*byte)));
        let program_words = program_words
            .into_iter()
            .map(|word| word as i64)
            .collect::<Vec<_>>();
        let program_tensor = Tensor::from_slice(&program_words, program_words.len(), device)
            .map_err(candle_error)?;

        let string_slot_words = if string_possible {
            METAL_MUTATION_TYPED_MAX_STRING_BYTES
        } else {
            0
        };
        let output_payload_words =
            intent_capacity
                .checked_mul(string_slot_words)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation string output capacity overflow",
                    )
                })?;
        let output_words = METAL_MUTATION_TYPED_HEADER_WORDS
            .checked_add(
                receipt_count
                    .checked_mul(METAL_MUTATION_STATIC_RECEIPT_WORDS)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal mutation receipt output overflow",
                        )
                    })?,
            )
            .and_then(|words| {
                intent_capacity
                    .checked_mul(METAL_MUTATION_TYPED_INTENT_WORDS)
                    .and_then(|intents| words.checked_add(intents))
            })
            .and_then(|words| words.checked_add(output_payload_words))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation output shape overflow",
                )
            })?;

        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        {
            let arguments = MetalMutationTypedArgs {
                execution_high: program.execution.high,
                execution_low: program.execution.low,
                row_count: selected_rows as u64,
                output_word_count: output_words as u64,
                input_word_count: input_word_count as u64,
                dictionary_word_count: dictionary.elem_count() as u64,
                program_word_count: program_words.len() as u64,
                command_count: program.commands.len() as u32,
                value_count: program.values.len() as u32,
                property_input_count: property_input_count as u32,
                receipt_count: receipt_count as u32,
                filter_count: program.filter_obligations.len() as u32,
                expression_count: program.expression_obligations.len() as u32,
                intent_capacity: intent_capacity as u32,
                string_slot_words: string_slot_words as u32,
                constant_byte_count: constant_bytes.len() as u32,
                node_dictionary_offset_count: dictionary_counts[0] as u32,
                node_dictionary_byte_count: dictionary_counts[1] as u32,
                edge_dictionary_offset_count: dictionary_counts[2] as u32,
                edge_dictionary_byte_count: dictionary_counts[3] as u32,
            };
            let encoded = input
                .apply_op3_no_bwd(
                    &dictionary,
                    &program_tensor,
                    &MetalMutationTyped {
                        arguments,
                        input_storage_words: input.elem_count(),
                    },
                )
                .map_err(candle_error)?;
            let words = encoded.to_vec1::<i64>().map_err(candle_error)?;
            ensure_not_cancelled(cancellation)?;
            let result = decode_metal_typed_mutation(&words, program)?;
            return Ok(MetalMutationExecution {
                result,
                packet: encoded,
                packet_kind: MetalMutationPacketKind::Typed,
            });
        }
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        {
            let _ = (input, dictionary, program_tensor, output_words);
            Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation kernels are unavailable on this build target",
            ))
        }
    }

    fn execute_static_metal_mutation(
        &self,
        device: &Device,
        request: &ResidentNodePipelineRequest,
        rows: &DeviceNodePipelineRows,
        cancellation: &CancellationToken,
    ) -> Result<MetalMutationExecution> {
        let program = request
            .mutation
            .as_ref()
            .ok_or_else(|| Error::internal("resident mutation dispatch has no compiled program"))?;
        let document_set = program.exact_document_constant_set();
        let target = match program.commands.first().map(|command| &command.operation) {
            Some(super::ResidentMutationOperation::AddLabels { target, .. })
            | Some(super::ResidentMutationOperation::RemoveLabels { target, .. }) => {
                super::ResidentEntityBinding::Node(*target)
            }
            Some(super::ResidentMutationOperation::RemoveProperty { target, .. }) => *target,
            Some(super::ResidentMutationOperation::SetProperty { target, .. })
                if document_set.is_some() =>
            {
                *target
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal static mutation requires a label, property removal, or sealed document SET command",
                ));
            }
        };
        let node_shape = target
            == super::ResidentEntityBinding::Node(super::ResidentNodeBinding::Start)
            && request.expansion.is_none()
            && rows.nodes.len() == 1
            && rows.relationships.is_empty()
            && program.commands.iter().all(|command| {
                matches!(
                    command.operation,
                    super::ResidentMutationOperation::AddLabels {
                        target: super::ResidentNodeBinding::Start,
                        ..
                    } | super::ResidentMutationOperation::RemoveLabels {
                        target: super::ResidentNodeBinding::Start,
                        ..
                    } | super::ResidentMutationOperation::RemoveProperty {
                        target: super::ResidentEntityBinding::Node(
                            super::ResidentNodeBinding::Start
                        ),
                        ..
                    }
                )
            });
        let relationship_shape = matches!(target, super::ResidentEntityBinding::Relationship(_))
            && request.expansion.is_some()
            && request.continuations.is_empty()
            && request.correlated_optional.is_none()
            && rows.nodes.len() >= 2
            && program.commands.iter().all(|command| {
                matches!(
                    command.operation,
                    super::ResidentMutationOperation::RemoveProperty {
                        target: command_target,
                        ..
                    } if command_target == target
                )
            })
            && self.mutation_binding_rows(rows, target).is_ok();
        let document_shape = document_set.is_some()
            && program.commands.len() == 1
            && self.mutation_binding_rows(rows, target).is_ok();
        if !request.mutation_filter_stages()?.is_empty()
            || request.initial_optional
            || !request.continuations.is_empty()
            || request.correlated_optional.is_some()
            || !request.orders.is_empty()
            || (program.continuation.is_none()
                && (request.offset != 0 || request.limit != usize::MAX))
            || (!document_shape && !program.values.is_empty())
            || !program.expression_obligations.is_empty()
            || (!node_shape && !relationship_shape && !document_shape)
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation static dispatch does not cover this row or RHS program",
            ));
        }
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native Metal mutation program requires the selected Metal device",
            ));
        };
        ensure_not_cancelled(cancellation)?;
        let selected_rows = rows.row_count();
        let intent_count = selected_rows
            .checked_mul(program.commands.len())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation intent cardinality overflow",
                )
            })?;
        if intent_count > program.max_intents {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation intent budget exceeded",
            ));
        }
        let target_fields = self.mutation_entity_fields(rows, target, device)?;
        let target_kind = match target {
            super::ResidentEntityBinding::Node(_) => EntityKind::Node,
            super::ResidentEntityBinding::Relationship(_) => EntityKind::Relationship,
        };
        let mut command_words = Vec::with_capacity(
            program
                .commands
                .len()
                .saturating_mul(METAL_MUTATION_STATIC_COMMAND_WORDS),
        );
        let mut payload_words = Vec::new();
        let mut membership_parts = Vec::new();
        for command in &program.commands {
            let payload_offset = payload_words.len();
            let (action, payload): (u64, &[u16]) = match &command.operation {
                super::ResidentMutationOperation::AddLabels {
                    target: command_target,
                    labels,
                } if target == super::ResidentEntityBinding::Node(*command_target) => {
                    for label in labels {
                        let token = *program
                            .label_tokens
                            .get(*label as usize)
                            .ok_or_else(|| Error::internal("Metal label token disappeared"))?;
                        membership_parts.push(self.mutation_node_label_membership(
                            &target_fields.safe_rows,
                            token,
                            device,
                        )?);
                    }
                    (1, labels)
                }
                super::ResidentMutationOperation::RemoveLabels {
                    target: command_target,
                    labels,
                } if target == super::ResidentEntityBinding::Node(*command_target) => {
                    for label in labels {
                        let token = *program
                            .label_tokens
                            .get(*label as usize)
                            .ok_or_else(|| Error::internal("Metal label token disappeared"))?;
                        membership_parts.push(self.mutation_node_label_membership(
                            &target_fields.safe_rows,
                            token,
                            device,
                        )?);
                    }
                    (2, labels)
                }
                super::ResidentMutationOperation::RemoveProperty {
                    target: command_target,
                    property_name,
                } if *command_target == target => {
                    let token = *program
                        .property_tokens
                        .get(*property_name as usize)
                        .ok_or_else(|| Error::internal("Metal property token disappeared"))?;
                    membership_parts.push(self.mutation_property_presence(
                        target,
                        token,
                        &target_fields.safe_rows,
                        &target_fields.validity,
                        device,
                    )?);
                    (3, std::slice::from_ref(property_name))
                }
                super::ResidentMutationOperation::SetProperty {
                    target: command_target,
                    property_name,
                    ..
                } if *command_target == target
                    && document_set.is_some_and(|(expected_target, expected_property, _)| {
                        expected_target == target && expected_property == *property_name
                    }) =>
                {
                    let (_, _, value) = document_set
                        .ok_or_else(|| Error::internal("Metal document SET profile disappeared"))?;
                    let token = *program
                        .property_tokens
                        .get(*property_name as usize)
                        .ok_or_else(|| Error::internal("Metal property token disappeared"))?;
                    membership_parts.push(
                        self.metal_row_bound_exact_property_mask(
                            target_kind,
                            token,
                            &target_fields.safe_rows,
                            value,
                            device,
                            cancellation,
                        )?
                        .to_dtype(DType::I64)
                        .map_err(candle_error)?,
                    );
                    (
                        METAL_MUTATION_ACTION_SET_PROPERTY,
                        std::slice::from_ref(property_name),
                    )
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal mutation static dispatch supports one node target or one relationship-property target",
                    ));
                }
            };
            if payload.is_empty() {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal mutation static command has no typed payload",
                ));
            }
            payload_words.extend(payload.iter().map(|value| u64::from(*value)));
            command_words.extend([
                action,
                u64::try_from(payload_offset).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation payload offset exceeds u64",
                    )
                })?,
                u64::try_from(payload.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation payload length exceeds u64",
                    )
                })?,
                command.rhs_obligation.id,
                command.effect_obligation.id,
                target_kind as u64,
                u64::try_from(payload_offset).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation membership offset exceeds u64",
                    )
                })?,
            ]);
        }

        let input_word_count = selected_rows
            .checked_mul(payload_words.len().checked_add(2).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation input width overflow",
                )
            })?)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation input image overflow",
                )
            })?;
        let mut input_parts = Vec::with_capacity(membership_parts.len().saturating_add(2));
        input_parts.push(target_fields.validity);
        input_parts.push(target_fields.ids);
        input_parts.extend(membership_parts);
        let input = mutation_concat_i64(&input_parts, input_word_count, device)?;

        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        {
            let command_words = command_words
                .into_iter()
                .map(|word| word as i64)
                .collect::<Vec<_>>();
            let payload_words = payload_words
                .into_iter()
                .map(|word| word as i64)
                .collect::<Vec<_>>();
            let commands = Tensor::from_slice(&command_words, command_words.len(), device)
                .map_err(candle_error)?;
            let payload = Tensor::from_slice(&payload_words, payload_words.len(), device)
                .map_err(candle_error)?;
            let receipt_count = program
                .commands
                .len()
                .checked_mul(2)
                .and_then(|count| count.checked_add(1))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation receipt count overflow",
                    )
                })?;
            let output_payload_words =
                selected_rows
                    .checked_mul(payload_words.len())
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal mutation output payload overflow",
                        )
                    })?;
            let output_words = METAL_MUTATION_STATIC_HEADER_WORDS
                .checked_add(
                    receipt_count
                        .checked_mul(METAL_MUTATION_STATIC_RECEIPT_WORDS)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal mutation receipt output overflow",
                            )
                        })?,
                )
                .and_then(|words| {
                    intent_count
                        .checked_mul(METAL_MUTATION_STATIC_INTENT_WORDS)
                        .and_then(|intents| words.checked_add(intents))
                })
                .and_then(|words| words.checked_add(output_payload_words))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation output shape overflow",
                    )
                })?;
            let arguments = MetalMutationStaticArgs {
                execution_high: program.execution.high,
                execution_low: program.execution.low,
                row_count: u64::try_from(selected_rows).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation row count exceeds u64",
                    )
                })?,
                output_word_count: u64::try_from(output_words).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation output count exceeds u64",
                    )
                })?,
                input_word_count: u64::try_from(input_word_count).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation input count exceeds u64",
                    )
                })?,
                selection_obligation_id: program.selection_obligation.id,
                command_count: u32::try_from(program.commands.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation command count exceeds u32",
                    )
                })?,
                receipt_count: u32::try_from(receipt_count).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation receipt count exceeds u32",
                    )
                })?,
                command_word_count: u32::try_from(command_words.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation command image exceeds u32",
                    )
                })?,
                payload_word_count: u32::try_from(payload_words.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation payload image exceeds u32",
                    )
                })?,
            };
            let encoded = input
                .apply_op3_no_bwd(
                    &commands,
                    &payload,
                    &MetalMutationStatic {
                        arguments,
                        input_storage_words: input.elem_count(),
                    },
                )
                .map_err(candle_error)?;
            let words = encoded.to_vec1::<i64>().map_err(candle_error)?;
            ensure_not_cancelled(cancellation)?;
            let result = decode_metal_static_mutation(&words, program)?;
            return Ok(MetalMutationExecution {
                result,
                packet: encoded,
                packet_kind: MetalMutationPacketKind::Static,
            });
        }
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        {
            let _ = (input, command_words, payload_words);
            Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation kernels are unavailable on this build target",
            ))
        }
    }

    fn metal_mutation_read_set(
        &self,
        device: &Device,
        request: &ResidentNodePipelineRequest,
        cancellation: &CancellationToken,
    ) -> Result<MetalMutationReadSet> {
        let continuation = request
            .mutation
            .as_ref()
            .and_then(|program| program.continuation.as_ref())
            .ok_or_else(|| Error::internal("Metal read-set collection has no continuation"))?;
        let expansion_count = request.expansion_steps().count();
        if expansion_count > 1 || request.correlated_optional.is_some() {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation read-set collection currently admits at most one uncorrelated expansion",
            ));
        }
        let empty = || Tensor::zeros(0, DType::U32, device).map_err(candle_error);
        if self.node_count == 0 {
            return Ok(MetalMutationReadSet {
                nodes: empty()?,
                relationships: empty()?,
            });
        }

        // This is the generic matcher's initial candidate domain, before ordinary WHERE filters.
        // Only predicates compiled from the initial pattern literal narrow read dependencies.
        let initial_mask = self.node_selection_mask(&request.labels, request.layers)?;
        let mut dependency_starts =
            selected_positions(&initial_mask, self.node_count, device, cancellation)?;
        for predicate in &continuation.initial_dependency_predicates {
            if predicate.binding != super::ResidentNodeBinding::Start {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal mutation read-set predicate is not start-node scoped",
                ));
            }
            if dependency_starts.elem_count() == 0 {
                break;
            }
            let (values, validity) =
                self.selected_integer_column_tensor(predicate.property, &dependency_starts)?;
            let predicate_mask = match predicate.operation {
                CompareOp::Eq => values.eq(predicate.operand),
                CompareOp::NotEq => values.ne(predicate.operand),
                CompareOp::Less => values.lt(predicate.operand),
                CompareOp::LessOrEqual => values.le(predicate.operand),
                CompareOp::Greater => values.gt(predicate.operand),
                CompareOp::GreaterOrEqual => values.ge(predicate.operand),
            }
            .and_then(|matched| matched.broadcast_mul(&validity.eq(1_u8)?))
            .map_err(candle_error)?;
            let selected = selected_positions(
                &predicate_mask,
                dependency_starts.elem_count(),
                device,
                cancellation,
            )?;
            dependency_starts = if selected.elem_count() == 0 {
                empty()?
            } else {
                dependency_starts
                    .index_select(&selected, 0)
                    .map_err(candle_error)?
            };
        }

        if dependency_starts.elem_count() == 0 {
            return Ok(MetalMutationReadSet {
                nodes: empty()?,
                relationships: empty()?,
            });
        }
        let mut node_candidates = dependency_starts.clone();
        let mut relationship_candidates = empty()?;
        if let Some(expansion) = request.expansion_steps().next() {
            // CPU records a visible edge/end candidate before end labels, endpoint predicates,
            // endpoint equality, and OPTIONAL null extension can reject it. Preserve exactly that
            // boundary while retaining immutable relationship type/direction/layer constraints.
            let mut dependency_expansion = expansion.clone();
            dependency_expansion.optional = false;
            dependency_expansion.end_labels.clear();
            dependency_expansion.end_predicates.clear();
            dependency_expansion.end_equals_start = false;
            let maximum_rows = request.maximum_pipeline_rows(self.node_count, self.edge_count)?;
            let (_, edges, ends) = self.expand_pipeline_row_positions(
                device,
                &dependency_starts,
                &dependency_expansion,
                request.layers,
                maximum_rows,
                cancellation,
            )?;
            if ends.elem_count() != 0 {
                node_candidates =
                    Tensor::cat(&[&node_candidates, &ends], 0).map_err(candle_error)?;
            }
            relationship_candidates = edges;
        }
        let nodes = sorted_unique_u32_tensor(&node_candidates, device, cancellation)?;
        let relationships =
            sorted_unique_u32_tensor(&relationship_candidates, device, cancellation)?;
        let dependency_count = nodes
            .elem_count()
            .checked_add(relationships.elem_count())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation read-set cardinality overflow",
                )
            })?;
        if dependency_count > continuation.maximum_read_dependencies {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation read dependencies exceeded their admitted capacity",
            ));
        }
        Ok(MetalMutationReadSet {
            nodes,
            relationships,
        })
    }

    fn execute_metal_mutation_continuation(
        &self,
        device: &Device,
        request: &ResidentNodePipelineRequest,
        rows: &DeviceNodePipelineRows,
        read_set: &MetalMutationReadSet,
        mutation: &MetalMutationExecution,
        cancellation: &CancellationToken,
    ) -> Result<(
        Vec<super::ResidentMutationReadDependency>,
        super::ResidentMutationFinalRelation,
        Vec<ResidentExecutionReceipt>,
    )> {
        let program = request
            .mutation
            .as_ref()
            .ok_or_else(|| Error::internal("Metal continuation has no mutation program"))?;
        let continuation = program
            .continuation
            .as_ref()
            .ok_or_else(|| Error::internal("Metal continuation contract disappeared"))?;
        let Device::Metal(_) = device else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "native mutation continuation requires the selected Metal device",
            ));
        };
        if self.project != request.project
            || self.bookmark != continuation.expected_bookmark
            || self.revision != continuation.expected_graph_revision
            || self.layout_version != continuation.expected_layout_version
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation continuation expected a different immutable resident generation",
            ));
        }
        ensure_not_cancelled(cancellation)?;
        let row_count = rows.row_count();
        if row_count > request.max_output_rows || row_count > u32::MAX as usize {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation continuation selection exceeded its execution row budget",
            ));
        }
        let computed_outputs = continuation.outputs.iter().all(|output| {
            matches!(
                output.source,
                super::ResidentMutationProjectionSource::ComputedValue(_)
            )
        });
        if continuation.outputs.len() != 1 && !computed_outputs {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation continuation currently requires one typed final column",
            ));
        }

        let value_source = metal_mutation_continuation_value_source(continuation)?;
        let (output_kind, dense_rows) = match continuation.outputs[0].source {
            super::ResidentMutationProjectionSource::Entity(source) => (
                METAL_MUTATION_CONTINUATION_OUTPUT_ENTITY,
                self.mutation_binding_rows(rows, source)?
                    .to_dtype(DType::I64)
                    .map_err(candle_error)?,
            ),
            super::ResidentMutationProjectionSource::IntegerProperty(_)
            | super::ResidentMutationProjectionSource::PropertyIsNotNull(_)
            | super::ResidentMutationProjectionSource::PropertyCount(_) => (
                METAL_MUTATION_CONTINUATION_OUTPUT_INTEGER,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
            ),
            super::ResidentMutationProjectionSource::AggregateInteger => (
                METAL_MUTATION_CONTINUATION_OUTPUT_AGGREGATE,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
            ),
            super::ResidentMutationProjectionSource::ComputedValue(_) => (
                METAL_MUTATION_CONTINUATION_OUTPUT_COMPUTED,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
            ),
        };
        if output_kind != METAL_MUTATION_CONTINUATION_OUTPUT_ENTITY
            && output_kind != METAL_MUTATION_CONTINUATION_OUTPUT_COMPUTED
            && value_source.is_none()
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation continuation output has no typed value source",
            ));
        }
        if matches!(
            value_source,
            Some(MetalMutationContinuationValueSource::PropertyCount(_))
        ) && mutation.packet_kind != MetalMutationPacketKind::Static
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal property-count continuation currently requires static REMOVE intents",
            ));
        }
        let value_fields = match value_source {
            Some(source) => self.mutation_continuation_value_fields(rows, source, device)?,
            None => [
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
                Tensor::zeros(row_count, DType::I64, device).map_err(candle_error)?,
            ],
        };
        let dependency_node_count = read_set.nodes.elem_count();
        let dependency_relationship_count = read_set.relationships.elem_count();
        let dependency_count = dependency_node_count
            .checked_add(dependency_relationship_count)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation continuation read-set cardinality overflow",
                )
            })?;
        if dependency_count > continuation.maximum_read_dependencies {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation continuation read set exceeded its admitted capacity",
            ));
        }
        let mut input_parts =
            Vec::with_capacity(METAL_MUTATION_CONTINUATION_INPUT_FIELDS.saturating_add(2));
        input_parts.push(dense_rows);
        input_parts.extend(value_fields);
        append_metal_mutation_read_set_inputs(&mut input_parts, read_set)?;
        let input_word_count = row_count
            .checked_mul(METAL_MUTATION_CONTINUATION_INPUT_FIELDS)
            .and_then(|words| words.checked_add(dependency_count))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation continuation input image overflow",
                )
            })?;
        let inputs = mutation_concat_i64(&input_parts, input_word_count, device)?;

        let mut continuation_words = Vec::with_capacity(
            continuation
                .stages
                .len()
                .saturating_mul(METAL_MUTATION_CONTINUATION_STAGE_WORDS)
                .saturating_add(
                    continuation
                        .stages
                        .len()
                        .saturating_add(3)
                        .saturating_mul(METAL_MUTATION_CONTINUATION_RECEIPT_DESCRIPTOR_WORDS),
                ),
        );
        for stage in &continuation.stages {
            let descriptor = match stage {
                super::ResidentMutationPostStage::Project { .. } => {
                    [METAL_MUTATION_CONTINUATION_STAGE_PROJECT, 0, 0]
                }
                super::ResidentMutationPostStage::FilterIntegerModuloEquals {
                    divisor,
                    operand,
                    ..
                } => [
                    METAL_MUTATION_CONTINUATION_STAGE_FILTER_MODULO,
                    *divisor as u64,
                    *operand as u64,
                ],
                super::ResidentMutationPostStage::Skip { rows } => [
                    METAL_MUTATION_CONTINUATION_STAGE_SKIP,
                    u64::try_from(*rows).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal mutation continuation SKIP exceeds u64",
                        )
                    })?,
                    0,
                ],
                super::ResidentMutationPostStage::Limit { rows } => [
                    METAL_MUTATION_CONTINUATION_STAGE_LIMIT,
                    u64::try_from(*rows).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal mutation continuation LIMIT exceeds u64",
                        )
                    })?,
                    0,
                ],
                super::ResidentMutationPostStage::SumInteger { .. }
                | super::ResidentMutationPostStage::SumPropertyCount { .. } => {
                    [METAL_MUTATION_CONTINUATION_STAGE_SUM, 0, 0]
                }
            };
            continuation_words.extend(descriptor);
        }
        for obligation in std::iter::once(continuation.read_dependency_obligation)
            .chain(std::iter::once(continuation.overlay_obligation))
            .chain(continuation.stage_obligations.iter().copied())
            .chain(std::iter::once(continuation.final_relation_obligation))
        {
            push_metal_mutation_continuation_obligation(&mut continuation_words, obligation)?;
        }
        let continuation_words = continuation_words
            .into_iter()
            .map(|word| word as i64)
            .collect::<Vec<_>>();
        let continuation_packet =
            Tensor::from_slice(&continuation_words, continuation_words.len(), device)
                .map_err(candle_error)?;

        let receipt_count = continuation.stages.len().checked_add(3).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation continuation receipt count overflow",
            )
        })?;
        let output_words = METAL_MUTATION_CONTINUATION_HEADER_WORDS
            .checked_add(
                receipt_count
                    .checked_mul(METAL_MUTATION_CONTINUATION_RECEIPT_WORDS)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal mutation continuation receipt output overflow",
                        )
                    })?,
            )
            .and_then(|words| {
                continuation
                    .maximum_read_dependencies
                    .checked_mul(METAL_MUTATION_CONTINUATION_DEPENDENCY_WORDS)
                    .and_then(|dependencies| words.checked_add(dependencies))
            })
            .and_then(|words| {
                continuation
                    .maximum_output_rows
                    .checked_mul(2)
                    .and_then(|values| words.checked_add(values))
            })
            .and_then(|words| {
                row_count
                    .checked_mul(3)
                    .and_then(|scratch| words.checked_add(scratch))
            })
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal mutation continuation output image overflow",
                )
            })?;
        let project = request.project.0.as_u128();
        let mut fingerprint = [0_u64; 4];
        for (index, chunk) in continuation.fingerprint.0.chunks_exact(8).enumerate() {
            fingerprint[index] = u64::from_le_bytes(chunk.try_into().map_err(|_| {
                Error::internal("mutation continuation fingerprint chunk changed width")
            })?);
        }

        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        {
            let arguments = MetalMutationContinuationArgs {
                execution_high: program.execution.high,
                execution_low: program.execution.low,
                project_high: (project >> 64) as u64,
                project_low: project as u64,
                bookmark_term: continuation.expected_bookmark.term,
                bookmark_index: continuation.expected_bookmark.index,
                graph_revision: continuation.expected_graph_revision,
                layout_version: continuation.expected_layout_version,
                fingerprint_0: fingerprint[0],
                fingerprint_1: fingerprint[1],
                fingerprint_2: fingerprint[2],
                fingerprint_3: fingerprint[3],
                input_word_count: input_word_count as u64,
                mutation_word_count: mutation.packet.elem_count() as u64,
                program_word_count: continuation_words.len() as u64,
                output_word_count: output_words as u64,
                row_count: row_count as u32,
                stage_count: continuation.stages.len() as u32,
                receipt_count: receipt_count as u32,
                output_capacity: continuation.maximum_output_rows as u32,
                dependency_node_count: u32::try_from(dependency_node_count).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal mutation node read-set cardinality exceeds u32",
                    )
                })?,
                dependency_relationship_count: u32::try_from(dependency_relationship_count)
                    .map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal mutation relationship read-set cardinality exceeds u32",
                        )
                    })?,
                dependency_capacity: u32::try_from(continuation.maximum_read_dependencies)
                    .map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal mutation read-set capacity exceeds u32",
                        )
                    })?,
                output_kind,
                property_name: value_source
                    .and_then(MetalMutationContinuationValueSource::property_name)
                    .map_or(0, u32::from),
                value_source: value_source.map_or(
                    METAL_MUTATION_CONTINUATION_SOURCE_NONE,
                    MetalMutationContinuationValueSource::encoded_kind,
                ),
                mutation_kind: mutation.packet_kind as u32,
            };
            let encoded = inputs
                .apply_op3_no_bwd(
                    &mutation.packet,
                    &continuation_packet,
                    &MetalMutationContinuation {
                        arguments,
                        input_storage_words: inputs.elem_count(),
                    },
                )
                .map_err(candle_error)?;
            let words = encoded.to_vec1::<i64>().map_err(candle_error)?;
            ensure_not_cancelled(cancellation)?;
            let (dependencies, mut relation, receipts) =
                decode_metal_mutation_continuation(&words, request)?;
            let mut computed_values = Vec::new();
            if let Some(value_program) = &continuation.value_program {
                let validated =
                    execute_metal_quantifier_program(device, self, value_program, cancellation)?
                        .validate(value_program, super::BackendKind::Metal)?;
                let [row] = validated.rows() else {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal mutation value program returned the wrong row count",
                    ));
                };
                let [value] = row.as_slice() else {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal mutation value program returned the wrong column count",
                    ));
                };
                computed_values.push(value.clone());
            }
            if let Some(value_program) = &continuation.segmented_value_program {
                let prepared = prepare_metal_segmented_aggregation(self, value_program)?;
                let validated = execute_metal_segmented_aggregation(
                    device,
                    self,
                    value_program,
                    &prepared,
                    cancellation,
                )?
                .validate_for_publication(value_program, super::BackendKind::Metal)?;
                computed_values.extend(super::resident_segmented_one_row_values(
                    validated.relation(),
                )?);
            }
            if !computed_values.is_empty() {
                relation.columns =
                    continuation
                        .outputs
                        .iter()
                        .map(|output| {
                            let super::ResidentMutationProjectionSource::ComputedValue(index) =
                                output.source
                            else {
                                return Err(Error::internal(
                                    "Metal segmented mutation value output changed type",
                                ));
                            };
                            let value = computed_values.get(index as usize).cloned().ok_or_else(
                                || {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "Metal segmented mutation value output index is invalid",
                                    )
                                },
                            )?;
                            Ok(super::ResidentMutationRelationColumn::Value {
                                source: output.source,
                                values: vec![value; relation.row_count],
                            })
                        })
                        .collect::<Result<Vec<_>>>()?;
            }
            return Ok((dependencies, relation, receipts));
        }
        #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
        {
            let _ = (
                inputs,
                continuation_packet,
                output_words,
                fingerprint,
                output_kind,
            );
            Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation continuation kernels are unavailable on this build target",
            ))
        }
    }

    pub fn execute_node_group_pipeline(
        &self,
        device: &Device,
        request: &ResidentNodeGroupPipelineRequest,
        cancellation: &CancellationToken,
    ) -> Result<Vec<ResidentGroup>> {
        let rows = self.select_node_pipeline_rows(device, &request.input, cancellation)?;
        self.reduce_node_group_pipeline_rows(device, &rows, request, cancellation)
    }

    pub fn execute_node_group_pipelines(
        &self,
        device: &Device,
        first: &ResidentNodeGroupPipelineRequest,
        additional: &[ResidentNodeGroupPipelineRequest],
        cancellation: &CancellationToken,
    ) -> Result<Vec<Vec<ResidentGroup>>> {
        if additional
            .iter()
            .any(|request| request.input != first.input)
        {
            return Err(Error::internal(
                "aligned resident reductions have different input pipelines",
            ));
        }
        let rows = self.select_node_pipeline_rows(device, &first.input, cancellation)?;
        std::iter::once(first)
            .chain(additional)
            .map(|request| {
                self.reduce_node_group_pipeline_rows(device, &rows, request, cancellation)
            })
            .collect()
    }

    fn reduce_node_group_pipeline_rows(
        &self,
        device: &Device,
        rows: &DeviceNodePipelineRows,
        request: &ResidentNodeGroupPipelineRequest,
        cancellation: &CancellationToken,
    ) -> Result<Vec<ResidentGroup>> {
        if request.distinct_relationship {
            if request.key.is_some()
                || request.value.is_some()
                || request.aggregate != ResidentAggregate::CountAll
            {
                return Err(Error::internal(
                    "resident distinct-relationship aggregate has an invalid shape",
                ));
            }
            if request.max_groups == 0 {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident grouping exceeded the result row budget",
                ));
            }
            let relationships = rows.relationships.last().ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident distinct-relationship aggregate has no relationship column",
                )
            })?;
            let count = distinct_non_null_u32_count(relationships, device, cancellation)?;
            return Ok(vec![ResidentGroup {
                key: None,
                rows: u64::try_from(rows.row_count()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident grouping row count exceeds u64",
                    )
                })?,
                value: Some(ScalarValue::Integer(i64::try_from(count).map_err(
                    |_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "resident distinct relationship count exceeds i64",
                        )
                    },
                )?)),
            }]);
        }
        let key_input = request
            .key
            .map(|projection| {
                rows.binding(projection.binding)
                    .map(|rows| (projection.property, rows))
            })
            .transpose()?;
        let value_input = request
            .value
            .map(|projection| {
                rows.binding(projection.binding)
                    .map(|rows| (projection.property, rows))
            })
            .transpose()?;
        self.group_selected_node_i64(
            rows.binding(super::ResidentNodeBinding::Start)?,
            key_input,
            value_input,
            request.aggregate,
            request.max_groups,
            device,
            cancellation,
        )
    }

    pub fn execute_temporal_pipeline(
        &self,
        device: &Device,
        request: &ResidentTemporalPipelineRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentTemporalPipelineResult> {
        if request.from_nanos >= request.to_nanos {
            return Err(Error::new(
                ErrorCode::TemporalRange,
                "resident temporal range must be non-empty",
            ));
        }
        let column = self
            .temporal_integer
            .get(&(EntityKind::Node as u8, request.target, request.property))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "resident temporal property is not an integer node column",
                )
            })?;
        let mut input = request.input.clone();
        input.integer_projections.clear();
        input.property_null_projections.clear();
        input.max_output_rows = usize::MAX;
        let rows = self.select_node_pipeline_rows(device, &input, cancellation)?;
        let start_rows = rows.binding(super::ResidentNodeBinding::Start)?;
        let edge_rows = rows.relationships.last();
        let end_rows = (rows.nodes.len() > 1).then(|| rows.nodes.last()).flatten();
        let binding_rows = rows.binding(request.binding)?;
        if binding_rows.elem_count() == 0 || column.rows == 0 {
            return Ok(empty_temporal_pipeline_result());
        }
        let node_id_order_keys = self
            .node_id_order_keys
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty graph has no node-ID order-key tensor"))?
            .index_select(binding_rows, 0)
            .map_err(candle_error)?;
        let entity_ids = column
            .entity_ids
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty temporal column has no entity IDs"))?;
        let event_times = column
            .event_times_nanos
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty temporal column has no event times"))?;
        let sequence_indexes = column
            .sequence_indexes
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty temporal column has no sequence indexes"))?;
        let values = column
            .values
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty temporal column has no values"))?;
        let validity = column
            .validity
            .as_ref()
            .ok_or_else(|| Error::internal("non-empty temporal column has no validity"))?;

        let entity_low = sorted_integer_bound(
            entity_ids,
            column.rows,
            &node_id_order_keys,
            false,
            device,
            cancellation,
        )?;
        let entity_high = sorted_integer_bound(
            entity_ids,
            column.rows,
            &node_id_order_keys,
            true,
            device,
            cancellation,
        )?;
        let from = Tensor::full(request.from_nanos, node_id_order_keys.elem_count(), device)
            .map_err(candle_error)?;
        let to = Tensor::full(request.to_nanos, node_id_order_keys.elem_count(), device)
            .map_err(candle_error)?;
        let sample_low = sorted_integer_bound_ranges(
            event_times,
            &entity_low,
            &entity_high,
            &from,
            false,
            device,
            cancellation,
        )?;
        let sample_high = sorted_integer_bound_ranges(
            event_times,
            &entity_low,
            &entity_high,
            &to,
            false,
            device,
            cancellation,
        )?;
        let counts = sample_high.sub(&sample_low).map_err(candle_error)?;
        let cap = i64::try_from(request.max_output_rows.min(i64::MAX as usize - 1))
            .unwrap_or(i64::MAX - 1)
            .saturating_add(1);
        let cumulative = bounded_inclusive_scan_i64(&counts, cap, device, cancellation)?;
        let candidate_count = cumulative
            .narrow(0, cumulative.elem_count() - 1, 1)
            .and_then(|count| count.to_vec1::<i64>())
            .map_err(candle_error)?;
        let candidate_count = *candidate_count
            .first()
            .ok_or_else(|| Error::internal("resident temporal result count is absent"))?;
        let candidate_count = usize::try_from(candidate_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident temporal result count exceeds host address space",
            )
        })?;
        if candidate_count > request.max_output_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident temporal pipeline exceeded the result row budget",
            ));
        }
        if candidate_count == 0 {
            return Ok(empty_temporal_pipeline_result());
        }

        let output_positions = Tensor::arange(
            0_i64,
            i64::try_from(candidate_count).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident temporal result count exceeds i64",
                )
            })?,
            device,
        )
        .map_err(candle_error)?;
        let source_positions = sorted_integer_bound(
            &cumulative,
            cumulative.elem_count(),
            &output_positions,
            true,
            device,
            cancellation,
        )?;
        let exclusive = cumulative.sub(&counts).map_err(candle_error)?;
        let source_output_starts = exclusive
            .index_select(&source_positions, 0)
            .map_err(candle_error)?;
        let sample_rows = sample_low
            .index_select(&source_positions, 0)
            .and_then(|rows| rows.add(&output_positions.sub(&source_output_starts)?))
            .map_err(candle_error)?;
        let bookmark_key = u64_order_key(request.bookmark_index);
        let visible = sequence_indexes
            .index_select(&sample_rows, 0)
            .and_then(|indexes| indexes.le(bookmark_key))
            .map_err(candle_error)?;
        let visible_positions =
            selected_positions(&visible, candidate_count, device, cancellation)?;
        let source_positions = source_positions
            .index_select(&visible_positions, 0)
            .and_then(|positions| positions.to_dtype(DType::U32))
            .map_err(candle_error)?;
        let sample_rows = sample_rows
            .index_select(&visible_positions, 0)
            .map_err(candle_error)?;
        if sample_rows.elem_count() == 0 {
            return Ok(empty_temporal_pipeline_result());
        }
        if column.rows > u32::MAX as usize {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident temporal row space exceeds u32",
            ));
        }
        // Candle's Metal indexing kernels intentionally expose the complete U32 index family,
        // while the I64-index/U8-value specialization is absent. Canonical temporal row space is
        // already bounded to U32, so normalize once before gathering times, values, and validity.
        let sample_rows = sample_rows.to_dtype(DType::U32).map_err(candle_error)?;

        let mut output_start = start_rows
            .index_select(&source_positions, 0)
            .map_err(candle_error)?;
        let mut output_edges = edge_rows
            .as_ref()
            .map(|rows| {
                rows.index_select(&source_positions, 0)
                    .map_err(candle_error)
            })
            .transpose()?;
        let mut output_end = end_rows
            .as_ref()
            .map(|rows| {
                rows.index_select(&source_positions, 0)
                    .map_err(candle_error)
            })
            .transpose()?;
        let mut output_times = event_times
            .index_select(&sample_rows, 0)
            .map_err(candle_error)?;
        let mut output_values = values.index_select(&sample_rows, 0).map_err(candle_error)?;
        let mut output_validity = validity
            .index_select(&sample_rows, 0)
            .map_err(candle_error)?;
        let mut bucket_starts = Tensor::zeros(0, DType::I64, device).map_err(candle_error)?;
        let mut bucket_ends = Tensor::zeros(0, DType::I64, device).map_err(candle_error)?;

        if let Some(window) = request.window {
            let mut spec = if window.width_nanos == window.every_nanos {
                WindowSpec::tumbling(window.width_nanos)
            } else {
                WindowSpec::hopping(window.width_nanos, window.every_nanos)
            };
            spec.align_nanos = window.align_nanos;
            let boundaries =
                TemporalStore::window_boundaries(request.from_nanos, request.to_nanos, &spec)?;
            let base_count = output_times.elem_count();
            let mut start_parts = Vec::new();
            let mut edge_parts = Vec::new();
            let mut end_parts = Vec::new();
            let mut time_parts = Vec::new();
            let mut value_parts = Vec::new();
            let mut validity_parts = Vec::new();
            let mut bucket_start_parts = Vec::new();
            let mut bucket_end_parts = Vec::new();
            let mut windowed_count = 0_usize;
            for (bucket_start, bucket_end) in boundaries {
                ensure_not_cancelled(cancellation)?;
                let in_bucket = output_times
                    .ge(bucket_start)
                    .and_then(|lower| lower.broadcast_mul(&output_times.lt(bucket_end)?))
                    .map_err(candle_error)?;
                let selected = selected_positions(&in_bucket, base_count, device, cancellation)?;
                let selected_count = selected.elem_count();
                if selected_count == 0 {
                    continue;
                }
                windowed_count = windowed_count.checked_add(selected_count).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident temporal window row count overflow",
                    )
                })?;
                if windowed_count > request.max_output_rows {
                    return Err(Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident temporal window exceeded the result row budget",
                    ));
                }
                start_parts.push(
                    output_start
                        .index_select(&selected, 0)
                        .map_err(candle_error)?,
                );
                if let Some(edges) = &output_edges {
                    edge_parts.push(edges.index_select(&selected, 0).map_err(candle_error)?);
                }
                if let Some(end) = &output_end {
                    end_parts.push(end.index_select(&selected, 0).map_err(candle_error)?);
                }
                time_parts.push(
                    output_times
                        .index_select(&selected, 0)
                        .map_err(candle_error)?,
                );
                value_parts.push(
                    output_values
                        .index_select(&selected, 0)
                        .map_err(candle_error)?,
                );
                validity_parts.push(
                    output_validity
                        .index_select(&selected, 0)
                        .map_err(candle_error)?,
                );
                bucket_start_parts.push(
                    Tensor::full(bucket_start, selected_count, device).map_err(candle_error)?,
                );
                bucket_end_parts
                    .push(Tensor::full(bucket_end, selected_count, device).map_err(candle_error)?);
            }
            output_start = concatenate_tensors(&start_parts, DType::U32, device)?;
            output_edges = output_edges
                .as_ref()
                .map(|_| concatenate_tensors(&edge_parts, DType::U32, device))
                .transpose()?;
            output_end = output_end
                .as_ref()
                .map(|_| concatenate_tensors(&end_parts, DType::U32, device))
                .transpose()?;
            output_times = concatenate_tensors(&time_parts, DType::I64, device)?;
            output_values = concatenate_tensors(&value_parts, DType::I64, device)?;
            output_validity = concatenate_tensors(&validity_parts, DType::U8, device)?;
            bucket_starts = concatenate_tensors(&bucket_start_parts, DType::I64, device)?;
            bucket_ends = concatenate_tensors(&bucket_end_parts, DType::I64, device)?;
        }

        ensure_not_cancelled(cancellation)?;
        Ok(ResidentTemporalPipelineResult {
            start_rows: output_start.to_vec1::<u32>().map_err(candle_error)?,
            edge_rows: output_edges
                .map(|rows| rows.to_vec1::<u32>().map_err(candle_error))
                .transpose()?
                .unwrap_or_default(),
            end_rows: output_end
                .map(|rows| rows.to_vec1::<u32>().map_err(candle_error))
                .transpose()?
                .unwrap_or_default(),
            event_times_nanos: output_times.to_vec1::<i64>().map_err(candle_error)?,
            values: output_values.to_vec1::<i64>().map_err(candle_error)?,
            validity: output_validity.to_vec1::<u8>().map_err(candle_error)?,
            bucket_starts_nanos: bucket_starts.to_vec1::<i64>().map_err(candle_error)?,
            bucket_ends_nanos: bucket_ends.to_vec1::<i64>().map_err(candle_error)?,
        })
    }

    #[allow(clippy::too_many_lines)]
    pub fn execute_graph_procedure(
        &self,
        device: &Device,
        request: &ResidentGraphProcedureRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentGraphProcedureResult> {
        if request.project != self.project {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident graph procedure targets a different project",
            ));
        }
        ensure_graph_execution(cancellation, request.deadline)?;
        if request.max_output_rows == 0
            && matches!(request.procedure, ResidentGraphProcedure::TriangleCount)
        {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "graph procedure result exceeds the query row budget",
            ));
        }
        if self.node_count == 0 {
            return match request.procedure {
                ResidentGraphProcedure::Degree => Ok(ResidentGraphProcedureResult::Degree {
                    node_rows: Vec::new(),
                    out_degree: Vec::new(),
                    in_degree: Vec::new(),
                }),
                ResidentGraphProcedure::BreadthFirst { .. } => Err(Error::new(
                    ErrorCode::QueryType,
                    "BFS source is out of bounds",
                )),
                ResidentGraphProcedure::DepthFirst { .. } => Err(Error::new(
                    ErrorCode::QueryType,
                    "DFS source is out of bounds",
                )),
                ResidentGraphProcedure::ShortestPath { .. } => Err(Error::new(
                    ErrorCode::QueryType,
                    "shortest-path endpoint is out of bounds",
                )),
                ResidentGraphProcedure::DijkstraUnit { .. }
                | ResidentGraphProcedure::DijkstraWeighted { .. } => Err(Error::new(
                    ErrorCode::QueryType,
                    "Dijkstra source is out of bounds",
                )),
                ResidentGraphProcedure::WeaklyConnectedComponents
                | ResidentGraphProcedure::StronglyConnectedComponents => {
                    Ok(ResidentGraphProcedureResult::Components {
                        node_rows: Vec::new(),
                        component: Vec::new(),
                    })
                }
                ResidentGraphProcedure::Louvain => Ok(ResidentGraphProcedureResult::Louvain {
                    node_rows: Vec::new(),
                    community: Vec::new(),
                }),
                ResidentGraphProcedure::PageRank {
                    damping,
                    tolerance,
                    max_iterations,
                } => {
                    if !(0.0..1.0).contains(&damping)
                        || !tolerance.is_finite()
                        || tolerance <= 0.0
                        || max_iterations == 0
                    {
                        Err(Error::new(
                            ErrorCode::QueryType,
                            "invalid PageRank configuration",
                        ))
                    } else {
                        Ok(ResidentGraphProcedureResult::PageRank {
                            node_rows: Vec::new(),
                            score: Vec::new(),
                        })
                    }
                }
                ResidentGraphProcedure::TriangleCount => {
                    Ok(ResidentGraphProcedureResult::TriangleCount { count: 0 })
                }
                ResidentGraphProcedure::ClusteringCoefficient => {
                    Ok(ResidentGraphProcedureResult::ClusteringCoefficient {
                        node_rows: Vec::new(),
                        coefficient: Vec::new(),
                    })
                }
                ResidentGraphProcedure::KCore => Ok(ResidentGraphProcedureResult::KCore {
                    node_rows: Vec::new(),
                    core: Vec::new(),
                }),
            };
        }
        let visible_mask = self.node_selection_mask(&[], request.layers)?;
        // Path procedures consume the visibility bitmap directly. Avoid manufacturing a compact
        // all-visible row vector through the generic O(V log V) prefix scan when no path kernel
        // reads that vector.
        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        if matches!(device, Device::Metal(_)) {
            match request.procedure {
                ResidentGraphProcedure::BreadthFirst { source_dense } => {
                    return self.metal_breadth_first_direct(
                        &visible_mask,
                        source_dense,
                        request.layers,
                        request.max_output_rows,
                        cancellation,
                        request.deadline,
                    );
                }
                ResidentGraphProcedure::DepthFirst { source_dense } => {
                    return self.metal_depth_first(
                        &visible_mask,
                        source_dense,
                        request.layers,
                        request.max_output_rows,
                        cancellation,
                        request.deadline,
                    );
                }
                ResidentGraphProcedure::ShortestPath {
                    source_dense,
                    target_dense,
                } => {
                    return self.metal_shortest_path(
                        &visible_mask,
                        source_dense,
                        target_dense,
                        request.layers,
                        request.max_output_rows,
                        cancellation,
                        request.deadline,
                    );
                }
                ResidentGraphProcedure::DijkstraWeighted {
                    source_dense,
                    weight_property,
                } => {
                    return self.metal_dijkstra_weighted(
                        &visible_mask,
                        source_dense,
                        weight_property,
                        request.layers,
                        request.max_output_rows,
                        cancellation,
                        request.deadline,
                    );
                }
                ResidentGraphProcedure::DijkstraUnit { source_dense } => {
                    return self.metal_dijkstra_unit(
                        &visible_mask,
                        source_dense,
                        request.layers,
                        request.max_output_rows,
                        cancellation,
                        request.deadline,
                    );
                }
                _ => {}
            }
        }
        let visible_rows =
            if request.layers == LayerMask::ALL && self.active_node_count == self.node_count {
                Tensor::arange(
                    0_u32,
                    checked_u32(self.node_count, "visible node count")?,
                    device,
                )
                .map_err(candle_error)?
            } else {
                selected_positions_with_deadline(
                    &visible_mask,
                    self.node_count,
                    device,
                    cancellation,
                    request.deadline,
                )?
            };
        if visible_rows.elem_count() > request.max_output_rows
            && !matches!(
                request.procedure,
                ResidentGraphProcedure::BreadthFirst { .. }
                    | ResidentGraphProcedure::DepthFirst { .. }
                    | ResidentGraphProcedure::ShortestPath { .. }
                    | ResidentGraphProcedure::DijkstraUnit { .. }
                    | ResidentGraphProcedure::DijkstraWeighted { .. }
                    | ResidentGraphProcedure::TriangleCount
            )
        {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "graph procedure result exceeds the query row budget",
            ));
        }
        #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
        if matches!(device, Device::Metal(_))
            && matches!(
                request.procedure,
                ResidentGraphProcedure::Degree
                    | ResidentGraphProcedure::BreadthFirst { .. }
                    | ResidentGraphProcedure::DepthFirst { .. }
                    | ResidentGraphProcedure::ShortestPath { .. }
                    | ResidentGraphProcedure::DijkstraUnit { .. }
                    | ResidentGraphProcedure::DijkstraWeighted { .. }
                    | ResidentGraphProcedure::WeaklyConnectedComponents
                    | ResidentGraphProcedure::StronglyConnectedComponents
                    | ResidentGraphProcedure::Louvain
                    | ResidentGraphProcedure::PageRank { .. }
                    | ResidentGraphProcedure::TriangleCount
                    | ResidentGraphProcedure::ClusteringCoefficient
                    | ResidentGraphProcedure::KCore
            )
        {
            return self.execute_metal_sparse_graph_procedure(
                &visible_mask,
                &visible_rows,
                request,
                cancellation,
            );
        }
        match request.procedure {
            ResidentGraphProcedure::Degree => {
                let (sources, targets) = self.visible_edge_endpoints(
                    device,
                    &visible_rows,
                    request.layers,
                    cancellation,
                    request.deadline,
                )?;
                let out_degree = scatter_counts(&sources, self.node_count, device)?;
                let in_degree = scatter_counts(&targets, self.node_count, device)?;
                let out_degree = out_degree
                    .index_select(&visible_rows, 0)
                    .and_then(|values| values.to_vec1::<u32>())
                    .map_err(candle_error)?;
                let in_degree = in_degree
                    .index_select(&visible_rows, 0)
                    .and_then(|values| values.to_vec1::<u32>())
                    .map_err(candle_error)?;
                let node_rows = visible_rows.to_vec1::<u32>().map_err(candle_error)?;
                Ok(ResidentGraphProcedureResult::Degree {
                    node_rows,
                    out_degree,
                    in_degree,
                })
            }
            ResidentGraphProcedure::BreadthFirst { source_dense } => {
                if source_dense as usize >= self.node_count {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "BFS source is out of bounds",
                    ));
                }
                let row_ids = Tensor::arange(
                    0_u32,
                    checked_u32(self.node_count, "BFS node count")?,
                    device,
                )
                .map_err(candle_error)?;
                let source_mask = row_ids
                    .eq(source_dense)
                    .and_then(|mask| mask.broadcast_mul(&visible_mask))
                    .map_err(candle_error)?;
                let source_visible = source_mask
                    .to_dtype(DType::U32)
                    .and_then(|mask| mask.sum_all())
                    .and_then(|count| count.to_scalar::<u32>())
                    .map_err(candle_error)?;
                if source_visible == 0 {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "graph procedure node is not visible",
                    ));
                }
                let mut frontier = source_mask;
                let mut distances = frontier
                    .where_cond(
                        &Tensor::zeros(self.node_count, DType::I64, device)
                            .map_err(candle_error)?,
                        &Tensor::full(-1_i64, self.node_count, device).map_err(candle_error)?,
                    )
                    .map_err(candle_error)?;
                for depth in 1..=self.node_count {
                    ensure_graph_execution(cancellation, request.deadline)?;
                    let frontier_rows = selected_positions_with_deadline(
                        &frontier,
                        self.node_count,
                        device,
                        cancellation,
                        request.deadline,
                    )?;
                    if frontier_rows.elem_count() == 0 {
                        break;
                    }
                    let (_, _, targets) = self.expand_pipeline_rows_with_deadline(
                        device,
                        &frontier_rows,
                        &super::ResidentExpansion {
                            direction: super::ResidentDirection::Outgoing,
                            relationship_types: Vec::new(),
                            end_labels: Vec::new(),
                            end_equals_start: false,
                            optional: false,
                            end_predicates: Vec::new(),
                        },
                        request.layers,
                        self.edge_count,
                        cancellation,
                        request.deadline,
                    )?;
                    let candidates = scatter_counts(&targets, self.node_count, device)?
                        .gt(0_u32)
                        .map_err(candle_error)?;
                    let unvisited = distances.lt(0_i64).map_err(candle_error)?;
                    let next = candidates
                        .broadcast_mul(&unvisited)
                        .and_then(|mask| mask.broadcast_mul(&visible_mask))
                        .map_err(candle_error)?;
                    let depth = i64::try_from(depth).map_err(|_| {
                        Error::new(ErrorCode::ResultBudgetExceeded, "BFS distance exceeds i64")
                    })?;
                    distances = next
                        .where_cond(
                            &Tensor::full(depth, self.node_count, device).map_err(candle_error)?,
                            &distances,
                        )
                        .map_err(candle_error)?;
                    frontier = next;
                }
                let reached = distances
                    .ge(0_i64)
                    .and_then(|mask| mask.broadcast_mul(&visible_mask))
                    .map_err(candle_error)?;
                let rows = selected_positions_with_deadline(
                    &reached,
                    self.node_count,
                    device,
                    cancellation,
                    request.deadline,
                )?;
                if rows.elem_count() > request.max_output_rows {
                    return Err(Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "BFS result exceeds the query row budget",
                    ));
                }
                let distance = distances
                    .index_select(&rows, 0)
                    .and_then(|values| values.to_vec1::<i64>())
                    .map_err(candle_error)?
                    .into_iter()
                    .map(|value| {
                        u32::try_from(value).map_err(|_| {
                            Error::internal("resident BFS produced an invalid distance")
                        })
                    })
                    .collect::<Result<Vec<_>>>()?;
                let node_rows = rows.to_vec1::<u32>().map_err(candle_error)?;
                Ok(ResidentGraphProcedureResult::BreadthFirst {
                    node_rows,
                    distance,
                })
            }
            ResidentGraphProcedure::DijkstraUnit { .. } => Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "exact unit-weight Dijkstra currently requires the Metal graph backend",
            )),
            ResidentGraphProcedure::DepthFirst { .. }
            | ResidentGraphProcedure::ShortestPath { .. }
            | ResidentGraphProcedure::DijkstraWeighted { .. }
            | ResidentGraphProcedure::WeaklyConnectedComponents
            | ResidentGraphProcedure::StronglyConnectedComponents
            | ResidentGraphProcedure::Louvain
            | ResidentGraphProcedure::TriangleCount
            | ResidentGraphProcedure::ClusteringCoefficient
            | ResidentGraphProcedure::KCore => Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "graph procedure currently requires the Metal graph backend",
            )),
            ResidentGraphProcedure::PageRank {
                damping,
                tolerance,
                max_iterations,
            } => {
                if !(0.0..1.0).contains(&damping)
                    || !tolerance.is_finite()
                    || tolerance <= 0.0
                    || max_iterations == 0
                {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "invalid PageRank configuration",
                    ));
                }
                let visible_count = visible_rows.elem_count();
                if visible_count == 0 {
                    return Ok(ResidentGraphProcedureResult::PageRank {
                        node_rows: Vec::new(),
                        score: Vec::new(),
                    });
                }
                let (sources, targets) = self.visible_edge_endpoints(
                    device,
                    &visible_rows,
                    request.layers,
                    cancellation,
                    request.deadline,
                )?;
                let out_degree = scatter_counts(&sources, self.node_count, device)?;
                let visible_f32 = visible_mask.to_dtype(DType::F32).map_err(candle_error)?;
                let count = visible_count as f32;
                let damping_f32 = damping as f32;
                let mut rank = visible_f32
                    .affine(1.0 / f64::from(count), 0.0)
                    .map_err(candle_error)?;
                for _ in 0..max_iterations {
                    ensure_graph_execution(cancellation, request.deadline)?;
                    let dangling_mask = out_degree
                        .eq(0_u32)
                        .and_then(|mask| mask.broadcast_mul(&visible_mask))
                        .and_then(|mask| mask.to_dtype(DType::F32))
                        .map_err(candle_error)?;
                    // Keep dangling-mass reduction on the selected device.  Pulling it to the
                    // host here used to force an avoidable synchronization before every rank
                    // update; only the convergence decision needs one scalar readback.
                    let dangling = rank
                        .broadcast_mul(&dangling_mask)
                        .and_then(|values| values.sum_all())
                        .map_err(candle_error)?;
                    let incoming = if sources.elem_count() == 0 {
                        Tensor::zeros(self.node_count, DType::F32, device).map_err(candle_error)?
                    } else {
                        let source_rank = rank.index_select(&sources, 0).map_err(candle_error)?;
                        let degree = out_degree
                            .index_select(&sources, 0)
                            .and_then(|degree| degree.to_dtype(DType::F32))
                            .map_err(candle_error)?;
                        let contribution = source_rank.div(&degree).map_err(candle_error)?;
                        Tensor::zeros(self.node_count, DType::F32, device)
                            .and_then(|zeros| zeros.scatter_add(&targets, &contribution, 0))
                            .map_err(candle_error)?
                    };
                    let base = dangling
                        .affine(
                            f64::from(damping_f32 / count),
                            f64::from((1.0_f32 - damping_f32) / count),
                        )
                        .map_err(candle_error)?;
                    let next = incoming
                        .affine(f64::from(damping_f32), 0.0)
                        .and_then(|rank| rank.broadcast_add(&base))
                        .and_then(|rank| rank.broadcast_mul(&visible_f32))
                        .map_err(candle_error)?;
                    let change = rank
                        .sub(&next)
                        .and_then(|delta| delta.abs())
                        .and_then(|delta| delta.sum_all())
                        .and_then(|value| value.to_scalar::<f32>())
                        .map_err(candle_error)?;
                    rank = next;
                    if f64::from(change) <= tolerance {
                        break;
                    }
                }
                let score = rank
                    .index_select(&visible_rows, 0)
                    .and_then(|values| values.to_vec1::<f32>())
                    .map_err(candle_error)?
                    .into_iter()
                    .map(f64::from)
                    .collect();
                let node_rows = visible_rows.to_vec1::<u32>().map_err(candle_error)?;
                ensure_graph_execution(cancellation, request.deadline)?;
                Ok(ResidentGraphProcedureResult::PageRank { node_rows, score })
            }
        }
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    #[allow(clippy::too_many_lines)]
    fn execute_metal_sparse_graph_procedure(
        &self,
        visible_mask: &Tensor,
        visible_rows: &Tensor,
        request: &ResidentGraphProcedureRequest,
        cancellation: &CancellationToken,
    ) -> Result<ResidentGraphProcedureResult> {
        match request.procedure {
            ResidentGraphProcedure::Degree => self.metal_degree(
                visible_mask,
                visible_rows,
                request.layers,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::BreadthFirst { source_dense } => self
                .metal_breadth_first_direct(
                    visible_mask,
                    source_dense,
                    request.layers,
                    request.max_output_rows,
                    cancellation,
                    request.deadline,
                ),
            ResidentGraphProcedure::DepthFirst { source_dense } => self.metal_depth_first(
                visible_mask,
                source_dense,
                request.layers,
                request.max_output_rows,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::ShortestPath {
                source_dense,
                target_dense,
            } => self.metal_shortest_path(
                visible_mask,
                source_dense,
                target_dense,
                request.layers,
                request.max_output_rows,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::DijkstraUnit { source_dense } => self.metal_dijkstra_unit(
                visible_mask,
                source_dense,
                request.layers,
                request.max_output_rows,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::DijkstraWeighted {
                source_dense,
                weight_property,
            } => self.metal_dijkstra_weighted(
                visible_mask,
                source_dense,
                weight_property,
                request.layers,
                request.max_output_rows,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::PageRank {
                damping,
                tolerance,
                max_iterations,
            } => self.metal_pagerank(
                visible_mask,
                visible_rows,
                request.layers,
                damping,
                tolerance,
                max_iterations,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::WeaklyConnectedComponents => self
                .metal_weakly_connected_components(
                    visible_mask,
                    visible_rows,
                    request.layers,
                    cancellation,
                    request.deadline,
                ),
            ResidentGraphProcedure::StronglyConnectedComponents => self
                .metal_strongly_connected_components(
                    visible_mask,
                    visible_rows,
                    request.layers,
                    cancellation,
                    request.deadline,
                ),
            ResidentGraphProcedure::TriangleCount => self.metal_triangle_count(
                visible_mask,
                request.layers,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::ClusteringCoefficient => self.metal_clustering_coefficient(
                visible_mask,
                visible_rows,
                request.layers,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::KCore => self.metal_k_core(
                visible_mask,
                visible_rows,
                request.layers,
                cancellation,
                request.deadline,
            ),
            ResidentGraphProcedure::Louvain => graph_louvain::execute(
                self,
                visible_mask,
                visible_rows,
                request.layers,
                cancellation,
                request.deadline,
            ),
        }
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    #[allow(clippy::too_many_lines)]
    fn metal_bfs_workspace(
        &self,
        visible_mask: &Tensor,
        source_dense: u32,
        layers: LayerMask,
        cancellation: &CancellationToken,
        deadline: Option<std::time::Instant>,
    ) -> Result<Tensor> {
        if source_dense as usize >= self.node_count {
            return Err(Error::new(
                ErrorCode::QueryType,
                "BFS source is out of bounds",
            ));
        }
        let source_visible = graph_paths::read_u8_slice(visible_mask, source_dense as usize, 1)?
            .first()
            .copied()
            .unwrap_or(0);
        ensure_graph_execution(cancellation, deadline)?;
        if source_visible == 0 {
            return Err(Error::new(
                ErrorCode::QueryType,
                "graph procedure node is not visible",
            ));
        }
        if let Some(outgoing_neighbors) = self.outgoing_neighbors.as_ref() {
            let adjacency_count = outgoing_neighbors.elem_count();
            if graph_paths::bfs_should_start_persistent(self.node_count, adjacency_count) {
                let outgoing_edges = self.outgoing_edges.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident outgoing adjacency has no edge-row tensor",
                    )
                })?;
                let incoming_neighbors = self.incoming_neighbors.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident outgoing adjacency has no incoming counterpart",
                    )
                })?;
                let incoming_edges = self.incoming_edges.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident incoming adjacency has no edge-row tensor",
                    )
                })?;
                let edge_active = self.edge_active.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident adjacency has no edge-active tensor",
                    )
                })?;
                let edge_layers = self.edge_layers.as_ref().ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident adjacency has no edge-layer tensor",
                    )
                })?;
                if outgoing_edges.elem_count() != adjacency_count
                    || incoming_neighbors.elem_count() != adjacency_count
                    || incoming_edges.elem_count() != adjacency_count
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident incoming and outgoing CSR cardinalities differ",
                    ));
                }
                let is_metal_vector = |tensor: &Tensor, dtype: DType, elements: usize| {
                    let (storage, layout) = tensor.storage_and_layout();
                    matches!(&*storage, Storage::Metal(_))
                        && tensor.dtype() == dtype
                        && layout.is_contiguous()
                        && layout.dims().len() == 1
                        && layout.shape().elem_count() == elements
                };
                if !is_metal_vector(
                    &self.outgoing_offsets,
                    DType::U32,
                    self.node_count.saturating_add(1),
                ) || !is_metal_vector(outgoing_neighbors, DType::U32, adjacency_count)
                    || !is_metal_vector(outgoing_edges, DType::U32, adjacency_count)
                    || !is_metal_vector(
                        &self.incoming_offsets,
                        DType::U32,
                        self.node_count.saturating_add(1),
                    )
                    || !is_metal_vector(incoming_neighbors, DType::U32, adjacency_count)
                    || !is_metal_vector(incoming_edges, DType::U32, adjacency_count)
                    || !is_metal_vector(visible_mask, DType::U8, self.node_count)
                    || !is_metal_vector(edge_active, DType::U8, self.edge_count)
                    || !is_metal_vector(edge_layers, DType::U8, self.edge_count)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal BFS persistent-start tensor contract is invalid",
                    ));
                }
                // The source frontier is exactly one row. Sparse resident shapes that already
                // satisfy the persistent engine's hard bounds do not need eight grid probes or a
                // discarded workspace before taking the same deterministic FIFO path.
                return self.metal_bfs_persistent_workspace(
                    visible_mask,
                    source_dense,
                    layers,
                    cancellation,
                    deadline,
                );
            }
        }
        let layer_mask = u32::from(layers.bits());
        let control_offset = self.node_count.checked_mul(3).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal BFS control offset overflow",
            )
        })?;
        let workspace_words = control_offset
            .checked_add(METAL_GRAPH_CONTROL_WORDS)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal BFS workspace size overflow",
                )
            })?;
        let mut workspace = graph_paths::allocate_u32_workspace(
            visible_mask,
            workspace_words,
            "irongraph Metal BFS workspace",
        )?;
        for node_begin in (0..self.node_count).step_by(graph_paths::PATH_NODE_QUANTUM) {
            ensure_graph_execution(cancellation, deadline)?;
            let node_end = node_begin
                .saturating_add(graph_paths::PATH_NODE_QUANTUM)
                .min(self.node_count);
            workspace = visible_mask
                .apply_op2_no_bwd(
                    &workspace,
                    &MetalGraphBfsInitialize {
                        node_count: self.node_count,
                        edge_count: self.edge_count,
                        source_dense,
                        layer_mask,
                        workspace_words,
                        node_begin,
                        node_end,
                    },
                )
                .map_err(candle_error)?;
            let initialize_control = graph_paths::read_u32_slice(&workspace, control_offset, 2)?;
            if initialize_control.get(1).copied().unwrap_or(1) != 0 {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal BFS rejected corrupt resident graph metadata",
                ));
            }
            ensure_graph_execution(cancellation, deadline)?;
        }
        let mut control = graph_paths::read_u32_slice(&workspace, control_offset, 2)?;
        let Some(outgoing_neighbors) = self.outgoing_neighbors.as_ref() else {
            return Ok(workspace);
        };
        let outgoing_edges = self.outgoing_edges.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident outgoing adjacency has no edge-row tensor",
            )
        })?;
        let incoming_neighbors = self.incoming_neighbors.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident outgoing adjacency has no incoming counterpart",
            )
        })?;
        let incoming_edges = self.incoming_edges.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident incoming adjacency has no edge-row tensor",
            )
        })?;
        let edge_active = self.edge_active.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident adjacency has no edge-active tensor",
            )
        })?;
        let edge_layers = self.edge_layers.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident adjacency has no edge-layer tensor",
            )
        })?;
        let adjacency_count = outgoing_neighbors.elem_count();
        if adjacency_count == 0
            && self.outgoing_overlay.rows.is_empty()
            && self.incoming_overlay.rows.is_empty()
        {
            return Ok(workspace);
        }
        if outgoing_edges.elem_count() != adjacency_count
            || incoming_neighbors.elem_count() != adjacency_count
            || incoming_edges.elem_count() != adjacency_count
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident incoming and outgoing CSR cardinalities differ",
            ));
        }
        let visible_count = visible_mask
            .to_dtype(DType::U32)
            .and_then(|mask| mask.sum_all())
            .and_then(|count| count.to_scalar::<u32>())
            .map_err(candle_error)? as usize;
        let mut frontier_count = control.first().copied().unwrap_or(0) as usize;
        let mut first_depth = 1_usize;
        while first_depth <= self.node_count && frontier_count != 0 {
            // Direction-optimizing BFS: a dense frontier is cheaper as an incoming-CSR pull,
            // while sparse frontiers retain the ordinary outgoing-CSR push.
            let bottom_up = frontier_count.saturating_mul(20) > visible_count;
            let adjacency_tile_domain = adjacency_count.max(self.edge_count);
            for edge_begin in (0..adjacency_tile_domain).step_by(METAL_GRAPH_EDGE_TILE) {
                let edge_end = edge_begin
                    .saturating_add(METAL_GRAPH_EDGE_TILE)
                    .min(adjacency_tile_domain);
                for node_begin in (0..self.node_count).step_by(graph_paths::PATH_NODE_QUANTUM) {
                    ensure_graph_execution(cancellation, deadline)?;
                    let node_end = node_begin
                        .saturating_add(graph_paths::PATH_NODE_QUANTUM)
                        .min(self.node_count);
                    workspace = workspace
                        .apply_op1_no_bwd(&MetalGraphBfsChunk {
                            outgoing_offsets: self.outgoing_offsets.clone(),
                            outgoing_neighbors: outgoing_neighbors.clone(),
                            outgoing_edges: outgoing_edges.clone(),
                            outgoing_overlay: self
                                .outgoing_overlay
                                .packet
                                .clone()
                                .unwrap_or_else(|| self.outgoing_offsets.clone()),
                            incoming_offsets: self.incoming_offsets.clone(),
                            incoming_neighbors: incoming_neighbors.clone(),
                            incoming_edges: incoming_edges.clone(),
                            incoming_overlay: self
                                .incoming_overlay
                                .packet
                                .clone()
                                .unwrap_or_else(|| self.incoming_offsets.clone()),
                            visible_nodes: visible_mask.clone(),
                            edge_active: edge_active.clone(),
                            edge_layers: edge_layers.clone(),
                            node_count: self.node_count,
                            edge_count: self.edge_count,
                            adjacency_count,
                            outgoing_overlay_count: self.outgoing_overlay.rows.len(),
                            incoming_overlay_count: self.incoming_overlay.rows.len(),
                            source_dense,
                            layer_mask,
                            first_depth,
                            level_count: 1,
                            bottom_up,
                            edge_begin,
                            edge_end,
                            prepare: edge_begin == 0,
                            node_begin,
                            node_end,
                        })
                        .map_err(candle_error)?;
                    // The copied two-word control tensor synchronizes this bounded node/edge
                    // intersection without staging the full BFS backing allocation.
                    control = graph_paths::read_u32_slice(&workspace, control_offset, 2)?;
                    if control.get(1).copied().unwrap_or(1) != 0 {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal BFS rejected corrupt resident graph metadata",
                        ));
                    }
                    ensure_graph_execution(cancellation, deadline)?;
                }
            }
            frontier_count = control.first().copied().unwrap_or(0) as usize;
            first_depth = first_depth.saturating_add(1);
            if graph_paths::bfs_should_switch_to_persistent(
                self.node_count,
                adjacency_count,
                first_depth.saturating_sub(1),
                frontier_count,
            ) {
                // The persistent traversal restarts from the source. Release the probe workspace
                // before allocating its replacement so Candle can reuse the same private-buffer
                // bucket instead of retaining two full BFS workspaces for the rest of the call.
                drop(control);
                drop(workspace);
                return self.metal_bfs_persistent_workspace(
                    visible_mask,
                    source_dense,
                    layers,
                    cancellation,
                    deadline,
                );
            }
        }
        ensure_graph_execution(cancellation, deadline)?;
        Ok(workspace)
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    #[allow(clippy::too_many_lines)]
    fn metal_dijkstra_unit(
        &self,
        visible_mask: &Tensor,
        source_dense: u32,
        layers: LayerMask,
        max_output_rows: usize,
        cancellation: &CancellationToken,
        deadline: Option<std::time::Instant>,
    ) -> Result<ResidentGraphProcedureResult> {
        if source_dense as usize >= self.node_count {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Dijkstra source is out of bounds",
            ));
        }
        let source_visible = graph_paths::read_u8_slice(visible_mask, source_dense as usize, 1)?
            .first()
            .copied()
            .unwrap_or(0);
        ensure_graph_execution(cancellation, deadline)?;
        if source_visible == 0 {
            return Err(Error::new(
                ErrorCode::QueryType,
                "graph procedure node is not visible",
            ));
        }
        if max_output_rows == 0 {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Dijkstra result exceeds the query row budget",
            ));
        }
        let workspace =
            self.metal_bfs_workspace(visible_mask, source_dense, layers, cancellation, deadline)?;
        ensure_graph_execution(cancellation, deadline)?;
        let u32_dummy =
            Tensor::zeros(1, DType::U32, visible_mask.device()).map_err(candle_error)?;
        let incoming_neighbors = self.incoming_neighbors.as_ref().unwrap_or(&u32_dummy);
        let incoming_edges = self.incoming_edges.as_ref().unwrap_or(&u32_dummy);
        let incoming_overlay = self.incoming_overlay.packet.as_ref().unwrap_or(&u32_dummy);
        let edge_active = self.edge_active.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident adjacency has no edge-active tensor",
            )
        })?;
        let edge_layers = self.edge_layers.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident adjacency has no edge-layer tensor",
            )
        })?;
        let adjacency_count = self
            .incoming_neighbors
            .as_ref()
            .map_or(0, Tensor::elem_count);
        let adjacency_domain = adjacency_count.max(self.edge_count);
        if adjacency_domain == 0 {
            return Ok(ResidentGraphProcedureResult::Dijkstra {
                node_rows: vec![source_dense],
                cost: vec![0.0],
                predecessor: vec![None],
            });
        }
        if incoming_edges.elem_count() != adjacency_count {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident incoming CSR cardinalities differ",
            ));
        }
        let distance_lane = workspace
            .narrow(0, 0, self.node_count)
            .map_err(candle_error)?;
        let reached = distance_lane.ne(u32::MAX).map_err(candle_error)?;
        let selected = selected_positions_with_deadline(
            &reached,
            self.node_count,
            visible_mask.device(),
            cancellation,
            deadline,
        )?;
        let result_count = selected.elem_count();
        if result_count > max_output_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Dijkstra result exceeds the query row budget",
            ));
        }
        let packet_words = self
            .node_count
            .checked_mul(3)
            .and_then(|words| words.checked_add(1))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal Dijkstra result workspace size overflow",
                )
            })?;
        let mut packet = graph_paths::allocate_u32_workspace(
            visible_mask,
            packet_words,
            "irongraph Metal unit Dijkstra result packet",
        )?;
        for edge_begin in (0..adjacency_domain).step_by(METAL_GRAPH_EDGE_TILE) {
            let edge_end = edge_begin
                .saturating_add(METAL_GRAPH_EDGE_TILE)
                .min(adjacency_domain);
            for node_begin in (0..self.node_count).step_by(graph_paths::PATH_NODE_QUANTUM) {
                ensure_graph_execution(cancellation, deadline)?;
                let node_end = node_begin
                    .saturating_add(graph_paths::PATH_NODE_QUANTUM)
                    .min(self.node_count);
                packet = workspace
                    .apply_op2_no_bwd(
                        &packet,
                        &MetalGraphDijkstraUnitFinalize {
                            incoming_offsets: self.incoming_offsets.clone(),
                            incoming_neighbors: incoming_neighbors.clone(),
                            incoming_edges: incoming_edges.clone(),
                            incoming_overlay: incoming_overlay.clone(),
                            visible_nodes: visible_mask.clone(),
                            edge_active: edge_active.clone(),
                            edge_layers: edge_layers.clone(),
                            node_count: self.node_count,
                            edge_count: self.edge_count,
                            adjacency_count,
                            incoming_overlay_count: self.incoming_overlay.rows.len(),
                            layer_mask: u32::from(layers.bits()),
                            edge_begin,
                            edge_end,
                            initialize: edge_begin == 0,
                            node_begin,
                            node_end,
                        },
                    )
                    .map_err(candle_error)?;
                let status = graph_paths::read_u32_slice(&packet, self.node_count * 3, 1)?
                    .first()
                    .copied()
                    .unwrap_or(1);
                if status != 0 {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal Dijkstra rejected corrupt resident graph metadata",
                    ));
                }
                ensure_graph_execution(cancellation, deadline)?;
            }
        }
        let control = graph_paths::read_u32_slice(&packet, self.node_count * 3, 1)?
            .first()
            .copied()
            .unwrap_or(1);
        if control != 0 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal Dijkstra rejected corrupt resident graph metadata",
            ));
        }
        let compact_cost_words = packet
            .narrow(0, 0, self.node_count * 2)
            .and_then(|words| words.reshape((self.node_count, 2)))
            .and_then(|words| words.index_select(&selected, 0))
            .and_then(|words| words.flatten_all())
            .map_err(candle_error)?;
        let compact_predecessor = packet
            .narrow(0, self.node_count * 2, self.node_count)
            .and_then(|values| values.index_select(&selected, 0))
            .map_err(candle_error)?;
        let node_rows =
            graph_paths::read_u32_bounded(&selected, 0, result_count, cancellation, deadline)?;
        let cost_words = graph_paths::read_u32_bounded(
            &compact_cost_words,
            0,
            result_count * 2,
            cancellation,
            deadline,
        )?;
        let raw_predecessor = graph_paths::read_u32_bounded(
            &compact_predecessor,
            0,
            result_count,
            cancellation,
            deadline,
        )?;
        let mut cost = Vec::with_capacity(result_count);
        let mut predecessor = Vec::with_capacity(result_count);
        for (index, dense) in node_rows.iter().copied().enumerate() {
            if index.is_multiple_of(graph_paths::PATH_NODE_QUANTUM) {
                ensure_graph_execution(cancellation, deadline)?;
            }
            let low = u64::from(cost_words[index * 2]);
            let high = u64::from(cost_words[index * 2 + 1]);
            let value = f64::from_bits(low | (high << 32));
            if !value.is_finite() || value < 0.0 {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal Dijkstra produced an invalid unit cost",
                ));
            }
            let predecessor_dense = raw_predecessor[index];
            let predecessor_dense = if dense == source_dense {
                if value != 0.0 || predecessor_dense != u32::MAX {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal Dijkstra produced an invalid source result",
                    ));
                }
                None
            } else {
                if value == 0.0 || predecessor_dense == u32::MAX {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal Dijkstra produced an invalid predecessor",
                    ));
                }
                Some(predecessor_dense)
            };
            cost.push(value);
            predecessor.push(predecessor_dense);
        }
        ensure_graph_execution(cancellation, deadline)?;
        Ok(ResidentGraphProcedureResult::Dijkstra {
            node_rows,
            cost,
            predecessor,
        })
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    #[allow(
        clippy::cast_possible_truncation,
        clippy::cast_precision_loss,
        clippy::too_many_arguments,
        clippy::too_many_lines
    )]
    fn metal_pagerank(
        &self,
        visible_mask: &Tensor,
        visible_rows: &Tensor,
        layers: LayerMask,
        damping: f64,
        tolerance: f64,
        max_iterations: usize,
        cancellation: &CancellationToken,
        deadline: Option<std::time::Instant>,
    ) -> Result<ResidentGraphProcedureResult> {
        if !(0.0..1.0).contains(&damping)
            || !tolerance.is_finite()
            || tolerance <= 0.0
            || max_iterations == 0
        {
            return Err(Error::new(
                ErrorCode::QueryType,
                "invalid PageRank configuration",
            ));
        }
        let visible_count = visible_rows.elem_count();
        if visible_count == 0 {
            ensure_graph_execution(cancellation, deadline)?;
            return Ok(ResidentGraphProcedureResult::PageRank {
                node_rows: Vec::new(),
                score: Vec::new(),
            });
        }
        let constant_result = |rank: f64| -> Result<ResidentGraphProcedureResult> {
            ensure_graph_execution(cancellation, deadline)?;
            let score = Tensor::full(rank, visible_count, visible_mask.device())
                .and_then(|values| values.to_vec1::<f64>())
                .map_err(candle_error)?;
            let node_rows = visible_rows.to_vec1::<u32>().map_err(candle_error)?;
            ensure_graph_execution(cancellation, deadline)?;
            Ok(ResidentGraphProcedureResult::PageRank { node_rows, score })
        };
        if self.edge_count == 0 {
            return constant_result(1.0 / visible_count as f64);
        }
        let edge_sources = self.edge_sources.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident adjacency has no canonical edge-source tensor",
            )
        })?;
        let edge_targets = self.edge_targets.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident adjacency has no canonical edge-target tensor",
            )
        })?;
        let u32_dummy =
            Tensor::zeros(1, DType::U32, visible_mask.device()).map_err(candle_error)?;
        let incoming_neighbors = self.incoming_neighbors.as_ref().unwrap_or(&u32_dummy);
        let incoming_edges = self.incoming_edges.as_ref().unwrap_or(&u32_dummy);
        let incoming_overlay = self.incoming_overlay.packet.as_ref().unwrap_or(&u32_dummy);
        let edge_active = self.edge_active.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident adjacency has no edge-active tensor",
            )
        })?;
        let edge_layers = self.edge_layers.as_ref().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident adjacency has no edge-layer tensor",
            )
        })?;
        let adjacency_count = self
            .incoming_neighbors
            .as_ref()
            .map_or(0, Tensor::elem_count);
        if (adjacency_count != 0
            && (incoming_neighbors.elem_count() != adjacency_count
                || incoming_edges.elem_count() != adjacency_count))
            || edge_sources.elem_count() != self.edge_count
            || edge_targets.elem_count() != self.edge_count
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident incoming and outgoing CSR cardinalities differ",
            ));
        }
        let layer_mask = u32::from(layers.bits());
        let mut workspace = visible_mask
            .apply_op1_no_bwd(&MetalGraphPageRankInitialize {
                node_count: self.node_count,
                edge_count: self.edge_count,
                adjacency_count,
                visible_count,
                layer_mask,
                damping,
                tolerance,
            })
            .map_err(candle_error)?;
        let graph_layout = metal_graph_pagerank_layout(self.node_count).map_err(candle_error)?;
        let phase = |phase| MetalGraphPageRankChunk {
            incoming_offsets: self.incoming_offsets.clone(),
            incoming_neighbors: incoming_neighbors.clone(),
            incoming_edges: incoming_edges.clone(),
            incoming_overlay: incoming_overlay.clone(),
            visible_nodes: visible_mask.clone(),
            edge_active: edge_active.clone(),
            edge_layers: edge_layers.clone(),
            node_count: self.node_count,
            edge_count: self.edge_count,
            adjacency_count,
            incoming_overlay_count: self.incoming_overlay.rows.len(),
            visible_count,
            layer_mask,
            damping,
            tolerance,
            phase,
        };
        for begin in (METAL_GRAPH_PAGERANK_NODE_TILE..self.node_count)
            .step_by(METAL_GRAPH_PAGERANK_NODE_TILE)
        {
            ensure_graph_execution(cancellation, deadline)?;
            let count = (self.node_count - begin).min(METAL_GRAPH_PAGERANK_NODE_TILE);
            workspace = workspace
                .apply_op1_no_bwd(&phase(MetalGraphPageRankPhase::Initialize { begin, count }))
                .map_err(candle_error)?;
        }
        let mut control = Vec::new();
        for range_begin in (0..self.edge_count).step_by(METAL_GRAPH_PAGERANK_EDGE_TILE) {
            ensure_graph_execution(cancellation, deadline)?;
            let range_count = (self.edge_count - range_begin).min(METAL_GRAPH_PAGERANK_EDGE_TILE);
            workspace = workspace
                .apply_op1_no_bwd(&MetalGraphPageRankDegreeChunk {
                    edge_targets: edge_targets.clone(),
                    edge_sources: edge_sources.clone(),
                    visible_nodes: visible_mask.clone(),
                    edge_active: edge_active.clone(),
                    edge_layers: edge_layers.clone(),
                    node_count: self.node_count,
                    edge_count: self.edge_count,
                    visible_count,
                    layer_mask,
                    damping,
                    tolerance,
                    range_begin,
                    range_count,
                })
                .map_err(candle_error)?;
            control = metal_read_u32_words(&workspace, graph_layout.control, 4)?;
            if control.get(2).copied().unwrap_or(1) != 0 {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal PageRank rejected corrupt resident graph metadata",
                ));
            }
            ensure_graph_execution(cancellation, deadline)?;
        }
        let mut completed = control.get(1).copied().unwrap_or(0) as usize;
        while completed < max_iterations && control.first().copied().unwrap_or(0) == 0 {
            for begin in (0..self.node_count).step_by(METAL_GRAPH_PAGERANK_NODE_TILE) {
                ensure_graph_execution(cancellation, deadline)?;
                let count = (self.node_count - begin).min(METAL_GRAPH_PAGERANK_NODE_TILE);
                workspace = workspace
                    .apply_op1_no_bwd(&phase(MetalGraphPageRankPhase::Dangling {
                        iteration: completed,
                        begin,
                        count,
                    }))
                    .map_err(candle_error)?;
            }
            for begin in (0..self.node_count).step_by(METAL_GRAPH_PAGERANK_NODE_TILE) {
                ensure_graph_execution(cancellation, deadline)?;
                let count = (self.node_count - begin).min(METAL_GRAPH_PAGERANK_NODE_TILE);
                workspace = workspace
                    .apply_op1_no_bwd(&phase(MetalGraphPageRankPhase::PullPrepare {
                        iteration: completed,
                        begin,
                        count,
                    }))
                    .map_err(candle_error)?;
            }
            loop {
                for begin in (0..self.node_count).step_by(METAL_GRAPH_PAGERANK_NODE_TILE) {
                    ensure_graph_execution(cancellation, deadline)?;
                    let count = (self.node_count - begin).min(METAL_GRAPH_PAGERANK_NODE_TILE);
                    workspace = workspace
                        .apply_op1_no_bwd(&phase(MetalGraphPageRankPhase::PullScan {
                            iteration: completed,
                            begin,
                            count,
                            reset_pending: begin == 0,
                        }))
                        .map_err(candle_error)?;
                    control = metal_read_u32_words(&workspace, graph_layout.control, 4)?;
                    if control.get(2).copied().unwrap_or(1) != 0 {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal PageRank rejected corrupt resident graph metadata",
                        ));
                    }
                    ensure_graph_execution(cancellation, deadline)?;
                }
                if control.get(3).copied().unwrap_or(1) == 0 {
                    break;
                }
            }
            for begin in (0..self.node_count).step_by(METAL_GRAPH_PAGERANK_NODE_TILE) {
                ensure_graph_execution(cancellation, deadline)?;
                let count = (self.node_count - begin).min(METAL_GRAPH_PAGERANK_NODE_TILE);
                workspace = workspace
                    .apply_op1_no_bwd(&phase(MetalGraphPageRankPhase::Delta {
                        iteration: completed,
                        begin,
                        count,
                    }))
                    .map_err(candle_error)?;
            }
            control = metal_read_u32_words(&workspace, graph_layout.control, 4)?;
            if control.get(2).copied().unwrap_or(1) != 0 {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal PageRank rejected corrupt resident graph metadata",
                ));
            }
            completed = completed.checked_add(1).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "PageRank host iteration counter overflow",
                )
            })?;
        }
        ensure_graph_execution(cancellation, deadline)?;
        let publication_words = visible_count.checked_mul(2).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal PageRank publication size overflow",
            )
        })?;
        for range_begin in (0..visible_count).step_by(METAL_GRAPH_PAGERANK_NODE_TILE) {
            ensure_graph_execution(cancellation, deadline)?;
            let range_count = (visible_count - range_begin).min(METAL_GRAPH_PAGERANK_NODE_TILE);
            workspace = workspace
                .apply_op1_no_bwd(&MetalGraphPageRankPublish {
                    selected_rows: visible_rows.clone(),
                    node_count: self.node_count,
                    edge_count: self.edge_count,
                    adjacency_count,
                    visible_count,
                    layer_mask,
                    damping,
                    tolerance,
                    range_begin,
                    range_count,
                })
                .map_err(candle_error)?;
        }
        let control = metal_read_u32_words(&workspace, graph_layout.control, 4)?;
        if control.get(2).copied().unwrap_or(1) != 0 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal PageRank publication rejected an invalid selected row",
            ));
        }
        let rank_words =
            metal_read_u32_words(&workspace, graph_layout.publication, publication_words)?;
        if rank_words.len() != publication_words {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal PageRank publication length mismatch",
            ));
        }
        let score = rank_words
            .chunks_exact(2)
            .map(|words| f64::from_bits(u64::from(words[0]) | (u64::from(words[1]) << 32)))
            .collect();
        let node_rows = visible_rows.to_vec1::<u32>().map_err(candle_error)?;
        ensure_graph_execution(cancellation, deadline)?;
        Ok(ResidentGraphProcedureResult::PageRank { node_rows, score })
    }

    fn visible_edge_endpoints(
        &self,
        device: &Device,
        visible_rows: &Tensor,
        layers: LayerMask,
        cancellation: &CancellationToken,
        deadline: Option<std::time::Instant>,
    ) -> Result<(Tensor, Tensor)> {
        let (sources, _, targets) = self.expand_pipeline_rows_with_deadline(
            device,
            visible_rows,
            &super::ResidentExpansion {
                direction: super::ResidentDirection::Outgoing,
                relationship_types: Vec::new(),
                end_labels: Vec::new(),
                end_equals_start: false,
                optional: false,
                end_predicates: Vec::new(),
            },
            layers,
            self.edge_count,
            cancellation,
            deadline,
        )?;
        ensure_graph_execution(cancellation, deadline)?;
        Ok((sources, targets))
    }

    fn selected_integer_column(
        &self,
        device: &Device,
        property: PropertyId,
        rows: &[u32],
    ) -> Result<(Tensor, Tensor)> {
        let column = self.integer_nodes.get(&property).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "resident property is not an integer column",
            )
        })?;
        if rows.iter().any(|row| *row as usize >= column.rows) {
            return Err(Error::new(
                ErrorCode::QueryType,
                "resident integer operator row is out of bounds",
            ));
        }
        let row_tensor = Tensor::from_slice(rows, rows.len(), device).map_err(candle_error)?;
        self.selected_integer_column_tensor(property, &row_tensor)
    }

    fn selected_integer_column_tensor(
        &self,
        property: PropertyId,
        rows: &Tensor,
    ) -> Result<(Tensor, Tensor)> {
        let column = self.integer_nodes.get(&property).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "resident property is not an integer column",
            )
        })?;
        // Metal's index_select has no valid zero-length launch configuration. An empty binding
        // is nevertheless a valid query result (for example a non-matching indexed property
        // predicate), so preserve the typed empty columns without a host fallback.
        if rows.elem_count() == 0 {
            return Ok((
                Tensor::zeros(0, DType::I64, rows.device()).map_err(candle_error)?,
                Tensor::zeros(0, DType::U8, rows.device()).map_err(candle_error)?,
            ));
        }
        let row_validity = rows.ne(super::RESIDENT_NULL_ROW).map_err(candle_error)?;
        let safe_rows = row_validity
            .where_cond(
                rows,
                &Tensor::zeros(rows.shape(), DType::U32, rows.device()).map_err(candle_error)?,
            )
            .map_err(candle_error)?;
        let values = column
            .values
            .as_ref()
            .ok_or_else(|| Error::internal("integer column values are absent"))?
            .index_select(&safe_rows, 0)
            .map_err(candle_error)?;
        let validity = column
            .validity
            .as_ref()
            .ok_or_else(|| Error::internal("integer column validity is absent"))?
            .index_select(&safe_rows, 0)
            .and_then(|validity| validity.broadcast_mul(&row_validity))
            .map_err(candle_error)?;
        Ok((values, validity))
    }

