const METAL_SEGMENTED_GRAPH_RETAINED_ALLOCATION_COUNT: usize = 7;
const METAL_SEGMENTED_GRAPH_PRIVATE_ALLOCATION_COUNT: usize = 18;
#[cfg(test)]
const METAL_SEGMENTED_GRAPH_SOURCE_ARENA_ALLOCATION: usize = 3;

fn metal_nullable_relation_packet_private_bytes(
    graph_words: usize,
    output_words: usize,
) -> Result<usize> {
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal nullable-relation private-buffer scratch accounting overflow",
        )
    };
    // Each non-empty conversion lane rounds to less than twice its logical bytes, and their
    // total logical width is bounded by the final graph packet. The final concatenation is a
    // second rounded packet, so 4x the graph packet's raw bytes is a strict upper bound.
    let graph_private = graph_words
        .checked_mul(4 * size_of::<i64>())
        .ok_or_else(overflow)?;
    let output_logical = output_words
        .max(1)
        .checked_mul(size_of::<i64>())
        .ok_or_else(overflow)?;
    let output_private = output_logical
        .checked_next_power_of_two()
        .ok_or_else(overflow)?;
    // The completed private output and the independently pooled shared `to_vec1` staging buffer
    // have the same rounded shape and can both remain resident through readback.
    graph_private
        .checked_add(output_private)
        .and_then(|bytes| bytes.checked_add(output_private))
        .ok_or_else(overflow)
}

#[cfg(any(
    test,
    all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))
))]
fn validate_metal_segmented_graph_stage_widths(
    group_count: usize,
    reduction_count: usize,
    maximum_order_width: usize,
) -> Result<()> {
    if group_count > super::RESIDENT_SEGMENTED_AGGREGATION_MAX_GROUP_KEYS
        || reduction_count > super::RESIDENT_SEGMENTED_AGGREGATION_MAX_AGGREGATES
        || maximum_order_width > METAL_SEGMENTED_GRAPH_MAX_ORDER_KEYS
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal segmented graph stage width exceeds its bounded native ABI",
        ));
    }
    Ok(())
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Debug, PartialEq, Eq)]
struct MetalSegmentedGraphScratchLayout {
    /// Nested nullable command plus per-call uploads/fallbacks that remain live during dispatch.
    retained_bytes: [usize; METAL_SEGMENTED_GRAPH_RETAINED_ALLOCATION_COUNT],
    /// Logical bytes requested by each CustomOp buffer, in construction order.
    private_logical_bytes: [usize; METAL_SEGMENTED_GRAPH_PRIVATE_ALLOCATION_COUNT],
    /// Candle's Metal private pool rounds every non-empty allocation to a power of two.
    private_allocated_bytes: [usize; METAL_SEGMENTED_GRAPH_PRIVATE_ALLOCATION_COUNT],
    total_bytes: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl MetalSegmentedGraphScratchLayout {
    fn build(
        retained_bytes: [usize; METAL_SEGMENTED_GRAPH_RETAINED_ALLOCATION_COUNT],
        private_logical_bytes: [usize; METAL_SEGMENTED_GRAPH_PRIVATE_ALLOCATION_COUNT],
    ) -> Result<Self> {
        let overflow = || {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal segmented graph actual-byte scratch accounting overflow",
            )
        };
        let private_allocated_bytes = private_logical_bytes
            .map(|bytes| bytes.max(1).checked_next_power_of_two())
            .into_iter()
            .collect::<Option<Vec<_>>>()
            .ok_or_else(overflow)?
            .try_into()
            .map_err(|_| Error::internal("Metal segmented graph allocation count changed"))?;
        let total_bytes = retained_bytes
            .into_iter()
            .chain(private_allocated_bytes)
            .try_fold(0_usize, |total, bytes| {
                total.checked_add(bytes).ok_or_else(overflow)
            })?;
        Ok(Self {
            retained_bytes,
            private_logical_bytes,
            private_allocated_bytes,
            total_bytes,
        })
    }

    fn validate_private_shape(
        &self,
        private_logical_bytes: [usize; METAL_SEGMENTED_GRAPH_PRIVATE_ALLOCATION_COUNT],
    ) -> Result<()> {
        let rebuilt = Self::build(self.retained_bytes, private_logical_bytes)?;
        if rebuilt.private_logical_bytes != self.private_logical_bytes
            || rebuilt.private_allocated_bytes != self.private_allocated_bytes
            || rebuilt.total_bytes != self.total_bytes
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal segmented graph scratch layout changed after admission",
            ));
        }
        Ok(())
    }
}

