#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_source_maximum_items(
    path: &ResidentVariablePathRequest,
    kind: ResidentQuantifierEntityKind,
    skip: u32,
) -> Result<usize> {
    let maximum_hops = path
        .segments
        .iter()
        .try_fold(0_usize, |total, segment| {
            let segment_maximum = segment
                .maximum_hops
                .map_or(path.expected_edge_slots, |maximum| maximum as usize)
                .min(path.expected_edge_slots);
            total
                .checked_add(segment_maximum)
                .ok_or_else(|| metal_quantifier_overflow("Metal entity-list path width overflow"))
        })?
        .min(path.expected_edge_slots);
    let full = match kind {
        ResidentQuantifierEntityKind::Node => maximum_hops
            .checked_add(1)
            .ok_or_else(|| metal_quantifier_overflow("Metal entity-list node width overflow"))?,
        ResidentQuantifierEntityKind::Relationship => maximum_hops,
    };
    Ok(full.saturating_sub(skip as usize))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_source_maximum_dependencies(
    path: &ResidentVariablePathRequest,
    kind: ResidentQuantifierEntityKind,
    properties: &[ResidentQuantifierEntityProperty],
) -> Result<usize> {
    let property_count = properties
        .iter()
        .filter(|property| property.property.is_some())
        .count();
    let entity_rows = match kind {
        ResidentQuantifierEntityKind::Node => path.expected_node_slots,
        ResidentQuantifierEntityKind::Relationship => path.expected_edge_slots,
    };
    path.expected_node_slots
        .checked_add(path.expected_edge_slots)
        .and_then(|identities| {
            entity_rows
                .checked_mul(property_count)
                .and_then(|properties| identities.checked_add(properties))
        })
        .ok_or_else(|| metal_quantifier_overflow("Metal entity dependency bound overflow"))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_entity_group_capacities(
    path_capacity: usize,
    group_enabled: bool,
) -> Result<(usize, usize)> {
    if !group_enabled {
        return Ok((1, path_capacity.max(1)));
    }
    let table_capacity = path_capacity
        .checked_mul(2)
        .and_then(usize::checked_next_power_of_two)
        .ok_or_else(|| metal_quantifier_overflow("Metal entity group hash table overflow"))?;
    let sort_capacity = path_capacity
        .checked_next_power_of_two()
        .ok_or_else(|| metal_quantifier_overflow("Metal entity group sort capacity overflow"))?;
    if table_capacity > u32::MAX as usize || sort_capacity > u32::MAX as usize {
        return Err(metal_quantifier_overflow(
            "Metal entity group capacity exceeds the native u32 ABI",
        ));
    }
    Ok((table_capacity, sort_capacity))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_entity_scratch_bytes(
    path: &ResidentVariablePathRequest,
    entity_kind: ResidentQuantifierEntityKind,
    group_enabled: bool,
    group_table_capacity: usize,
    group_sort_capacity: usize,
) -> Result<usize> {
    let path_capacity = path.maximum_output_rows;
    let entity_rows = match entity_kind {
        ResidentQuantifierEntityKind::Node => path.expected_node_slots,
        ResidentQuantifierEntityKind::Relationship => path.expected_edge_slots,
    };
    let combined_entities = path
        .expected_node_slots
        .checked_add(path.expected_edge_slots)
        .ok_or_else(|| metal_quantifier_overflow("Metal entity dependency domain overflow"))?;
    if combined_entities > u32::MAX as usize {
        return Err(metal_quantifier_overflow(
            "Metal entity dependency domain exceeds the native u32 scan ABI",
        ));
    }
    let mut u32_words = 16_usize;
    for (words, label) in [
        (
            metal_quantifier_mul(
                path_capacity,
                4,
                "Metal entity group scan allocation overflow",
            )?,
            "Metal entity group scan allocation overflow",
        ),
        (
            group_sort_capacity,
            "Metal entity group representative allocation overflow",
        ),
        (
            group_table_capacity,
            "Metal entity group hash table allocation overflow",
        ),
        (
            path.expected_node_slots.max(1),
            "Metal entity node dependency allocation overflow",
        ),
        (
            path.expected_edge_slots.max(1),
            "Metal entity relationship dependency allocation overflow",
        ),
        (
            entity_rows.max(1),
            "Metal entity property dependency allocation overflow",
        ),
        (
            metal_quantifier_mul(
                combined_entities.max(1),
                2,
                "Metal entity dependency prefix allocation overflow",
            )?,
            "Metal entity dependency prefix allocation overflow",
        ),
    ] {
        u32_words = metal_quantifier_add(u32_words, words, label)?;
    }
    let u32_bytes = metal_quantifier_mul(
        u32_words,
        size_of::<u32>(),
        "Metal entity u32 scratch allocation overflow",
    )?;
    let hash_rows = if group_enabled { path_capacity } else { 1 };
    let hash_bytes = metal_quantifier_mul(
        hash_rows,
        size_of::<u64>(),
        "Metal entity structural-hash allocation overflow",
    )?;
    metal_quantifier_add(
        u32_bytes,
        hash_bytes,
        "Metal entity scratch allocation overflow",
    )
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_entity_predicate_property<'a>(
    expression: &'a ResidentQuantifierExpression,
    variable: ResidentQuantifierSlot,
) -> Option<&'a str> {
    let ResidentQuantifierExpression::Property { source, key } = expression else {
        return None;
    };
    let ResidentQuantifierExpression::Slot(slot) = source.as_ref() else {
        return None;
    };
    (*slot == variable).then_some(key.as_str())
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_entity_predicate_literal(
    expression: &ResidentQuantifierExpression,
) -> Option<&ResidentQuantifierValue> {
    let ResidentQuantifierExpression::Literal(value) = expression else {
        return None;
    };
    matches!(
        value,
        ResidentQuantifierValue::Null
            | ResidentQuantifierValue::Boolean(_)
            | ResidentQuantifierValue::Integer(_)
            | ResidentQuantifierValue::Float(_)
            | ResidentQuantifierValue::String(_)
    )
    .then_some(value)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_predicate_binding(
    output: ResidentQuantifierSlot,
    expression: &ResidentQuantifierExpression,
    properties: &[ResidentQuantifierEntityProperty],
    encoder: &mut MetalQuantifierEncoder,
) -> Result<Option<MetalQuantifierEntityBinding>> {
    let ResidentQuantifierExpression::Predicate {
        kind,
        variable,
        list,
        predicate,
    } = expression
    else {
        return Ok(None);
    };
    let ResidentQuantifierExpression::Slot(source) = list.as_ref() else {
        return Ok(None);
    };
    let ResidentQuantifierExpression::Binary {
        left,
        operation,
        right,
    } = predicate.as_ref()
    else {
        return Ok(None);
    };
    if !matches!(
        operation,
        ResidentQuantifierBinary::Equal
            | ResidentQuantifierBinary::NotEqual
            | ResidentQuantifierBinary::Less
            | ResidentQuantifierBinary::LessOrEqual
            | ResidentQuantifierBinary::Greater
            | ResidentQuantifierBinary::GreaterOrEqual
    ) {
        return Ok(None);
    }
    let (key, literal, reversed) = if let (Some(key), Some(literal)) = (
        metal_quantifier_entity_predicate_property(left, *variable),
        metal_quantifier_entity_predicate_literal(right),
    ) {
        (key, literal, false)
    } else if let (Some(literal), Some(key)) = (
        metal_quantifier_entity_predicate_literal(left),
        metal_quantifier_entity_predicate_property(right, *variable),
    ) {
        (key, literal, true)
    } else {
        return Ok(None);
    };
    let property_lane = properties
        .iter()
        .position(|property| property.key == key)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal entity quantifier predicate property is absent from the sealed source",
            )
        })?;
    Ok(Some(MetalQuantifierEntityBinding {
        output,
        source: *source,
        mode: 1,
        kind: Some(*kind),
        property_lane,
        operation: *operation,
        literal: encoder.encode_value(literal)?,
        reversed,
    }))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_build_entity_source_plan(
    request: &ResidentQuantifierProgramRequest,
    encoder: &mut MetalQuantifierEncoder,
) -> Result<Option<MetalQuantifierEntitySourcePlan>> {
    let ResidentQuantifierSource::VariablePathEntityList {
        path,
        output,
        entity_kind,
        skip,
        properties,
        ..
    } = &request.source
    else {
        return Ok(None);
    };
    if properties.len() > 1 {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal entity quantifier currently admits one canonical property lane per fused command",
        ));
    }
    let (group_stage, project_stage, list_slot, count_slots, project) = match request
        .program
        .stages
        .as_slice()
    {
        [
            ResidentQuantifierStage::Project {
                keep_scope: false,
                bindings,
            },
        ] => (None, 0_usize, *output, BTreeSet::new(), bindings.as_slice()),
        [
            ResidentQuantifierStage::GroupCount {
                groups,
                count_outputs,
            },
            ResidentQuantifierStage::Project {
                keep_scope: false,
                bindings,
            },
        ] if groups.len() == 1
            && !count_outputs.is_empty()
            && matches!(
                &groups[0].expression,
                ResidentQuantifierExpression::Slot(slot) if slot == output
            ) =>
        {
            (
                Some(0_usize),
                1_usize,
                groups[0].output,
                count_outputs.iter().copied().collect(),
                bindings.as_slice(),
            )
        }
        _ => {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal entity quantifier requires one parallel projection, optionally preceded by structural GroupCount",
            ));
        }
    };
    let mut compiled = Vec::with_capacity(project.len());
    for binding in project {
        if let ResidentQuantifierExpression::Slot(source) = &binding.expression {
            let mode = if *source == list_slot {
                0
            } else if count_slots.contains(source) {
                2
            } else {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal entity quantifier native projection admits only its structural entity-list or count slot",
                ));
            };
            compiled.push(MetalQuantifierEntityBinding {
                output: binding.output,
                source: *source,
                mode,
                kind: None,
                property_lane: 0,
                operation: ResidentQuantifierBinary::Equal,
                literal: METAL_QUANTIFIER_IMMUTABLE_HANDLE,
                reversed: false,
            });
            continue;
        }
        let Some(binding) = metal_quantifier_predicate_binding(
            binding.output,
            &binding.expression,
            properties,
            encoder,
        )?
        else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal entity quantifier projection contains an expression outside the native scalar-property predicate subset",
            ));
        };
        if binding.source != list_slot {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal entity quantifier predicate reads a list outside the fused source",
            ));
        }
        compiled.push(binding);
    }
    let outputs = request
        .program
        .outputs
        .iter()
        .map(|output| output.source)
        .collect::<BTreeSet<_>>();
    let projected = compiled
        .iter()
        .map(|binding| binding.output)
        .collect::<BTreeSet<_>>();
    if !outputs.is_subset(&projected) {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal entity quantifier final output is not owned by its native projection",
        ));
    }
    let (group_table_capacity, group_sort_capacity) =
        metal_quantifier_entity_group_capacities(path.maximum_output_rows, group_stage.is_some())?;
    let scratch_bytes = metal_quantifier_entity_scratch_bytes(
        path,
        *entity_kind,
        group_stage.is_some(),
        group_table_capacity,
        group_sort_capacity,
    )?;
    Ok(Some(MetalQuantifierEntitySourcePlan {
        path: MetalVariablePathPlan::build(path)?,
        path_packet_base: 0,
        source_base: 0,
        output: *output,
        entity_kind: *entity_kind,
        skip: *skip,
        properties: properties.clone(),
        group_stage,
        project_stage,
        bindings: compiled,
        maximum_items: metal_quantifier_source_maximum_items(path, *entity_kind, *skip)?,
        maximum_dependencies: metal_quantifier_source_maximum_dependencies(
            path,
            *entity_kind,
            properties,
        )?,
        group_table_capacity,
        group_sort_capacity,
        scratch_bytes,
    }))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl MetalQuantifierPlan {
    fn build(
        resident: &CandleResident,
        request: &ResidentQuantifierProgramRequest,
    ) -> Result<Self> {
        request.validate()?;
        let graph_free_capacity = matches!(
            &request.source,
            ResidentQuantifierSource::Unit | ResidentQuantifierSource::Range { .. }
        )
        .then(|| metal_quantifier_capacity(request))
        .transpose()?;
        let mut encoder = MetalQuantifierEncoder::new(request);
        encoder.encode_stages(
            request,
            graph_free_capacity
                .as_ref()
                .map_or(&[][..], |capacity| capacity.project_allocations.as_slice()),
            graph_free_capacity
                .as_ref()
                .map_or(&[][..], |capacity| capacity.unwind_allocations.as_slice()),
            graph_free_capacity
                .as_ref()
                .map_or(&[][..], |capacity| capacity.filter_allocations.as_slice()),
        )?;
        let mut entity_source = metal_quantifier_build_entity_source_plan(request, &mut encoder)?;
        if let (Some(source), ResidentQuantifierSource::VariablePathEntityList { path, .. }) =
            (entity_source.as_mut(), &request.source)
        {
            if resident.node_count != path.expected_node_slots
                || resident.edge_count != path.expected_edge_slots
            {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal entity staging estimate targets a different resident graph shape",
                ));
            }
            source.scratch_bytes = metal_quantifier_add(
                source.scratch_bytes,
                metal_quantifier_entity_staging_bytes(resident, path, source)?,
                "Metal fused entity staging admission overflow",
            )?;
        }
        let capacity = if entity_source.is_some() {
            let final_row_bound = match &request.source {
                ResidentQuantifierSource::VariablePathEntityList { path, .. } => {
                    path.maximum_output_rows.min(request.max_rows)
                }
                ResidentQuantifierSource::Unit | ResidentQuantifierSource::Range { .. } => {
                    unreachable!("entity capacity without an entity source")
                }
            };
            MetalQuantifierCapacity {
                final_row_bound,
                eval_lane_count: 1,
                dynamic: MetalQuantifierAllocation::default(),
                output_cells: metal_quantifier_mul(
                    final_row_bound,
                    request.program.outputs.len(),
                    "Metal entity scalar output cell capacity overflow",
                )?,
                output_items: 0,
                output_bytes: 0,
                project_allocations: Vec::new(),
                unwind_allocations: Vec::new(),
                filter_allocations: Vec::new(),
                stage_row_bounds: Vec::new(),
            }
        } else {
            graph_free_capacity.ok_or_else(|| {
                Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal entity quantifier did not produce its required fused source plan",
                )
            })?
        };
        let obligations = request.obligations();

        let slot_cells = metal_quantifier_mul(
            request.max_rows,
            usize::from(request.program.slot_count),
            "Metal quantifier row-slot arena overflow",
        )?;
        let mut cursor = 0_usize;
        let row_a_base = cursor;
        cursor = metal_quantifier_add(cursor, slot_cells, "Metal quantifier scratch overflow")?;
        let row_b_base = cursor;
        cursor = metal_quantifier_add(cursor, slot_cells, "Metal quantifier scratch overflow")?;
        let lineage_a_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            request.max_rows,
            "Metal quantifier lineage arena overflow",
        )?;
        let lineage_b_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            request.max_rows,
            "Metal quantifier lineage arena overflow",
        )?;
        let dynamic_cell_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            metal_quantifier_mul(
                capacity.dynamic.cells.max(1),
                METAL_QUANTIFIER_VALUE_WORDS,
                "Metal quantifier dynamic-cell arena overflow",
            )?,
            "Metal quantifier scratch overflow",
        )?;
        let dynamic_item_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            capacity.dynamic.items.max(1),
            "Metal quantifier dynamic-item arena overflow",
        )?;
        let dynamic_byte_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            metal_quantifier_packed_words(capacity.dynamic.bytes.max(1))?,
            "Metal quantifier dynamic-byte arena overflow",
        )?;
        let eval_frame_base = cursor;
        let frame_capacity = encoder.expressions.len().saturating_add(1).max(2);
        let eval_lane_count = if entity_source.is_some() {
            1
        } else {
            capacity.eval_lane_count
        };
        cursor = metal_quantifier_add(
            cursor,
            metal_quantifier_mul(
                metal_quantifier_mul(
                    eval_lane_count,
                    frame_capacity,
                    "Metal quantifier evaluator-lane arena overflow",
                )?,
                METAL_QUANTIFIER_EVAL_FRAME_WORDS,
                "Metal quantifier evaluator-frame arena overflow",
            )?,
            "Metal quantifier scratch overflow",
        )?;
        let compare_frame_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            metal_quantifier_mul(
                frame_capacity,
                METAL_QUANTIFIER_COMPARE_FRAME_WORDS,
                "Metal quantifier comparison-frame arena overflow",
            )?,
            "Metal quantifier scratch overflow",
        )?;
        let filter_flag_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            eval_lane_count,
            "Metal quantifier filter-flag arena overflow",
        )?;
        let filter_rank_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            eval_lane_count,
            "Metal quantifier filter-rank arena overflow",
        )?;
        let control_base = cursor;
        cursor = metal_quantifier_add(
            cursor,
            METAL_QUANTIFIER_SCRATCH_CONTROL_WORDS,
            "Metal quantifier control arena overflow",
        )?;
        let scratch = MetalQuantifierScratchLayout {
            row_a_base,
            row_b_base,
            lineage_a_base,
            lineage_b_base,
            dynamic_cell_base,
            dynamic_item_base,
            dynamic_byte_base,
            eval_frame_base,
            compare_frame_base,
            filter_flag_base,
            filter_rank_base,
            control_base,
            words: cursor,
        };

        let receipt_base = METAL_QUANTIFIER_OUTPUT_HEADER_WORDS;
        let root_base = metal_quantifier_add(
            receipt_base,
            metal_quantifier_mul(
                obligations.len(),
                METAL_QUANTIFIER_OUTPUT_RECEIPT_WORDS,
                "Metal quantifier receipt packet overflow",
            )?,
            "Metal quantifier output packet overflow",
        )?;
        let root_capacity = metal_quantifier_mul(
            capacity.final_row_bound,
            request.program.outputs.len(),
            "Metal quantifier output-root arena overflow",
        )?;
        let cell_base = metal_quantifier_add(
            root_base,
            root_capacity,
            "Metal quantifier output packet overflow",
        )?;
        let cell_capacity = capacity.output_cells.max(1);
        let item_base = metal_quantifier_add(
            cell_base,
            metal_quantifier_mul(
                cell_capacity,
                METAL_QUANTIFIER_VALUE_WORDS,
                "Metal quantifier output-cell arena overflow",
            )?,
            "Metal quantifier output packet overflow",
        )?;
        let item_capacity = capacity.output_items.max(1);
        let byte_base = metal_quantifier_add(
            item_base,
            item_capacity,
            "Metal quantifier output packet overflow",
        )?;
        let byte_capacity = capacity.output_bytes.max(1);
        let scalar_output_words = metal_quantifier_add(
            byte_base,
            metal_quantifier_packed_words(byte_capacity)?,
            "Metal quantifier output packet overflow",
        )?;
        let entity_output = if let Some(source) = &entity_source {
            let path = match &request.source {
                ResidentQuantifierSource::VariablePathEntityList { path, .. } => path,
                ResidentQuantifierSource::Unit | ResidentQuantifierSource::Range { .. } => {
                    unreachable!("entity source plan without source")
                }
            };
            let base = scalar_output_words;
            let path_descriptor_base = metal_quantifier_add(
                base,
                METAL_QUANTIFIER_ENTITY_OUTPUT_HEADER_WORDS,
                "Metal entity output header overflow",
            )?;
            let path_edge_base = metal_quantifier_add(
                path_descriptor_base,
                metal_quantifier_mul(
                    path.maximum_output_rows,
                    3,
                    "Metal entity path descriptor overflow",
                )?,
                "Metal entity path output overflow",
            )?;
            let path_node_base = metal_quantifier_add(
                path_edge_base,
                metal_quantifier_mul(
                    path.maximum_output_rows,
                    path.expected_edge_slots,
                    "Metal entity relationship-trail output overflow",
                )?,
                "Metal entity path output overflow",
            )?;
            let path_segment_base = metal_quantifier_add(
                path_node_base,
                metal_quantifier_mul(
                    path.maximum_output_rows,
                    path.expected_edge_slots.saturating_add(1),
                    "Metal entity node-trail output overflow",
                )?,
                "Metal entity path output overflow",
            )?;
            let entity_descriptor_base = metal_quantifier_add(
                path_segment_base,
                metal_quantifier_mul(
                    path.maximum_output_rows,
                    path.segments.len(),
                    "Metal entity segment-lineage output overflow",
                )?,
                "Metal entity path output overflow",
            )?;
            let entity_output_capacity = metal_quantifier_mul(
                capacity.final_row_bound,
                request.program.outputs.len(),
                "Metal entity sidecar descriptor capacity overflow",
            )?;
            let entity_item_base = metal_quantifier_add(
                entity_descriptor_base,
                metal_quantifier_mul(
                    entity_output_capacity,
                    METAL_QUANTIFIER_ENTITY_OUTPUT_DESCRIPTOR_WORDS,
                    "Metal entity sidecar descriptor overflow",
                )?,
                "Metal entity sidecar output overflow",
            )?;
            let entity_item_capacity = metal_quantifier_mul(
                entity_output_capacity,
                source.maximum_items,
                "Metal entity sidecar item capacity overflow",
            )?;
            let dependency_base = metal_quantifier_add(
                entity_item_base,
                metal_quantifier_mul(
                    entity_item_capacity,
                    METAL_QUANTIFIER_ENTITY_ITEM_WORDS,
                    "Metal entity sidecar item output overflow",
                )?,
                "Metal entity sidecar output overflow",
            )?;
            Some(MetalQuantifierEntityOutputLayout {
                base,
                path_descriptor_base,
                path_edge_base,
                path_node_base,
                path_segment_base,
                entity_descriptor_base,
                entity_item_base,
                dependency_base,
                path_capacity: path.maximum_output_rows,
                edge_slots: path.expected_edge_slots,
                segment_count: path.segments.len(),
                entity_output_capacity,
                entity_item_capacity,
                dependency_capacity: source.maximum_dependencies,
            })
        } else {
            None
        };
        let output_words = if let Some(entity) = &entity_output {
            metal_quantifier_add(
                entity.dependency_base,
                metal_quantifier_mul(
                    entity.dependency_capacity,
                    METAL_QUANTIFIER_ENTITY_DEPENDENCY_WORDS,
                    "Metal entity dependency output overflow",
                )?,
                "Metal entity output packet overflow",
            )?
        } else {
            scalar_output_words
        };
        let output = MetalQuantifierOutputLayout {
            receipt_base,
            root_base,
            cell_base,
            item_base,
            byte_base,
            root_capacity,
            cell_capacity,
            item_capacity,
            byte_capacity,
            words: output_words,
        };

        let immutable_bytes = metal_quantifier_words(&encoder.immutable_bytes);
        let stage_base = METAL_QUANTIFIER_PROGRAM_HEADER_WORDS;
        let stage_data_base = metal_quantifier_add(
            stage_base,
            metal_quantifier_mul(
                encoder.stages.len(),
                METAL_QUANTIFIER_STAGE_WORDS,
                "Metal quantifier stage packet overflow",
            )?,
            "Metal quantifier program packet overflow",
        )?;
        let expression_base = metal_quantifier_add(
            stage_data_base,
            encoder.stage_data.len(),
            "Metal quantifier program packet overflow",
        )?;
        let child_base = metal_quantifier_add(
            expression_base,
            metal_quantifier_mul(
                encoder.expressions.len(),
                METAL_QUANTIFIER_EXPRESSION_WORDS,
                "Metal quantifier expression packet overflow",
            )?,
            "Metal quantifier program packet overflow",
        )?;
        let immutable_cell_base = metal_quantifier_add(
            child_base,
            encoder.children.len(),
            "Metal quantifier program packet overflow",
        )?;
        let immutable_item_base = metal_quantifier_add(
            immutable_cell_base,
            metal_quantifier_mul(
                encoder.immutable_cells.len(),
                METAL_QUANTIFIER_VALUE_WORDS,
                "Metal quantifier immutable-cell packet overflow",
            )?,
            "Metal quantifier program packet overflow",
        )?;
        let immutable_byte_base = metal_quantifier_add(
            immutable_item_base,
            encoder.immutable_items.len(),
            "Metal quantifier program packet overflow",
        )?;
        let output_source_base = metal_quantifier_add(
            immutable_byte_base,
            immutable_bytes.len(),
            "Metal quantifier program packet overflow",
        )?;
        let receipt_descriptor_base = metal_quantifier_add(
            output_source_base,
            request.program.outputs.len(),
            "Metal quantifier program packet overflow",
        )?;
        let base_program_words = metal_quantifier_add(
            receipt_descriptor_base,
            metal_quantifier_mul(
                obligations.len(),
                METAL_QUANTIFIER_RECEIPT_DESCRIPTOR_WORDS,
                "Metal quantifier receipt-descriptor packet overflow",
            )?,
            "Metal quantifier program packet overflow",
        )?;
        let program_words = if let Some(source) = entity_source.as_mut() {
            source.source_base = base_program_words;
            let binding_base = metal_quantifier_add(
                source.source_base,
                METAL_QUANTIFIER_ENTITY_SOURCE_HEADER_WORDS,
                "Metal entity source header overflow",
            )?;
            source.path_packet_base = metal_quantifier_add(
                binding_base,
                metal_quantifier_mul(
                    source.bindings.len(),
                    METAL_QUANTIFIER_ENTITY_BINDING_WORDS,
                    "Metal entity binding packet overflow",
                )?,
                "Metal entity source packet overflow",
            )?;
            metal_quantifier_add(
                source.path_packet_base,
                source.path.packet.len(),
                "Metal entity embedded path packet overflow",
            )?
        } else {
            base_program_words
        };

        let expression_count = encoder.expressions.len();
        let immutable_cell_count = encoder.immutable_cells.len();
        let immutable_item_count = encoder.immutable_items.len();
        let immutable_byte_count = encoder.immutable_bytes.len();
        let fingerprint = metal_quantifier_hash_words(request.fingerprint.0);
        let mut packet = vec![0_u64; METAL_QUANTIFIER_PROGRAM_HEADER_WORDS];
        packet[0] = METAL_QUANTIFIER_PROGRAM_MAGIC;
        packet[1] = program_words as u64;
        packet[2] = encoder.stages.len() as u64;
        packet[3] = encoder.stage_data.len() as u64;
        packet[4] = encoder.expressions.len() as u64;
        packet[5] = encoder.children.len() as u64;
        packet[6] = encoder.immutable_cells.len() as u64;
        packet[7] = encoder.immutable_items.len() as u64;
        packet[8] = encoder.immutable_bytes.len() as u64;
        packet[9] = request.program.outputs.len() as u64;
        packet[10] = obligations.len() as u64;
        packet[11] = u64::from(request.program.slot_count);
        packet[12] = request.max_rows as u64;
        packet[13] = request.max_list_items as u64;
        packet[14] = request.random_seed;
        packet[15..19].copy_from_slice(&fingerprint);
        packet[19] = request.execution.high;
        packet[20] = request.execution.low;
        packet[21] = scratch.words as u64;
        packet[22] = output.words as u64;
        packet[23] = capacity.final_row_bound as u64;
        packet.extend(encoder.stages.into_iter().flatten());
        packet.extend(encoder.stage_data);
        packet.extend(encoder.expressions.into_iter().flatten());
        packet.extend(encoder.children);
        packet.extend(encoder.immutable_cells.into_iter().flatten());
        packet.extend(encoder.immutable_items);
        packet.extend(immutable_bytes);
        packet.extend(
            request
                .program
                .outputs
                .iter()
                .map(|output| u64::from(output.source.0)),
        );
        for obligation in obligations {
            let (scope, index) = metal_quantifier_scope_words(obligation.scope);
            packet.extend([obligation.id, obligation.kind as u64, scope, index]);
        }
        if let Some(source) = &entity_source {
            let (property_shape, maximum_string_bytes, property_id) = source
                .properties
                .first()
                .map_or((0_u64, 0_u64, u64::MAX), |property| {
                    let (shape, maximum) = match property.shape {
                        ResidentQuantifierEntityPropertyShape::Absent => (0, 0),
                        ResidentQuantifierEntityPropertyShape::Boolean => (1, 0),
                        ResidentQuantifierEntityPropertyShape::Integer => (2, 0),
                        ResidentQuantifierEntityPropertyShape::Float => (3, 0),
                        ResidentQuantifierEntityPropertyShape::String { maximum_bytes } => {
                            (4, u64::from(maximum_bytes))
                        }
                        ResidentQuantifierEntityPropertyShape::MixedScalar {
                            maximum_string_bytes,
                        } => (5, u64::from(maximum_string_bytes)),
                    };
                    (
                        shape,
                        maximum,
                        property.property.map_or(u64::MAX, |value| value.0),
                    )
                });
            let binding_base = source.source_base + METAL_QUANTIFIER_ENTITY_SOURCE_HEADER_WORDS;
            packet.extend([
                METAL_QUANTIFIER_ENTITY_SOURCE_MAGIC,
                (program_words - source.source_base) as u64,
                source.entity_kind as u64,
                u64::from(source.output.0),
                u64::from(source.skip),
                source.properties.len() as u64,
                property_shape,
                maximum_string_bytes,
                source.path_packet_base as u64,
                source.path.packet.len() as u64,
                request.source_receipt_count() as u64,
                source.group_stage.map_or(u64::MAX, |stage| stage as u64),
                source.project_stage as u64,
                source.bindings.len() as u64,
                binding_base as u64,
                source.maximum_items as u64,
                property_id,
                source.maximum_dependencies as u64,
                match &request.source {
                    ResidentQuantifierSource::VariablePathEntityList { path, .. } => {
                        path.expected_node_slots as u64
                    }
                    ResidentQuantifierSource::Unit | ResidentQuantifierSource::Range { .. } => 0,
                },
                match &request.source {
                    ResidentQuantifierSource::VariablePathEntityList { path, .. } => {
                        path.expected_edge_slots as u64
                    }
                    ResidentQuantifierSource::Unit | ResidentQuantifierSource::Range { .. } => 0,
                },
                match &request.source {
                    ResidentQuantifierSource::VariablePathEntityList { path, .. } => {
                        path.maximum_output_rows as u64
                    }
                    ResidentQuantifierSource::Unit | ResidentQuantifierSource::Range { .. } => 0,
                },
                match &request.source {
                    ResidentQuantifierSource::VariablePathEntityList { path, .. } => {
                        path.maximum_frontier_paths as u64
                    }
                    ResidentQuantifierSource::Unit | ResidentQuantifierSource::Range { .. } => 0,
                },
                u64::from(source.path.source_mode),
                0x5345_414c_4544_5155,
            ]);
            for binding in &source.bindings {
                packet.extend([
                    u64::from(binding.output.0),
                    u64::from(binding.mode),
                    u64::from(binding.source.0),
                    binding.kind.map_or(0, |kind| kind as u64),
                    binding.property_lane as u64,
                    binding.operation as u64,
                    binding.literal,
                    u64::from(binding.reversed),
                ]);
            }
            packet.extend(source.path.packet.iter().copied());
        }
        if packet.len() != program_words {
            return Err(Error::internal(
                "Metal quantifier packed program length changed during encoding",
            ));
        }

        let program_bytes = metal_quantifier_mul(
            packet.len(),
            size_of::<u64>(),
            "Metal quantifier program allocation overflow",
        )?;
        let scratch_bytes = metal_quantifier_mul(
            scratch.words,
            size_of::<u64>(),
            "Metal quantifier scratch allocation overflow",
        )?;
        let output_bytes = metal_quantifier_mul(
            output.words,
            size_of::<u64>(),
            "Metal quantifier output allocation overflow",
        )?;
        let admitted_bytes = metal_quantifier_add(
            metal_quantifier_add(
                program_bytes,
                scratch_bytes,
                "Metal quantifier admitted allocation overflow",
            )?,
            output_bytes,
            "Metal quantifier admitted allocation overflow",
        )?;
        let admitted_bytes =
            if let (ResidentQuantifierSource::VariablePathEntityList { path, .. }, Some(source)) =
                (&request.source, &entity_source)
            {
                let admitted_bytes = metal_quantifier_add(
                    admitted_bytes,
                    path.scratch_bytes()?,
                    "Metal fused path/quantifier admission overflow",
                )?;
                metal_quantifier_add(
                    admitted_bytes,
                    source.scratch_bytes,
                    "Metal fused entity scratch admission overflow",
                )?
            } else {
                admitted_bytes
            };
        Ok(Self {
            packet,
            capacity,
            scratch,
            output,
            stage_base,
            stage_data_base,
            expression_base,
            child_base,
            immutable_cell_base,
            immutable_item_base,
            immutable_byte_base,
            output_source_base,
            receipt_descriptor_base,
            expression_count,
            immutable_cell_count,
            immutable_item_count,
            immutable_byte_count,
            entity_source,
            entity_output,
            admitted_bytes,
        })
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
pub fn metal_quantifier_program_scratch_bytes(
    resident: &CandleResident,
    request: &ResidentQuantifierProgramRequest,
) -> Result<usize> {
    if resident.project != request.generation.project
        || resident.bookmark != request.generation.bookmark
        || resident.revision != request.generation.graph_revision
        || resident.layout_version != request.generation.layout_version
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident quantifier scratch estimate targets a stale Metal generation",
        ));
    }
    MetalQuantifierPlan::build(resident, request).map(|plan| plan.admitted_bytes)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Debug)]
struct MetalQuantifierEntityPropertyInput {
    storage_shape: u32,
    values: Tensor,
    validity: Tensor,
    offsets: Tensor,
    bytes: Tensor,
    offset_count: usize,
    byte_count: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_entity_property_input(
    resident: &CandleResident,
    source: &MetalQuantifierEntitySourcePlan,
    device: &Device,
) -> Result<MetalQuantifierEntityPropertyInput> {
    let entity_rows = match source.entity_kind {
        ResidentQuantifierEntityKind::Node => resident.node_count,
        ResidentQuantifierEntityKind::Relationship => resident.edge_count,
    };
    let storage_rows = entity_rows.max(1);
    let dummy_i64 = || Tensor::zeros(1, DType::I64, device).map_err(candle_error);
    let dummy_i64_values = || Tensor::zeros(storage_rows, DType::I64, device).map_err(candle_error);
    let dummy_validity = || Tensor::zeros(storage_rows, DType::U8, device).map_err(candle_error);
    let absent_validity = || Tensor::zeros(1, DType::U8, device).map_err(candle_error);
    let dummy_offsets = || Tensor::zeros(1, DType::U32, device).map_err(candle_error);
    let dummy_bytes = || Tensor::zeros(1, DType::U8, device).map_err(candle_error);
    let Some(descriptor) = source.properties.first() else {
        return Ok(MetalQuantifierEntityPropertyInput {
            storage_shape: 0,
            values: dummy_i64()?,
            validity: absent_validity()?,
            offsets: dummy_offsets()?,
            bytes: dummy_bytes()?,
            offset_count: 1,
            byte_count: 0,
        });
    };
    let Some(property) = descriptor.property else {
        return Ok(MetalQuantifierEntityPropertyInput {
            storage_shape: 0,
            values: dummy_i64()?,
            validity: absent_validity()?,
            offsets: dummy_offsets()?,
            bytes: dummy_bytes()?,
            offset_count: 1,
            byte_count: 0,
        });
    };
    let unsupported_physical = match source.entity_kind {
        ResidentQuantifierEntityKind::Node => {
            resident.date_nodes.contains_key(&property)
                || resident.local_time_nodes.contains_key(&property)
                || resident.zoned_time_nodes.contains_key(&property)
                || resident.local_datetime_nodes.contains_key(&property)
                || resident.zoned_datetime_nodes.contains_key(&property)
                || resident.duration_nodes.contains_key(&property)
                || resident.unsupported_node_properties.contains(&property)
        }
        ResidentQuantifierEntityKind::Relationship => {
            resident.date_edges.contains_key(&property)
                || resident.local_time_edges.contains_key(&property)
                || resident.zoned_time_edges.contains_key(&property)
                || resident.local_datetime_edges.contains_key(&property)
                || resident.zoned_datetime_edges.contains_key(&property)
                || resident.duration_edges.contains_key(&property)
                || resident.unsupported_edge_properties.contains(&property)
        }
    };
    if unsupported_physical {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident quantifier entity property has an unsupported canonical Metal column",
        ));
    }
    let (integers, booleans, floats, strings, mixed, unsupported, dictionary) =
        match source.entity_kind {
            ResidentQuantifierEntityKind::Node => (
                &resident.integer_nodes,
                &resident.boolean_nodes,
                &resident.float_nodes,
                &resident.string_nodes,
                &resident.mixed_nodes,
                &resident.unsupported_node_properties,
                &resident.node_string_dictionary,
            ),
            ResidentQuantifierEntityKind::Relationship => (
                &resident.integer_edges,
                &resident.boolean_edges,
                &resident.float_edges,
                &resident.string_edges,
                &resident.mixed_edges,
                &resident.unsupported_edge_properties,
                &resident.edge_string_dictionary,
            ),
        };
    let validity = |validity: &Option<Tensor>| -> Result<Tensor> {
        validity.as_ref().cloned().map_or_else(dummy_validity, Ok)
    };
    let input = if let Some(column) = booleans.get(&property) {
        if column.rows != entity_rows {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident Boolean property has an invalid entity-source row count",
            ));
        }
        MetalQuantifierEntityPropertyInput {
            storage_shape: 1,
            values: column.values.as_ref().cloned().map_or_else(
                || Tensor::zeros(storage_rows, DType::U8, device).map_err(candle_error),
                Ok,
            )?,
            validity: validity(&column.validity)?,
            offsets: dummy_offsets()?,
            bytes: dummy_bytes()?,
            offset_count: 1,
            byte_count: 0,
        }
    } else if let Some(column) = integers.get(&property) {
        if column.rows != entity_rows {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident integer property has an invalid entity-source row count",
            ));
        }
        MetalQuantifierEntityPropertyInput {
            storage_shape: 2,
            values: column
                .values
                .as_ref()
                .cloned()
                .map_or_else(dummy_i64_values, Ok)?,
            validity: validity(&column.validity)?,
            offsets: dummy_offsets()?,
            bytes: dummy_bytes()?,
            offset_count: 1,
            byte_count: 0,
        }
    } else if let Some(column) = floats.get(&property) {
        if column.rows != entity_rows {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident float property has an invalid entity-source row count",
            ));
        }
        MetalQuantifierEntityPropertyInput {
            storage_shape: 3,
            values: column
                .values
                .as_ref()
                .cloned()
                .map_or_else(dummy_i64_values, Ok)?,
            validity: validity(&column.validity)?,
            offsets: dummy_offsets()?,
            bytes: dummy_bytes()?,
            offset_count: 1,
            byte_count: 0,
        }
    } else if let Some(column) = strings.get(&property) {
        if column.rows != entity_rows {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident string property has an invalid entity-source row count",
            ));
        }
        MetalQuantifierEntityPropertyInput {
            storage_shape: 4,
            values: column.values.as_ref().cloned().map_or_else(
                || Tensor::zeros(storage_rows, DType::U32, device).map_err(candle_error),
                Ok,
            )?,
            validity: validity(&column.validity)?,
            offsets: dictionary.offsets.clone(),
            bytes: dictionary
                .bytes
                .as_ref()
                .cloned()
                .map_or_else(dummy_bytes, Ok)?,
            offset_count: dictionary.offsets.elem_count(),
            byte_count: dictionary.bytes.as_ref().map_or(0, Tensor::elem_count),
        }
    } else if let Some(column) = mixed.get(&property) {
        if column.offsets.elem_count() != entity_rows.saturating_add(1) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident mixed property has an invalid entity-source row count",
            ));
        }
        MetalQuantifierEntityPropertyInput {
            storage_shape: 5,
            values: dummy_i64()?,
            validity: validity(&column.validity)?,
            offsets: column.offsets.clone(),
            bytes: column
                .bytes
                .as_ref()
                .cloned()
                .map_or_else(dummy_bytes, Ok)?,
            offset_count: column.offsets.elem_count(),
            byte_count: column.bytes.as_ref().map_or(0, Tensor::elem_count),
        }
    } else {
        if unsupported.contains(&property) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident quantifier entity property has an unsupported canonical Metal column",
            ));
        }
        MetalQuantifierEntityPropertyInput {
            storage_shape: 0,
            values: dummy_i64()?,
            validity: absent_validity()?,
            offsets: dummy_offsets()?,
            bytes: dummy_bytes()?,
            offset_count: 1,
            byte_count: 0,
        }
    };
    Ok(input)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_node_selection_allocation_bytes(
    node_rows: usize,
    label_count: usize,
    layers: LayerMask,
) -> Result<usize> {
    if node_rows == 0 {
        return Ok(0);
    }
    let layer_count = crate::Layer::ALL
        .into_iter()
        .filter(|layer| layers.contains_layer(*layer))
        .count();
    let tensors = layer_count
        .checked_mul(2)
        .and_then(|count| count.checked_add(2))
        .and_then(|count| count.checked_add(label_count))
        .ok_or_else(|| metal_quantifier_overflow("Metal node-selection staging overflow"))?;
    metal_quantifier_mul(node_rows, tensors, "Metal node-selection staging overflow")
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_entity_property_staging_bytes(
    resident: &CandleResident,
    source: &MetalQuantifierEntitySourcePlan,
) -> Result<usize> {
    let entity_rows = match source.entity_kind {
        ResidentQuantifierEntityKind::Node => resident.node_count,
        ResidentQuantifierEntityKind::Relationship => resident.edge_count,
    };
    let storage_rows = entity_rows.max(1);
    let absent_bytes = size_of::<i64>() + size_of::<u8>() + size_of::<u32>() + size_of::<u8>();
    let Some(descriptor) = source.properties.first() else {
        return Ok(absent_bytes);
    };
    let Some(property) = descriptor.property else {
        return Ok(absent_bytes);
    };
    let (integers, booleans, floats, strings, mixed, unsupported, dictionary) =
        match source.entity_kind {
            ResidentQuantifierEntityKind::Node => (
                &resident.integer_nodes,
                &resident.boolean_nodes,
                &resident.float_nodes,
                &resident.string_nodes,
                &resident.mixed_nodes,
                &resident.unsupported_node_properties,
                &resident.node_string_dictionary,
            ),
            ResidentQuantifierEntityKind::Relationship => (
                &resident.integer_edges,
                &resident.boolean_edges,
                &resident.float_edges,
                &resident.string_edges,
                &resident.mixed_edges,
                &resident.unsupported_edge_properties,
                &resident.edge_string_dictionary,
            ),
        };
    let unsupported_physical = unsupported.contains(&property)
        || match source.entity_kind {
            ResidentQuantifierEntityKind::Node => {
                resident.date_nodes.contains_key(&property)
                    || resident.local_time_nodes.contains_key(&property)
                    || resident.zoned_time_nodes.contains_key(&property)
                    || resident.local_datetime_nodes.contains_key(&property)
                    || resident.zoned_datetime_nodes.contains_key(&property)
                    || resident.duration_nodes.contains_key(&property)
            }
            ResidentQuantifierEntityKind::Relationship => {
                resident.date_edges.contains_key(&property)
                    || resident.local_time_edges.contains_key(&property)
                    || resident.zoned_time_edges.contains_key(&property)
                    || resident.local_datetime_edges.contains_key(&property)
                    || resident.zoned_datetime_edges.contains_key(&property)
                    || resident.duration_edges.contains_key(&property)
            }
        };
    if unsupported_physical {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident quantifier entity property has an unsupported canonical Metal column",
        ));
    }
    let validity_bytes = |validity: &Option<Tensor>| {
        if validity.is_some() { 0 } else { storage_rows }
    };
    let typed_dummies = size_of::<u32>() + size_of::<u8>();
    if let Some(column) = booleans.get(&property) {
        return metal_quantifier_add(
            typed_dummies + validity_bytes(&column.validity),
            if column.values.is_some() {
                0
            } else {
                storage_rows
            },
            "Metal Boolean property staging overflow",
        );
    }
    if let Some(column) = integers.get(&property) {
        return metal_quantifier_add(
            typed_dummies + validity_bytes(&column.validity),
            if column.values.is_some() {
                0
            } else {
                metal_quantifier_mul(
                    storage_rows,
                    size_of::<i64>(),
                    "Metal integer property staging overflow",
                )?
            },
            "Metal integer property staging overflow",
        );
    }
    if let Some(column) = floats.get(&property) {
        return metal_quantifier_add(
            typed_dummies + validity_bytes(&column.validity),
            if column.values.is_some() {
                0
            } else {
                metal_quantifier_mul(
                    storage_rows,
                    size_of::<i64>(),
                    "Metal float property staging overflow",
                )?
            },
            "Metal float property staging overflow",
        );
    }
    if let Some(column) = strings.get(&property) {
        let values = if column.values.is_some() {
            0
        } else {
            metal_quantifier_mul(
                storage_rows,
                size_of::<u32>(),
                "Metal string property staging overflow",
            )?
        };
        return metal_quantifier_add(
            values + validity_bytes(&column.validity),
            usize::from(dictionary.bytes.is_none()),
            "Metal string property staging overflow",
        );
    }
    if let Some(column) = mixed.get(&property) {
        return metal_quantifier_add(
            size_of::<i64>() + validity_bytes(&column.validity),
            usize::from(column.bytes.is_none()),
            "Metal mixed property staging overflow",
        );
    }
    Ok(absent_bytes)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_entity_staging_bytes(
    resident: &CandleResident,
    path: &ResidentVariablePathRequest,
    source: &MetalQuantifierEntitySourcePlan,
) -> Result<usize> {
    let input_rows = match &path.input {
        ResidentVariablePathInput::Rows(rows) => rows.len().max(1),
        ResidentVariablePathInput::VisibleNodeScan { .. } => 1,
    };
    let mut bytes = metal_quantifier_mul(
        input_rows,
        size_of::<u32>(),
        "Metal entity path input staging overflow",
    )?;
    bytes = metal_quantifier_add(
        bytes,
        size_of::<u32>() + size_of::<u8>() + size_of::<i64>(),
        "Metal entity path dummy staging overflow",
    )?;
    let start_labels = match &path.input {
        ResidentVariablePathInput::Rows(_) => 0,
        ResidentVariablePathInput::VisibleNodeScan { labels, .. } => labels.len(),
    };
    bytes = metal_quantifier_add(
        bytes,
        metal_quantifier_node_selection_allocation_bytes(
            resident.node_count,
            start_labels,
            path.layers,
        )?,
        "Metal entity start-mask staging overflow",
    )?;
    if resident.node_count != 0 && !path.multiplicity_scans.is_empty() {
        for scan in &path.multiplicity_scans {
            bytes = metal_quantifier_add(
                bytes,
                metal_quantifier_node_selection_allocation_bytes(
                    resident.node_count,
                    scan.labels.len(),
                    path.layers,
                )?,
                "Metal entity multiplicity-mask staging overflow",
            )?;
        }
        bytes = metal_quantifier_add(
            bytes,
            metal_quantifier_mul(
                resident.node_count,
                path.multiplicity_scans.len(),
                "Metal entity multiplicity concatenation overflow",
            )?,
            "Metal entity multiplicity concatenation overflow",
        )?;
    }
    metal_quantifier_add(
        bytes,
        metal_quantifier_entity_property_staging_bytes(resident, source)?,
        "Metal entity property staging overflow",
    )
}

