#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp1 for MetalQuantifierCommand {
    fn name(&self) -> &'static str {
        "irongraph-metal-quantifier-program"
    }

    fn cpu_fwd(
        &self,
        _storage: &CpuStorage,
        _layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal quantifier command cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        program: &MetalStorage,
        layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let args = self.arguments;
        let program_words = usize::try_from(args.program_words).map_err(|_| {
            candle_core::Error::Msg("Metal quantifier program exceeds host address space".into())
        })?;
        let scratch_words = usize::try_from(args.scratch_words).map_err(|_| {
            candle_core::Error::Msg("Metal quantifier scratch exceeds host address space".into())
        })?;
        let output_words = usize::try_from(args.output_words).map_err(|_| {
            candle_core::Error::Msg("Metal quantifier output exceeds host address space".into())
        })?;
        let expected_receipt_base = METAL_QUANTIFIER_OUTPUT_HEADER_WORDS;
        let expected_root_base = expected_receipt_base
            .checked_add(
                (args.receipt_count as usize)
                    .checked_mul(METAL_QUANTIFIER_OUTPUT_RECEIPT_WORDS)
                    .ok_or_else(|| {
                        candle_core::Error::Msg("Metal quantifier receipt shape overflow".into())
                    })?,
            )
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal quantifier output shape overflow".into())
            })?;
        let expected_cell_base = expected_root_base
            .checked_add(args.root_capacity as usize)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal quantifier output shape overflow".into())
            })?;
        let expected_item_base = expected_cell_base
            .checked_add(
                (args.output_cell_capacity as usize)
                    .checked_mul(METAL_QUANTIFIER_VALUE_WORDS)
                    .ok_or_else(|| {
                        candle_core::Error::Msg("Metal quantifier output shape overflow".into())
                    })?,
            )
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal quantifier output shape overflow".into())
            })?;
        let expected_byte_base = expected_item_base
            .checked_add(args.output_item_capacity as usize)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal quantifier output shape overflow".into())
            })?;
        let expected_output_words = expected_byte_base
            .checked_add(
                (args.output_byte_capacity as usize)
                    .checked_add(7)
                    .ok_or_else(|| {
                        candle_core::Error::Msg("Metal quantifier byte shape overflow".into())
                    })?
                    / 8,
            )
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal quantifier output shape overflow".into())
            })?;
        let source_contract = match args.source_kind {
            0 => {
                args.source_receipt_count == 0
                    && args.source_output_slot == u64::MAX
                    && args.source_row_bound == 1
                    && args.range_start == 0
                    && args.range_end == 0
                    && args.range_step == 0
                    && args.range_integer_mask == 0
            }
            1 => {
                args.source_receipt_count == 1
                    && args.source_output_slot < args.slot_count
                    && args.source_row_bound == args.max_rows
                    && args.source_row_bound <= args.dynamic_cell_capacity
                    && args.range_integer_mask & !0b111 == 0
            }
            _ => false,
        };
        if program.dtype() != DType::I64
            || !layout.is_contiguous()
            || layout.dims().len() != 1
            || layout.shape().elem_count() != program_words
            || program_words < METAL_QUANTIFIER_PROGRAM_HEADER_WORDS
            || scratch_words == 0
            || output_words != expected_output_words
            || args.receipt_base != expected_receipt_base as u64
            || args.root_base != expected_root_base as u64
            || args.output_cell_base != expected_cell_base as u64
            || args.output_item_base != expected_item_base as u64
            || args.output_byte_base != expected_byte_base as u64
            || args.stage_count == 0
            || args.output_count == 0
            || args.receipt_count
                != args
                    .source_receipt_count
                    .saturating_add(args.stage_count)
                    .saturating_add(1)
            || !source_contract
            || args.slot_count == 0
            || args.max_rows == 0
            || args.max_list_items == 0
            || args.final_row_bound > args.max_rows
            || args.root_capacity != args.final_row_bound.saturating_mul(args.output_count)
            || args.frame_capacity <= args.expression_count
            || args.eval_lane_count
                != self
                    .stage_row_bounds
                    .iter()
                    .copied()
                    .max()
                    .unwrap_or(1)
                    .max(args.final_row_bound as usize)
                    .max(1) as u64
            || args.dynamic_cell_capacity > u64::from(u32::MAX)
            || args.dynamic_item_capacity > u64::from(u32::MAX)
            || args.dynamic_byte_capacity > u64::from(u32::MAX)
            || self.stage_opcodes.len() != args.stage_count as usize
            || self.stage_row_bounds.len() != args.stage_count as usize
            || self
                .stage_row_bounds
                .iter()
                .any(|bound| *bound > args.eval_lane_count as usize)
            || self
                .stage_opcodes
                .iter()
                .any(|opcode| !(1..=4).contains(opcode))
        {
            return Err(candle_core::Error::Msg(
                "Metal quantifier tensor contract is invalid".to_owned(),
            ));
        }
        let device = program.device();
        let scratch = device
            .new_buffer_builder()
            .with_size_for(scratch_words, DType::I64)
            .with_label("irongraph quantifier bounded scratch")
            .build()?;
        let output = device
            .new_buffer_builder()
            .with_size_for(output_words, DType::I64)
            .with_label("irongraph quantifier rows and receipts")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        let pipelines = metal_quantifier_program_pipelines(device)?;
        encoder.set_input_buffer(
            0,
            Some(program.buffer()),
            layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_output_buffer(1, Some(&scratch), 0);
        encoder.set_output_buffer(2, Some(&output), 0);
        encoder.set_bytes(3, &args);
        let threads = METAL_SORT_THREADS;
        let dispatch = |encoder: &ComputeCommandEncoder, items: usize| {
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: items.max(1).div_ceil(threads),
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: threads,
                    height: 1,
                    depth: 1,
                },
            );
        };
        encoder.set_compute_pipeline_state(&pipelines.clear);
        dispatch(encoder, scratch_words.max(output_words));
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.initialize);
        dispatch(encoder, 1);
        encoder.insert_memory_barrier();

        if args.source_kind == 1 {
            encoder.set_compute_pipeline_state(&pipelines.range_source);
            dispatch(encoder, args.source_row_bound as usize);
            encoder.insert_memory_barrier();
        }

        let mut current_base = args.row_a_base;
        let mut next_base = args.row_b_base;
        let mut current_lineage = args.lineage_a_base;
        let mut next_lineage = args.lineage_b_base;
        for (stage_index, opcode) in self.stage_opcodes.iter().copied().enumerate() {
            let step = MetalQuantifierStageStep {
                stage_index: stage_index as u64,
                current_base,
                next_base,
                current_lineage,
                next_lineage,
            };
            encoder.set_bytes(4, &step);
            if opcode == 1 {
                encoder.set_compute_pipeline_state(&pipelines.project);
                dispatch(encoder, self.stage_row_bounds[stage_index]);
            } else if opcode == 2 {
                let input_bound = self.stage_row_bounds[stage_index];
                let output_bound = self
                    .stage_row_bounds
                    .get(stage_index + 1)
                    .copied()
                    .unwrap_or(args.final_row_bound as usize);
                encoder.set_compute_pipeline_state(&pipelines.unwind_evaluate);
                dispatch(encoder, input_bound);
                encoder.insert_memory_barrier();

                let mut scan_in = args.filter_rank_base;
                let mut scan_out = next_lineage;
                let mut stride = 1_usize;
                while stride < input_bound {
                    encoder.set_compute_pipeline_state(&pipelines.unwind_prefix_step);
                    encoder.set_bytes(
                        5,
                        &MetalQuantifierScanStep {
                            stride: stride as u64,
                            input_base: scan_in,
                            output_base: scan_out,
                        },
                    );
                    dispatch(encoder, input_bound);
                    encoder.insert_memory_barrier();
                    std::mem::swap(&mut scan_in, &mut scan_out);
                    let Some(next_stride) = stride.checked_mul(2) else {
                        break;
                    };
                    stride = next_stride;
                }
                let scan = MetalQuantifierScanStep {
                    stride: output_bound as u64,
                    input_base: scan_in,
                    output_base: args.filter_rank_base,
                };
                encoder.set_bytes(5, &scan);
                encoder.set_compute_pipeline_state(&pipelines.unwind_prefix_finalize);
                dispatch(encoder, 1);
                encoder.insert_memory_barrier();
                encoder.set_compute_pipeline_state(&pipelines.unwind_prefix_exclusive);
                dispatch(encoder, input_bound);
                encoder.insert_memory_barrier();
                encoder.set_compute_pipeline_state(&pipelines.unwind_scatter);
                dispatch(encoder, output_bound);
                encoder.insert_memory_barrier();
                encoder.set_compute_pipeline_state(&pipelines.unwind_finalize);
                dispatch(encoder, 1);
            } else if opcode == 3 {
                encoder.set_compute_pipeline_state(&pipelines.filter_evaluate);
                dispatch(encoder, self.stage_row_bounds[stage_index]);
                encoder.insert_memory_barrier();
                encoder.set_compute_pipeline_state(&pipelines.filter_prefix);
                dispatch(encoder, 1);
                encoder.insert_memory_barrier();
                encoder.set_compute_pipeline_state(&pipelines.filter_compact);
                dispatch(encoder, self.stage_row_bounds[stage_index]);
                encoder.insert_memory_barrier();
                encoder.set_compute_pipeline_state(&pipelines.filter_finalize);
                dispatch(encoder, 1);
            } else {
                encoder.set_compute_pipeline_state(&pipelines.group);
                dispatch(encoder, 1);
            }
            encoder.insert_memory_barrier();
            if opcode <= 3 {
                std::mem::swap(&mut current_base, &mut next_base);
                std::mem::swap(&mut current_lineage, &mut next_lineage);
            }
        }

        let publish = MetalQuantifierStageStep {
            stage_index: args.stage_count,
            current_base,
            next_base,
            current_lineage,
            next_lineage,
        };
        encoder.set_compute_pipeline_state(&pipelines.publish);
        encoder.set_bytes(4, &publish);
        dispatch(encoder, 1);
        Ok((
            MetalStorage::new(output, device.clone(), output_words, DType::I64),
            Shape::from(output_words),
        ))
    }
}

/// Collision-safe hash-table grouping over one or more canonical values published by the
/// quantifier packet. The selected value rows and endpoint IDs never leave Metal; the result is
/// only the leader/ordinal metadata needed by relationship MERGE.
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[repr(C)]
#[derive(Clone, Copy, Debug)]
struct MetalBoundValueGroupArgs {
    row_count: u64,
    table_capacity: u64,
    direction: u64,
    quantifier_output_count: u64,
    root_base: u64,
    cell_base: u64,
    item_base: u64,
    byte_base: u64,
    cell_capacity: u64,
    item_capacity: u64,
    byte_capacity: u64,
    column_count: u64,
    packet_words: u64,
    output_words: u64,
    active_row: u64,
    active_column: u64,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Debug)]
struct MetalBoundValueGroupCommand {
    arguments: MetalBoundValueGroupArgs,
    parents: Tensor,
    sources: Tensor,
    targets: Tensor,
    value_rows: Tensor,
    columns: Tensor,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp1 for MetalBoundValueGroupCommand {
    fn name(&self) -> &'static str {
        "irongraph-metal-bound-value-group"
    }

    fn cpu_fwd(
        &self,
        _storage: &CpuStorage,
        _layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal bound-value grouping cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        packet: &MetalStorage,
        packet_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        macro_rules! metal_tensor {
            ($field:ident, $storage:ident, $layout:ident, $metal:ident) => {
                let ($storage, $layout) = self.$field.storage_and_layout();
                let Storage::Metal($metal) = &*$storage else {
                    return Err(candle_core::Error::Msg(
                        concat!(
                            "Metal bound-value tensor moved off Metal: ",
                            stringify!($field)
                        )
                        .to_owned(),
                    ));
                };
            };
        }
        metal_tensor!(parents, parents_storage, parents_layout, parents);
        metal_tensor!(sources, sources_storage, sources_layout, sources);
        metal_tensor!(targets, targets_storage, targets_layout, targets);
        metal_tensor!(
            value_rows,
            value_rows_storage,
            value_rows_layout,
            value_rows
        );
        metal_tensor!(columns, columns_storage, columns_layout, columns);

        let args = self.arguments;
        let row_count = usize::try_from(args.row_count).map_err(|_| {
            candle_core::Error::Msg("Metal bound-value row count exceeds usize".to_owned())
        })?;
        let column_count = usize::try_from(args.column_count).map_err(|_| {
            candle_core::Error::Msg("Metal bound-value column count exceeds usize".to_owned())
        })?;
        let output_words = usize::try_from(args.output_words).map_err(|_| {
            candle_core::Error::Msg("Metal bound-value output exceeds usize".to_owned())
        })?;
        let cell_capacity = usize::try_from(args.cell_capacity).map_err(|_| {
            candle_core::Error::Msg("Metal bound-value cell capacity exceeds usize".to_owned())
        })?;
        let expected_output_words =
            metal_row_bound_value_group_output_words(row_count, cell_capacity)
                .map_err(|error| candle_core::Error::Msg(error.to_string()))?;
        let vector = |layout: &Layout, rows: usize| {
            layout.is_contiguous()
                && layout.dims().len() == 1
                && layout.shape().elem_count() == rows
        };
        if packet.dtype() != DType::I64
            || !packet_layout.is_contiguous()
            || packet_layout.dims().len() != 1
            || packet_layout.shape().elem_count() != args.packet_words as usize
            || parents.dtype() != DType::U32
            || sources.dtype() != DType::I64
            || targets.dtype() != DType::I64
            || value_rows.dtype() != DType::U32
            || columns.dtype() != DType::U32
            || !vector(&parents_layout, row_count)
            || !vector(&sources_layout, row_count)
            || !vector(&targets_layout, row_count)
            || !vector(&value_rows_layout, row_count)
            || !vector(&columns_layout, column_count)
            || row_count == 0
            || column_count == 0
            || args.quantifier_output_count == 0
            || args.table_capacity < args.row_count.saturating_mul(2)
            || !args.table_capacity.is_power_of_two()
            || args.direction > 1
            || output_words != expected_output_words
        {
            return Err(candle_core::Error::Msg(
                "Metal bound-value grouping tensor contract is invalid".to_owned(),
            ));
        }
        let device = packet.device();
        let output = device
            .new_buffer_builder()
            .with_size_for(output_words, DType::I64)
            .with_label("irongraph bound relationship value groups")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        let pipelines = metal_quantifier_program_pipelines(device)?;
        encoder.set_input_buffer(
            0,
            Some(packet.buffer()),
            packet_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(parents.buffer()),
            parents_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(sources.buffer()),
            sources_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            3,
            Some(targets.buffer()),
            targets_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            4,
            Some(value_rows.buffer()),
            value_rows_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            5,
            Some(columns.buffer()),
            columns_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(6, Some(&output), 0);
        let mut row_args = args;
        encoder.set_compute_pipeline_state(&pipelines.bound_value_clear);
        encoder.set_bytes(7, &row_args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();
        for pipeline in [
            &pipelines.bound_value_validate_group_layout,
            &pipelines.bound_value_validate_packet_header,
            &pipelines.bound_value_validate_packet_arenas,
            &pipelines.bound_value_validate_root_bounds,
            &pipelines.bound_value_validate_columns,
            &pipelines.bound_value_build_subtrees,
            &pipelines.bound_value_validate_maps,
            &pipelines.bound_value_validate_arenas,
            &pipelines.bound_value_validate_roots,
            &pipelines.bound_value_validate_selected,
        ] {
            encoder.set_compute_pipeline_state(pipeline);
            encoder.set_bytes(7, &row_args);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
            );
            encoder.insert_memory_barrier();
        }
        for row in 0..row_count {
            row_args.active_row = row as u64;
            row_args.active_column = 0;
            encoder.set_compute_pipeline_state(&pipelines.bound_value_begin);
            encoder.set_bytes(7, &row_args);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
            );
            encoder.insert_memory_barrier();
            // At row `r`, at most `r` slots are occupied. Thus `r + 1` deterministic probes are
            // sufficient either to find an equal earlier representative or the first empty slot.
            for _ in 0..=row {
                encoder.set_compute_pipeline_state(&pipelines.bound_value_probe);
                encoder.set_bytes(7, &row_args);
                encoder.dispatch_thread_groups(
                    objc2_metal::MTLSize {
                        width: 1,
                        height: 1,
                        depth: 1,
                    },
                    objc2_metal::MTLSize {
                        width: 1,
                        height: 1,
                        depth: 1,
                    },
                );
                encoder.insert_memory_barrier();
                for column in 0..column_count {
                    row_args.active_column = column as u64;
                    encoder.set_compute_pipeline_state(&pipelines.bound_value_compare);
                    encoder.set_bytes(7, &row_args);
                    encoder.dispatch_thread_groups(
                        objc2_metal::MTLSize {
                            width: 1,
                            height: 1,
                            depth: 1,
                        },
                        objc2_metal::MTLSize {
                            width: 1,
                            height: 1,
                            depth: 1,
                        },
                    );
                    encoder.insert_memory_barrier();
                }
            }
        }
        Ok((
            MetalStorage::new(output, device.clone(), output_words, DType::I64),
            Shape::from(output_words),
        ))
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Debug)]
