/// Stored STRING keys keep the resident dictionary-rank fast path unless their bytes are needed
/// by a later STRING expression. Constants and generated strings always own exact UTF-8 bytes in
/// the evaluated arena. This decision is derived solely from the immutable SSA image and is shared
/// by admission, metadata encoding, sorting, and proof.
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_string_register_is_materialized(
    request: &ResidentRowProgramRequest,
    register: u16,
) -> Result<bool> {
    let instruction = request
        .program
        .instructions
        .get(register as usize)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "Metal string register is absent"))?;
    if instruction.output_type != ResidentRowValueType::String {
        return Ok(false);
    }
    match &instruction.operation {
        ResidentRowOperation::StringConstant(_)
        | ResidentRowOperation::StringConcat { .. }
        | ResidentRowOperation::StringCoalesce { .. }
        | ResidentRowOperation::BooleanToString { .. }
        | ResidentRowOperation::TemporalAccessor { .. } => Ok(true),
        ResidentRowOperation::InputColumn(ResidentRowColumn::String { .. })
        | ResidentRowOperation::LoadStringProperty { .. } => {
            Ok(request.final_registers.contains(&register)
                || request.program.instructions.iter().any(|candidate| {
                    matches!(
                        &candidate.operation,
                        ResidentRowOperation::StringConcat { left, right }
                            | ResidentRowOperation::StringCoalesce { left, right }
                            if *left == register || *right == register
                    )
                }))
        }
        _ => Err(Error::internal(
            "validated Metal string register has a non-string operation",
        )),
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_literal_string_ranks(column: &ResidentRowColumn) -> Result<Vec<i64>> {
    let ResidentRowColumn::String {
        offsets,
        bytes,
        validity,
    } = column
    else {
        return Err(Error::internal(
            "string-rank encoder received a non-string row column",
        ));
    };
    let mut unique = std::collections::BTreeSet::new();
    for (row, valid) in validity.iter().copied().enumerate() {
        if valid == 0 {
            continue;
        }
        let start = offsets[row] as usize;
        let end = offsets[row + 1] as usize;
        unique.insert(bytes[start..end].to_vec());
    }
    let ranks = unique
        .into_iter()
        .enumerate()
        .map(|(rank, value)| {
            let rank = i64::try_from(rank).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal literal string rank exceeds i64",
                )
            })?;
            Ok((value, rank))
        })
        .collect::<Result<BTreeMap<_, _>>>()?;
    validity
        .iter()
        .copied()
        .enumerate()
        .map(|(row, valid)| {
            if valid == 0 {
                return Ok(0);
            }
            let start = offsets[row] as usize;
            let end = offsets[row + 1] as usize;
            ranks.get(&bytes[start..end]).copied().ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal literal string rank table is incomplete",
                )
            })
        })
        .collect()
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_checked_product(left: usize, right: usize, detail: &'static str) -> Result<usize> {
    left.checked_mul(right)
        .ok_or_else(|| Error::new(ErrorCode::ResultBudgetExceeded, detail))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_checked_sum(values: impl IntoIterator<Item = usize>) -> Result<usize> {
    values.into_iter().try_fold(0_usize, |total, value| {
        total.checked_add(value).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal resident typed-row allocation shape overflow",
            )
        })
    })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_append_temporal_property_input(
    property_parts: &mut Vec<Tensor>,
    extra_parts: &mut Vec<Tensor>,
    extra_cursor: &mut usize,
    property_load_count: &mut usize,
    input: MetalRowTemporalPropertyInput,
) -> Result<(usize, Vec<usize>)> {
    property_parts.extend([input.primary, input.validity]);
    let ordinal = *property_load_count;
    *property_load_count = property_load_count.checked_add(1).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal resident temporal property-input count overflow",
        )
    })?;
    let mut bases = Vec::with_capacity(input.components.len());
    for component in input.components {
        bases.push(*extra_cursor);
        *extra_cursor = extra_cursor
            .checked_add(component.elem_count())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal resident temporal component image overflow",
                )
            })?;
        extra_parts.push(component);
    }
    Ok((ordinal, bases))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_typed_temporal_input(
    column: &ResidentRowColumn,
    device: &Device,
) -> Result<Option<MetalRowTemporalPropertyInput>> {
    let validity = || {
        let values = column
            .validity()
            .iter()
            .map(|valid| i64::from(*valid))
            .collect::<Vec<_>>();
        Tensor::from_slice(&values, values.len(), device).map_err(candle_error)
    };
    let i64_tensor =
        |values: &[i64]| Tensor::from_slice(values, values.len(), device).map_err(candle_error);
    let input = match column {
        ResidentRowColumn::Date { days, .. } => MetalRowTemporalPropertyInput {
            primary: i64_tensor(days)?,
            validity: validity()?,
            components: Vec::new(),
        },
        ResidentRowColumn::LocalTime { nanos, .. } => MetalRowTemporalPropertyInput {
            primary: i64_tensor(nanos)?,
            validity: validity()?,
            components: Vec::new(),
        },
        ResidentRowColumn::ZonedTime {
            nanos,
            offset_seconds,
            ..
        } => {
            let offsets = offset_seconds
                .iter()
                .map(|offset| i64::from(*offset))
                .collect::<Vec<_>>();
            MetalRowTemporalPropertyInput {
                primary: i64_tensor(nanos)?,
                validity: validity()?,
                components: vec![i64_tensor(&offsets)?],
            }
        }
        ResidentRowColumn::LocalDateTime { seconds, nanos, .. }
        | ResidentRowColumn::ZonedDateTime { seconds, nanos, .. } => {
            let nanos = nanos
                .iter()
                .map(|nanos| i64::from(*nanos))
                .collect::<Vec<_>>();
            MetalRowTemporalPropertyInput {
                primary: i64_tensor(seconds)?,
                validity: validity()?,
                components: vec![i64_tensor(&nanos)?],
            }
        }
        ResidentRowColumn::Boolean { .. }
        | ResidentRowColumn::Integer { .. }
        | ResidentRowColumn::Float { .. }
        | ResidentRowColumn::String { .. }
        | ResidentRowColumn::List { .. } => return Ok(None),
    };
    Ok(Some(input))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_private_buffer_bytes(logical: usize) -> Result<usize> {
    if logical == 0 {
        return Ok(0);
    }
    logical
        .checked_next_power_of_two()
        .map(|bytes| bytes.max(4_096))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal resident typed-row private allocation overflow",
            )
        })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_shared_buffer_bytes(logical: usize) -> Result<usize> {
    if logical == 0 {
        return Ok(0);
    }
    logical
        .checked_next_power_of_two()
        .map(|bytes| bytes.max(4_096))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal resident typed-row shared allocation overflow",
            )
        })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_fixed_evaluate_words(row_count: usize, instruction_count: usize) -> Result<usize> {
    metal_row_checked_product(
        row_count,
        instruction_count,
        "Metal row register shape overflow",
    )?
    .checked_mul(2)
    .and_then(|words| words.checked_add(1))
    .and_then(|words| words.checked_add(row_count))
    .ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal resident row evaluation output overflow",
        )
    })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const fn metal_row_temporal_sidecar_lanes(value_type: ResidentRowValueType) -> usize {
    match value_type {
        // The ordinary payload holds normalized UTC nanos. The sidecar retains canonical local
        // nanos and offset for proof and result publication.
        ResidentRowValueType::ZonedTime => 2,
        // The ordinary payload holds seconds.
        ResidentRowValueType::LocalDateTime => 1,
        // The ordinary payload holds seconds; nanos and a packed timezone reference are sidecars.
        ResidentRowValueType::ZonedDateTime => 2,
        _ => 0,
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_temporal_arena_words(
    request: &ResidentRowProgramRequest,
    row_count: usize,
) -> Result<usize> {
    request
        .program
        .instructions
        .iter()
        .try_fold(0_usize, |total, instruction| {
            total
                .checked_add(metal_row_checked_product(
                    metal_row_temporal_sidecar_lanes(instruction.output_type),
                    row_count,
                    "Metal temporal row sidecar overflow",
                )?)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal temporal row sidecar overflow",
                    )
                })
        })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_temporal_slots(
    request: &ResidentRowProgramRequest,
    row_count: usize,
) -> Result<Vec<(usize, usize)>> {
    let mut cursor = metal_row_fixed_evaluate_words(row_count, request.program.instructions.len())?;
    let mut slots = Vec::with_capacity(request.program.instructions.len());
    for instruction in &request.program.instructions {
        let lanes = metal_row_temporal_sidecar_lanes(instruction.output_type);
        if lanes == 0 {
            slots.push((0, 0));
            continue;
        }
        slots.push((cursor, lanes));
        cursor = cursor
            .checked_add(metal_row_checked_product(
                lanes,
                row_count,
                "Metal temporal row sidecar overflow",
            )?)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal temporal row sidecar overflow",
                )
            })?;
    }
    let expected = metal_row_fixed_evaluate_words(row_count, request.program.instructions.len())?
        .checked_add(metal_row_temporal_arena_words(request, row_count)?)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal temporal row sidecar overflow",
            )
        })?;
    if cursor != expected {
        return Err(Error::internal(
            "Metal temporal row slot layout has an invalid width",
        ));
    }
    Ok(slots)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_string_arena_bytes(
    request: &ResidentRowProgramRequest,
    row_count: usize,
) -> Result<usize> {
    request.program.instructions.iter().enumerate().try_fold(
        0_usize,
        |total, (register, instruction)| {
            let register = u16::try_from(register).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal variable-width register exceeds u16",
                )
            })?;
            let capacity = match instruction.output_type {
                ResidentRowValueType::String
                    if metal_row_string_register_is_materialized(request, register)? =>
                {
                    request
                        .program
                        .string_register_capacity(register)?
                        .ok_or_else(|| {
                            Error::internal("Metal string register capacity disappeared")
                        })?
                }
                ResidentRowValueType::ZonedDateTime => request
                    .program
                    .timezone_register_capacity(register)?
                    .ok_or_else(|| {
                        Error::internal("Metal timezone register capacity disappeared")
                    })?,
                ResidentRowValueType::List => request
                    .program
                    .list_register_capacity(register)?
                    .ok_or_else(|| Error::internal("Metal list register capacity disappeared"))?
                    .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal list register byte capacity overflow",
                        )
                    })?,
                _ => return Ok(total),
            };
            total
                .checked_add(metal_row_checked_product(
                    capacity,
                    row_count,
                    "Metal string row arena overflow",
                )?)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal string row arena overflow",
                    )
                })
        },
    )
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_evaluate_words(
    request: &ResidentRowProgramRequest,
    row_count: usize,
) -> Result<usize> {
    let fixed = metal_row_fixed_evaluate_words(row_count, request.program.instructions.len())?;
    let temporal = metal_row_temporal_arena_words(request, row_count)?;
    let arena_bytes = metal_row_string_arena_bytes(request, row_count)?;
    fixed
        .checked_add(temporal)
        .and_then(|words| words.checked_add(arena_bytes.div_ceil(size_of::<i64>())))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal resident row evaluation output overflow",
            )
        })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_string_slots(
    request: &ResidentRowProgramRequest,
    row_count: usize,
) -> Result<Vec<(u32, u32)>> {
    let fixed_and_temporal_words =
        metal_row_fixed_evaluate_words(row_count, request.program.instructions.len())?
            .checked_add(metal_row_temporal_arena_words(request, row_count)?)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row fixed and temporal register bytes overflow",
                )
            })?;
    let fixed_bytes = metal_row_checked_product(
        fixed_and_temporal_words,
        size_of::<i64>(),
        "Metal row fixed register bytes overflow",
    )?;
    let mut cursor = fixed_bytes;
    let mut slots = Vec::with_capacity(request.program.instructions.len());
    for (register, instruction) in request.program.instructions.iter().enumerate() {
        let register = u16::try_from(register).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal string register exceeds u16",
            )
        })?;
        let capacity = match instruction.output_type {
            ResidentRowValueType::String
                if metal_row_string_register_is_materialized(request, register)? =>
            {
                request
                    .program
                    .string_register_capacity(register)?
                    .ok_or_else(|| Error::internal("Metal string register capacity disappeared"))?
            }
            ResidentRowValueType::ZonedDateTime => request
                .program
                .timezone_register_capacity(register)?
                .ok_or_else(|| Error::internal("Metal timezone register capacity disappeared"))?,
            ResidentRowValueType::List => request
                .program
                .list_register_capacity(register)?
                .ok_or_else(|| Error::internal("Metal list register capacity disappeared"))?
                .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal list slot byte capacity overflow",
                    )
                })?,
            _ => {
                slots.push((0, 0));
                continue;
            }
        };
        let base = u32::try_from(cursor).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal string arena offset exceeds u32",
            )
        })?;
        if base & 0x8000_0000 != 0 {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal string arena offset exceeds the packed reference domain",
            ));
        }
        let capacity = u32::try_from(capacity).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal string slot capacity exceeds u32",
            )
        })?;
        slots.push((base, capacity));
        cursor = cursor
            .checked_add(metal_row_checked_product(
                capacity as usize,
                row_count,
                "Metal string slot bytes overflow",
            )?)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal string arena cursor overflow",
                )
            })?;
        if cursor > 0x8000_0000_usize {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal string arena exceeds the packed reference domain",
            ));
        }
    }
    let expected = metal_row_checked_product(
        metal_row_evaluate_words(request, row_count)?,
        size_of::<i64>(),
        "Metal evaluated row bytes overflow",
    )?;
    if cursor > expected {
        return Err(Error::internal(
            "Metal string slot layout exceeds the evaluated buffer",
        ));
    }
    Ok(slots)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_metadata_words(request: &ResidentRowProgramRequest) -> Result<usize> {
    metal_row_checked_sum([
        metal_row_checked_product(
            request.program.instructions.len(),
            METAL_ROW_INSTRUCTION_WORDS,
            "Metal row instruction metadata overflow",
        )?,
        request.final_registers.len(),
        metal_row_checked_product(
            request.obligations().count(),
            METAL_ROW_OBLIGATION_WORDS,
            "Metal row obligation metadata overflow",
        )?,
    ])
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_packet_words(
    request: &ResidentRowProgramRequest,
    output_rows: usize,
) -> Result<usize> {
    let projection_words =
        request
            .final_registers
            .iter()
            .try_fold(0_usize, |total, register| {
                total
                    .checked_add(metal_row_projection_packet_words(
                        request,
                        *register,
                        output_rows,
                    )?)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal row projection packet overflow",
                        )
                    })
            })?;
    metal_row_checked_sum([
        METAL_ROW_PACKET_HEADER_WORDS,
        output_rows,
        projection_words,
        metal_row_checked_product(
            request.obligations().count(),
            METAL_ROW_PACKET_RECEIPT_WORDS,
            "Metal row receipt packet overflow",
        )?,
    ])
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_projection_packet_words(
    request: &ResidentRowProgramRequest,
    register: u16,
    output_rows: usize,
) -> Result<usize> {
    let value_type = request.program.register_type(register).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "resident row projection names an absent register",
        )
    })?;
    let (fixed_columns, variable_capacity) = match value_type {
        ResidentRowValueType::Boolean
        | ResidentRowValueType::Integer
        | ResidentRowValueType::Float
        | ResidentRowValueType::Date
        | ResidentRowValueType::LocalTime => (2, None),
        ResidentRowValueType::ZonedTime | ResidentRowValueType::LocalDateTime => (3, None),
        // seconds, nanos, timezone byte length, validity
        ResidentRowValueType::ZonedDateTime => (
            4,
            Some(
                request
                    .program
                    .timezone_register_capacity(register)?
                    .ok_or_else(|| {
                        Error::internal("Metal projected timezone capacity disappeared")
                    })?,
            ),
        ),
        // UTF-8 byte length and validity, followed by fixed-capacity packed row slots.
        ResidentRowValueType::String => (
            2,
            Some(
                request
                    .program
                    .string_register_capacity(register)?
                    .ok_or_else(|| {
                        Error::internal("Metal projected string capacity disappeared")
                    })?,
            ),
        ),
        // Encoded elements use one validity-order byte followed by an order-preserving i64 key.
        ResidentRowValueType::List => (
            2,
            Some(
                request
                    .program
                    .list_register_capacity(register)?
                    .ok_or_else(|| Error::internal("Metal projected list capacity disappeared"))?
                    .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal projected list byte capacity overflow",
                        )
                    })?,
            ),
        ),
    };
    let fixed = metal_row_checked_sum([
        METAL_ROW_PACKET_PROJECTION_HEADER_WORDS,
        metal_row_checked_product(
            output_rows,
            fixed_columns,
            "Metal row projected temporal payload shape overflow",
        )?,
    ])?;
    let Some(capacity) = variable_capacity else {
        return Ok(fixed);
    };
    let variable_bytes = metal_row_checked_product(
        output_rows,
        capacity,
        "Metal projected variable-width byte arena overflow",
    )?;
    fixed
        .checked_add(variable_bytes.div_ceil(size_of::<i64>()))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal projected variable-width packet overflow",
            )
        })
}

/// The one authoritative decision for typed-row ordering. Admission and dispatch both consume this
/// value, so a bounded window can never be accounted as top-k and then executed as radix.
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MetalRowSortStrategy {
    /// No ORDER BY keys; publish the stable input positions directly.
    NoSort,
    /// No row can be published, so no position image or sort command is needed.
    EmptyWindow,
    /// Exactly one key and a device-top-k-sized prefix window.
    SingleKeyTopK { window: usize },
    /// Every multi-key order and every larger single-key window uses stable radix passes.
    Radix,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_sort_strategy(
    request: &ResidentRowProgramRequest,
    input_rows: usize,
    output_rows: usize,
) -> Result<MetalRowSortStrategy> {
    // Sorting is semantically vacuous when the admitted input or selected output is empty. This
    // check intentionally precedes NoSort so LIMIT 0 never allocates a full position tensor.
    if input_rows == 0 || output_rows == 0 {
        return Ok(MetalRowSortStrategy::EmptyWindow);
    }
    if request.sort_keys.is_empty() {
        return Ok(MetalRowSortStrategy::NoSort);
    }
    let has_materialized_string_key =
        request
            .sort_keys
            .iter()
            .try_fold(false, |found, key| -> Result<bool> {
                Ok(found
                    || match request.program.register_type(key.register) {
                        Some(ResidentRowValueType::String) => {
                            metal_row_string_register_is_materialized(request, key.register)?
                        }
                        Some(ResidentRowValueType::List) => true,
                        _ => false,
                    })
            })?;
    let has_composite_temporal_key = request.sort_keys.iter().any(|key| {
        matches!(
            request.program.register_type(key.register),
            Some(
                ResidentRowValueType::ZonedTime
                    | ResidentRowValueType::LocalDateTime
                    | ResidentRowValueType::ZonedDateTime
            )
        )
    });
    let window = request
        .offset
        .checked_add(output_rows)
        .map(|window| window.min(input_rows))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal resident row sort window overflow",
            )
        })?;
    if !has_materialized_string_key
        && !has_composite_temporal_key
        && request.sort_keys.len() == 1
        && window <= METAL_TOP_K_MAX_ROWS
    {
        return Ok(MetalRowSortStrategy::SingleKeyTopK { window });
    }
    Ok(MetalRowSortStrategy::Radix)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_graph_column_count(request: &ResidentRowProgramRequest) -> Result<usize> {
    if !request.has_graph_input() {
        return Ok(0);
    }
    1_usize
        .checked_add(request.input.expansion_steps().count())
        .and_then(|columns| columns.checked_add(request.input.relationship_column_count()))
        .and_then(|columns| {
            columns.checked_add(usize::from(request.input.value_matrix.is_some()) * 2)
        })
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row graph-column count overflow",
            )
        })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_graph_columns(
    rows: &DeviceNodePipelineRows,
    request: &ResidentRowProgramRequest,
    expected_rows: usize,
) -> Result<Vec<Tensor>> {
    let expected_node_columns = 1_usize
        .checked_add(request.input.expansion_steps().count())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row node-column count overflow",
            )
        })?;
    let expected_relationship_columns = request.input.relationship_column_count();
    if rows.nodes.len() != expected_node_columns
        || rows.relationships.len() != expected_relationship_columns
        || rows.value_indices.is_some() != request.input.value_matrix.is_some()
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal resident row graph proof received an invalid column shape",
        ));
    }
    let mut columns = Vec::with_capacity(metal_row_graph_column_count(request)?);
    columns.extend(rows.nodes.iter().cloned());
    columns.extend(rows.relationships.iter().cloned());
    if let Some((left, right)) = &rows.value_indices {
        columns.extend([left.clone(), right.clone()]);
    }
    for column in &columns {
        if column.dtype() != DType::U32
            || column.rank() != 1
            || column.elem_count() != expected_rows
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal resident row graph proof received a malformed graph column",
            ));
        }
    }
    Ok(columns)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_graph_proof_image(
    input: Option<&DeviceNodePipelineRows>,
    output: Option<&DeviceNodePipelineRows>,
    request: &ResidentRowProgramRequest,
    input_rows: usize,
    output_rows: usize,
    device: &Device,
) -> Result<Tensor> {
    if !request.has_graph_input() {
        if input.is_some() || output.is_some() || metal_row_graph_column_count(request)? != 0 {
            return Err(Error::internal(
                "Metal scalar row proof unexpectedly received graph columns",
            ));
        }
        return Tensor::zeros(1, DType::U32, device).map_err(candle_error);
    }
    let input = input
        .ok_or_else(|| Error::internal("Metal graph row proof omitted its input graph columns"))?;
    let output = output
        .ok_or_else(|| Error::internal("Metal graph row proof omitted its output graph columns"))?;
    let mut columns = metal_row_graph_columns(input, request, input_rows)?;
    columns.extend(metal_row_graph_columns(output, request, output_rows)?);
    let graph_columns = metal_row_graph_column_count(request)?;
    if columns.len() != graph_columns.saturating_mul(2) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal resident row graph proof omitted a graph column",
        ));
    }
    let words = graph_columns
        .checked_mul(input_rows.checked_add(output_rows).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof graph-image shape overflow",
            )
        })?)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof graph-image shape overflow",
            )
        })?;
    if words == 0 {
        return Tensor::zeros(1, DType::U32, device).map_err(candle_error);
    }
    let references = columns.iter().collect::<Vec<_>>();
    let image = Tensor::cat(&references, 0).map_err(candle_error)?;
    if image.elem_count() != words {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal resident row graph proof image has an invalid shape",
        ));
    }
    Ok(image)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_proof_args(
    request: &ResidentRowProgramRequest,
    input_rows: usize,
    output_rows: usize,
    position_count: usize,
    graph_column_count: usize,
    strategy: MetalRowSortStrategy,
) -> Result<MetalResidentRowProofArgs> {
    let (strategy_code, expected_positions) = match strategy {
        MetalRowSortStrategy::EmptyWindow => (METAL_ROW_PROOF_STRATEGY_EMPTY, 0),
        MetalRowSortStrategy::NoSort => (METAL_ROW_PROOF_STRATEGY_IDENTITY, input_rows),
        MetalRowSortStrategy::SingleKeyTopK { window } => (METAL_ROW_PROOF_STRATEGY_TOP_K, window),
        MetalRowSortStrategy::Radix => (METAL_ROW_PROOF_STRATEGY_RADIX, input_rows),
    };
    if position_count != expected_positions {
        return Err(Error::internal(
            "Metal resident row sorter returned a position shape inconsistent with admission",
        ));
    }
    let mut sort_keys =
        [MetalResidentRowProofKey::default(); super::RESIDENT_ROW_PROGRAM_MAX_SORT_KEYS];
    let temporal_slots = metal_row_temporal_slots(request, input_rows)?;
    for (descriptor, key) in sort_keys.iter_mut().zip(&request.sort_keys) {
        let value_type = request.program.register_type(key.register).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "resident row proof sort key names an absent register",
            )
        })?;
        *descriptor = MetalResidentRowProofKey {
            register: u32::from(key.register),
            value_type: value_type as u8 as u32,
            descending: u32::from(key.descending),
            nulls_first: u32::from(key.nulls_first),
            sidecar_base: temporal_slots[key.register as usize].0 as u64,
            sidecar_lanes: temporal_slots[key.register as usize].1 as u32,
            reserved: 0,
        };
    }
    let project = request.project.0.as_u128();
    let mut fingerprint = [0_u64; 4];
    for (index, chunk) in request.manifest.fingerprint.0.chunks_exact(8).enumerate() {
        fingerprint[index] = u64::from_le_bytes(chunk.try_into().map_err(|_| {
            Error::internal("resident row proof fingerprint chunk has an invalid width")
        })?);
    }
    let graph_image_words = graph_column_count
        .checked_mul(input_rows.checked_add(output_rows).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof graph-image shape overflow",
            )
        })?)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof graph-image shape overflow",
            )
        })?;
    let proof_word_count = output_rows
        .max(1)
        .checked_mul(2)
        .and_then(|positions| METAL_ROW_PROOF_HEADER_WORDS.checked_add(positions))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof packet shape overflow",
            )
        })?;
    Ok(MetalResidentRowProofArgs {
        execution_high: request.execution.high,
        execution_low: request.execution.low,
        project_high: (project >> 64) as u64,
        project_low: project as u64,
        bookmark_term: request.expected_bookmark.term,
        bookmark_index: request.expected_bookmark.index,
        graph_revision: request.expected_graph_revision,
        layout_version: request.expected_layout_version,
        fingerprint_0: fingerprint[0],
        fingerprint_1: fingerprint[1],
        fingerprint_2: fingerprint[2],
        fingerprint_3: fingerprint[3],
        input_rows: u64::try_from(input_rows).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row input exceeds u64",
            )
        })?,
        output_rows: u64::try_from(output_rows).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row output exceeds u64",
            )
        })?,
        position_count: u64::try_from(position_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof position count exceeds u64",
            )
        })?,
        offset: u64::try_from(request.offset).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof offset exceeds u64",
            )
        })?,
        graph_column_count: u64::try_from(graph_column_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof graph-column count exceeds u64",
            )
        })?,
        graph_image_words: u64::try_from(graph_image_words.max(1)).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof graph image exceeds u64",
            )
        })?,
        proof_word_count: u64::try_from(proof_word_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof packet exceeds u64",
            )
        })?,
        evaluated_word_count: u64::try_from(metal_row_evaluate_words(request, input_rows)?)
            .map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row evaluated image exceeds u64",
                )
            })?,
        dispatch_base: 0,
        dispatch_count: 0,
        instruction_count: u32::try_from(request.program.instructions.len()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof instruction count exceeds u32",
            )
        })?,
        sort_key_count: u32::try_from(request.sort_keys.len()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof sort-key count exceeds u32",
            )
        })?,
        strategy: strategy_code,
        reserved: 0,
        sort_keys,
    })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_sort_workspace_bytes(
    strategy: MetalRowSortStrategy,
    input_rows: usize,
) -> Result<usize> {
    if matches!(
        strategy,
        MetalRowSortStrategy::NoSort | MetalRowSortStrategy::EmptyWindow
    ) {
        return Ok(0);
    }
    let row_position_bytes = metal_row_checked_product(
        input_rows,
        size_of::<u64>(),
        "Metal resident row sort-position bytes overflow",
    )?;
    let selected_values = metal_row_private_buffer_bytes(metal_row_checked_product(
        input_rows,
        size_of::<i64>(),
        "Metal resident row sort-value bytes overflow",
    )?)?;
    let selected_validity = metal_row_private_buffer_bytes(input_rows)?;
    // `arange`/read-write position owners and the custom-op output are independently pooled. Use
    // the real Candle power-of-two size class for both shared position buffers.
    let shared_rows = metal_row_shared_buffer_bytes(row_position_bytes)?;
    let positions = metal_row_shared_buffer_bytes(row_position_bytes)?;
    let operator = match strategy {
        MetalRowSortStrategy::SingleKeyTopK { window } => {
            let blocks = input_rows.div_ceil(METAL_SORT_TILE_ROWS);
            let full_blocks = input_rows / METAL_SORT_TILE_ROWS;
            let remainder = input_rows % METAL_SORT_TILE_ROWS;
            let first_output = full_blocks
                .checked_mul(window)
                .and_then(|rows| rows.checked_add(remainder.min(window)))
                .and_then(|rows| rows.checked_mul(size_of::<u64>()))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal resident row top-k output shape overflow",
                    )
                })?;
            if blocks == 0 {
                0
            } else {
                metal_row_private_buffer_bytes(first_output)?
            }
        }
        MetalRowSortStrategy::Radix => {
            let output = metal_row_private_buffer_bytes(row_position_bytes)?;
            let table_elements = input_rows
                .div_ceil(METAL_SORT_TILE_ROWS)
                .checked_mul(METAL_SORT_RADIX)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal resident row radix table shape overflow",
                    )
                })?;
            let histograms = metal_row_private_buffer_bytes(metal_row_checked_product(
                table_elements,
                size_of::<u32>(),
                "Metal resident row radix histogram bytes overflow",
            )?)?;
            let offsets = metal_row_private_buffer_bytes(metal_row_checked_product(
                table_elements,
                size_of::<u64>(),
                "Metal resident row radix offset bytes overflow",
            )?)?;
            metal_row_checked_sum([output, histograms, offsets])?
        }
        MetalRowSortStrategy::NoSort | MetalRowSortStrategy::EmptyWindow => {
            return Err(Error::internal(
                "non-sorting Metal row strategy reached sort workspace accounting",
            ));
        }
    };
    metal_row_checked_sum([
        shared_rows,
        selected_values,
        selected_validity,
        positions,
        operator,
        4_096,
    ])
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_repeated_private_bytes(
    buffers: usize,
    logical_bytes: usize,
    detail: &'static str,
) -> Result<usize> {
    metal_row_checked_product(
        buffers,
        metal_row_private_buffer_bytes(logical_bytes)?,
        detail,
    )
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_host_vector_bytes(
    elements: usize,
    element_bytes: usize,
    detail: &'static str,
) -> Result<usize> {
    // Rust result vectors live in unified memory on Apple platforms. A private-allocation size
    // class is a deliberately conservative upper bound for their allocator-rounded capacity.
    metal_row_private_buffer_bytes(metal_row_checked_product(elements, element_bytes, detail)?)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct MetalResidentRowScratchBreakdown {
    graph_input_device: usize,
    graph_output_device: usize,
    typed_input_device: usize,
    typed_input_host: usize,
    property_gather_device: usize,
    property_gather_temporaries: usize,
    property_image_device: usize,
    metadata_device: usize,
    metadata_host: usize,
    evaluated_device: usize,
    sort_workspace: usize,
    position_device: usize,
    proof_position_device: usize,
    proof_graph_device: usize,
    proof_membership_device: usize,
    proof_argument_bytes: usize,
    /// The device-authored proof packet consumed by finalization. The historical field name is
    /// retained so the existing exact-boundary tests keep describing the finalization lifetime.
    finalize_position_device: usize,
    packet_device: usize,
    packet_readback_staging: usize,
    packet_host: usize,
    decoded_host: usize,
    graph_readback_staging: usize,
    graph_host: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl MetalResidentRowScratchBreakdown {
    fn required_bytes(&self) -> Result<usize> {
        // The packet readback is the device synchronization boundary. Explicit drops in the
        // executor then separate packet decoding from graph-column readback, so admission is the
        // maximum of the three real lifetime phases rather than their unnecessarily punitive sum.
        let device_and_packet_readback = metal_row_checked_sum([
            self.graph_input_device,
            self.graph_output_device,
            self.typed_input_device,
            self.typed_input_host,
            self.property_gather_device,
            self.property_gather_temporaries,
            self.property_image_device,
            self.metadata_device,
            self.metadata_host,
            self.evaluated_device,
            self.sort_workspace,
            self.position_device,
            self.proof_position_device,
            self.proof_graph_device,
            self.proof_membership_device,
            self.proof_argument_bytes,
            self.finalize_position_device,
            self.packet_device,
            self.packet_readback_staging,
            self.packet_host,
        ])?;
        let packet_decode = metal_row_checked_sum([
            self.graph_output_device,
            self.packet_host,
            self.decoded_host,
        ])?;
        let graph_readback = metal_row_checked_sum([
            self.graph_output_device,
            self.decoded_host,
            self.graph_readback_staging,
            self.graph_host,
        ])?;
        Ok(device_and_packet_readback
            .max(packet_decode)
            .max(graph_readback))
    }
}

/// Peak allocator-rounded Metal and unified-memory buffers owned by the typed-row stage. The
/// wrapped graph pipeline is admitted separately; this calculation includes both its selected
/// input columns while they remain live and every independently allocated row-stage buffer.
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_resident_row_program_scratch_breakdown(
    request: &ResidentRowProgramRequest,
    input_rows: usize,
    strategy: MetalRowSortStrategy,
) -> Result<MetalResidentRowScratchBreakdown> {
    request.validate()?;
    let output_rows = request.output_cardinality(input_rows)?;
    let expected_strategy = metal_row_sort_strategy(request, input_rows, output_rows)?;
    if strategy != expected_strategy {
        return Err(Error::internal(
            "Metal resident row scratch and dispatch strategies diverged",
        ));
    }
    // Scratch admission must validate the same packed-reference layout that dispatch encodes.
    // A byte count alone can fit in `usize` while an individual arena base no longer fits in the
    // 31-bit offset field carried by a materialized STRING value.
    let _string_slots = metal_row_string_slots(request, input_rows)?;

    let typed_input_count = request
        .program
        .instructions
        .iter()
        .filter(|instruction| {
            matches!(&instruction.operation, ResidentRowOperation::InputColumn(_))
        })
        .count();
    let graph_property_load_count = request
        .program
        .instructions
        .iter()
        .filter(|instruction| {
            matches!(
                &instruction.operation,
                ResidentRowOperation::LoadBooleanProperty { .. }
                    | ResidentRowOperation::LoadIntegerProperty { .. }
                    | ResidentRowOperation::LoadFloatProperty { .. }
                    | ResidentRowOperation::LoadStringProperty { .. }
                    | ResidentRowOperation::LoadDateProperty { .. }
                    | ResidentRowOperation::LoadLocalTimeProperty { .. }
                    | ResidentRowOperation::LoadZonedTimeProperty { .. }
                    | ResidentRowOperation::LoadLocalDateTimeProperty { .. }
                    | ResidentRowOperation::LoadZonedDateTimeProperty { .. }
                    | ResidentRowOperation::LoadListProperty { .. }
                    | ResidentRowOperation::LoadDurationAccessor { .. }
            )
        })
        .count();
    let input_load_count = typed_input_count
        .checked_add(graph_property_load_count)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal resident row input-column count overflow",
            )
        })?;
    let fixed_property_words = metal_row_checked_product(
        metal_row_checked_product(input_load_count, 2, "Metal row input width overflow")?,
        input_rows,
        "Metal row input image overflow",
    )?;
    // Materialized literal strings are uploaded as I64 words after the fixed values/validity
    // columns. Offsets remain present for an empty string column (one canonical zero offset), and
    // string constants occupy the same concatenated query-local input image.
    let property_extra_words = request.program.instructions.iter().enumerate().try_fold(
        0_usize,
        |total, (register, instruction)| {
            let register = u16::try_from(register).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal string register exceeds u16",
                )
            })?;
            let extra = match &instruction.operation {
                ResidentRowOperation::InputColumn(ResidentRowColumn::String {
                    offsets,
                    bytes,
                    ..
                }) if metal_row_string_register_is_materialized(request, register)? => {
                    metal_row_checked_sum([offsets.len(), bytes.len()])?
                }
                ResidentRowOperation::InputColumn(ResidentRowColumn::ZonedTime { .. })
                | ResidentRowOperation::InputColumn(ResidentRowColumn::LocalDateTime { .. }) => {
                    input_rows
                }
                ResidentRowOperation::InputColumn(ResidentRowColumn::ZonedDateTime {
                    timezone_offsets,
                    timezone_bytes,
                    ..
                }) => metal_row_checked_sum([
                    input_rows,
                    timezone_offsets.len(),
                    timezone_bytes.len(),
                ])?,
                ResidentRowOperation::InputColumn(ResidentRowColumn::List {
                    offsets,
                    values,
                    element_validity,
                    ..
                }) => metal_row_checked_sum([offsets.len(), values.len(), element_validity.len()])?,
                ResidentRowOperation::StringConstant(value) => value.len(),
                ResidentRowOperation::List { elements } => elements.len(),
                ResidentRowOperation::LoadZonedTimeProperty { .. }
                | ResidentRowOperation::LoadLocalDateTimeProperty { .. } => input_rows,
                ResidentRowOperation::LoadZonedDateTimeProperty { .. } => {
                    metal_row_checked_product(
                        input_rows,
                        2,
                        "Metal temporal component image overflow",
                    )?
                }
                ResidentRowOperation::LoadDurationAccessor { .. } => metal_row_checked_product(
                    input_rows,
                    3,
                    "Metal duration component image overflow",
                )?,
                ResidentRowOperation::LoadListProperty {
                    maximum_elements, ..
                } => {
                    let source_rows = request.input.max_output_rows;
                    let maximum_row_bytes = usize::try_from(*maximum_elements)
                        .ok()
                        .and_then(|elements| {
                            elements
                                .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
                                .and_then(|bytes| bytes.checked_add(10))
                        })
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal list property canonical width overflow",
                            )
                        })?;
                    metal_row_checked_sum([
                        source_rows.saturating_add(1),
                        metal_row_checked_product(
                            source_rows,
                            maximum_row_bytes,
                            "Metal list property canonical image overflow",
                        )?,
                    ])?
                }
                _ => 0,
            };
            metal_row_checked_sum([total, extra])
        },
    )?;
    let named_zone_table_words = request
        .program
        .instructions
        .iter()
        .filter_map(|instruction| match &instruction.operation {
            ResidentRowOperation::TemporalAccessor {
                named_zone_table, ..
            } => Some(named_zone_table),
            _ => None,
        })
        .try_fold(None::<&Arc<[u8]>>, |selected, candidate| {
            if selected.is_some_and(|selected| selected.as_ref() != candidate.as_ref()) {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal temporal accessors carry different named-zone rule images",
                ));
            }
            Ok(Some(selected.unwrap_or(candidate)))
        })?
        .map_or(0, |table| table.len());
    let property_extra_words =
        metal_row_checked_sum([property_extra_words, named_zone_table_words])?;
    let property_words = if input_rows == 0 {
        // Dispatch returns a one-word placeholder after uploading and dropping any canonical
        // zero-row offsets/constants, so those uploads are accounted separately below.
        0
    } else {
        metal_row_checked_sum([fixed_property_words, property_extra_words])?
    };
    let graph_column_count = metal_row_graph_column_count(request)?;
    let input_u32_bytes = metal_row_checked_product(
        input_rows,
        size_of::<u32>(),
        "Metal row input graph bytes overflow",
    )?;
    let output_u32_bytes = metal_row_checked_product(
        output_rows,
        size_of::<u32>(),
        "Metal row output graph bytes overflow",
    )?;
    let empty_shared_buffer = metal_row_shared_buffer_bytes(1)?;
    let graph_input_device = if graph_column_count == 0 {
        0
    } else if input_rows == 0 {
        empty_shared_buffer
    } else {
        metal_row_repeated_private_bytes(
            graph_column_count,
            input_u32_bytes,
            "Metal row input graph allocation overflow",
        )?
    };
    let graph_output_device = if graph_column_count == 0 {
        0
    } else if output_rows == 0 {
        empty_shared_buffer
    } else {
        metal_row_repeated_private_bytes(
            graph_column_count,
            output_u32_bytes,
            "Metal row output graph allocation overflow",
        )?
    };

    let row_i64_bytes = metal_row_checked_product(
        input_rows,
        size_of::<i64>(),
        "Metal row gathered I64 bytes overflow",
    )?;
    // Every InputColumn owns independent I64 values/validity tensors. A materialized STRING also
    // owns independently rounded offset and byte-word uploads; StringConstant owns one byte-word
    // upload. Device tensors from all instructions survive until concatenation, while converted
    // host vectors coexist only inside the currently encoded instruction, so account device sums
    // and the maximum per-instruction host peak separately.
    let mut typed_input_device = 0_usize;
    let mut typed_input_host = 0_usize;
    if named_zone_table_words != 0 {
        let logical = metal_row_checked_product(
            named_zone_table_words,
            size_of::<i64>(),
            "Metal named-zone row table upload overflow",
        )?;
        typed_input_device = metal_row_shared_buffer_bytes(logical)?;
        typed_input_host = metal_row_host_vector_bytes(
            named_zone_table_words,
            size_of::<i64>(),
            "Metal named-zone row table host conversion overflow",
        )?;
    }
    for (register, instruction) in request.program.instructions.iter().enumerate() {
        let register = u16::try_from(register).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal string register exceeds u16",
            )
        })?;
        let mut instruction_device = 0_usize;
        let mut instruction_host = 0_usize;
        match &instruction.operation {
            ResidentRowOperation::InputColumn(column) => {
                if input_rows != 0 {
                    instruction_device = metal_row_checked_product(
                        2,
                        metal_row_shared_buffer_bytes(row_i64_bytes)?,
                        "Metal row typed-input allocation overflow",
                    )?;
                    instruction_host = metal_row_checked_product(
                        2,
                        metal_row_host_vector_bytes(
                            input_rows,
                            size_of::<i64>(),
                            "Metal row typed-input host conversion overflow",
                        )?,
                        "Metal row typed-input host allocation overflow",
                    )?;
                }
                if let ResidentRowColumn::String { offsets, bytes, .. } = column
                    && metal_row_string_register_is_materialized(request, register)?
                {
                    for (elements, detail) in [
                        (offsets.len(), "Metal row string-offset upload overflow"),
                        (bytes.len(), "Metal row string-byte upload overflow"),
                    ] {
                        if elements == 0 {
                            continue;
                        }
                        let logical =
                            metal_row_checked_product(elements, size_of::<i64>(), detail)?;
                        instruction_device = metal_row_checked_sum([
                            instruction_device,
                            metal_row_shared_buffer_bytes(logical)?,
                        ])?;
                        instruction_host = metal_row_checked_sum([
                            instruction_host,
                            metal_row_host_vector_bytes(elements, size_of::<i64>(), detail)?,
                        ])?;
                    }
                }
                if let ResidentRowColumn::List {
                    offsets,
                    values,
                    element_validity,
                    ..
                } = column
                {
                    for (elements, detail) in [
                        (offsets.len(), "Metal row list-offset upload overflow"),
                        (values.len(), "Metal row list-value upload overflow"),
                        (
                            element_validity.len(),
                            "Metal row list-validity upload overflow",
                        ),
                    ] {
                        if elements == 0 {
                            continue;
                        }
                        let logical =
                            metal_row_checked_product(elements, size_of::<i64>(), detail)?;
                        instruction_device = metal_row_checked_sum([
                            instruction_device,
                            metal_row_shared_buffer_bytes(logical)?,
                        ])?;
                        instruction_host = metal_row_checked_sum([
                            instruction_host,
                            metal_row_host_vector_bytes(elements, size_of::<i64>(), detail)?,
                        ])?;
                    }
                }
                let (temporal_extra_lengths, temporal_extra_count) = match column {
                    ResidentRowColumn::ZonedTime { offset_seconds, .. } => {
                        ([offset_seconds.len(), 0, 0], 1)
                    }
                    ResidentRowColumn::LocalDateTime { nanos, .. } => ([nanos.len(), 0, 0], 1),
                    ResidentRowColumn::ZonedDateTime {
                        nanos,
                        timezone_offsets,
                        timezone_bytes,
                        ..
                    } => (
                        [nanos.len(), timezone_offsets.len(), timezone_bytes.len()],
                        3,
                    ),
                    _ => ([0, 0, 0], 0),
                };
                for elements in temporal_extra_lengths
                    .into_iter()
                    .take(temporal_extra_count)
                {
                    if elements == 0 {
                        continue;
                    }
                    let logical = metal_row_checked_product(
                        elements,
                        size_of::<i64>(),
                        "Metal temporal typed-input upload overflow",
                    )?;
                    instruction_device = metal_row_checked_sum([
                        instruction_device,
                        metal_row_shared_buffer_bytes(logical)?,
                    ])?;
                    instruction_host = metal_row_checked_sum([
                        instruction_host,
                        metal_row_host_vector_bytes(
                            elements,
                            size_of::<i64>(),
                            "Metal temporal typed-input host conversion overflow",
                        )?,
                    ])?;
                }
            }
            ResidentRowOperation::StringConstant(value) if !value.is_empty() => {
                let logical = metal_row_checked_product(
                    value.len(),
                    size_of::<i64>(),
                    "Metal row string-literal upload overflow",
                )?;
                instruction_device = metal_row_shared_buffer_bytes(logical)?;
                instruction_host = metal_row_host_vector_bytes(
                    value.len(),
                    size_of::<i64>(),
                    "Metal row string-literal host conversion overflow",
                )?;
            }
            ResidentRowOperation::List { elements } if !elements.is_empty() => {
                let logical = metal_row_checked_product(
                    elements.len(),
                    size_of::<i64>(),
                    "Metal row list-construction upload overflow",
                )?;
                instruction_device = metal_row_shared_buffer_bytes(logical)?;
                instruction_host = metal_row_host_vector_bytes(
                    elements.len(),
                    size_of::<i64>(),
                    "Metal row list-construction host conversion overflow",
                )?;
            }
            ResidentRowOperation::LoadListProperty {
                maximum_elements, ..
            } => {
                let source_rows = request.input.max_output_rows;
                let maximum_row_bytes = usize::try_from(*maximum_elements)
                    .ok()
                    .and_then(|elements| {
                        elements
                            .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
                            .and_then(|bytes| bytes.checked_add(10))
                    })
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal list property canonical width overflow",
                        )
                    })?;
                for elements in [
                    source_rows.saturating_add(1),
                    metal_row_checked_product(
                        source_rows,
                        maximum_row_bytes,
                        "Metal list property canonical image overflow",
                    )?,
                ] {
                    if elements == 0 {
                        continue;
                    }
                    instruction_device = metal_row_checked_sum([
                        instruction_device,
                        metal_row_private_buffer_bytes(metal_row_checked_product(
                            elements,
                            size_of::<i64>(),
                            "Metal list property conversion overflow",
                        )?)?,
                    ])?;
                }
            }
            _ => {}
        }
        typed_input_device = metal_row_checked_sum([typed_input_device, instruction_device])?;
        typed_input_host = typed_input_host.max(instruction_host);
    }
    let temporal_component_buffers =
        request
            .program
            .instructions
            .iter()
            .try_fold(0_usize, |total, instruction| {
                let components = match instruction.operation {
                    ResidentRowOperation::LoadZonedTimeProperty { .. }
                    | ResidentRowOperation::LoadLocalDateTimeProperty { .. } => 1,
                    ResidentRowOperation::LoadZonedDateTimeProperty { .. } => 2,
                    ResidentRowOperation::LoadDurationAccessor { .. } => 3,
                    _ => 0,
                };
                total.checked_add(components).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal temporal property component count overflow",
                    )
                })
            })?;
    let property_gather_buffers = metal_row_checked_sum([
        metal_row_checked_product(
            graph_property_load_count,
            2,
            "Metal row gathered property-buffer count overflow",
        )?,
        temporal_component_buffers,
    ])?;
    let property_gather_device = if input_rows == 0 {
        metal_row_checked_product(
            property_gather_buffers,
            empty_shared_buffer,
            "Metal row empty property gather allocation overflow",
        )?
    } else {
        metal_row_repeated_private_bytes(
            property_gather_buffers,
            row_i64_bytes,
            "Metal row gathered property allocation overflow",
        )?
    };
    let rounded_row_u8 = metal_row_private_buffer_bytes(input_rows)?;
    let rounded_row_u32 = metal_row_private_buffer_bytes(input_u32_bytes)?;
    let mut ordinary_graph_loads = 0_usize;
    let mut boolean_graph_loads = 0_usize;
    let mut materialized_string_graph_loads = 0_usize;
    let mut ranked_string_graph_loads = 0_usize;
    let mut temporal_u32_component_gathers = 0_usize;
    for (register, instruction) in request.program.instructions.iter().enumerate() {
        match &instruction.operation {
            ResidentRowOperation::LoadBooleanProperty { .. } => {
                ordinary_graph_loads = ordinary_graph_loads.checked_add(1).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row Boolean property-load count overflow",
                    )
                })?;
                boolean_graph_loads = boolean_graph_loads.checked_add(1).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row Boolean property-load count overflow",
                    )
                })?;
            }
            ResidentRowOperation::LoadIntegerProperty { .. }
            | ResidentRowOperation::LoadFloatProperty { .. }
            | ResidentRowOperation::LoadDateProperty { .. }
            | ResidentRowOperation::LoadLocalTimeProperty { .. }
            | ResidentRowOperation::LoadZonedTimeProperty { .. }
            | ResidentRowOperation::LoadListProperty { .. }
            | ResidentRowOperation::LoadDurationAccessor { .. } => {
                ordinary_graph_loads = ordinary_graph_loads.checked_add(1).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row property-load count overflow",
                    )
                })?;
            }
            ResidentRowOperation::LoadLocalDateTimeProperty { .. }
            | ResidentRowOperation::LoadZonedDateTimeProperty { .. } => {
                ordinary_graph_loads = ordinary_graph_loads.checked_add(1).ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row temporal property-load count overflow",
                    )
                })?;
                let components = usize::from(matches!(
                    instruction.operation,
                    ResidentRowOperation::LoadLocalDateTimeProperty { .. }
                )) + if matches!(
                    instruction.operation,
                    ResidentRowOperation::LoadZonedDateTimeProperty { .. }
                ) {
                    2
                } else {
                    0
                };
                temporal_u32_component_gathers = temporal_u32_component_gathers
                    .checked_add(components)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal temporal U32 gather count overflow",
                        )
                    })?;
            }
            ResidentRowOperation::LoadStringProperty { .. } => {
                let register = u16::try_from(register).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal string register exceeds u16",
                    )
                })?;
                if metal_row_string_register_is_materialized(request, register)? {
                    materialized_string_graph_loads = materialized_string_graph_loads
                        .checked_add(1)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal row materialized-string load count overflow",
                            )
                        })?;
                } else {
                    ranked_string_graph_loads =
                        ranked_string_graph_loads.checked_add(1).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal row ranked-string load count overflow",
                            )
                        })?;
                }
            }
            _ => {}
        }
    }
    // Ordinary property gathers retain three U8 validity tensors and two U32 row-index tensors;
    // Boolean adds its pre-I64 value gather. A materialized STRING retains one additional U32 ID
    // gather. The rank path additionally retains presence, safe-ID, and dictionary-rank staging.
    // Each is an independently rounded Metal allocation.
    let temporary_u8_buffers = metal_row_checked_sum([
        metal_row_checked_product(
            ordinary_graph_loads,
            3,
            "Metal row ordinary validity temporary count overflow",
        )?,
        boolean_graph_loads,
        metal_row_checked_product(
            materialized_string_graph_loads,
            3,
            "Metal row materialized-string validity count overflow",
        )?,
        metal_row_checked_product(
            ranked_string_graph_loads,
            4,
            "Metal row ranked-string validity count overflow",
        )?,
    ])?;
    let temporary_u32_buffers = metal_row_checked_sum([
        metal_row_checked_product(
            ordinary_graph_loads,
            2,
            "Metal row ordinary index temporary count overflow",
        )?,
        metal_row_checked_product(
            materialized_string_graph_loads,
            3,
            "Metal row materialized-string index count overflow",
        )?,
        metal_row_checked_product(
            ranked_string_graph_loads,
            5,
            "Metal row ranked-string index count overflow",
        )?,
        temporal_u32_component_gathers,
    ])?;
    let property_gather_temporaries = if input_rows == 0 {
        0
    } else {
        metal_row_checked_sum([
            metal_row_checked_product(
                temporary_u8_buffers,
                rounded_row_u8,
                "Metal row validity temporary allocation overflow",
            )?,
            metal_row_checked_product(
                temporary_u32_buffers,
                rounded_row_u32,
                "Metal row index temporary allocation overflow",
            )?,
        ])?
    };
    let property_image_device = if property_words == 0 {
        metal_row_shared_buffer_bytes(size_of::<i64>())?
    } else {
        metal_row_private_buffer_bytes(metal_row_checked_product(
            property_words,
            size_of::<i64>(),
            "Metal row concatenated property bytes overflow",
        )?)?
    };

    let metadata_bytes = metal_row_checked_product(
        metal_row_metadata_words(request)?,
        size_of::<i64>(),
        "Metal row metadata bytes overflow",
    )?;
    let metadata_device = metal_row_shared_buffer_bytes(metadata_bytes)?;
    let metadata_host = metal_row_host_vector_bytes(
        metal_row_metadata_words(request)?,
        size_of::<i64>(),
        "Metal row host metadata bytes overflow",
    )?;
    let evaluated_device = metal_row_private_buffer_bytes(metal_row_checked_product(
        metal_row_evaluate_words(request, input_rows)?,
        size_of::<i64>(),
        "Metal row register bytes overflow",
    )?)?;
    let has_variable_utf8_digits =
        request
            .sort_keys
            .iter()
            .try_fold(false, |found, key| -> Result<bool> {
                if found {
                    return Ok(found);
                }
                match request.program.register_type(key.register) {
                    Some(ResidentRowValueType::String)
                        if metal_row_string_register_is_materialized(request, key.register)? =>
                    {
                        Ok(request
                            .program
                            .string_register_capacity(key.register)?
                            .is_some_and(|capacity| capacity != 0))
                    }
                    Some(ResidentRowValueType::ZonedDateTime) => Ok(request
                        .program
                        .timezone_register_capacity(key.register)?
                        .is_some_and(|capacity| capacity != 0)),
                    Some(ResidentRowValueType::List) => Ok(request
                        .program
                        .list_register_capacity(key.register)?
                        .is_some_and(|capacity| capacity != 0)),
                    _ => Ok(false),
                }
            })?;
    let variable_digit_workspace = if has_variable_utf8_digits {
        metal_row_checked_product(
            2,
            metal_row_private_buffer_bytes(input_rows)?,
            "Metal row variable-width digit allocation overflow",
        )?
    } else {
        0
    };
    let sort_workspace = metal_row_checked_sum([
        metal_row_sort_workspace_bytes(strategy, input_rows)?,
        variable_digit_workspace,
    ])?;
    let position_device = match strategy {
        MetalRowSortStrategy::EmptyWindow => empty_shared_buffer,
        MetalRowSortStrategy::NoSort | MetalRowSortStrategy::Radix => {
            metal_row_private_buffer_bytes(metal_row_checked_product(
                input_rows,
                size_of::<u64>(),
                "Metal row position bytes overflow",
            )?)?
        }
        MetalRowSortStrategy::SingleKeyTopK { window } => {
            metal_row_private_buffer_bytes(metal_row_checked_product(
                window,
                size_of::<u64>(),
                "Metal row top-k position bytes overflow",
            )?)?
        }
    };
    let proof_position_device = if matches!(strategy, MetalRowSortStrategy::EmptyWindow) {
        empty_shared_buffer
    } else {
        0
    };
    let proof_graph_words = metal_row_checked_product(
        graph_column_count,
        input_rows.checked_add(output_rows).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof graph-image shape overflow",
            )
        })?,
        "Metal row proof graph-image shape overflow",
    )?;
    let proof_graph_device = metal_row_private_buffer_bytes(metal_row_checked_product(
        proof_graph_words.max(1),
        size_of::<u32>(),
        "Metal row proof graph-image bytes overflow",
    )?)?;
    let proof_membership_device = metal_row_private_buffer_bytes(metal_row_checked_product(
        input_rows.max(1),
        size_of::<u32>(),
        "Metal row proof membership bytes overflow",
    )?)?;
    let proof_argument_copies = if matches!(strategy, MetalRowSortStrategy::EmptyWindow) {
        2
    } else {
        3
    };
    let proof_argument_bytes = metal_row_shared_buffer_bytes(metal_row_checked_sum([
        metal_row_checked_product(
            proof_argument_copies,
            size_of::<MetalResidentRowProofArgs>(),
            "Metal row proof argument bytes overflow",
        )?,
        size_of::<MetalResidentRowFinalizeArgs>(),
    ])?)?;
    let proof_words = output_rows
        .max(1)
        .checked_mul(2)
        .and_then(|positions| METAL_ROW_PROOF_HEADER_WORDS.checked_add(positions))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row proof packet shape overflow",
            )
        })?;
    let finalize_position_device = metal_row_private_buffer_bytes(metal_row_checked_product(
        proof_words,
        size_of::<u32>(),
        "Metal row proof packet bytes overflow",
    )?)?;

    let packet_words = metal_row_packet_words(request, output_rows)?;
    let packet_bytes = metal_row_checked_product(
        packet_words,
        size_of::<i64>(),
        "Metal row packet bytes overflow",
    )?;
    let packet_device = metal_row_private_buffer_bytes(packet_bytes)?;
    let packet_readback_staging = metal_row_shared_buffer_bytes(packet_bytes)?;
    let packet_host = metal_row_host_vector_bytes(
        packet_words,
        size_of::<i64>(),
        "Metal row host packet bytes overflow",
    )?;

    let (decoded_projection_payloads, decoded_projection_temporary) =
        request.final_registers.iter().try_fold(
            (0_usize, 0_usize),
            |(total, temporary), register| -> Result<(usize, usize)> {
                let value_type = request.program.register_type(*register).ok_or_else(|| {
                    Error::new(
                        ErrorCode::QueryType,
                        "resident row projection names an absent register",
                    )
                })?;
                let mut projection = metal_row_host_vector_bytes(
                    output_rows,
                    size_of::<u8>(),
                    "Metal row decoded projection validity overflow",
                )?;
                let mut projection_temporary = 0_usize;
                for element_bytes in match value_type {
                    ResidentRowValueType::Boolean => vec![size_of::<u8>()],
                    ResidentRowValueType::Integer
                    | ResidentRowValueType::Float
                    | ResidentRowValueType::Date
                    | ResidentRowValueType::LocalTime => vec![size_of::<u64>()],
                    ResidentRowValueType::ZonedTime | ResidentRowValueType::LocalDateTime => {
                        vec![size_of::<i64>(), size_of::<u32>()]
                    }
                    ResidentRowValueType::ZonedDateTime => {
                        let capacity = request
                            .program
                            .timezone_register_capacity(*register)?
                            .ok_or_else(|| {
                                Error::internal("Metal decoded timezone capacity disappeared")
                            })?;
                        let slot_bytes = metal_row_checked_product(
                            output_rows,
                            capacity,
                            "Metal decoded timezone slot arena overflow",
                        )?;
                        let packed_capacity = slot_bytes
                            .div_ceil(size_of::<i64>())
                            .checked_mul(size_of::<i64>())
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal decoded packed timezone arena overflow",
                                )
                            })?;
                        projection = metal_row_checked_sum([
                            projection,
                            metal_row_host_vector_bytes(
                                output_rows.saturating_add(1),
                                size_of::<u32>(),
                                "Metal decoded timezone-offset arena overflow",
                            )?,
                            metal_row_host_vector_bytes(
                                slot_bytes,
                                size_of::<u8>(),
                                "Metal decoded timezone-byte arena overflow",
                            )?,
                        ])?;
                        projection_temporary = metal_row_host_vector_bytes(
                            packed_capacity,
                            size_of::<u8>(),
                            "Metal decoded packed timezone temporary overflow",
                        )?;
                        vec![size_of::<i64>(), size_of::<u32>()]
                    }
                    ResidentRowValueType::String => {
                        let capacity = request
                            .program
                            .string_register_capacity(*register)?
                            .ok_or_else(|| {
                                Error::internal("Metal decoded string capacity disappeared")
                            })?;
                        let slot_bytes = metal_row_checked_product(
                            output_rows,
                            capacity,
                            "Metal decoded string slot arena overflow",
                        )?;
                        let packed_capacity = slot_bytes
                            .div_ceil(size_of::<i64>())
                            .checked_mul(size_of::<i64>())
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal decoded packed string arena overflow",
                                )
                            })?;
                        projection = metal_row_checked_sum([
                            projection,
                            metal_row_host_vector_bytes(
                                output_rows.saturating_add(1),
                                size_of::<u32>(),
                                "Metal decoded string-offset arena overflow",
                            )?,
                            metal_row_host_vector_bytes(
                                slot_bytes,
                                size_of::<u8>(),
                                "Metal decoded string-byte arena overflow",
                            )?,
                        ])?;
                        projection_temporary = metal_row_host_vector_bytes(
                            packed_capacity,
                            size_of::<u8>(),
                            "Metal decoded packed string temporary overflow",
                        )?;
                        Vec::new()
                    }
                    ResidentRowValueType::List => {
                        let capacity = request
                            .program
                            .list_register_capacity(*register)?
                            .ok_or_else(|| {
                                Error::internal("Metal decoded list capacity disappeared")
                            })?;
                        let element_slots = metal_row_checked_product(
                            output_rows,
                            capacity,
                            "Metal decoded list element arena overflow",
                        )?;
                        let slot_bytes = metal_row_checked_product(
                            element_slots,
                            METAL_ROW_LIST_ELEMENT_BYTES,
                            "Metal decoded list byte arena overflow",
                        )?;
                        let packed_capacity = slot_bytes
                            .div_ceil(size_of::<i64>())
                            .checked_mul(size_of::<i64>())
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::ResultBudgetExceeded,
                                    "Metal decoded packed list arena overflow",
                                )
                            })?;
                        projection = metal_row_checked_sum([
                            projection,
                            metal_row_host_vector_bytes(
                                output_rows.saturating_add(1),
                                size_of::<u32>(),
                                "Metal decoded list-offset arena overflow",
                            )?,
                            metal_row_host_vector_bytes(
                                element_slots,
                                size_of::<i64>(),
                                "Metal decoded list-value arena overflow",
                            )?,
                            metal_row_host_vector_bytes(
                                element_slots,
                                size_of::<u8>(),
                                "Metal decoded list-validity arena overflow",
                            )?,
                        ])?;
                        projection_temporary = metal_row_host_vector_bytes(
                            packed_capacity,
                            size_of::<u8>(),
                            "Metal decoded packed list temporary overflow",
                        )?;
                        Vec::new()
                    }
                } {
                    projection = metal_row_checked_sum([
                        projection,
                        metal_row_host_vector_bytes(
                            output_rows,
                            element_bytes,
                            "Metal row decoded projection payload overflow",
                        )?,
                    ])?;
                }
                Ok((
                    metal_row_checked_sum([total, projection])?,
                    temporary.max(projection_temporary),
                ))
            },
        )?;
    let decoded_host = metal_row_checked_sum([
        metal_row_host_vector_bytes(
            output_rows,
            size_of::<u64>(),
            "Metal row decoded source-position overflow",
        )?,
        metal_row_host_vector_bytes(
            request.final_registers.len(),
            size_of::<ResidentRowProjectedColumn>(),
            "Metal row decoded projection-header overflow",
        )?,
        decoded_projection_payloads,
        decoded_projection_temporary,
        metal_row_host_vector_bytes(
            request.obligations().count(),
            size_of::<super::ResidentExecutionReceipt>(),
            "Metal row decoded receipt overflow",
        )?,
    ])?;
    let graph_readback_staging = if graph_column_count == 0 {
        0
    } else {
        metal_row_shared_buffer_bytes(output_u32_bytes.max(1))?
    };
    let graph_host = if graph_column_count == 0 {
        0
    } else {
        metal_row_checked_sum([
            metal_row_repeated_private_bytes(
                graph_column_count,
                output_u32_bytes,
                "Metal row host graph-column allocation overflow",
            )?,
            metal_row_host_vector_bytes(
                graph_column_count,
                size_of::<Vec<u32>>(),
                "Metal row host graph-column header overflow",
            )?,
        ])?
    };

    let breakdown = MetalResidentRowScratchBreakdown {
        graph_input_device,
        graph_output_device,
        typed_input_device,
        typed_input_host,
        property_gather_device,
        property_gather_temporaries,
        property_image_device,
        metadata_device,
        metadata_host,
        evaluated_device,
        sort_workspace,
        position_device,
        proof_position_device,
        proof_graph_device,
        proof_membership_device,
        proof_argument_bytes,
        finalize_position_device,
        packet_device,
        packet_readback_staging,
        packet_host,
        decoded_host,
        graph_readback_staging,
        graph_host,
    };
    breakdown.required_bytes()?;
    Ok(breakdown)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_resident_row_program_scratch_bytes_with_strategy(
    request: &ResidentRowProgramRequest,
    input_rows: usize,
    strategy: MetalRowSortStrategy,
) -> Result<usize> {
    metal_resident_row_program_scratch_breakdown(request, input_rows, strategy)?.required_bytes()
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
pub fn metal_resident_row_program_scratch_bytes(
    request: &ResidentRowProgramRequest,
    input_rows: usize,
) -> Result<usize> {
    request.validate()?;
    let output_rows = request.output_cardinality(input_rows)?;
    let strategy = metal_row_sort_strategy(request, input_rows, output_rows)?;
    metal_resident_row_program_scratch_bytes_with_strategy(request, input_rows, strategy)
}

