#[path = "accelerator_row_scratch_tests.rs"]
mod accelerator_row_scratch_tests;

#[cfg(all(test, feature = "accelerator", target_os = "macos"))]
#[path = "accelerator_row_proof_tests.rs"]
mod accelerator_row_proof_tests;

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_register_payload(
    evaluated: &Tensor,
    row_count: usize,
    register: u16,
) -> Result<Tensor> {
    evaluated
        .narrow(
            0,
            1_usize
                .checked_add(metal_row_checked_product(
                    register as usize,
                    row_count,
                    "Metal row register offset overflow",
                )?)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row register offset overflow",
                    )
                })?,
            row_count,
        )
        .map_err(candle_error)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_register_validity(
    evaluated: &Tensor,
    row_count: usize,
    instruction_count: usize,
    register: u16,
) -> Result<Tensor> {
    let register_rows = metal_row_checked_product(
        instruction_count,
        row_count,
        "Metal row validity base overflow",
    )?;
    evaluated
        .narrow(
            0,
            1_usize
                .checked_add(register_rows)
                .and_then(|offset| {
                    metal_row_checked_product(
                        register as usize,
                        row_count,
                        "Metal row validity register offset overflow",
                    )
                    .ok()
                    .and_then(|register| offset.checked_add(register))
                })
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row validity offset overflow",
                    )
                })?,
            row_count,
        )
        .and_then(|validity| validity.to_dtype(DType::U8))
        .map_err(candle_error)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_sort_columns(
    evaluated: &Tensor,
    request: &ResidentRowProgramRequest,
    key: super::ResidentRowSortKey,
    row_count: usize,
) -> Result<(Tensor, Tensor)> {
    let payload = metal_row_register_payload(evaluated, row_count, key.register)?;
    let validity = metal_row_register_validity(
        evaluated,
        row_count,
        request.program.instructions.len(),
        key.register,
    )?;
    let values = if request.program.register_type(key.register) == Some(ResidentRowValueType::Float)
    {
        payload
            .apply_op1_no_bwd(&MetalResidentRowFloatOrderKey { row_count })
            .map_err(candle_error)?
    } else {
        payload
    };
    Ok((values, validity))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_temporal_sidecar_column(
    evaluated: &Tensor,
    request: &ResidentRowProgramRequest,
    register: u16,
    lane: usize,
    row_count: usize,
) -> Result<(Tensor, usize)> {
    let slots = metal_row_temporal_slots(request, row_count)?;
    let (base, lanes) = slots.get(register as usize).copied().ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "Metal temporal row register is absent",
        )
    })?;
    if lane >= lanes {
        return Err(Error::internal(
            "Metal temporal row sidecar lane is outside its admitted layout",
        ));
    }
    let lane_base = base
        .checked_add(metal_row_checked_product(
            lane,
            row_count,
            "Metal temporal sidecar lane overflow",
        )?)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal temporal sidecar lane overflow",
            )
        })?;
    let column = evaluated
        .narrow(0, lane_base, row_count)
        .map_err(candle_error)?;
    Ok((column, lane_base))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[allow(clippy::too_many_arguments)]
fn metal_row_sort_utf8_sidecar(
    evaluated: &Tensor,
    payload_base: usize,
    maximum_width: usize,
    validity: &Tensor,
    key: super::ResidentRowSortKey,
    row_count: usize,
    mut positions: Tensor,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    let maximum_width = u32::try_from(maximum_width).map_err(|_| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal temporal timezone sort width exceeds u32",
        )
    })?;
    let arguments = |byte_position, presence| MetalResidentRowStringDigitArgs {
        row_count: row_count as u64,
        dispatch_base: 0,
        dispatch_count: 0,
        evaluated_word_count: evaluated.elem_count() as u64,
        payload_base: payload_base as u64,
        byte_position,
        presence,
    };
    for byte_position in (0..maximum_width).rev() {
        ensure_not_cancelled(cancellation)?;
        let bytes = evaluated
            .apply_op1_no_bwd(&MetalResidentRowStringDigit {
                arguments: arguments(byte_position, 0),
            })
            .map_err(candle_error)?;
        positions = metal_stable_radix_argsort_from_positions(
            &bytes,
            validity,
            positions,
            key.descending,
            false,
            key.nulls_first,
            device,
            cancellation,
        )?;
        let presence = evaluated
            .apply_op1_no_bwd(&MetalResidentRowStringDigit {
                arguments: arguments(byte_position, 1),
            })
            .map_err(candle_error)?;
        positions = metal_stable_radix_argsort_from_positions(
            &presence,
            validity,
            positions,
            key.descending,
            false,
            key.nulls_first,
            device,
            cancellation,
        )?;
    }
    Ok(positions)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[allow(clippy::too_many_arguments)]
fn metal_row_sort_composite_temporal(
    evaluated: &Tensor,
    request: &ResidentRowProgramRequest,
    key: super::ResidentRowSortKey,
    row_count: usize,
    mut positions: Tensor,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    let value_type = request.program.register_type(key.register).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "Metal temporal sort register is absent",
        )
    })?;
    let payload = metal_row_register_payload(evaluated, row_count, key.register)?;
    let validity = metal_row_register_validity(
        evaluated,
        row_count,
        request.program.instructions.len(),
        key.register,
    )?;
    match value_type {
        ResidentRowValueType::ZonedTime => {
            let (offsets, _) =
                metal_row_temporal_sidecar_column(evaluated, request, key.register, 1, row_count)?;
            positions = metal_stable_radix_argsort_from_positions(
                &offsets,
                &validity,
                positions,
                key.descending,
                false,
                key.nulls_first,
                device,
                cancellation,
            )?;
        }
        ResidentRowValueType::LocalDateTime => {
            let (nanos, _) =
                metal_row_temporal_sidecar_column(evaluated, request, key.register, 0, row_count)?;
            positions = metal_stable_radix_argsort_from_positions(
                &nanos,
                &validity,
                positions,
                key.descending,
                false,
                key.nulls_first,
                device,
                cancellation,
            )?;
        }
        ResidentRowValueType::ZonedDateTime => {
            let (timezone_references, timezone_base) =
                metal_row_temporal_sidecar_column(evaluated, request, key.register, 1, row_count)?;
            let maximum_width = request
                .program
                .timezone_register_capacity(key.register)?
                .ok_or_else(|| Error::internal("Metal timezone sort capacity disappeared"))?;
            positions = metal_row_sort_utf8_sidecar(
                evaluated,
                timezone_base,
                maximum_width,
                &validity,
                key,
                row_count,
                positions,
                device,
                cancellation,
            )?;
            drop(timezone_references);
            let (nanos, _) =
                metal_row_temporal_sidecar_column(evaluated, request, key.register, 0, row_count)?;
            positions = metal_stable_radix_argsort_from_positions(
                &nanos,
                &validity,
                positions,
                key.descending,
                false,
                key.nulls_first,
                device,
                cancellation,
            )?;
        }
        _ => {
            return Err(Error::internal(
                "Metal composite temporal sorter received a scalar row type",
            ));
        }
    }
    positions = metal_stable_radix_argsort_from_positions(
        &payload,
        &validity,
        positions,
        key.descending,
        true,
        key.nulls_first,
        device,
        cancellation,
    )?;
    device.synchronize().map_err(candle_error)?;
    ensure_not_cancelled(cancellation)?;
    Ok(positions)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[allow(clippy::too_many_arguments)]
fn metal_row_sort_materialized_string(
    evaluated: &Tensor,
    request: &ResidentRowProgramRequest,
    key: super::ResidentRowSortKey,
    row_count: usize,
    mut positions: Tensor,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    let maximum_width = match request.program.register_type(key.register) {
        Some(ResidentRowValueType::String) => request
            .program
            .string_register_capacity(key.register)?
            .ok_or_else(|| Error::internal("materialized string sort lost its capacity"))?,
        Some(ResidentRowValueType::List) => request
            .program
            .list_register_capacity(key.register)?
            .ok_or_else(|| Error::internal("materialized list sort lost its capacity"))?
            .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal list sort width overflow",
                )
            })?,
        _ => {
            return Err(Error::internal(
                "materialized variable-width sorter received a fixed-width row type",
            ));
        }
    };
    let maximum_width = u32::try_from(maximum_width).map_err(|_| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal string sort width exceeds u32",
        )
    })?;
    let payload = metal_row_register_payload(evaluated, row_count, key.register)?;
    let validity = metal_row_register_validity(
        evaluated,
        row_count,
        request.program.instructions.len(),
        key.register,
    )?;
    let payload_base = 1_usize
        .checked_add(metal_row_checked_product(
            key.register as usize,
            row_count,
            "Metal string payload base overflow",
        )?)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal string payload base overflow",
            )
        })?;
    let arguments = |byte_position, presence| MetalResidentRowStringDigitArgs {
        row_count: row_count as u64,
        dispatch_base: 0,
        dispatch_count: 0,
        evaluated_word_count: evaluated.elem_count() as u64,
        payload_base: payload_base as u64,
        byte_position,
        presence,
    };
    // Each UTF-8 position is a composite `(present, byte)` digit. Sorting byte first and presence
    // second preserves embedded NUL exactly while making a shorter prefix sort before its longer
    // continuation. Walking positions from the maximum width back to zero is an LSD lexicographic
    // sort over the complete bounded string.
    for byte_position in (0..maximum_width).rev() {
        ensure_not_cancelled(cancellation)?;
        let bytes = evaluated
            .apply_op1_no_bwd(&MetalResidentRowStringDigit {
                arguments: arguments(byte_position, 0),
            })
            .map_err(candle_error)?;
        positions = metal_stable_radix_argsort_from_positions(
            &bytes,
            &validity,
            positions,
            key.descending,
            false,
            key.nulls_first,
            device,
            cancellation,
        )?;
        let presence = evaluated
            .apply_op1_no_bwd(&MetalResidentRowStringDigit {
                arguments: arguments(byte_position, 1),
            })
            .map_err(candle_error)?;
        positions = metal_stable_radix_argsort_from_positions(
            &presence,
            &validity,
            positions,
            key.descending,
            false,
            key.nulls_first,
            device,
            cancellation,
        )?;
    }
    // NULL placement is independent of ASC/DESC in Cypher. The dedicated ninth I64 radix pass
    // reads only validity and therefore does not reinterpret the packed string reference.
    ensure_not_cancelled(cancellation)?;
    positions = payload
        .apply_op3_no_bwd(
            &validity,
            &positions,
            &MetalStableRadixPass {
                digit_pass: 8,
                descending: key.descending,
                nullable: true,
                nulls_first: key.nulls_first,
                value_type: 2,
            },
        )
        .map_err(candle_error)?;
    device.synchronize().map_err(candle_error)?;
    ensure_not_cancelled(cancellation)?;
    Ok(positions)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_order_positions(
    evaluated: &Tensor,
    request: &ResidentRowProgramRequest,
    input_rows: usize,
    strategy: MetalRowSortStrategy,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    let full_positions = || {
        Tensor::arange(
            0_i64,
            i64::try_from(input_rows).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal resident row source positions exceed i64 addressability",
                )
            })?,
            device,
        )
        .map_err(candle_error)
    };
    match strategy {
        MetalRowSortStrategy::EmptyWindow => {
            Tensor::zeros(0, DType::I64, device).map_err(candle_error)
        }
        MetalRowSortStrategy::NoSort => full_positions(),
        MetalRowSortStrategy::SingleKeyTopK { window } => {
            let [key] = request.sort_keys.as_slice() else {
                return Err(Error::internal(
                    "Metal row top-k strategy does not name exactly one key",
                ));
            };
            let (values, validity) = metal_row_sort_columns(evaluated, request, *key, input_rows)?;
            metal_stable_i64_top_k(
                &values,
                &validity,
                window,
                key.descending,
                key.nulls_first,
                device,
                cancellation,
            )
        }
        MetalRowSortStrategy::Radix => {
            if request.sort_keys.is_empty() {
                return Err(Error::internal("Metal row radix strategy has no sort keys"));
            }
            let mut positions = full_positions()?;
            for key in request.sort_keys.iter().rev().copied() {
                ensure_not_cancelled(cancellation)?;
                let value_type = request.program.register_type(key.register);
                if (value_type == Some(ResidentRowValueType::String)
                    && metal_row_string_register_is_materialized(request, key.register)?)
                    || value_type == Some(ResidentRowValueType::List)
                {
                    positions = metal_row_sort_materialized_string(
                        evaluated,
                        request,
                        key,
                        input_rows,
                        positions,
                        device,
                        cancellation,
                    )?;
                } else if matches!(
                    value_type,
                    Some(
                        ResidentRowValueType::ZonedTime
                            | ResidentRowValueType::LocalDateTime
                            | ResidentRowValueType::ZonedDateTime
                    )
                ) {
                    positions = metal_row_sort_composite_temporal(
                        evaluated,
                        request,
                        key,
                        input_rows,
                        positions,
                        device,
                        cancellation,
                    )?;
                } else {
                    let (values, validity) =
                        metal_row_sort_columns(evaluated, request, key, input_rows)?;
                    positions = metal_stable_radix_argsort_from_positions(
                        &values,
                        &validity,
                        positions,
                        key.descending,
                        true,
                        key.nulls_first,
                        device,
                        cancellation,
                    )?;
                }
            }
            Ok(positions)
        }
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_finalize_args(
    request: &ResidentRowProgramRequest,
    input_rows: usize,
    output_rows: usize,
    scratch_bytes: usize,
    proof: &MetalResidentRowProofArgs,
) -> Result<MetalResidentRowFinalizeArgs> {
    let proof_position_count = usize::try_from(proof.position_count).map_err(|_| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal row proof position count exceeds usize",
        )
    })?;
    let strategy = metal_row_sort_strategy(request, input_rows, output_rows)?;
    let expected_proof = metal_row_proof_args(
        request,
        input_rows,
        output_rows,
        proof_position_count,
        metal_row_graph_column_count(request)?,
        strategy,
    )?;
    if *proof != expected_proof {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal resident row proof metadata is not bound to the request manifest",
        ));
    }
    let project = request.project.0.as_u128();
    let mut fingerprint = [0_u64; 4];
    for (index, chunk) in request.manifest.fingerprint.0.chunks_exact(8).enumerate() {
        fingerprint[index] =
            u64::from_le_bytes(chunk.try_into().map_err(|_| {
                Error::internal("resident row fingerprint chunk has an invalid width")
            })?);
    }
    let instruction_words = metal_row_checked_product(
        request.program.instructions.len(),
        METAL_ROW_INSTRUCTION_WORDS,
        "Metal row projection metadata offset overflow",
    )?;
    let receipt_offset = instruction_words
        .checked_add(request.final_registers.len())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row receipt metadata offset overflow",
            )
        })?;
    let projection_word_count =
        request
            .final_registers
            .iter()
            .try_fold(0_usize, |total, register| {
                total
                    .checked_add(metal_row_projection_packet_words(
                        request,
                        *register,
                        output_rows,
                    )?)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal row projection packet overflow",
                        )
                    })
            })?;
    Ok(MetalResidentRowFinalizeArgs {
        execution_high: request.execution.high,
        execution_low: request.execution.low,
        project_high: (project >> 64) as u64,
        project_low: project as u64,
        bookmark_term: request.expected_bookmark.term,
        bookmark_index: request.expected_bookmark.index,
        graph_revision: request.expected_graph_revision,
        layout_version: request.expected_layout_version,
        fingerprint_0: fingerprint[0],
        fingerprint_1: fingerprint[1],
        fingerprint_2: fingerprint[2],
        fingerprint_3: fingerprint[3],
        input_rows: input_rows as u64,
        output_rows: output_rows as u64,
        scratch_bytes: scratch_bytes as u64,
        output_word_count: metal_row_packet_words(request, output_rows)? as u64,
        metadata_word_count: metal_row_metadata_words(request)? as u64,
        evaluated_word_count: metal_row_evaluate_words(request, input_rows)? as u64,
        instruction_count: request.program.instructions.len() as u32,
        projection_count: request.final_registers.len() as u32,
        receipt_count: request.obligations().count() as u32,
        projection_metadata_offset: u32::try_from(instruction_words).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row projection metadata offset exceeds u32",
            )
        })?,
        receipt_metadata_offset: u32::try_from(receipt_offset).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row receipt metadata offset exceeds u32",
            )
        })?,
        proof_strategy: proof.strategy,
        proof_sort_key_count: proof.sort_key_count,
        proof_position_count: proof.position_count,
        proof_offset: proof.offset,
        proof_graph_column_count: proof.graph_column_count,
        proof_word_count: proof.proof_word_count,
        projection_word_count: projection_word_count as u64,
        dispatch_base: 0,
        dispatch_count: 0,
    })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
struct DecodedMetalRowPacket {
    project: ProjectId,
    execution: super::ResidentExecutionId,
    bookmark: Bookmark,
    graph_revision: u64,
    layout_version: super::ResidentGraphLayoutVersion,
    manifest_fingerprint: super::ResidentRowManifestFingerprint,
    input_cardinality: usize,
    source_positions: Vec<u64>,
    projected_columns: Vec<ResidentRowProjectedColumn>,
    receipts: Vec<super::ResidentExecutionReceipt>,
    scratch_bytes: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn decode_metal_row_packet(
    words: &[i64],
    request: &ResidentRowProgramRequest,
) -> Result<DecodedMetalRowPacket> {
    let corrupt = |detail: &'static str| Error::new(ErrorCode::CorruptStorage, detail);
    if words.len() < METAL_ROW_PACKET_HEADER_WORDS || words[0] as u64 != METAL_ROW_PACKET_MAGIC {
        return Err(corrupt("Metal resident row packet has an invalid header"));
    }
    if words[1] == 1 {
        return Err(Error::new(
            ErrorCode::QueryType,
            "integer arithmetic overflow",
        ));
    }
    if words[1] == 2 {
        return Err(Error::new(ErrorCode::QueryType, "modulo by zero"));
    }
    if words[1] == 3 {
        return Err(corrupt(
            "Metal resident row evaluator rejected its instruction descriptor",
        ));
    }
    if words[1] == 4 {
        return Err(Error::new(
            ErrorCode::QueryType,
            "integer negation overflow",
        ));
    }
    if words[1] == 5 {
        return Err(corrupt(
            "Metal resident row device proof rejected result publication",
        ));
    }
    if words[1] == 6 {
        return Err(Error::new(
            ErrorCode::TemporalRange,
            "temporal duration arithmetic is outside the supported range",
        ));
    }
    if words[1] == 7 {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "native Metal calendar-duration arithmetic requires a fixed-offset timezone",
        ));
    }
    if words[1] != 0 {
        return Err(corrupt(
            "Metal resident row packet has an unknown completion status",
        ));
    }
    let input_cardinality_u64 = words[14] as u64;
    let input_cardinality = usize::try_from(input_cardinality_u64)
        .map_err(|_| corrupt("Metal row input cardinality exceeds usize"))?;
    let output_cardinality = usize::try_from(words[15] as u64)
        .map_err(|_| corrupt("Metal row output cardinality exceeds usize"))?;
    let source_count = usize::try_from(words[16] as u64)
        .map_err(|_| corrupt("Metal row source count exceeds usize"))?;
    let projection_count = usize::try_from(words[17] as u64)
        .map_err(|_| corrupt("Metal row projection count exceeds usize"))?;
    let receipt_count = usize::try_from(words[18] as u64)
        .map_err(|_| corrupt("Metal row receipt count exceeds usize"))?;
    let scratch_bytes = usize::try_from(words[19] as u64)
        .map_err(|_| corrupt("Metal row scratch count exceeds usize"))?;
    let expected_output_cardinality = request.output_cardinality(input_cardinality)?;
    let expected_packet_words = metal_row_packet_words(request, output_cardinality)?;
    if output_cardinality != expected_output_cardinality
        || source_count != output_cardinality
        || projection_count != request.final_registers.len()
        || receipt_count != request.obligations().count()
        || words.len() != expected_packet_words
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            format!(
                "Metal resident row packet has an invalid cardinality or result shape: input={input_cardinality}, output={output_cardinality}/{expected_output_cardinality}, sources={source_count}, projections={projection_count}/{}, receipts={receipt_count}/{}, words={}/{expected_packet_words}, header={:?}",
                request.final_registers.len(),
                request.obligations().count(),
                words.len(),
                &words[..METAL_ROW_PACKET_HEADER_WORDS],
            ),
        ));
    }

    let project_bits = (u128::from(words[4] as u64) << 64) | u128::from(words[5] as u64);
    let project = ProjectId(uuid::Uuid::from_u128(project_bits));
    let execution = super::ResidentExecutionId {
        high: words[2] as u64,
        low: words[3] as u64,
    };
    let bookmark = Bookmark {
        term: words[6] as u64,
        index: words[7] as u64,
    };
    let mut fingerprint = [0_u8; 32];
    for index in 0..4 {
        fingerprint[index * 8..index * 8 + 8]
            .copy_from_slice(&(words[10 + index] as u64).to_le_bytes());
    }

    let mut cursor = METAL_ROW_PACKET_HEADER_WORDS;
    let source_positions = words[cursor..cursor + source_count]
        .iter()
        .map(|word| {
            let position = *word as u64;
            (position < input_cardinality_u64)
                .then_some(position)
                .ok_or_else(|| {
                    corrupt("Metal resident row packet contains an invalid source position")
                })
        })
        .collect::<Result<Vec<_>>>()?;
    cursor += source_count;

    let mut projected_columns = Vec::with_capacity(projection_count);
    for _ in 0..projection_count {
        let register = u16::try_from(words[cursor]).map_err(|_| {
            corrupt("Metal resident row packet contains an invalid projection register")
        })?;
        let value_type = match words[cursor + 1] {
            1 => ResidentRowValueType::Boolean,
            2 => ResidentRowValueType::Integer,
            3 => ResidentRowValueType::Float,
            4 => ResidentRowValueType::String,
            5 => ResidentRowValueType::Date,
            6 => ResidentRowValueType::LocalTime,
            7 => ResidentRowValueType::ZonedTime,
            8 => ResidentRowValueType::LocalDateTime,
            9 => ResidentRowValueType::ZonedDateTime,
            10 => ResidentRowValueType::List,
            _ => {
                return Err(corrupt(
                    "Metal resident row packet contains an invalid projection type",
                ));
            }
        };
        let payload_start = cursor + METAL_ROW_PACKET_PROJECTION_HEADER_WORDS;
        let validity_start = payload_start
            + match value_type {
                ResidentRowValueType::Boolean
                | ResidentRowValueType::Integer
                | ResidentRowValueType::Float
                | ResidentRowValueType::String
                | ResidentRowValueType::Date
                | ResidentRowValueType::LocalTime
                | ResidentRowValueType::List => output_cardinality,
                ResidentRowValueType::ZonedTime | ResidentRowValueType::LocalDateTime => {
                    output_cardinality.saturating_mul(2)
                }
                ResidentRowValueType::ZonedDateTime => output_cardinality.saturating_mul(3),
            };
        let validity = words[validity_start..validity_start + output_cardinality]
            .iter()
            .map(|word| {
                let value = u8::try_from(*word).map_err(|_| {
                    corrupt("Metal resident row packet contains invalid projection validity")
                })?;
                if value > 1 {
                    return Err(corrupt(
                        "Metal resident row packet contains invalid projection validity",
                    ));
                }
                Ok(value)
            })
            .collect::<Result<Vec<_>>>()?;
        let column = match value_type {
            ResidentRowValueType::Boolean => ResidentRowColumn::Boolean {
                values: words[payload_start..payload_start + output_cardinality]
                    .iter()
                    .map(|word| {
                        let value = u8::try_from(*word).map_err(|_| {
                            corrupt("Metal resident row packet contains an invalid Boolean value")
                        })?;
                        if value > 1 {
                            return Err(corrupt(
                                "Metal resident row packet contains an invalid Boolean value",
                            ));
                        }
                        Ok(value)
                    })
                    .collect::<Result<Vec<_>>>()?,
                validity,
            },
            ResidentRowValueType::Integer => ResidentRowColumn::Integer {
                values: words[payload_start..payload_start + output_cardinality].to_vec(),
                validity,
            },
            ResidentRowValueType::Float => ResidentRowColumn::Float {
                bits: words[payload_start..payload_start + output_cardinality]
                    .iter()
                    .map(|word| *word as u64)
                    .collect(),
                validity,
            },
            ResidentRowValueType::String => {
                let packed_start = validity_start + output_cardinality;
                let capacity = request
                    .program
                    .string_register_capacity(register)?
                    .ok_or_else(|| corrupt("Metal projected string capacity disappeared"))?;
                let slot_bytes = output_cardinality
                    .checked_mul(capacity)
                    .ok_or_else(|| corrupt("Metal projected string byte arena overflow"))?;
                let packed_words = slot_bytes.div_ceil(size_of::<i64>());
                let mut packed = Vec::with_capacity(packed_words.saturating_mul(8));
                for word in &words[packed_start..packed_start + packed_words] {
                    packed.extend_from_slice(&word.to_le_bytes());
                }
                packed.truncate(slot_bytes);
                let mut offsets = Vec::with_capacity(output_cardinality.saturating_add(1));
                let mut bytes = Vec::new();
                offsets.push(0_u32);
                for row in 0..output_cardinality {
                    let length = usize::try_from(words[payload_start + row])
                        .map_err(|_| corrupt("Metal projected string length exceeds usize"))?;
                    if length > capacity || (validity[row] == 0 && length != 0) {
                        return Err(corrupt(
                            "Metal projected string length exceeds its admitted slot",
                        ));
                    }
                    let slot = row
                        .checked_mul(capacity)
                        .ok_or_else(|| corrupt("Metal projected string slot overflow"))?;
                    let value = packed
                        .get(slot..slot + length)
                        .ok_or_else(|| corrupt("Metal projected string slot is truncated"))?;
                    std::str::from_utf8(value)
                        .map_err(|_| corrupt("Metal projected string is not valid UTF-8"))?;
                    bytes.extend_from_slice(value);
                    offsets.push(
                        u32::try_from(bytes.len())
                            .map_err(|_| corrupt("Metal projected string bytes exceed u32"))?,
                    );
                }
                ResidentRowColumn::String {
                    offsets,
                    bytes,
                    validity,
                }
            }
            ResidentRowValueType::List => {
                let packed_start = validity_start + output_cardinality;
                let capacity = request
                    .program
                    .list_register_capacity(register)?
                    .ok_or_else(|| corrupt("Metal projected list capacity disappeared"))?;
                let capacity_bytes = capacity
                    .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
                    .ok_or_else(|| corrupt("Metal projected list byte capacity overflow"))?;
                let slot_bytes = output_cardinality
                    .checked_mul(capacity_bytes)
                    .ok_or_else(|| corrupt("Metal projected list byte arena overflow"))?;
                let packed_words = slot_bytes.div_ceil(size_of::<i64>());
                let mut packed = Vec::with_capacity(packed_words.saturating_mul(8));
                for word in &words[packed_start..packed_start + packed_words] {
                    packed.extend_from_slice(&word.to_le_bytes());
                }
                packed.truncate(slot_bytes);
                let maximum_elements = output_cardinality
                    .checked_mul(capacity)
                    .ok_or_else(|| corrupt("Metal projected list element arena overflow"))?;
                let mut offsets = Vec::with_capacity(output_cardinality.saturating_add(1));
                let mut values = Vec::with_capacity(maximum_elements);
                let mut element_validity = Vec::with_capacity(maximum_elements);
                offsets.push(0_u32);
                for row in 0..output_cardinality {
                    let length = usize::try_from(words[payload_start + row])
                        .map_err(|_| corrupt("Metal projected list length exceeds usize"))?;
                    if length > capacity || (validity[row] == 0 && length != 0) {
                        return Err(corrupt(
                            "Metal projected list length exceeds its admitted slot",
                        ));
                    }
                    let slot = row
                        .checked_mul(capacity_bytes)
                        .ok_or_else(|| corrupt("Metal projected list slot overflow"))?;
                    let encoded_length = length
                        .checked_mul(METAL_ROW_LIST_ELEMENT_BYTES)
                        .ok_or_else(|| corrupt("Metal projected list byte length overflow"))?;
                    let encoded = packed
                        .get(slot..slot + encoded_length)
                        .ok_or_else(|| corrupt("Metal projected list slot is truncated"))?;
                    for element in encoded.chunks_exact(METAL_ROW_LIST_ELEMENT_BYTES) {
                        let order_bytes: [u8; size_of::<i64>()] = element[1..]
                            .try_into()
                            .map_err(|_| corrupt("Metal projected list element is truncated"))?;
                        match element[0] {
                            1 => {
                                values
                                    .push((u64::from_be_bytes(order_bytes) ^ (1_u64 << 63)) as i64);
                                element_validity.push(1);
                            }
                            2 if order_bytes == [0; size_of::<i64>()] => {
                                values.push(0);
                                element_validity.push(0);
                            }
                            _ => {
                                return Err(corrupt(
                                    "Metal projected list element encoding is invalid",
                                ));
                            }
                        }
                    }
                    offsets.push(
                        u32::try_from(values.len())
                            .map_err(|_| corrupt("Metal projected list elements exceed u32"))?,
                    );
                }
                ResidentRowColumn::List {
                    offsets,
                    values,
                    element_validity,
                    validity,
                }
            }
            ResidentRowValueType::Date => ResidentRowColumn::Date {
                days: words[payload_start..payload_start + output_cardinality].to_vec(),
                validity,
            },
            ResidentRowValueType::LocalTime => ResidentRowColumn::LocalTime {
                nanos: words[payload_start..payload_start + output_cardinality].to_vec(),
                validity,
            },
            ResidentRowValueType::ZonedTime => {
                let offset_start = payload_start + output_cardinality;
                ResidentRowColumn::ZonedTime {
                    nanos: words[payload_start..payload_start + output_cardinality].to_vec(),
                    offset_seconds: words[offset_start..offset_start + output_cardinality]
                        .iter()
                        .map(|word| {
                            i32::try_from(*word).map_err(|_| {
                                corrupt("Metal resident row packet contains an invalid time offset")
                            })
                        })
                        .collect::<Result<Vec<_>>>()?,
                    validity,
                }
            }
            ResidentRowValueType::LocalDateTime => {
                let nanos_start = payload_start + output_cardinality;
                ResidentRowColumn::LocalDateTime {
                    seconds: words[payload_start..payload_start + output_cardinality].to_vec(),
                    nanos: words[nanos_start..nanos_start + output_cardinality]
                        .iter()
                        .map(|word| {
                            u32::try_from(*word).map_err(|_| {
                                corrupt("Metal resident row packet contains invalid datetime nanos")
                            })
                        })
                        .collect::<Result<Vec<_>>>()?,
                    validity,
                }
            }
            ResidentRowValueType::ZonedDateTime => {
                let nanos_start = payload_start + output_cardinality;
                let lengths_start = nanos_start + output_cardinality;
                let packed_start = validity_start + output_cardinality;
                let capacity = request
                    .program
                    .timezone_register_capacity(register)?
                    .ok_or_else(|| corrupt("Metal projected timezone capacity disappeared"))?;
                let slot_bytes = output_cardinality
                    .checked_mul(capacity)
                    .ok_or_else(|| corrupt("Metal projected timezone byte arena overflow"))?;
                let packed_words = slot_bytes.div_ceil(size_of::<i64>());
                let mut packed = Vec::with_capacity(packed_words.saturating_mul(8));
                for word in &words[packed_start..packed_start + packed_words] {
                    packed.extend_from_slice(&word.to_le_bytes());
                }
                packed.truncate(slot_bytes);
                let mut timezone_offsets = Vec::with_capacity(output_cardinality.saturating_add(1));
                let mut timezone_bytes = Vec::new();
                timezone_offsets.push(0_u32);
                for row in 0..output_cardinality {
                    let length = usize::try_from(words[lengths_start + row])
                        .map_err(|_| corrupt("Metal projected timezone length exceeds usize"))?;
                    if length > capacity || (validity[row] == 0 && length != 0) {
                        return Err(corrupt(
                            "Metal projected timezone length exceeds its admitted slot",
                        ));
                    }
                    let slot = row
                        .checked_mul(capacity)
                        .ok_or_else(|| corrupt("Metal projected timezone slot overflow"))?;
                    timezone_bytes.extend_from_slice(
                        packed
                            .get(slot..slot + length)
                            .ok_or_else(|| corrupt("Metal projected timezone slot is truncated"))?,
                    );
                    timezone_offsets.push(
                        u32::try_from(timezone_bytes.len())
                            .map_err(|_| corrupt("Metal projected timezone bytes exceed u32"))?,
                    );
                }
                ResidentRowColumn::ZonedDateTime {
                    seconds: words[payload_start..payload_start + output_cardinality].to_vec(),
                    nanos: words[nanos_start..nanos_start + output_cardinality]
                        .iter()
                        .map(|word| {
                            u32::try_from(*word).map_err(|_| {
                                corrupt("Metal resident row packet contains invalid datetime nanos")
                            })
                        })
                        .collect::<Result<Vec<_>>>()?,
                    timezone_offsets,
                    timezone_bytes,
                    validity,
                }
            }
        };
        projected_columns.push(ResidentRowProjectedColumn { register, column });
        cursor = cursor
            .checked_add(metal_row_projection_packet_words(
                request,
                register,
                output_cardinality,
            )?)
            .ok_or_else(|| corrupt("Metal row projection cursor overflow"))?;
    }

    let mut receipts = Vec::with_capacity(receipt_count);
    for _ in 0..receipt_count {
        let receipt = &words[cursor..cursor + METAL_ROW_PACKET_RECEIPT_WORDS];
        let kind = match receipt[3] {
            3 => super::ResidentObligationKind::Expression,
            9 => super::ResidentObligationKind::Sort,
            _ => return Err(corrupt("Metal row packet contains an invalid receipt kind")),
        };
        if receipt[4] as u64 != METAL_ROW_SCOPE_EXPRESSION {
            return Err(corrupt(
                "Metal row packet contains an invalid receipt scope",
            ));
        }
        let scope_index = u16::try_from(receipt[5])
            .map_err(|_| corrupt("Metal row receipt scope exceeds u16"))?;
        if receipt[8] != super::ResidentDeviceCompletion::Metal as u8 as i64 {
            return Err(corrupt(
                "Metal row packet contains a non-Metal completion marker",
            ));
        }
        receipts.push(super::ResidentExecutionReceipt {
            execution: super::ResidentExecutionId {
                high: receipt[0] as u64,
                low: receipt[1] as u64,
            },
            obligation: super::ResidentExecutionObligation {
                id: receipt[2] as u64,
                kind,
                scope: super::ResidentObligationScope::Expression(scope_index),
            },
            input_cardinality: receipt[6] as u64,
            output_cardinality: receipt[7] as u64,
            completion: super::ResidentDeviceCompletion::Metal,
        });
        cursor += METAL_ROW_PACKET_RECEIPT_WORDS;
    }
    if cursor != words.len() {
        return Err(corrupt("Metal row packet has trailing words"));
    }
    Ok(DecodedMetalRowPacket {
        project,
        execution,
        bookmark,
        graph_revision: words[8] as u64,
        layout_version: words[9] as u64,
        manifest_fingerprint: super::ResidentRowManifestFingerprint(fingerprint),
        input_cardinality,
        source_positions,
        projected_columns,
        receipts,
        scratch_bytes,
    })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_stable_radix_argsort(
    values: &Tensor,
    validity: &Tensor,
    descending: bool,
    nullable: bool,
    nulls_first: bool,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    let positions = Tensor::arange(
        0_i64,
        i64::try_from(values.elem_count()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal stable radix input exceeds i64 addressability",
            )
        })?,
        device,
    )
    .map_err(candle_error)?;
    metal_stable_radix_argsort_from_positions(
        values,
        validity,
        positions,
        descending,
        nullable,
        nulls_first,
        device,
        cancellation,
    )
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[allow(clippy::too_many_arguments)]
fn metal_stable_radix_argsort_from_positions(
    values: &Tensor,
    validity: &Tensor,
    mut positions: Tensor,
    descending: bool,
    nullable: bool,
    nulls_first: bool,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    if values.rank() != 1
        || values.elem_count() == 0
        || validity.dtype() != DType::U8
        || validity.rank() != 1
        || validity.elem_count() != values.elem_count()
        || positions.dtype() != DType::I64
        || positions.rank() != 1
        || positions.elem_count() != values.elem_count()
    {
        return Err(Error::new(
            ErrorCode::QueryType,
            "Metal stable radix sort received invalid columns or source positions",
        ));
    }
    let (value_type, value_passes) = match values.dtype() {
        DType::U8 => (0, 1),
        DType::U32 => (1, 4),
        DType::I64 => (2, 8),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal stable radix sort requires U8, U32, or I64 values",
            ));
        }
    };
    if nullable && values.dtype() != DType::I64 {
        return Err(Error::new(
            ErrorCode::QueryType,
            "nullable Metal radix sort requires I64 values",
        ));
    }
    for digit_pass in 0..value_passes {
        ensure_not_cancelled(cancellation)?;
        positions = values
            .apply_op3_no_bwd(
                validity,
                &positions,
                &MetalStableRadixPass {
                    digit_pass,
                    descending,
                    nullable,
                    nulls_first,
                    value_type,
                },
            )
            .map_err(candle_error)?;
        // Bound peak residency to one radix pass and make the cancellation boundary real. Candle
        // otherwise retains every pass's intermediate buffers in one pending command buffer.
        device.synchronize().map_err(candle_error)?;
    }
    if nullable {
        ensure_not_cancelled(cancellation)?;
        positions = values
            .apply_op3_no_bwd(
                validity,
                &positions,
                &MetalStableRadixPass {
                    digit_pass: 8,
                    descending,
                    nullable,
                    nulls_first,
                    value_type,
                },
            )
            .map_err(candle_error)?;
        device.synchronize().map_err(candle_error)?;
    }
    ensure_not_cancelled(cancellation)?;
    Ok(positions)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_stable_i64_top_k(
    values: &Tensor,
    validity: &Tensor,
    limit: usize,
    descending: bool,
    nulls_first: bool,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    if values.dtype() != DType::I64
        || values.rank() != 1
        || values.elem_count() == 0
        || validity.dtype() != DType::U8
        || validity.rank() != 1
        || validity.elem_count() != values.elem_count()
        || limit == 0
        || limit > METAL_TOP_K_MAX_ROWS
    {
        return Err(Error::new(
            ErrorCode::QueryType,
            "Metal stable top-k received invalid columns or limit",
        ));
    }
    let row_count = values.elem_count();
    let mut candidates = Tensor::arange(
        0_i64,
        i64::try_from(row_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal stable top-k input exceeds i64 addressability",
            )
        })?,
        device,
    )
    .map_err(candle_error)?;
    loop {
        ensure_not_cancelled(cancellation)?;
        candidates = values
            .apply_op3_no_bwd(
                validity,
                &candidates,
                &MetalStableI64TopK {
                    row_count,
                    limit,
                    descending,
                    nulls_first,
                },
            )
            .map_err(candle_error)?;
        // Each recursive pruning pass owns O(candidate_count) output. Commit it before the next
        // pass so dropped candidates cannot accumulate outside the shared scratch admission.
        device.synchronize().map_err(candle_error)?;
        if candidates.elem_count() <= limit {
            ensure_not_cancelled(cancellation)?;
            return Ok(candidates);
        }
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Copy, Debug)]
struct EncodedValueMatrixCell {
    tag: u32,
    payload: u64,
    auxiliary: u32,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl Default for EncodedValueMatrixCell {
    fn default() -> Self {
        Self {
            tag: 7,
            payload: 0,
            auxiliary: 0,
        }
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn encode_value_matrix_at(
    value: &ResidentValueMatrixValue,
    index: usize,
    depth: usize,
    cells: &mut Vec<EncodedValueMatrixCell>,
    list_entries: &mut Vec<u32>,
    utf8: &mut Vec<u8>,
) -> Result<()> {
    if depth >= super::RESIDENT_SCALAR_STRUCTURAL_MAX_PAIRS || index >= cells.len() {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident value matrix exceeds its bounded structural arena",
        ));
    }
    let cell = match value {
        ResidentValueMatrixValue::Null => EncodedValueMatrixCell {
            tag: 0,
            ..EncodedValueMatrixCell::default()
        },
        ResidentValueMatrixValue::Boolean(value) => EncodedValueMatrixCell {
            tag: 1,
            payload: u64::from(*value),
            auxiliary: 0,
        },
        ResidentValueMatrixValue::Integer(value) => EncodedValueMatrixCell {
            tag: 2,
            payload: *value as u64,
            auxiliary: 0,
        },
        ResidentValueMatrixValue::Float(bits) => EncodedValueMatrixCell {
            tag: 3,
            payload: *bits,
            auxiliary: 0,
        },
        ResidentValueMatrixValue::String(value) => {
            let start = u32::try_from(utf8.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident value matrix UTF-8 offset exceeds u32",
                )
            })?;
            let length = u32::try_from(value.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident value matrix string length exceeds u32",
                )
            })?;
            utf8.try_reserve(value.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident value matrix UTF-8 staging allocation failed",
                )
            })?;
            utf8.extend_from_slice(value.as_bytes());
            EncodedValueMatrixCell {
                tag: 4,
                payload: u64::from(start),
                auxiliary: length,
            }
        }
        ResidentValueMatrixValue::List(values) => {
            let start = u32::try_from(list_entries.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident value matrix list offset exceeds u32",
                )
            })?;
            let count = u32::try_from(values.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident value matrix list length exceeds u32",
                )
            })?;
            for child in values {
                let child_index = cells.len();
                let child_index_u32 = u32::try_from(child_index).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "resident value matrix cell index exceeds u32",
                    )
                })?;
                cells.push(EncodedValueMatrixCell::default());
                list_entries.push(child_index_u32);
                encode_value_matrix_at(child, child_index, depth + 1, cells, list_entries, utf8)?;
            }
            EncodedValueMatrixCell {
                tag: 5,
                payload: u64::from(start),
                auxiliary: count,
            }
        }
        ResidentValueMatrixValue::Map => EncodedValueMatrixCell {
            tag: 6,
            ..EncodedValueMatrixCell::default()
        },
        ResidentValueMatrixValue::Node => EncodedValueMatrixCell {
            tag: 8,
            ..EncodedValueMatrixCell::default()
        },
        ResidentValueMatrixValue::Relationship => EncodedValueMatrixCell {
            tag: 9,
            ..EncodedValueMatrixCell::default()
        },
        ResidentValueMatrixValue::Path => EncodedValueMatrixCell {
            tag: 10,
            ..EncodedValueMatrixCell::default()
        },
    };
    cells[index] = cell;
    Ok(())
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn encode_value_matrix(
    program: &ResidentValueMatrixProgram,
) -> Result<(Vec<u32>, Vec<u32>, Vec<u8>, usize, usize, usize)> {
    program.validate()?;
    let root_count = program.values.len();
    let mut cells = vec![EncodedValueMatrixCell::default(); root_count];
    let mut list_entries = Vec::new();
    let mut utf8 = Vec::new();
    for (index, value) in program.values.iter().enumerate() {
        encode_value_matrix_at(value, index, 0, &mut cells, &mut list_entries, &mut utf8)?;
    }
    let cell_count = cells.len();
    let list_entry_count = list_entries.len();
    let utf8_byte_count = utf8.len();
    let mut words = Vec::new();
    words
        .try_reserve_exact(cell_count.saturating_mul(4))
        .map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident value matrix descriptor allocation failed",
            )
        })?;
    for cell in cells {
        words.push(cell.tag);
        words.push(cell.payload as u32);
        words.push((cell.payload >> 32) as u32);
        words.push(cell.auxiliary);
    }
    if list_entries.is_empty() {
        list_entries.push(0);
    }
    if utf8.is_empty() {
        utf8.push(0);
    }
    Ok((
        words,
        list_entries,
        utf8,
        cell_count,
        list_entry_count,
        utf8_byte_count,
    ))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn execute_metal_value_matrix(
    program: &ResidentValueMatrixProgram,
    input_rows: usize,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<(Tensor, Tensor, Tensor)> {
    let Device::Metal(_) = device else {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "native resident value matrix requires a Metal device",
        ));
    };
    ensure_not_cancelled(cancellation)?;
    let candidate_count = program.maximum_rows(input_rows)?;
    checked_u32(input_rows, "Metal value-matrix input")?;
    checked_u32(candidate_count, "Metal value-matrix candidates")?;
    let (words, list_entries, utf8, cell_count, list_entry_count, utf8_byte_count) =
        encode_value_matrix(program)?;
    let descriptors = Tensor::from_slice(&words, words.len(), device).map_err(candle_error)?;
    let lists =
        Tensor::from_slice(&list_entries, list_entries.len(), device).map_err(candle_error)?;
    let utf8 = Tensor::from_slice(&utf8, utf8.len(), device).map_err(candle_error)?;
    let encoded = descriptors
        .apply_op3_no_bwd(
            &lists,
            &utf8,
            &MetalValueMatrix {
                input_rows,
                value_count: program.values.len(),
                cell_count,
                list_entry_count,
                utf8_byte_count,
                comparison: program.comparison,
                exclude_same_index: program.exclude_same_index,
            },
        )
        .map_err(candle_error)?;
    let keep = encoded
        .narrow(1, 0, 1)
        .and_then(|values| values.squeeze(1))
        .and_then(|values| values.contiguous())
        .and_then(|values| values.eq(1_u32))
        .map_err(candle_error)?;
    let selected = selected_positions(&keep, candidate_count, device, cancellation)?;
    if selected.elem_count() == 0 {
        let empty = Tensor::zeros(0, DType::U32, device).map_err(candle_error)?;
        return Ok((empty.clone(), empty.clone(), empty));
    }
    let select_column = |column| {
        encoded
            .narrow(1, column, 1)
            .and_then(|values| values.squeeze(1))
            .and_then(|values| values.contiguous())
            .and_then(|values| values.index_select(&selected, 0))
            .map_err(candle_error)
    };
    ensure_not_cancelled(cancellation)?;
    Ok((select_column(1)?, select_column(2)?, select_column(3)?))
}

fn mutation_gather_column(
    values: Option<&Tensor>,
    safe_rows: &Tensor,
    row_count: usize,
    dtype: DType,
    device: &Device,
    name: &str,
) -> Result<Tensor> {
    if row_count == 0 {
        return Tensor::zeros(0, dtype, device).map_err(candle_error);
    }
    let values = values.ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            format!("non-empty resident {name} mutation column has no value tensor"),
        )
    })?;
    if values.dtype() != dtype || values.rank() != 1 {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            format!("resident {name} mutation column has an invalid tensor shape"),
        ));
    }
    values.index_select(safe_rows, 0).map_err(candle_error)
}

fn mutation_gather_validity(
    validity: Option<&Tensor>,
    safe_rows: &Tensor,
    entity_validity: &Tensor,
    row_count: usize,
    device: &Device,
    name: &str,
) -> Result<Tensor> {
    if row_count == 0 {
        return Tensor::zeros(0, DType::I64, device).map_err(candle_error);
    }
    let validity = validity.ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            format!("non-empty resident {name} mutation column has no validity tensor"),
        )
    })?;
    if validity.dtype() != DType::U8 || validity.rank() != 1 {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            format!("resident {name} mutation validity has an invalid tensor shape"),
        ));
    }
    validity
        .index_select(safe_rows, 0)
        .and_then(|value| value.to_dtype(DType::I64))
        .and_then(|value| value.broadcast_mul(entity_validity))
        .map_err(candle_error)
}

fn mutation_i64_bytes(bytes: Option<&Tensor>, device: &Device) -> Result<Tensor> {
    match bytes {
        Some(bytes) => bytes.to_dtype(DType::I64).map_err(candle_error),
        None => Tensor::zeros(0, DType::I64, device).map_err(candle_error),
    }
}

fn metal_mutation_continuation_value_source(
    continuation: &super::ResidentMutationContinuation,
) -> Result<Option<MetalMutationContinuationValueSource>> {
    let mut selected = None;
    let mut include = |source: MetalMutationContinuationValueSource| -> Result<()> {
        if selected.is_some_and(|selected| selected != source) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation continuation currently admits one immutable value source",
            ));
        }
        selected = Some(source);
        Ok(())
    };
    for stage in &continuation.stages {
        match stage {
            super::ResidentMutationPostStage::Project { columns } => {
                for column in columns {
                    match column {
                        super::ResidentMutationProjectionSource::IntegerProperty(source) => {
                            include(MetalMutationContinuationValueSource::Property(*source))?;
                        }
                        super::ResidentMutationProjectionSource::PropertyIsNotNull(source) => {
                            include(MetalMutationContinuationValueSource::PropertyIsNotNull(
                                *source,
                            ))?;
                        }
                        super::ResidentMutationProjectionSource::PropertyCount(binding) => {
                            include(MetalMutationContinuationValueSource::PropertyCount(
                                *binding,
                            ))?;
                        }
                        super::ResidentMutationProjectionSource::Entity(_)
                        | super::ResidentMutationProjectionSource::ComputedValue(_)
                        | super::ResidentMutationProjectionSource::AggregateInteger => {}
                    }
                }
            }
            super::ResidentMutationPostStage::FilterIntegerModuloEquals { source, .. }
            | super::ResidentMutationPostStage::SumInteger { source } => {
                include(MetalMutationContinuationValueSource::Property(*source))?
            }
            super::ResidentMutationPostStage::SumPropertyCount { source } => {
                include(MetalMutationContinuationValueSource::PropertyCount(*source))?
            }
            super::ResidentMutationPostStage::Skip { .. }
            | super::ResidentMutationPostStage::Limit { .. } => {}
        }
    }
    for output in &continuation.outputs {
        match output.source {
            super::ResidentMutationProjectionSource::IntegerProperty(source) => {
                include(MetalMutationContinuationValueSource::Property(source))?;
            }
            super::ResidentMutationProjectionSource::PropertyIsNotNull(source) => {
                include(MetalMutationContinuationValueSource::PropertyIsNotNull(
                    source,
                ))?;
            }
            super::ResidentMutationProjectionSource::PropertyCount(binding) => {
                include(MetalMutationContinuationValueSource::PropertyCount(binding))?;
            }
            super::ResidentMutationProjectionSource::Entity(_)
            | super::ResidentMutationProjectionSource::ComputedValue(_)
            | super::ResidentMutationProjectionSource::AggregateInteger => {}
        }
    }
    Ok(selected)
}

fn push_metal_mutation_continuation_obligation(
    words: &mut Vec<u64>,
    obligation: super::ResidentExecutionObligation,
) -> Result<()> {
    let (scope, index) = match obligation.scope {
        super::ResidentObligationScope::Selection => (0, 0),
        super::ResidentObligationScope::Expression(index) => (2, u64::from(index)),
        _ => {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal mutation continuation requires selection- or expression-scoped obligations",
            ));
        }
    };
    if obligation.id == 0 {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal mutation continuation obligation has no execution identity",
        ));
    }
    words.extend([obligation.id, obligation.kind as u64, scope, index]);
    Ok(())
}

fn metal_row_create_continuation_property_source(
    continuation: &super::ResidentRowCreateContinuation,
) -> Result<Option<(u16, u16)>> {
    let mut selected = None;
    let mut include = |entity: u16, property_name: u16| -> Result<()> {
        let source = (entity, property_name);
        if selected.is_some_and(|selected| selected != source) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal row CREATE continuation requires one integer property source",
            ));
        }
        selected = Some(source);
        Ok(())
    };
    for stage in &continuation.stages {
        match stage {
            super::ResidentRowCreatePostStage::Project { columns } => {
                for column in columns {
                    if let super::ResidentRowCreateProjectionSource::IntegerProperty {
                        entity,
                        property_name,
                    } = column
                    {
                        include(*entity, *property_name)?;
                    }
                }
            }
            super::ResidentRowCreatePostStage::FilterIntegerModuloEquals {
                entity,
                property_name,
                ..
            }
            | super::ResidentRowCreatePostStage::SumInteger {
                entity,
                property_name,
            } => include(*entity, *property_name)?,
            super::ResidentRowCreatePostStage::Skip { .. }
            | super::ResidentRowCreatePostStage::Limit { .. } => {}
        }
    }
    for output in &continuation.outputs {
        if let super::ResidentRowCreateProjectionSource::IntegerProperty {
            entity,
            property_name,
        } = output.source
        {
            include(entity, property_name)?;
        }
    }
    Ok(selected)
}

fn push_metal_row_create_continuation_obligation(
    words: &mut Vec<u64>,
    obligation: super::ResidentExecutionObligation,
) -> Result<()> {
    let (scope, index) = match obligation.scope {
        super::ResidentObligationScope::Expression(index) => (2, u64::from(index)),
        super::ResidentObligationScope::PatternFinal => (5, 0),
        _ => {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal row CREATE continuation requires expression- or final-scoped obligations",
            ));
        }
    };
    if obligation.id == 0 {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal row CREATE continuation obligation has no execution identity",
        ));
    }
    words.extend([obligation.id, obligation.kind as u64, scope, index]);
    Ok(())
}

fn execute_metal_row_create_continuation(
    device: &Device,
    request: &ResidentRowMutationRequest,
    state: &MetalRowCreateDeviceState,
    cancellation: &CancellationToken,
) -> Result<
    Option<(
        Vec<super::ResidentRowCreateContinuationStageLineage>,
        super::ResidentRowCreateFinalRelation,
        Vec<ResidentExecutionReceipt>,
    )>,
> {
    let body = request
        .create_body()
        .ok_or_else(|| Error::internal("Metal row CREATE continuation lost its body"))?;
    let Some(continuation) = &body.program.continuation else {
        return Ok(None);
    };
    let Device::Metal(_) = device else {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "row CREATE continuation requires the selected Metal device",
        ));
    };
    ensure_not_cancelled(cancellation)?;
    let row_count = state.source_rows.elem_count();
    if row_count > u32::MAX as usize || continuation.outputs.len() != 1 {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal row CREATE continuation exceeds its compact row/output ABI",
        ));
    }

    let property_source = metal_row_create_continuation_property_source(continuation)?;
    let source_count = if request.input.is_empty() {
        1_usize
    } else {
        request.input.len()
    };
    let mut source_values = Vec::with_capacity(source_count);
    let mut source_validity = Vec::with_capacity(source_count);
    if let Some((entity, property_name)) = property_source {
        let source = body
            .program
            .created_property(entity, property_name)?
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal row CREATE continuation property source disappeared",
                )
            })?;
        for source_row in 0..source_count {
            let source_row = u64::try_from(source_row).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal row CREATE source row exceeds u64",
                )
            })?;
            match super::resident_row_create_property_value(
                &request.input,
                &body.program,
                source_row,
                source,
            )? {
                ScalarValue::Integer(value) => {
                    source_values.push(value);
                    source_validity.push(1_i64);
                }
                ScalarValue::Null => {
                    source_values.push(0_i64);
                    source_validity.push(0_i64);
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal row CREATE continuation admits only integer-or-null properties",
                    ));
                }
            }
        }
    } else {
        source_values.resize(source_count, 0_i64);
        source_validity.resize(source_count, 0_i64);
    }
    let source_values =
        Tensor::from_slice(&source_values, source_values.len(), device).map_err(candle_error)?;
    let source_validity = Tensor::from_slice(&source_validity, source_validity.len(), device)
        .map_err(candle_error)?;
    let values = device_index_select(&source_values, &state.source_rows, 0)?;
    let validity = device_index_select(&source_validity, &state.source_rows, 0)?;
    let input_word_count = row_count.checked_mul(2).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal row CREATE continuation input image overflows usize",
        )
    })?;
    let inputs = if input_word_count == 0 {
        Tensor::zeros(1, DType::I64, device).map_err(candle_error)?
    } else {
        Tensor::cat(&[&values, &validity], 0).map_err(candle_error)?
    };

    let mut program_words = Vec::with_capacity(
        continuation
            .stages
            .len()
            .saturating_mul(METAL_ROW_CREATE_CONTINUATION_STAGE_WORDS)
            .saturating_add(
                continuation
                    .stages
                    .len()
                    .saturating_add(1)
                    .saturating_mul(METAL_ROW_CREATE_CONTINUATION_OBLIGATION_WORDS),
            ),
    );
    for stage in &continuation.stages {
        let descriptor = match stage {
            super::ResidentRowCreatePostStage::Project { .. } => {
                [METAL_MUTATION_CONTINUATION_STAGE_PROJECT, 0, 0]
            }
            super::ResidentRowCreatePostStage::FilterIntegerModuloEquals {
                divisor,
                operand,
                ..
            } => [
                METAL_MUTATION_CONTINUATION_STAGE_FILTER_MODULO,
                u64::from_ne_bytes(divisor.to_ne_bytes()),
                u64::from_ne_bytes(operand.to_ne_bytes()),
            ],
            super::ResidentRowCreatePostStage::Skip { rows } => {
                [METAL_MUTATION_CONTINUATION_STAGE_SKIP, *rows, 0]
            }
            super::ResidentRowCreatePostStage::Limit { rows } => {
                [METAL_MUTATION_CONTINUATION_STAGE_LIMIT, *rows, 0]
            }
            super::ResidentRowCreatePostStage::SumInteger { .. } => {
                [METAL_MUTATION_CONTINUATION_STAGE_SUM, 0, 0]
            }
        };
        program_words.extend(descriptor);
    }
    for obligation in continuation
        .stage_obligations
        .iter()
        .copied()
        .chain(std::iter::once(body.program.final_relation_obligation))
    {
        push_metal_row_create_continuation_obligation(&mut program_words, obligation)?;
    }
    let program_words = program_words
        .into_iter()
        .map(|word| word as i64)
        .collect::<Vec<_>>();
    let program_packet =
        Tensor::from_slice(&program_words, program_words.len(), device).map_err(candle_error)?;
    let receipt_count = continuation.stages.len().checked_add(1).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal row CREATE continuation receipt count overflows usize",
        )
    })?;
    let output_capacity = row_count.max(1);
    let output_words = METAL_ROW_CREATE_CONTINUATION_HEADER_WORDS
        .checked_add(
            receipt_count
                .checked_mul(METAL_ROW_CREATE_CONTINUATION_RECEIPT_WORDS)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row CREATE continuation receipt image overflows usize",
                    )
                })?,
        )
        .and_then(|words| words.checked_add(continuation.stages.len()))
        .and_then(|words| {
            continuation
                .stages
                .len()
                .checked_mul(output_capacity)
                .and_then(|lineage| words.checked_add(lineage))
        })
        .and_then(|words| {
            output_capacity
                .checked_mul(4)
                .and_then(|relation| words.checked_add(relation))
        })
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row CREATE continuation output image overflows usize",
            )
        })?;
    let output_kind = match continuation.outputs[0].source {
        super::ResidentRowCreateProjectionSource::Entity(_) => {
            METAL_ROW_CREATE_CONTINUATION_OUTPUT_ENTITY
        }
        super::ResidentRowCreateProjectionSource::IntegerProperty { .. } => {
            METAL_ROW_CREATE_CONTINUATION_OUTPUT_INTEGER
        }
        super::ResidentRowCreateProjectionSource::AggregateInteger => {
            METAL_ROW_CREATE_CONTINUATION_OUTPUT_AGGREGATE
        }
    };
    let mut fingerprint = [0_u64; 4];
    for (index, chunk) in request.fingerprint.0.chunks_exact(8).enumerate() {
        fingerprint[index] = u64::from_le_bytes(chunk.try_into().map_err(|_| {
            Error::internal("row CREATE continuation fingerprint chunk changed width")
        })?);
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    {
        let arguments = MetalRowCreateContinuationArgs {
            execution_high: request.execution.high,
            execution_low: request.execution.low,
            fingerprint_0: fingerprint[0],
            fingerprint_1: fingerprint[1],
            fingerprint_2: fingerprint[2],
            fingerprint_3: fingerprint[3],
            input_word_count: input_word_count as u64,
            program_word_count: program_words.len() as u64,
            output_word_count: output_words as u64,
            row_count: row_count as u32,
            stage_count: continuation.stages.len() as u32,
            receipt_count: receipt_count as u32,
            output_capacity: output_capacity as u32,
            output_kind,
        };
        let encoded = inputs
            .apply_op2_no_bwd(
                &program_packet,
                &MetalRowCreateContinuation {
                    arguments,
                    input_storage_words: inputs.elem_count(),
                },
            )
            .map_err(candle_error)?;
        let words = encoded.to_vec1::<i64>().map_err(candle_error)?;
        ensure_not_cancelled(cancellation)?;
        return decode_metal_row_create_continuation(&words, request, row_count).map(Some);
    }
    #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
    {
        let _ = (
            inputs,
            program_packet,
            output_words,
            output_kind,
            fingerprint,
        );
        Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal row CREATE continuation kernels are unavailable on this build target",
        ))
    }
}

fn mutation_concat_i64(parts: &[Tensor], logical_words: usize, device: &Device) -> Result<Tensor> {
    let actual_words = parts.iter().map(Tensor::elem_count).sum::<usize>();
    if actual_words != logical_words || parts.iter().any(|part| part.dtype() != DType::I64) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation device input image has an invalid typed shape",
        ));
    }
    if logical_words == 0 {
        return Tensor::zeros(1, DType::I64, device).map_err(candle_error);
    }
    let parts = parts
        .iter()
        .filter(|part| part.elem_count() != 0)
        .collect::<Vec<_>>();
    if parts.is_empty() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation device input omitted a non-empty logical image",
        ));
    }
    Tensor::cat(&parts, 0).map_err(candle_error)
}

fn append_metal_mutation_read_set_inputs(
    parts: &mut Vec<Tensor>,
    read_set: &MetalMutationReadSet,
) -> Result<()> {
    for namespace in [&read_set.nodes, &read_set.relationships] {
        if namespace.dtype() != DType::U32 || namespace.rank() != 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation read set is not a canonical dense-row vector",
            ));
        }
        // Candle's generic Metal cast launcher cannot dispatch a zero-element grid. Omit an
        // empty namespace entirely; the explicit per-namespace counts keep the concatenated ABI
        // unambiguous and the kernel still proves the exact empty set.
        if namespace.elem_count() != 0 {
            parts.push(namespace.to_dtype(DType::I64).map_err(candle_error)?);
        }
    }
    Ok(())
}

const METAL_ROW_MATCH_MERGE_GRAPH_MAGIC: u64 = 0x4752_4352_4d4d_5232;
const METAL_ROW_MATCH_MERGE_PROGRAM_MAGIC: u64 = 0x5052_4352_4d4d_5232;
const METAL_ROW_MATCH_MERGE_PROGRAM_VERSION: u64 = 2;
const METAL_ROW_MATCH_MERGE_PROGRAM_HEADER_WORDS: usize = 32;
const METAL_ROW_MATCH_MERGE_ENTRY_WORDS: usize = 5;
const METAL_ROW_MATCH_MERGE_OUTPUT_MAGIC: u64 = 0x4f52_4352_4d4d_5232;
const METAL_ROW_MATCH_MERGE_OUTPUT_VERSION: u64 = 2;
const METAL_ROW_MATCH_MERGE_OUTPUT_HEADER_WORDS: usize = 48;
const METAL_ROW_MATCH_MERGE_RECEIPT_WORDS: usize = 9;
const METAL_ROW_MATCH_MERGE_OBLIGATION_WORDS: usize = 4;
const METAL_ROW_MATCH_MERGE_CONTROL_WORDS: usize = 16;
const METAL_ROW_MATCH_MERGE_SEALED: u64 = 0x5345_414c_4d4d_5232;

#[derive(Clone, Debug)]
struct EncodedMetalRowMatchMergeRelationshipProgram {
    words: Vec<u64>,
    map_offset_base: usize,
    entry_base: usize,
    key_byte_base: usize,
    key_byte_count: usize,
    match_key_offset: usize,
    match_key_length: usize,
    merge_key_offset: usize,
    merge_key_length: usize,
    obligation_base: usize,
}

#[derive(Clone, Copy, Debug)]
struct MetalRowMatchMergeRelationshipGraphLayout {
    word_count: usize,
    node_active_base: usize,
    node_layer_base: usize,
    node_id_base: usize,
    matched_label_base: usize,
    merged_label_base: usize,
    matched_value_base: usize,
    matched_validity_base: usize,
    merged_value_base: usize,
    merged_validity_base: usize,
    edge_active_base: usize,
    edge_layer_base: usize,
    edge_id_base: usize,
    edge_source_base: usize,
    edge_target_base: usize,
    edge_type_base: usize,
}

#[derive(Clone, Copy, Debug)]
struct MetalRowMatchMergeRelationshipOutputLayout {
    word_count: usize,
    pair_count: usize,
    receipt_base: usize,
    pair_active_base: usize,
    work_source_base: usize,
    matched_id_base: usize,
    matched_dense_base: usize,
    merged_id_base: usize,
    merged_dense_base: usize,
    merged_created_base: usize,
    relationship_id_base: usize,
    relationship_dense_base: usize,
    relationship_created_base: usize,
    node_create_base: usize,
    relationship_create_base: usize,
    node_dependency_base: usize,
    relationship_dependency_base: usize,
    sorted_value_base: usize,
    sorted_work_base: usize,
    control_base: usize,
}

fn validate_metal_row_match_merge_relationship_shape(
    request: &ResidentRowMutationRequest,
) -> Result<&super::ResidentRowMutationMatchMergeRelationshipProgram> {
    let program = request.match_merge_relationship.as_ref().ok_or_else(|| {
        Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal MATCH/MERGE row mutation requires its generalized program",
        )
    })?;
    if request.program.merge.keys.len() != 1
        || request.program.merge.labels.len() != 1
        || !request.program.sets.is_empty()
        || !request.program.outputs.is_empty()
        || program.matched_node.keys.len() != 1
        || program.matched_node.labels.len() != 1
        || !program.relationship.keys.is_empty()
        || program.relationship_type_names.len() != 1
        || program.relationship_type_tokens.len() != 1
        || program.relationship.relationship_type != 0
        || program.integer_outputs.len() != 1
        || program.integer_outputs[0].entity != request.program.merge.output_entity
        || program.integer_outputs[0].property_name != request.program.merge.keys[0].property_name
        || program.ascending_order.output != 0
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal MATCH/MERGE row mutation currently requires one MATCH label/key, one node-MERGE label/key, one property-free relationship type, and that merged integer key as its ascending output",
        ));
    }
    Ok(program)
}

fn encode_metal_row_match_merge_relationship_program(
    request: &ResidentRowMutationRequest,
) -> Result<EncodedMetalRowMatchMergeRelationshipProgram> {
    request.validate()?;
    let program = validate_metal_row_match_merge_relationship_shape(request)?;
    let match_key = program.matched_node.keys[0];
    let merge_key = request.program.merge.keys[0];
    let match_input_name = request
        .program
        .input_keys
        .get(usize::from(match_key.input_key))
        .ok_or_else(|| Error::internal("Metal MATCH input-key name disappeared"))?;
    let merge_input_name = request
        .program
        .input_keys
        .get(usize::from(merge_key.input_key))
        .ok_or_else(|| Error::internal("Metal node-MERGE input-key name disappeared"))?;

    let mut map_offsets = Vec::with_capacity(request.input.len().saturating_add(1));
    let mut entry_descriptors = Vec::new();
    let mut key_bytes = Vec::<u8>::new();
    let mut entry_count = 0_usize;
    map_offsets.push(0_u64);
    for row in &request.input {
        for (key, value) in &row.entries {
            let key_offset = key_bytes.len();
            key_bytes.extend_from_slice(key.as_bytes());
            // The specialized program evaluates only its two named integer inputs, but ordinary
            // Cypher maps may contain unrelated values of any canonical scalar shape. Preserve a
            // sealed type tag for every shape so those fields remain legal and a named non-integer
            // key reaches normal MATCH/MERGE type semantics instead of failing GPU admission.
            let (tag, bits) = match value {
                ScalarValue::Null => (0_u64, 0_u64),
                ScalarValue::Boolean(value) => (1_u64, u64::from(*value)),
                ScalarValue::Integer(value) => (2_u64, *value as u64),
                ScalarValue::Float(value) => (3_u64, value.0.to_bits()),
                ScalarValue::String(_) => (4_u64, 0_u64),
                ScalarValue::Bytes(_) => (5_u64, 0_u64),
                ScalarValue::Date(value) => (6_u64, *value as u64),
                ScalarValue::LocalTime(value) => (7_u64, *value as u64),
                ScalarValue::ZonedTime { .. } => (8_u64, 0_u64),
                ScalarValue::LocalDateTime { .. } => (9_u64, 0_u64),
                ScalarValue::ZonedDateTime { .. } => (10_u64, 0_u64),
                ScalarValue::Duration { .. } => (11_u64, 0_u64),
                ScalarValue::List(_) => (12_u64, 0_u64),
                ScalarValue::Map(_) => (13_u64, 0_u64),
            };
            entry_descriptors.extend([
                u64::try_from(key_offset).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal MATCH/MERGE key arena exceeds u64",
                    )
                })?,
                u64::try_from(key.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal MATCH/MERGE key width exceeds u64",
                    )
                })?,
                tag,
                bits,
                0,
            ]);
            entry_count = entry_count.checked_add(1).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal MATCH/MERGE map entry count overflow",
                )
            })?;
        }
        map_offsets.push(u64::try_from(entry_count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal MATCH/MERGE map entry count exceeds u64",
            )
        })?);
    }
    let match_key_offset = key_bytes.len();
    key_bytes.extend_from_slice(match_input_name.as_bytes());
    let merge_key_offset = key_bytes.len();
    key_bytes.extend_from_slice(merge_input_name.as_bytes());
    let obligations = request.obligations();
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal MATCH/MERGE program packet overflow",
        )
    };
    let map_offset_base = METAL_ROW_MATCH_MERGE_PROGRAM_HEADER_WORDS;
    let entry_base = map_offset_base
        .checked_add(map_offsets.len())
        .ok_or_else(overflow)?;
    let key_byte_base = entry_base
        .checked_add(entry_descriptors.len())
        .ok_or_else(overflow)?;
    let obligation_base = key_byte_base
        .checked_add(key_bytes.len())
        .ok_or_else(overflow)?;
    let word_count = obligation_base
        .checked_add(obligations.len().checked_mul(4).ok_or_else(overflow)?)
        .ok_or_else(overflow)?;
    let first_edge_id = request.first_edge_id.ok_or_else(|| {
        Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal MATCH/MERGE row mutation requires an edge-ID origin",
        )
    })?;
    let mut words = vec![0_u64; METAL_ROW_MATCH_MERGE_PROGRAM_HEADER_WORDS];
    words.extend(map_offsets);
    words.extend(entry_descriptors);
    words.extend(key_bytes.iter().map(|byte| u64::from(*byte)));
    for obligation in &obligations {
        words.extend(metal_delete_obligation_words(*obligation));
    }
    if words.len() != word_count {
        return Err(Error::internal(
            "Metal MATCH/MERGE program layout disagrees with its encoded packet",
        ));
    }
    words[0] = METAL_ROW_MATCH_MERGE_PROGRAM_MAGIC;
    words[1] = METAL_ROW_MATCH_MERGE_PROGRAM_VERSION;
    words[2] = request.input.len() as u64;
    words[3] = entry_count as u64;
    words[4] = map_offset_base as u64;
    words[5] = entry_base as u64;
    words[6] = key_byte_base as u64;
    words[7] = key_bytes.len() as u64;
    words[8] = match_key_offset as u64;
    words[9] = match_input_name.len() as u64;
    words[10] = merge_key_offset as u64;
    words[11] = merge_input_name.len() as u64;
    words[12] = obligations.len() as u64;
    words[13] = obligation_base as u64;
    words[14] = request.first_node_id;
    words[15] = first_edge_id;
    words[16] = u64::from(request.read_layers.bits());
    words[17] = request.maximum_output_rows as u64;
    words[18] = METAL_ROW_MATCH_MERGE_SEALED;
    Ok(EncodedMetalRowMatchMergeRelationshipProgram {
        words,
        map_offset_base,
        entry_base,
        key_byte_base,
        key_byte_count: key_bytes.len(),
        match_key_offset,
        match_key_length: match_input_name.len(),
        merge_key_offset,
        merge_key_length: merge_input_name.len(),
        obligation_base,
    })
}

fn metal_row_match_merge_relationship_graph_layout(
    resident: &CandleResident,
    request: &ResidentRowMutationRequest,
) -> Result<MetalRowMatchMergeRelationshipGraphLayout> {
    validate_metal_row_match_merge_relationship_shape(request)?;
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal MATCH/MERGE graph packet overflow",
        )
    };
    let mut cursor = 1_usize;
    let mut take = |count: usize| -> Result<usize> {
        let base = cursor;
        cursor = cursor.checked_add(count).ok_or_else(overflow)?;
        Ok(base)
    };
    let node_active_base = take(resident.node_count)?;
    let node_layer_base = take(resident.node_count)?;
    let node_id_base = take(resident.node_count)?;
    let matched_label_base = take(resident.node_count)?;
    let merged_label_base = take(resident.node_count)?;
    let matched_value_base = take(resident.node_count)?;
    let matched_validity_base = take(resident.node_count)?;
    let merged_value_base = take(resident.node_count)?;
    let merged_validity_base = take(resident.node_count)?;
    let edge_active_base = take(resident.edge_count)?;
    let edge_layer_base = take(resident.edge_count)?;
    let edge_id_base = take(resident.edge_count)?;
    let edge_source_base = take(resident.edge_count)?;
    let edge_target_base = take(resident.edge_count)?;
    let edge_type_base = take(resident.edge_count)?;
    Ok(MetalRowMatchMergeRelationshipGraphLayout {
        word_count: cursor,
        node_active_base,
        node_layer_base,
        node_id_base,
        matched_label_base,
        merged_label_base,
        matched_value_base,
        matched_validity_base,
        merged_value_base,
        merged_validity_base,
        edge_active_base,
        edge_layer_base,
        edge_id_base,
        edge_source_base,
        edge_target_base,
        edge_type_base,
    })
}

fn metal_row_match_merge_relationship_output_layout(
    resident: &CandleResident,
    request: &ResidentRowMutationRequest,
) -> Result<MetalRowMatchMergeRelationshipOutputLayout> {
    validate_metal_row_match_merge_relationship_shape(request)?;
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal MATCH/MERGE output packet overflow",
        )
    };
    let pair_count = request
        .input
        .len()
        .checked_mul(resident.node_count)
        .ok_or_else(overflow)?;
    let work = request.maximum_output_rows;
    let mut cursor = METAL_ROW_MATCH_MERGE_OUTPUT_HEADER_WORDS;
    let mut take = |count: usize| -> Result<usize> {
        let base = cursor;
        cursor = cursor.checked_add(count).ok_or_else(overflow)?;
        Ok(base)
    };
    let receipt_base = take(
        request
            .obligations()
            .len()
            .checked_mul(METAL_ROW_MATCH_MERGE_RECEIPT_WORDS)
            .ok_or_else(overflow)?,
    )?;
    let pair_active_base = take(pair_count)?;
    let work_source_base = take(work)?;
    let matched_id_base = take(work)?;
    let matched_dense_base = take(work)?;
    let merged_id_base = take(work)?;
    let merged_dense_base = take(work)?;
    let merged_created_base = take(work)?;
    let relationship_id_base = take(work)?;
    let relationship_dense_base = take(work)?;
    let relationship_created_base = take(work)?;
    let node_create_base = take(work)?;
    let relationship_create_base = take(work)?;
    let node_dependency_base = take(resident.node_count)?;
    let relationship_dependency_base = take(resident.edge_count)?;
    let sorted_value_base = take(work)?;
    let sorted_work_base = take(work)?;
    let control_base = take(METAL_ROW_MATCH_MERGE_CONTROL_WORDS)?;
    Ok(MetalRowMatchMergeRelationshipOutputLayout {
        word_count: cursor,
        pair_count,
        receipt_base,
        pair_active_base,
        work_source_base,
        matched_id_base,
        matched_dense_base,
        merged_id_base,
        merged_dense_base,
        merged_created_base,
        relationship_id_base,
        relationship_dense_base,
        relationship_created_base,
        node_create_base,
        relationship_create_base,
        node_dependency_base,
        relationship_dependency_base,
        sorted_value_base,
        sorted_work_base,
        control_base,
    })
}

fn append_metal_row_match_merge_integer_lane(
    parts: &mut Vec<Tensor>,
    resident: &CandleResident,
    request: &ResidentRowMutationRequest,
    property_name: u16,
    device: &Device,
    label: &'static str,
) -> Result<()> {
    let property = request
        .program
        .property_tokens
        .get(usize::from(property_name))
        .copied()
        .flatten();
    if let Some(property) = property {
        if resident.mixed_nodes.contains_key(&property) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                format!("{label} is mixed-typed and needs a native tagged value lane"),
            ));
        }
        if let Some(column) = resident.integer_nodes.get(&property) {
            if column.rows != resident.node_count {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    format!("{label} has the wrong resident row count"),
                ));
            }
            append_metal_nullable_i64(
                parts,
                column.values.as_ref(),
                resident.node_count,
                DType::I64,
                label,
            )?;
            append_metal_nullable_i64(
                parts,
                column.validity.as_ref(),
                resident.node_count,
                DType::U8,
                label,
            )?;
            return Ok(());
        }
    }
    parts.push(Tensor::zeros(resident.node_count, DType::I64, device).map_err(candle_error)?);
    parts.push(Tensor::zeros(resident.node_count, DType::I64, device).map_err(candle_error)?);
    Ok(())
}

fn decode_metal_row_match_merge_relationship_result(
    words: &[i64],
    request: &ResidentRowMutationRequest,
    encoded: &EncodedMetalRowMatchMergeRelationshipProgram,
    graph: MetalRowMatchMergeRelationshipGraphLayout,
    output: MetalRowMatchMergeRelationshipOutputLayout,
) -> Result<ResidentRowMutationResult> {
    if words.len() != output.word_count {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE output packet has the wrong length",
        ));
    }
    let program = validate_metal_row_match_merge_relationship_shape(request)?;
    let obligations = request.obligations();
    let word = |index: usize| words[index] as u64;
    let project = request.generation.project.0.as_u128();
    let catalog = metal_nullable_relation_hash_words(request.generation.catalog_generation);
    let fingerprint = metal_nullable_relation_hash_words(request.fingerprint.0);
    let relationship_token = program
        .relationship_type_tokens
        .get(usize::from(program.relationship.relationship_type))
        .copied()
        .flatten();
    if word(0) != METAL_ROW_MATCH_MERGE_OUTPUT_MAGIC
        || word(1) != METAL_ROW_MATCH_MERGE_OUTPUT_VERSION
        || word(3) != ResidentDeviceCompletion::Metal as u64
        || word(4) != request.execution.high
        || word(5) != request.execution.low
        || word(6) != (project >> 64) as u64
        || word(7) != project as u64
        || word(8) != request.generation.bookmark.term
        || word(9) != request.generation.bookmark.index
        || word(10) != request.generation.graph_revision
        || word(11) != request.generation.layout_version
        || [word(12), word(13), word(14), word(15)] != fingerprint
        || word(16) != request.input.len() as u64
        || word(20) != obligations.len() as u64
        || word(21) != encoded.words.len() as u64
        || word(22) != graph.word_count as u64
        || word(23) != output.word_count as u64
        || word(24) != request.first_node_id
        || word(25) != request.first_edge_id.unwrap_or(0)
        || word(26) != METAL_ROW_MATCH_MERGE_SEALED
        || word(29) != graph.node_layer_base.saturating_sub(graph.node_active_base) as u64
        || word(30) != graph.edge_layer_base.saturating_sub(graph.edge_active_base) as u64
        || word(31) != request.maximum_output_rows as u64
        || [word(32), word(33), word(34), word(35)] != catalog
        || word(36) != u64::from(relationship_token.is_some())
        || word(37) != relationship_token.map_or(0, |token| token.0)
        || (38..METAL_ROW_MATCH_MERGE_OUTPUT_HEADER_WORDS).any(|index| word(index) != 0)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE output forged its generation, fingerprint, or packet provenance",
        ));
    }
    let status_word = word(2);
    match status_word {
        5 => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE kernels rejected a corrupt graph, program, or output packet",
            ));
        }
        0..=4 | 6..=7 => {}
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE kernel returned an unknown status",
            ));
        }
    }
    let work_count = usize::try_from(word(17)).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE work cardinality exceeds host address space",
        )
    })?;
    if (status_word == 6 && work_count <= request.maximum_output_rows)
        || (status_word != 6 && work_count > request.maximum_output_rows)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE work cardinality contradicts its sealed status or capacity",
        ));
    }
    let mut receipts = Vec::with_capacity(obligations.len());
    for (index, expected_obligation) in obligations.iter().enumerate() {
        let base = output.receipt_base + index * METAL_ROW_MATCH_MERGE_RECEIPT_WORDS;
        if word(base) != request.execution.high
            || word(base + 1) != request.execution.low
            || word(base + 8) != ResidentDeviceCompletion::Metal as u64
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE receipt forged execution or completion provenance",
            ));
        }
        let obligation = decode_metal_delete_obligation([
            word(base + 2),
            word(base + 3),
            word(base + 4),
            word(base + 5),
        ])?;
        if &obligation != expected_obligation {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE receipt substituted an execution obligation",
            ));
        }
        receipts.push(ResidentExecutionReceipt {
            execution: request.execution,
            obligation,
            input_cardinality: word(base + 6),
            output_cardinality: word(base + 7),
            completion: ResidentDeviceCompletion::Metal,
        });
    }
    let failed_receipt = match status_word {
        0 => None,
        1..=3 => Some(2_usize),
        4 => Some(4),
        6 => Some(1),
        7 => match word(28) {
            0 => Some(3),
            1 => Some(5),
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal MATCH/MERGE identity conflict named an invalid entity kind",
                ));
            }
        },
        _ => unreachable!("corrupt and unknown statuses returned above"),
    };
    let source_count = request.input.len() as u64;
    for (index, receipt) in receipts.iter().enumerate() {
        let (expected_input, expected_output) = match failed_receipt {
            None if index == 0 => (1, source_count),
            None if index == 1 => (source_count, work_count as u64),
            None => (work_count as u64, work_count as u64),
            Some(failed) if index == 0 => (1, if failed == 0 { 0 } else { source_count }),
            Some(failed) if index == 1 => (
                if failed == 0 { 0 } else { source_count },
                if failed > 1 { work_count as u64 } else { 0 },
            ),
            Some(failed) if failed >= 2 && index < failed => (work_count as u64, work_count as u64),
            Some(failed) if index == failed => (work_count as u64, 0),
            Some(_) => (0, 0),
        };
        if receipt.input_cardinality != expected_input
            || receipt.output_cardinality != expected_output
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE receipt cardinality contradicts its sealed status",
            ));
        }
    }
    if status_word != 0 && (word(18) != 0 || word(19) != 0) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "failed Metal MATCH/MERGE mutation exposed intents or dependencies",
        ));
    }
    let mut pair_active_count = 0_u64;
    for pair in 0..output.pair_count {
        match word(output.pair_active_base + pair) {
            0 => {}
            1 => {
                pair_active_count = pair_active_count.checked_add(1).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal MATCH/MERGE pair cardinality overflowed",
                    )
                })?;
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal MATCH/MERGE pair bitmap contains a non-boolean flag",
                ));
            }
        }
    }
    if pair_active_count != word(17) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE pair bitmap contradicts its sealed work cardinality",
        ));
    }
    if status_word == 6 {
        if word(28) != work_count as u64 || (source_count != 0 && word(27) >= source_count) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE output-budget failure has impossible lineage",
            ));
        }
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal MATCH expansion exceeded the query's explicit output-byte admission budget",
        ));
    }
    if status_word == 7 {
        if word(27) >= work_count as u64 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE identity conflict has impossible work lineage",
            ));
        }
        let kind = if word(28) == 0 {
            "node"
        } else {
            "relationship"
        };
        return Err(Error::new(
            ErrorCode::TransactionConflict,
            format!("Metal MATCH/MERGE candidate {kind} identity already exists"),
        ));
    }
    let status = match status_word {
        0 => ResidentRowMutationStatus::Success,
        1 => ResidentRowMutationStatus::NullMergeKey {
            source_row: word(27),
            key: request.program.merge.keys[0].input_key,
        },
        2 => ResidentRowMutationStatus::UnsupportedMergeKey {
            source_row: word(27),
            key: request.program.merge.keys[0].input_key,
        },
        3 => ResidentRowMutationStatus::MultipleMatches {
            source_row: word(27),
            matches: word(28),
        },
        4 => ResidentRowMutationStatus::MultipleRelationshipMatches {
            work_row: word(27),
            matches: word(28),
        },
        _ => unreachable!("direct error statuses returned above"),
    };
    if !matches!(status, ResidentRowMutationStatus::Success) {
        return Ok(ResidentRowMutationResult::completed(
            request,
            ResidentDeviceCompletion::Metal,
            status,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            receipts,
        ));
    }

    let node_count = graph.node_layer_base.saturating_sub(graph.node_active_base);
    let mut expected_pairs = Vec::with_capacity(work_count);
    for pair in 0..output.pair_count {
        let flag = word(output.pair_active_base + pair);
        if flag > 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE pair bitmap contains a non-boolean flag",
            ));
        }
        if flag == 1 {
            if node_count == 0 {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal MATCH/MERGE pair bitmap selected a node from an empty graph",
                ));
            }
            expected_pairs.push((pair / node_count, pair % node_count));
        }
    }
    if expected_pairs.len() != work_count {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE compacted work cardinality disagrees with its pair bitmap",
        ));
    }

    let mut work_rows = Vec::with_capacity(work_count);
    let mut node_create_flags = Vec::with_capacity(work_count);
    let mut relationship_create_flags = Vec::with_capacity(work_count);
    for work in 0..work_count {
        let source_row = word(output.work_source_base + work);
        let matched_dense = word(output.matched_dense_base + work);
        let merged_dense = word(output.merged_dense_base + work);
        let merged_created = word(output.merged_created_base + work);
        let relationship_dense = word(output.relationship_dense_base + work);
        let relationship_created = word(output.relationship_created_base + work);
        let matched_node = ResidentRowMutationTarget {
            target_id: word(output.matched_id_base + work),
            dense_row: if matched_dense == 0 {
                None
            } else {
                Some(u32::try_from(matched_dense - 1).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal MATCH dense node exceeds u32",
                    )
                })?)
            },
            created_by: None,
        };
        let merged_node = ResidentRowMutationTarget {
            target_id: word(output.merged_id_base + work),
            dense_row: if merged_dense == 0 {
                None
            } else {
                Some(u32::try_from(merged_dense - 1).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal node-MERGE dense target exceeds u32",
                    )
                })?)
            },
            created_by: if merged_created == 0 {
                None
            } else {
                Some(merged_created - 1)
            },
        };
        let merged_relationship = ResidentRowMutationTarget {
            target_id: word(output.relationship_id_base + work),
            dense_row: if relationship_dense == 0 {
                None
            } else {
                Some(u32::try_from(relationship_dense - 1).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal relationship-MERGE dense target exceeds u32",
                    )
                })?)
            },
            created_by: if relationship_created == 0 {
                None
            } else {
                Some(relationship_created - 1)
            },
        };
        let (expected_source, expected_node) = expected_pairs[work];
        if source_row >= request.input.len() as u64
            || usize::try_from(source_row).ok() != Some(expected_source)
            || usize::try_from(matched_dense).ok() != expected_node.checked_add(1)
            || matched_node.target_id == 0
            || matched_node.dense_row.is_none()
            || merged_node.target_id == 0
            || merged_relationship.target_id == 0
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE work row contains an invalid lineage or entity target",
            ));
        }
        let work_row = u64::try_from(work).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE work row exceeds u64",
            )
        })?;
        work_rows.push(ResidentRowMutationWorkRow {
            work_row,
            source_row,
            matched_node,
            merged_node,
            merged_relationship,
        });
        let node_create = word(output.node_create_base + work);
        let relationship_create = word(output.relationship_create_base + work);
        if node_create > 1 || relationship_create > 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE intent flag is not boolean",
            ));
        }
        node_create_flags.push(node_create == 1);
        relationship_create_flags.push(relationship_create == 1);
    }

    let mut read_dependencies = Vec::new();
    for dense in 0..graph.node_layer_base.saturating_sub(graph.node_active_base) {
        let flag = word(output.node_dependency_base + dense);
        if flag > 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE node dependency flag is not boolean",
            ));
        }
        if flag == 1 {
            read_dependencies.push(ResidentMutationReadDependency::Node(
                u32::try_from(dense).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal MATCH/MERGE node dependency exceeds u32",
                    )
                })?,
            ));
        }
    }
    for dense in 0..graph.edge_layer_base.saturating_sub(graph.edge_active_base) {
        let flag = word(output.relationship_dependency_base + dense);
        if flag > 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE relationship dependency flag is not boolean",
            ));
        }
        if flag == 1 {
            read_dependencies.push(ResidentMutationReadDependency::Relationship(
                u32::try_from(dense).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal MATCH/MERGE relationship dependency exceeds u32",
                    )
                })?,
            ));
        }
    }
    if read_dependencies.len() as u64 != word(19) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE dependencies disagree with their sealed count",
        ));
    }
    let mut values = Vec::with_capacity(work_count);
    let mut sorted_work_rows = Vec::with_capacity(work_count);
    let mut merge_values_by_work = vec![None; work_count];
    let mut previous_order = None::<(i64, u64)>;
    for position in 0..work_count {
        let value = words[output.sorted_value_base + position];
        let reference = word(output.sorted_work_base + position);
        if reference == 0 || reference > work_count as u64 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE sorted lineage contains an invalid work reference",
            ));
        }
        let work = usize::try_from(reference - 1).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE sorted work reference exceeds host address space",
            )
        })?;
        if merge_values_by_work[work].replace(value).is_some() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE sorted lineage repeats one work row",
            ));
        }
        if previous_order.is_some_and(|(previous_value, previous_work)| {
            value < previous_value || (value == previous_value && reference - 1 < previous_work)
        }) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal MATCH/MERGE integer output is not in stable ascending order",
            ));
        }
        previous_order = Some((value, reference - 1));
        values.push(value);
        sorted_work_rows.push(reference - 1);
    }
    if merge_values_by_work.iter().any(Option::is_none) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE sorted lineage omitted a work row",
        ));
    }

    // Independently prove statement-local MERGE leader identity from the sealed GPU relation.
    // This catches accidental collapse of different node keys or relationship endpoints even if
    // every individual target field is otherwise in range.
    for (work, row) in work_rows.iter().enumerate() {
        match row.merged_node.created_by {
            None => {
                if row.merged_node.dense_row.is_none() || node_create_flags[work] {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal node-MERGE target is neither an immutable row nor a sealed leader",
                    ));
                }
            }
            Some(leader) => {
                let leader = usize::try_from(leader).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal node-MERGE leader exceeds host address space",
                    )
                })?;
                let expected_id = request
                    .first_node_id
                    .checked_add(leader as u64)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal node-MERGE leader identity overflowed",
                        )
                    })?;
                if leader > work
                    || row.merged_node.dense_row.is_some()
                    || expected_id != row.merged_node.target_id
                    || work_rows[leader].merged_node.created_by != Some(leader as u64)
                    || work_rows[leader].merged_node.target_id != row.merged_node.target_id
                    || merge_values_by_work[leader] != merge_values_by_work[work]
                    || !node_create_flags[leader]
                    || node_create_flags[work] != (leader == work)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal node-MERGE rows disagree about their statement-local key leader",
                    ));
                }
            }
        }
        match row.merged_relationship.created_by {
            None => {
                if row.merged_relationship.dense_row.is_none() || relationship_create_flags[work] {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal relationship-MERGE target is neither immutable nor a sealed leader",
                    ));
                }
            }
            Some(leader) => {
                let leader = usize::try_from(leader).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal relationship-MERGE leader exceeds host address space",
                    )
                })?;
                let expected_id = request
                    .first_edge_id
                    .and_then(|first| first.checked_add(leader as u64))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal relationship-MERGE leader identity overflowed",
                        )
                    })?;
                if leader > work
                    || row.merged_relationship.dense_row.is_some()
                    || expected_id != row.merged_relationship.target_id
                    || work_rows[leader].merged_relationship.created_by != Some(leader as u64)
                    || work_rows[leader].merged_relationship.target_id
                        != row.merged_relationship.target_id
                    || work_rows[leader].merged_node.target_id != row.merged_node.target_id
                    || work_rows[leader].matched_node.target_id != row.matched_node.target_id
                    || !relationship_create_flags[leader]
                    || relationship_create_flags[work] != (leader == work)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal relationship-MERGE rows disagree about their endpoint leader",
                    ));
                }
            }
        }
    }

    let merge_key = request.program.merge.keys[0];
    let mut intents = Vec::new();
    for (work, row) in work_rows.iter().enumerate() {
        let work_row = work as u64;
        if node_create_flags[work] {
            let merge_value = merge_values_by_work[work].ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal node-CREATE leader omitted its sealed integer key",
                )
            })?;
            intents.push(ResidentRowMutationWorkIntent {
                work_row,
                source_row: row.source_row,
                command: 0,
                target_id: row.merged_node.target_id,
                action: ResidentRowMutationWorkIntentAction::CreateNode {
                    labels: request.program.merge.labels.clone(),
                    properties: vec![super::ResidentMutationIntentEntry {
                        property_name: merge_key.property_name,
                        value: ScalarValue::Integer(merge_value),
                    }],
                },
            });
        }
        if relationship_create_flags[work] {
            intents.push(ResidentRowMutationWorkIntent {
                work_row,
                source_row: row.source_row,
                command: 1,
                target_id: row.merged_relationship.target_id,
                action: ResidentRowMutationWorkIntentAction::CreateRelationship {
                    relationship_type: program.relationship.relationship_type,
                    source_node_id: row.merged_node.target_id,
                    target_node_id: row.matched_node.target_id,
                    properties: Vec::new(),
                },
            });
        }
    }
    if intents.len() as u64 != word(18) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal MATCH/MERGE intents disagree with their sealed count",
        ));
    }
    let columns = vec![ResidentRowMutationIntegerColumn {
        output: 0,
        values,
        validity: vec![1; work_count],
        work_rows: sorted_work_rows,
    }];
    Ok(
        ResidentRowMutationResult::completed_match_merge_relationship(
            request,
            ResidentDeviceCompletion::Metal,
            ResidentRowMutationStatus::Success,
            intents,
            work_rows,
            read_dependencies,
            columns,
            receipts,
        ),
    )
}

const METAL_ROW_MUTATION_GRAPH_MAGIC: u64 = 0x4752_4352_4f57_4d31;
const METAL_ROW_MUTATION_PROGRAM_MAGIC: u64 = 0x5052_4352_4f57_4d31;
const METAL_ROW_MUTATION_PROGRAM_VERSION: u64 = 1;
const METAL_ROW_MUTATION_PROGRAM_HEADER_WORDS: usize = 32;
const METAL_ROW_MUTATION_ENTRY_WORDS: usize = 5;
const METAL_ROW_MUTATION_OUTPUT_MAGIC: u64 = 0x4f52_4352_4f57_4d31;
const METAL_ROW_MUTATION_OUTPUT_VERSION: u64 = 1;
const METAL_ROW_MUTATION_OUTPUT_HEADER_WORDS: usize = 40;
const METAL_ROW_MUTATION_RECEIPT_WORDS: usize = 9;
const METAL_ROW_MUTATION_CONTROL_WORDS: usize = 8;
const METAL_ROW_MUTATION_SEALED: u64 = 0x5345_414c_4544_524d;

#[derive(Clone, Debug)]
struct EncodedMetalRowMutationProgram {
    words: Vec<u64>,
    entry_values: Vec<ScalarValue>,
    map_offset_base: usize,
    entry_base: usize,
    key_byte_base: usize,
    key_byte_count: usize,
    value_byte_base: usize,
    value_byte_count: usize,
    obligation_base: usize,
    output_source_base: usize,
}

#[derive(Clone, Copy, Debug)]
struct MetalRowMutationGraphLayout {
    word_count: usize,
    node_active_base: usize,
    node_layer_base: usize,
    node_id_base: usize,
    label_base: usize,
    property_value_base: usize,
    property_validity_base: usize,
    dictionary_offset_base: usize,
    dictionary_offset_count: usize,
    dictionary_byte_base: usize,
    dictionary_byte_count: usize,
}

#[derive(Clone, Copy, Debug)]
struct MetalRowMutationOutputLayout {
    word_count: usize,
    receipt_base: usize,
    target_id_base: usize,
    target_dense_base: usize,
    target_created_base: usize,
    merge_ref_base: usize,
    set_ref_base: usize,
    row_status_base: usize,
    row_match_base: usize,
    dependency_base: usize,
    final_ref_base: usize,
    create_base: usize,
    control_base: usize,
}

fn encode_metal_row_mutation_program(
    request: &ResidentRowMutationRequest,
) -> Result<EncodedMetalRowMutationProgram> {
    request.validate()?;
    if request.program.merge.keys.len() != 1 || request.program.sets.len() != 1 {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal row mutation currently requires one node MERGE key and one ordered SET",
        ));
    }
    let merge_key = request.program.merge.keys[0];
    let set = request.program.sets[0];
    if set.property_name == merge_key.property_name {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal row mutation does not yet admit SET of its MERGE key; ordered key-overlay execution is required",
        ));
    }
    let merge_input_name = request
        .program
        .input_keys
        .get(usize::from(merge_key.input_key))
        .ok_or_else(|| Error::internal("Metal row MERGE input-key name disappeared"))?;
    let set_input_name = request
        .program
        .input_keys
        .get(usize::from(set.input_key))
        .ok_or_else(|| Error::internal("Metal row SET input-key name disappeared"))?;

    let mut map_offsets = Vec::with_capacity(request.input.len().saturating_add(1));
    let mut entry_descriptors = Vec::new();
    let mut entry_values = Vec::new();
    let mut key_bytes = Vec::<u8>::new();
    let mut value_bytes = Vec::<u8>::new();
    map_offsets.push(0_u64);
    for row in &request.input {
        for (key, value) in &row.entries {
            let key_offset = key_bytes.len();
            key_bytes.extend_from_slice(key.as_bytes());
            let (tag, value_offset, value_length) = match value {
                ScalarValue::Null => (0_u64, value_bytes.len(), 0_usize),
                ScalarValue::String(value) => {
                    let offset = value_bytes.len();
                    value_bytes.extend_from_slice(value.as_bytes());
                    (1, offset, value.len())
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal row mutation currently requires NULL or STRING map fields",
                    ));
                }
            };
            entry_descriptors.extend([
                u64::try_from(key_offset).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row-mutation key arena exceeds u64",
                    )
                })?,
                u64::try_from(key.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row-mutation key width exceeds u64",
                    )
                })?,
                tag,
                u64::try_from(value_offset).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row-mutation value arena exceeds u64",
                    )
                })?,
                u64::try_from(value_length).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal row-mutation value width exceeds u64",
                    )
                })?,
            ]);
            entry_values.push(value.clone());
        }
        map_offsets.push(u64::try_from(entry_values.len()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row-mutation map entry count exceeds u64",
            )
        })?);
    }
    let merge_key_offset = key_bytes.len();
    key_bytes.extend_from_slice(merge_input_name.as_bytes());
    let set_key_offset = key_bytes.len();
    key_bytes.extend_from_slice(set_input_name.as_bytes());

    let output_sources = request
        .program
        .outputs
        .iter()
        .map(|output| {
            if output.property_name == set.property_name {
                Ok(1_u64)
            } else if output.property_name == merge_key.property_name {
                Ok(0_u64)
            } else {
                Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "Metal row-mutation output is not supplied by MERGE or the final SET",
                ))
            }
        })
        .collect::<Result<Vec<_>>>()?;
    let obligations = request.obligations();
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal row-mutation program packet overflow",
        )
    };
    let map_offset_base = METAL_ROW_MUTATION_PROGRAM_HEADER_WORDS;
    let entry_base = map_offset_base
        .checked_add(map_offsets.len())
        .ok_or_else(overflow)?;
    let key_byte_base = entry_base
        .checked_add(entry_descriptors.len())
        .ok_or_else(overflow)?;
    let value_byte_base = key_byte_base
        .checked_add(key_bytes.len())
        .ok_or_else(overflow)?;
    let obligation_base = value_byte_base
        .checked_add(value_bytes.len())
        .ok_or_else(overflow)?;
    let output_source_base = obligation_base
        .checked_add(obligations.len().checked_mul(4).ok_or_else(overflow)?)
        .ok_or_else(overflow)?;
    let word_count = output_source_base
        .checked_add(output_sources.len())
        .ok_or_else(overflow)?;
    let mut words = vec![0_u64; METAL_ROW_MUTATION_PROGRAM_HEADER_WORDS];
    words.extend(map_offsets);
    words.extend(entry_descriptors);
    words.extend(key_bytes.iter().map(|byte| u64::from(*byte)));
    words.extend(value_bytes.iter().map(|byte| u64::from(*byte)));
    for obligation in &obligations {
        words.extend(metal_delete_obligation_words(*obligation));
    }
    words.extend(&output_sources);
    if words.len() != word_count {
        return Err(Error::internal(
            "Metal row-mutation program layout disagrees with its encoded packet",
        ));
    }
    words[0] = METAL_ROW_MUTATION_PROGRAM_MAGIC;
    words[1] = METAL_ROW_MUTATION_PROGRAM_VERSION;
    words[2] = request.input.len() as u64;
    words[3] = entry_values.len() as u64;
    words[4] = map_offset_base as u64;
    words[5] = entry_base as u64;
    words[6] = key_byte_base as u64;
    words[7] = key_bytes.len() as u64;
    words[8] = value_byte_base as u64;
    words[9] = value_bytes.len() as u64;
    words[10] = merge_key_offset as u64;
    words[11] = merge_input_name.len() as u64;
    words[12] = set_key_offset as u64;
    words[13] = set_input_name.len() as u64;
    words[14] = output_sources.len() as u64;
    words[15] = obligations.len() as u64;
    words[16] = obligation_base as u64;
    words[17] = output_source_base as u64;
    words[18] = request.first_node_id;
    words[19] = u64::from(request.read_layers.bits());
    words[20] = request.program.merge.labels.len() as u64;
    words[21] = 1;
    words[22] = METAL_ROW_MUTATION_ENTRY_WORDS as u64;
    words[31] = METAL_ROW_MUTATION_SEALED;
    Ok(EncodedMetalRowMutationProgram {
        words,
        entry_values,
        map_offset_base,
        entry_base,
        key_byte_base,
        key_byte_count: key_bytes.len(),
        value_byte_base,
        value_byte_count: value_bytes.len(),
        obligation_base,
        output_source_base,
    })
}

fn metal_row_mutation_graph_layout(
    resident: &CandleResident,
    request: &ResidentRowMutationRequest,
) -> Result<MetalRowMutationGraphLayout> {
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal row-mutation graph packet overflow",
        )
    };
    let nodes = resident.node_count;
    let mut cursor = 1_usize;
    let mut take = |count: usize| -> Result<usize> {
        let base = cursor;
        cursor = cursor.checked_add(count).ok_or_else(overflow)?;
        Ok(base)
    };
    let node_active_base = take(nodes)?;
    let node_layer_base = take(nodes)?;
    let node_id_base = take(nodes)?;
    let label_base = take(
        request
            .program
            .merge
            .labels
            .len()
            .checked_mul(nodes)
            .ok_or_else(overflow)?,
    )?;
    let property_value_base = take(nodes)?;
    let property_validity_base = take(nodes)?;
    let dictionary_offset_count = resident.node_string_dictionary.offsets.elem_count();
    let dictionary_offset_base = take(dictionary_offset_count)?;
    let dictionary_byte_count = resident
        .node_string_dictionary
        .bytes
        .as_ref()
        .map_or(0, Tensor::elem_count);
    let dictionary_byte_base = take(dictionary_byte_count)?;
    Ok(MetalRowMutationGraphLayout {
        word_count: cursor,
        node_active_base,
        node_layer_base,
        node_id_base,
        label_base,
        property_value_base,
        property_validity_base,
        dictionary_offset_base,
        dictionary_offset_count,
        dictionary_byte_base,
        dictionary_byte_count,
    })
}

fn metal_row_mutation_output_layout(
    resident: &CandleResident,
    request: &ResidentRowMutationRequest,
) -> Result<MetalRowMutationOutputLayout> {
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal row-mutation output packet overflow",
        )
    };
    let rows = request.input.len();
    let mut cursor = METAL_ROW_MUTATION_OUTPUT_HEADER_WORDS;
    let mut take = |count: usize| -> Result<usize> {
        let base = cursor;
        cursor = cursor.checked_add(count).ok_or_else(overflow)?;
        Ok(base)
    };
    let receipt_base = take(
        request
            .obligations()
            .len()
            .checked_mul(METAL_ROW_MUTATION_RECEIPT_WORDS)
            .ok_or_else(overflow)?,
    )?;
    let target_id_base = take(rows)?;
    let target_dense_base = take(rows)?;
    let target_created_base = take(rows)?;
    let merge_ref_base = take(rows)?;
    let set_ref_base = take(rows)?;
    let row_status_base = take(rows)?;
    let row_match_base = take(rows)?;
    let dependency_base = take(resident.node_count)?;
    let final_ref_base = take(
        rows.checked_mul(request.program.outputs.len())
            .ok_or_else(overflow)?,
    )?;
    let create_base = take(rows)?;
    let control_base = take(METAL_ROW_MUTATION_CONTROL_WORDS)?;
    Ok(MetalRowMutationOutputLayout {
        word_count: cursor,
        receipt_base,
        target_id_base,
        target_dense_base,
        target_created_base,
        merge_ref_base,
        set_ref_base,
        row_status_base,
        row_match_base,
        dependency_base,
        final_ref_base,
        create_base,
        control_base,
    })
}

fn metal_row_mutation_entry_value(
    encoded: &EncodedMetalRowMutationProgram,
    reference: u64,
) -> Result<ScalarValue> {
    if reference == 0 {
        return Ok(ScalarValue::Null);
    }
    let index = usize::try_from(reference - 1).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal row-mutation entry reference exceeds host address space",
        )
    })?;
    encoded.entry_values.get(index).cloned().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal row-mutation entry reference is outside the raw input map",
        )
    })
}

fn decode_metal_row_mutation_result(
    words: &[i64],
    request: &ResidentRowMutationRequest,
    encoded: &EncodedMetalRowMutationProgram,
    graph: MetalRowMutationGraphLayout,
    output: MetalRowMutationOutputLayout,
) -> Result<ResidentRowMutationResult> {
    if words.len() != output.word_count {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal row-mutation output packet has the wrong length",
        ));
    }
    let word = |index: usize| words[index] as u64;
    let project = request.generation.project.0.as_u128();
    let catalog = metal_nullable_relation_hash_words(request.generation.catalog_generation);
    let fingerprint = metal_nullable_relation_hash_words(request.fingerprint.0);
    if word(0) != METAL_ROW_MUTATION_OUTPUT_MAGIC
        || word(1) != METAL_ROW_MUTATION_OUTPUT_VERSION
        || word(3) != ResidentDeviceCompletion::Metal as u64
        || word(4) != request.execution.high
        || word(5) != request.execution.low
        || word(6) != (project >> 64) as u64
        || word(7) != project as u64
        || word(8) != request.generation.bookmark.term
        || word(9) != request.generation.bookmark.index
        || word(10) != request.generation.graph_revision
        || word(11) != request.generation.layout_version
        || [word(12), word(13), word(14), word(15)] != fingerprint
        || word(16) != request.input.len() as u64
        || word(19) != request.obligations().len() as u64
        || word(20) != request.program.outputs.len() as u64
        || word(21) != encoded.words.len() as u64
        || word(22) != graph.word_count as u64
        || word(23) != output.word_count as u64
        || word(24) != request.first_node_id
        || word(25) != u64::from(request.read_layers.bits())
        || word(26) != METAL_ROW_MUTATION_SEALED
        || word(29) != graph.node_layer_base.saturating_sub(graph.node_active_base) as u64
        || word(30) != request.program.merge.labels.len() as u64
        || word(31) != request.program.sets.len() as u64
        || [word(32), word(33), word(34), word(35)] != catalog
        || (36..METAL_ROW_MUTATION_OUTPUT_HEADER_WORDS).any(|index| word(index) != 0)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal row-mutation output has forged generation, fingerprint, or packet provenance",
        ));
    }
    let mut receipts = Vec::with_capacity(request.obligations().len());
    for index in 0..request.obligations().len() {
        let base = output.receipt_base + index * METAL_ROW_MUTATION_RECEIPT_WORDS;
        if word(base) != request.execution.high
            || word(base + 1) != request.execution.low
            || word(base + 8) != ResidentDeviceCompletion::Metal as u64
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal row-mutation receipt has forged execution or completion provenance",
            ));
        }
        receipts.push(ResidentExecutionReceipt {
            execution: request.execution,
            obligation: decode_metal_delete_obligation([
                word(base + 2),
                word(base + 3),
                word(base + 4),
                word(base + 5),
            ])?,
            input_cardinality: word(base + 6),
            output_cardinality: word(base + 7),
            completion: ResidentDeviceCompletion::Metal,
        });
    }
    let status = match word(2) {
        0 => ResidentRowMutationStatus::Success,
        1 => ResidentRowMutationStatus::NullMergeKey {
            source_row: word(27),
            key: request.program.merge.keys[0].input_key,
        },
        2 => ResidentRowMutationStatus::MultipleMatches {
            source_row: word(27),
            matches: word(28),
        },
        3 => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal row-mutation kernel rejected a corrupt graph or program packet",
            ));
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal row-mutation kernel returned an unknown status",
            ));
        }
    };
    if !matches!(status, ResidentRowMutationStatus::Success) {
        if word(17) != 0 || word(18) != 0 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "failed Metal row mutation exposed intent or dependency counts",
            ));
        }
        return Ok(ResidentRowMutationResult::completed(
            request,
            ResidentDeviceCompletion::Metal,
            status,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            receipts,
        ));
    }

    let rows = request.input.len();
    let mut targets = Vec::with_capacity(rows);
    for row in 0..rows {
        let dense = word(output.target_dense_base + row);
        let created = word(output.target_created_base + row);
        targets.push(ResidentRowMutationTarget {
            target_id: word(output.target_id_base + row),
            dense_row: if dense == 0 {
                None
            } else {
                Some(u32::try_from(dense - 1).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal row-mutation dense target exceeds u32",
                    )
                })?)
            },
            created_by: if created == 0 {
                None
            } else {
                Some(created - 1)
            },
        });
    }
    let node_count = graph.node_layer_base.saturating_sub(graph.node_active_base);
    let read_dependencies = (0..node_count)
        .filter_map(|dense| (word(output.dependency_base + dense) == 1).then_some(dense))
        .map(|dense| {
            u32::try_from(dense).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row-mutation dependency exceeds u32",
                )
            })
        })
        .collect::<Result<Vec<_>>>()?;
    if read_dependencies.len() as u64 != word(18) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal row-mutation dependency flags disagree with their sealed count",
        ));
    }

    let merge = request.program.merge.keys[0];
    let set = request.program.sets[0];
    let mut intents = Vec::new();
    for row in 0..rows {
        let source_row = row as u64;
        let target_id = targets[row].target_id;
        if word(output.create_base + row) == 1 {
            let value = metal_row_mutation_entry_value(encoded, word(output.merge_ref_base + row))?;
            if matches!(value, ScalarValue::Null) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row-mutation CREATE leader lost its non-null MERGE key",
                ));
            }
            intents.push(ResidentRowMutationIntent {
                source_row,
                command: 0,
                target_id,
                action: ResidentRowMutationIntentAction::CreateNode {
                    labels: request.program.merge.labels.clone(),
                    properties: vec![super::ResidentMutationIntentEntry {
                        property_name: merge.property_name,
                        value,
                    }],
                },
            });
        }
        intents.push(ResidentRowMutationIntent {
            source_row,
            command: 1,
            target_id,
            action: ResidentRowMutationIntentAction::SetProperty {
                property_name: set.property_name,
                value: metal_row_mutation_entry_value(encoded, word(output.set_ref_base + row))?,
            },
        });
    }
    if intents.len() as u64 != word(17) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal row-mutation intents disagree with their sealed count",
        ));
    }

    let mut latest_set_by_target = BTreeMap::new();
    for row in 0..rows {
        latest_set_by_target.insert(targets[row].target_id, word(output.set_ref_base + row));
    }
    let mut columns = Vec::with_capacity(request.program.outputs.len());
    for output_index in 0..request.program.outputs.len() {
        let mut offsets = Vec::with_capacity(rows.saturating_add(1));
        let mut bytes = Vec::new();
        let mut validity = Vec::with_capacity(rows);
        offsets.push(0);
        for row in 0..rows {
            let reference =
                word(output.final_ref_base + row * request.program.outputs.len() + output_index);
            let compiled_output = &request.program.outputs[output_index];
            let expected_reference = if compiled_output.property_name == set.property_name {
                latest_set_by_target
                    .get(&targets[row].target_id)
                    .copied()
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal row-mutation final SET overlay lost its target",
                        )
                    })?
            } else if compiled_output.property_name == merge.property_name {
                word(output.merge_ref_base + row)
            } else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row-mutation final output has no compiled value source",
                ));
            };
            if reference != expected_reference {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row-mutation final reference disagrees with its sealed statement overlay",
                ));
            }
            match metal_row_mutation_entry_value(encoded, reference)? {
                ScalarValue::Null => validity.push(0),
                ScalarValue::String(value) => {
                    validity.push(1);
                    bytes.extend_from_slice(value.as_bytes());
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal row-mutation final reference selected a non-string map value",
                    ));
                }
            }
            offsets.push(bytes.len() as u64);
        }
        let output = u16::try_from(output_index).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal row-mutation output index exceeds its validated representation",
            )
        })?;
        columns.push(ResidentRowMutationStringColumn {
            output,
            offsets,
            bytes,
            validity,
        });
    }
    Ok(ResidentRowMutationResult::completed(
        request,
        ResidentDeviceCompletion::Metal,
        ResidentRowMutationStatus::Success,
        intents,
        targets,
        read_dependencies,
        columns,
        receipts,
    ))
}

const METAL_DELETE_PROGRAM_MAGIC: u64 = 0x4947_4445_4c50_5247;
const METAL_DELETE_PROGRAM_VERSION: u64 = 2;
const METAL_DELETE_PROGRAM_HEADER_WORDS: usize = 64;
const METAL_DELETE_FILTER_WORDS: usize = 12;
const METAL_DELETE_COMMAND_WORDS: usize = 14;
const METAL_DELETE_STAGE_WORDS: usize = 14;
const METAL_DELETE_OUTPUT_HEADER_WORDS: usize = 48;
const METAL_DELETE_RECEIPT_WORDS: usize = 9;
const METAL_DELETE_INTENT_WORDS: usize = 5;
const METAL_DELETE_DEPENDENCY_WORDS: usize = 2;
const METAL_DELETE_CONTROL_WORDS: usize = 32;
const METAL_DELETE_NODE_ROW_COLUMNS: usize = 4;
const METAL_DELETE_RELATIONSHIP_ROW_COLUMNS: usize = 3;
const METAL_DELETE_OUTPUT_MAGIC: u64 = 0x4947_4445_4c4f_5554;
const METAL_DELETE_OUTPUT_VERSION: u64 = 2;
const METAL_DELETE_BINDING_NODE: u64 = 1;
const METAL_DELETE_BINDING_RELATIONSHIP: u64 = 2;
const METAL_DELETE_NODE_END: u64 = u64::MAX;
const METAL_DELETE_PROPERTY_ABSENT: u64 = 0;
const METAL_DELETE_PROPERTY_INTEGER: u64 = 1;
const METAL_DELETE_PROPERTY_INCOMPATIBLE: u64 = 2;
const METAL_DELETE_SOURCE_NONE: u64 = 0;
const METAL_DELETE_SOURCE_CONSTANT: u64 = 1;
const METAL_DELETE_SOURCE_PROPERTY: u64 = 2;
const METAL_DELETE_SOURCE_AGGREGATE: u64 = 3;
const METAL_DELETE_SOURCE_NULL_ENTITY: u64 = 4;
const METAL_DELETE_SOURCE_RELATIONSHIP_TYPE: u64 = 5;
const METAL_DELETE_SELECTOR_EACH_SELECTED_ROW: u64 = 0;
const METAL_DELETE_SELECTOR_COLLECTED_ORDINAL: u64 = 1;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct MetalDeletePropertyLane {
    kind: EntityKind,
    property: PropertyId,
}

#[derive(Clone, Debug)]
struct EncodedMetalDeleteProgram {
    words: Vec<u64>,
    label_lanes: Vec<LabelId>,
    property_lanes: Vec<MetalDeletePropertyLane>,
    filter_count: usize,
    command_count: usize,
    stage_count: usize,
    receipt_count: usize,
    #[allow(dead_code)]
    has_expansion: bool,
}

#[derive(Clone, Copy, Debug)]
struct MetalDeleteGraphLayout {
    word_count: usize,
    node_active_base: usize,
    node_layer_base: usize,
    node_id_base: usize,
    label_base: usize,
    edge_active_base: usize,
    edge_layer_base: usize,
    edge_type_base: usize,
    edge_id_base: usize,
    outgoing_offset_base: usize,
    outgoing_neighbor_base: usize,
    outgoing_edge_base: usize,
    outgoing_count: usize,
    incoming_offset_base: usize,
    incoming_neighbor_base: usize,
    incoming_edge_base: usize,
    incoming_count: usize,
    node_property_value_base: usize,
    node_property_validity_base: usize,
    node_property_count: usize,
    edge_property_value_base: usize,
    edge_property_validity_base: usize,
    edge_property_count: usize,
}

#[derive(Clone, Copy, Debug)]
struct MetalDeleteOutputLayout {
    word_count: usize,
    receipt_base: usize,
    command_attempt_base: usize,
    intent_base: usize,
    dependency_base: usize,
    final_value_base: usize,
    final_validity_base: usize,
    start_row_base: usize,
    relationship_row_base: usize,
    end_row_base: usize,
    position_base: usize,
    intent_dense_base: usize,
    intent_processed_base: usize,
    control_base: usize,
}

fn metal_delete_binding(binding: ResidentEntityBinding) -> (u64, u64) {
    match binding {
        ResidentEntityBinding::Node(ResidentNodeBinding::Start) => (METAL_DELETE_BINDING_NODE, 0),
        ResidentEntityBinding::Node(ResidentNodeBinding::Intermediate(index)) => (
            METAL_DELETE_BINDING_NODE,
            u64::from(index).saturating_add(1),
        ),
        ResidentEntityBinding::Node(ResidentNodeBinding::End) => {
            (METAL_DELETE_BINDING_NODE, METAL_DELETE_NODE_END)
        }
        ResidentEntityBinding::Relationship(index) => {
            (METAL_DELETE_BINDING_RELATIONSHIP, u64::from(index))
        }
    }
}

fn exact_metal_three_hop_path_delete(request: &ResidentDeleteRequest) -> bool {
    let expansions = request.selection.expansion_steps().collect::<Vec<_>>();
    matches!(expansions.as_slice(), [first, second, third]
    if [*first, *second, *third].into_iter().all(|expansion| {
        expansion.direction == super::ResidentDirection::Outgoing
            && expansion.relationship_types.is_empty()
            && expansion.end_labels.is_empty()
            && !expansion.end_equals_start
            && !expansion.optional
            && expansion.end_predicates.is_empty()
    })) && !request.selection.initial_optional
        && request.selection.correlated_optional.is_none()
        && request.selection.relationship_null_filter.is_none()
        && request.selection.predicates.is_empty()
        && request.selection.property_filters.is_empty()
        && request.selection.value_matrix.is_none()
        && request.selection.mutation.is_none()
        && request.selection.orders.is_empty()
        && request.selection.offset == 0
        && request.selection.limit == usize::MAX
        && request.selection.integer_projections.is_empty()
        && request.selection.property_null_projections.is_empty()
        && !request.selection_is_statically_empty
        && request.selection_filters.is_empty()
        && request.continuation.is_none()
        && matches!(
            request.commands.as_slice(),
            [
                ResidentDeleteCommand {
                    target: ResidentEntityBinding::Node(ResidentNodeBinding::Start),
                    selector: ResidentDeleteTargetSelector::EachSelectedRow,
                    detach: true,
                    ..
                },
                ResidentDeleteCommand {
                    target: ResidentEntityBinding::Relationship(0),
                    selector: ResidentDeleteTargetSelector::EachSelectedRow,
                    detach: true,
                    ..
                },
                ResidentDeleteCommand {
                    target: ResidentEntityBinding::Node(ResidentNodeBinding::Intermediate(0)),
                    selector: ResidentDeleteTargetSelector::EachSelectedRow,
                    detach: true,
                    ..
                },
                ResidentDeleteCommand {
                    target: ResidentEntityBinding::Relationship(1),
                    selector: ResidentDeleteTargetSelector::EachSelectedRow,
                    detach: true,
                    ..
                },
                ResidentDeleteCommand {
                    target: ResidentEntityBinding::Node(ResidentNodeBinding::Intermediate(1)),
                    selector: ResidentDeleteTargetSelector::EachSelectedRow,
                    detach: true,
                    ..
                },
                ResidentDeleteCommand {
                    target: ResidentEntityBinding::Relationship(2),
                    selector: ResidentDeleteTargetSelector::EachSelectedRow,
                    detach: true,
                    ..
                },
                ResidentDeleteCommand {
                    target: ResidentEntityBinding::Node(ResidentNodeBinding::End),
                    selector: ResidentDeleteTargetSelector::EachSelectedRow,
                    detach: true,
                    ..
                },
            ]
        )
}

fn metal_delete_compare(operation: CompareOp) -> u64 {
    match operation {
        CompareOp::Eq => 0,
        CompareOp::NotEq => 1,
        CompareOp::Less => 2,
        CompareOp::LessOrEqual => 3,
        CompareOp::Greater => 4,
        CompareOp::GreaterOrEqual => 5,
    }
}

fn metal_delete_selector(selector: ResidentDeleteTargetSelector) -> (u64, u64) {
    match selector {
        ResidentDeleteTargetSelector::EachSelectedRow => {
            (METAL_DELETE_SELECTOR_EACH_SELECTED_ROW, 0)
        }
        ResidentDeleteTargetSelector::CollectedOrdinal { index } => {
            (METAL_DELETE_SELECTOR_COLLECTED_ORDINAL, u64::from(index))
        }
    }
}

fn metal_delete_obligation_words(obligation: ResidentExecutionObligation) -> [u64; 4] {
    let (scope, index) = match obligation.scope {
        super::ResidentObligationScope::Selection => (0, 0),
        super::ResidentObligationScope::MutationCommand(index) => (1, u64::from(index)),
        super::ResidentObligationScope::Expression(index) => (2, u64::from(index)),
        super::ResidentObligationScope::Filter(index) => (3, u64::from(index)),
        super::ResidentObligationScope::PatternLeaf(index) => (4, u64::from(index)),
        super::ResidentObligationScope::PatternFinal => (5, 0),
        super::ResidentObligationScope::PatternScan => (6, 0),
        super::ResidentObligationScope::PatternScanN => (7, 0),
        super::ResidentObligationScope::PatternScanM => (8, 0),
        super::ResidentObligationScope::PatternCartesian => (9, 0),
    };
    [obligation.id, obligation.kind as u64, scope, index]
}

fn metal_delete_expected_receipts(request: &ResidentDeleteRequest) -> Result<usize> {
    let continuation = request.continuation.as_ref().map_or(0, |continuation| {
        continuation.stages.len().saturating_add(1)
    });
    2_usize
        .checked_add(request.selection_filters.len())
        .and_then(|count| count.checked_add(request.commands.len().checked_mul(2)?))
        .and_then(|count| count.checked_add(continuation))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal DELETE receipt count overflow",
            )
        })
}

impl CandleResident {
    fn metal_delete_property_reference(
        &self,
        binding: ResidentEntityBinding,
        property: Option<PropertyId>,
        lanes: &mut Vec<MetalDeletePropertyLane>,
    ) -> Result<(u64, u64)> {
        let Some(property) = property else {
            return Ok((METAL_DELETE_PROPERTY_ABSENT, 0));
        };
        let kind = match binding {
            ResidentEntityBinding::Node(_) => EntityKind::Node,
            ResidentEntityBinding::Relationship(_) => EntityKind::Relationship,
        };
        let integer = match kind {
            EntityKind::Node => self.integer_nodes.contains_key(&property),
            EntityKind::Relationship => self.integer_edges.contains_key(&property),
        };
        if integer {
            if let Some((index, _)) = lanes
                .iter()
                .filter(|lane| lane.kind == kind)
                .enumerate()
                .find(|(_, lane)| lane.property == property)
            {
                return Ok((METAL_DELETE_PROPERTY_INTEGER, index as u64));
            }
            let index = lanes.iter().filter(|lane| lane.kind == kind).count();
            lanes.push(MetalDeletePropertyLane { kind, property });
            return Ok((
                METAL_DELETE_PROPERTY_INTEGER,
                u64::try_from(index).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal DELETE property-lane index exceeds u64",
                    )
                })?,
            ));
        }
        let incompatible = match kind {
            EntityKind::Node => {
                self.boolean_nodes.contains_key(&property)
                    || self.float_nodes.contains_key(&property)
                    || self.string_nodes.contains_key(&property)
                    || self.date_nodes.contains_key(&property)
                    || self.local_time_nodes.contains_key(&property)
                    || self.zoned_time_nodes.contains_key(&property)
                    || self.local_datetime_nodes.contains_key(&property)
                    || self.zoned_datetime_nodes.contains_key(&property)
                    || self.mixed_nodes.contains_key(&property)
                    || self.unsupported_node_properties.contains(&property)
                    || self.vectors.contains_key(&property)
            }
            EntityKind::Relationship => {
                self.boolean_edges.contains_key(&property)
                    || self.float_edges.contains_key(&property)
                    || self.string_edges.contains_key(&property)
                    || self.date_edges.contains_key(&property)
                    || self.local_time_edges.contains_key(&property)
                    || self.zoned_time_edges.contains_key(&property)
                    || self.local_datetime_edges.contains_key(&property)
                    || self.zoned_datetime_edges.contains_key(&property)
                    || self.mixed_edges.contains_key(&property)
                    || self.unsupported_edge_properties.contains(&property)
            }
        };
        Ok((
            if incompatible {
                METAL_DELETE_PROPERTY_INCOMPATIBLE
            } else {
                METAL_DELETE_PROPERTY_ABSENT
            },
            0,
        ))
    }

    fn metal_delete_integer_source_words(
        &self,
        source: ResidentDeleteIntegerSource,
        lanes: &mut Vec<MetalDeletePropertyLane>,
    ) -> Result<[u64; 6]> {
        match source {
            ResidentDeleteIntegerSource::Constant(value) => Ok([
                METAL_DELETE_SOURCE_CONSTANT,
                0,
                0,
                METAL_DELETE_PROPERTY_ABSENT,
                0,
                value as u64,
            ]),
            ResidentDeleteIntegerSource::Property { binding, property } => {
                let (binding_kind, binding_index) = metal_delete_binding(binding);
                let (property_mode, property_lane) =
                    self.metal_delete_property_reference(binding, property, lanes)?;
                Ok([
                    METAL_DELETE_SOURCE_PROPERTY,
                    binding_kind,
                    binding_index,
                    property_mode,
                    property_lane,
                    0,
                ])
            }
            ResidentDeleteIntegerSource::Aggregate => Ok([
                METAL_DELETE_SOURCE_AGGREGATE,
                0,
                0,
                METAL_DELETE_PROPERTY_ABSENT,
                0,
                0,
            ]),
        }
    }

    fn metal_delete_output_source_words(
        &self,
        source: ResidentDeleteOutputSource,
        lanes: &mut Vec<MetalDeletePropertyLane>,
    ) -> Result<[u64; 6]> {
        match source {
            ResidentDeleteOutputSource::Integer(source) => {
                self.metal_delete_integer_source_words(source, lanes)
            }
            ResidentDeleteOutputSource::RelationshipType(binding) => {
                let ResidentEntityBinding::Relationship(_) = binding else {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal DELETE relationship-type source is not a relationship binding",
                    ));
                };
                let (binding_kind, binding_index) = metal_delete_binding(binding);
                Ok([
                    METAL_DELETE_SOURCE_RELATIONSHIP_TYPE,
                    binding_kind,
                    binding_index,
                    METAL_DELETE_PROPERTY_ABSENT,
                    0,
                    0,
                ])
            }
            ResidentDeleteOutputSource::NullEntity(kind) => Ok([
                METAL_DELETE_SOURCE_NULL_ENTITY,
                match kind {
                    EntityKind::Node => METAL_DELETE_BINDING_NODE,
                    EntityKind::Relationship => METAL_DELETE_BINDING_RELATIONSHIP,
                },
                0,
                METAL_DELETE_PROPERTY_ABSENT,
                0,
                0,
            ]),
        }
    }

    fn encode_metal_delete_program(
        &self,
        request: &ResidentDeleteRequest,
    ) -> Result<EncodedMetalDeleteProgram> {
        request.validate()?;
        let expansion_count = request.selection.expansion_steps().count();
        let exact_three_hop_path_delete = exact_metal_three_hop_path_delete(request);
        if (expansion_count > 1 && !exact_three_hop_path_delete)
            || request.selection.correlated_optional.is_some()
            || request.selection.relationship_null_filter.is_some()
            || !request.selection.predicates.is_empty()
            || !request.selection.property_filters.is_empty()
            || request.selection.value_matrix.is_some()
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal DELETE exact contract requires one complete scan, one fixed expansion, or the sealed three-hop path delete",
            ));
        }
        if request.selection.initial_optional
            && (!request.selection_filters.is_empty()
                || expansion_count > 1
                || request.commands.iter().any(|command| {
                    command.selector != ResidentDeleteTargetSelector::EachSelectedRow
                }))
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal DELETE initial OPTIONAL contract requires one null-extendable fixed pattern",
            ));
        }
        let expansion = request.selection.expansion_steps().next();
        let exact_optional_relationship_delete = expansion.is_some_and(|expansion| {
            expansion.optional
                && expansion.direction == super::ResidentDirection::Undirected
                && expansion.relationship_types.is_empty()
                && expansion.end_labels.is_empty()
                && !expansion.end_equals_start
                && expansion.end_predicates.is_empty()
                && request.selection.labels.is_empty()
                && !request.selection.initial_optional
                && request.selection_filters.is_empty()
                && request.continuation.is_none()
                && matches!(
                    request.commands.as_slice(),
                    [
                        ResidentDeleteCommand {
                            target: ResidentEntityBinding::Node(ResidentNodeBinding::Start),
                            detach: false,
                            selector: ResidentDeleteTargetSelector::EachSelectedRow,
                            ..
                        },
                        ResidentDeleteCommand {
                            target: ResidentEntityBinding::Relationship(0),
                            detach: false,
                            selector: ResidentDeleteTargetSelector::EachSelectedRow,
                            ..
                        }
                    ]
                )
        });
        if expansion.is_some_and(|expansion| {
            !expansion.end_predicates.is_empty()
                || (expansion.optional && !exact_optional_relationship_delete)
        }) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal DELETE exact contract admits only the bounded optional-relationship delete or a predicate-free mandatory expansion",
            ));
        }
        if request.selection.max_output_rows == 0
            || request.selection.max_output_rows > u32::MAX as usize
            || self.node_count > u32::MAX as usize
            || self.edge_count > u32::MAX as usize
        {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal DELETE dimensions exceed the exact device ABI",
            ));
        }

        let mut labels = BTreeSet::new();
        labels.extend(request.selection.labels.iter().copied());
        if let Some(expansion) = expansion {
            labels.extend(expansion.end_labels.iter().copied());
        }
        let label_lanes = labels.into_iter().collect::<Vec<_>>();
        let label_index = label_lanes
            .iter()
            .enumerate()
            .map(|(index, label)| (*label, index as u64))
            .collect::<BTreeMap<_, _>>();
        let start_label_words = request
            .selection
            .labels
            .iter()
            .map(|label| {
                label_index
                    .get(label)
                    .copied()
                    .ok_or_else(|| Error::internal("Metal DELETE start-label lane disappeared"))
            })
            .collect::<Result<Vec<_>>>()?;
        let end_label_words = expansion
            .map(|expansion| {
                expansion
                    .end_labels
                    .iter()
                    .map(|label| {
                        label_index.get(label).copied().ok_or_else(|| {
                            Error::internal("Metal DELETE end-label lane disappeared")
                        })
                    })
                    .collect::<Result<Vec<_>>>()
            })
            .transpose()?
            .unwrap_or_default();
        let relationship_types = expansion
            .map(|expansion| {
                expansion
                    .relationship_types
                    .iter()
                    .map(|relationship_type| relationship_type.0)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();

        let filter_count = request.selection_filters.len();
        let command_count = request.commands.len();
        let stage_count = request
            .continuation
            .as_ref()
            .map_or(0, |continuation| continuation.stages.len());
        let receipt_count = metal_delete_expected_receipts(request)?;
        let descriptor_words = METAL_DELETE_PROGRAM_HEADER_WORDS
            .checked_add(
                filter_count
                    .checked_mul(METAL_DELETE_FILTER_WORDS)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal DELETE filter ABI overflow",
                        )
                    })?,
            )
            .and_then(|words| {
                command_count
                    .checked_mul(METAL_DELETE_COMMAND_WORDS)
                    .and_then(|commands| words.checked_add(commands))
            })
            .and_then(|words| {
                stage_count
                    .checked_mul(METAL_DELETE_STAGE_WORDS)
                    .and_then(|stages| words.checked_add(stages))
            })
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal DELETE descriptor ABI overflow",
                )
            })?;
        let mut words = vec![0_u64; descriptor_words];
        let filter_offset = METAL_DELETE_PROGRAM_HEADER_WORDS;
        let command_offset = filter_offset + filter_count * METAL_DELETE_FILTER_WORDS;
        let stage_offset = command_offset + command_count * METAL_DELETE_COMMAND_WORDS;
        let mut property_lanes = Vec::new();

        for (index, filter) in request.selection_filters.iter().enumerate() {
            let base = filter_offset + index * METAL_DELETE_FILTER_WORDS;
            let (binding_kind, binding_index) = metal_delete_binding(filter.binding);
            let (property_mode, property_lane) = self.metal_delete_property_reference(
                filter.binding,
                filter.property,
                &mut property_lanes,
            )?;
            let obligation = metal_delete_obligation_words(filter.obligation);
            words[base..base + METAL_DELETE_FILTER_WORDS].copy_from_slice(&[
                binding_kind,
                binding_index,
                property_mode,
                property_lane,
                metal_delete_compare(filter.operation),
                filter.operand as u64,
                obligation[0],
                obligation[1],
                obligation[2],
                obligation[3],
                0,
                0,
            ]);
        }
        for (index, command) in request.commands.iter().enumerate() {
            let base = command_offset + index * METAL_DELETE_COMMAND_WORDS;
            let (binding_kind, binding_index) = metal_delete_binding(command.target);
            let (selector, selector_index) = metal_delete_selector(command.selector);
            let rhs = metal_delete_obligation_words(command.rhs_obligation);
            let effect = metal_delete_obligation_words(command.effect_obligation);
            words[base..base + METAL_DELETE_COMMAND_WORDS].copy_from_slice(&[
                binding_kind,
                binding_index,
                u64::from(command.detach),
                rhs[0],
                rhs[1],
                rhs[2],
                rhs[3],
                effect[0],
                effect[1],
                effect[2],
                effect[3],
                selector,
                selector_index,
                0,
            ]);
        }
        if let Some(continuation) = &request.continuation {
            for (index, (stage, obligation)) in continuation
                .stages
                .iter()
                .zip(&continuation.stage_obligations)
                .enumerate()
            {
                let base = stage_offset + index * METAL_DELETE_STAGE_WORDS;
                let (opcode, source, argument_0, argument_1) = match stage {
                    ResidentDeletePostStage::Project { source } => (
                        1,
                        self.metal_delete_output_source_words(*source, &mut property_lanes)?,
                        0,
                        0,
                    ),
                    ResidentDeletePostStage::FilterIntegerModuloEquals {
                        source,
                        divisor,
                        operand,
                    } => (
                        2,
                        self.metal_delete_integer_source_words(*source, &mut property_lanes)?,
                        *divisor as u64,
                        *operand as u64,
                    ),
                    ResidentDeletePostStage::Skip { rows } => (
                        3,
                        [METAL_DELETE_SOURCE_NONE, 0, 0, 0, 0, 0],
                        u64::try_from(*rows).unwrap_or(u64::MAX),
                        0,
                    ),
                    ResidentDeletePostStage::Limit { rows } => (
                        4,
                        [METAL_DELETE_SOURCE_NONE, 0, 0, 0, 0, 0],
                        u64::try_from(*rows).unwrap_or(u64::MAX),
                        0,
                    ),
                    ResidentDeletePostStage::SumInteger { source } => (
                        5,
                        self.metal_delete_integer_source_words(*source, &mut property_lanes)?,
                        0,
                        0,
                    ),
                    ResidentDeletePostStage::Count => {
                        (6, [METAL_DELETE_SOURCE_NONE, 0, 0, 0, 0, 0], 0, 0)
                    }
                };
                let obligation = metal_delete_obligation_words(*obligation);
                words[base..base + METAL_DELETE_STAGE_WORDS].copy_from_slice(&[
                    opcode,
                    source[0],
                    source[1],
                    source[2],
                    source[3],
                    source[4],
                    source[5],
                    argument_0,
                    argument_1,
                    obligation[0],
                    obligation[1],
                    obligation[2],
                    obligation[3],
                    0,
                ]);
            }
        }

        let start_label_offset = words.len();
        words.extend_from_slice(&start_label_words);
        let end_label_offset = words.len();
        words.extend_from_slice(&end_label_words);
        let relationship_type_offset = words.len();
        words.extend_from_slice(&relationship_types);

        let selection_obligation = metal_delete_obligation_words(request.selection_obligation);
        let read_obligation = metal_delete_obligation_words(request.read_dependency_obligation);
        let (final_source, final_obligation, maximum_final_rows, maximum_final_cells) = request
            .continuation
            .as_ref()
            .map(|continuation| {
                Ok::<_, Error>((
                    self.metal_delete_output_source_words(
                        continuation.output.source,
                        &mut property_lanes,
                    )?,
                    metal_delete_obligation_words(continuation.final_relation_obligation),
                    continuation.maximum_output_rows,
                    continuation.maximum_output_cells,
                ))
            })
            .transpose()?
            .unwrap_or(([METAL_DELETE_SOURCE_NONE, 0, 0, 0, 0, 0], [0; 4], 0, 0));
        let direction = expansion.map_or(0, |expansion| match expansion.direction {
            super::ResidentDirection::Outgoing => 1,
            super::ResidentDirection::Incoming => 2,
            super::ResidentDirection::Undirected => 3,
        });
        words[0] = METAL_DELETE_PROGRAM_MAGIC;
        words[1] = METAL_DELETE_PROGRAM_VERSION;
        words[2] = u64::from(request.selection.layers.bits());
        words[3] = direction;
        words[4] = start_label_offset as u64;
        words[5] = start_label_words.len() as u64;
        words[6] = end_label_offset as u64;
        words[7] = end_label_words.len() as u64;
        words[8] = relationship_type_offset as u64;
        words[9] = relationship_types.len() as u64;
        words[10] = u64::from(expansion.is_some_and(|expansion| expansion.end_equals_start));
        words[11] = u64::from(expansion.is_some_and(|expansion| expansion.optional));
        words[12] = filter_offset as u64;
        words[13] = filter_count as u64;
        words[14] = command_offset as u64;
        words[15] = command_count as u64;
        words[16] = stage_offset as u64;
        words[17] = stage_count as u64;
        words[18..24].copy_from_slice(&final_source);
        words[24] = request.selection.max_output_rows as u64;
        words[25] = request.maximum_delete_intents as u64;
        words[26] = request.maximum_read_dependencies as u64;
        words[27] = maximum_final_rows as u64;
        words[28] = maximum_final_cells as u64;
        words[29] = request.selection.relationship_column_count() as u64;
        words[30] = expansion_count as u64;
        words[31] = u64::from(request.continuation.is_some());
        words[32..36].copy_from_slice(&selection_obligation);
        words[36..40].copy_from_slice(&read_obligation);
        words[40..44].copy_from_slice(&final_obligation);
        words[44] = receipt_count as u64;
        words[45] = property_lanes
            .iter()
            .filter(|lane| lane.kind == EntityKind::Node)
            .count() as u64;
        words[46] = property_lanes
            .iter()
            .filter(|lane| lane.kind == EntityKind::Relationship)
            .count() as u64;
        words[47] = label_lanes.len() as u64;
        words[48] = u64::from(request.selection.initial_optional);
        words[49] = u64::from(request.selection_is_statically_empty);
        words[50] = u64::from(exact_three_hop_path_delete);
        words[51] = u64::from(request.variable_path_selection.is_some());

        Ok(EncodedMetalDeleteProgram {
            words,
            label_lanes,
            property_lanes,
            filter_count,
            command_count,
            stage_count,
            receipt_count,
            has_expansion: expansion.is_some(),
        })
    }
}

fn metal_delete_graph_layout(
    resident: &CandleResident,
    encoded: &EncodedMetalDeleteProgram,
) -> Result<MetalDeleteGraphLayout> {
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal DELETE graph packet layout overflow",
        )
    };
    let mut cursor = 0_usize;
    let mut take = |count: usize| -> Result<usize> {
        let base = cursor;
        cursor = cursor.checked_add(count).ok_or_else(overflow)?;
        Ok(base)
    };
    let node_count = resident.node_count;
    let edge_count = resident.edge_count;
    let outgoing_count = resident
        .outgoing_neighbors
        .as_ref()
        .map_or(0, Tensor::elem_count);
    let incoming_count = resident
        .incoming_neighbors
        .as_ref()
        .map_or(0, Tensor::elem_count);
    let node_property_count = encoded
        .property_lanes
        .iter()
        .filter(|lane| lane.kind == EntityKind::Node)
        .count();
    let edge_property_count = encoded
        .property_lanes
        .iter()
        .filter(|lane| lane.kind == EntityKind::Relationship)
        .count();
    let node_property_words = node_count
        .checked_mul(node_property_count)
        .ok_or_else(overflow)?;
    let edge_property_words = edge_count
        .checked_mul(edge_property_count)
        .ok_or_else(overflow)?;
    let node_active_base = take(node_count)?;
    let node_layer_base = take(node_count)?;
    let node_id_base = take(node_count)?;
    let label_base = take(
        node_count
            .checked_mul(encoded.label_lanes.len())
            .ok_or_else(overflow)?,
    )?;
    let edge_active_base = take(edge_count)?;
    let edge_layer_base = take(edge_count)?;
    let edge_type_base = take(edge_count)?;
    let edge_id_base = take(edge_count)?;
    let outgoing_offset_base = take(node_count.checked_add(1).ok_or_else(overflow)?)?;
    let outgoing_neighbor_base = take(outgoing_count)?;
    let outgoing_edge_base = take(outgoing_count)?;
    let incoming_offset_base = take(node_count.checked_add(1).ok_or_else(overflow)?)?;
    let incoming_neighbor_base = take(incoming_count)?;
    let incoming_edge_base = take(incoming_count)?;
    let node_property_value_base = take(node_property_words)?;
    let node_property_validity_base = take(node_property_words)?;
    let edge_property_value_base = take(edge_property_words)?;
    let edge_property_validity_base = take(edge_property_words)?;
    Ok(MetalDeleteGraphLayout {
        word_count: cursor,
        node_active_base,
        node_layer_base,
        node_id_base,
        label_base,
        edge_active_base,
        edge_layer_base,
        edge_type_base,
        edge_id_base,
        outgoing_offset_base,
        outgoing_neighbor_base,
        outgoing_edge_base,
        outgoing_count,
        incoming_offset_base,
        incoming_neighbor_base,
        incoming_edge_base,
        incoming_count,
        node_property_value_base,
        node_property_validity_base,
        node_property_count,
        edge_property_value_base,
        edge_property_validity_base,
        edge_property_count,
    })
}

fn metal_delete_output_layout(
    request: &ResidentDeleteRequest,
    encoded: &EncodedMetalDeleteProgram,
) -> Result<MetalDeleteOutputLayout> {
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal DELETE output packet layout overflow",
        )
    };
    let selector_capacity = request.selection.max_output_rows;
    let final_capacity = request
        .continuation
        .as_ref()
        .map_or(0, |continuation| continuation.maximum_output_rows);
    let mut cursor = METAL_DELETE_OUTPUT_HEADER_WORDS;
    let mut take = |count: usize| -> Result<usize> {
        let base = cursor;
        cursor = cursor.checked_add(count).ok_or_else(overflow)?;
        Ok(base)
    };
    let receipt_base = take(
        encoded
            .receipt_count
            .checked_mul(METAL_DELETE_RECEIPT_WORDS)
            .ok_or_else(overflow)?,
    )?;
    let command_attempt_base = take(encoded.command_count)?;
    let intent_base = take(
        request
            .maximum_delete_intents
            .checked_mul(METAL_DELETE_INTENT_WORDS)
            .ok_or_else(overflow)?,
    )?;
    let dependency_base = take(
        request
            .maximum_read_dependencies
            .checked_mul(METAL_DELETE_DEPENDENCY_WORDS)
            .ok_or_else(overflow)?,
    )?;
    let final_value_base = take(final_capacity)?;
    let final_validity_base = take(final_capacity)?;
    let start_row_base = take(
        selector_capacity
            .checked_mul(METAL_DELETE_NODE_ROW_COLUMNS)
            .ok_or_else(overflow)?,
    )?;
    let relationship_row_base = take(
        selector_capacity
            .checked_mul(METAL_DELETE_RELATIONSHIP_ROW_COLUMNS)
            .ok_or_else(overflow)?,
    )?;
    let end_row_base = start_row_base
        .checked_add(selector_capacity)
        .ok_or_else(overflow)?;
    let position_base = take(selector_capacity)?;
    let intent_dense_base = take(request.maximum_delete_intents)?;
    let intent_processed_base = take(request.maximum_delete_intents)?;
    let control_base = take(METAL_DELETE_CONTROL_WORDS)?;
    Ok(MetalDeleteOutputLayout {
        word_count: cursor,
        receipt_base,
        command_attempt_base,
        intent_base,
        dependency_base,
        final_value_base,
        final_validity_base,
        start_row_base,
        relationship_row_base,
        end_row_base,
        position_base,
        intent_dense_base,
        intent_processed_base,
        control_base,
    })
}

fn decode_metal_delete_obligation(words: [u64; 4]) -> Result<ResidentExecutionObligation> {
    let kind = match words[1] {
        1 => super::ResidentObligationKind::MutationSelect,
        2 => super::ResidentObligationKind::MutationRhs,
        3 => super::ResidentObligationKind::Expression,
        4 => super::ResidentObligationKind::Filter,
        5 => super::ResidentObligationKind::PatternTraversal,
        6 => super::ResidentObligationKind::PatternFilter,
        7 => super::ResidentObligationKind::PatternScan,
        8 => super::ResidentObligationKind::PatternCartesian,
        9 => super::ResidentObligationKind::Sort,
        10 => super::ResidentObligationKind::Aggregate,
        11 => super::ResidentObligationKind::Procedure,
        12 => super::ResidentObligationKind::MutationEffect,
        13 => super::ResidentObligationKind::MutationReadSet,
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE receipt has an unknown obligation kind",
            ));
        }
    };
    let index = u16::try_from(words[3]).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal DELETE receipt scope index exceeds u16",
        )
    })?;
    let scope = match words[2] {
        0 if words[3] == 0 => super::ResidentObligationScope::Selection,
        1 => super::ResidentObligationScope::MutationCommand(index),
        2 => super::ResidentObligationScope::Expression(index),
        3 => super::ResidentObligationScope::Filter(index),
        4 => super::ResidentObligationScope::PatternLeaf(index),
        5 if words[3] == 0 => super::ResidentObligationScope::PatternFinal,
        6 if words[3] == 0 => super::ResidentObligationScope::PatternScan,
        7 if words[3] == 0 => super::ResidentObligationScope::PatternScanN,
        8 if words[3] == 0 => super::ResidentObligationScope::PatternScanM,
        9 if words[3] == 0 => super::ResidentObligationScope::PatternCartesian,
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE receipt has an invalid obligation scope",
            ));
        }
    };
    Ok(ResidentExecutionObligation {
        id: words[0],
        kind,
        scope,
    })
}

fn decode_metal_delete_result(
    words: &[i64],
    request: &ResidentDeleteRequest,
    encoded: &EncodedMetalDeleteProgram,
    layout: MetalDeleteOutputLayout,
) -> Result<ResidentDeleteResult> {
    if words.len() != layout.word_count {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal DELETE output packet has a wrong length",
        ));
    }
    let word = |index: usize| words[index] as u64;
    let project = request.project.0.as_u128();
    let fingerprint = metal_nullable_relation_hash_words(request.fingerprint.0);
    if word(0) != METAL_DELETE_OUTPUT_MAGIC
        || word(1) != METAL_DELETE_OUTPUT_VERSION
        || word(4) != request.execution.high
        || word(5) != request.execution.low
        || word(6) != (project >> 64) as u64
        || word(7) != project as u64
        || word(8) != request.expected_bookmark.term
        || word(9) != request.expected_bookmark.index
        || word(10) != request.expected_graph_revision
        || word(11) != request.expected_layout_version
        || [word(12), word(13), word(14), word(15)] != fingerprint
        || word(18) != encoded.command_count as u64
        || word(21) != encoded.receipt_count as u64
        || word(24) != request.scratch_bytes()? as u64
        || word(26) != encoded.words.len() as u64
        || word(27) != layout.word_count as u64
        || word(28) != request.selection.max_output_rows as u64
        || word(29) != request.maximum_delete_intents as u64
        || word(30) != request.maximum_read_dependencies as u64
        || word(31)
            != request
                .continuation
                .as_ref()
                .map_or(0, |continuation| continuation.maximum_output_rows) as u64
        || word(32) != encoded.filter_count as u64
        || word(33) != encoded.stage_count as u64
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal DELETE output packet has forged generation, fingerprint, or capacity provenance",
        ));
    }
    match word(2) {
        0 => {}
        1 => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE rejected a corrupt device packet",
            ));
        }
        2 => {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal DELETE exceeded an admitted device capacity",
            ));
        }
        3 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "DeleteConnectedNode: node still has relationships",
            ));
        }
        4 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal DELETE continuation property is not an integer",
            ));
        }
        5 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal DELETE SUM integer overflow",
            ));
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE returned an unknown device status",
            ));
        }
    }
    if word(3) != ResidentDeviceCompletion::Metal as u64 || word(34) != 0x5345_414c_4544_4445 {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal DELETE did not publish a sealed device completion",
        ));
    }
    let selector_rows = word(16);
    let selected_rows = word(17);
    let intent_count = usize::try_from(word(19)).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal DELETE intent count exceeds host address space",
        )
    })?;
    let dependency_count = usize::try_from(word(20)).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal DELETE dependency count exceeds host address space",
        )
    })?;
    let final_rows = usize::try_from(word(22)).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal DELETE final row count exceeds host address space",
        )
    })?;
    if selected_rows > selector_rows
        || selector_rows > request.selection.max_output_rows as u64
        || intent_count > request.maximum_delete_intents
        || dependency_count > request.maximum_read_dependencies
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal DELETE output cardinalities exceed their admitted bounds",
        ));
    }

    let mut receipts = Vec::with_capacity(encoded.receipt_count);
    for index in 0..encoded.receipt_count {
        let base = layout.receipt_base + index * METAL_DELETE_RECEIPT_WORDS;
        if word(base) != request.execution.high
            || word(base + 1) != request.execution.low
            || word(base + 8) != ResidentDeviceCompletion::Metal as u64
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE receipt has forged execution or backend provenance",
            ));
        }
        receipts.push(ResidentExecutionReceipt {
            execution: request.execution,
            obligation: decode_metal_delete_obligation([
                word(base + 2),
                word(base + 3),
                word(base + 4),
                word(base + 5),
            ])?,
            input_cardinality: word(base + 6),
            output_cardinality: word(base + 7),
            completion: ResidentDeviceCompletion::Metal,
        });
    }

    let command_attempts = (0..encoded.command_count)
        .map(|index| word(layout.command_attempt_base + index))
        .collect::<Vec<_>>();
    let mut intents = Vec::with_capacity(intent_count);
    for index in 0..intent_count {
        let base = layout.intent_base + index * METAL_DELETE_INTENT_WORDS;
        let source_row = u32::try_from(word(base)).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE intent source row exceeds u32",
            )
        })?;
        let command = u16::try_from(word(base + 1)).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE intent command exceeds u16",
            )
        })?;
        let target_kind = match word(base + 2) {
            1 => EntityKind::Relationship,
            2 => EntityKind::Node,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal DELETE intent has an unknown entity kind",
                ));
            }
        };
        let origin = match word(base + 4) {
            1 => ResidentDeleteIntentOrigin::Explicit,
            2 => ResidentDeleteIntentOrigin::DetachIncident,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal DELETE intent has an unknown origin",
                ));
            }
        };
        intents.push(ResidentDeleteIntent {
            source_row,
            command,
            target_kind,
            target_id: word(base + 3),
            origin,
        });
    }

    let mut read_dependencies = Vec::with_capacity(dependency_count);
    for index in 0..dependency_count {
        let base = layout.dependency_base + index * METAL_DELETE_DEPENDENCY_WORDS;
        let dense = u32::try_from(word(base + 1)).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE dependency dense row exceeds u32",
            )
        })?;
        read_dependencies.push(match word(base) {
            1 => ResidentMutationReadDependency::Node(dense),
            2 => ResidentMutationReadDependency::Relationship(dense),
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal DELETE dependency has an unknown entity kind",
                ));
            }
        });
    }

    let final_relation = match (&request.continuation, word(23)) {
        (None, 0) if final_rows == 0 => None,
        (Some(continuation), 1)
            if final_rows <= continuation.maximum_output_rows
                && final_rows <= continuation.maximum_output_cells =>
        {
            let mut values = Vec::with_capacity(final_rows);
            let mut validity = Vec::with_capacity(final_rows);
            for row in 0..final_rows {
                values.push(word(layout.final_value_base + row) as i64);
                validity.push(
                    u8::try_from(word(layout.final_validity_base + row)).map_err(|_| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal DELETE final validity exceeds u8",
                        )
                    })?,
                );
            }
            Some(ResidentDeleteFinalRelation {
                row_count: final_rows,
                values,
                validity,
            })
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal DELETE final relation contradicts its continuation contract",
            ));
        }
    };
    ResidentDeleteResult::completed(
        request,
        ResidentDeviceCompletion::Metal,
        selected_rows,
        command_attempts,
        intents,
        read_dependencies,
        receipts,
        final_relation,
    )
}

#[derive(Clone, Debug)]
struct EncodedMetalNullableRelation {
    words: Vec<u64>,
    label_lanes: Vec<LabelId>,
    property_lanes: Vec<ResidentNullableRelationPropertyLane>,
    candidate_filters_by_stage: Vec<Vec<usize>>,
    candidate_filters_by_group: Vec<Vec<usize>>,
    relation_filters_after: Vec<Vec<usize>>,
    optional_groups: Vec<(usize, usize)>,
    final_columns: Vec<ResidentNullableRelationOutputSource>,
}

#[derive(Clone, Copy, Debug)]
struct MetalNullableRelationGraphLayout {
    word_count: usize,
    node_active_base: usize,
    node_layer_base: usize,
    label_base: usize,
    edge_active_base: usize,
    edge_layer_base: usize,
    edge_type_base: usize,
    edge_source_base: usize,
    edge_target_base: usize,
    outgoing_offset_base: usize,
    outgoing_neighbor_base: usize,
    outgoing_edge_base: usize,
    outgoing_count: usize,
    outgoing_overlay_base: usize,
    outgoing_overlay_word_count: usize,
    outgoing_overlay_row_count: usize,
    incoming_offset_base: usize,
    incoming_neighbor_base: usize,
    incoming_edge_base: usize,
    incoming_count: usize,
    incoming_overlay_base: usize,
    incoming_overlay_word_count: usize,
    incoming_overlay_row_count: usize,
    node_integer_value_base: usize,
    node_integer_validity_base: usize,
    node_integer_count: usize,
    node_float_value_base: usize,
    node_float_validity_base: usize,
    node_float_count: usize,
    node_string_value_base: usize,
    node_string_validity_base: usize,
    node_string_count: usize,
    edge_integer_value_base: usize,
    edge_integer_validity_base: usize,
    edge_integer_count: usize,
    edge_float_value_base: usize,
    edge_float_validity_base: usize,
    edge_float_count: usize,
    edge_string_value_base: usize,
    edge_string_validity_base: usize,
    edge_string_count: usize,
    node_string_offset_base: usize,
    node_string_offset_count: usize,
    node_string_byte_base: usize,
    node_string_byte_count: usize,
    edge_string_offset_base: usize,
    edge_string_offset_count: usize,
    edge_string_byte_base: usize,
    edge_string_byte_count: usize,
    property_descriptor_base: usize,
    property_descriptor_count: usize,
}

#[derive(Clone, Copy, Debug)]
struct MetalNullableRelationOutputLayout {
    word_count: usize,
    column_base: usize,
    final_base: usize,
    final_row_capacity: usize,
    final_byte_count: usize,
    relation_a_base: usize,
    relation_b_base: usize,
    parent_relation_base: usize,
    lineage_a_base: usize,
    lineage_b_base: usize,
    maximum_relation_rows: usize,
    slot_map_base: usize,
    next_slot_map_base: usize,
    filter_truth_base: usize,
    filter_rank_base: usize,
    maximum_filter_rows: usize,
    control_base: usize,
}

fn metal_nullable_relation_hash_words(bytes: [u8; 32]) -> [u64; 4] {
    let mut words = [0_u64; 4];
    for (word, chunk) in words.iter_mut().zip(bytes.chunks_exact(8)) {
        let mut bytes = [0_u8; 8];
        bytes.copy_from_slice(chunk);
        *word = u64::from_le_bytes(bytes);
    }
    words
}

fn metal_nullable_relation_compare(operation: CompareOp) -> u64 {
    match operation {
        CompareOp::Eq => 0,
        CompareOp::NotEq => 1,
        CompareOp::Less => 2,
        CompareOp::LessOrEqual => 3,
        CompareOp::Greater => 4,
        CompareOp::GreaterOrEqual => 5,
    }
}

fn metal_nullable_relation_binding_kind(kind: ResidentNullableRelationBindingKind) -> u64 {
    match kind {
        ResidentNullableRelationBindingKind::Node => 1,
        ResidentNullableRelationBindingKind::Relationship => 2,
    }
}

fn metal_nullable_relation_property_lane_words(
    lanes: &[ResidentNullableRelationPropertyLane],
) -> Vec<u64> {
    let mut words = Vec::with_capacity(
        lanes
            .len()
            .saturating_mul(METAL_NULLABLE_RELATION_PROPERTY_LANE_WORDS),
    );
    for (global_lane, lane) in lanes.iter().enumerate() {
        let category_lane = lanes[..global_lane]
            .iter()
            .filter(|candidate| candidate.kind == lane.kind && candidate.shape == lane.shape)
            .count();
        words.extend([
            metal_nullable_relation_binding_kind(lane.kind),
            match lane.shape {
                ResidentNullableRelationPropertyShape::Integer => 1,
                ResidentNullableRelationPropertyShape::String => 2,
                ResidentNullableRelationPropertyShape::Float => 3,
            },
            lane.property.0,
            category_lane as u64,
            0,
            0,
            0,
            0,
        ]);
    }
    words
}

fn metal_nullable_relation_graph_property_lane_words(
    resident: &CandleResident,
    encoded: &EncodedMetalNullableRelation,
    layout: &MetalNullableRelationGraphLayout,
) -> Result<Vec<u64>> {
    let mut words = metal_nullable_relation_property_lane_words(&encoded.property_lanes);
    let mut cursor = layout
        .edge_string_byte_base
        .checked_add(layout.edge_string_byte_count)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable mixed-string graph layout overflow",
            )
        })?;
    for (index, lane) in encoded.property_lanes.iter().enumerate() {
        let descriptor = index * METAL_NULLABLE_RELATION_PROPERTY_LANE_WORDS;
        if let Some((column, rows)) = metal_nullable_relation_mixed_string_column(resident, lane) {
            let offset_count = rows.checked_add(1).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable mixed-string offset count overflow",
                )
            })?;
            let offsets_base = cursor;
            cursor = cursor.checked_add(offset_count).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable mixed-string offset layout overflow",
                )
            })?;
            let byte_base = cursor;
            let byte_count = column.bytes.as_ref().map_or(0, Tensor::elem_count);
            cursor = cursor.checked_add(byte_count).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable mixed-string byte layout overflow",
                )
            })?;
            words[descriptor + 4] = METAL_NULLABLE_STRING_STORAGE_MIXED;
            words[descriptor + 5] = offsets_base as u64;
            words[descriptor + 6] = byte_base as u64;
            words[descriptor + 7] = byte_count as u64;
        } else if lane.shape == ResidentNullableRelationPropertyShape::String {
            words[descriptor + 4] = METAL_NULLABLE_STRING_STORAGE_DICTIONARY;
        }
    }
    if cursor != layout.property_descriptor_base {
        return Err(Error::internal(
            "Metal nullable mixed-string sections disagree with the sealed graph layout",
        ));
    }
    Ok(words)
}

fn metal_nullable_relation_output_source_words(
    request: &ResidentNullableRelationRequest,
    source: &ResidentNullableRelationOutputSource,
    label_indices: &BTreeMap<LabelId, u64>,
    payload: &mut Vec<u64>,
    payload_base: usize,
) -> Result<[u64; METAL_NULLABLE_RELATION_OUTPUT_SOURCE_WORDS]> {
    let slot = source.slot();
    let kind = source.kind();
    if let ResidentNullableRelationOutputSource::EntityLabelPredicate { domain, .. } = source {
        let (domain_kind, domain_offset, domain_count) = match domain {
            ResidentNullableRelationEntityLabelDomain::Node(domain) => {
                encode_metal_nullable_node_domain(domain, label_indices, payload, payload_base)?
            }
            ResidentNullableRelationEntityLabelDomain::Relationship(domain) => {
                encode_metal_nullable_relationship_domain(domain, payload, payload_base)?
            }
        };
        return Ok([
            METAL_NULLABLE_OUTPUT_ENTITY_LABEL_PREDICATE,
            u64::from(slot.0),
            metal_nullable_relation_binding_kind(kind),
            domain_kind,
            domain_offset,
            domain_count,
            0,
        ]);
    }
    let (source_type, shape, property, maximum_bytes) = match source {
        ResidentNullableRelationOutputSource::Entity { .. } => {
            (METAL_NULLABLE_OUTPUT_ENTITY, None, u64::MAX, 0)
        }
        ResidentNullableRelationOutputSource::IntegerProperty { property, .. } => (
            METAL_NULLABLE_OUTPUT_INTEGER_PROPERTY,
            Some(ResidentNullableRelationPropertyShape::Integer),
            property.0,
            0,
        ),
        ResidentNullableRelationOutputSource::FloatProperty { property, .. } => (
            METAL_NULLABLE_OUTPUT_FLOAT_PROPERTY,
            Some(ResidentNullableRelationPropertyShape::Float),
            property.0,
            0,
        ),
        ResidentNullableRelationOutputSource::StringProperty {
            property,
            maximum_bytes,
            ..
        } => (
            METAL_NULLABLE_OUTPUT_STRING_PROPERTY,
            Some(ResidentNullableRelationPropertyShape::String),
            property.0,
            u64::from(*maximum_bytes),
        ),
        ResidentNullableRelationOutputSource::NullProperty { .. } => {
            (METAL_NULLABLE_OUTPUT_NULL_PROPERTY, None, u64::MAX, 0)
        }
        ResidentNullableRelationOutputSource::RelationshipType { .. } => {
            (METAL_NULLABLE_OUTPUT_RELATIONSHIP_TYPE, None, u64::MAX, 0)
        }
        ResidentNullableRelationOutputSource::StringPropertyToInteger { property, .. } => (
            METAL_NULLABLE_OUTPUT_STRING_PROPERTY_TO_INTEGER,
            Some(ResidentNullableRelationPropertyShape::String),
            property.0,
            0,
        ),
        ResidentNullableRelationOutputSource::IntegerPropertyToFloat { property, .. } => (
            METAL_NULLABLE_OUTPUT_INTEGER_PROPERTY_TO_FLOAT,
            Some(ResidentNullableRelationPropertyShape::Integer),
            property.0,
            0,
        ),
        ResidentNullableRelationOutputSource::IntegerPropertyToString { property, .. } => (
            METAL_NULLABLE_OUTPUT_INTEGER_PROPERTY_TO_STRING,
            Some(ResidentNullableRelationPropertyShape::Integer),
            property.0,
            u64::from(RESIDENT_NULLABLE_RELATION_INTEGER_STRING_MAXIMUM_BYTES),
        ),
        ResidentNullableRelationOutputSource::EntityLabelPredicate { .. } => {
            unreachable!("entity label outputs return after encoding their exact domain")
        }
    };
    let (category_lane, global_lane) = if let Some(shape) = shape {
        let global_lane = request.output_property_lane_index(source)?.ok_or_else(|| {
            Error::internal("validated nullable output property omitted its sealed lane")
        })? as usize;
        let lane = request.property_lanes().get(global_lane).ok_or_else(|| {
            Error::internal("validated nullable output property lane disappeared")
        })?;
        if lane.kind != kind || lane.shape != shape || lane.property.0 != property {
            return Err(Error::internal(
                "validated nullable output property lane changed physical identity",
            ));
        }
        let category_lane = request.property_lanes()[..global_lane]
            .iter()
            .filter(|candidate| candidate.kind == kind && candidate.shape == shape)
            .count();
        (category_lane as u64, global_lane as u64)
    } else {
        (u64::MAX, u64::MAX)
    };
    Ok([
        source_type,
        u64::from(slot.0),
        metal_nullable_relation_binding_kind(kind),
        category_lane,
        global_lane,
        property,
        maximum_bytes,
    ])
}

fn metal_nullable_relation_collect_predicate_labels(
    predicate: &ResidentNullableRelationPredicate,
    labels: &mut BTreeSet<LabelId>,
) {
    match predicate {
        ResidentNullableRelationPredicate::HasLabels {
            labels: ResidentNullableNodeDomain::Known(required),
            ..
        } => labels.extend(required.iter().copied()),
        ResidentNullableRelationPredicate::Not(operand) => {
            metal_nullable_relation_collect_predicate_labels(operand, labels);
        }
        ResidentNullableRelationPredicate::And(left, right)
        | ResidentNullableRelationPredicate::Or(left, right) => {
            metal_nullable_relation_collect_predicate_labels(left, labels);
            metal_nullable_relation_collect_predicate_labels(right, labels);
        }
        ResidentNullableRelationPredicate::Constant(_)
        | ResidentNullableRelationPredicate::IsNull { .. }
        | ResidentNullableRelationPredicate::HasLabels { .. }
        | ResidentNullableRelationPredicate::CompareInteger { .. }
        | ResidentNullableRelationPredicate::CompareString { .. }
        | ResidentNullableRelationPredicate::RelationshipEndpoint { .. } => {}
    }
}

fn metal_nullable_relation_predicate_instruction_count(
    predicate: &ResidentNullableRelationPredicate,
) -> Result<usize> {
    let add = |left: usize, right: usize| {
        left.checked_add(right).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable predicate instruction count overflow",
            )
        })
    };
    match predicate {
        ResidentNullableRelationPredicate::Constant(_)
        | ResidentNullableRelationPredicate::HasLabels { .. }
        | ResidentNullableRelationPredicate::RelationshipEndpoint { .. } => Ok(1),
        ResidentNullableRelationPredicate::IsNull { .. } => Ok(2),
        ResidentNullableRelationPredicate::CompareInteger { .. }
        | ResidentNullableRelationPredicate::CompareString { .. } => Ok(3),
        ResidentNullableRelationPredicate::Not(operand) => add(
            metal_nullable_relation_predicate_instruction_count(operand)?,
            1,
        ),
        ResidentNullableRelationPredicate::And(left, right)
        | ResidentNullableRelationPredicate::Or(left, right) => add(
            add(
                metal_nullable_relation_predicate_instruction_count(left)?,
                metal_nullable_relation_predicate_instruction_count(right)?,
            )?,
            1,
        ),
    }
}

fn encode_metal_nullable_predicate_value(
    request: &ResidentNullableRelationRequest,
    value: &ResidentNullableRelationPredicateValue,
    instructions: &mut Vec<[u64; METAL_NULLABLE_RELATION_PREDICATE_WORDS]>,
    payload: &mut Vec<u64>,
    payload_base: usize,
) -> Result<()> {
    let mut instruction = [0_u64; METAL_NULLABLE_RELATION_PREDICATE_WORDS];
    match value {
        ResidentNullableRelationPredicateValue::Null => {
            instruction[0] = METAL_NULLABLE_PREDICATE_NULL;
        }
        ResidentNullableRelationPredicateValue::Boolean(value) => {
            instruction[0] = METAL_NULLABLE_PREDICATE_BOOLEAN;
            instruction[1] = u64::from(*value);
        }
        ResidentNullableRelationPredicateValue::Integer(value) => {
            instruction[0] = METAL_NULLABLE_PREDICATE_INTEGER;
            instruction[1] = *value as u64;
        }
        ResidentNullableRelationPredicateValue::String(value) => {
            instruction[0] = METAL_NULLABLE_PREDICATE_STRING;
            instruction[1] = u64::try_from(payload_base + payload.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable string literal offset exceeds u64",
                )
            })?;
            instruction[2] = value.len() as u64;
            payload.extend(value.as_bytes().iter().map(|byte| u64::from(*byte)));
        }
        ResidentNullableRelationPredicateValue::Binding { slot, kind } => {
            instruction[0] = METAL_NULLABLE_PREDICATE_BINDING;
            instruction[1] = u64::from(slot.0);
            instruction[2] = metal_nullable_relation_binding_kind(*kind);
        }
        ResidentNullableRelationPredicateValue::IntegerProperty {
            slot,
            kind,
            property: _,
        }
        | ResidentNullableRelationPredicateValue::StringProperty {
            slot,
            kind,
            property: _,
        } => {
            let shape = if matches!(
                value,
                ResidentNullableRelationPredicateValue::IntegerProperty { .. }
            ) {
                ResidentNullableRelationPropertyShape::Integer
            } else {
                ResidentNullableRelationPropertyShape::String
            };
            instruction[0] = if shape == ResidentNullableRelationPropertyShape::Integer {
                METAL_NULLABLE_PREDICATE_INTEGER_PROPERTY
            } else {
                METAL_NULLABLE_PREDICATE_STRING_PROPERTY
            };
            instruction[1] = u64::from(slot.0);
            instruction[2] = metal_nullable_relation_binding_kind(*kind);
            let global_lane = request.property_lane_index(value)?.ok_or_else(|| {
                Error::internal("validated nullable property reference omitted its sealed lane")
            })? as usize;
            let lane = request.property_lanes().get(global_lane).ok_or_else(|| {
                Error::internal("validated nullable property lane index disappeared")
            })?;
            if lane.kind != *kind || lane.shape != shape {
                return Err(Error::internal(
                    "validated nullable property lane changed physical shape",
                ));
            }
            let category_lane = request.property_lanes()[..global_lane]
                .iter()
                .filter(|candidate| candidate.kind == *kind && candidate.shape == shape)
                .count();
            instruction[3] = category_lane as u64;
            instruction[4] = global_lane as u64;
        }
    }
    instructions.push(instruction);
    Ok(())
}

fn encode_metal_nullable_predicate(
    request: &ResidentNullableRelationRequest,
    predicate: &ResidentNullableRelationPredicate,
    label_indices: &BTreeMap<LabelId, u64>,
    instructions: &mut Vec<[u64; METAL_NULLABLE_RELATION_PREDICATE_WORDS]>,
    payload: &mut Vec<u64>,
    payload_base: usize,
) -> Result<()> {
    let mut operation = [0_u64; METAL_NULLABLE_RELATION_PREDICATE_WORDS];
    match predicate {
        ResidentNullableRelationPredicate::Constant(value) => {
            return encode_metal_nullable_predicate_value(
                request,
                &match value {
                    Some(value) => ResidentNullableRelationPredicateValue::Boolean(*value),
                    None => ResidentNullableRelationPredicateValue::Null,
                },
                instructions,
                payload,
                payload_base,
            );
        }
        ResidentNullableRelationPredicate::IsNull { value, negated } => {
            encode_metal_nullable_predicate_value(
                request,
                value,
                instructions,
                payload,
                payload_base,
            )?;
            operation[0] = METAL_NULLABLE_PREDICATE_IS_NULL;
            operation[1] = u64::from(*negated);
        }
        ResidentNullableRelationPredicate::HasLabels { node, labels } => {
            operation[0] = METAL_NULLABLE_PREDICATE_HAS_LABELS;
            operation[1] = u64::from(node.0);
            let domain =
                encode_metal_nullable_node_domain(labels, label_indices, payload, payload_base)?;
            operation[2] = domain.0;
            operation[3] = domain.1;
            operation[4] = domain.2;
        }
        ResidentNullableRelationPredicate::CompareInteger {
            left,
            operation: compare,
            right,
        }
        | ResidentNullableRelationPredicate::CompareString {
            left,
            operation: compare,
            right,
        } => {
            encode_metal_nullable_predicate_value(
                request,
                left,
                instructions,
                payload,
                payload_base,
            )?;
            encode_metal_nullable_predicate_value(
                request,
                right,
                instructions,
                payload,
                payload_base,
            )?;
            operation[0] = if matches!(
                predicate,
                ResidentNullableRelationPredicate::CompareInteger { .. }
            ) {
                METAL_NULLABLE_PREDICATE_COMPARE_INTEGER
            } else {
                METAL_NULLABLE_PREDICATE_COMPARE_STRING
            };
            operation[1] = metal_nullable_relation_compare(*compare);
        }
        ResidentNullableRelationPredicate::RelationshipEndpoint {
            relationship,
            node,
            endpoint,
        } => {
            operation[0] = METAL_NULLABLE_PREDICATE_RELATIONSHIP_ENDPOINT;
            operation[1] = u64::from(relationship.0);
            operation[2] = u64::from(node.0);
            operation[3] = *endpoint as u64;
        }
        ResidentNullableRelationPredicate::Not(operand) => {
            encode_metal_nullable_predicate(
                request,
                operand,
                label_indices,
                instructions,
                payload,
                payload_base,
            )?;
            operation[0] = METAL_NULLABLE_PREDICATE_NOT;
        }
        ResidentNullableRelationPredicate::And(left, right)
        | ResidentNullableRelationPredicate::Or(left, right) => {
            encode_metal_nullable_predicate(
                request,
                left,
                label_indices,
                instructions,
                payload,
                payload_base,
            )?;
            encode_metal_nullable_predicate(
                request,
                right,
                label_indices,
                instructions,
                payload,
                payload_base,
            )?;
            operation[0] = if matches!(predicate, ResidentNullableRelationPredicate::And(..)) {
                METAL_NULLABLE_PREDICATE_AND
            } else {
                METAL_NULLABLE_PREDICATE_OR
            };
        }
    }
    instructions.push(operation);
    Ok(())
}

fn encode_metal_nullable_relation_program(
    request: &ResidentNullableRelationRequest,
) -> Result<EncodedMetalNullableRelation> {
    request.validate()?;
    if request
        .predicate_program
        .filters
        .iter()
        .any(|filter| match filter.placement {
            ResidentNullableRelationFilterPlacement::RelationAfter { stage } => {
                usize::from(stage).saturating_add(1) >= request.program.stages.len()
            }
            ResidentNullableRelationFilterPlacement::OptionalCandidates { stage } => {
                usize::from(stage) >= request.program.stages.len()
            }
            ResidentNullableRelationFilterPlacement::OptionalGroupCandidates { .. } => false,
        })
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal nullable predicates currently require a complete materialized relation boundary",
        ));
    }
    let mut labels = BTreeSet::<LabelId>::new();
    for stage in &request.program.stages {
        match stage {
            ResidentNullableRelationStage::NodeScan {
                labels: ResidentNullableNodeDomain::Known(stage_labels),
                ..
            } => labels.extend(stage_labels.iter().copied()),
            ResidentNullableRelationStage::Expand {
                source_labels: ResidentNullableNodeDomain::Known(source_labels),
                target_labels: ResidentNullableNodeDomain::Known(stage_labels),
                ..
            } => {
                labels.extend(source_labels.iter().copied());
                labels.extend(stage_labels.iter().copied());
            }
            ResidentNullableRelationStage::Expand {
                source_labels: ResidentNullableNodeDomain::Known(source_labels),
                ..
            } => labels.extend(source_labels.iter().copied()),
            ResidentNullableRelationStage::Expand {
                target_labels: ResidentNullableNodeDomain::Known(stage_labels),
                ..
            } => labels.extend(stage_labels.iter().copied()),
            _ => {}
        }
    }
    for filter in &request.predicate_program.filters {
        metal_nullable_relation_collect_predicate_labels(&filter.predicate, &mut labels);
    }
    for stage in &request.program.stages {
        let ResidentNullableRelationStage::FinalProject { bindings } = stage else {
            continue;
        };
        for binding in bindings {
            if let ResidentNullableRelationOutputSource::EntityLabelPredicate {
                domain:
                    ResidentNullableRelationEntityLabelDomain::Node(ResidentNullableNodeDomain::Known(
                        required,
                    )),
                ..
            } = &binding.source
            {
                labels.extend(required.iter().copied());
            }
        }
    }
    let label_lanes = labels.into_iter().collect::<Vec<_>>();
    let label_indices = label_lanes
        .iter()
        .enumerate()
        .map(|(index, label)| (*label, index as u64))
        .collect::<BTreeMap<_, _>>();
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal nullable-relation program image overflow",
        )
    };
    let instruction_count =
        request
            .predicate_program
            .filters
            .iter()
            .try_fold(0_usize, |total, filter| {
                total
                    .checked_add(metal_nullable_relation_predicate_instruction_count(
                        &filter.predicate,
                    )?)
                    .ok_or_else(overflow)
            })?;
    let stage_descriptor_words = request
        .program
        .stages
        .len()
        .checked_mul(METAL_NULLABLE_RELATION_STAGE_WORDS)
        .ok_or_else(overflow)?;
    let filter_descriptor_words = request
        .predicate_program
        .filters
        .len()
        .checked_mul(METAL_NULLABLE_RELATION_FILTER_WORDS)
        .ok_or_else(overflow)?;
    let optional_group_descriptor_words = request
        .predicate_program
        .optional_groups
        .len()
        .checked_mul(METAL_NULLABLE_RELATION_OPTIONAL_GROUP_WORDS)
        .ok_or_else(overflow)?;
    let predicate_words = instruction_count
        .checked_mul(METAL_NULLABLE_RELATION_PREDICATE_WORDS)
        .ok_or_else(overflow)?;
    let property_descriptor_words = request
        .property_lanes()
        .len()
        .checked_mul(METAL_NULLABLE_RELATION_PROPERTY_LANE_WORDS)
        .ok_or_else(overflow)?;
    let filter_descriptor_base = METAL_NULLABLE_RELATION_PROGRAM_HEADER_WORDS
        .checked_add(stage_descriptor_words)
        .ok_or_else(overflow)?;
    let optional_group_descriptor_base = filter_descriptor_base
        .checked_add(filter_descriptor_words)
        .ok_or_else(overflow)?;
    let instruction_base = optional_group_descriptor_base
        .checked_add(optional_group_descriptor_words)
        .ok_or_else(overflow)?;
    let property_descriptor_base = instruction_base
        .checked_add(predicate_words)
        .ok_or_else(overflow)?;
    let payload_base = property_descriptor_base
        .checked_add(property_descriptor_words)
        .ok_or_else(overflow)?;
    let mut descriptors = Vec::<[u64; METAL_NULLABLE_RELATION_STAGE_WORDS]>::with_capacity(
        request.program.stages.len(),
    );
    let mut payload = Vec::<u64>::new();
    let mut slot_kinds =
        BTreeMap::<ResidentNullableRelationSlot, ResidentNullableRelationBindingKind>::new();
    let mut final_columns = None;

    for (index, stage) in request.program.stages.iter().enumerate() {
        let obligation =
            request.obligation_for(ResidentNullableRelationProofAction::Stage(index))?;
        let mut descriptor = [0_u64; METAL_NULLABLE_RELATION_STAGE_WORDS];
        match stage {
            ResidentNullableRelationStage::NodeScan {
                mode,
                output,
                labels,
            } => {
                descriptor[0] = METAL_NULLABLE_RELATION_STAGE_NODE_SCAN;
                descriptor[1] = *mode as u64;
                descriptor[2] = u64::from(output.0);
                let domain = encode_metal_nullable_node_domain(
                    labels,
                    &label_indices,
                    &mut payload,
                    payload_base,
                )?;
                descriptor[7] = domain.0;
                descriptor[8] = domain.1;
                descriptor[9] = domain.2;
                if slot_kinds
                    .insert(*output, ResidentNullableRelationBindingKind::Node)
                    .is_some()
                {
                    return Err(Error::internal(
                        "validated nullable node scan reused a slot during encoding",
                    ));
                }
            }
            ResidentNullableRelationStage::Expand {
                mode,
                uniqueness_group,
                source,
                source_labels,
                relationship,
                different_from,
                target,
                direction,
                relationship_types,
                target_labels,
            } => {
                descriptor[0] = METAL_NULLABLE_RELATION_STAGE_EXPAND;
                descriptor[1] = *mode as u64;
                descriptor[2] = u64::from(source.0);
                descriptor[3] = relationship.map_or(u64::MAX, |slot| u64::from(slot.0));
                let (target_kind, target_slot) = match target {
                    ResidentNullableRelationTarget::Existing(slot) => (0, *slot),
                    ResidentNullableRelationTarget::Introduce(slot) => (1, *slot),
                };
                descriptor[4] = target_kind;
                descriptor[5] = u64::from(target_slot.0);
                descriptor[6] = match direction {
                    super::ResidentDirection::Outgoing => 1,
                    super::ResidentDirection::Incoming => 2,
                    super::ResidentDirection::Undirected => 3,
                };
                let relationship_domain = encode_metal_nullable_relationship_domain(
                    relationship_types,
                    &mut payload,
                    payload_base,
                )?;
                descriptor[7] = relationship_domain.0;
                descriptor[8] = relationship_domain.1;
                descriptor[9] = relationship_domain.2;
                let target_domain = encode_metal_nullable_node_domain(
                    target_labels,
                    &label_indices,
                    &mut payload,
                    payload_base,
                )?;
                descriptor[10] = target_domain.0;
                descriptor[11] = target_domain.1;
                descriptor[12] = target_domain.2;
                descriptor[13] = u64::try_from(payload_base + payload.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal nullable DifferentRelationships payload offset exceeds u64",
                    )
                })?;
                descriptor[14] = different_from.len() as u64;
                payload.push(u64::from(*uniqueness_group));
                for slot in different_from {
                    if slot_kinds.get(slot).copied()
                        != Some(ResidentNullableRelationBindingKind::Relationship)
                    {
                        return Err(Error::internal(
                            "validated nullable DifferentRelationships slot kind disappeared",
                        ));
                    }
                    payload.push(u64::from(slot.0));
                }
                let source_domain_metadata = payload.len();
                payload.extend([0, 0, 0]);
                let source_domain = encode_metal_nullable_node_domain(
                    source_labels,
                    &label_indices,
                    &mut payload,
                    payload_base,
                )?;
                payload[source_domain_metadata] = source_domain.0;
                payload[source_domain_metadata + 1] = source_domain.1;
                payload[source_domain_metadata + 2] = source_domain.2;
                if let Some(relationship) = relationship {
                    match slot_kinds.get(relationship).copied() {
                        Some(ResidentNullableRelationBindingKind::Relationship) => {}
                        Some(ResidentNullableRelationBindingKind::Node) => {
                            return Err(Error::internal(
                                "validated nullable relationship slot changed to a node during encoding",
                            ));
                        }
                        None => {
                            slot_kinds.insert(
                                *relationship,
                                ResidentNullableRelationBindingKind::Relationship,
                            );
                        }
                    }
                }
                if target_kind == 1
                    && slot_kinds
                        .insert(target_slot, ResidentNullableRelationBindingKind::Node)
                        .is_some()
                {
                    return Err(Error::internal(
                        "validated nullable expansion reused a target slot during encoding",
                    ));
                }
            }
            ResidentNullableRelationStage::ScopeProject { bindings } => {
                descriptor[0] = METAL_NULLABLE_RELATION_STAGE_SCOPE_PROJECT;
                descriptor[1] = bindings[0].row_limit.map_or(u64::MAX, u64::from);
                descriptor[13] = u64::try_from(payload_base + payload.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal nullable projection payload offset exceeds u64",
                    )
                })?;
                descriptor[14] = bindings.len() as u64;
                let prior = slot_kinds.clone();
                let mut projected = BTreeMap::new();
                for binding in bindings {
                    let kind = prior.get(&binding.source).copied().ok_or_else(|| {
                        Error::internal("nullable projection source kind disappeared")
                    })?;
                    payload.extend([u64::from(binding.source.0), u64::from(binding.output.0)]);
                    projected.insert(binding.output, kind);
                }
                slot_kinds = projected;
            }
            ResidentNullableRelationStage::FinalProject { bindings } => {
                descriptor[0] = METAL_NULLABLE_RELATION_STAGE_FINAL_PROJECT;
                descriptor[13] = u64::try_from(payload_base + payload.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal nullable final payload offset exceeds u64",
                    )
                })?;
                descriptor[14] = bindings.len() as u64;
                let descriptor_base = payload.len();
                let descriptor_words = bindings
                    .len()
                    .checked_mul(METAL_NULLABLE_RELATION_OUTPUT_SOURCE_WORDS)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "Metal nullable final descriptor size overflow",
                        )
                    })?;
                payload.resize(
                    descriptor_base
                        .checked_add(descriptor_words)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "Metal nullable final descriptor offset overflow",
                            )
                        })?,
                    0,
                );
                let columns = bindings
                    .iter()
                    .enumerate()
                    .map(|(column, binding)| {
                        let source = &binding.source;
                        let slot = source.slot();
                        let kind = slot_kinds.get(&slot).copied().ok_or_else(|| {
                            Error::internal("nullable final source kind disappeared")
                        })?;
                        if kind != source.kind() {
                            return Err(Error::internal(
                                "nullable final source kind changed during Metal encoding",
                            ));
                        }
                        let words = metal_nullable_relation_output_source_words(
                            request,
                            source,
                            &label_indices,
                            &mut payload,
                            payload_base,
                        )?;
                        let start =
                            descriptor_base + column * METAL_NULLABLE_RELATION_OUTPUT_SOURCE_WORDS;
                        payload[start..start + METAL_NULLABLE_RELATION_OUTPUT_SOURCE_WORDS]
                            .copy_from_slice(&words);
                        Ok(source.clone())
                    })
                    .collect::<Result<Vec<_>>>()?;
                final_columns = Some(columns);
            }
        }
        descriptor[15] = obligation.id;
        descriptor[16] = u64::from(obligation.stage);
        descriptor[17] = obligation.kind as u64;
        descriptor[18] = u64::from(request.capacities.stage_input_rows[index]);
        descriptor[19] = u64::from(request.capacities.stage_candidate_rows[index]);
        descriptor[20] = u64::from(request.capacities.stage_output_rows[index]);
        descriptor[21] = u64::from(request.capacities.stage_live_bindings[index]);
        descriptors.push(descriptor);
    }
    let mut filter_descriptors = Vec::<[u64; METAL_NULLABLE_RELATION_FILTER_WORDS]>::with_capacity(
        request.predicate_program.filters.len(),
    );
    let mut predicate_instructions =
        Vec::<[u64; METAL_NULLABLE_RELATION_PREDICATE_WORDS]>::with_capacity(instruction_count);
    let mut candidate_filters_by_stage = vec![Vec::new(); request.program.stages.len()];
    let mut candidate_filters_by_group =
        vec![Vec::new(); request.predicate_program.optional_groups.len()];
    let mut relation_filters_after = vec![Vec::new(); request.program.stages.len()];
    for (index, filter) in request.predicate_program.filters.iter().enumerate() {
        let (placement, stage_index) = match filter.placement {
            ResidentNullableRelationFilterPlacement::RelationAfter { stage } => {
                let stage = usize::from(stage);
                relation_filters_after
                    .get_mut(stage)
                    .ok_or_else(|| Error::internal("Metal relation-filter stage disappeared"))?
                    .push(index);
                (METAL_NULLABLE_RELATION_FILTER_AFTER, stage)
            }
            ResidentNullableRelationFilterPlacement::OptionalCandidates { stage } => {
                let stage = usize::from(stage);
                candidate_filters_by_stage
                    .get_mut(stage)
                    .ok_or_else(|| Error::internal("Metal candidate-filter stage disappeared"))?
                    .push(index);
                (METAL_NULLABLE_RELATION_FILTER_OPTIONAL_CANDIDATES, stage)
            }
            ResidentNullableRelationFilterPlacement::OptionalGroupCandidates { group } => {
                let group = usize::from(group);
                candidate_filters_by_group
                    .get_mut(group)
                    .ok_or_else(|| {
                        Error::internal("Metal OPTIONAL-group filter target disappeared")
                    })?
                    .push(index);
                (METAL_NULLABLE_RELATION_FILTER_OPTIONAL_GROUP, group)
            }
        };
        let obligation =
            request.obligation_for(ResidentNullableRelationProofAction::Filter(index))?;
        let first_instruction = predicate_instructions.len();
        encode_metal_nullable_predicate(
            request,
            &filter.predicate,
            &label_indices,
            &mut predicate_instructions,
            &mut payload,
            payload_base,
        )?;
        let count = predicate_instructions
            .len()
            .checked_sub(first_instruction)
            .ok_or_else(overflow)?;
        let mut descriptor = [0_u64; METAL_NULLABLE_RELATION_FILTER_WORDS];
        descriptor[0] = placement;
        descriptor[1] = stage_index as u64;
        descriptor[2] = u64::try_from(
            instruction_base
                .checked_add(
                    first_instruction
                        .checked_mul(METAL_NULLABLE_RELATION_PREDICATE_WORDS)
                        .ok_or_else(overflow)?,
                )
                .ok_or_else(overflow)?,
        )
        .map_err(|_| overflow())?;
        descriptor[3] = count as u64;
        descriptor[4] = obligation.id;
        descriptor[5] = u64::from(obligation.stage);
        descriptor[6] = obligation.kind as u64;
        filter_descriptors.push(descriptor);
    }
    let mut optional_group_descriptors =
        Vec::<[u64; METAL_NULLABLE_RELATION_OPTIONAL_GROUP_WORDS]>::with_capacity(
            request.predicate_program.optional_groups.len(),
        );
    let mut optional_groups = Vec::with_capacity(request.predicate_program.optional_groups.len());
    for (index, group) in request.predicate_program.optional_groups.iter().enumerate() {
        let introduced = request.optional_group_introduced_bindings(index)?;
        let obligation =
            request.obligation_for(ResidentNullableRelationProofAction::OptionalGroup(index))?;
        let mut descriptor = [0_u64; METAL_NULLABLE_RELATION_OPTIONAL_GROUP_WORDS];
        descriptor[0] = u64::from(group.first_stage);
        descriptor[1] = u64::from(group.last_stage);
        descriptor[2] = u64::try_from(payload_base + payload.len()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable OPTIONAL-group payload offset exceeds u64",
            )
        })?;
        descriptor[3] = introduced.len() as u64;
        descriptor[4] = obligation.id;
        descriptor[5] = u64::from(obligation.stage);
        descriptor[6] = obligation.kind as u64;
        for (slot, kind) in introduced {
            payload.extend([
                u64::from(slot.0),
                metal_nullable_relation_binding_kind(kind),
            ]);
        }
        optional_group_descriptors.push(descriptor);
        optional_groups.push((
            usize::from(group.first_stage),
            usize::from(group.last_stage),
        ));
    }
    if predicate_instructions.len() != instruction_count {
        return Err(Error::internal(
            "Metal nullable predicate instruction count changed during encoding",
        ));
    }
    let final_columns = final_columns
        .ok_or_else(|| Error::internal("nullable relation encoder omitted final columns"))?;
    let word_count = payload_base.checked_add(payload.len()).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal nullable-relation program size overflow",
        )
    })?;
    let mut words = Vec::with_capacity(word_count);
    words.extend([
        METAL_NULLABLE_RELATION_PROGRAM_MAGIC,
        METAL_NULLABLE_RELATION_VERSION,
        request.program.stages.len() as u64,
        word_count as u64,
        label_lanes.len() as u64,
        u64::from(request.program.layers.bits()),
        u64::from(request.capacities.binding_slot_count),
        u64::from(request.capacities.maximum_live_bindings),
        request.predicate_program.filters.len() as u64,
        instruction_count as u64,
        request.property_lanes().len() as u64,
        request
            .property_lanes()
            .iter()
            .filter(|lane| {
                lane.kind == ResidentNullableRelationBindingKind::Node
                    && lane.shape == ResidentNullableRelationPropertyShape::Integer
            })
            .count() as u64,
        request
            .property_lanes()
            .iter()
            .filter(|lane| {
                lane.kind == ResidentNullableRelationBindingKind::Node
                    && lane.shape == ResidentNullableRelationPropertyShape::String
            })
            .count() as u64,
        request
            .property_lanes()
            .iter()
            .filter(|lane| {
                lane.kind == ResidentNullableRelationBindingKind::Relationship
                    && lane.shape == ResidentNullableRelationPropertyShape::Integer
            })
            .count() as u64,
        request
            .property_lanes()
            .iter()
            .filter(|lane| {
                lane.kind == ResidentNullableRelationBindingKind::Relationship
                    && lane.shape == ResidentNullableRelationPropertyShape::String
            })
            .count() as u64,
        property_descriptor_base as u64,
        request.predicate_program.optional_groups.len() as u64,
        optional_group_descriptor_base as u64,
    ]);
    for descriptor in descriptors {
        words.extend(descriptor);
    }
    for descriptor in filter_descriptors {
        words.extend(descriptor);
    }
    for descriptor in optional_group_descriptors {
        words.extend(descriptor);
    }
    for instruction in predicate_instructions {
        words.extend(instruction);
    }
    words.extend(metal_nullable_relation_property_lane_words(
        request.property_lanes(),
    ));
    words.extend(payload);
    if words.len() != word_count
        || final_columns.len() != request.capacities.final_output_columns as usize
    {
        return Err(Error::internal(
            "Metal nullable-relation encoder produced an inconsistent image",
        ));
    }
    Ok(EncodedMetalNullableRelation {
        words,
        label_lanes,
        property_lanes: request.property_lanes().to_vec(),
        candidate_filters_by_stage,
        candidate_filters_by_group,
        relation_filters_after,
        optional_groups,
        final_columns,
    })
}

fn encode_metal_nullable_node_domain(
    domain: &ResidentNullableNodeDomain,
    label_indices: &BTreeMap<LabelId, u64>,
    payload: &mut Vec<u64>,
    payload_base: usize,
) -> Result<(u64, u64, u64)> {
    match domain {
        ResidentNullableNodeDomain::Any => Ok((METAL_NULLABLE_RELATION_DOMAIN_ANY, 0, 0)),
        ResidentNullableNodeDomain::Known(labels) => {
            let offset = u64::try_from(payload_base + payload.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable node-domain offset exceeds u64",
                )
            })?;
            for label in labels {
                payload.push(*label_indices.get(label).ok_or_else(|| {
                    Error::internal("Metal nullable node-domain lane disappeared")
                })?);
            }
            Ok((
                METAL_NULLABLE_RELATION_DOMAIN_KNOWN,
                offset,
                labels.len() as u64,
            ))
        }
        ResidentNullableNodeDomain::KnownEmpty => Ok((METAL_NULLABLE_RELATION_DOMAIN_EMPTY, 0, 0)),
    }
}

fn encode_metal_nullable_relationship_domain(
    domain: &ResidentNullableRelationshipDomain,
    payload: &mut Vec<u64>,
    payload_base: usize,
) -> Result<(u64, u64, u64)> {
    match domain {
        ResidentNullableRelationshipDomain::Any => Ok((METAL_NULLABLE_RELATION_DOMAIN_ANY, 0, 0)),
        ResidentNullableRelationshipDomain::Known(types) => {
            let offset = u64::try_from(payload_base + payload.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable relationship-domain offset exceeds u64",
                )
            })?;
            payload.extend(types.iter().map(|relationship_type| relationship_type.0));
            Ok((
                METAL_NULLABLE_RELATION_DOMAIN_KNOWN,
                offset,
                types.len() as u64,
            ))
        }
        ResidentNullableRelationshipDomain::KnownEmpty => {
            Ok((METAL_NULLABLE_RELATION_DOMAIN_EMPTY, 0, 0))
        }
    }
}

fn metal_nullable_relation_mixed_string_column<'a>(
    resident: &'a CandleResident,
    lane: &ResidentNullableRelationPropertyLane,
) -> Option<(&'a MixedColumn, usize)> {
    if lane.shape != ResidentNullableRelationPropertyShape::String {
        return None;
    }
    match lane.kind {
        ResidentNullableRelationBindingKind::Node
            if !resident.string_nodes.contains_key(&lane.property) =>
        {
            resident
                .mixed_nodes
                .get(&lane.property)
                .map(|column| (column, resident.node_count))
        }
        ResidentNullableRelationBindingKind::Relationship
            if !resident.string_edges.contains_key(&lane.property) =>
        {
            resident
                .mixed_edges
                .get(&lane.property)
                .map(|column| (column, resident.edge_count))
        }
        _ => None,
    }
}

fn metal_nullable_relation_graph_layout(
    resident: &CandleResident,
    encoded: &EncodedMetalNullableRelation,
) -> Result<MetalNullableRelationGraphLayout> {
    let adjacency_count =
        |neighbors: Option<&Tensor>, edges: Option<&Tensor>, name: &str| match (neighbors, edges) {
            (Some(neighbors), Some(edges)) if neighbors.elem_count() == edges.elem_count() => {
                Ok(neighbors.elem_count())
            }
            (None, None) => Ok(0),
            _ => Err(Error::new(
                ErrorCode::CorruptStorage,
                format!("resident nullable {name} adjacency lanes disagree"),
            )),
        };
    let outgoing_count = adjacency_count(
        resident.outgoing_neighbors.as_ref(),
        resident.outgoing_edges.as_ref(),
        "outgoing",
    )?;
    let incoming_count = adjacency_count(
        resident.incoming_neighbors.as_ref(),
        resident.incoming_edges.as_ref(),
        "incoming",
    )?;
    let outgoing_overlay_word_count = resident
        .outgoing_overlay
        .packet
        .as_ref()
        .map_or(0, Tensor::elem_count);
    let outgoing_overlay_row_count = resident.outgoing_overlay.rows.len();
    let incoming_overlay_word_count = resident
        .incoming_overlay
        .packet
        .as_ref()
        .map_or(0, Tensor::elem_count);
    let incoming_overlay_row_count = resident.incoming_overlay.rows.len();
    if (outgoing_overlay_row_count == 0) != (outgoing_overlay_word_count == 0)
        || (incoming_overlay_row_count == 0) != (incoming_overlay_word_count == 0)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident nullable CSR overlay rows and packet disagree",
        ));
    }
    let lane_count = |kind, shape| {
        encoded
            .property_lanes
            .iter()
            .filter(|lane| lane.kind == kind && lane.shape == shape)
            .count()
    };
    let node_integer_count = lane_count(
        ResidentNullableRelationBindingKind::Node,
        ResidentNullableRelationPropertyShape::Integer,
    );
    let node_float_count = lane_count(
        ResidentNullableRelationBindingKind::Node,
        ResidentNullableRelationPropertyShape::Float,
    );
    let node_string_count = lane_count(
        ResidentNullableRelationBindingKind::Node,
        ResidentNullableRelationPropertyShape::String,
    );
    let edge_integer_count = lane_count(
        ResidentNullableRelationBindingKind::Relationship,
        ResidentNullableRelationPropertyShape::Integer,
    );
    let edge_float_count = lane_count(
        ResidentNullableRelationBindingKind::Relationship,
        ResidentNullableRelationPropertyShape::Float,
    );
    let edge_string_count = lane_count(
        ResidentNullableRelationBindingKind::Relationship,
        ResidentNullableRelationPropertyShape::String,
    );
    let node_string_offset_count = (node_string_count != 0)
        .then(|| resident.node_string_dictionary.offsets.elem_count())
        .unwrap_or(0);
    let node_string_byte_count = (node_string_count != 0)
        .then(|| {
            resident
                .node_string_dictionary
                .bytes
                .as_ref()
                .map_or(0, Tensor::elem_count)
        })
        .unwrap_or(0);
    let edge_string_offset_count = (edge_string_count != 0)
        .then(|| resident.edge_string_dictionary.offsets.elem_count())
        .unwrap_or(0);
    let edge_string_byte_count = (edge_string_count != 0)
        .then(|| {
            resident
                .edge_string_dictionary
                .bytes
                .as_ref()
                .map_or(0, Tensor::elem_count)
        })
        .unwrap_or(0);
    let mut cursor = 0_usize;
    let mut take = |words: usize| -> Result<usize> {
        let base = cursor;
        cursor = cursor.checked_add(words).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable-relation graph image overflow",
            )
        })?;
        Ok(base)
    };
    let node_active_base = take(resident.node_count)?;
    let node_layer_base = take(resident.node_count)?;
    let label_base = take(
        resident
            .node_count
            .checked_mul(encoded.label_lanes.len())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable-relation label image overflow",
                )
            })?,
    )?;
    let edge_active_base = take(resident.edge_count)?;
    let edge_layer_base = take(resident.edge_count)?;
    let edge_type_base = take(resident.edge_count)?;
    let edge_source_base = take(resident.edge_count)?;
    let edge_target_base = take(resident.edge_count)?;
    let outgoing_offset_base = take(resident.node_count.saturating_add(1))?;
    let outgoing_neighbor_base = take(outgoing_count)?;
    let outgoing_edge_base = take(outgoing_count)?;
    let outgoing_overlay_base = take(outgoing_overlay_word_count)?;
    let incoming_offset_base = take(resident.node_count.saturating_add(1))?;
    let incoming_neighbor_base = take(incoming_count)?;
    let incoming_edge_base = take(incoming_count)?;
    let incoming_overlay_base = take(incoming_overlay_word_count)?;
    let node_integer_words = resident
        .node_count
        .checked_mul(node_integer_count)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable node-integer property image overflow",
            )
        })?;
    let node_float_words = resident
        .node_count
        .checked_mul(node_float_count)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable node-float property image overflow",
            )
        })?;
    let node_string_words = resident
        .node_count
        .checked_mul(node_string_count)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable node-string property image overflow",
            )
        })?;
    let edge_integer_words = resident
        .edge_count
        .checked_mul(edge_integer_count)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable relationship-integer property image overflow",
            )
        })?;
    let edge_float_words = resident
        .edge_count
        .checked_mul(edge_float_count)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable relationship-float property image overflow",
            )
        })?;
    let edge_string_words = resident
        .edge_count
        .checked_mul(edge_string_count)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable relationship-string property image overflow",
            )
        })?;
    let node_integer_value_base = take(node_integer_words)?;
    let node_integer_validity_base = take(node_integer_words)?;
    let node_float_value_base = take(node_float_words)?;
    let node_float_validity_base = take(node_float_words)?;
    let node_string_value_base = take(node_string_words)?;
    let node_string_validity_base = take(node_string_words)?;
    let edge_integer_value_base = take(edge_integer_words)?;
    let edge_integer_validity_base = take(edge_integer_words)?;
    let edge_float_value_base = take(edge_float_words)?;
    let edge_float_validity_base = take(edge_float_words)?;
    let edge_string_value_base = take(edge_string_words)?;
    let edge_string_validity_base = take(edge_string_words)?;
    let node_string_offset_base = take(node_string_offset_count)?;
    let node_string_byte_base = take(node_string_byte_count)?;
    let edge_string_offset_base = take(edge_string_offset_count)?;
    let edge_string_byte_base = take(edge_string_byte_count)?;
    for lane in &encoded.property_lanes {
        let Some((column, rows)) = metal_nullable_relation_mixed_string_column(resident, lane)
        else {
            continue;
        };
        if column.offsets.elem_count() != rows.saturating_add(1) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal nullable mixed-string offsets have a wrong row count",
            ));
        }
        take(column.offsets.elem_count())?;
        take(column.bytes.as_ref().map_or(0, Tensor::elem_count))?;
    }
    let property_descriptor_count = encoded.property_lanes.len();
    let property_descriptor_base = take(
        property_descriptor_count
            .checked_mul(METAL_NULLABLE_RELATION_PROPERTY_LANE_WORDS)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable property descriptor image overflow",
                )
            })?,
    )?;
    Ok(MetalNullableRelationGraphLayout {
        word_count: cursor,
        node_active_base,
        node_layer_base,
        label_base,
        edge_active_base,
        edge_layer_base,
        edge_type_base,
        edge_source_base,
        edge_target_base,
        outgoing_offset_base,
        outgoing_neighbor_base,
        outgoing_edge_base,
        outgoing_count,
        outgoing_overlay_base,
        outgoing_overlay_word_count,
        outgoing_overlay_row_count,
        incoming_offset_base,
        incoming_neighbor_base,
        incoming_edge_base,
        incoming_count,
        incoming_overlay_base,
        incoming_overlay_word_count,
        incoming_overlay_row_count,
        node_integer_value_base,
        node_integer_validity_base,
        node_integer_count,
        node_float_value_base,
        node_float_validity_base,
        node_float_count,
        node_string_value_base,
        node_string_validity_base,
        node_string_count,
        edge_integer_value_base,
        edge_integer_validity_base,
        edge_integer_count,
        edge_float_value_base,
        edge_float_validity_base,
        edge_float_count,
        edge_string_value_base,
        edge_string_validity_base,
        edge_string_count,
        node_string_offset_base,
        node_string_offset_count,
        node_string_byte_base,
        node_string_byte_count,
        edge_string_offset_base,
        edge_string_offset_count,
        edge_string_byte_base,
        edge_string_byte_count,
        property_descriptor_base,
        property_descriptor_count,
    })
}

fn metal_nullable_relation_graph_word_count(
    resident: &CandleResident,
    encoded: &EncodedMetalNullableRelation,
) -> Result<usize> {
    Ok(metal_nullable_relation_graph_layout(resident, encoded)?.word_count)
}

fn append_metal_nullable_i64(
    parts: &mut Vec<Tensor>,
    tensor: Option<&Tensor>,
    expected_words: usize,
    expected_dtype: DType,
    name: &str,
) -> Result<()> {
    if expected_words == 0 {
        if tensor.is_some_and(|tensor| tensor.elem_count() != 0) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                format!("empty nullable-relation {name} lane retained device values"),
            ));
        }
        return Ok(());
    }
    let tensor = tensor.ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            format!("nullable-relation {name} lane is absent"),
        )
    })?;
    if tensor.dtype() != expected_dtype
        || tensor.rank() != 1
        || tensor.elem_count() != expected_words
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            format!("nullable-relation {name} lane has an invalid tensor shape"),
        ));
    }
    parts.push(if expected_dtype == DType::I64 {
        tensor.clone()
    } else {
        tensor.to_dtype(DType::I64).map_err(candle_error)?
    });
    Ok(())
}

/// Appends the cold CSR offsets used by a nullable-relation query image and materializes only the
/// missing empty-row tail. New topology remains in the overlay, so this delta work is proportional
/// to nodes added after the cold CSR prefix and never rebuilds or copies the resident adjacency.
fn append_metal_nullable_csr_offsets(
    parts: &mut Vec<Tensor>,
    offsets: &Tensor,
    expected_words: usize,
    name: &str,
) -> Result<()> {
    let cold_words = offsets.elem_count();
    if offsets.dtype() != DType::U32
        || offsets.rank() != 1
        || cold_words == 0
        || cold_words > expected_words
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            format!("nullable-relation {name} lane has an invalid tensor shape"),
        ));
    }
    append_metal_nullable_i64(parts, Some(offsets), cold_words, DType::U32, name)?;
    let tail_words = expected_words - cold_words;
    if tail_words == 0 {
        return Ok(());
    }
    let tail = offsets
        .narrow(0, cold_words - 1, 1)
        .and_then(|terminal| terminal.broadcast_as(tail_words))
        .map_err(candle_error)?;
    append_metal_nullable_i64(parts, Some(&tail), tail_words, DType::U32, name)
}

fn metal_nullable_relation_max_relation_cells(
    request: &ResidentNullableRelationRequest,
) -> Result<usize> {
    request
        .capacities
        .stage_output_rows
        .iter()
        .zip(&request.capacities.stage_live_bindings)
        .try_fold(0_usize, |maximum, (rows, bindings)| {
            let rows = usize::try_from(*rows).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable-relation row count exceeds host addressability",
                )
            })?;
            let cells = rows.checked_mul(usize::from(*bindings)).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal nullable-relation relation image overflow",
                )
            })?;
            Ok(maximum.max(cells))
        })
}

fn metal_nullable_relation_output_words(
    request: &ResidentNullableRelationRequest,
    relation_cells: usize,
) -> Result<usize> {
    Ok(metal_nullable_relation_output_layout(request, relation_cells)?.word_count)
}

fn metal_nullable_relation_output_layout(
    request: &ResidentNullableRelationRequest,
    relation_cells: usize,
) -> Result<MetalNullableRelationOutputLayout> {
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal nullable-relation output image overflow",
        )
    };
    let mut cursor = METAL_NULLABLE_RELATION_HEADER_WORDS
        .checked_add(
            request
                .manifest
                .obligations
                .len()
                .checked_mul(METAL_NULLABLE_RELATION_RECEIPT_WORDS)
                .ok_or_else(overflow)?,
        )
        .ok_or_else(overflow)?;
    let column_base = cursor;
    cursor = cursor
        .checked_add(
            (request.capacities.final_output_columns as usize)
                .checked_mul(METAL_NULLABLE_RELATION_COLUMN_WORDS)
                .ok_or_else(overflow)?,
        )
        .ok_or_else(overflow)?;
    let final_base = cursor;
    let final_row_capacity = usize::try_from(
        request
            .capacities
            .stage_output_rows
            .last()
            .copied()
            .unwrap_or(0)
            .min(u64::from(request.capacities.max_output_rows)),
    )
    .map_err(|_| overflow())?;
    let final_byte_count = usize::try_from(request.capacities.final_output_bytes_per_row)
        .map_err(|_| overflow())?
        .checked_mul(final_row_capacity)
        .and_then(|bytes| {
            usize::try_from(request.capacities.final_output_fixed_bytes)
                .ok()
                .and_then(|fixed| bytes.checked_add(fixed))
        })
        .ok_or_else(overflow)?;
    let final_words = final_byte_count
        .checked_add(std::mem::size_of::<u64>() - 1)
        .ok_or_else(overflow)?
        / std::mem::size_of::<u64>();
    cursor = cursor.checked_add(final_words).ok_or_else(overflow)?;
    let relation_a_base = cursor;
    cursor = cursor.checked_add(relation_cells).ok_or_else(overflow)?;
    let relation_b_base = cursor;
    cursor = cursor.checked_add(relation_cells).ok_or_else(overflow)?;
    let parent_relation_base = cursor;
    cursor = cursor.checked_add(relation_cells).ok_or_else(overflow)?;
    let maximum_relation_rows = usize::try_from(
        request
            .capacities
            .stage_input_rows
            .iter()
            .chain(&request.capacities.stage_output_rows)
            .copied()
            .max()
            .unwrap_or(1)
            .max(1),
    )
    .map_err(|_| overflow())?;
    let lineage_a_base = cursor;
    cursor = cursor
        .checked_add(maximum_relation_rows)
        .ok_or_else(overflow)?;
    let lineage_b_base = cursor;
    cursor = cursor
        .checked_add(maximum_relation_rows)
        .ok_or_else(overflow)?;
    let slot_map_base = cursor;
    cursor = cursor
        .checked_add(request.capacities.binding_slot_count as usize)
        .ok_or_else(overflow)?;
    let next_slot_map_base = cursor;
    cursor = cursor
        .checked_add(request.capacities.binding_slot_count as usize)
        .ok_or_else(overflow)?;
    let maximum_filter_rows = if request.predicate_program.filters.is_empty() {
        0
    } else {
        usize::try_from(
            request
                .capacities
                .stage_output_rows
                .iter()
                .copied()
                .max()
                .unwrap_or(0),
        )
        .map_err(|_| overflow())?
    };
    let filter_truth_base = cursor;
    cursor = cursor
        .checked_add(maximum_filter_rows)
        .ok_or_else(overflow)?;
    let filter_rank_base = cursor;
    cursor = cursor
        .checked_add(maximum_filter_rows)
        .ok_or_else(overflow)?;
    let control_base = cursor;
    cursor = cursor
        .checked_add(METAL_NULLABLE_RELATION_CONTROL_WORDS)
        .ok_or_else(overflow)?;
    Ok(MetalNullableRelationOutputLayout {
        word_count: cursor,
        column_base,
        final_base,
        final_row_capacity,
        final_byte_count,
        relation_a_base,
        relation_b_base,
        parent_relation_base,
        lineage_a_base,
        lineage_b_base,
        maximum_relation_rows,
        slot_map_base,
        next_slot_map_base,
        filter_truth_base,
        filter_rank_base,
        maximum_filter_rows,
        control_base,
    })
}

#[derive(Clone, Copy, Debug)]
struct MetalNullableRelationFinalColumnLayout {
    source_rows_base: usize,
    values_or_offsets_base: Option<usize>,
    bytes_base: Option<usize>,
    validity_base: Option<usize>,
    end: usize,
}

fn metal_nullable_relation_final_column_layouts(
    sources: &[ResidentNullableRelationOutputSource],
    maximum_rows: usize,
    final_base: usize,
    final_byte_count: usize,
) -> Result<Vec<MetalNullableRelationFinalColumnLayout>> {
    let overflow = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal nullable final packet byte layout overflow",
        )
    };
    let start = final_base
        .checked_mul(std::mem::size_of::<u64>())
        .ok_or_else(overflow)?;
    let packet_end = start.checked_add(final_byte_count).ok_or_else(overflow)?;
    let mut cursor = start;
    let take = |cursor: &mut usize, bytes: usize| -> Result<usize> {
        let base = *cursor;
        *cursor = cursor.checked_add(bytes).ok_or_else(overflow)?;
        if *cursor > packet_end {
            return Err(overflow());
        }
        Ok(base)
    };
    let source_row_bytes = maximum_rows
        .checked_mul(std::mem::size_of::<u32>())
        .ok_or_else(overflow)?;
    let mut layouts = Vec::with_capacity(sources.len());
    for source in sources {
        let source_rows_base = take(&mut cursor, source_row_bytes)?;
        let (values_or_offsets_base, bytes_base, validity_base) = match source {
            ResidentNullableRelationOutputSource::Entity { .. }
            | ResidentNullableRelationOutputSource::NullProperty { .. } => (None, None, None),
            ResidentNullableRelationOutputSource::IntegerProperty { .. }
            | ResidentNullableRelationOutputSource::StringPropertyToInteger { .. }
            | ResidentNullableRelationOutputSource::FloatProperty { .. }
            | ResidentNullableRelationOutputSource::IntegerPropertyToFloat { .. } => {
                let values = take(
                    &mut cursor,
                    maximum_rows
                        .checked_mul(std::mem::size_of::<i64>())
                        .ok_or_else(overflow)?,
                )?;
                let validity = take(&mut cursor, maximum_rows)?;
                (Some(values), None, Some(validity))
            }
            ResidentNullableRelationOutputSource::StringProperty { maximum_bytes, .. } => {
                let offsets = take(
                    &mut cursor,
                    maximum_rows
                        .checked_add(1)
                        .and_then(|count| count.checked_mul(std::mem::size_of::<u32>()))
                        .ok_or_else(overflow)?,
                )?;
                let arena_bytes = maximum_rows
                    .checked_mul(*maximum_bytes as usize)
                    .ok_or_else(overflow)?;
                if arena_bytes > u32::MAX as usize {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal nullable string output arena exceeds u32 offsets",
                    ));
                }
                let bytes = take(&mut cursor, arena_bytes)?;
                let validity = take(&mut cursor, maximum_rows)?;
                (Some(offsets), Some(bytes), Some(validity))
            }
            ResidentNullableRelationOutputSource::IntegerPropertyToString { .. } => {
                let offsets = take(
                    &mut cursor,
                    maximum_rows
                        .checked_add(1)
                        .and_then(|count| count.checked_mul(std::mem::size_of::<u32>()))
                        .ok_or_else(overflow)?,
                )?;
                let arena_bytes = maximum_rows
                    .checked_mul(RESIDENT_NULLABLE_RELATION_INTEGER_STRING_MAXIMUM_BYTES as usize)
                    .ok_or_else(overflow)?;
                if arena_bytes > u32::MAX as usize {
                    return Err(Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal nullable integer-string output arena exceeds u32 offsets",
                    ));
                }
                let bytes = take(&mut cursor, arena_bytes)?;
                let validity = take(&mut cursor, maximum_rows)?;
                (Some(offsets), Some(bytes), Some(validity))
            }
            ResidentNullableRelationOutputSource::RelationshipType { .. } => {
                let relationship_types = take(
                    &mut cursor,
                    maximum_rows
                        .checked_mul(std::mem::size_of::<u64>())
                        .ok_or_else(overflow)?,
                )?;
                (Some(relationship_types), None, None)
            }
            ResidentNullableRelationOutputSource::EntityLabelPredicate { .. } => {
                let values = take(&mut cursor, maximum_rows)?;
                let validity = take(&mut cursor, maximum_rows)?;
                (Some(values), None, Some(validity))
            }
        };
        layouts.push(MetalNullableRelationFinalColumnLayout {
            source_rows_base,
            values_or_offsets_base,
            bytes_base,
            validity_base,
            end: cursor,
        });
    }
    if cursor != packet_end {
        return Err(Error::internal(
            "Metal nullable final packet capacities disagree with typed outputs",
        ));
    }
    Ok(layouts)
}

fn metal_nullable_relation_packet_byte(words: &[i64], byte: usize) -> Result<u8> {
    let word = *words
        .get(byte / std::mem::size_of::<i64>())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal nullable final packet byte is out of bounds",
            )
        })? as u64;
    Ok(((word >> ((byte % std::mem::size_of::<i64>()) * u8::BITS as usize)) & 0xff) as u8)
}

fn metal_nullable_relation_packet_u32(words: &[i64], base: usize) -> Result<u32> {
    let mut bytes = [0_u8; std::mem::size_of::<u32>()];
    for (offset, byte) in bytes.iter_mut().enumerate() {
        *byte = metal_nullable_relation_packet_byte(words, base + offset)?;
    }
    Ok(u32::from_le_bytes(bytes))
}

fn metal_nullable_relation_packet_i64(words: &[i64], base: usize) -> Result<i64> {
    let mut bytes = [0_u8; std::mem::size_of::<i64>()];
    for (offset, byte) in bytes.iter_mut().enumerate() {
        *byte = metal_nullable_relation_packet_byte(words, base + offset)?;
    }
    Ok(i64::from_le_bytes(bytes))
}

fn metal_nullable_relation_packet_u64(words: &[i64], base: usize) -> Result<u64> {
    let mut bytes = [0_u8; std::mem::size_of::<u64>()];
    for (offset, byte) in bytes.iter_mut().enumerate() {
        *byte = metal_nullable_relation_packet_byte(words, base + offset)?;
    }
    Ok(u64::from_le_bytes(bytes))
}

fn decode_metal_nullable_relation(
    words: &[i64],
    request: &ResidentNullableRelationRequest,
    graph_word_count: usize,
) -> Result<ResidentNullableRelationResult> {
    request.validate()?;
    let relation_cells = metal_nullable_relation_max_relation_cells(request)?;
    let encoded = encode_metal_nullable_relation_program(request)?;
    let output_layout = metal_nullable_relation_output_layout(request, relation_cells)?;
    let expected_words = output_layout.word_count;
    if words.len() != expected_words || words.len() < METAL_NULLABLE_RELATION_HEADER_WORDS {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal nullable-relation completion packet has the wrong size",
        ));
    }
    let word = |index: usize| words[index] as u64;
    if word(0) != METAL_NULLABLE_RELATION_MAGIC {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal nullable-relation completion packet has the wrong magic",
        ));
    }
    match word(1) {
        1 => {}
        3 => {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal nullable relation exceeded its sealed stage capacity",
            ));
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                format!(
                    "Metal nullable-relation device program rejected its sealed packet \
                     (validation={}, graph_validation={}, stage={}, prepared={})",
                    word(31),
                    word(output_layout.control_base + 7),
                    word(output_layout.control_base + 5),
                    word(output_layout.control_base + 8),
                ),
            ));
        }
    }
    let project = request.generation.project.0.as_u128();
    let catalog = metal_nullable_relation_hash_words(request.generation.catalog_generation);
    let fingerprint = metal_nullable_relation_hash_words(request.manifest.fingerprint.0);
    let row_count = usize::try_from(word(21)).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal nullable-relation row count exceeds the host address space",
        )
    })?;
    let scratch_bytes = request.scratch_bytes()?;
    if word(2) != request.execution.high
        || word(3) != request.execution.low
        || word(4) != (project >> 64) as u64
        || word(5) != project as u64
        || word(6) != request.generation.bookmark.term
        || word(7) != request.generation.bookmark.index
        || word(8) != request.generation.graph_revision
        || word(9) != request.generation.layout_version
        || (0..4).any(|index| word(10 + index) != catalog[index])
        || (0..4).any(|index| word(14 + index) != fingerprint[index])
        || word(18) != ResidentDeviceCompletion::Metal as u64
        || word(19) != request.program.stages.len() as u64
        || word(20) != request.manifest.obligations.len() as u64
        || row_count > output_layout.final_row_capacity
        || word(22) != u64::from(request.capacities.final_output_columns)
        || word(23) != scratch_bytes as u64
        || word(24) != expected_words as u64
        || word(25) != relation_cells as u64
        || word(26) != output_layout.final_row_capacity as u64
        || word(27) != u64::from(request.capacities.binding_slot_count)
        || word(28) != encoded.words.len() as u64
        || word(29) != graph_word_count as u64
        || word(30) != METAL_NULLABLE_RELATION_VERSION
        || word(31) != 0
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal nullable-relation completion packet has forged provenance or capacity metadata",
        ));
    }

    let mut receipts = Vec::with_capacity(request.manifest.obligations.len());
    for (index, expected) in request.manifest.obligations.iter().enumerate() {
        let base =
            METAL_NULLABLE_RELATION_HEADER_WORDS + index * METAL_NULLABLE_RELATION_RECEIPT_WORDS;
        let stage = u16::try_from(word(base + 3)).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal nullable-relation receipt stage exceeds u16",
            )
        })?;
        let kind = match word(base + 4) {
            1 => ResidentNullableRelationObligationKind::MandatoryNodeScan,
            2 => ResidentNullableRelationObligationKind::OptionalNodeScan,
            3 => ResidentNullableRelationObligationKind::MandatoryExpand,
            4 => ResidentNullableRelationObligationKind::OptionalExpand,
            5 => ResidentNullableRelationObligationKind::ScopeProjection,
            6 => ResidentNullableRelationObligationKind::FinalProjection,
            7 => ResidentNullableRelationObligationKind::RelationFilter,
            8 => ResidentNullableRelationObligationKind::OptionalCandidateFilter,
            9 => ResidentNullableRelationObligationKind::AtomicOptionalGroup,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal nullable-relation receipt has an unknown obligation kind",
                ));
            }
        };
        let obligation = super::ResidentNullableRelationObligation {
            id: word(base + 2),
            stage,
            kind,
        };
        if word(base) != request.execution.high
            || word(base + 1) != request.execution.low
            || obligation != *expected
            || word(base + 10) != ResidentDeviceCompletion::Metal as u64
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal nullable-relation receipt has forged execution provenance",
            ));
        }
        receipts.push(ResidentNullableRelationReceipt {
            execution: request.execution,
            obligation,
            input_cardinality: word(base + 5),
            matched_input_cardinality: word(base + 6),
            candidate_cardinality: word(base + 7),
            null_extension_cardinality: word(base + 8),
            output_cardinality: word(base + 9),
            completion: ResidentDeviceCompletion::Metal,
        });
    }

    let column_count = encoded.final_columns.len();
    let columns_base = METAL_NULLABLE_RELATION_HEADER_WORDS
        + request.manifest.obligations.len() * METAL_NULLABLE_RELATION_RECEIPT_WORDS;
    let column_capacity = output_layout.final_row_capacity;
    let final_layouts = metal_nullable_relation_final_column_layouts(
        &encoded.final_columns,
        column_capacity,
        output_layout.final_base,
        output_layout.final_byte_count,
    )?;
    let mut columns = Vec::with_capacity(column_count);
    for (column_index, (expected_source, layout)) in encoded
        .final_columns
        .iter()
        .cloned()
        .zip(final_layouts)
        .enumerate()
    {
        let expected_slot = expected_source.slot();
        let expected_kind = expected_source.kind();
        let descriptor = columns_base + column_index * METAL_NULLABLE_RELATION_COLUMN_WORDS;
        let source = u16::try_from(word(descriptor)).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal nullable-relation output source exceeds u16",
            )
        })?;
        let kind = match word(descriptor + 1) {
            1 => ResidentNullableRelationBindingKind::Node,
            2 => ResidentNullableRelationBindingKind::Relationship,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal nullable-relation output has an unknown binding kind",
                ));
            }
        };
        let (expected_type, expected_property, expected_maximum_bytes) = match &expected_source {
            ResidentNullableRelationOutputSource::Entity { .. } => {
                (METAL_NULLABLE_OUTPUT_ENTITY, u64::MAX, 0)
            }
            ResidentNullableRelationOutputSource::IntegerProperty { property, .. } => {
                (METAL_NULLABLE_OUTPUT_INTEGER_PROPERTY, property.0, 0)
            }
            ResidentNullableRelationOutputSource::FloatProperty { property, .. } => {
                (METAL_NULLABLE_OUTPUT_FLOAT_PROPERTY, property.0, 0)
            }
            ResidentNullableRelationOutputSource::StringProperty {
                property,
                maximum_bytes,
                ..
            } => (
                METAL_NULLABLE_OUTPUT_STRING_PROPERTY,
                property.0,
                u64::from(*maximum_bytes),
            ),
            ResidentNullableRelationOutputSource::NullProperty { .. } => {
                (METAL_NULLABLE_OUTPUT_NULL_PROPERTY, u64::MAX, 0)
            }
            ResidentNullableRelationOutputSource::RelationshipType { .. } => {
                (METAL_NULLABLE_OUTPUT_RELATIONSHIP_TYPE, u64::MAX, 0)
            }
            ResidentNullableRelationOutputSource::StringPropertyToInteger { property, .. } => (
                METAL_NULLABLE_OUTPUT_STRING_PROPERTY_TO_INTEGER,
                property.0,
                0,
            ),
            ResidentNullableRelationOutputSource::IntegerPropertyToFloat { property, .. } => (
                METAL_NULLABLE_OUTPUT_INTEGER_PROPERTY_TO_FLOAT,
                property.0,
                0,
            ),
            ResidentNullableRelationOutputSource::IntegerPropertyToString { property, .. } => (
                METAL_NULLABLE_OUTPUT_INTEGER_PROPERTY_TO_STRING,
                property.0,
                u64::from(RESIDENT_NULLABLE_RELATION_INTEGER_STRING_MAXIMUM_BYTES),
            ),
            ResidentNullableRelationOutputSource::EntityLabelPredicate { domain, .. } => {
                let (domain_kind, domain_count) = match domain {
                    ResidentNullableRelationEntityLabelDomain::Node(
                        ResidentNullableNodeDomain::Known(labels),
                    ) => (METAL_NULLABLE_RELATION_DOMAIN_KNOWN, labels.len() as u64),
                    ResidentNullableRelationEntityLabelDomain::Relationship(
                        ResidentNullableRelationshipDomain::Known(types),
                    ) => (METAL_NULLABLE_RELATION_DOMAIN_KNOWN, types.len() as u64),
                    ResidentNullableRelationEntityLabelDomain::Node(
                        ResidentNullableNodeDomain::KnownEmpty,
                    )
                    | ResidentNullableRelationEntityLabelDomain::Relationship(
                        ResidentNullableRelationshipDomain::KnownEmpty,
                    ) => (METAL_NULLABLE_RELATION_DOMAIN_EMPTY, 0),
                    ResidentNullableRelationEntityLabelDomain::Node(
                        ResidentNullableNodeDomain::Any,
                    )
                    | ResidentNullableRelationEntityLabelDomain::Relationship(
                        ResidentNullableRelationshipDomain::Any,
                    ) => {
                        return Err(Error::internal(
                            "validated entity-label output changed to an unsealed domain",
                        ));
                    }
                };
                (
                    METAL_NULLABLE_OUTPUT_ENTITY_LABEL_PREDICATE,
                    domain_kind,
                    domain_count,
                )
            }
        };
        let expected_values = layout
            .values_or_offsets_base
            .map_or(u64::MAX, |base| base as u64);
        let expected_bytes = layout.bytes_base.map_or(u64::MAX, |base| base as u64);
        let expected_validity = layout.validity_base.map_or(u64::MAX, |base| base as u64);
        if ResidentNullableRelationSlot(source) != expected_slot
            || kind != expected_kind
            || word(descriptor + 2) != expected_type
            || word(descriptor + 3) != expected_property
            || word(descriptor + 4) != expected_maximum_bytes
            || word(descriptor + 5) != layout.source_rows_base as u64
            || word(descriptor + 6) != expected_values
            || word(descriptor + 7) != expected_bytes
            || word(descriptor + 8) != expected_validity
            || word(descriptor + 9) != layout.end as u64
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal nullable-relation output columns disagree with the final projection",
            ));
        }
        let dense_capacity = match kind {
            ResidentNullableRelationBindingKind::Node => request.capacities.node_slot_count,
            ResidentNullableRelationBindingKind::Relationship => {
                request.capacities.relationship_slot_count
            }
        };
        let mut rows = Vec::with_capacity(row_count);
        for row in 0..row_count {
            let dense = metal_nullable_relation_packet_u32(
                words,
                layout.source_rows_base + row * std::mem::size_of::<u32>(),
            )?;
            if dense != super::RESIDENT_NULLABLE_RELATION_NULL_ROW && dense >= dense_capacity {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal nullable-relation output dense row is outside its resident domain",
                ));
            }
            rows.push(dense);
        }
        let column = match expected_source {
            ResidentNullableRelationOutputSource::Entity { .. } => {
                ResidentNullableRelationOutputColumn::Entity {
                    slot: expected_slot,
                    kind,
                    rows,
                }
            }
            ResidentNullableRelationOutputSource::NullProperty { .. } => {
                ResidentNullableRelationOutputColumn::NullProperty {
                    slot: expected_slot,
                    kind,
                    source_rows: rows,
                }
            }
            ResidentNullableRelationOutputSource::IntegerProperty { property, .. } => {
                let values_base = layout.values_or_offsets_base.ok_or_else(|| {
                    Error::internal("Metal nullable integer output omitted its value lane")
                })?;
                let validity_base = layout.validity_base.ok_or_else(|| {
                    Error::internal("Metal nullable integer output omitted its validity lane")
                })?;
                let mut values = Vec::with_capacity(row_count);
                let mut validity = Vec::with_capacity(row_count);
                for row in 0..row_count {
                    let value = metal_nullable_relation_packet_i64(
                        words,
                        values_base + row * std::mem::size_of::<i64>(),
                    )?;
                    let valid = metal_nullable_relation_packet_byte(words, validity_base + row)?;
                    if valid > 1 || (valid == 0 && value != 0) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable integer output has a non-canonical null payload",
                        ));
                    }
                    values.push(value);
                    validity.push(valid);
                }
                ResidentNullableRelationOutputColumn::IntegerProperty {
                    slot: expected_slot,
                    kind,
                    property,
                    source_rows: rows,
                    values,
                    validity,
                }
            }
            ResidentNullableRelationOutputSource::StringPropertyToInteger { property, .. } => {
                let values_base = layout.values_or_offsets_base.ok_or_else(|| {
                    Error::internal(
                        "Metal nullable string-to-integer output omitted its value lane",
                    )
                })?;
                let validity_base = layout.validity_base.ok_or_else(|| {
                    Error::internal(
                        "Metal nullable string-to-integer output omitted its validity lane",
                    )
                })?;
                let mut values = Vec::with_capacity(row_count);
                let mut validity = Vec::with_capacity(row_count);
                for row in 0..row_count {
                    let value = metal_nullable_relation_packet_i64(
                        words,
                        values_base + row * std::mem::size_of::<i64>(),
                    )?;
                    let valid = metal_nullable_relation_packet_byte(words, validity_base + row)?;
                    if valid > 1 || (valid == 0 && value != 0) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable string-to-integer output has a non-canonical null payload",
                        ));
                    }
                    values.push(value);
                    validity.push(valid);
                }
                ResidentNullableRelationOutputColumn::StringPropertyToInteger {
                    slot: expected_slot,
                    kind,
                    property,
                    source_rows: rows,
                    values,
                    validity,
                }
            }
            ResidentNullableRelationOutputSource::FloatProperty { property, .. } => {
                let values_base = layout.values_or_offsets_base.ok_or_else(|| {
                    Error::internal("Metal nullable float output omitted its value lane")
                })?;
                let validity_base = layout.validity_base.ok_or_else(|| {
                    Error::internal("Metal nullable float output omitted its validity lane")
                })?;
                let mut bits = Vec::with_capacity(row_count);
                let mut validity = Vec::with_capacity(row_count);
                for row in 0..row_count {
                    let value = metal_nullable_relation_packet_u64(
                        words,
                        values_base + row * std::mem::size_of::<u64>(),
                    )?;
                    let valid = metal_nullable_relation_packet_byte(words, validity_base + row)?;
                    if valid > 1
                        || (valid == 0 && value != 0)
                        || (valid == 1 && !f64::from_bits(value).is_finite())
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable float output has an invalid or non-canonical payload",
                        ));
                    }
                    bits.push(value);
                    validity.push(valid);
                }
                ResidentNullableRelationOutputColumn::FloatProperty {
                    slot: expected_slot,
                    kind,
                    property,
                    source_rows: rows,
                    bits,
                    validity,
                }
            }
            ResidentNullableRelationOutputSource::IntegerPropertyToFloat { property, .. } => {
                let values_base = layout.values_or_offsets_base.ok_or_else(|| {
                    Error::internal("Metal nullable integer-to-float output omitted its value lane")
                })?;
                let validity_base = layout.validity_base.ok_or_else(|| {
                    Error::internal(
                        "Metal nullable integer-to-float output omitted its validity lane",
                    )
                })?;
                let mut bits = Vec::with_capacity(row_count);
                let mut validity = Vec::with_capacity(row_count);
                for row in 0..row_count {
                    let value = metal_nullable_relation_packet_u64(
                        words,
                        values_base + row * std::mem::size_of::<u64>(),
                    )?;
                    let valid = metal_nullable_relation_packet_byte(words, validity_base + row)?;
                    if valid > 1
                        || (valid == 0 && value != 0)
                        || (valid == 1 && !f64::from_bits(value).is_finite())
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable integer-to-float output has an invalid or non-canonical payload",
                        ));
                    }
                    bits.push(value);
                    validity.push(valid);
                }
                ResidentNullableRelationOutputColumn::IntegerPropertyToFloat {
                    slot: expected_slot,
                    kind,
                    property,
                    source_rows: rows,
                    bits,
                    validity,
                }
            }
            ResidentNullableRelationOutputSource::StringProperty {
                property,
                maximum_bytes,
                ..
            } => {
                let offsets_base = layout.values_or_offsets_base.ok_or_else(|| {
                    Error::internal("Metal nullable string output omitted its offset lane")
                })?;
                let bytes_base = layout.bytes_base.ok_or_else(|| {
                    Error::internal("Metal nullable string output omitted its byte arena")
                })?;
                let validity_base = layout.validity_base.ok_or_else(|| {
                    Error::internal("Metal nullable string output omitted its validity lane")
                })?;
                let mut offsets = Vec::with_capacity(row_count + 1);
                for row in 0..=row_count {
                    offsets.push(metal_nullable_relation_packet_u32(
                        words,
                        offsets_base + row * std::mem::size_of::<u32>(),
                    )?);
                }
                let byte_capacity = column_capacity
                    .checked_mul(maximum_bytes as usize)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable string output capacity overflow",
                        )
                    })?;
                if offsets.first().copied() != Some(0)
                    || offsets.windows(2).any(|pair| pair[0] > pair[1])
                    || offsets.last().copied().unwrap_or(0) as usize > byte_capacity
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal nullable string output has invalid offsets",
                    ));
                }
                let mut validity = Vec::with_capacity(row_count);
                for row in 0..row_count {
                    let valid = metal_nullable_relation_packet_byte(words, validity_base + row)?;
                    let width = offsets[row + 1] - offsets[row];
                    if valid > 1 || (valid == 0 && width != 0) || width > maximum_bytes {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable string output violates null or width invariants",
                        ));
                    }
                    validity.push(valid);
                }
                let actual_bytes = offsets.last().copied().unwrap_or(0) as usize;
                let bytes = (0..actual_bytes)
                    .map(|offset| metal_nullable_relation_packet_byte(words, bytes_base + offset))
                    .collect::<Result<Vec<_>>>()?;
                ResidentNullableRelationOutputColumn::StringProperty {
                    slot: expected_slot,
                    kind,
                    property,
                    maximum_bytes,
                    source_rows: rows,
                    offsets,
                    bytes,
                    validity,
                }
            }
            ResidentNullableRelationOutputSource::IntegerPropertyToString { property, .. } => {
                let maximum_bytes = RESIDENT_NULLABLE_RELATION_INTEGER_STRING_MAXIMUM_BYTES;
                let offsets_base = layout.values_or_offsets_base.ok_or_else(|| {
                    Error::internal(
                        "Metal nullable integer-to-string output omitted its offset lane",
                    )
                })?;
                let bytes_base = layout.bytes_base.ok_or_else(|| {
                    Error::internal(
                        "Metal nullable integer-to-string output omitted its byte arena",
                    )
                })?;
                let validity_base = layout.validity_base.ok_or_else(|| {
                    Error::internal(
                        "Metal nullable integer-to-string output omitted its validity lane",
                    )
                })?;
                let mut offsets = Vec::with_capacity(row_count + 1);
                for row in 0..=row_count {
                    offsets.push(metal_nullable_relation_packet_u32(
                        words,
                        offsets_base + row * std::mem::size_of::<u32>(),
                    )?);
                }
                let byte_capacity = column_capacity
                    .checked_mul(maximum_bytes as usize)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable integer-to-string output capacity overflow",
                        )
                    })?;
                if offsets.first().copied() != Some(0)
                    || offsets.windows(2).any(|pair| pair[0] > pair[1])
                    || offsets.last().copied().unwrap_or(0) as usize > byte_capacity
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal nullable integer-to-string output has invalid offsets",
                    ));
                }
                let mut validity = Vec::with_capacity(row_count);
                for row in 0..row_count {
                    let valid = metal_nullable_relation_packet_byte(words, validity_base + row)?;
                    let width = offsets[row + 1] - offsets[row];
                    if valid > 1 || (valid == 0 && width != 0) || width > maximum_bytes {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable integer-to-string output violates null or width invariants",
                        ));
                    }
                    validity.push(valid);
                }
                let actual_bytes = offsets.last().copied().unwrap_or(0) as usize;
                let bytes = (0..actual_bytes)
                    .map(|offset| metal_nullable_relation_packet_byte(words, bytes_base + offset))
                    .collect::<Result<Vec<_>>>()?;
                ResidentNullableRelationOutputColumn::IntegerPropertyToString {
                    slot: expected_slot,
                    kind,
                    property,
                    source_rows: rows,
                    offsets,
                    bytes,
                    validity,
                }
            }
            ResidentNullableRelationOutputSource::RelationshipType { .. } => {
                let values_base = layout.values_or_offsets_base.ok_or_else(|| {
                    Error::internal(
                        "Metal nullable relationship-type output omitted its token lane",
                    )
                })?;
                let mut relationship_types = Vec::with_capacity(row_count);
                for (row, source_row) in rows.iter().copied().enumerate() {
                    let relationship_type = metal_nullable_relation_packet_u64(
                        words,
                        values_base + row * std::mem::size_of::<u64>(),
                    )?;
                    if source_row == super::RESIDENT_NULLABLE_RELATION_NULL_ROW
                        && relationship_type != 0
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable relationship-type output has a non-canonical null payload",
                        ));
                    }
                    relationship_types.push(crate::types::RelationshipTypeId(relationship_type));
                }
                ResidentNullableRelationOutputColumn::RelationshipType {
                    slot: expected_slot,
                    source_rows: rows,
                    relationship_types,
                }
            }
            ResidentNullableRelationOutputSource::EntityLabelPredicate { domain, .. } => {
                let values_base = layout.values_or_offsets_base.ok_or_else(|| {
                    Error::internal("Metal nullable entity-label output omitted its value lane")
                })?;
                let validity_base = layout.validity_base.ok_or_else(|| {
                    Error::internal("Metal nullable entity-label output omitted its validity lane")
                })?;
                let mut values = Vec::with_capacity(row_count);
                let mut validity = Vec::with_capacity(row_count);
                for (row, source_row) in rows.iter().copied().enumerate() {
                    let value = metal_nullable_relation_packet_byte(words, values_base + row)?;
                    let valid = metal_nullable_relation_packet_byte(words, validity_base + row)?;
                    if value > 1
                        || valid > 1
                        || (valid == 0 && value != 0)
                        || (source_row == super::RESIDENT_NULLABLE_RELATION_NULL_ROW)
                            != (valid == 0)
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal nullable entity-label output has invalid Boolean bytes or null propagation",
                        ));
                    }
                    values.push(value);
                    validity.push(valid);
                }
                ResidentNullableRelationOutputColumn::EntityLabelPredicate {
                    slot: expected_slot,
                    domain,
                    source_rows: rows,
                    values,
                    validity,
                }
            }
        };
        columns.push(column);
    }

    let result = ResidentNullableRelationResult::completed(ResidentNullableRelationResultParts {
        generation: request.generation,
        execution: request.execution,
        fingerprint: request.manifest.fingerprint,
        row_count,
        columns,
        receipts,
        scratch_bytes,
    });
    result
        .clone()
        .validate(request, ResidentDeviceCompletion::Metal)?;
    Ok(result)
}

fn encode_metal_mutation_constant(
    value: &ScalarValue,
    bytes: &mut Vec<u8>,
) -> Result<[u64; METAL_MUTATION_TYPED_VALUE_WORDS]> {
    let mut descriptor = [0_u64; METAL_MUTATION_TYPED_VALUE_WORDS];
    descriptor[0] = METAL_MUTATION_VALUE_OPCODE_CONSTANT;
    match value {
        ScalarValue::Null => {
            descriptor[1] = METAL_MUTATION_VALUE_NULL;
        }
        ScalarValue::Boolean(value) => {
            descriptor[1] = METAL_MUTATION_VALUE_BOOLEAN;
            descriptor[2] = u64::from(*value);
        }
        ScalarValue::Integer(value) => {
            descriptor[1] = METAL_MUTATION_VALUE_INTEGER;
            descriptor[2] = *value as u64;
        }
        ScalarValue::Float(value) => {
            descriptor[1] = METAL_MUTATION_VALUE_FLOAT;
            descriptor[2] = value.0.to_bits();
        }
        ScalarValue::String(value) => {
            if value.len() > METAL_MUTATION_TYPED_MAX_STRING_BYTES {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "string constant exceeds the bounded Metal mutation value width",
                ));
            }
            descriptor[1] = METAL_MUTATION_VALUE_STRING;
            descriptor[3] = METAL_MUTATION_STRING_PROGRAM_CONSTANT;
            descriptor[4] = bytes.len() as u64;
            descriptor[5] = value.len() as u64;
            bytes.extend_from_slice(value.as_bytes());
        }
        _ => {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal typed mutation constants currently support only null, Boolean, integer, float, and string values",
            ));
        }
    }
    Ok(descriptor)
}

fn push_metal_mutation_receipt_descriptor(
    words: &mut Vec<u64>,
    obligation: super::ResidentExecutionObligation,
    input: u64,
    output: u64,
) {
    let (scope, index) = match obligation.scope {
        super::ResidentObligationScope::Selection => (0_u64, 0_u64),
        super::ResidentObligationScope::MutationCommand(index) => (1, u64::from(index)),
        super::ResidentObligationScope::Expression(index) => (2, u64::from(index)),
        super::ResidentObligationScope::Filter(index) => (3, u64::from(index)),
        super::ResidentObligationScope::PatternLeaf(index) => (4, u64::from(index)),
        super::ResidentObligationScope::PatternFinal => (5, 0),
        super::ResidentObligationScope::PatternScan => (6, 0),
        super::ResidentObligationScope::PatternScanN => (7, 0),
        super::ResidentObligationScope::PatternScanM => (8, 0),
        super::ResidentObligationScope::PatternCartesian => (9, 0),
    };
    words.extend([
        obligation.id,
        obligation.kind as u64,
        scope,
        index,
        input,
        output,
    ]);
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_PACKET_HEADER_WORDS: usize = 6;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_LEAF_WORDS: usize = 11;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_INSTRUCTION_WORDS: usize = 2;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_FRAME_HEADER_WORDS: usize = 12;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_RECEIPT_WORDS: usize = 9;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_MAGIC: u64 = 0x4947_5041_5454_4552;

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn resident_pattern_column(
    column: Option<&Tensor>,
    rows: usize,
    dummy: &Tensor,
    name: &str,
) -> Result<Tensor> {
    if rows == 0 {
        return Ok(dummy.clone());
    }
    column.cloned().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            format!("resident pattern predicate {name} column is absent"),
        )
    })
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn resident_pattern_property_ids(
    program: &super::ResidentPatternPredicateProgram,
) -> Vec<PropertyId> {
    program
        .leaves
        .iter()
        .filter_map(|leaf| leaf.property_equality)
        .flat_map(|equality| [equality.start, equality.end])
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn encode_metal_pattern_predicate(
    program: &super::ResidentPatternPredicateProgram,
) -> Result<Vec<i64>> {
    program.validate()?;
    let property_ids = resident_pattern_property_ids(program);
    let property_lanes = property_ids
        .iter()
        .copied()
        .enumerate()
        .map(|(lane, property)| (property, lane))
        .collect::<BTreeMap<_, _>>();
    let type_count = program
        .leaves
        .iter()
        .map(|leaf| match &leaf.relationship_types {
            super::ResidentPatternRelationshipTypes::Known(types) => types.len(),
            super::ResidentPatternRelationshipTypes::Any
            | super::ResidentPatternRelationshipTypes::Never => 0,
        })
        .try_fold(0_usize, |total, count| total.checked_add(count))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal pattern predicate type packet overflow",
            )
        })?;
    let packet_words = METAL_PATTERN_PACKET_HEADER_WORDS
        .checked_add(
            program
                .leaves
                .len()
                .checked_mul(METAL_PATTERN_LEAF_WORDS)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::GpuAdmissionFailure,
                        "Metal pattern predicate leaf packet overflow",
                    )
                })?,
        )
        .and_then(|words| {
            words.checked_add(
                program
                    .instructions
                    .len()
                    .checked_mul(METAL_PATTERN_INSTRUCTION_WORDS)?,
            )
        })
        .and_then(|words| words.checked_add(type_count))
        .and_then(|words| words.checked_add(property_ids.len()))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "Metal pattern predicate packet shape overflow",
            )
        })?;
    let mut words = Vec::with_capacity(packet_words);
    words.extend([
        2_i64,
        program.leaves.len() as i64,
        program.instructions.len() as i64,
        type_count as i64,
        property_ids.len() as i64,
        program.final_obligation.id as i64,
    ]);
    let mut type_offset = 0_usize;
    for leaf in &program.leaves {
        let (type_start, leaf_type_count) = match &leaf.relationship_types {
            super::ResidentPatternRelationshipTypes::Known(types) => {
                let start = type_offset;
                type_offset = type_offset.saturating_add(types.len());
                (start, types.len())
            }
            super::ResidentPatternRelationshipTypes::Any
            | super::ResidentPatternRelationshipTypes::Never => (type_offset, 0),
        };
        let direction = match leaf.direction {
            super::ResidentDirection::Outgoing => 0_u64,
            super::ResidentDirection::Incoming => 1,
            super::ResidentDirection::Undirected => 2,
        };
        let (property_mode, start_property_lane, end_property_lane) = leaf
            .property_equality
            .and_then(|equality| {
                let start = property_lanes.get(&equality.start).copied()?;
                let end = property_lanes.get(&equality.end).copied()?;
                Some((1_i64, i64::try_from(start).ok()?, i64::try_from(end).ok()?))
            })
            .unwrap_or((0, 0, 0));
        words.extend([
            direction as i64,
            leaf.relationship_types.wire_kind() as i64,
            type_start as i64,
            leaf_type_count as i64,
            leaf.length as u8 as i64,
            leaf.obligation.id as i64,
            property_mode,
            start_property_lane,
            end_property_lane,
            i64::from(leaf.minimum_witnesses),
            i64::from(leaf.maximum_witnesses),
        ]);
    }
    for instruction in &program.instructions {
        let (opcode, operand) = match *instruction {
            super::ResidentPatternBooleanInstruction::Leaf(index) => (0_u64, u64::from(index)),
            super::ResidentPatternBooleanInstruction::Not => (1, 0),
            super::ResidentPatternBooleanInstruction::And => (2, 0),
            super::ResidentPatternBooleanInstruction::Or => (3, 0),
        };
        words.extend([opcode as i64, operand as i64]);
    }
    for leaf in &program.leaves {
        if let super::ResidentPatternRelationshipTypes::Known(types) = &leaf.relationship_types {
            words.extend(
                types
                    .iter()
                    .map(|relationship_type| relationship_type.0 as i64),
            );
        }
    }
    words.extend(property_ids.iter().map(|property| property.0 as i64));
    if words.len() != packet_words || type_offset != type_count {
        return Err(Error::internal(
            "Metal pattern predicate packet encoder produced an inconsistent shape",
        ));
    }
    Ok(words)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn decode_metal_pattern_predicate(
    words: &[i64],
    request: &super::ResidentPatternPredicateRequest,
) -> Result<super::ResidentPatternPredicateResult> {
    request.validate()?;
    let receipt_count = request.obligations().count();
    let expected_words = METAL_PATTERN_FRAME_HEADER_WORDS
        .checked_add(
            receipt_count
                .checked_mul(METAL_PATTERN_RECEIPT_WORDS)
                .ok_or_else(|| Error::internal("Metal pattern receipt frame overflow"))?,
        )
        .and_then(|count| count.checked_add(request.max_output_rows))
        .ok_or_else(|| Error::internal("Metal pattern output frame overflow"))?;
    if words.len() != expected_words
        || words.first().copied().map(|word| word as u64) != Some(METAL_PATTERN_MAGIC)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal pattern predicate returned an invalid result frame",
        ));
    }
    match words[1] as u64 {
        1 => {}
        2 => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal pattern predicate detected an invalid device program or graph shape",
            ));
        }
        3 => {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident pattern predicate exceeded its output row budget",
            ));
        }
        4 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "resident pattern predicate outer row is not active in the requested layers",
            ));
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal pattern predicate returned an unknown completion status",
            ));
        }
    }
    let execution = super::ResidentExecutionId {
        high: words[2] as u64,
        low: words[3] as u64,
    };
    let input_count = usize::try_from(words[4] as u64).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal pattern predicate input count exceeds host addressing",
        )
    })?;
    let output_count = usize::try_from(words[5] as u64).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal pattern predicate output count exceeds host addressing",
        )
    })?;
    let bookmark = Bookmark {
        term: words[8] as u64,
        index: words[9] as u64,
    };
    let graph_revision = words[10] as u64;
    let layout_version = words[11] as u64;
    if execution != request.program.execution
        || bookmark != request.expected_bookmark
        || graph_revision != request.expected_graph_revision
        || layout_version != request.expected_layout_version
        || input_count != request.input.row_count()
        || output_count > request.max_output_rows
        || words[6] as u64 != receipt_count as u64
        || words[7] as u64 != super::ResidentDeviceCompletion::Metal as u64
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal pattern predicate result header has invalid provenance",
        ));
    }
    let mut receipts = Vec::with_capacity(receipt_count);
    for index in 0..receipt_count {
        let base = METAL_PATTERN_FRAME_HEADER_WORDS + index * METAL_PATTERN_RECEIPT_WORDS;
        let scope_index = u16::try_from(words[base + 5] as u64).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal pattern predicate receipt scope exceeds u16",
            )
        })?;
        let kind = match words[base + 3] as u64 {
            5 => super::ResidentObligationKind::PatternTraversal,
            6 => super::ResidentObligationKind::PatternFilter,
            7 => super::ResidentObligationKind::PatternScan,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal pattern predicate receipt has an unknown kind",
                ));
            }
        };
        let scope = match words[base + 4] as u64 {
            4 => super::ResidentObligationScope::PatternLeaf(scope_index),
            5 if scope_index == 0 => super::ResidentObligationScope::PatternFinal,
            6 if scope_index == 0 => super::ResidentObligationScope::PatternScan,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal pattern predicate receipt has an unknown scope",
                ));
            }
        };
        if words[base + 8] as u64 != super::ResidentDeviceCompletion::Metal as u64 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal pattern predicate receipt has a non-Metal completion marker",
            ));
        }
        receipts.push(super::ResidentExecutionReceipt {
            execution: super::ResidentExecutionId {
                high: words[base] as u64,
                low: words[base + 1] as u64,
            },
            obligation: super::ResidentExecutionObligation {
                id: words[base + 2] as u64,
                kind,
                scope,
            },
            input_cardinality: words[base + 6] as u64,
            output_cardinality: words[base + 7] as u64,
            completion: super::ResidentDeviceCompletion::Metal,
        });
    }
    let rows_base = METAL_PATTERN_FRAME_HEADER_WORDS + receipt_count * METAL_PATTERN_RECEIPT_WORDS;
    let output_rows = words[rows_base..rows_base + output_count]
        .iter()
        .map(|word| {
            u32::try_from(*word as u64).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal pattern predicate returned a row outside u32",
                )
            })
        })
        .collect::<Result<Vec<_>>>()?;
    Ok(super::ResidentPatternPredicateResult::completed(
        execution,
        bookmark,
        graph_revision,
        layout_version,
        output_rows,
        receipts,
    ))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_PAIR_PACKET_HEADER_WORDS: usize = 7;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_PAIR_FRAME_HEADER_WORDS: usize = 12;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_PAIR_RECEIPT_WORDS: usize = 9;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_PAIR_RECEIPTS: usize = 5;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_PATTERN_PAIR_MAGIC: u64 = 0x4947_5041_4952_5052;

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn encode_metal_pattern_pair_predicate(
    program: &super::ResidentPatternPairPredicateProgram,
) -> Result<Vec<i64>> {
    program.validate()?;
    let types = match &program.leaf.relationship_types {
        super::ResidentPatternRelationshipTypes::Known(types) => types.as_slice(),
        super::ResidentPatternRelationshipTypes::Any
        | super::ResidentPatternRelationshipTypes::Never => &[],
    };
    let direction = match program.leaf.direction {
        super::ResidentDirection::Outgoing => 0_u64,
        super::ResidentDirection::Incoming => 1,
        super::ResidentDirection::Undirected => 2,
    };
    let mut words = Vec::with_capacity(METAL_PATTERN_PAIR_PACKET_HEADER_WORDS + types.len());
    words.extend([
        1_i64,
        direction as i64,
        program.leaf.relationship_types.wire_kind() as i64,
        program.leaf.length as u8 as i64,
        types.len() as i64,
        program.leaf.obligation.id as i64,
        program.final_obligation.id as i64,
    ]);
    words.extend(
        types
            .iter()
            .map(|relationship_type| relationship_type.0 as i64),
    );
    Ok(words)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn decode_metal_pattern_pair_predicate(
    words: &[i64],
    request: &super::ResidentPatternPairPredicateRequest,
) -> Result<super::ResidentPatternPairPredicateResult> {
    request.validate()?;
    let expected_words = METAL_PATTERN_PAIR_FRAME_HEADER_WORDS
        .checked_add(METAL_PATTERN_PAIR_RECEIPTS * METAL_PATTERN_PAIR_RECEIPT_WORDS)
        .and_then(|count| count.checked_add(request.max_output_pairs.checked_mul(3)?))
        .ok_or_else(|| Error::internal("Metal paired pattern output frame overflow"))?;
    if words.len() != expected_words
        || words.first().copied().map(|word| word as u64) != Some(METAL_PATTERN_PAIR_MAGIC)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal paired pattern returned an invalid result frame",
        ));
    }
    match words[1] as u64 {
        1 => {}
        2 => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal paired pattern detected an invalid device program or graph shape",
            ));
        }
        3 => {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident paired pattern exceeded its output pair budget",
            ));
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal paired pattern returned an unknown completion status",
            ));
        }
    }
    let execution = super::ResidentExecutionId {
        high: words[2] as u64,
        low: words[3] as u64,
    };
    let pair_count = words[4] as u64;
    let output_count = usize::try_from(words[5] as u64).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal paired pattern output count exceeds host addressing",
        )
    })?;
    let bookmark = Bookmark {
        term: words[8] as u64,
        index: words[9] as u64,
    };
    let graph_revision = words[10] as u64;
    let layout_version = words[11] as u64;
    if execution != request.program.execution
        || bookmark != request.expected_bookmark
        || graph_revision != request.expected_graph_revision
        || layout_version != request.expected_layout_version
        || pair_count != request.logical_pair_domain()?
        || output_count > request.max_output_pairs
        || words[6] as u64 != METAL_PATTERN_PAIR_RECEIPTS as u64
        || words[7] as u64 != super::ResidentDeviceCompletion::Metal as u64
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal paired pattern result header has invalid provenance",
        ));
    }

    let mut receipts = Vec::with_capacity(METAL_PATTERN_PAIR_RECEIPTS);
    for index in 0..METAL_PATTERN_PAIR_RECEIPTS {
        let base = METAL_PATTERN_PAIR_FRAME_HEADER_WORDS + index * METAL_PATTERN_PAIR_RECEIPT_WORDS;
        if words[base + 5] != 0
            || words[base + 8] as u64 != super::ResidentDeviceCompletion::Metal as u64
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal paired pattern receipt has an invalid scope/completion marker",
            ));
        }
        let kind = match words[base + 3] as u64 {
            5 => super::ResidentObligationKind::PatternTraversal,
            6 => super::ResidentObligationKind::PatternFilter,
            7 => super::ResidentObligationKind::PatternScan,
            8 => super::ResidentObligationKind::PatternCartesian,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal paired pattern receipt has an unknown kind",
                ));
            }
        };
        let scope = match words[base + 4] as u64 {
            4 => super::ResidentObligationScope::PatternLeaf(0),
            5 => super::ResidentObligationScope::PatternFinal,
            7 => super::ResidentObligationScope::PatternScanN,
            8 => super::ResidentObligationScope::PatternScanM,
            9 => super::ResidentObligationScope::PatternCartesian,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal paired pattern receipt has an unknown scope",
                ));
            }
        };
        receipts.push(super::ResidentExecutionReceipt {
            execution: super::ResidentExecutionId {
                high: words[base] as u64,
                low: words[base + 1] as u64,
            },
            obligation: super::ResidentExecutionObligation {
                id: words[base + 2] as u64,
                kind,
                scope,
            },
            input_cardinality: words[base + 6] as u64,
            output_cardinality: words[base + 7] as u64,
            completion: super::ResidentDeviceCompletion::Metal,
        });
    }
    let rows_base = METAL_PATTERN_PAIR_FRAME_HEADER_WORDS
        + METAL_PATTERN_PAIR_RECEIPTS * METAL_PATTERN_PAIR_RECEIPT_WORDS;
    let mut pair_positions = Vec::with_capacity(output_count);
    let mut n_rows = Vec::with_capacity(output_count);
    let mut m_rows = Vec::with_capacity(output_count);
    for index in 0..output_count {
        let base = rows_base + index * 3;
        pair_positions.push(words[base] as u64);
        n_rows.push(u32::try_from(words[base + 1] as u64).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal paired pattern returned an n row outside u32",
            )
        })?);
        m_rows.push(u32::try_from(words[base + 2] as u64).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal paired pattern returned an m row outside u32",
            )
        })?);
    }
    Ok(super::ResidentPatternPairPredicateResult::completed(
        execution,
        bookmark,
        graph_revision,
        layout_version,
        pair_positions,
        n_rows,
        m_rows,
        receipts,
    ))
}

fn decode_metal_static_mutation(
    words: &[i64],
    program: &super::ResidentMutationProgram,
) -> Result<super::ResidentMutationProgramResult> {
    let word = |index: usize| {
        words
            .get(index)
            .copied()
            .map(|value| value as u64)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation output is truncated",
                )
            })
    };
    if word(0)? != METAL_MUTATION_STATIC_MAGIC
        || word(1)? != 1
        || word(5)? != program.execution.high
        || word(6)? != program.execution.low
        || word(7)? != super::ResidentDeviceCompletion::Metal as u64
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation output has an invalid execution header",
        ));
    }
    let intent_count = usize::try_from(word(2)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation intent count exceeds host address space",
        )
    })?;
    let receipt_count = usize::try_from(word(3)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation receipt count exceeds host address space",
        )
    })?;
    let payload_count = usize::try_from(word(4)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation payload count exceeds host address space",
        )
    })?;
    let intent_capacity = usize::try_from(word(8)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation intent capacity exceeds host address space",
        )
    })?;
    let expected_receipts = program
        .commands
        .len()
        .checked_mul(2)
        .and_then(|count| count.checked_add(1))
        .ok_or_else(|| Error::internal("Metal mutation receipt count overflow"))?;
    if receipt_count != expected_receipts
        || intent_count > intent_capacity
        || intent_capacity > program.max_intents
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation output has an invalid effect/intent cardinality",
        ));
    }
    let receipt_base = METAL_MUTATION_STATIC_HEADER_WORDS;
    let intent_base = receipt_base
        .checked_add(
            receipt_count
                .checked_mul(METAL_MUTATION_STATIC_RECEIPT_WORDS)
                .ok_or_else(|| Error::internal("Metal mutation receipt shape overflow"))?,
        )
        .ok_or_else(|| Error::internal("Metal mutation receipt boundary overflow"))?;
    let payload_base = intent_base
        .checked_add(
            intent_capacity
                .checked_mul(METAL_MUTATION_STATIC_INTENT_WORDS)
                .ok_or_else(|| Error::internal("Metal mutation intent shape overflow"))?,
        )
        .ok_or_else(|| Error::internal("Metal mutation intent boundary overflow"))?;
    if payload_base.checked_add(payload_count) != Some(words.len()) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation output has inconsistent section lengths",
        ));
    }

    let mut receipts = Vec::with_capacity(receipt_count);
    for index in 0..receipt_count {
        let base = receipt_base + index * METAL_MUTATION_STATIC_RECEIPT_WORDS;
        let kind = match word(base + 3)? {
            1 => super::ResidentObligationKind::MutationSelect,
            2 => super::ResidentObligationKind::MutationRhs,
            3 => super::ResidentObligationKind::Expression,
            4 => super::ResidentObligationKind::Filter,
            12 => super::ResidentObligationKind::MutationEffect,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation receipt has an unknown obligation kind",
                ));
            }
        };
        let scope_index = u16::try_from(word(base + 5)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation receipt scope exceeds u16",
            )
        })?;
        let scope = match word(base + 4)? {
            0 => super::ResidentObligationScope::Selection,
            1 => super::ResidentObligationScope::MutationCommand(scope_index),
            2 => super::ResidentObligationScope::Expression(scope_index),
            3 => super::ResidentObligationScope::Filter(scope_index),
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation receipt has an unknown obligation scope",
                ));
            }
        };
        if word(base + 8)? != super::ResidentDeviceCompletion::Metal as u64 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation receipt has a non-Metal completion status",
            ));
        }
        receipts.push(super::ResidentExecutionReceipt {
            execution: super::ResidentExecutionId {
                high: word(base)?,
                low: word(base + 1)?,
            },
            obligation: super::ResidentExecutionObligation {
                id: word(base + 2)?,
                kind,
                scope,
            },
            input_cardinality: word(base + 6)?,
            output_cardinality: word(base + 7)?,
            completion: super::ResidentDeviceCompletion::Metal,
        });
    }
    let expected_obligations = std::iter::once(program.selection_obligation).chain(
        program
            .commands
            .iter()
            .flat_map(|command| [command.rhs_obligation, command.effect_obligation]),
    );
    if receipts
        .iter()
        .zip(expected_obligations)
        .any(|(receipt, obligation)| {
            receipt.execution != program.execution || receipt.obligation != obligation
        })
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation receipts do not match the sealed obligation order",
        ));
    }

    let mut intents = Vec::with_capacity(intent_count);
    for index in 0..intent_count {
        let base = intent_base + index * METAL_MUTATION_STATIC_INTENT_WORDS;
        let effectful = match word(base + 7)? {
            0 => false,
            1 => true,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation intent has an invalid effect status",
                ));
            }
        };
        if word(base + 8)? != 1 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation intent has an incomplete device status",
            ));
        }
        let source_row = u32::try_from(word(base)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation source row exceeds u32",
            )
        })?;
        let command = u16::try_from(word(base + 1)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation command index exceeds u16",
            )
        })?;
        let target_kind = match word(base + 2)? {
            0 => EntityKind::Node,
            1 => EntityKind::Relationship,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation intent has an unknown target kind",
                ));
            }
        };
        let payload_offset = usize::try_from(word(base + 5)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation payload offset exceeds host address space",
            )
        })?;
        let action_payload_count = usize::try_from(word(base + 6)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation action payload exceeds host address space",
            )
        })?;
        let payload_end = payload_offset
            .checked_add(action_payload_count)
            .filter(|end| *end <= payload_count)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation action payload is out of bounds",
                )
            })?;
        let payload = (payload_offset..payload_end)
            .map(|position| {
                u16::try_from(word(payload_base + position)?).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal mutation name index exceeds u16",
                    )
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let action = match word(base + 4)? {
            1 if effectful == !payload.is_empty() => {
                super::ResidentMutationIntentAction::AddLabels { labels: payload }
            }
            2 if effectful == !payload.is_empty() => {
                super::ResidentMutationIntentAction::RemoveLabels { labels: payload }
            }
            3 if payload.len() == 1 => super::ResidentMutationIntentAction::RemoveProperty {
                property_name: payload[0],
            },
            METAL_MUTATION_ACTION_SET_PROPERTY if payload.len() == 1 => {
                let (target, property_name, value) =
                    program.exact_document_constant_set().ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal static document SET escaped its sealed program profile",
                        )
                    })?;
                let expected_kind = match target {
                    super::ResidentEntityBinding::Node(_) => EntityKind::Node,
                    super::ResidentEntityBinding::Relationship(_) => EntityKind::Relationship,
                };
                if command != 0 || target_kind != expected_kind || payload[0] != property_name {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal static document SET returned a mismatched target or property",
                    ));
                }
                super::ResidentMutationIntentAction::SetProperty {
                    property_name,
                    value: value.clone(),
                }
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation intent has an invalid typed action payload",
                ));
            }
        };
        intents.push(super::ResidentMutationIntent {
            source_row,
            command,
            target_kind,
            target_id: word(base + 3)?,
            action,
            effectful,
        });
    }
    Ok(super::ResidentMutationProgramResult::completed(
        program.execution,
        intents,
        receipts,
    ))
}

fn decode_metal_typed_mutation(
    words: &[i64],
    program: &super::ResidentMutationProgram,
) -> Result<super::ResidentMutationProgramResult> {
    let word = |index: usize| {
        words
            .get(index)
            .copied()
            .map(|value| value as u64)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal typed mutation output is truncated",
                )
            })
    };
    if word(0)? != METAL_MUTATION_TYPED_MAGIC
        || word(5)? != program.execution.high
        || word(6)? != program.execution.low
        || word(7)? != super::ResidentDeviceCompletion::Metal as u64
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal typed mutation output has an invalid execution header",
        ));
    }
    match word(1)? {
        1 => {}
        3 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal mutation expression encountered incompatible value types",
            ));
        }
        4 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal mutation arithmetic overflowed its bounded scalar domain",
            ));
        }
        5 => {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation value exceeded its admitted device arena",
            ));
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation kernel rejected its typed packet shape",
            ));
        }
    }
    let intent_count = usize::try_from(word(2)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation intent count exceeds host address space",
        )
    })?;
    let receipt_count = usize::try_from(word(3)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation receipt count exceeds host address space",
        )
    })?;
    let payload_count = usize::try_from(word(4)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation payload count exceeds host address space",
        )
    })?;
    let intent_capacity = usize::try_from(word(8)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation intent capacity exceeds host address space",
        )
    })?;
    let expected_receipts = 1_usize
        .checked_add(program.filter_obligations.len())
        .and_then(|count| count.checked_add(program.expression_obligations.len()))
        .and_then(|count| {
            program
                .commands
                .len()
                .checked_mul(2)
                .and_then(|commands| count.checked_add(commands))
        })
        .ok_or_else(|| Error::internal("Metal mutation receipt count overflow"))?;
    if intent_count > intent_capacity
        || intent_capacity > program.max_intents
        || receipt_count != expected_receipts
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation output exceeded its intent capacity",
        ));
    }
    let receipt_base = METAL_MUTATION_TYPED_HEADER_WORDS;
    let intent_base = receipt_base
        .checked_add(
            receipt_count
                .checked_mul(METAL_MUTATION_STATIC_RECEIPT_WORDS)
                .ok_or_else(|| Error::internal("Metal mutation receipt shape overflow"))?,
        )
        .ok_or_else(|| Error::internal("Metal mutation receipt boundary overflow"))?;
    let payload_base = intent_base
        .checked_add(
            intent_capacity
                .checked_mul(METAL_MUTATION_TYPED_INTENT_WORDS)
                .ok_or_else(|| Error::internal("Metal mutation intent shape overflow"))?,
        )
        .ok_or_else(|| Error::internal("Metal mutation intent boundary overflow"))?;
    if payload_base.checked_add(payload_count) != Some(words.len()) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation output has inconsistent typed section lengths",
        ));
    }

    let mut receipts = Vec::with_capacity(receipt_count);
    for index in 0..receipt_count {
        let base = receipt_base + index * METAL_MUTATION_STATIC_RECEIPT_WORDS;
        let kind = match word(base + 3)? {
            1 => super::ResidentObligationKind::MutationSelect,
            2 => super::ResidentObligationKind::MutationRhs,
            3 => super::ResidentObligationKind::Expression,
            4 => super::ResidentObligationKind::Filter,
            12 => super::ResidentObligationKind::MutationEffect,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation receipt has an unknown obligation kind",
                ));
            }
        };
        let scope_index = u16::try_from(word(base + 5)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation receipt scope exceeds u16",
            )
        })?;
        let scope = match word(base + 4)? {
            0 => super::ResidentObligationScope::Selection,
            1 => super::ResidentObligationScope::MutationCommand(scope_index),
            2 => super::ResidentObligationScope::Expression(scope_index),
            3 => super::ResidentObligationScope::Filter(scope_index),
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation receipt has an unknown obligation scope",
                ));
            }
        };
        if word(base + 8)? != super::ResidentDeviceCompletion::Metal as u64 {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation receipt has a non-Metal completion status",
            ));
        }
        receipts.push(super::ResidentExecutionReceipt {
            execution: super::ResidentExecutionId {
                high: word(base)?,
                low: word(base + 1)?,
            },
            obligation: super::ResidentExecutionObligation {
                id: word(base + 2)?,
                kind,
                scope,
            },
            input_cardinality: word(base + 6)?,
            output_cardinality: word(base + 7)?,
            completion: super::ResidentDeviceCompletion::Metal,
        });
    }
    let expected_obligations = std::iter::once(program.selection_obligation)
        .chain(program.filter_obligations.iter().copied())
        .chain(program.expression_obligations.iter().copied())
        .chain(
            program
                .commands
                .iter()
                .flat_map(|command| [command.rhs_obligation, command.effect_obligation]),
        );
    if receipts
        .iter()
        .zip(expected_obligations)
        .any(|(receipt, obligation)| {
            receipt.execution != program.execution || receipt.obligation != obligation
        })
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal typed mutation receipts do not match the sealed obligation order",
        ));
    }

    let mut intents = Vec::with_capacity(intent_count);
    for index in 0..intent_count {
        let base = intent_base + index * METAL_MUTATION_TYPED_INTENT_WORDS;
        let effectful = match word(base + 9)? {
            0 => false,
            1 => true,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation intent has an invalid typed effect status",
                ));
            }
        };
        if word(base + 10)? != 1 || word(base + 4)? != METAL_MUTATION_ACTION_SET_PROPERTY {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation intent has an incomplete typed action status",
            ));
        }
        let source_row = u32::try_from(word(base)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation source row exceeds u32",
            )
        })?;
        let command = u16::try_from(word(base + 1)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation command index exceeds u16",
            )
        })?;
        let target_kind = match word(base + 2)? {
            0 => EntityKind::Node,
            1 => EntityKind::Relationship,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation intent has an unknown target kind",
                ));
            }
        };
        let property_name = u16::try_from(word(base + 5)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation property name exceeds u16",
            )
        })?;
        let payload = word(base + 7)?;
        let length = usize::try_from(word(base + 8)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation string length exceeds host address space",
            )
        })?;
        let value = match word(base + 6)? {
            METAL_MUTATION_VALUE_NULL if payload == 0 && length == 0 => ScalarValue::Null,
            METAL_MUTATION_VALUE_BOOLEAN if payload <= 1 && length == 0 => {
                ScalarValue::Boolean(payload != 0)
            }
            METAL_MUTATION_VALUE_INTEGER if length == 0 => ScalarValue::Integer(payload as i64),
            METAL_MUTATION_VALUE_FLOAT if length == 0 => {
                ScalarValue::Float(OrderedFloat(f64::from_bits(payload)))
            }
            METAL_MUTATION_VALUE_STRING => {
                let offset = usize::try_from(payload).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal mutation string offset exceeds host address space",
                    )
                })?;
                let end = offset
                    .checked_add(length)
                    .filter(|end| *end <= payload_count)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal mutation string payload is out of bounds",
                        )
                    })?;
                let bytes = (offset..end)
                    .map(|position| {
                        u8::try_from(word(payload_base + position)?).map_err(|_| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "Metal mutation string payload contains a non-byte value",
                            )
                        })
                    })
                    .collect::<Result<Vec<_>>>()?;
                let value = String::from_utf8(bytes).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal mutation string payload is not UTF-8",
                    )
                })?;
                ScalarValue::String(std::sync::Arc::from(value))
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation intent has an invalid scalar cell",
                ));
            }
        };
        intents.push(super::ResidentMutationIntent {
            source_row,
            command,
            target_kind,
            target_id: word(base + 3)?,
            action: super::ResidentMutationIntentAction::SetProperty {
                property_name,
                value,
            },
            effectful,
        });
    }
    Ok(super::ResidentMutationProgramResult::completed(
        program.execution,
        intents,
        receipts,
    ))
}

fn decode_metal_mutation_continuation(
    words: &[i64],
    request: &ResidentNodePipelineRequest,
) -> Result<(
    Vec<super::ResidentMutationReadDependency>,
    super::ResidentMutationFinalRelation,
    Vec<ResidentExecutionReceipt>,
)> {
    request.validate_mutation()?;
    let program = request
        .mutation
        .as_ref()
        .ok_or_else(|| Error::internal("Metal continuation result has no mutation program"))?;
    let continuation = program
        .continuation
        .as_ref()
        .ok_or_else(|| Error::internal("Metal continuation result has no continuation"))?;
    let word = |index: usize| {
        words
            .get(index)
            .copied()
            .map(|value| value as u64)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation output is truncated",
                )
            })
    };
    if words.len() < METAL_MUTATION_CONTINUATION_HEADER_WORDS
        || word(0)? != METAL_MUTATION_CONTINUATION_MAGIC
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation returned an invalid result frame",
        ));
    }
    match word(1)? {
        1 => {}
        3 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal mutation continuation encountered a non-integer property",
            ));
        }
        4 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal mutation continuation aggregate overflowed",
            ));
        }
        5 => {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal mutation continuation exceeded its final relation capacity",
            ));
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation continuation rejected its sealed packet",
            ));
        }
    }
    let project_bits = (u128::from(word(4)?) << 64) | u128::from(word(5)?);
    let project = ProjectId(uuid::Uuid::from_u128(project_bits));
    let bookmark = Bookmark {
        term: word(6)?,
        index: word(7)?,
    };
    let mut fingerprint = [0_u8; 32];
    for index in 0..4 {
        fingerprint[index * 8..index * 8 + 8].copy_from_slice(&word(10 + index)?.to_le_bytes());
    }
    let fingerprint = super::ResidentMutationPipelineFingerprint(fingerprint);
    let selected_rows = usize::try_from(word(15)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation selected-row count exceeds host address space",
        )
    })?;
    let final_rows = usize::try_from(word(16)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation final-row count exceeds host address space",
        )
    })?;
    let receipt_count = usize::try_from(word(17)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation receipt count exceeds host address space",
        )
    })?;
    let dependency_count = usize::try_from(word(19)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation dependency count exceeds host address space",
        )
    })?;
    let dependency_capacity = usize::try_from(word(20)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation dependency capacity exceeds host address space",
        )
    })?;
    let expected_receipts = continuation
        .stages
        .len()
        .checked_add(3)
        .ok_or_else(|| Error::internal("Metal mutation continuation receipt count overflow"))?;
    let expected_output_kind = match continuation.outputs.as_slice() {
        [
            super::ResidentMutationOutput {
                source: super::ResidentMutationProjectionSource::Entity(_),
                ..
            },
        ] => METAL_MUTATION_CONTINUATION_OUTPUT_ENTITY,
        [
            super::ResidentMutationOutput {
                source:
                    super::ResidentMutationProjectionSource::IntegerProperty(_)
                    | super::ResidentMutationProjectionSource::PropertyIsNotNull(_)
                    | super::ResidentMutationProjectionSource::PropertyCount(_),
                ..
            },
        ] => METAL_MUTATION_CONTINUATION_OUTPUT_INTEGER,
        [
            super::ResidentMutationOutput {
                source: super::ResidentMutationProjectionSource::AggregateInteger,
                ..
            },
        ] => METAL_MUTATION_CONTINUATION_OUTPUT_AGGREGATE,
        outputs
            if !outputs.is_empty()
                && outputs.iter().all(|output| {
                    matches!(
                        output.source,
                        super::ResidentMutationProjectionSource::ComputedValue(_)
                    )
                }) =>
        {
            METAL_MUTATION_CONTINUATION_OUTPUT_COMPUTED
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation continuation has an unsupported final output shape",
            ));
        }
    };
    let expected_words = METAL_MUTATION_CONTINUATION_HEADER_WORDS
        .checked_add(
            receipt_count
                .checked_mul(METAL_MUTATION_CONTINUATION_RECEIPT_WORDS)
                .ok_or_else(|| Error::internal("Metal continuation receipt frame overflow"))?,
        )
        .and_then(|count| {
            dependency_capacity
                .checked_mul(METAL_MUTATION_CONTINUATION_DEPENDENCY_WORDS)
                .and_then(|dependencies| count.checked_add(dependencies))
        })
        .and_then(|count| {
            continuation
                .maximum_output_rows
                .checked_mul(2)
                .and_then(|values| count.checked_add(values))
        })
        .and_then(|count| {
            selected_rows
                .checked_mul(3)
                .and_then(|scratch| count.checked_add(scratch))
        })
        .ok_or_else(|| Error::internal("Metal continuation result frame overflow"))?;
    if word(2)? != program.execution.high
        || word(3)? != program.execution.low
        || project != request.project
        || bookmark != continuation.expected_bookmark
        || word(8)? != continuation.expected_graph_revision
        || word(9)? != continuation.expected_layout_version
        || fingerprint != continuation.fingerprint
        || fingerprint != request.mutation_pipeline_fingerprint()?
        || word(14)? != super::ResidentDeviceCompletion::Metal as u64
        || selected_rows > request.max_output_rows
        || final_rows > continuation.maximum_output_rows
        || receipt_count != expected_receipts
        || dependency_count > dependency_capacity
        || dependency_capacity != continuation.maximum_read_dependencies
        || word(18)? != u64::from(expected_output_kind)
        || words.len() != expected_words
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation returned invalid provenance or capacity metadata",
        ));
    }

    let expected_obligations = std::iter::once(continuation.read_dependency_obligation)
        .chain(std::iter::once(continuation.overlay_obligation))
        .chain(continuation.stage_obligations.iter().copied())
        .chain(std::iter::once(continuation.final_relation_obligation))
        .collect::<Vec<_>>();
    let mut receipts = Vec::with_capacity(receipt_count);
    for (index, expected) in expected_obligations.into_iter().enumerate() {
        let base = METAL_MUTATION_CONTINUATION_HEADER_WORDS
            + index * METAL_MUTATION_CONTINUATION_RECEIPT_WORDS;
        let kind = match word(base + 3)? {
            2 => super::ResidentObligationKind::MutationRhs,
            3 => super::ResidentObligationKind::Expression,
            4 => super::ResidentObligationKind::Filter,
            9 => super::ResidentObligationKind::Sort,
            10 => super::ResidentObligationKind::Aggregate,
            13 => super::ResidentObligationKind::MutationReadSet,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation receipt has an unknown obligation kind",
                ));
            }
        };
        let scope_index = u16::try_from(word(base + 5)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation continuation receipt scope exceeds u16",
            )
        })?;
        let scope = match word(base + 4)? {
            0 => super::ResidentObligationScope::Selection,
            2 => super::ResidentObligationScope::Expression(scope_index),
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation receipt has an invalid scope",
                ));
            }
        };
        let obligation = super::ResidentExecutionObligation {
            id: word(base + 2)?,
            kind,
            scope,
        };
        let execution = super::ResidentExecutionId {
            high: word(base)?,
            low: word(base + 1)?,
        };
        if execution != program.execution
            || obligation != expected
            || word(base + 8)? != super::ResidentDeviceCompletion::Metal as u64
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation continuation receipt has forged order or provenance",
            ));
        }
        receipts.push(super::ResidentExecutionReceipt {
            execution,
            obligation,
            input_cardinality: word(base + 6)?,
            output_cardinality: word(base + 7)?,
            completion: super::ResidentDeviceCompletion::Metal,
        });
    }

    let dependencies_base = METAL_MUTATION_CONTINUATION_HEADER_WORDS
        + receipt_count * METAL_MUTATION_CONTINUATION_RECEIPT_WORDS;
    let read_dependencies = (0..dependency_count)
        .map(|index| {
            let base = dependencies_base + index * METAL_MUTATION_CONTINUATION_DEPENDENCY_WORDS;
            let dense_row = u32::try_from(word(base + 1)?).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation dependency row exceeds u32",
                )
            })?;
            if dense_row == super::RESIDENT_NULL_ROW {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation emitted a null read dependency",
                ));
            }
            match word(base)? {
                0 => Ok(super::ResidentMutationReadDependency::Node(dense_row)),
                1 => Ok(super::ResidentMutationReadDependency::Relationship(
                    dense_row,
                )),
                _ => Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation emitted an unknown dependency kind",
                )),
            }
        })
        .collect::<Result<Vec<_>>>()?;
    if read_dependencies.windows(2).any(|pair| pair[0] >= pair[1]) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation emitted an unordered read set",
        ));
    }
    let values_base =
        dependencies_base + dependency_capacity * METAL_MUTATION_CONTINUATION_DEPENDENCY_WORDS;
    let validity_base = values_base + continuation.maximum_output_rows;
    let values = (0..final_rows)
        .map(|index| word(values_base + index).map(|value| value as i64))
        .collect::<Result<Vec<_>>>()?;
    let validity = (0..final_rows)
        .map(|index| {
            u8::try_from(word(validity_base + index)?).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation validity contains a non-byte value",
                )
            })
        })
        .collect::<Result<Vec<_>>>()?;
    if validity.iter().any(|valid| *valid > 1) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal mutation continuation validity is not canonical",
        ));
    }
    let source = continuation.outputs[0].source;
    let column = match source {
        super::ResidentMutationProjectionSource::Entity(source) => {
            if validity.iter().any(|valid| *valid != 1) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation entity output is nullable",
                ));
            }
            let dense_rows = values
                .into_iter()
                .map(|value| {
                    u32::try_from(value as u64).map_err(|_| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal mutation continuation entity row exceeds u32",
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            super::ResidentMutationRelationColumn::Entity { source, dense_rows }
        }
        super::ResidentMutationProjectionSource::IntegerProperty(_)
        | super::ResidentMutationProjectionSource::PropertyIsNotNull(_)
        | super::ResidentMutationProjectionSource::PropertyCount(_)
        | super::ResidentMutationProjectionSource::AggregateInteger => {
            if matches!(
                source,
                super::ResidentMutationProjectionSource::PropertyIsNotNull(_)
            ) && (validity.iter().any(|valid| *valid != 1)
                || values.iter().any(|value| !matches!(*value, 0 | 1)))
            {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal mutation continuation returned a non-canonical Boolean",
                ));
            }
            super::ResidentMutationRelationColumn::Integer {
                source,
                values,
                validity,
            }
        }
        super::ResidentMutationProjectionSource::ComputedValue(0) => {
            super::ResidentMutationRelationColumn::Value {
                source,
                values: vec![ResidentQuantifierValue::Null; final_rows],
            }
        }
        super::ResidentMutationProjectionSource::ComputedValue(_) => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal mutation continuation computed output index is invalid",
            ));
        }
    };
    Ok((
        read_dependencies,
        super::ResidentMutationFinalRelation {
            row_count: final_rows,
            columns: vec![column],
            arena: Vec::new(),
        },
        receipts,
    ))
}

fn decode_metal_row_create_continuation(
    words: &[i64],
    request: &ResidentRowMutationRequest,
    expected_rows: usize,
) -> Result<(
    Vec<super::ResidentRowCreateContinuationStageLineage>,
    super::ResidentRowCreateFinalRelation,
    Vec<ResidentExecutionReceipt>,
)> {
    request.validate()?;
    let body = request
        .create_body()
        .ok_or_else(|| Error::internal("Metal row CREATE continuation result lost its body"))?;
    let continuation =
        body.program.continuation.as_ref().ok_or_else(|| {
            Error::internal("Metal row CREATE continuation result lost its program")
        })?;
    let word = |index: usize| {
        words
            .get(index)
            .copied()
            .map(|value| value as u64)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row CREATE continuation output is truncated",
                )
            })
    };
    if words.len() < METAL_ROW_CREATE_CONTINUATION_HEADER_WORDS
        || word(0)? != METAL_ROW_CREATE_CONTINUATION_MAGIC
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal row CREATE continuation returned an invalid result frame",
        ));
    }
    match word(1)? {
        1 => {}
        3 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal row CREATE continuation encountered a non-integer lane",
            ));
        }
        4 => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "Metal row CREATE continuation SUM overflowed INTEGER",
            ));
        }
        5 => {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal row CREATE continuation exceeded its final relation capacity",
            ));
        }
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal row CREATE continuation rejected its sealed packet",
            ));
        }
    }
    let mut fingerprint = [0_u8; 32];
    for index in 0..4 {
        fingerprint[index * 8..index * 8 + 8].copy_from_slice(&word(4 + index)?.to_le_bytes());
    }
    let fingerprint = super::ResidentRowMutationFingerprint(fingerprint);
    let selected_rows = usize::try_from(word(8)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal row CREATE continuation row count exceeds usize",
        )
    })?;
    let final_rows = usize::try_from(word(9)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal row CREATE continuation final row count exceeds usize",
        )
    })?;
    let stage_count = usize::try_from(word(10)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal row CREATE continuation stage count exceeds usize",
        )
    })?;
    let receipt_count = usize::try_from(word(11)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal row CREATE continuation receipt count exceeds usize",
        )
    })?;
    let aggregate = match word(13)? {
        0 => false,
        1 => true,
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal row CREATE continuation aggregate bit is malformed",
            ));
        }
    };
    let output_capacity = usize::try_from(word(14)?).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "Metal row CREATE continuation output capacity exceeds usize",
        )
    })?;
    let expected_kind = match continuation.outputs.as_slice() {
        [
            super::ResidentRowCreateContinuationOutput {
                source: super::ResidentRowCreateProjectionSource::Entity(_),
                ..
            },
        ] => METAL_ROW_CREATE_CONTINUATION_OUTPUT_ENTITY,
        [
            super::ResidentRowCreateContinuationOutput {
                source: super::ResidentRowCreateProjectionSource::IntegerProperty { .. },
                ..
            },
        ] => METAL_ROW_CREATE_CONTINUATION_OUTPUT_INTEGER,
        [
            super::ResidentRowCreateContinuationOutput {
                source: super::ResidentRowCreateProjectionSource::AggregateInteger,
                ..
            },
        ] => METAL_ROW_CREATE_CONTINUATION_OUTPUT_AGGREGATE,
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal row CREATE continuation output shape changed",
            ));
        }
    };
    let expected_words = METAL_ROW_CREATE_CONTINUATION_HEADER_WORDS
        .checked_add(
            receipt_count
                .checked_mul(METAL_ROW_CREATE_CONTINUATION_RECEIPT_WORDS)
                .ok_or_else(|| Error::internal("row CREATE receipt frame overflow"))?,
        )
        .and_then(|words| words.checked_add(stage_count))
        .and_then(|words| {
            stage_count
                .checked_mul(output_capacity)
                .and_then(|lineage| words.checked_add(lineage))
        })
        .and_then(|words| {
            output_capacity
                .checked_mul(4)
                .and_then(|relation| words.checked_add(relation))
        })
        .ok_or_else(|| Error::internal("row CREATE continuation frame overflow"))?;
    if word(2)? != request.execution.high
        || word(3)? != request.execution.low
        || fingerprint != request.fingerprint
        || selected_rows != expected_rows
        || stage_count != continuation.stages.len()
        || receipt_count != stage_count.saturating_add(1)
        || final_rows > output_capacity
        || output_capacity != expected_rows.max(1)
        || word(12)? != u64::from(expected_kind)
        || word(15)? != super::ResidentDeviceCompletion::Metal as u64
        || aggregate
            != matches!(
                continuation.outputs[0].source,
                super::ResidentRowCreateProjectionSource::AggregateInteger
            )
        || words.len() != expected_words
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal row CREATE continuation returned invalid provenance or capacity metadata",
        ));
    }

    let expected_obligations = continuation
        .stage_obligations
        .iter()
        .copied()
        .chain(std::iter::once(body.program.final_relation_obligation));
    let mut receipts = Vec::with_capacity(receipt_count);
    for (index, expected) in expected_obligations.enumerate() {
        let base = METAL_ROW_CREATE_CONTINUATION_HEADER_WORDS
            + index * METAL_ROW_CREATE_CONTINUATION_RECEIPT_WORDS;
        let kind = match word(base + 3)? {
            3 => super::ResidentObligationKind::Expression,
            4 => super::ResidentObligationKind::Filter,
            9 => super::ResidentObligationKind::Sort,
            10 => super::ResidentObligationKind::Aggregate,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row CREATE continuation receipt has an unknown kind",
                ));
            }
        };
        let scope_index = u16::try_from(word(base + 5)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal row CREATE continuation receipt scope exceeds u16",
            )
        })?;
        let scope = match word(base + 4)? {
            2 => super::ResidentObligationScope::Expression(scope_index),
            5 if scope_index == 0 => super::ResidentObligationScope::PatternFinal,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row CREATE continuation receipt scope is invalid",
                ));
            }
        };
        let receipt = ResidentExecutionReceipt {
            execution: super::ResidentExecutionId {
                high: word(base)?,
                low: word(base + 1)?,
            },
            obligation: super::ResidentExecutionObligation {
                id: word(base + 2)?,
                kind,
                scope,
            },
            input_cardinality: word(base + 6)?,
            output_cardinality: word(base + 7)?,
            completion: super::ResidentDeviceCompletion::Metal,
        };
        if receipt.execution != request.execution
            || receipt.obligation != expected
            || word(base + 8)? != super::ResidentDeviceCompletion::Metal as u64
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal row CREATE continuation receipt forged order or provenance",
            ));
        }
        receipts.push(receipt);
    }

    let stage_count_base = METAL_ROW_CREATE_CONTINUATION_HEADER_WORDS
        + receipt_count * METAL_ROW_CREATE_CONTINUATION_RECEIPT_WORDS;
    let stage_lineage_base = stage_count_base + stage_count;
    let mut lineage = Vec::with_capacity(stage_count);
    for stage in 0..stage_count {
        let count = usize::try_from(word(stage_count_base + stage)?).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "Metal row CREATE continuation lineage count exceeds usize",
            )
        })?;
        if count > output_capacity {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "Metal row CREATE continuation lineage exceeds its capacity",
            ));
        }
        let base = stage_lineage_base + stage * output_capacity;
        let work_rows = (0..count)
            .map(|index| {
                let row = word(base + index)?;
                if usize::try_from(row)
                    .ok()
                    .is_none_or(|row| row >= selected_rows)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal row CREATE continuation lineage names a foreign row",
                    ));
                }
                Ok(row)
            })
            .collect::<Result<Vec<_>>>()?;
        lineage.push(super::ResidentRowCreateContinuationStageLineage {
            stage: u16::try_from(stage).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row CREATE continuation stage exceeds u16",
                )
            })?,
            work_rows,
        });
    }

    let final_position_base = stage_lineage_base + stage_count * output_capacity;
    let value_base = final_position_base + output_capacity;
    let validity_base = value_base + output_capacity;
    let work_rows = if aggregate {
        Vec::new()
    } else {
        (0..final_rows)
            .map(|index| {
                let row = word(final_position_base + index)?;
                if usize::try_from(row)
                    .ok()
                    .is_none_or(|row| row >= selected_rows)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "Metal row CREATE final lineage names a foreign row",
                    ));
                }
                Ok(row)
            })
            .collect::<Result<Vec<_>>>()?
    };
    let column = match continuation.outputs[0].source {
        super::ResidentRowCreateProjectionSource::Entity(_) => {
            super::ResidentRowCreateContinuationColumn::Entity { output: 0 }
        }
        super::ResidentRowCreateProjectionSource::IntegerProperty { .. }
        | super::ResidentRowCreateProjectionSource::AggregateInteger => {
            let values = (0..final_rows)
                .map(|index| word(value_base + index).map(|value| value as i64))
                .collect::<Result<Vec<_>>>()?;
            let validity = (0..final_rows)
                .map(|index| {
                    u8::try_from(word(validity_base + index)?).map_err(|_| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "Metal row CREATE continuation validity is not a byte",
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            if validity.iter().any(|valid| *valid > 1) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row CREATE continuation validity is not canonical",
                ));
            }
            super::ResidentRowCreateContinuationColumn::Integer {
                output: 0,
                values,
                validity,
            }
        }
    };
    Ok((
        lineage,
        super::ResidentRowCreateFinalRelation {
            row_count: u64::try_from(final_rows).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "Metal row CREATE final cardinality exceeds u64",
                )
            })?,
            work_rows,
            columns: vec![column],
        },
        receipts,
    ))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_GRAPH_THREADS: usize = 256;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_GRAPH_CONTROL_WORDS: usize = 8;
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
const METAL_GRAPH_EDGE_TILE: usize = 1 << 20;

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[repr(C)]
#[derive(Clone, Copy, Debug)]
struct MetalGraphBfsArgs {
    node_count: u32,
    edge_count: u32,
    adjacency_count: u32,
    source_dense: u32,
    layer_mask: u32,
    depth: u32,
    edge_begin: u32,
    edge_end: u32,
    node_begin: u32,
    overlay_count: u32,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl MetalGraphBfsArgs {
    fn new(
        node_count: usize,
        edge_count: usize,
        adjacency_count: usize,
        source_dense: u32,
        layer_mask: u32,
        depth: usize,
        edge_begin: usize,
        edge_end: usize,
        node_begin: usize,
        overlay_count: usize,
    ) -> candle_core::Result<Self> {
        graph_paths::validate_u32_workspace_words(node_count, 3, METAL_GRAPH_CONTROL_WORDS, "BFS")?;
        if edge_begin > edge_end
            || edge_end > adjacency_count.max(edge_count)
            || node_begin > node_count
        {
            return Err(candle_core::Error::Msg(
                "Metal BFS physical-edge tile is invalid".to_owned(),
            ));
        }
        Ok(Self {
            node_count: u32::try_from(node_count).map_err(|_| {
                candle_core::Error::Msg("Metal BFS node count exceeds u32".to_owned())
            })?,
            edge_count: u32::try_from(edge_count).map_err(|_| {
                candle_core::Error::Msg("Metal BFS edge capacity exceeds u32".to_owned())
            })?,
            adjacency_count: u32::try_from(adjacency_count).map_err(|_| {
                candle_core::Error::Msg("Metal BFS adjacency count exceeds u32".to_owned())
            })?,
            source_dense,
            layer_mask,
            depth: u32::try_from(depth)
                .map_err(|_| candle_core::Error::Msg("Metal BFS depth exceeds u32".to_owned()))?,
            edge_begin: u32::try_from(edge_begin).map_err(|_| {
                candle_core::Error::Msg("Metal BFS tile start exceeds u32".to_owned())
            })?,
            edge_end: u32::try_from(edge_end).map_err(|_| {
                candle_core::Error::Msg("Metal BFS tile end exceeds u32".to_owned())
            })?,
            node_begin: u32::try_from(node_begin).map_err(|_| {
                candle_core::Error::Msg("Metal BFS node tile start exceeds u32".to_owned())
            })?,
            overlay_count: u32::try_from(overlay_count).map_err(|_| {
                candle_core::Error::Msg("Metal BFS overlay row count exceeds u32".to_owned())
            })?,
        })
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone)]
struct MetalGraphPipelines {
    bfs_initialize: candle_metal_kernels::metal::ComputePipeline,
    bfs_prepare: candle_metal_kernels::metal::ComputePipeline,
    bfs_top_down: candle_metal_kernels::metal::ComputePipeline,
    bfs_bottom_up: candle_metal_kernels::metal::ComputePipeline,
    pagerank_prepare: candle_metal_kernels::metal::ComputePipeline,
    pagerank_initialize_nodes: candle_metal_kernels::metal::ComputePipeline,
    pagerank_degree_edges: candle_metal_kernels::metal::ComputePipeline,
    pagerank_dangling_chunk: candle_metal_kernels::metal::ComputePipeline,
    pagerank_pull_prepare: candle_metal_kernels::metal::ComputePipeline,
    pagerank_pending_clear: candle_metal_kernels::metal::ComputePipeline,
    pagerank_pull_scan: candle_metal_kernels::metal::ComputePipeline,
    pagerank_delta_chunk: candle_metal_kernels::metal::ComputePipeline,
    pagerank_publish: candle_metal_kernels::metal::ComputePipeline,
    dijkstra_unit_prepare: candle_metal_kernels::metal::ComputePipeline,
    dijkstra_unit_finalize: candle_metal_kernels::metal::ComputePipeline,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_graph_pipelines(
    device: &candle_core::MetalDevice,
) -> candle_core::Result<MetalGraphPipelines> {
    static PIPELINES: OnceLock<MetalGraphPipelines> = OnceLock::new();
    if let Some(pipelines) = PIPELINES.get() {
        return Ok(pipelines.clone());
    }
    let library = device
        .metal_device()
        .new_library_with_source(include_str!("../../../kernels/metal/operators.metal"), None)
        .map_err(|error| {
            candle_core::Error::Msg(format!("compiling Metal graph kernels failed: {error}"))
        })?;
    let pipeline = |name: &str| -> candle_core::Result<_> {
        let function = library.get_function(name, None).map_err(|error| {
            candle_core::Error::Msg(format!("loading Metal graph kernel {name} failed: {error}"))
        })?;
        let raw = device
            .metal_device()
            .as_ref()
            .newComputePipelineStateWithFunction_error(function.as_ref())
            .map_err(|error| {
                candle_core::Error::Msg(format!(
                    "creating Metal graph pipeline {name} failed: {error:?}"
                ))
            })?;
        Ok(candle_metal_kernels::metal::ComputePipeline::new(raw))
    };
    let pipelines = MetalGraphPipelines {
        bfs_initialize: pipeline("ig_graph_bfs_initialize")?,
        bfs_prepare: pipeline("ig_graph_bfs_prepare_step")?,
        bfs_top_down: pipeline("ig_graph_bfs_top_down_step")?,
        bfs_bottom_up: pipeline("ig_graph_bfs_bottom_up_step")?,
        pagerank_prepare: pipeline("ig_graph_pagerank_prepare")?,
        pagerank_initialize_nodes: pipeline("ig_graph_pagerank_initialize_nodes")?,
        pagerank_degree_edges: pipeline("ig_graph_pagerank_degree_edges")?,
        pagerank_dangling_chunk: pipeline("ig_graph_pagerank_dangling_chunk")?,
        pagerank_pull_prepare: pipeline("ig_graph_pagerank_pull_prepare")?,
        pagerank_pending_clear: pipeline("ig_graph_pagerank_pending_clear")?,
        pagerank_pull_scan: pipeline("ig_graph_pagerank_pull_scan")?,
        pagerank_delta_chunk: pipeline("ig_graph_pagerank_delta_chunk")?,
        pagerank_publish: pipeline("ig_graph_pagerank_publish")?,
        dijkstra_unit_prepare: pipeline("ig_graph_dijkstra_unit_prepare")?,
        dijkstra_unit_finalize: pipeline("ig_graph_dijkstra_unit_finalize")?,
    };
    for candidate in [
        &pipelines.bfs_initialize,
        &pipelines.bfs_prepare,
        &pipelines.bfs_top_down,
        &pipelines.bfs_bottom_up,
        &pipelines.pagerank_prepare,
        &pipelines.pagerank_initialize_nodes,
        &pipelines.pagerank_degree_edges,
        &pipelines.pagerank_dangling_chunk,
        &pipelines.pagerank_pull_prepare,
        &pipelines.pagerank_pending_clear,
        &pipelines.pagerank_pull_scan,
        &pipelines.pagerank_delta_chunk,
        &pipelines.pagerank_publish,
        &pipelines.dijkstra_unit_prepare,
        &pipelines.dijkstra_unit_finalize,
    ] {
        if candidate.max_total_threads_per_threadgroup() < METAL_GRAPH_THREADS {
            return Err(candle_core::Error::Msg(
                "selected Metal device cannot run 256-thread graph groups".to_owned(),
            ));
        }
    }
    let _ = PIPELINES.set(pipelines.clone());
    Ok(PIPELINES.get().cloned().unwrap_or(pipelines))
}

/// Compile, cache, and validate the shared traversal/PageRank operator library at backend startup.
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
pub fn prepare_metal_graph_pipelines(device: &Device) -> Result<()> {
    let Device::Metal(device) = device else {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal graph pipeline preparation requires a Metal device",
        ));
    };
    metal_graph_pipelines(device).map_err(candle_error)?;
    Ok(())
}

/// Compile, cache, and validate every production sparse-graph pipeline before a Metal backend is
/// admitted. Keeping this in the accelerator owner prevents backend construction from drifting
/// away from the exact libraries used by graph-procedure execution.
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
pub fn prepare_metal_graph_algorithm_kernels(device: &Device) -> Result<()> {
    prepare_metal_graph_pipelines(device)?;
    graph_paths::prepare(device)?;
    graph_components_metrics::prepare(device)?;
    graph_louvain::prepare(device)?;
    Ok(())
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Copy, Debug)]
struct MetalGraphBfsInitialize {
    node_count: usize,
    edge_count: usize,
    source_dense: u32,
    layer_mask: u32,
    workspace_words: usize,
    node_begin: usize,
    node_end: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp2 for MetalGraphBfsInitialize {
    fn name(&self) -> &'static str {
        "irongraph-metal-graph-bfs-initialize"
    }

    fn cpu_fwd(
        &self,
        _visible_nodes: &CpuStorage,
        _visible_nodes_layout: &Layout,
        _workspace: &CpuStorage,
        _workspace_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal graph BFS initialization cannot execute on CPU".to_owned(),
        ))
    }

    #[allow(clippy::significant_drop_tightening)]
    fn metal_fwd(
        &self,
        visible_nodes: &MetalStorage,
        visible_nodes_layout: &Layout,
        workspace: &MetalStorage,
        workspace_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        if self.node_count == 0
            || self.source_dense as usize >= self.node_count
            || self.layer_mask == 0
            || self.node_begin >= self.node_end
            || self.node_end > self.node_count
            || visible_nodes.dtype() != DType::U8
            || workspace.dtype() != DType::U32
            || !visible_nodes_layout.is_contiguous()
            || !workspace_layout.is_contiguous()
            || visible_nodes_layout.dims().len() != 1
            || workspace_layout.dims().len() != 1
            || visible_nodes_layout.shape().elem_count() != self.node_count
            || workspace_layout.shape().elem_count() != self.workspace_words
        {
            return Err(candle_core::Error::Msg(
                "Metal graph BFS initialization contract is invalid".to_owned(),
            ));
        }
        let expected_workspace_words = self
            .node_count
            .checked_mul(3)
            .and_then(|words| words.checked_add(METAL_GRAPH_CONTROL_WORDS))
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal graph BFS workspace size overflow".to_owned())
            })?;
        if expected_workspace_words != self.workspace_words {
            return Err(candle_core::Error::Msg(
                "Metal graph BFS initialization workspace size is invalid".to_owned(),
            ));
        }
        let arguments = MetalGraphBfsArgs::new(
            self.node_count,
            self.edge_count,
            0,
            self.source_dense,
            self.layer_mask,
            0,
            0,
            0,
            self.node_begin,
            0,
        )?;
        let device = visible_nodes.device();
        let pipelines = metal_graph_pipelines(device)?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&pipelines.bfs_initialize);
        encoder.set_input_buffer(
            0,
            Some(visible_nodes.buffer()),
            visible_nodes_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        let workspace_base = workspace_layout.start_offset() * DType::U32.size_in_bytes();
        encoder.set_output_buffer(1, Some(workspace.buffer()), workspace_base);
        encoder.set_output_buffer(
            2,
            Some(workspace.buffer()),
            workspace_base + self.node_count * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(
            3,
            Some(workspace.buffer()),
            workspace_base + self.node_count * 2 * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(
            4,
            Some(workspace.buffer()),
            workspace_base + self.node_count * 3 * DType::U32.size_in_bytes(),
        );
        encoder.set_bytes(5, &arguments);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: (self.node_end - self.node_begin).div_ceil(METAL_GRAPH_THREADS),
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_GRAPH_THREADS,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(
                Arc::new(workspace.buffer().clone()),
                device.clone(),
                self.workspace_words,
                DType::U32,
            ),
            Shape::from(self.workspace_words),
        ))
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Debug)]
struct MetalGraphBfsChunk {
    outgoing_offsets: Tensor,
    outgoing_neighbors: Tensor,
    outgoing_edges: Tensor,
    outgoing_overlay: Tensor,
    incoming_offsets: Tensor,
    incoming_neighbors: Tensor,
    incoming_edges: Tensor,
    incoming_overlay: Tensor,
    visible_nodes: Tensor,
    edge_active: Tensor,
    edge_layers: Tensor,
    node_count: usize,
    edge_count: usize,
    adjacency_count: usize,
    outgoing_overlay_count: usize,
    incoming_overlay_count: usize,
    source_dense: u32,
    layer_mask: u32,
    first_depth: usize,
    level_count: usize,
    bottom_up: bool,
    edge_begin: usize,
    edge_end: usize,
    prepare: bool,
    node_begin: usize,
    node_end: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp1 for MetalGraphBfsChunk {
    fn name(&self) -> &'static str {
        "irongraph-metal-graph-bfs-chunk"
    }

    fn cpu_fwd(
        &self,
        _workspace: &CpuStorage,
        _workspace_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal graph BFS chunk cannot execute on CPU".to_owned(),
        ))
    }

    #[allow(clippy::significant_drop_tightening, clippy::too_many_lines)]
    fn metal_fwd(
        &self,
        workspace: &MetalStorage,
        workspace_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        macro_rules! metal_tensor {
            ($field:ident, $storage:ident, $layout:ident, $metal:ident, $message:literal) => {
                let ($storage, $layout) = self.$field.storage_and_layout();
                let Storage::Metal($metal) = &*$storage else {
                    return Err(candle_core::Error::Msg($message.to_owned()));
                };
            };
        }
        metal_tensor!(
            outgoing_offsets,
            offsets_storage,
            offsets_layout,
            offsets,
            "Metal graph BFS offsets moved off device"
        );
        metal_tensor!(
            outgoing_neighbors,
            neighbors_storage,
            neighbors_layout,
            neighbors,
            "Metal graph BFS neighbors moved off device"
        );
        metal_tensor!(
            outgoing_edges,
            edges_storage,
            edges_layout,
            edges,
            "Metal graph BFS edge rows moved off device"
        );
        metal_tensor!(
            outgoing_overlay,
            outgoing_overlay_storage,
            outgoing_overlay_layout,
            outgoing_overlay,
            "Metal graph BFS outgoing overlay moved off device"
        );
        metal_tensor!(
            incoming_offsets,
            incoming_offsets_storage,
            incoming_offsets_layout,
            incoming_offsets,
            "Metal graph BFS incoming offsets moved off device"
        );
        metal_tensor!(
            incoming_neighbors,
            incoming_neighbors_storage,
            incoming_neighbors_layout,
            incoming_neighbors,
            "Metal graph BFS incoming neighbors moved off device"
        );
        metal_tensor!(
            incoming_edges,
            incoming_edges_storage,
            incoming_edges_layout,
            incoming_edges,
            "Metal graph BFS incoming edge rows moved off device"
        );
        metal_tensor!(
            incoming_overlay,
            incoming_overlay_storage,
            incoming_overlay_layout,
            incoming_overlay,
            "Metal graph BFS incoming overlay moved off device"
        );
        metal_tensor!(
            visible_nodes,
            visible_nodes_storage,
            visible_nodes_layout,
            visible_nodes,
            "Metal graph BFS visible-node mask moved off device"
        );
        metal_tensor!(
            edge_active,
            edge_active_storage,
            edge_active_layout,
            edge_active,
            "Metal graph BFS edge-active column moved off device"
        );
        metal_tensor!(
            edge_layers,
            edge_layers_storage,
            edge_layers_layout,
            edge_layers,
            "Metal graph BFS edge-layer column moved off device"
        );
        let workspace_words = self
            .node_count
            .checked_mul(3)
            .and_then(|words| words.checked_add(METAL_GRAPH_CONTROL_WORDS))
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal graph BFS workspace size overflow".to_owned())
            })?;
        let layouts = [
            workspace_layout,
            offsets_layout,
            neighbors_layout,
            edges_layout,
            outgoing_overlay_layout,
            incoming_offsets_layout,
            incoming_neighbors_layout,
            incoming_edges_layout,
            incoming_overlay_layout,
            visible_nodes_layout,
            edge_active_layout,
            edge_layers_layout,
        ];
        if self.node_count == 0
            || (self.adjacency_count == 0
                && self.outgoing_overlay_count == 0
                && self.incoming_overlay_count == 0)
            || self.level_count == 0
            || self.level_count != 1
            || self.edge_begin >= self.edge_end
            || self.edge_end > self.adjacency_count.max(self.edge_count)
            || self.node_begin >= self.node_end
            || self.node_end > self.node_count
            || self.source_dense as usize >= self.node_count
            || self.layer_mask == 0
            || workspace.dtype() != DType::U32
            || self.outgoing_offsets.dtype() != DType::U32
            || self.outgoing_neighbors.dtype() != DType::U32
            || self.outgoing_edges.dtype() != DType::U32
            || self.outgoing_overlay.dtype() != DType::U32
            || self.incoming_offsets.dtype() != DType::U32
            || self.incoming_neighbors.dtype() != DType::U32
            || self.incoming_edges.dtype() != DType::U32
            || self.incoming_overlay.dtype() != DType::U32
            || self.visible_nodes.dtype() != DType::U8
            || self.edge_active.dtype() != DType::U8
            || self.edge_layers.dtype() != DType::U8
            || layouts
                .iter()
                .any(|layout| !layout.is_contiguous() || layout.dims().len() != 1)
            || workspace_layout.shape().elem_count() != workspace_words
            || offsets_layout.shape().elem_count() != self.node_count.saturating_add(1)
            || (self.adjacency_count == 0
                && (neighbors_layout.shape().elem_count() != 1
                    || edges_layout.shape().elem_count() != 1))
            || (self.adjacency_count != 0
                && (neighbors_layout.shape().elem_count() != self.adjacency_count
                    || edges_layout.shape().elem_count() != self.adjacency_count))
            || incoming_offsets_layout.shape().elem_count() != self.node_count.saturating_add(1)
            || incoming_neighbors_layout.shape().elem_count() != self.adjacency_count
            || incoming_edges_layout.shape().elem_count() != self.adjacency_count
            || outgoing_overlay_layout.shape().elem_count()
                < self
                    .outgoing_overlay_count
                    .saturating_mul(2)
                    .saturating_add(1)
            || incoming_overlay_layout.shape().elem_count()
                < self
                    .incoming_overlay_count
                    .saturating_mul(2)
                    .saturating_add(1)
            || visible_nodes_layout.shape().elem_count() != self.node_count
            || edge_active_layout.shape().elem_count() != self.edge_count
            || edge_layers_layout.shape().elem_count() != self.edge_count
        {
            return Err(candle_core::Error::Msg(
                "Metal graph BFS chunk tensor contract is invalid".to_owned(),
            ));
        }
        let device = workspace.device();
        let pipelines = metal_graph_pipelines(device)?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        let distance_offset = workspace_layout.start_offset() * DType::U32.size_in_bytes();
        let first_frontier_offset = distance_offset + self.node_count * DType::U32.size_in_bytes();
        let second_frontier_offset =
            first_frontier_offset + self.node_count * DType::U32.size_in_bytes();
        let control_offset = second_frontier_offset + self.node_count * DType::U32.size_in_bytes();
        for depth in self.first_depth..self.first_depth.saturating_add(self.level_count) {
            let arguments = MetalGraphBfsArgs::new(
                self.node_count,
                self.edge_count,
                self.adjacency_count,
                self.source_dense,
                self.layer_mask,
                depth,
                self.edge_begin,
                self.edge_end,
                self.node_begin,
                if self.bottom_up {
                    self.incoming_overlay_count
                } else {
                    self.outgoing_overlay_count
                },
            )?;
            let (frontier_offset, next_offset) = if depth & 1 == 1 {
                (first_frontier_offset, second_frontier_offset)
            } else {
                (second_frontier_offset, first_frontier_offset)
            };
            if self.prepare {
                encoder.set_compute_pipeline_state(&pipelines.bfs_prepare);
                encoder.set_output_buffer(0, Some(workspace.buffer()), next_offset);
                encoder.set_output_buffer(1, Some(workspace.buffer()), control_offset);
                encoder.set_bytes(2, &arguments);
                encoder.dispatch_thread_groups(
                    objc2_metal::MTLSize {
                        width: (self.node_end - self.node_begin).div_ceil(METAL_GRAPH_THREADS),
                        height: 1,
                        depth: 1,
                    },
                    objc2_metal::MTLSize {
                        width: METAL_GRAPH_THREADS,
                        height: 1,
                        depth: 1,
                    },
                );
                encoder.insert_memory_barrier();
            }
            encoder.set_compute_pipeline_state(if self.bottom_up {
                &pipelines.bfs_bottom_up
            } else {
                &pipelines.bfs_top_down
            });
            let (step_offsets, step_offsets_layout, step_neighbors, step_neighbors_layout) =
                if self.bottom_up {
                    (
                        incoming_offsets,
                        &incoming_offsets_layout,
                        incoming_neighbors,
                        &incoming_neighbors_layout,
                    )
                } else {
                    (offsets, &offsets_layout, neighbors, &neighbors_layout)
                };
            let (step_edges, step_edges_layout) = if self.bottom_up {
                (incoming_edges, &incoming_edges_layout)
            } else {
                (edges, &edges_layout)
            };
            let (step_overlay, step_overlay_layout) = if self.bottom_up {
                (incoming_overlay, &incoming_overlay_layout)
            } else {
                (outgoing_overlay, &outgoing_overlay_layout)
            };
            encoder.set_input_buffer(
                0,
                Some(step_offsets.buffer()),
                step_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            encoder.set_input_buffer(
                1,
                Some(step_neighbors.buffer()),
                step_neighbors_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            encoder.set_input_buffer(
                2,
                Some(step_edges.buffer()),
                step_edges_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            encoder.set_input_buffer(
                3,
                Some(step_overlay.buffer()),
                step_overlay_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            encoder.set_input_buffer(
                4,
                Some(visible_nodes.buffer()),
                visible_nodes_layout.start_offset() * DType::U8.size_in_bytes(),
            );
            encoder.set_input_buffer(
                5,
                Some(edge_active.buffer()),
                edge_active_layout.start_offset() * DType::U8.size_in_bytes(),
            );
            encoder.set_input_buffer(
                6,
                Some(edge_layers.buffer()),
                edge_layers_layout.start_offset() * DType::U8.size_in_bytes(),
            );
            encoder.set_input_buffer(7, Some(workspace.buffer()), frontier_offset);
            encoder.set_output_buffer(8, Some(workspace.buffer()), distance_offset);
            encoder.set_output_buffer(9, Some(workspace.buffer()), next_offset);
            encoder.set_output_buffer(10, Some(workspace.buffer()), control_offset);
            encoder.set_bytes(11, &arguments);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: (self.node_end - self.node_begin).div_ceil(METAL_GRAPH_THREADS),
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: METAL_GRAPH_THREADS,
                    height: 1,
                    depth: 1,
                },
            );
            encoder.insert_memory_barrier();
        }
        Ok((
            MetalStorage::new(
                Arc::new(workspace.buffer().clone()),
                device.clone(),
                workspace_words,
                DType::U32,
            ),
            Shape::from(workspace_words),
        ))
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[repr(C)]
#[derive(Clone, Copy, Debug)]
struct MetalGraphDijkstraUnitArgs {
    node_count: u32,
    edge_count: u32,
    incoming_adjacency_count: u32,
    layer_mask: u32,
    edge_begin: u32,
    edge_end: u32,
    initialize: u32,
    incoming_overlay_count: u32,
    node_begin: u32,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl MetalGraphDijkstraUnitArgs {
    fn new(
        node_count: usize,
        edge_count: usize,
        incoming_adjacency_count: usize,
        layer_mask: u32,
        edge_begin: usize,
        edge_end: usize,
        initialize: bool,
        incoming_overlay_count: usize,
        node_begin: usize,
    ) -> candle_core::Result<Self> {
        graph_paths::validate_u32_workspace_words(
            node_count,
            3,
            METAL_GRAPH_CONTROL_WORDS,
            "unit Dijkstra",
        )?;
        if edge_begin > edge_end
            || edge_end > incoming_adjacency_count.max(edge_count)
            || node_begin > node_count
        {
            return Err(candle_core::Error::Msg(
                "Metal unit Dijkstra physical-edge tile is invalid".to_owned(),
            ));
        }
        Ok(Self {
            node_count: u32::try_from(node_count).map_err(|_| {
                candle_core::Error::Msg("Metal Dijkstra node count exceeds u32".to_owned())
            })?,
            edge_count: u32::try_from(edge_count).map_err(|_| {
                candle_core::Error::Msg("Metal Dijkstra edge capacity exceeds u32".to_owned())
            })?,
            incoming_adjacency_count: u32::try_from(incoming_adjacency_count).map_err(|_| {
                candle_core::Error::Msg("Metal Dijkstra adjacency count exceeds u32".to_owned())
            })?,
            layer_mask,
            edge_begin: u32::try_from(edge_begin).map_err(|_| {
                candle_core::Error::Msg("Metal unit Dijkstra tile start exceeds u32".to_owned())
            })?,
            edge_end: u32::try_from(edge_end).map_err(|_| {
                candle_core::Error::Msg("Metal unit Dijkstra tile end exceeds u32".to_owned())
            })?,
            initialize: u32::from(initialize),
            incoming_overlay_count: u32::try_from(incoming_overlay_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal unit Dijkstra overlay row count exceeds u32".to_owned(),
                )
            })?,
            node_begin: u32::try_from(node_begin).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal unit Dijkstra node tile start exceeds u32".to_owned(),
                )
            })?,
        })
    }
}

