#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp2 for MetalSegmentedTemporalRankPrelude {
    fn name(&self) -> &'static str {
        "irongraph-metal-segmented-temporal-rank-prelude"
    }

    fn cpu_fwd(
        &self,
        _temporal: &CpuStorage,
        _temporal_layout: &Layout,
        _template: &CpuStorage,
        _template_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "sealed Metal temporal-rank prelude cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        temporal: &MetalStorage,
        temporal_layout: &Layout,
        template: &MetalStorage,
        template_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let args = self.arguments;
        let temporal_words = usize::try_from(args.temporal_words).unwrap_or(usize::MAX);
        let packet_words = usize::try_from(args.packet_words).unwrap_or(usize::MAX);
        let template_words = usize::try_from(args.template_words).unwrap_or(usize::MAX);
        if size_of::<MetalSegmentedTemporalRankArgs>() != 15 * size_of::<u64>()
            || temporal_words == usize::MAX
            || packet_words == usize::MAX
            || template_words == usize::MAX
            || args.row_count == 0
            || args.register_stride < super::RESIDENT_TEMPORAL_REGISTER_BASE_WORDS as u64
            || args.expected_function > ResidentTemporalValueFunction::DateTime as u64
            || args.receipt_base != METAL_QUANTIFIER_OUTPUT_HEADER_WORDS as u64
            || args.receipt_count != 5
            || args.cell_capacity != args.row_count.saturating_mul(2)
            || temporal.dtype() != DType::U32
            || template.dtype() != DType::I64
            || !temporal_layout.is_contiguous()
            || !template_layout.is_contiguous()
            || temporal_layout.dims().len() != 1
            || template_layout.dims().len() != 1
            || temporal_layout.shape().elem_count() != temporal_words
            || template_layout.shape().elem_count() != template_words
            || packet_words == 0
            || template_words <= packet_words
        {
            return Err(candle_core::Error::Msg(
                "Metal segmented temporal-rank tensor contract is invalid".to_owned(),
            ));
        }
        let device = temporal.device();
        let output = device
            .new_buffer_builder()
            .with_size_for(packet_words, DType::I64)
            .with_label("irongraph segmented temporal-rank packet")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(
            &metal_sort_pipelines(device)?.segmented_temporal_rank_prelude,
        );
        encoder.set_input_buffer(
            0,
            Some(temporal.buffer()),
            temporal_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(template.buffer()),
            template_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_output_buffer(2, Some(&output), 0);
        encoder.set_bytes(3, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), packet_words, DType::I64),
            Shape::from(packet_words),
        ))
    }
}

