#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp3 for MetalSegmentedGraphAggregationProgram {
    fn name(&self) -> &'static str {
        "irongraph-metal-segmented-graph-aggregation"
    }

    fn cpu_fwd(
        &self,
        _nullable: &CpuStorage,
        _nullable_layout: &Layout,
        _node_ids: &CpuStorage,
        _node_ids_layout: &Layout,
        _edge_ids: &CpuStorage,
        _edge_ids_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal segmented graph aggregation cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        nullable: &MetalStorage,
        nullable_layout: &Layout,
        node_ids: &MetalStorage,
        node_ids_layout: &Layout,
        edge_ids: &MetalStorage,
        edge_ids_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let (program_storage, program_layout) = self.program.storage_and_layout();
        let Storage::Metal(program) = &*program_storage else {
            return Err(candle_core::Error::Msg(
                "segmented graph program moved to a non-Metal device".to_owned(),
            ));
        };
        let (grouping_storage, grouping_layout) = self.grouping.storage_and_layout();
        let Storage::Metal(grouping) = &*grouping_storage else {
            return Err(candle_core::Error::Msg(
                "segmented graph grouping moved to a non-Metal device".to_owned(),
            ));
        };
        let (aggregate_storage, aggregate_layout) = self.aggregates.storage_and_layout();
        let Storage::Metal(aggregates) = &*aggregate_storage else {
            return Err(candle_core::Error::Msg(
                "segmented graph aggregates moved to a non-Metal device".to_owned(),
            ));
        };
        let args = self.arguments;
        let generic = self.generic_arguments;
        let usize_arg = |value: u64, label: &str| {
            usize::try_from(value).map_err(|_| {
                candle_core::Error::Msg(format!(
                    "Metal segmented graph {label} exceeds host addressability"
                ))
            })
        };
        let nullable_words = usize_arg(args.nullable_words, "nullable packet")?;
        let node_id_elems = usize_arg(args.node_id_storage_elems, "node IDs")?;
        let edge_id_elems = usize_arg(args.edge_id_storage_elems, "relationship IDs")?;
        let program_words = usize_arg(args.program_words, "program")?;
        let source_header_words = usize_arg(args.source_header_words, "source header")?;
        let source_cell_words = usize_arg(args.source_cell_words, "source cells")?;
        let source_arena_bytes = usize_arg(args.source_arena_storage_bytes, "source arena")?;
        let generic_receipt_words = usize_arg(args.generic_receipt_words, "generic receipts")?;
        let aggregate_header_words = usize_arg(args.aggregate_header_words, "aggregate header")?;
        let aggregate_cell_words = usize_arg(args.aggregate_cell_words, "aggregate cells")?;
        let aggregate_arena_bytes =
            usize_arg(args.aggregate_arena_storage_bytes, "aggregate arena")?;
        let slot_cell_words = usize_arg(args.slot_cell_words, "slot cells")?;
        let projection_result_words =
            usize_arg(args.projection_result_cell_words, "projection scratch")?;
        let order_rows = usize_arg(args.order_row_elems, "order rows")?;
        let order_key_words = usize_arg(args.order_key_cell_words, "order key scratch")?;
        let output_header_words = usize_arg(args.output_header_words, "output header")?;
        let output_cell_words = usize_arg(args.output_cell_words, "output cells")?;
        let output_arena_bytes = usize_arg(args.output_arena_storage_bytes, "output arena")?;
        let dependency_words = usize_arg(args.dependency_words, "dependencies")?;
        let outer_receipt_words = usize_arg(args.outer_receipt_words, "outer receipts")?;
        let property_presence_bytes =
            usize_arg(args.property_presence_bytes, "PropertyKeys presence")?;
        let reduction_state_words = (generic.reduction_state_capacity as usize)
            .checked_mul(METAL_SEGMENTED_AGGREGATION_STATE_WORDS)
            .ok_or_else(|| {
                candle_core::Error::Msg(
                    "Metal segmented graph reduction-state size overflow".to_owned(),
                )
            })?;
        let pair_capacity = (generic.maximum_output_groups as usize)
            .checked_mul(generic.aggregate_count as usize)
            .ok_or_else(|| {
                candle_core::Error::Msg(
                    "Metal segmented graph aggregate dispatch overflow".to_owned(),
                )
            })?;
        let expected_output_cell_words = (generic.maximum_output_cells as usize)
            .checked_mul(METAL_SEGMENTED_AGGREGATION_CELL_WORDS)
            .ok_or_else(|| {
                candle_core::Error::Msg(
                    "Metal segmented graph output-cell size overflow".to_owned(),
                )
            })?;
        let expected_outer_cell_words = output_cell_words;
        let output_layout = self.output_layout;
        let private_logical_bytes =
            metal_segmented_graph_private_logical_bytes(args, generic, output_layout)
                .map_err(|error| candle_core::Error::Msg(error.message.to_string()))?;
        self.scratch_layout
            .validate_private_shape(private_logical_bytes)
            .map_err(|error| candle_core::Error::Msg(error.message.to_string()))?;
        let expected_property_presence = self.property_keys.as_ref().map_or(0, |property| {
            property
                .nullable_capacity
                .checked_mul(property.descriptor_count)
                .unwrap_or(usize::MAX)
        });
        if size_of::<MetalSegmentedGraphArgs>() != 21 * size_of::<u64>()
            || nullable.dtype() != DType::I64
            || node_ids.dtype() != DType::I64
            || edge_ids.dtype() != DType::I64
            || self.program.dtype() != DType::I64
            || self.grouping.dtype() != DType::U32
            || self.aggregates.dtype() != DType::U32
            || !nullable_layout.is_contiguous()
            || !node_ids_layout.is_contiguous()
            || !edge_ids_layout.is_contiguous()
            || !program_layout.is_contiguous()
            || !grouping_layout.is_contiguous()
            || !aggregate_layout.is_contiguous()
            || nullable_layout.dims().len() != 1
            || node_ids_layout.dims().len() != 1
            || edge_ids_layout.dims().len() != 1
            || program_layout.dims().len() != 1
            || grouping_layout.dims().len() != 1
            || aggregate_layout.dims().len() != 1
            || nullable_layout.shape().elem_count() != nullable_words
            || node_ids_layout.shape().elem_count() != node_id_elems
            || edge_ids_layout.shape().elem_count() != edge_id_elems
            || program_layout.shape().elem_count() != program_words
            || grouping_layout.shape().elem_count() != self.logical_grouping_columns.max(1)
            || aggregate_layout.shape().elem_count() != self.logical_aggregate_words
            || self.logical_aggregate_words
                != generic.aggregate_count as usize * METAL_SEGMENTED_AGGREGATION_AGGREGATE_WORDS
            || source_header_words != METAL_SEGMENTED_AGGREGATION_HEADER_WORDS
            || source_cell_words
                != generic.input_cell_count as usize * METAL_SEGMENTED_AGGREGATION_CELL_WORDS
            || source_arena_bytes != (generic.input_arena_bytes as usize).max(1)
            || generic_receipt_words
                != generic.receipt_record_capacity as usize
                    * METAL_SEGMENTED_AGGREGATION_RECEIPT_WORDS
            || aggregate_header_words != METAL_SEGMENTED_AGGREGATION_HEADER_WORDS
            || aggregate_cell_words != expected_output_cell_words
            || aggregate_arena_bytes != (generic.maximum_output_arena_bytes as usize).max(1)
            || order_rows != generic.maximum_output_groups as usize
            || output_header_words != METAL_SEGMENTED_GRAPH_OUTPUT_HEADER_WORDS
            || expected_outer_cell_words
                != (output_layout.arena_base - output_layout.cell_base) / size_of::<u64>()
            || output_arena_bytes != output_layout.arena_storage_bytes
            || dependency_words
                != (output_layout.receipt_base - output_layout.dependency_base) / size_of::<u64>()
            || outer_receipt_words
                != (output_layout.output_bytes - output_layout.receipt_base) / size_of::<u64>()
            || property_presence_bytes != expected_property_presence
            || self.property_keys.as_ref().is_some_and(|property| {
                property.validities.len() != property.descriptor_count
                    || property.entity_storage_rows.max(1)
                        != match property.entity_kind {
                            ResidentNullableRelationBindingKind::Node => node_id_elems,
                            ResidentNullableRelationBindingKind::Relationship => edge_id_elems,
                        }
            })
            || (self.property_keys.is_some() && self.property_value.is_some())
            || self.property_value.as_ref().is_some_and(|property| {
                property.offsets.dtype() != DType::U32
                    || property.offsets.dims().len() != 1
                    || property.offsets.elem_count() != property.entity_rows.saturating_add(1)
                    || property.bytes.as_ref().is_some_and(|bytes| {
                        bytes.dtype() != DType::U8
                            || bytes.dims().len() != 1
                            || bytes.elem_count() != property.byte_count
                    })
                    || property.validity.as_ref().is_some_and(|validity| {
                        validity.dtype() != DType::U8
                            || validity.dims().len() != 1
                            || validity.elem_count() != property.entity_rows
                    })
                    || (property.entity_rows != 0 && property.validity.is_none())
                    || !matches!(
                        property.mode,
                        METAL_SEGMENTED_PROPERTY_VALUE_STRUCTURAL_DISTINCT
                            | METAL_SEGMENTED_PROPERTY_VALUE_FLAT_LIST_GROUP
                    )
                    || property.maximum_bytes == 0
            })
            || pair_capacity == 0
            || slot_cell_words == 0
        {
            return Err(candle_core::Error::Msg(
                "Metal segmented graph tensor contract is invalid".to_owned(),
            ));
        }

        let device = nullable.device();
        let pipelines = metal_sort_pipelines(device)?;
        let output = device
            .new_buffer_builder()
            .with_size_for(output_layout.output_bytes.max(1), DType::U8)
            .with_label("irongraph segmented graph output")
            .build()?;
        let source_header = device
            .new_buffer_builder()
            .with_size_for(source_header_words.max(1), DType::I64)
            .with_label("irongraph segmented graph source header")
            .build()?;
        let source_cells = device
            .new_buffer_builder()
            .with_size_for(source_cell_words.max(1), DType::I64)
            .with_label("irongraph segmented graph source cells")
            .build()?;
        let source_arena = device
            .new_buffer_builder()
            .with_size_for(source_arena_bytes.max(1), DType::U8)
            .with_label("irongraph segmented graph source arena")
            .build()?;
        let generic_receipts = device
            .new_buffer_builder()
            .with_size_for(generic_receipt_words.max(1), DType::I64)
            .with_label("irongraph segmented graph aggregate receipts")
            .build()?;
        let graph_control = device
            .new_buffer_builder()
            .with_size_for(METAL_SEGMENTED_GRAPH_CONTROL_WORDS, DType::U32)
            .with_label("irongraph segmented graph control")
            .build()?;
        let aggregate_header = device
            .new_buffer_builder()
            .with_size_for(aggregate_header_words.max(1), DType::I64)
            .with_label("irongraph segmented graph aggregate header")
            .build()?;
        let aggregate_cells = device
            .new_buffer_builder()
            .with_size_for(aggregate_cell_words.max(1), DType::I64)
            .with_label("irongraph segmented graph aggregate cells")
            .build()?;
        let aggregate_arena = device
            .new_buffer_builder()
            .with_size_for(aggregate_arena_bytes.max(1), DType::U8)
            .with_label("irongraph segmented graph aggregate arena")
            .build()?;
        let generic_control = device
            .new_buffer_builder()
            .with_size_for(METAL_SEGMENTED_AGGREGATION_CONTROL_WORDS, DType::U32)
            .with_label("irongraph segmented graph aggregate control")
            .build()?;
        let row_group_ids = device
            .new_buffer_builder()
            .with_size_for((generic.row_group_capacity as usize).max(1), DType::U32)
            .with_label("irongraph segmented graph row groups")
            .build()?;
        let group_first_rows = device
            .new_buffer_builder()
            .with_size_for((generic.group_first_capacity as usize).max(1), DType::U32)
            .with_label("irongraph segmented graph first rows")
            .build()?;
        let reduction_states = device
            .new_buffer_builder()
            .with_size_for(reduction_state_words.max(1), DType::I64)
            .with_label("irongraph segmented graph reduction states")
            .build()?;
        let slot_cells = device
            .new_buffer_builder()
            .with_size_for(slot_cell_words.max(1), DType::I64)
            .with_label("irongraph segmented graph slot cells")
            .build()?;
        let projection_results = device
            .new_buffer_builder()
            .with_size_for(projection_result_words.max(1), DType::I64)
            .with_label("irongraph segmented graph projection scratch")
            .build()?;
        let ordered_rows = device
            .new_buffer_builder()
            .with_size_for(order_rows.max(1), DType::U32)
            .with_label("irongraph segmented graph order rows")
            .build()?;
        let order_keys = device
            .new_buffer_builder()
            .with_size_for(order_key_words.max(1), DType::I64)
            .with_label("irongraph segmented graph order keys")
            .build()?;
        let property_presence = device
            .new_buffer_builder()
            .with_size_for(property_presence_bytes.max(1), DType::U8)
            .with_label("irongraph segmented graph PropertyKeys presence")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();

        encoder.set_input_buffer(
            0,
            Some(nullable.buffer()),
            nullable_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(node_ids.buffer()),
            node_ids_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(edge_ids.buffer()),
            edge_ids_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            3,
            Some(program.buffer()),
            program_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_output_buffer(4, Some(&source_header), 0);
        encoder.set_output_buffer(5, Some(&source_cells), 0);
        encoder.set_output_buffer(6, Some(&source_arena), 0);
        encoder.set_output_buffer(7, Some(&output), output_layout.dependency_base);
        encoder.set_output_buffer(8, Some(&generic_receipts), 0);
        encoder.set_output_buffer(9, Some(&graph_control), 0);
        encoder.set_output_buffer(10, Some(&output), 0);
        encoder.set_output_buffer(11, Some(&output), output_layout.cell_base);
        encoder.set_output_buffer(12, Some(&output), output_layout.arena_base);
        encoder.set_output_buffer(13, Some(&output), output_layout.receipt_base);
        encoder.set_bytes(14, &args);
        encoder.set_input_buffer(
            15,
            Some(grouping.buffer()),
            grouping_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            16,
            Some(aggregates.buffer()),
            aggregate_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(17, Some(&property_presence), 0);
        let dispatch_graph_serial = |pipeline: &candle_metal_kernels::metal::ComputePipeline| {
            encoder.set_compute_pipeline_state(pipeline);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
            );
            encoder.insert_memory_barrier();
        };
        for pipeline in [
            &pipelines.segmented_graph_initialize,
            &pipelines.segmented_graph_validate_header_shape,
            &pipelines.segmented_graph_validate_section_layout,
            &pipelines.segmented_graph_validate_capacity_nullable_header,
            &pipelines.segmented_graph_validate_bindings_groups,
            &pipelines.segmented_graph_validate_aggregates_initial,
            &pipelines.segmented_graph_validate_stages,
            &pipelines.segmented_graph_validate_expressions_output,
            &pipelines.segmented_graph_validate_receipts,
        ] {
            dispatch_graph_serial(pipeline);
        }
        let mut property_value_args = MetalSegmentedPropertyValueArgs {
            offset_storage_elems: 1,
            byte_storage_elems: 0,
            validity_storage_elems: 1,
            entity_rows: 0,
            maximum_bytes: 0,
            mode: 0,
        };
        encoder.set_input_buffer(20, Some(&property_presence), 0);
        encoder.set_input_buffer(21, Some(&property_presence), 0);
        encoder.set_input_buffer(22, Some(&property_presence), 0);
        if let Some(property) = &self.property_value {
            let (offset_storage, offset_layout) = property.offsets.storage_and_layout();
            let Storage::Metal(offsets) = &*offset_storage else {
                return Err(candle_core::Error::Msg(
                    "PropertyValue offsets moved to a non-Metal device".to_owned(),
                ));
            };
            if !offset_layout.is_contiguous()
                || offset_layout.dims().len() != 1
                || offset_layout.shape().elem_count() != property.entity_rows.saturating_add(1)
            {
                return Err(candle_core::Error::Msg(
                    "PropertyValue offset tensor contract is invalid".to_owned(),
                ));
            }
            encoder.set_input_buffer(
                20,
                Some(offsets.buffer()),
                offset_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            if let Some(bytes) = &property.bytes {
                let (byte_storage, byte_layout) = bytes.storage_and_layout();
                let Storage::Metal(bytes) = &*byte_storage else {
                    return Err(candle_core::Error::Msg(
                        "PropertyValue bytes moved to a non-Metal device".to_owned(),
                    ));
                };
                if !byte_layout.is_contiguous()
                    || byte_layout.dims().len() != 1
                    || byte_layout.shape().elem_count() != property.byte_count
                {
                    return Err(candle_core::Error::Msg(
                        "PropertyValue byte tensor contract is invalid".to_owned(),
                    ));
                }
                encoder.set_input_buffer(
                    21,
                    Some(bytes.buffer()),
                    byte_layout.start_offset() * DType::U8.size_in_bytes(),
                );
            }
            if let Some(validity) = &property.validity {
                let (validity_storage, validity_layout) = validity.storage_and_layout();
                let Storage::Metal(validity) = &*validity_storage else {
                    return Err(candle_core::Error::Msg(
                        "PropertyValue validity moved to a non-Metal device".to_owned(),
                    ));
                };
                if !validity_layout.is_contiguous()
                    || validity_layout.dims().len() != 1
                    || validity_layout.shape().elem_count() != property.entity_rows
                {
                    return Err(candle_core::Error::Msg(
                        "PropertyValue validity tensor contract is invalid".to_owned(),
                    ));
                }
                encoder.set_input_buffer(
                    22,
                    Some(validity.buffer()),
                    validity_layout.start_offset() * DType::U8.size_in_bytes(),
                );
            }
            property_value_args = MetalSegmentedPropertyValueArgs {
                offset_storage_elems: property.entity_rows.saturating_add(1) as u64,
                byte_storage_elems: property.byte_count as u64,
                validity_storage_elems: property.entity_rows.max(1) as u64,
                entity_rows: property.entity_rows as u64,
                maximum_bytes: property.maximum_bytes as u64,
                mode: property.mode,
            };
        }
        encoder.set_bytes(23, &property_value_args);
        dispatch_graph_serial(&pipelines.segmented_graph_source);
        if let Some(property_keys) = &self.property_keys {
            for (descriptor_index, validity) in property_keys.validities.iter().enumerate() {
                let validity_args;
                if let Some(validity) = validity {
                    let (validity_storage, validity_layout) = validity.storage_and_layout();
                    let Storage::Metal(validity) = &*validity_storage else {
                        return Err(candle_core::Error::Msg(
                            "PropertyKeys validity moved to a non-Metal device".to_owned(),
                        ));
                    };
                    if validity.dtype() != DType::U8
                        || !validity_layout.is_contiguous()
                        || validity_layout.dims().len() != 1
                        || validity_layout.shape().elem_count() != property_keys.entity_storage_rows
                    {
                        return Err(candle_core::Error::Msg(
                            "PropertyKeys validity tensor contract is invalid".to_owned(),
                        ));
                    }
                    encoder.set_input_buffer(
                        18,
                        Some(validity.buffer()),
                        validity_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    validity_args = MetalSegmentedPropertyValidityArgs {
                        descriptor_index: descriptor_index as u64,
                        validity_storage_elems: property_keys.entity_storage_rows as u64,
                        validity_present: 1,
                        reserved: 0,
                    };
                } else {
                    encoder.set_input_buffer(18, Some(&property_presence), 0);
                    validity_args = MetalSegmentedPropertyValidityArgs {
                        descriptor_index: descriptor_index as u64,
                        validity_storage_elems: 1,
                        validity_present: 0,
                        reserved: 0,
                    };
                }
                encoder.set_bytes(19, &validity_args);
                dispatch_graph_serial(&pipelines.segmented_graph_property_keys_mark);
            }
            dispatch_graph_serial(&pipelines.segmented_graph_property_keys_complete);
        }

        let bind_generic = |pipeline: &candle_metal_kernels::metal::ComputePipeline| {
            encoder.set_compute_pipeline_state(pipeline);
            encoder.set_input_buffer(0, Some(&source_header), 0);
            encoder.set_input_buffer(1, Some(&source_cells), 0);
            encoder.set_input_buffer(2, Some(&source_arena), 0);
            encoder.set_input_buffer(
                3,
                Some(grouping.buffer()),
                grouping_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            encoder.set_input_buffer(
                4,
                Some(aggregates.buffer()),
                aggregate_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            encoder.set_output_buffer(5, Some(&generic_receipts), 0);
            encoder.set_output_buffer(6, Some(&aggregate_header), 0);
            encoder.set_output_buffer(7, Some(&aggregate_cells), 0);
            encoder.set_output_buffer(8, Some(&aggregate_arena), 0);
            encoder.set_output_buffer(9, Some(&generic_control), 0);
            encoder.set_output_buffer(10, Some(&row_group_ids), 0);
            encoder.set_output_buffer(11, Some(&group_first_rows), 0);
            encoder.set_output_buffer(12, Some(&reduction_states), 0);
            encoder.set_bytes(13, &generic);
        };
        bind_generic(&pipelines.segmented_aggregation_group);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();
        bind_generic(&pipelines.segmented_aggregation_reduce);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: pair_capacity.div_ceil(METAL_SORT_THREADS),
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();
        bind_generic(&pipelines.segmented_aggregation_finalize);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.segmented_graph_finalize);
        encoder.set_input_buffer(
            0,
            Some(program.buffer()),
            program_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(1, Some(&aggregate_header), 0);
        encoder.set_input_buffer(2, Some(&aggregate_cells), 0);
        encoder.set_input_buffer(3, Some(&aggregate_arena), 0);
        encoder.set_output_buffer(4, Some(&slot_cells), 0);
        encoder.set_output_buffer(5, Some(&projection_results), 0);
        encoder.set_output_buffer(6, Some(&ordered_rows), 0);
        encoder.set_output_buffer(7, Some(&order_keys), 0);
        encoder.set_input_buffer(8, Some(&output), output_layout.dependency_base);
        encoder.set_output_buffer(9, Some(&output), 0);
        encoder.set_output_buffer(10, Some(&output), output_layout.cell_base);
        encoder.set_output_buffer(11, Some(&output), output_layout.arena_base);
        encoder.set_output_buffer(12, Some(&output), output_layout.receipt_base);
        encoder.set_output_buffer(13, Some(&graph_control), 0);
        encoder.set_bytes(14, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(
                output,
                device.clone(),
                output_layout.output_bytes,
                DType::U8,
            ),
            Shape::from(output_layout.output_bytes),
        ))
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Debug)]
struct MetalSegmentedAggregationProgram {
    grouping: Tensor,
    aggregates: Tensor,
    receipts: Tensor,
    arguments: MetalSegmentedAggregationArgs,
    logical_input_cell_words: usize,
    logical_input_arena_bytes: usize,
    logical_grouping_columns: usize,
    aggregate_descriptor_words: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp3 for MetalSegmentedAggregationProgram {
    fn name(&self) -> &'static str {
        "irongraph-metal-segmented-aggregation"
    }

    fn cpu_fwd(
        &self,
        _header: &CpuStorage,
        _header_layout: &Layout,
        _cells: &CpuStorage,
        _cells_layout: &Layout,
        _arena: &CpuStorage,
        _arena_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal segmented aggregation cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        header: &MetalStorage,
        header_layout: &Layout,
        cells: &MetalStorage,
        cells_layout: &Layout,
        arena: &MetalStorage,
        arena_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let (grouping_storage, grouping_layout) = self.grouping.storage_and_layout();
        let Storage::Metal(grouping) = &*grouping_storage else {
            return Err(candle_core::Error::Msg(
                "segmented grouping columns moved to a non-Metal device".to_owned(),
            ));
        };
        let (aggregate_storage, aggregate_layout) = self.aggregates.storage_and_layout();
        let Storage::Metal(aggregates) = &*aggregate_storage else {
            return Err(candle_core::Error::Msg(
                "segmented aggregate descriptors moved to a non-Metal device".to_owned(),
            ));
        };
        let (receipt_storage, receipt_layout) = self.receipts.storage_and_layout();
        let Storage::Metal(receipts) = &*receipt_storage else {
            return Err(candle_core::Error::Msg(
                "segmented receipts moved to a non-Metal device".to_owned(),
            ));
        };

        let args = self.arguments;
        let output_cell_words = (args.output_cell_capacity as usize)
            .checked_mul(METAL_SEGMENTED_AGGREGATION_CELL_WORDS)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal segmented output cell overflow".to_owned())
            })?;
        let output_header_bytes = METAL_SEGMENTED_AGGREGATION_HEADER_WORDS
            .checked_mul(size_of::<u64>())
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal segmented output header overflow".to_owned())
            })?;
        let output_cell_bytes =
            output_cell_words
                .checked_mul(size_of::<u64>())
                .ok_or_else(|| {
                    candle_core::Error::Msg("Metal segmented output cell bytes overflow".to_owned())
                })?;
        let output_arena_bytes = (args.output_arena_capacity as usize).max(1);
        let output_arena_offset = output_header_bytes
            .checked_add(output_cell_bytes)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal segmented output arena offset overflow".to_owned())
            })?;
        let output_bytes = output_arena_offset
            .checked_add(output_arena_bytes)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal segmented output packet overflow".to_owned())
            })?;
        let reduction_state_words = (args.reduction_state_capacity as usize)
            .checked_mul(METAL_SEGMENTED_AGGREGATION_STATE_WORDS)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal segmented reduction scratch overflow".to_owned())
            })?;
        let receipt_words = (args.receipt_record_capacity as usize)
            .checked_mul(METAL_SEGMENTED_AGGREGATION_RECEIPT_WORDS)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal segmented receipt shape overflow".to_owned())
            })?;
        let pair_capacity = (args.maximum_output_groups as usize)
            .checked_mul(args.aggregate_count as usize)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal segmented dispatch overflow".to_owned())
            })?;
        if size_of::<MetalSegmentedAggregationArgs>() != 18 * size_of::<u32>()
            || args.input_cell_count as usize * METAL_SEGMENTED_AGGREGATION_CELL_WORDS
                != self.logical_input_cell_words
            || args.input_arena_bytes as usize != self.logical_input_arena_bytes
            || args.grouping_column_count as usize != self.logical_grouping_columns
            || args.aggregate_count as usize * METAL_SEGMENTED_AGGREGATION_AGGREGATE_WORDS
                != self.aggregate_descriptor_words
            || args.receipt_count != args.aggregate_count.saturating_add(1)
            || args.receipt_record_capacity != args.receipt_count
            || args.row_group_capacity != args.input_row_count
            || args.group_first_capacity != args.maximum_output_groups
            || args.reduction_state_capacity as usize != pair_capacity
            || args.output_cell_capacity != args.maximum_output_cells
            || args.output_arena_capacity != args.maximum_output_arena_bytes
            || (args.flags & !METAL_SEGMENTED_AGGREGATION_FLAG_FLAT_LIST_MIN_MAX) != 0
            || args.reserved != 0
            || pair_capacity == 0
            || header.dtype() != DType::I64
            || cells.dtype() != DType::I64
            || arena.dtype() != DType::U8
            || self.grouping.dtype() != DType::U32
            || self.aggregates.dtype() != DType::U32
            || self.receipts.dtype() != DType::I64
            || !header_layout.is_contiguous()
            || !cells_layout.is_contiguous()
            || !arena_layout.is_contiguous()
            || !grouping_layout.is_contiguous()
            || !aggregate_layout.is_contiguous()
            || !receipt_layout.is_contiguous()
            || header_layout.dims().len() != 1
            || cells_layout.dims().len() != 1
            || arena_layout.dims().len() != 1
            || grouping_layout.dims().len() != 1
            || aggregate_layout.dims().len() != 1
            || receipt_layout.dims().len() != 1
            || header_layout.shape().elem_count() != METAL_SEGMENTED_AGGREGATION_HEADER_WORDS
            || cells_layout.shape().elem_count() != self.logical_input_cell_words.max(1)
            || arena_layout.shape().elem_count() != self.logical_input_arena_bytes.max(1)
            || grouping_layout.shape().elem_count() != self.logical_grouping_columns.max(1)
            || aggregate_layout.shape().elem_count() != self.aggregate_descriptor_words
            || receipt_layout.shape().elem_count() != receipt_words
        {
            return Err(candle_core::Error::Msg(
                "Metal segmented aggregation tensor contract is invalid".to_owned(),
            ));
        }

        let device = header.device();
        let pipelines = metal_sort_pipelines(device)?;
        let output = device
            .new_buffer_builder()
            .with_size_for(output_bytes, DType::U8)
            .with_label("irongraph segmented aggregation output")
            .build()?;
        let control = device
            .new_buffer_builder()
            .with_size_for(METAL_SEGMENTED_AGGREGATION_CONTROL_WORDS, DType::U32)
            .with_label("irongraph segmented aggregation control")
            .build()?;
        let row_group_ids = device
            .new_buffer_builder()
            .with_size_for((args.row_group_capacity as usize).max(1), DType::U32)
            .with_label("irongraph segmented row groups")
            .build()?;
        let group_first_rows = device
            .new_buffer_builder()
            .with_size_for((args.group_first_capacity as usize).max(1), DType::U32)
            .with_label("irongraph segmented first rows")
            .build()?;
        let reduction_states = device
            .new_buffer_builder()
            .with_size_for(reduction_state_words.max(1), DType::I64)
            .with_label("irongraph segmented reduction states")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_input_buffer(
            0,
            Some(header.buffer()),
            header_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(cells.buffer()),
            cells_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(arena.buffer()),
            arena_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            3,
            Some(grouping.buffer()),
            grouping_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            4,
            Some(aggregates.buffer()),
            aggregate_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(
            5,
            Some(receipts.buffer()),
            receipt_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_output_buffer(6, Some(&output), 0);
        encoder.set_output_buffer(7, Some(&output), output_header_bytes);
        encoder.set_output_buffer(8, Some(&output), output_arena_offset);
        encoder.set_output_buffer(9, Some(&control), 0);
        encoder.set_output_buffer(10, Some(&row_group_ids), 0);
        encoder.set_output_buffer(11, Some(&group_first_rows), 0);
        encoder.set_output_buffer(12, Some(&reduction_states), 0);
        encoder.set_bytes(13, &self.arguments);

        encoder.set_compute_pipeline_state(&pipelines.segmented_aggregation_group);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();
        encoder.set_compute_pipeline_state(&pipelines.segmented_aggregation_reduce);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: pair_capacity.div_ceil(METAL_SORT_THREADS),
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();
        encoder.set_compute_pipeline_state(&pipelines.segmented_aggregation_finalize);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), output_bytes, DType::U8),
            Shape::from(output_bytes),
        ))
    }
}

