#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Debug)]
struct MetalCreateNodeIntent {
    payload: Tensor,
    receipts: Tensor,
    temporal_values: Tensor,
    arguments: MetalCreateNodeIntentArgs,
    label_count: usize,
    property_count: usize,
    input_payload_bytes: usize,
    output_payload_capacity: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp3 for MetalCreateNodeIntent {
    fn name(&self) -> &'static str {
        "irongraph-metal-create-node-intent"
    }

    fn cpu_fwd(
        &self,
        _header: &CpuStorage,
        _header_layout: &Layout,
        _labels: &CpuStorage,
        _labels_layout: &Layout,
        _properties: &CpuStorage,
        _properties_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal CREATE intent cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        header: &MetalStorage,
        header_layout: &Layout,
        labels: &MetalStorage,
        labels_layout: &Layout,
        properties: &MetalStorage,
        properties_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let (payload_storage, payload_layout) = self.payload.storage_and_layout();
        let Storage::Metal(payload) = &*payload_storage else {
            return Err(candle_core::Error::Msg(
                "CREATE payload moved to a non-Metal device".to_owned(),
            ));
        };
        let (receipt_storage, receipt_layout) = self.receipts.storage_and_layout();
        let Storage::Metal(receipts) = &*receipt_storage else {
            return Err(candle_core::Error::Msg(
                "CREATE receipts moved to a non-Metal device".to_owned(),
            ));
        };
        let (temporal_storage, temporal_layout) = self.temporal_values.storage_and_layout();
        let Storage::Metal(temporal_values) = &*temporal_storage else {
            return Err(candle_core::Error::Msg(
                "CREATE temporal values moved to a non-Metal device".to_owned(),
            ));
        };

        let label_bytes = self
            .label_count
            .checked_mul(size_of::<u64>())
            .ok_or_else(|| candle_core::Error::Msg("Metal CREATE label shape overflow".into()))?;
        let property_bytes = self
            .property_count
            .checked_mul(METAL_CREATE_NODE_OUTPUT_PROPERTY_WORDS)
            .and_then(|words| words.checked_mul(size_of::<u64>()))
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal CREATE property shape overflow".into())
            })?;
        let header_bytes = METAL_CREATE_NODE_HEADER_WORDS * size_of::<u64>();
        let property_base = header_bytes.checked_add(label_bytes).ok_or_else(|| {
            candle_core::Error::Msg("Metal CREATE property offset overflow".into())
        })?;
        let payload_base = property_base.checked_add(property_bytes).ok_or_else(|| {
            candle_core::Error::Msg("Metal CREATE payload offset overflow".into())
        })?;
        let output_bytes = payload_base
            .checked_add(self.output_payload_capacity.max(1))
            .ok_or_else(|| candle_core::Error::Msg("Metal CREATE output overflow".into()))?;
        let expected_property_words = self
            .property_count
            .checked_mul(METAL_CREATE_NODE_INPUT_PROPERTY_WORDS)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal CREATE property input overflow".into())
            })?;
        let expected_receipt_words = usize::try_from(self.arguments.receipt_record_capacity)
            .ok()
            .and_then(|count| count.checked_mul(METAL_CREATE_NODE_RECEIPT_WORDS))
            .ok_or_else(|| candle_core::Error::Msg("Metal CREATE receipt overflow".into()))?;
        let temporal_value_count = usize::try_from(self.arguments.temporal_value_count)
            .map_err(|_| candle_core::Error::Msg("Metal CREATE temporal count overflow".into()))?;
        let expected_temporal_words = temporal_value_count.checked_mul(8).ok_or_else(|| {
            candle_core::Error::Msg("Metal CREATE temporal shape overflow".into())
        })?;
        if header.dtype() != DType::I64
            || labels.dtype() != DType::I64
            || properties.dtype() != DType::I64
            || self.payload.dtype() != DType::U8
            || self.receipts.dtype() != DType::I64
            || self.temporal_values.dtype() != DType::U32
            || !header_layout.is_contiguous()
            || !labels_layout.is_contiguous()
            || !properties_layout.is_contiguous()
            || !payload_layout.is_contiguous()
            || !receipt_layout.is_contiguous()
            || !temporal_layout.is_contiguous()
            || header_layout.dims().len() != 1
            || labels_layout.dims().len() != 1
            || properties_layout.dims().len() != 1
            || payload_layout.dims().len() != 1
            || receipt_layout.dims().len() != 1
            || temporal_layout.dims().len() != 1
            || header_layout.shape().elem_count() != METAL_CREATE_NODE_HEADER_WORDS
            || labels_layout.shape().elem_count() != self.label_count.max(1)
            || properties_layout.shape().elem_count() != expected_property_words.max(1)
            || payload_layout.shape().elem_count() != self.input_payload_bytes.max(1)
            || receipt_layout.shape().elem_count() != expected_receipt_words
            || temporal_layout.shape().elem_count() != expected_temporal_words.max(8)
            || self.arguments.label_count as usize != self.label_count
            || self.arguments.property_count as usize != self.property_count
            || self.arguments.input_payload_bytes as usize != self.input_payload_bytes
            || self.arguments.output_label_capacity as usize != self.label_count
            || self.arguments.output_property_capacity as usize != self.property_count
            || self.arguments.output_payload_capacity as usize != self.output_payload_capacity
            || self.arguments.receipt_count != self.arguments.receipt_record_capacity
            || self.arguments.receipt_count != self.arguments.expression_count.saturating_add(2)
            || self.arguments.temporal_value_count > self.arguments.expression_count
        {
            return Err(candle_core::Error::Msg(
                "Metal CREATE tensor contract is invalid".to_owned(),
            ));
        }

        let device = header.device();
        let output = device
            .new_buffer_builder()
            .with_size_for(output_bytes, DType::U8)
            .with_label("irongraph CREATE intent output")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&metal_sort_pipelines(device)?.create_node_intent);
        encoder.set_input_buffer(
            0,
            Some(header.buffer()),
            header_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(labels.buffer()),
            labels_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(properties.buffer()),
            properties_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            3,
            Some(payload.buffer()),
            payload_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_output_buffer(
            4,
            Some(receipts.buffer()),
            receipt_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_output_buffer(5, Some(&output), 0);
        encoder.set_output_buffer(6, Some(&output), header_bytes);
        encoder.set_output_buffer(7, Some(&output), property_base);
        encoder.set_output_buffer(8, Some(&output), payload_base);
        encoder.set_bytes(9, &self.arguments);
        encoder.set_input_buffer(
            10,
            Some(temporal_values.buffer()),
            temporal_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), output_bytes, DType::U8),
            Shape::from(output_bytes),
        ))
    }
}

