#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_logical_dispatch_chunks(
    logical_count: u64,
    threads: usize,
) -> candle_core::Result<Vec<MetalRowMutationDispatchChunk>> {
    if logical_count == 0 {
        return Ok(Vec::new());
    }
    let thread_width = u64::try_from(threads).map_err(|_| {
        candle_core::Error::Msg("Metal logical threadgroup width exceeds u64".to_owned())
    })?;
    if thread_width == 0 {
        return Err(candle_core::Error::Msg(
            "Metal logical threadgroup width is zero".to_owned(),
        ));
    }
    let chunk_limit = u64::from(u32::MAX)
        .checked_sub(thread_width.saturating_sub(1))
        .ok_or_else(|| {
            candle_core::Error::Msg(
                "Metal logical threadgroup width exceeds the shader grid".to_owned(),
            )
        })?;
    let mut chunks = Vec::new();
    let mut logical_base = 0_u64;
    while logical_base < logical_count {
        let chunk = (logical_count - logical_base).min(chunk_limit);
        let group_count = usize::try_from(chunk.div_ceil(thread_width)).map_err(|_| {
            candle_core::Error::Msg(
                "Metal logical group count exceeds host address space".to_owned(),
            )
        })?;
        chunks.push(MetalRowMutationDispatchChunk {
            logical_base,
            logical_count: chunk,
            group_count,
        });
        logical_base = logical_base.checked_add(chunk).ok_or_else(|| {
            candle_core::Error::Msg("Metal logical dispatch base overflowed".to_owned())
        })?;
    }
    Ok(chunks)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_row_mutation_dispatch_chunks(
    count: usize,
    threads: usize,
) -> candle_core::Result<Vec<MetalRowMutationDispatchChunk>> {
    let logical_count = u64::try_from(count).map_err(|_| {
        candle_core::Error::Msg("Metal row-mutation dispatch count exceeds u64".to_owned())
    })?;
    metal_logical_dispatch_chunks(logical_count, threads)
}

