#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp2 for MetalRowMatchMergeRelationship {
    fn name(&self) -> &'static str {
        "irongraph-metal-row-match-merge-relationship"
    }

    fn cpu_fwd(
        &self,
        _graph: &CpuStorage,
        _graph_layout: &Layout,
        _program: &CpuStorage,
        _program_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal MATCH/MERGE row mutation cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        graph: &MetalStorage,
        graph_layout: &Layout,
        program: &MetalStorage,
        program_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let args = self.arguments;
        let fail = |message: &str| candle_core::Error::Msg(message.to_owned());
        let as_usize =
            |value: u64, message: &str| usize::try_from(value).map_err(|_| fail(message));
        let graph_words = as_usize(
            args.graph_word_count,
            "Metal MATCH/MERGE graph packet exceeds host address space",
        )?;
        let program_words = as_usize(
            args.program_word_count,
            "Metal MATCH/MERGE program exceeds host address space",
        )?;
        let output_words = as_usize(
            args.output_word_count,
            "Metal MATCH/MERGE output exceeds host address space",
        )?;
        let sources = as_usize(
            args.source_count,
            "Metal MATCH/MERGE source count exceeds host address space",
        )?;
        let nodes = as_usize(
            args.node_count,
            "Metal MATCH/MERGE node count exceeds host address space",
        )?;
        let edges = as_usize(
            args.edge_count,
            "Metal MATCH/MERGE relationship count exceeds host address space",
        )?;
        let pairs = as_usize(
            args.pair_count,
            "Metal MATCH/MERGE pair count exceeds host address space",
        )?;
        let work = as_usize(
            args.maximum_work_rows,
            "Metal MATCH/MERGE work-row capacity exceeds host address space",
        )?;
        let receipts = as_usize(
            args.receipt_count,
            "Metal MATCH/MERGE receipt count exceeds host address space",
        )?;
        let key_bytes = as_usize(
            args.program_key_byte_count,
            "Metal MATCH/MERGE key arena exceeds host address space",
        )?;
        let match_key_offset = as_usize(
            args.program_match_key_offset,
            "Metal MATCH/MERGE MATCH-key offset exceeds host address space",
        )?;
        let match_key_length = as_usize(
            args.program_match_key_length,
            "Metal MATCH/MERGE MATCH-key length exceeds host address space",
        )?;
        let merge_key_offset = as_usize(
            args.program_merge_key_offset,
            "Metal MATCH/MERGE MERGE-key offset exceeds host address space",
        )?;
        let merge_key_length = as_usize(
            args.program_merge_key_length,
            "Metal MATCH/MERGE MERGE-key length exceeds host address space",
        )?;
        let overflow = || fail("Metal MATCH/MERGE tensor contract size overflow");
        let add = |left: usize, right: usize| left.checked_add(right).ok_or_else(overflow);
        let product = |left: usize, right: usize| left.checked_mul(right).ok_or_else(overflow);

        let expected_node_active = 1_usize;
        let expected_node_layer = add(expected_node_active, nodes)?;
        let expected_node_id = add(expected_node_layer, nodes)?;
        let expected_matched_label = add(expected_node_id, nodes)?;
        let expected_merged_label = add(expected_matched_label, nodes)?;
        let expected_matched_value = add(expected_merged_label, nodes)?;
        let expected_matched_validity = add(expected_matched_value, nodes)?;
        let expected_merged_value = add(expected_matched_validity, nodes)?;
        let expected_merged_validity = add(expected_merged_value, nodes)?;
        let expected_edge_active = add(expected_merged_validity, nodes)?;
        let expected_edge_layer = add(expected_edge_active, edges)?;
        let expected_edge_id = add(expected_edge_layer, edges)?;
        let expected_edge_source = add(expected_edge_id, edges)?;
        let expected_edge_target = add(expected_edge_source, edges)?;
        let expected_edge_type = add(expected_edge_target, edges)?;
        let expected_graph_words = add(expected_edge_type, edges)?;

        let expected_map_offset = METAL_ROW_MATCH_MERGE_PROGRAM_HEADER_WORDS;
        let expected_entry_base = add(expected_map_offset, add(sources, 1)?)?;
        let entry_base = as_usize(
            args.program_entry_base,
            "Metal MATCH/MERGE entry base exceeds host address space",
        )?;
        let key_byte_base = as_usize(
            args.program_key_byte_base,
            "Metal MATCH/MERGE key base exceeds host address space",
        )?;
        let obligation_base = as_usize(
            args.program_obligation_base,
            "Metal MATCH/MERGE obligation base exceeds host address space",
        )?;
        let entry_words = key_byte_base.checked_sub(entry_base).ok_or_else(overflow)?;
        let expected_obligation_base = add(key_byte_base, key_bytes)?;
        let expected_program_words = add(
            obligation_base,
            product(receipts, METAL_ROW_MATCH_MERGE_OBLIGATION_WORDS)?,
        )?;
        let match_key_end = add(match_key_offset, match_key_length)?;
        let merge_key_end = add(merge_key_offset, merge_key_length)?;

        let mut output_cursor = METAL_ROW_MATCH_MERGE_OUTPUT_HEADER_WORDS;
        let mut output_take = |count: usize| -> candle_core::Result<usize> {
            let base = output_cursor;
            output_cursor = add(output_cursor, count)?;
            Ok(base)
        };
        let expected_receipt =
            output_take(product(receipts, METAL_ROW_MATCH_MERGE_RECEIPT_WORDS)?)?;
        let expected_pair_active = output_take(pairs)?;
        let expected_work_source = output_take(work)?;
        let expected_matched_id = output_take(work)?;
        let expected_matched_dense = output_take(work)?;
        let expected_merged_id = output_take(work)?;
        let expected_merged_dense = output_take(work)?;
        let expected_merged_created = output_take(work)?;
        let expected_relationship_id = output_take(work)?;
        let expected_relationship_dense = output_take(work)?;
        let expected_relationship_created = output_take(work)?;
        let expected_node_create = output_take(work)?;
        let expected_relationship_create = output_take(work)?;
        let expected_node_dependency = output_take(nodes)?;
        let expected_relationship_dependency = output_take(edges)?;
        let expected_sorted_value = output_take(work)?;
        let expected_sorted_work = output_take(work)?;
        let expected_control = output_take(METAL_ROW_MATCH_MERGE_CONTROL_WORDS)?;

        if graph.dtype() != DType::I64
            || program.dtype() != DType::I64
            || !graph_layout.is_contiguous()
            || !program_layout.is_contiguous()
            || graph_layout.dims().len() != 1
            || program_layout.dims().len() != 1
            || graph_layout.shape().elem_count() != graph_words
            || graph_words != self.graph_storage_words
            || program_layout.shape().elem_count() != program_words
            || graph_words != expected_graph_words
            || program_words != expected_program_words
            || output_words != output_cursor
            || pairs != product(sources, nodes)?
            || args.layers == 0
            || receipts == 0
            || args.relationship_type_present > 1
            || args.graph_node_active_base != expected_node_active as u64
            || args.graph_node_layer_base != expected_node_layer as u64
            || args.graph_node_id_base != expected_node_id as u64
            || args.graph_matched_label_base != expected_matched_label as u64
            || args.graph_merged_label_base != expected_merged_label as u64
            || args.graph_matched_value_base != expected_matched_value as u64
            || args.graph_matched_validity_base != expected_matched_validity as u64
            || args.graph_merged_value_base != expected_merged_value as u64
            || args.graph_merged_validity_base != expected_merged_validity as u64
            || args.graph_edge_active_base != expected_edge_active as u64
            || args.graph_edge_layer_base != expected_edge_layer as u64
            || args.graph_edge_id_base != expected_edge_id as u64
            || args.graph_edge_source_base != expected_edge_source as u64
            || args.graph_edge_target_base != expected_edge_target as u64
            || args.graph_edge_type_base != expected_edge_type as u64
            || args.program_map_offset_base != expected_map_offset as u64
            || entry_base != expected_entry_base
            || entry_words % METAL_ROW_MATCH_MERGE_ENTRY_WORDS != 0
            || obligation_base != expected_obligation_base
            || match_key_length == 0
            || merge_key_length == 0
            || match_key_end > key_bytes
            || merge_key_end > key_bytes
            || args.output_receipt_base != expected_receipt as u64
            || args.output_pair_active_base != expected_pair_active as u64
            || args.output_work_source_base != expected_work_source as u64
            || args.output_matched_id_base != expected_matched_id as u64
            || args.output_matched_dense_base != expected_matched_dense as u64
            || args.output_merged_id_base != expected_merged_id as u64
            || args.output_merged_dense_base != expected_merged_dense as u64
            || args.output_merged_created_base != expected_merged_created as u64
            || args.output_relationship_id_base != expected_relationship_id as u64
            || args.output_relationship_dense_base != expected_relationship_dense as u64
            || args.output_relationship_created_base != expected_relationship_created as u64
            || args.output_node_create_base != expected_node_create as u64
            || args.output_relationship_create_base != expected_relationship_create as u64
            || args.output_node_dependency_base != expected_node_dependency as u64
            || args.output_relationship_dependency_base != expected_relationship_dependency as u64
            || args.output_sorted_value_base != expected_sorted_value as u64
            || args.output_sorted_work_base != expected_sorted_work as u64
            || args.output_control_base != expected_control as u64
        {
            return Err(fail("Metal MATCH/MERGE tensor contract is invalid"));
        }

        let device = graph.device();
        let output = device
            .new_buffer_builder()
            .with_size_for(output_words, DType::I64)
            .with_label("irongraph MATCH/MERGE row lineage, intents, and relation")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        let pipelines = metal_sort_pipelines(device)?;
        let dispatch = |pipeline: &candle_metal_kernels::metal::ComputePipeline,
                        count: usize,
                        threads: usize|
         -> candle_core::Result<()> {
            if count == 0 {
                return Ok(());
            }
            for chunk in metal_row_mutation_dispatch_chunks(count, threads)? {
                encoder.set_compute_pipeline_state(pipeline);
                encoder.set_input_buffer(
                    0,
                    Some(graph.buffer()),
                    graph_layout.start_offset() * DType::I64.size_in_bytes(),
                );
                encoder.set_input_buffer(
                    1,
                    Some(program.buffer()),
                    program_layout.start_offset() * DType::I64.size_in_bytes(),
                );
                encoder.set_output_buffer(2, Some(&output), 0);
                encoder.set_bytes(3, &args);
                encoder.set_bytes(
                    4,
                    &MetalRowMutationDispatchArgs {
                        logical_base: chunk.logical_base,
                    },
                );
                encoder.dispatch_thread_groups(
                    objc2_metal::MTLSize {
                        width: chunk.group_count,
                        height: 1,
                        depth: 1,
                    },
                    objc2_metal::MTLSize {
                        width: threads,
                        height: 1,
                        depth: 1,
                    },
                );
            }
            encoder.insert_memory_barrier();
            Ok(())
        };
        const THREADS: usize = 256;
        dispatch(&pipelines.row_match_merge_initialize, output_words, THREADS)?;
        dispatch(&pipelines.row_match_merge_validate_output, 1, 1)?;
        dispatch(&pipelines.row_match_merge_validate_graph, 1, 1)?;
        dispatch(&pipelines.row_match_merge_validate_program, 1, 1)?;
        dispatch(&pipelines.row_match_merge_validate_semantics, 1, 1)?;
        dispatch(
            &pipelines.row_match_merge_dependencies,
            nodes.max(edges),
            THREADS,
        )?;
        dispatch(&pipelines.row_match_merge_match, pairs, THREADS)?;
        dispatch(&pipelines.row_match_merge_compact, 1, 1)?;
        dispatch(&pipelines.row_match_merge_node_merge, 1, 1)?;
        dispatch(&pipelines.row_match_merge_relationship_merge, 1, 1)?;
        dispatch(&pipelines.row_match_merge_sort, work, THREADS)?;
        dispatch(&pipelines.row_match_merge_publish, 1, 1)?;
        Ok((
            MetalStorage::new(output, device.clone(), output_words, DType::I64),
            Shape::from(output_words),
        ))
    }
}

