#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp3 for MetalDelete {
    fn name(&self) -> &'static str {
        "irongraph-metal-delete"
    }

    fn cpu_fwd(
        &self,
        _graph: &CpuStorage,
        _graph_layout: &Layout,
        _program: &CpuStorage,
        _program_layout: &Layout,
        _variable_path: &CpuStorage,
        _variable_path_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal DELETE program cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        graph: &MetalStorage,
        graph_layout: &Layout,
        program: &MetalStorage,
        program_layout: &Layout,
        variable_path: &MetalStorage,
        variable_path_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let args = self.arguments;
        let fail = |message: &str| candle_core::Error::Msg(message.to_owned());
        let graph_words = usize::try_from(args.graph_word_count)
            .map_err(|_| fail("Metal DELETE graph packet exceeds host address space"))?;
        let program_words = usize::try_from(args.program_word_count)
            .map_err(|_| fail("Metal DELETE program packet exceeds host address space"))?;
        let output_words = usize::try_from(args.output_word_count)
            .map_err(|_| fail("Metal DELETE output packet exceeds host address space"))?;
        let node_count = usize::try_from(args.node_count)
            .map_err(|_| fail("Metal DELETE node count exceeds host address space"))?;
        let edge_count = usize::try_from(args.edge_count)
            .map_err(|_| fail("Metal DELETE edge count exceeds host address space"))?;
        let labels = usize::try_from(args.label_lane_count)
            .map_err(|_| fail("Metal DELETE label count exceeds host address space"))?;
        let node_properties = usize::try_from(args.node_property_count)
            .map_err(|_| fail("Metal DELETE node-property count exceeds host address space"))?;
        let edge_properties = usize::try_from(args.edge_property_count)
            .map_err(|_| fail("Metal DELETE edge-property count exceeds host address space"))?;
        let outgoing_count = usize::try_from(args.outgoing_count)
            .map_err(|_| fail("Metal DELETE outgoing adjacency exceeds host address space"))?;
        let incoming_count = usize::try_from(args.incoming_count)
            .map_err(|_| fail("Metal DELETE incoming adjacency exceeds host address space"))?;
        let filters = usize::try_from(args.filter_count)
            .map_err(|_| fail("Metal DELETE filter count exceeds host address space"))?;
        let commands = usize::try_from(args.command_count)
            .map_err(|_| fail("Metal DELETE command count exceeds host address space"))?;
        let stages = usize::try_from(args.stage_count)
            .map_err(|_| fail("Metal DELETE stage count exceeds host address space"))?;
        let receipts = usize::try_from(args.receipt_count)
            .map_err(|_| fail("Metal DELETE receipt count exceeds host address space"))?;
        let selector_capacity = usize::try_from(args.selector_capacity)
            .map_err(|_| fail("Metal DELETE selector capacity exceeds host address space"))?;
        let intent_capacity = usize::try_from(args.intent_capacity)
            .map_err(|_| fail("Metal DELETE intent capacity exceeds host address space"))?;
        let dependency_capacity = usize::try_from(args.dependency_capacity)
            .map_err(|_| fail("Metal DELETE dependency capacity exceeds host address space"))?;
        let final_capacity = usize::try_from(args.final_capacity)
            .map_err(|_| fail("Metal DELETE final capacity exceeds host address space"))?;
        let variable_path_words = usize::try_from(args.variable_path_word_count)
            .map_err(|_| fail("Metal DELETE variable-path frame exceeds host address space"))?;
        let overflow = || fail("Metal DELETE tensor contract size overflow");
        let add = |left: usize, right: usize| left.checked_add(right).ok_or_else(overflow);
        let product = |left: usize, right: usize| left.checked_mul(right).ok_or_else(overflow);

        let mut graph_cursor = 0_usize;
        let mut graph_take = |count: usize| -> candle_core::Result<usize> {
            let base = graph_cursor;
            graph_cursor = add(graph_cursor, count)?;
            Ok(base)
        };
        let expected_node_active = graph_take(node_count)?;
        let expected_node_layer = graph_take(node_count)?;
        let expected_node_id = graph_take(node_count)?;
        let expected_label = graph_take(product(labels, node_count)?)?;
        let expected_edge_active = graph_take(edge_count)?;
        let expected_edge_layer = graph_take(edge_count)?;
        let expected_edge_type = graph_take(edge_count)?;
        let expected_edge_id = graph_take(edge_count)?;
        let expected_outgoing_offset = graph_take(add(node_count, 1)?)?;
        let expected_outgoing_neighbor = graph_take(outgoing_count)?;
        let expected_outgoing_edge = graph_take(outgoing_count)?;
        let expected_incoming_offset = graph_take(add(node_count, 1)?)?;
        let expected_incoming_neighbor = graph_take(incoming_count)?;
        let expected_incoming_edge = graph_take(incoming_count)?;
        let expected_node_property_value = graph_take(product(node_properties, node_count)?)?;
        let expected_node_property_validity = graph_take(product(node_properties, node_count)?)?;
        let expected_edge_property_value = graph_take(product(edge_properties, edge_count)?)?;
        let expected_edge_property_validity = graph_take(product(edge_properties, edge_count)?)?;

        let mut output_cursor = METAL_DELETE_OUTPUT_HEADER_WORDS;
        let mut output_take = |count: usize| -> candle_core::Result<usize> {
            let base = output_cursor;
            output_cursor = add(output_cursor, count)?;
            Ok(base)
        };
        let expected_receipt = output_take(product(receipts, METAL_DELETE_RECEIPT_WORDS)?)?;
        let expected_command_attempt = output_take(commands)?;
        let expected_intent = output_take(product(intent_capacity, METAL_DELETE_INTENT_WORDS)?)?;
        let expected_dependency =
            output_take(product(dependency_capacity, METAL_DELETE_DEPENDENCY_WORDS)?)?;
        let expected_final_value = output_take(final_capacity)?;
        let expected_final_validity = output_take(final_capacity)?;
        let expected_start_row =
            output_take(product(selector_capacity, METAL_DELETE_NODE_ROW_COLUMNS)?)?;
        let expected_relationship_row = output_take(product(
            selector_capacity,
            METAL_DELETE_RELATIONSHIP_ROW_COLUMNS,
        )?)?;
        let expected_end_row = add(expected_start_row, selector_capacity)?;
        let expected_position = output_take(selector_capacity)?;
        let expected_intent_dense = output_take(intent_capacity)?;
        let expected_intent_processed = output_take(intent_capacity)?;
        let expected_control = output_take(METAL_DELETE_CONTROL_WORDS)?;

        let maximum = u64::from(u32::MAX);
        if graph.dtype() != DType::I64
            || program.dtype() != DType::I64
            || variable_path.dtype() != DType::I64
            || !graph_layout.is_contiguous()
            || !program_layout.is_contiguous()
            || !variable_path_layout.is_contiguous()
            || graph_layout.dims().len() != 1
            || program_layout.dims().len() != 1
            || variable_path_layout.dims().len() != 1
            || graph_layout.shape().elem_count() != graph_words
            || graph_words != self.graph_storage_words
            || program_layout.shape().elem_count() != program_words
            || program_words < METAL_DELETE_PROGRAM_HEADER_WORDS
            || variable_path_layout.shape().elem_count() != variable_path_words
            || filters != self.filter_count
            || stages != self.stage_count
            || commands == 0
            || selector_capacity == 0
            || graph_cursor != graph_words
            || output_cursor != output_words
            || args.node_active_base != expected_node_active as u64
            || args.node_layer_base != expected_node_layer as u64
            || args.node_id_base != expected_node_id as u64
            || args.label_base != expected_label as u64
            || args.edge_active_base != expected_edge_active as u64
            || args.edge_layer_base != expected_edge_layer as u64
            || args.edge_type_base != expected_edge_type as u64
            || args.edge_id_base != expected_edge_id as u64
            || args.outgoing_offset_base != expected_outgoing_offset as u64
            || args.outgoing_neighbor_base != expected_outgoing_neighbor as u64
            || args.outgoing_edge_base != expected_outgoing_edge as u64
            || args.incoming_offset_base != expected_incoming_offset as u64
            || args.incoming_neighbor_base != expected_incoming_neighbor as u64
            || args.incoming_edge_base != expected_incoming_edge as u64
            || args.node_property_value_base != expected_node_property_value as u64
            || args.node_property_validity_base != expected_node_property_validity as u64
            || args.edge_property_value_base != expected_edge_property_value as u64
            || args.edge_property_validity_base != expected_edge_property_validity as u64
            || args.receipt_base != expected_receipt as u64
            || args.command_attempt_base != expected_command_attempt as u64
            || args.intent_base != expected_intent as u64
            || args.dependency_base != expected_dependency as u64
            || args.final_value_base != expected_final_value as u64
            || args.final_validity_base != expected_final_validity as u64
            || args.start_row_base != expected_start_row as u64
            || args.relationship_row_base != expected_relationship_row as u64
            || args.end_row_base != expected_end_row as u64
            || args.position_base != expected_position as u64
            || args.intent_dense_base != expected_intent_dense as u64
            || args.intent_processed_base != expected_intent_processed as u64
            || args.control_base != expected_control as u64
            || args.output_word_count > maximum
            || args.node_count > maximum
            || args.edge_count > maximum
            || args.label_lane_count > maximum
            || args.node_property_count > maximum
            || args.edge_property_count > maximum
            || args.outgoing_count > maximum
            || args.incoming_count > maximum
            || args.filter_count > maximum
            || args.command_count > maximum
            || args.stage_count > maximum
            || args.receipt_count > maximum
            || args.selector_capacity > maximum
            || args.intent_capacity > maximum
            || args.dependency_capacity > maximum
            || args.final_capacity > maximum
            || args.variable_path_mode > 1
            || args.variable_path_word_count > maximum
            || (args.variable_path_mode == 0
                && (variable_path_words != 1
                    || args.variable_path_abi != 0
                    || args.variable_path_output_header_words != 0
                    || args.variable_path_publication_count_word != 0
                    || args.variable_path_publication_capacity != 0
                    || args.variable_path_receipt_base != 0
                    || args.variable_path_receipt_count != 0
                    || args.variable_path_receipt_words != 0
                    || args.variable_path_descriptor_base != 0
                    || args.variable_path_descriptor_stride != 0
                    || args.variable_path_edge_base != 0
                    || args.variable_path_edge_stride != 0
                    || args.variable_path_node_base != 0
                    || args.variable_path_node_stride != 0
                    || args.variable_path_segment_end_base != 0
                    || args.variable_path_segment_stride != 0
                    || args.variable_path_metadata_base != 0
                    || args.variable_path_metadata_stride != 0
                    || args.variable_path_final_relation_base != 0
                    || args.variable_path_final_relation_capacity != 0
                    || args.variable_path_fingerprint_0 != 0
                    || args.variable_path_fingerprint_1 != 0
                    || args.variable_path_fingerprint_2 != 0
                    || args.variable_path_fingerprint_3 != 0))
            || (args.variable_path_mode == 1
                && (variable_path_words < METAL_VARIABLE_PATH_OUTPUT_HEADER_WORDS
                    || args.variable_path_abi != METAL_VARIABLE_PATH_ABI_WORD
                    || args.variable_path_output_header_words
                        != METAL_VARIABLE_PATH_OUTPUT_HEADER_WORDS as u64
                    || args.variable_path_publication_count_word != 13
                    || args.variable_path_publication_capacity != args.selector_capacity
                    || args.variable_path_receipt_base
                        != METAL_VARIABLE_PATH_OUTPUT_HEADER_WORDS as u64
                    || args.variable_path_receipt_words
                        != METAL_VARIABLE_PATH_RECEIPT_WORDS as u64
                    || args.variable_path_descriptor_stride != 3
                    || args.variable_path_edge_stride != args.edge_count
                    || args.variable_path_node_stride != args.edge_count + 1
                    || args.variable_path_segment_stride != 1
                    || args.variable_path_metadata_stride != 3
                    || args.variable_path_final_relation_base != args.variable_path_word_count
                    || args.variable_path_final_relation_capacity != 0))
        {
            return Err(fail("Metal DELETE tensor contract is invalid"));
        }

        let device = graph.device();
        let output = device
            .new_buffer_builder()
            .with_size_for(output_words, DType::I64)
            .with_label("irongraph DELETE relation, intents, and receipts")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        let pipelines = metal_sort_pipelines(device)?;
        let dispatch = |pipeline: &candle_metal_kernels::metal::ComputePipeline,
                        step: Option<&MetalDeleteStepArgs>| {
            encoder.set_compute_pipeline_state(pipeline);
            encoder.set_input_buffer(
                0,
                Some(graph.buffer()),
                graph_layout.start_offset() * DType::I64.size_in_bytes(),
            );
            encoder.set_input_buffer(
                1,
                Some(program.buffer()),
                program_layout.start_offset() * DType::I64.size_in_bytes(),
            );
            encoder.set_output_buffer(2, Some(&output), 0);
            encoder.set_bytes(3, &args);
            if let Some(step) = step {
                encoder.set_bytes(4, step);
            }
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
            );
        };
        let dispatch_variable_path = |pipeline: &candle_metal_kernels::metal::ComputePipeline| {
            encoder.set_compute_pipeline_state(pipeline);
            encoder.set_input_buffer(
                0,
                Some(graph.buffer()),
                graph_layout.start_offset() * DType::I64.size_in_bytes(),
            );
            encoder.set_input_buffer(
                1,
                Some(program.buffer()),
                program_layout.start_offset() * DType::I64.size_in_bytes(),
            );
            encoder.set_output_buffer(2, Some(&output), 0);
            encoder.set_bytes(3, &args);
            encoder.set_input_buffer(
                4,
                Some(variable_path.buffer()),
                variable_path_layout.start_offset() * DType::I64.size_in_bytes(),
            );
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
            );
        };
        dispatch(&pipelines.delete_initialize, None);
        dispatch(&pipelines.delete_validate_program_header, None);
        dispatch(&pipelines.delete_validate_program_filters, None);
        dispatch(&pipelines.delete_validate_program_commands, None);
        dispatch(&pipelines.delete_validate_program_stages, None);
        dispatch(&pipelines.delete_validate_nodes, None);
        dispatch(&pipelines.delete_validate_edges, None);
        dispatch(&pipelines.delete_validate_outgoing, None);
        dispatch(&pipelines.delete_validate_incoming, None);
        dispatch(&pipelines.delete_validate_properties, None);
        if args.variable_path_mode == 1 {
            dispatch_variable_path(&pipelines.delete_variable_path_selection);
        } else {
            dispatch(&pipelines.delete_select_scan, None);
            dispatch(&pipelines.delete_select_outgoing, None);
            dispatch(&pipelines.delete_select_incoming, None);
            dispatch(&pipelines.delete_selection_publish, None);
        }
        for index in 0..filters {
            let step = MetalDeleteStepArgs {
                index: index as u64,
            };
            dispatch(&pipelines.delete_selection_filter, Some(&step));
        }
        if args.variable_path_mode == 1 {
            dispatch_variable_path(&pipelines.delete_variable_path_read_dependencies);
        } else {
            dispatch(&pipelines.delete_read_dependencies, None);
        }
        dispatch(&pipelines.delete_explicit_intents, None);
        dispatch(&pipelines.delete_connectivity, None);
        dispatch(&pipelines.delete_detach_incident, None);
        dispatch(&pipelines.delete_prepare_continuation, None);
        for index in 0..stages {
            let step = MetalDeleteStepArgs {
                index: index as u64,
            };
            dispatch(&pipelines.delete_continuation_stage, Some(&step));
        }
        dispatch(&pipelines.delete_final_relation, None);
        dispatch(&pipelines.delete_publish, None);
        Ok((
            MetalStorage::new(output, device.clone(), output_words, DType::I64),
            Shape::from(output_words),
        ))
    }
}

