#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp3 for MetalMutationContinuation {
    fn name(&self) -> &'static str {
        "irongraph-metal-mutation-continuation"
    }

    fn cpu_fwd(
        &self,
        _inputs: &CpuStorage,
        _inputs_layout: &Layout,
        _mutation: &CpuStorage,
        _mutation_layout: &Layout,
        _program: &CpuStorage,
        _program_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal mutation continuation cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        inputs: &MetalStorage,
        inputs_layout: &Layout,
        mutation: &MetalStorage,
        mutation_layout: &Layout,
        program: &MetalStorage,
        program_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let args = self.arguments;
        let logical_input_words = usize::try_from(args.input_word_count).map_err(|_| {
            candle_core::Error::Msg(
                "Metal mutation continuation input exceeds host address space".into(),
            )
        })?;
        let mutation_words = usize::try_from(args.mutation_word_count).map_err(|_| {
            candle_core::Error::Msg(
                "Metal mutation continuation intent packet exceeds host address space".into(),
            )
        })?;
        let program_words = usize::try_from(args.program_word_count).map_err(|_| {
            candle_core::Error::Msg(
                "Metal mutation continuation program exceeds host address space".into(),
            )
        })?;
        let output_words = usize::try_from(args.output_word_count).map_err(|_| {
            candle_core::Error::Msg(
                "Metal mutation continuation output exceeds host address space".into(),
            )
        })?;
        let row_count = args.row_count as usize;
        let stage_count = args.stage_count as usize;
        let receipt_count = args.receipt_count as usize;
        let output_capacity = args.output_capacity as usize;
        let dependency_count = (args.dependency_node_count as usize)
            .checked_add(args.dependency_relationship_count as usize)
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal mutation continuation read-set overflow".into())
            })?;
        let dependency_capacity = args.dependency_capacity as usize;
        let expected_input_words = row_count
            .checked_mul(METAL_MUTATION_CONTINUATION_INPUT_FIELDS)
            .and_then(|words| words.checked_add(dependency_count))
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal mutation continuation input overflow".into())
            })?;
        let expected_program_words = stage_count
            .checked_mul(METAL_MUTATION_CONTINUATION_STAGE_WORDS)
            .and_then(|words| {
                receipt_count
                    .checked_mul(METAL_MUTATION_CONTINUATION_RECEIPT_DESCRIPTOR_WORDS)
                    .and_then(|receipts| words.checked_add(receipts))
            })
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal mutation continuation program overflow".into())
            })?;
        let expected_output_words = METAL_MUTATION_CONTINUATION_HEADER_WORDS
            .checked_add(
                receipt_count
                    .checked_mul(METAL_MUTATION_CONTINUATION_RECEIPT_WORDS)
                    .ok_or_else(|| {
                        candle_core::Error::Msg(
                            "Metal mutation continuation receipt output overflow".into(),
                        )
                    })?,
            )
            .and_then(|words| {
                dependency_capacity
                    .checked_mul(METAL_MUTATION_CONTINUATION_DEPENDENCY_WORDS)
                    .and_then(|dependencies| words.checked_add(dependencies))
            })
            .and_then(|words| {
                output_capacity
                    .checked_mul(2)
                    .and_then(|values| words.checked_add(values))
            })
            .and_then(|words| {
                row_count
                    .checked_mul(3)
                    .and_then(|scratch| words.checked_add(scratch))
            })
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal mutation continuation output overflow".into())
            })?;
        if inputs.dtype() != DType::I64
            || mutation.dtype() != DType::I64
            || program.dtype() != DType::I64
            || !inputs_layout.is_contiguous()
            || !mutation_layout.is_contiguous()
            || !program_layout.is_contiguous()
            || inputs_layout.dims().len() != 1
            || mutation_layout.dims().len() != 1
            || program_layout.dims().len() != 1
            || inputs_layout.shape().elem_count() != self.input_storage_words
            || self.input_storage_words != logical_input_words.max(1)
            || mutation_layout.shape().elem_count() != mutation_words
            || program_layout.shape().elem_count() != program_words
            || logical_input_words != expected_input_words
            || program_words != expected_program_words
            || output_words != expected_output_words
            || receipt_count != stage_count.saturating_add(3)
            || dependency_count > dependency_capacity
            || !(METAL_MUTATION_CONTINUATION_OUTPUT_ENTITY
                ..=METAL_MUTATION_CONTINUATION_OUTPUT_COMPUTED)
                .contains(&args.output_kind)
            || args.value_source > METAL_MUTATION_CONTINUATION_SOURCE_PROPERTY_COUNT
            || args.property_name > u16::MAX as u32
            || (args.output_kind == METAL_MUTATION_CONTINUATION_OUTPUT_ENTITY
                && args.value_source != METAL_MUTATION_CONTINUATION_SOURCE_NONE)
            || (args.output_kind != METAL_MUTATION_CONTINUATION_OUTPUT_ENTITY
                && args.output_kind != METAL_MUTATION_CONTINUATION_OUTPUT_COMPUTED
                && args.value_source == METAL_MUTATION_CONTINUATION_SOURCE_NONE)
            || (args.output_kind == METAL_MUTATION_CONTINUATION_OUTPUT_COMPUTED
                && args.value_source != METAL_MUTATION_CONTINUATION_SOURCE_NONE)
            || !(MetalMutationPacketKind::Static as u32..=MetalMutationPacketKind::Typed as u32)
                .contains(&args.mutation_kind)
        {
            return Err(candle_core::Error::Msg(
                "Metal mutation continuation tensor contract is invalid".to_owned(),
            ));
        }
        let device = inputs.device();
        let output = device
            .new_buffer_builder()
            .with_size_for(output_words, DType::I64)
            .with_label("irongraph mutation continuation relation and receipts")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&metal_sort_pipelines(device)?.mutation_continuation);
        encoder.set_input_buffer(
            0,
            Some(inputs.buffer()),
            inputs_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(mutation.buffer()),
            mutation_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(program.buffer()),
            program_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_output_buffer(3, Some(&output), 0);
        encoder.set_bytes(4, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), output_words, DType::I64),
            Shape::from(output_words),
        ))
    }
}

