#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[allow(clippy::too_many_arguments)]
fn encode_metal_variable_path_accept(
    encoder: &ComputeCommandEncoder,
    pipelines: &MetalSortPipelines,
    source: &MetalBuffer,
    target_masks: &MetalBuffer,
    target_masks_offset: usize,
    packet: &MetalBuffer,
    packet_offset: usize,
    accepted: &MetalBuffer,
    counts: &MetalBuffer,
    offsets: &MetalBuffer,
    control: &MetalBuffer,
    args: &MetalVariablePathArgs,
    step: &MetalVariablePathStepArgs,
    groups: usize,
) {
    encoder.set_compute_pipeline_state(&pipelines.variable_path_accept_count);
    encoder.set_input_buffer(0, Some(source), 0);
    encoder.set_input_buffer(1, Some(target_masks), target_masks_offset);
    encoder.set_input_buffer(2, Some(packet), packet_offset);
    encoder.set_output_buffer(3, Some(counts), 0);
    encoder.set_output_buffer(4, Some(control), 0);
    encoder.set_bytes(5, args);
    encoder.set_bytes(6, step);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: groups,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: METAL_SORT_THREADS,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();

    encoder.set_compute_pipeline_state(&pipelines.variable_path_accept_prefix);
    encoder.set_input_buffer(0, Some(counts), 0);
    encoder.set_output_buffer(1, Some(offsets), 0);
    encoder.set_output_buffer(2, Some(control), 0);
    encoder.set_bytes(3, args);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();

    encoder.set_compute_pipeline_state(&pipelines.variable_path_accept_scatter);
    encoder.set_input_buffer(0, Some(source), 0);
    encoder.set_output_buffer(1, Some(accepted), 0);
    encoder.set_input_buffer(2, Some(counts), 0);
    encoder.set_input_buffer(3, Some(offsets), 0);
    encoder.set_input_buffer(4, Some(control), 0);
    encoder.set_bytes(5, args);
    encoder.set_bytes(6, step);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: groups,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: METAL_SORT_THREADS,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[allow(clippy::too_many_lines)]
fn encode_metal_variable_path(
    encoder: &ComputeCommandEncoder,
    pipelines: &MetalSortPipelines,
    inputs: &MetalVariablePathEncodingInputs<'_>,
    buffers: &MetalVariablePathEncodingBuffers<'_>,
    args: &MetalVariablePathArgs,
    segment_bounds: &[(u32, u32)],
) {
    let groups = usize::try_from(args.frontier_capacity)
        .unwrap_or(usize::MAX)
        .div_ceil(METAL_SORT_THREADS)
        .max(1);
    encoder.set_compute_pipeline_state(&pipelines.variable_path_initialize);
    encoder.set_input_buffer(0, Some(inputs.input_rows), inputs.input_rows_offset);
    encoder.set_input_buffer(1, Some(inputs.packet), inputs.packet_offset);
    encoder.set_input_buffer(2, Some(inputs.start_mask), inputs.start_mask_offset);
    encoder.set_input_buffer(
        3,
        Some(inputs.multiplicity_masks),
        inputs.multiplicity_masks_offset,
    );
    encoder.set_input_buffer(4, Some(inputs.terminal_mask), inputs.terminal_mask_offset);
    encoder.set_output_buffer(5, Some(buffers.frontier_a), 0);
    encoder.set_output_buffer(6, Some(buffers.terminal_rows), 0);
    encoder.set_output_buffer(7, Some(buffers.parent_table), 0);
    encoder.set_output_buffer(8, Some(buffers.control), 0);
    encoder.set_bytes(9, args);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();

    for (segment, (minimum, maximum)) in segment_bounds.iter().copied().enumerate() {
        let mut step = MetalVariablePathStepArgs {
            segment: segment as u32,
            depth: 0,
        };
        encoder.set_compute_pipeline_state(&pipelines.variable_path_segment_begin);
        encoder.set_input_buffer(0, Some(inputs.packet), inputs.packet_offset);
        encoder.set_input_buffer(1, Some(buffers.control), 0);
        encoder.set_bytes(2, args);
        encoder.set_bytes(3, &step);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        if minimum == 0 && minimum <= maximum {
            encode_metal_variable_path_accept(
                encoder,
                pipelines,
                buffers.frontier_a,
                inputs.target_masks,
                inputs.target_masks_offset,
                inputs.packet,
                inputs.packet_offset,
                buffers.accepted,
                buffers.counts,
                buffers.offsets,
                buffers.control,
                args,
                &step,
                groups,
            );
        }

        let mut source_is_a = true;
        if minimum <= maximum {
            for depth in 1..=maximum {
                step.depth = depth;
                let (source, destination) = if source_is_a {
                    (buffers.frontier_a, buffers.frontier_b)
                } else {
                    (buffers.frontier_b, buffers.frontier_a)
                };
                encoder.set_compute_pipeline_state(&pipelines.variable_path_expand_count);
                encoder.set_input_buffer(0, Some(inputs.packet), inputs.packet_offset);
                encoder.set_input_buffer(
                    1,
                    Some(inputs.outgoing_offsets),
                    inputs.outgoing_offsets_offset,
                );
                encoder.set_input_buffer(
                    2,
                    Some(inputs.outgoing_neighbors),
                    inputs.outgoing_neighbors_offset,
                );
                encoder.set_input_buffer(
                    3,
                    Some(inputs.outgoing_edges),
                    inputs.outgoing_edges_offset,
                );
                encoder.set_input_buffer(
                    4,
                    Some(inputs.incoming_offsets),
                    inputs.incoming_offsets_offset,
                );
                encoder.set_input_buffer(
                    5,
                    Some(inputs.incoming_neighbors),
                    inputs.incoming_neighbors_offset,
                );
                encoder.set_input_buffer(
                    6,
                    Some(inputs.incoming_edges),
                    inputs.incoming_edges_offset,
                );
                encoder.set_input_buffer(7, Some(inputs.node_active), inputs.node_active_offset);
                encoder.set_input_buffer(8, Some(inputs.node_layers), inputs.node_layers_offset);
                encoder.set_input_buffer(9, Some(inputs.edge_active), inputs.edge_active_offset);
                encoder.set_input_buffer(10, Some(inputs.edge_layers), inputs.edge_layers_offset);
                encoder.set_input_buffer(11, Some(inputs.edge_types), inputs.edge_types_offset);
                encoder.set_input_buffer(
                    12,
                    Some(inputs.relationship_masks),
                    inputs.relationship_masks_offset,
                );
                encoder.set_input_buffer(13, Some(source), 0);
                encoder.set_output_buffer(14, Some(buffers.counts), 0);
                encoder.set_output_buffer(15, Some(buffers.control), 0);
                encoder.set_input_buffer(
                    16,
                    Some(inputs.outgoing_overlay),
                    inputs.outgoing_overlay_offset,
                );
                encoder.set_input_buffer(
                    17,
                    Some(inputs.incoming_overlay),
                    inputs.incoming_overlay_offset,
                );
                encoder.set_bytes(18, args);
                encoder.set_bytes(19, &step);
                encoder.dispatch_thread_groups(
                    objc2_metal::MTLSize {
                        width: groups,
                        height: 1,
                        depth: 1,
                    },
                    objc2_metal::MTLSize {
                        width: METAL_SORT_THREADS,
                        height: 1,
                        depth: 1,
                    },
                );
                encoder.insert_memory_barrier();

                encoder.set_compute_pipeline_state(&pipelines.variable_path_prefix);
                encoder.set_input_buffer(0, Some(buffers.counts), 0);
                encoder.set_output_buffer(1, Some(buffers.offsets), 0);
                encoder.set_output_buffer(2, Some(buffers.control), 0);
                encoder.set_bytes(3, args);
                encoder.dispatch_thread_groups(
                    objc2_metal::MTLSize {
                        width: 1,
                        height: 1,
                        depth: 1,
                    },
                    objc2_metal::MTLSize {
                        width: 1,
                        height: 1,
                        depth: 1,
                    },
                );
                encoder.insert_memory_barrier();

                encoder.set_compute_pipeline_state(&pipelines.variable_path_scatter);
                encoder.set_input_buffer(0, Some(inputs.packet), inputs.packet_offset);
                encoder.set_input_buffer(
                    1,
                    Some(inputs.outgoing_offsets),
                    inputs.outgoing_offsets_offset,
                );
                encoder.set_input_buffer(
                    2,
                    Some(inputs.outgoing_neighbors),
                    inputs.outgoing_neighbors_offset,
                );
                encoder.set_input_buffer(
                    3,
                    Some(inputs.outgoing_edges),
                    inputs.outgoing_edges_offset,
                );
                encoder.set_input_buffer(
                    4,
                    Some(inputs.incoming_offsets),
                    inputs.incoming_offsets_offset,
                );
                encoder.set_input_buffer(
                    5,
                    Some(inputs.incoming_neighbors),
                    inputs.incoming_neighbors_offset,
                );
                encoder.set_input_buffer(
                    6,
                    Some(inputs.incoming_edges),
                    inputs.incoming_edges_offset,
                );
                encoder.set_input_buffer(7, Some(inputs.node_active), inputs.node_active_offset);
                encoder.set_input_buffer(8, Some(inputs.node_layers), inputs.node_layers_offset);
                encoder.set_input_buffer(9, Some(inputs.edge_active), inputs.edge_active_offset);
                encoder.set_input_buffer(10, Some(inputs.edge_layers), inputs.edge_layers_offset);
                encoder.set_input_buffer(11, Some(inputs.edge_types), inputs.edge_types_offset);
                encoder.set_input_buffer(
                    12,
                    Some(inputs.relationship_masks),
                    inputs.relationship_masks_offset,
                );
                encoder.set_input_buffer(13, Some(source), 0);
                encoder.set_output_buffer(14, Some(destination), 0);
                encoder.set_input_buffer(15, Some(buffers.offsets), 0);
                encoder.set_output_buffer(16, Some(buffers.control), 0);
                encoder.set_input_buffer(
                    17,
                    Some(inputs.outgoing_overlay),
                    inputs.outgoing_overlay_offset,
                );
                encoder.set_input_buffer(
                    18,
                    Some(inputs.incoming_overlay),
                    inputs.incoming_overlay_offset,
                );
                encoder.set_bytes(19, args);
                encoder.set_bytes(20, &step);
                encoder.dispatch_thread_groups(
                    objc2_metal::MTLSize {
                        width: groups,
                        height: 1,
                        depth: 1,
                    },
                    objc2_metal::MTLSize {
                        width: METAL_SORT_THREADS,
                        height: 1,
                        depth: 1,
                    },
                );
                encoder.insert_memory_barrier();

                if depth >= minimum {
                    encode_metal_variable_path_accept(
                        encoder,
                        pipelines,
                        destination,
                        inputs.target_masks,
                        inputs.target_masks_offset,
                        inputs.packet,
                        inputs.packet_offset,
                        buffers.accepted,
                        buffers.counts,
                        buffers.offsets,
                        buffers.control,
                        args,
                        &step,
                        groups,
                    );
                }
                source_is_a = !source_is_a;
            }
        }

        encoder.set_compute_pipeline_state(&pipelines.variable_path_segment_finish);
        encoder.set_output_buffer(0, Some(buffers.control), 0);
        encoder.set_bytes(1, args);
        encoder.set_bytes(2, &step);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();
        encoder.set_compute_pipeline_state(&pipelines.variable_path_copy);
        encoder.set_input_buffer(0, Some(buffers.accepted), 0);
        encoder.set_output_buffer(1, Some(buffers.frontier_a), 0);
        encoder.set_input_buffer(2, Some(buffers.control), 0);
        encoder.set_bytes(3, args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: groups,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();
    }

    encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_clear);
    encoder.set_output_buffer(0, Some(buffers.parent_matches), 0);
    encoder.set_output_buffer(1, Some(buffers.counts), 0);
    encoder.set_output_buffer(2, Some(buffers.offsets), 0);
    encoder.set_output_buffer(3, Some(buffers.control), 0);
    encoder.set_bytes(4, args);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: groups,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: METAL_SORT_THREADS,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();

    encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_count);
    encoder.set_input_buffer(0, Some(buffers.frontier_a), 0);
    encoder.set_input_buffer(1, Some(buffers.parent_table), 0);
    encoder.set_output_buffer(2, Some(buffers.counts), 0);
    encoder.set_output_buffer(3, Some(buffers.parent_matches), 0);
    encoder.set_output_buffer(4, Some(buffers.control), 0);
    encoder.set_bytes(5, args);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: groups,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: METAL_SORT_THREADS,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();

    encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_prefix);
    encoder.set_input_buffer(0, Some(buffers.counts), 0);
    encoder.set_output_buffer(1, Some(buffers.offsets), 0);
    encoder.set_output_buffer(2, Some(buffers.control), 0);
    encoder.set_bytes(3, args);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();

    encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_scatter);
    encoder.set_input_buffer(0, Some(buffers.frontier_a), 0);
    encoder.set_input_buffer(1, Some(buffers.counts), 0);
    encoder.set_input_buffer(2, Some(buffers.offsets), 0);
    encoder.set_output_buffer(3, Some(buffers.row_map), 0);
    encoder.set_output_buffer(4, Some(buffers.control), 0);
    encoder.set_bytes(5, args);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: groups,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: METAL_SORT_THREADS,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();

    encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_nulls);
    encoder.set_input_buffer(0, Some(buffers.parent_table), 0);
    encoder.set_input_buffer(1, Some(buffers.parent_matches), 0);
    encoder.set_output_buffer(2, Some(buffers.row_map), 0);
    encoder.set_output_buffer(3, Some(buffers.control), 0);
    encoder.set_bytes(4, args);
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();

    encoder.set_compute_pipeline_state(&pipelines.variable_path_publish);
    encoder.set_input_buffer(0, Some(inputs.packet), inputs.packet_offset);
    encoder.set_input_buffer(1, Some(buffers.frontier_a), 0);
    encoder.set_input_buffer(2, Some(buffers.parent_table), 0);
    encoder.set_input_buffer(3, Some(buffers.row_map), 0);
    encoder.set_input_buffer(4, Some(buffers.control), 0);
    encoder.set_output_buffer(5, Some(buffers.output), 0);
    encoder.set_bytes(6, args);
    // Fused quantifier sources admit only raw Publications. Bind resident dummy lanes to the
    // reduction-only slots so the shared v6 kernel has a complete argument table.
    encoder.set_input_buffer(7, Some(inputs.node_active), inputs.node_active_offset);
    encoder.set_input_buffer(8, Some(inputs.edge_types), inputs.edge_types_offset);
    encoder.set_input_buffer(9, Some(inputs.node_active), inputs.node_active_offset);
    encoder.set_input_buffer(
        10,
        Some(inputs.outgoing_offsets),
        inputs.outgoing_offsets_offset,
    );
    encoder.set_input_buffer(
        11,
        Some(inputs.outgoing_neighbors),
        inputs.outgoing_neighbors_offset,
    );
    encoder.set_input_buffer(
        12,
        Some(inputs.outgoing_edges),
        inputs.outgoing_edges_offset,
    );
    encoder.set_input_buffer(
        13,
        Some(inputs.incoming_offsets),
        inputs.incoming_offsets_offset,
    );
    encoder.set_input_buffer(
        14,
        Some(inputs.incoming_neighbors),
        inputs.incoming_neighbors_offset,
    );
    encoder.set_input_buffer(
        15,
        Some(inputs.incoming_edges),
        inputs.incoming_edges_offset,
    );
    encoder.set_input_buffer(16, Some(inputs.node_active), inputs.node_active_offset);
    encoder.set_input_buffer(17, Some(inputs.node_layers), inputs.node_layers_offset);
    encoder.set_input_buffer(18, Some(inputs.edge_active), inputs.edge_active_offset);
    encoder.set_input_buffer(19, Some(inputs.edge_layers), inputs.edge_layers_offset);
    encoder.set_input_buffer(20, Some(inputs.edge_types), inputs.edge_types_offset);
    encoder.set_input_buffer(
        21,
        Some(inputs.outgoing_overlay),
        inputs.outgoing_overlay_offset,
    );
    encoder.set_input_buffer(
        22,
        Some(inputs.incoming_overlay),
        inputs.incoming_overlay_offset,
    );
    encoder.dispatch_thread_groups(
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
        objc2_metal::MTLSize {
            width: 1,
            height: 1,
            depth: 1,
        },
    );
    encoder.insert_memory_barrier();
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp2 for MetalResidentVariablePath {
    fn name(&self) -> &'static str {
        "irongraph-metal-resident-variable-path"
    }

    fn cpu_fwd(
        &self,
        _input_rows: &CpuStorage,
        _input_rows_layout: &Layout,
        _packet: &CpuStorage,
        _packet_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal resident variable-path program cannot execute on CPU".to_owned(),
        ))
    }

    #[allow(clippy::too_many_lines)]
    fn metal_fwd(
        &self,
        input_rows: &MetalStorage,
        input_rows_layout: &Layout,
        packet: &MetalStorage,
        packet_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        macro_rules! metal_tensor {
            ($field:ident, $storage:ident, $layout:ident, $metal:ident, $message:literal) => {
                let ($storage, $layout) = self.$field.storage_and_layout();
                let Storage::Metal($metal) = &*$storage else {
                    return Err(candle_core::Error::Msg($message.to_owned()));
                };
            };
        }
        metal_tensor!(
            start_mask,
            start_mask_storage,
            start_mask_layout,
            start_mask,
            "variable-path start mask moved off Metal"
        );
        metal_tensor!(
            multiplicity_masks,
            multiplicity_masks_storage,
            multiplicity_masks_layout,
            multiplicity_masks,
            "variable-path multiplicity masks moved off Metal"
        );
        metal_tensor!(
            terminal_mask,
            terminal_mask_storage,
            terminal_mask_layout,
            terminal_mask,
            "variable-path terminal mask moved off Metal"
        );
        metal_tensor!(
            target_masks,
            target_masks_storage,
            target_masks_layout,
            target_masks,
            "variable-path target masks moved off Metal"
        );
        metal_tensor!(
            relationship_masks,
            relationship_masks_storage,
            relationship_masks_layout,
            relationship_masks,
            "variable-path relationship masks moved off Metal"
        );
        metal_tensor!(
            outgoing_offsets,
            outgoing_offsets_storage,
            outgoing_offsets_layout,
            outgoing_offsets,
            "variable-path outgoing offsets moved off Metal"
        );
        metal_tensor!(
            outgoing_neighbors,
            outgoing_neighbors_storage,
            outgoing_neighbors_layout,
            outgoing_neighbors,
            "variable-path outgoing neighbors moved off Metal"
        );
        metal_tensor!(
            outgoing_edges,
            outgoing_edges_storage,
            outgoing_edges_layout,
            outgoing_edges,
            "variable-path outgoing edges moved off Metal"
        );
        metal_tensor!(
            outgoing_overlay,
            outgoing_overlay_storage,
            outgoing_overlay_layout,
            outgoing_overlay,
            "variable-path outgoing overlay moved off Metal"
        );
        metal_tensor!(
            incoming_offsets,
            incoming_offsets_storage,
            incoming_offsets_layout,
            incoming_offsets,
            "variable-path incoming offsets moved off Metal"
        );
        metal_tensor!(
            incoming_neighbors,
            incoming_neighbors_storage,
            incoming_neighbors_layout,
            incoming_neighbors,
            "variable-path incoming neighbors moved off Metal"
        );
        metal_tensor!(
            incoming_edges,
            incoming_edges_storage,
            incoming_edges_layout,
            incoming_edges,
            "variable-path incoming edges moved off Metal"
        );
        metal_tensor!(
            incoming_overlay,
            incoming_overlay_storage,
            incoming_overlay_layout,
            incoming_overlay,
            "variable-path incoming overlay moved off Metal"
        );
        metal_tensor!(
            node_active,
            node_active_storage,
            node_active_layout,
            node_active,
            "variable-path node-active column moved off Metal"
        );
        metal_tensor!(
            node_layers,
            node_layers_storage,
            node_layers_layout,
            node_layers,
            "variable-path node-layer column moved off Metal"
        );
        metal_tensor!(
            edge_active,
            edge_active_storage,
            edge_active_layout,
            edge_active,
            "variable-path edge-active column moved off Metal"
        );
        metal_tensor!(
            edge_layers,
            edge_layers_storage,
            edge_layers_layout,
            edge_layers,
            "variable-path edge-layer column moved off Metal"
        );
        metal_tensor!(
            edge_types,
            edge_types_storage,
            edge_types_layout,
            edge_types,
            "variable-path edge-type column moved off Metal"
        );
        metal_tensor!(
            final_node_mask,
            final_node_mask_storage,
            final_node_mask_layout,
            final_node_mask,
            "variable-path final node mask moved off Metal"
        );
        metal_tensor!(
            final_property_values,
            final_property_values_storage,
            final_property_values_layout,
            final_property_values,
            "variable-path final property values moved off Metal"
        );
        metal_tensor!(
            final_property_validity,
            final_property_validity_storage,
            final_property_validity_layout,
            final_property_validity,
            "variable-path final property validity moved off Metal"
        );

        let node_storage_rows = self.node_count.max(1);
        let edge_storage_rows = self.edge_count.max(1);
        let input_storage_rows = if self.source_mode == 0 {
            self.input_row_count.max(1)
        } else {
            1
        };
        let layouts = [
            input_rows_layout,
            packet_layout,
            &start_mask_layout,
            &multiplicity_masks_layout,
            &terminal_mask_layout,
            &target_masks_layout,
            &relationship_masks_layout,
            &outgoing_offsets_layout,
            &outgoing_neighbors_layout,
            &outgoing_edges_layout,
            &outgoing_overlay_layout,
            &incoming_offsets_layout,
            &incoming_neighbors_layout,
            &incoming_edges_layout,
            &incoming_overlay_layout,
            &node_active_layout,
            &node_layers_layout,
            &edge_active_layout,
            &edge_layers_layout,
            &edge_types_layout,
            &final_node_mask_layout,
            &final_property_values_layout,
            &final_property_validity_layout,
        ];
        if layouts
            .iter()
            .any(|layout| !layout.is_contiguous() || layout.dims().len() != 1)
            || input_rows.dtype() != DType::U32
            || packet.dtype() != DType::I64
            || self.start_mask.dtype() != DType::U8
            || self.multiplicity_masks.dtype() != DType::U8
            || self.terminal_mask.dtype() != DType::U8
            || self.target_masks.dtype() != DType::U8
            || self.relationship_masks.dtype() != DType::U8
            || self.outgoing_offsets.dtype() != DType::U32
            || self.outgoing_neighbors.dtype() != DType::U32
            || self.outgoing_edges.dtype() != DType::U32
            || self.outgoing_overlay.dtype() != DType::U32
            || self.incoming_offsets.dtype() != DType::U32
            || self.incoming_neighbors.dtype() != DType::U32
            || self.incoming_edges.dtype() != DType::U32
            || self.incoming_overlay.dtype() != DType::U32
            || self.node_active.dtype() != DType::U8
            || self.node_layers.dtype() != DType::U8
            || self.edge_active.dtype() != DType::U8
            || self.edge_layers.dtype() != DType::U8
            || self.edge_types.dtype() != DType::I64
            || self.final_node_mask.dtype() != DType::U8
            || self.final_property_values.dtype() != DType::I64
            || self.final_property_validity.dtype() != DType::U8
            || input_rows_layout.shape().elem_count() != input_storage_rows
            || packet_layout.shape().elem_count() != self.packet_word_count
            || start_mask_layout.shape().elem_count() != node_storage_rows
            || multiplicity_masks_layout.shape().elem_count()
                != if self.multiplicity_scan_count == 0 || self.node_count == 0 {
                    1
                } else {
                    self.multiplicity_scan_count.saturating_mul(self.node_count)
                }
            || terminal_mask_layout.shape().elem_count()
                != if self.bound_terminal_mode == 0 || self.node_count == 0 {
                    1
                } else {
                    self.node_count
                }
            || target_masks_layout.shape().elem_count()
                != if self.node_count == 0 {
                    1
                } else {
                    self.segment_count.saturating_mul(self.node_count)
                }
            || relationship_masks_layout.shape().elem_count()
                != if self.edge_count == 0 {
                    1
                } else {
                    self.segment_count.saturating_mul(self.edge_count)
                }
            || outgoing_offsets_layout.shape().elem_count() != self.node_count.saturating_add(1)
            || incoming_offsets_layout.shape().elem_count() != self.node_count.saturating_add(1)
            || outgoing_neighbors_layout.shape().elem_count()
                != outgoing_edges_layout.shape().elem_count()
            || incoming_neighbors_layout.shape().elem_count()
                != incoming_edges_layout.shape().elem_count()
            || outgoing_overlay_layout.shape().elem_count()
                < self
                    .outgoing_overlay_count
                    .saturating_mul(2)
                    .saturating_add(1)
            || incoming_overlay_layout.shape().elem_count()
                < self
                    .incoming_overlay_count
                    .saturating_mul(2)
                    .saturating_add(1)
            || node_active_layout.shape().elem_count() != node_storage_rows
            || node_layers_layout.shape().elem_count() != node_storage_rows
            || edge_active_layout.shape().elem_count() != edge_storage_rows
            || edge_layers_layout.shape().elem_count() != edge_storage_rows
            || edge_types_layout.shape().elem_count() != edge_storage_rows
            || final_node_mask_layout.shape().elem_count()
                != if ((matches!(self.final_projection_mode, 4 | 6)
                    && self.final_projection_flags & 1 != 0)
                    || (self.final_projection_mode == 7 && self.final_projection_flags & 1 != 0)
                    || self.final_projection_mode == 12)
                    && self.node_count != 0
                {
                    self.node_count
                } else {
                    1
                }
            || final_property_values_layout.shape().elem_count()
                != match self.final_projection_mode {
                    5 if self.final_projection_flags & 1 != 0 && self.node_count != 0 => {
                        self.node_count
                    }
                    7..=8 if self.node_count != 0 => self.node_count,
                    9 | 11 if self.edge_count != 0 => self.edge_count,
                    14 if self.node_count != 0 => self.node_count.saturating_mul(3),
                    _ => 1,
                }
            || final_property_validity_layout.shape().elem_count()
                != final_property_values_layout.shape().elem_count()
            || self.segment_count == 0
            || self.segment_count != self.segment_bounds.len()
            || self.multiplicity_scan_count > super::RESIDENT_VARIABLE_PATH_MAX_MULTIPLICITY_SCANS
            || self.source_mode > 1
            || self.bound_terminal_mode > 1
            || self.optional_mode > 1
            || self.final_projection_mode > 16
            || self.final_projection_obligation_count
                != match self.final_projection_mode {
                    0 => 0,
                    1..=3 => 1,
                    4..=5 => 2,
                    6 => 4,
                    7 => 3,
                    8 => 2,
                    9 => 4,
                    10 => 2,
                    11 => 1,
                    12 => 4,
                    13 => 2,
                    14 => 4,
                    15 => 1,
                    16 => 3,
                    _ => usize::MAX,
                }
            || (self.source_mode == 0 && self.scan_obligation_id != 0)
            || (self.source_mode == 1 && self.scan_obligation_id == 0)
            || (self.bound_terminal_mode == 0 && self.bound_terminal_obligation_id != 0)
            || (self.bound_terminal_mode != 0 && self.bound_terminal_obligation_id == 0)
            || ((self.multiplicity_scan_count == 0 && self.bound_terminal_mode == 0)
                != (self.cartesian_obligation_id == 0))
        {
            return Err(candle_core::Error::Msg(
                "Metal resident variable-path tensor contract is invalid".to_owned(),
            ));
        }

        let edge_stride = self.edge_count;
        let node_stride = edge_stride.checked_add(1).ok_or_else(|| {
            candle_core::Error::Msg("variable-path node stride overflow".to_owned())
        })?;
        let path_store_words = self
            .frontier_capacity
            .checked_mul(
                4_usize
                    .checked_add(edge_stride)
                    .and_then(|width| width.checked_add(node_stride))
                    .and_then(|width| width.checked_add(self.segment_count))
                    .ok_or_else(|| {
                        candle_core::Error::Msg("variable-path store width overflow".to_owned())
                    })?,
            )
            .ok_or_else(|| {
                candle_core::Error::Msg("variable-path store shape overflow".to_owned())
            })?;
        let parent_table_words = self.frontier_capacity.checked_mul(2).ok_or_else(|| {
            candle_core::Error::Msg("variable-path parent table shape overflow".to_owned())
        })?;
        let row_map_words = self.output_capacity.checked_mul(2).ok_or_else(|| {
            candle_core::Error::Msg("variable-path publication map shape overflow".to_owned())
        })?;
        let control_words = 16_usize
            .checked_add(self.multiplicity_scan_count)
            .and_then(|words| words.checked_add(self.bound_terminal_mode as usize))
            .and_then(|words| words.checked_add(self.segment_count.saturating_mul(2)))
            .ok_or_else(|| {
                candle_core::Error::Msg("variable-path control shape overflow".to_owned())
            })?;
        let receipt_count = self
            .segment_count
            .checked_add(1)
            .and_then(|count| count.checked_add(self.multiplicity_scan_count))
            .and_then(|count| count.checked_add(self.bound_terminal_mode as usize))
            .and_then(|count| count.checked_add(usize::from(self.cartesian_obligation_id != 0)))
            .and_then(|count| count.checked_add(usize::from(self.source_mode == 1)))
            .and_then(|count| count.checked_add(self.final_projection_obligation_count))
            .ok_or_else(|| {
                candle_core::Error::Msg("variable-path receipt count overflow".to_owned())
            })?;
        let output_words = METAL_VARIABLE_PATH_OUTPUT_HEADER_WORDS
            .checked_add(
                receipt_count
                    .checked_mul(METAL_VARIABLE_PATH_RECEIPT_WORDS)
                    .ok_or_else(|| {
                        candle_core::Error::Msg("variable-path receipt frame overflow".to_owned())
                    })?,
            )
            .and_then(|words| words.checked_add(self.output_capacity.saturating_mul(3)))
            .and_then(|words| words.checked_add(self.output_capacity.saturating_mul(edge_stride)))
            .and_then(|words| words.checked_add(self.output_capacity.saturating_mul(node_stride)))
            .and_then(|words| {
                words.checked_add(self.output_capacity.saturating_mul(self.segment_count))
            })
            .and_then(|words| words.checked_add(self.output_capacity.saturating_mul(3)))
            .and_then(|words| match self.final_projection_mode {
                0 => Some(words),
                1..=5 => words.checked_add(self.output_capacity.saturating_mul(5)),
                6 => words.checked_add(self.final_projection_capacity_1),
                7 => words.checked_add(self.output_capacity.saturating_add(self.node_count)),
                8 => words.checked_add(self.final_projection_capacity_0),
                9 => words.checked_add(1),
                10 => words.checked_add(self.final_projection_capacity_0.saturating_mul(2)),
                11 => words.checked_add(self.output_capacity.saturating_mul(5)),
                12 => words.checked_add(1),
                13 => words.checked_add(self.output_capacity.saturating_mul(5)),
                14..=16 => words.checked_add(self.output_capacity.saturating_mul(5)),
                _ => None,
            })
            .ok_or_else(|| {
                candle_core::Error::Msg("variable-path output frame overflow".to_owned())
            })?;
        let args = MetalVariablePathArgs {
            execution_high: self.execution.high,
            execution_low: self.execution.low,
            bookmark_term: self.bookmark.term,
            bookmark_index: self.bookmark.index,
            graph_revision: self.graph_revision,
            layout_version: self.layout_version,
            scan_obligation_id: self.scan_obligation_id,
            bound_terminal_obligation_id: self.bound_terminal_obligation_id,
            cartesian_obligation_id: self.cartesian_obligation_id,
            final_obligation_id: self.final_obligation_id,
            final_projection_argument: self.final_projection_argument,
            final_projection_flags: self.final_projection_flags,
            final_projection_capacity_0: self.final_projection_capacity_0 as u64,
            final_projection_capacity_1: self.final_projection_capacity_1 as u64,
            final_projection_operand_0: self.final_projection_operand_0,
            final_projection_operand_1: self.final_projection_operand_1,
            output_word_count: output_words as u64,
            source_mode: self.source_mode,
            bound_terminal_mode: self.bound_terminal_mode,
            optional_mode: self.optional_mode,
            final_projection_mode: self.final_projection_mode,
            final_projection_obligation_count: u32::try_from(
                self.final_projection_obligation_count,
            )
            .map_err(|_| {
                candle_core::Error::Msg(
                    "variable-path projection receipt count exceeds u32".to_owned(),
                )
            })?,
            input_row_count: u32::try_from(self.input_row_count).map_err(|_| {
                candle_core::Error::Msg("variable-path input rows exceed u32".to_owned())
            })?,
            node_count: u32::try_from(self.node_count).map_err(|_| {
                candle_core::Error::Msg("variable-path node count exceeds u32".to_owned())
            })?,
            edge_count: u32::try_from(self.edge_count).map_err(|_| {
                candle_core::Error::Msg("variable-path edge count exceeds u32".to_owned())
            })?,
            outgoing_overlay_count: u32::try_from(self.outgoing_overlay_count).map_err(|_| {
                candle_core::Error::Msg("variable-path outgoing overlay rows exceed u32".to_owned())
            })?,
            incoming_overlay_count: u32::try_from(self.incoming_overlay_count).map_err(|_| {
                candle_core::Error::Msg("variable-path incoming overlay rows exceed u32".to_owned())
            })?,
            segment_count: u32::try_from(self.segment_count).map_err(|_| {
                candle_core::Error::Msg("variable-path segment count exceeds u32".to_owned())
            })?,
            multiplicity_scan_count: u32::try_from(self.multiplicity_scan_count).map_err(|_| {
                candle_core::Error::Msg(
                    "variable-path multiplicity scan count exceeds u32".to_owned(),
                )
            })?,
            packet_word_count: u32::try_from(self.packet_word_count).map_err(|_| {
                candle_core::Error::Msg("variable-path packet exceeds u32".to_owned())
            })?,
            layer_mask: u32::from(self.layer_mask),
            frontier_capacity: u32::try_from(self.frontier_capacity).map_err(|_| {
                candle_core::Error::Msg("variable-path frontier exceeds u32".to_owned())
            })?,
            output_capacity: u32::try_from(self.output_capacity).map_err(|_| {
                candle_core::Error::Msg("variable-path output capacity exceeds u32".to_owned())
            })?,
            output_limit: self
                .output_limit
                .map_or(u32::MAX, |limit| u32::try_from(limit).unwrap_or(u32::MAX)),
            receipt_count: u32::try_from(receipt_count).map_err(|_| {
                candle_core::Error::Msg("variable-path receipt count exceeds u32".to_owned())
            })?,
            path_store_words: u32::try_from(path_store_words).map_err(|_| {
                candle_core::Error::Msg("variable-path store exceeds u32 words".to_owned())
            })?,
            control_words: u32::try_from(control_words).map_err(|_| {
                candle_core::Error::Msg("variable-path control exceeds u32 words".to_owned())
            })?,
        };
        let device = input_rows.device();
        let pipelines = metal_sort_pipelines(device)?;
        let frontier_a = device
            .new_buffer_builder()
            .with_size_for(path_store_words.max(1), DType::U32)
            .with_label("irongraph variable-path frontier A")
            .build()?;
        let frontier_b = device
            .new_buffer_builder()
            .with_size_for(path_store_words.max(1), DType::U32)
            .with_label("irongraph variable-path frontier B")
            .build()?;
        let accepted = device
            .new_buffer_builder()
            .with_size_for(path_store_words.max(1), DType::U32)
            .with_label("irongraph variable-path accepted paths")
            .build()?;
        let counts = device
            .new_buffer_builder()
            .with_size_for(self.frontier_capacity.max(1), DType::U32)
            .with_label("irongraph variable-path candidate counts")
            .build()?;
        let offsets = device
            .new_buffer_builder()
            .with_size_for(self.frontier_capacity.max(1), DType::U32)
            .with_label("irongraph variable-path candidate offsets")
            .build()?;
        let terminal_row_capacity =
            metal_variable_path_terminal_row_capacity(self.bound_terminal_mode, self.node_count);
        let terminal_rows = device
            .new_buffer_builder()
            .with_size_for(terminal_row_capacity, DType::U32)
            .with_label("irongraph variable-path terminal rows")
            .build()?;
        let parent_table = device
            .new_buffer_builder()
            .with_size_for(parent_table_words.max(1), DType::U32)
            .with_label("irongraph variable-path parent table")
            .build()?;
        let parent_matches = device
            .new_buffer_builder()
            .with_size_for(self.frontier_capacity.max(1), DType::U32)
            .with_label("irongraph variable-path parent matches")
            .build()?;
        let row_map = device
            .new_buffer_builder()
            .with_size_for(row_map_words.max(1), DType::U32)
            .with_label("irongraph variable-path publication map")
            .build()?;
        let control = device
            .new_buffer_builder()
            .with_size_for(control_words.max(1), DType::U32)
            .with_label("irongraph variable-path control")
            .build()?;
        let output = device
            .new_buffer_builder()
            .with_size_for(output_words.max(1), DType::I64)
            .with_label("irongraph variable-path paths and receipts")
            .build()?;

        let groups = self.frontier_capacity.div_ceil(METAL_SORT_THREADS).max(1);
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&pipelines.variable_path_initialize);
        encoder.set_input_buffer(
            0,
            Some(input_rows.buffer()),
            input_rows_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(packet.buffer()),
            packet_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(start_mask.buffer()),
            start_mask_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            3,
            Some(multiplicity_masks.buffer()),
            multiplicity_masks_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            4,
            Some(terminal_mask.buffer()),
            terminal_mask_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_output_buffer(5, Some(&frontier_a), 0);
        encoder.set_output_buffer(6, Some(&terminal_rows), 0);
        encoder.set_output_buffer(7, Some(&parent_table), 0);
        encoder.set_output_buffer(8, Some(&control), 0);
        encoder.set_bytes(9, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        for (segment, (minimum, maximum)) in self.segment_bounds.iter().copied().enumerate() {
            let mut step = MetalVariablePathStepArgs {
                segment: segment as u32,
                depth: 0,
            };
            encoder.set_compute_pipeline_state(&pipelines.variable_path_segment_begin);
            encoder.set_input_buffer(
                0,
                Some(packet.buffer()),
                packet_layout.start_offset() * DType::I64.size_in_bytes(),
            );
            encoder.set_input_buffer(1, Some(&control), 0);
            encoder.set_bytes(2, &args);
            encoder.set_bytes(3, &step);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
            );
            encoder.insert_memory_barrier();

            if minimum == 0 && minimum <= maximum {
                encode_metal_variable_path_accept(
                    encoder,
                    &pipelines,
                    &frontier_a,
                    target_masks.buffer(),
                    target_masks_layout.start_offset() * DType::U8.size_in_bytes(),
                    packet.buffer(),
                    packet_layout.start_offset() * DType::I64.size_in_bytes(),
                    &accepted,
                    &counts,
                    &offsets,
                    &control,
                    &args,
                    &step,
                    groups,
                );
            }

            let mut source_is_a = true;
            if minimum <= maximum {
                for depth in 1..=maximum {
                    step.depth = depth;
                    let (source, destination) = if source_is_a {
                        (&frontier_a, &frontier_b)
                    } else {
                        (&frontier_b, &frontier_a)
                    };
                    encoder.set_compute_pipeline_state(&pipelines.variable_path_expand_count);
                    encoder.set_input_buffer(
                        0,
                        Some(packet.buffer()),
                        packet_layout.start_offset() * DType::I64.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        1,
                        Some(outgoing_offsets.buffer()),
                        outgoing_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        2,
                        Some(outgoing_neighbors.buffer()),
                        outgoing_neighbors_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        3,
                        Some(outgoing_edges.buffer()),
                        outgoing_edges_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        4,
                        Some(incoming_offsets.buffer()),
                        incoming_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        5,
                        Some(incoming_neighbors.buffer()),
                        incoming_neighbors_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        6,
                        Some(incoming_edges.buffer()),
                        incoming_edges_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        7,
                        Some(node_active.buffer()),
                        node_active_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        8,
                        Some(node_layers.buffer()),
                        node_layers_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        9,
                        Some(edge_active.buffer()),
                        edge_active_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        10,
                        Some(edge_layers.buffer()),
                        edge_layers_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        11,
                        Some(edge_types.buffer()),
                        edge_types_layout.start_offset() * DType::I64.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        12,
                        Some(relationship_masks.buffer()),
                        relationship_masks_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(13, Some(source), 0);
                    encoder.set_output_buffer(14, Some(&counts), 0);
                    encoder.set_output_buffer(15, Some(&control), 0);
                    encoder.set_input_buffer(
                        16,
                        Some(outgoing_overlay.buffer()),
                        outgoing_overlay_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        17,
                        Some(incoming_overlay.buffer()),
                        incoming_overlay_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_bytes(18, &args);
                    encoder.set_bytes(19, &step);
                    encoder.dispatch_thread_groups(
                        objc2_metal::MTLSize {
                            width: groups,
                            height: 1,
                            depth: 1,
                        },
                        objc2_metal::MTLSize {
                            width: METAL_SORT_THREADS,
                            height: 1,
                            depth: 1,
                        },
                    );
                    encoder.insert_memory_barrier();

                    encoder.set_compute_pipeline_state(&pipelines.variable_path_prefix);
                    encoder.set_input_buffer(0, Some(&counts), 0);
                    encoder.set_output_buffer(1, Some(&offsets), 0);
                    encoder.set_output_buffer(2, Some(&control), 0);
                    encoder.set_bytes(3, &args);
                    encoder.dispatch_thread_groups(
                        objc2_metal::MTLSize {
                            width: 1,
                            height: 1,
                            depth: 1,
                        },
                        objc2_metal::MTLSize {
                            width: 1,
                            height: 1,
                            depth: 1,
                        },
                    );
                    encoder.insert_memory_barrier();

                    encoder.set_compute_pipeline_state(&pipelines.variable_path_scatter);
                    encoder.set_input_buffer(
                        0,
                        Some(packet.buffer()),
                        packet_layout.start_offset() * DType::I64.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        1,
                        Some(outgoing_offsets.buffer()),
                        outgoing_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        2,
                        Some(outgoing_neighbors.buffer()),
                        outgoing_neighbors_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        3,
                        Some(outgoing_edges.buffer()),
                        outgoing_edges_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        4,
                        Some(incoming_offsets.buffer()),
                        incoming_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        5,
                        Some(incoming_neighbors.buffer()),
                        incoming_neighbors_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        6,
                        Some(incoming_edges.buffer()),
                        incoming_edges_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        7,
                        Some(node_active.buffer()),
                        node_active_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        8,
                        Some(node_layers.buffer()),
                        node_layers_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        9,
                        Some(edge_active.buffer()),
                        edge_active_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        10,
                        Some(edge_layers.buffer()),
                        edge_layers_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        11,
                        Some(edge_types.buffer()),
                        edge_types_layout.start_offset() * DType::I64.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        12,
                        Some(relationship_masks.buffer()),
                        relationship_masks_layout.start_offset() * DType::U8.size_in_bytes(),
                    );
                    encoder.set_input_buffer(13, Some(source), 0);
                    encoder.set_output_buffer(14, Some(destination), 0);
                    encoder.set_input_buffer(15, Some(&offsets), 0);
                    encoder.set_output_buffer(16, Some(&control), 0);
                    encoder.set_input_buffer(
                        17,
                        Some(outgoing_overlay.buffer()),
                        outgoing_overlay_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_input_buffer(
                        18,
                        Some(incoming_overlay.buffer()),
                        incoming_overlay_layout.start_offset() * DType::U32.size_in_bytes(),
                    );
                    encoder.set_bytes(19, &args);
                    encoder.set_bytes(20, &step);
                    encoder.dispatch_thread_groups(
                        objc2_metal::MTLSize {
                            width: groups,
                            height: 1,
                            depth: 1,
                        },
                        objc2_metal::MTLSize {
                            width: METAL_SORT_THREADS,
                            height: 1,
                            depth: 1,
                        },
                    );
                    encoder.insert_memory_barrier();

                    if depth >= minimum {
                        encode_metal_variable_path_accept(
                            encoder,
                            &pipelines,
                            destination,
                            target_masks.buffer(),
                            target_masks_layout.start_offset() * DType::U8.size_in_bytes(),
                            packet.buffer(),
                            packet_layout.start_offset() * DType::I64.size_in_bytes(),
                            &accepted,
                            &counts,
                            &offsets,
                            &control,
                            &args,
                            &step,
                            groups,
                        );
                    }
                    source_is_a = !source_is_a;
                }
            }

            encoder.set_compute_pipeline_state(&pipelines.variable_path_segment_finish);
            encoder.set_output_buffer(0, Some(&control), 0);
            encoder.set_bytes(1, &args);
            encoder.set_bytes(2, &step);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
            );
            encoder.insert_memory_barrier();
            encoder.set_compute_pipeline_state(&pipelines.variable_path_copy);
            encoder.set_input_buffer(0, Some(&accepted), 0);
            encoder.set_output_buffer(1, Some(&frontier_a), 0);
            encoder.set_input_buffer(2, Some(&control), 0);
            encoder.set_bytes(3, &args);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: groups,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: METAL_SORT_THREADS,
                    height: 1,
                    depth: 1,
                },
            );
            encoder.insert_memory_barrier();
        }

        encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_clear);
        encoder.set_output_buffer(0, Some(&parent_matches), 0);
        encoder.set_output_buffer(1, Some(&counts), 0);
        encoder.set_output_buffer(2, Some(&offsets), 0);
        encoder.set_output_buffer(3, Some(&control), 0);
        encoder.set_bytes(4, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: groups,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_count);
        encoder.set_input_buffer(0, Some(&frontier_a), 0);
        encoder.set_input_buffer(1, Some(&parent_table), 0);
        encoder.set_output_buffer(2, Some(&counts), 0);
        encoder.set_output_buffer(3, Some(&parent_matches), 0);
        encoder.set_output_buffer(4, Some(&control), 0);
        encoder.set_bytes(5, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: groups,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_prefix);
        encoder.set_input_buffer(0, Some(&counts), 0);
        encoder.set_output_buffer(1, Some(&offsets), 0);
        encoder.set_output_buffer(2, Some(&control), 0);
        encoder.set_bytes(3, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_scatter);
        encoder.set_input_buffer(0, Some(&frontier_a), 0);
        encoder.set_input_buffer(1, Some(&counts), 0);
        encoder.set_input_buffer(2, Some(&offsets), 0);
        encoder.set_output_buffer(3, Some(&row_map), 0);
        encoder.set_output_buffer(4, Some(&control), 0);
        encoder.set_bytes(5, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: groups,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.variable_path_finalize_nulls);
        encoder.set_input_buffer(0, Some(&parent_table), 0);
        encoder.set_input_buffer(1, Some(&parent_matches), 0);
        encoder.set_output_buffer(2, Some(&row_map), 0);
        encoder.set_output_buffer(3, Some(&control), 0);
        encoder.set_bytes(4, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.variable_path_publish);
        encoder.set_input_buffer(
            0,
            Some(packet.buffer()),
            packet_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(1, Some(&frontier_a), 0);
        encoder.set_input_buffer(2, Some(&parent_table), 0);
        encoder.set_input_buffer(3, Some(&row_map), 0);
        encoder.set_input_buffer(4, Some(&control), 0);
        encoder.set_output_buffer(5, Some(&output), 0);
        encoder.set_bytes(6, &args);
        encoder.set_input_buffer(
            7,
            Some(final_node_mask.buffer()),
            final_node_mask_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            8,
            Some(final_property_values.buffer()),
            final_property_values_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            9,
            Some(final_property_validity.buffer()),
            final_property_validity_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            10,
            Some(outgoing_offsets.buffer()),
            outgoing_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            11,
            Some(outgoing_neighbors.buffer()),
            outgoing_neighbors_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            12,
            Some(outgoing_edges.buffer()),
            outgoing_edges_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            13,
            Some(incoming_offsets.buffer()),
            incoming_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            14,
            Some(incoming_neighbors.buffer()),
            incoming_neighbors_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            15,
            Some(incoming_edges.buffer()),
            incoming_edges_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            16,
            Some(node_active.buffer()),
            node_active_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            17,
            Some(node_layers.buffer()),
            node_layers_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            18,
            Some(edge_active.buffer()),
            edge_active_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            19,
            Some(edge_layers.buffer()),
            edge_layers_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            20,
            Some(edge_types.buffer()),
            edge_types_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            21,
            Some(outgoing_overlay.buffer()),
            outgoing_overlay_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            22,
            Some(incoming_overlay.buffer()),
            incoming_overlay_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), output_words, DType::I64),
            Shape::from(output_words),
        ))
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
