#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Copy, Debug)]
struct MetalTemporalRegisterStep {
    function: super::ResidentTemporalValueFunction,
    input_tag: u32,
    payload_end: u32,
    zone_table_start: u32,
    zone_table_end: u32,
    zone_count: u32,
    register_count: u32,
    source_register: u32,
    right_register: u32,
    temporal_operation: u32,
    current_seconds_low: u32,
    current_seconds_high: u32,
    current_nanos: u32,
    register_stride: u32,
    string_capacity: u32,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp2 for MetalTemporalRegisterStep {
    fn name(&self) -> &'static str {
        match self.function {
            super::ResidentTemporalValueFunction::Date => "irongraph-metal-temporal-register-date",
            super::ResidentTemporalValueFunction::LocalTime => {
                "irongraph-metal-temporal-register-local-time"
            }
            super::ResidentTemporalValueFunction::Time => "irongraph-metal-temporal-register-time",
            super::ResidentTemporalValueFunction::LocalDateTime => {
                "irongraph-metal-temporal-register-local-datetime"
            }
            super::ResidentTemporalValueFunction::DateTime => {
                "irongraph-metal-temporal-register-datetime"
            }
            super::ResidentTemporalValueFunction::Duration => {
                "irongraph-metal-temporal-register-duration"
            }
        }
    }

    fn cpu_fwd(
        &self,
        _packet: &CpuStorage,
        _packet_layout: &Layout,
        _registers: &CpuStorage,
        _registers_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal temporal register step cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        packet: &MetalStorage,
        packet_layout: &Layout,
        registers: &MetalStorage,
        registers_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let register_stride = usize::try_from(self.register_stride).unwrap_or(usize::MAX);
        let required_register_words = usize::try_from(self.register_count)
            .ok()
            .and_then(|count| count.checked_mul(register_stride))
            .unwrap_or(usize::MAX)
            .max(register_stride);
        let packet_len = packet_layout.shape().elem_count();
        if packet.dtype() != DType::U8
            || registers.dtype() != DType::U32
            || !packet_layout.is_contiguous()
            || !registers_layout.is_contiguous()
            || packet_layout.dims().len() != 1
            || registers_layout.dims().len() != 1
            || packet_len == 0
            || register_stride < super::RESIDENT_TEMPORAL_REGISTER_BASE_WORDS
            || usize::try_from(self.string_capacity).map_or(true, |capacity| {
                capacity
                    > register_stride
                        .saturating_sub(2)
                        .saturating_mul(size_of::<u32>())
            })
            || registers_layout.shape().elem_count() != required_register_words
            || self.payload_end > self.zone_table_start
            || self.zone_table_start > self.zone_table_end
            || usize::try_from(self.zone_table_end).map_or(true, |end| end > packet_len)
            || self.input_tag > 9
            || (self.input_tag == 4 && self.source_register >= self.register_count)
            || (self.input_tag == 5
                && (self.source_register >= self.register_count
                    || self.right_register >= self.register_count))
            || (self.input_tag == 6 && self.source_register >= self.register_count)
            || (self.input_tag == 7 && self.current_nanos >= 1_000_000_000)
            || (self.input_tag == 8
                && (self.source_register >= self.register_count
                    || self.right_register >= self.register_count
                    || self.temporal_operation > 5))
            || (self.input_tag == 9 && self.source_register >= self.register_count)
        {
            return Err(candle_core::Error::Msg(
                "Metal temporal register tensor contract is invalid".to_owned(),
            ));
        }
        let device = packet.device();
        let pipeline = metal_temporal_register_pipeline(device, self.function)?;
        let output = device
            .new_buffer_builder()
            .with_size_for(register_stride, DType::U32)
            .with_label("irongraph temporal register output")
            .build()?;
        let arguments = MetalTemporalRegisterStepArgs {
            function: self.function as u32,
            input_tag: self.input_tag,
            payload_end: self.payload_end,
            zone_table_start: self.zone_table_start,
            zone_table_end: self.zone_table_end,
            zone_count: self.zone_count,
            register_count: self.register_count,
            source_register: self.source_register,
            right_register: self.right_register,
            temporal_operation: self.temporal_operation,
            current_seconds_low: self.current_seconds_low,
            current_seconds_high: self.current_seconds_high,
            current_nanos: self.current_nanos,
            register_stride: self.register_stride,
            string_capacity: self.string_capacity,
        };
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&pipeline);
        encoder.set_input_buffer(
            0,
            Some(packet.buffer()),
            packet_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(registers.buffer()),
            registers_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(2, Some(&output), 0);
        encoder.set_bytes(3, &arguments);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), register_stride, DType::U32),
            Shape::from(register_stride),
        ))
    }
}

