#[repr(C)]
#[derive(Clone, Copy, Debug)]
struct MetalScalarProgramArgs {
    output_count: u32,
    scalar_cell_count: u32,
    map_entry_count: u32,
    scalar_list_entry_count: u32,
    string_count: u32,
    string_byte_count: u32,
    instruction_count: u32,
    null_cell: u32,
    false_cell: u32,
    true_cell: u32,
    program_word_count: u32,
    table_word_count: u32,
    receipt_words: [u32; RESIDENT_SCALAR_PROGRAM_RECEIPT_WORDS],
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Copy, Debug)]
struct MetalScalarProgram {
    output_count: usize,
    scalar_cell_count: usize,
    map_entry_count: usize,
    scalar_list_entry_count: usize,
    string_count: usize,
    string_byte_count: usize,
    instruction_count: usize,
    null_cell: u16,
    false_cell: Option<u16>,
    true_cell: Option<u16>,
    program_word_count: usize,
    table_word_count: usize,
    receipt_words: [u32; RESIDENT_SCALAR_PROGRAM_RECEIPT_WORDS],
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp2 for MetalScalarProgram {
    fn name(&self) -> &'static str {
        "irongraph-metal-scalar-program"
    }

    fn cpu_fwd(
        &self,
        _program: &CpuStorage,
        _program_layout: &Layout,
        _tables: &CpuStorage,
        _tables_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal scalar value program cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        program: &MetalStorage,
        program_layout: &Layout,
        tables: &MetalStorage,
        tables_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let output_len = self
            .output_count
            .checked_add(self.table_word_count)
            .and_then(|words| words.checked_add(RESIDENT_SCALAR_PROGRAM_RECEIPT_WORDS))
            .ok_or_else(|| {
                candle_core::Error::Msg("Metal scalar value output length overflow".to_owned())
            })?;
        if self.output_count == 0
            || self.scalar_cell_count == 0
            || self.scalar_cell_count > u16::MAX as usize
            || self.instruction_count > 64
            || self.scalar_cell_count <= self.instruction_count
            || output_len > u32::MAX as usize
            || program.dtype() != DType::U32
            || tables.dtype() != DType::U32
            || !program_layout.is_contiguous()
            || !tables_layout.is_contiguous()
            || program_layout.dims().len() != 1
            || tables_layout.dims().len() != 1
            || program_layout.shape().elem_count() != self.program_word_count
            || tables_layout.shape().elem_count() != self.table_word_count
            || self.program_word_count
                != self
                    .instruction_count
                    .checked_mul(9)
                    .and_then(|words| words.checked_add(self.output_count.checked_mul(2)?))
                    .unwrap_or(usize::MAX)
            || self.table_word_count
                != self
                    .scalar_cell_count
                    .checked_mul(4)
                    .and_then(|words| words.checked_add(self.map_entry_count.checked_mul(2)?))
                    .and_then(|words| words.checked_add(self.scalar_list_entry_count))
                    .and_then(|words| words.checked_add(self.string_count.checked_add(1)?))
                    .and_then(|words| words.checked_add(self.string_byte_count))
                    .unwrap_or(usize::MAX)
            || self.null_cell as usize
                >= self
                    .scalar_cell_count
                    .saturating_sub(self.instruction_count)
        {
            return Err(candle_core::Error::Msg(
                "Metal scalar value tensor contract is invalid".to_owned(),
            ));
        }
        let arguments = MetalScalarProgramArgs {
            output_count: u32::try_from(self.output_count).map_err(|_| {
                candle_core::Error::Msg("Metal scalar value output count exceeds u32".to_owned())
            })?,
            scalar_cell_count: u32::try_from(self.scalar_cell_count).map_err(|_| {
                candle_core::Error::Msg("Metal scalar value cell count exceeds u32".to_owned())
            })?,
            map_entry_count: u32::try_from(self.map_entry_count).map_err(|_| {
                candle_core::Error::Msg("Metal scalar value map count exceeds u32".to_owned())
            })?,
            scalar_list_entry_count: u32::try_from(self.scalar_list_entry_count).map_err(|_| {
                candle_core::Error::Msg("Metal scalar value list count exceeds u32".to_owned())
            })?,
            string_count: u32::try_from(self.string_count).map_err(|_| {
                candle_core::Error::Msg("Metal scalar value string count exceeds u32".to_owned())
            })?,
            string_byte_count: u32::try_from(self.string_byte_count).map_err(|_| {
                candle_core::Error::Msg("Metal scalar value string bytes exceed u32".to_owned())
            })?,
            instruction_count: u32::try_from(self.instruction_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal scalar value instruction count exceeds u32".to_owned(),
                )
            })?,
            null_cell: u32::from(self.null_cell),
            false_cell: self.false_cell.map(u32::from).unwrap_or(u32::MAX),
            true_cell: self.true_cell.map(u32::from).unwrap_or(u32::MAX),
            program_word_count: u32::try_from(self.program_word_count).map_err(|_| {
                candle_core::Error::Msg("Metal scalar value program exceeds u32".to_owned())
            })?,
            table_word_count: u32::try_from(self.table_word_count).map_err(|_| {
                candle_core::Error::Msg("Metal scalar value table exceeds u32".to_owned())
            })?,
            receipt_words: self.receipt_words,
        };
        let device = program.device();
        let pipelines = metal_sort_pipelines(device)?;
        let output = device
            .new_buffer_builder()
            .with_size_for(output_len, DType::U32)
            .with_label("irongraph scalar value output")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&pipelines.scalar_program);
        encoder.set_input_buffer(
            0,
            Some(program.buffer()),
            program_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(tables.buffer()),
            tables_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(2, Some(&output), 0);
        encoder.set_bytes(3, &arguments);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                // The scalar VM has one deterministic register file. All lanes help copy the
                // result tables, while lane zero evaluates that register file.
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), output_len, DType::U32),
            Shape::from(output_len),
        ))
    }
}

