#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp3 for MetalBooleanProgram {
    fn name(&self) -> &'static str {
        "irongraph-metal-boolean-program"
    }

    fn cpu_fwd(
        &self,
        _inputs: &CpuStorage,
        _inputs_layout: &Layout,
        _code: &CpuStorage,
        _code_layout: &Layout,
        _output_and_filters: &CpuStorage,
        _output_and_filters_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal Boolean scalar program cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        inputs: &MetalStorage,
        inputs_layout: &Layout,
        code: &MetalStorage,
        code_layout: &Layout,
        output_and_filters: &MetalStorage,
        output_and_filters_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let output_width = self.output_count.checked_add(1).ok_or_else(|| {
            candle_core::Error::Msg("Metal Boolean scalar output width overflow".to_owned())
        })?;
        let output_len = self.row_count.checked_mul(output_width).ok_or_else(|| {
            candle_core::Error::Msg("Metal Boolean scalar output length overflow".to_owned())
        })?;
        let expected_code_len = self
            .instruction_count
            .checked_mul(3)
            .and_then(|words| words.checked_add(self.scalar_cell_count.checked_mul(4)?))
            .and_then(|words| words.checked_add(self.map_entry_count.checked_mul(2)?))
            .and_then(|words| words.checked_add(self.scalar_list_entry_count))
            .and_then(|words| words.checked_add(self.scalar_predicate_count.checked_mul(4)?))
            .and_then(|words| words.checked_add(self.reduction_count.checked_mul(3)?))
            .and_then(|words| words.checked_add(self.reduction_register_count))
            .and_then(|words| words.checked_add(self.scalar_expression_count.checked_mul(3)?))
            .and_then(|words| {
                words.checked_add(self.scalar_expression_instruction_count.checked_mul(3)?)
            })
            .unwrap_or(usize::MAX);
        let expected_input_stride = self
            .list_input_count
            .checked_mul(self.list_input_width.checked_add(1).unwrap_or(usize::MAX))
            .and_then(|lists| self.input_count.checked_add(lists))
            .unwrap_or(usize::MAX);
        // Empty-input programs carry one unread sentinel word because Candle Metal cannot create
        // a zero-length storage. Every non-empty input program is exactly row-major, including
        // the fixed-width row-local list slots used by `IN`.
        let expected_input_len = self
            .row_count
            .checked_mul(expected_input_stride)
            .unwrap_or(usize::MAX)
            .max(1);
        let expected_register_len = self
            .output_count
            .checked_add(self.filter_count)
            .unwrap_or(usize::MAX);
        if self.row_count == 0
            || self.output_count == 0
            || self.input_count.saturating_add(self.instruction_count)
                > super::RESIDENT_BOOLEAN_PROGRAM_MAX_REGISTERS
            || self.list_input_width > super::RESIDENT_BOOLEAN_PROGRAM_MAX_LIST_INPUT_VALUES
            || inputs.dtype() != DType::U32
            || code.dtype() != DType::U32
            || output_and_filters.dtype() != DType::U32
            || !inputs_layout.is_contiguous()
            || !code_layout.is_contiguous()
            || !output_and_filters_layout.is_contiguous()
            || inputs_layout.dims().len() != 1
            || code_layout.dims().len() != 1
            || output_and_filters_layout.dims().len() != 1
            || inputs_layout.shape().elem_count() != self.input_len
            || self.input_len != expected_input_len
            || self.input_stride != expected_input_stride
            || code_layout.shape().elem_count() != self.code_len
            || output_and_filters_layout.shape().elem_count() != self.output_register_len
            || self.input_len == 0
            || self.code_len != expected_code_len.max(1)
            || self.output_register_len != expected_register_len
            || output_len == 0
        {
            return Err(candle_core::Error::Msg(
                "Metal Boolean scalar tensor contract is invalid".to_owned(),
            ));
        }
        let arguments = MetalBooleanProgramArgs {
            row_count: u64::try_from(self.row_count).map_err(|_| {
                candle_core::Error::Msg("Metal Boolean scalar row count exceeds u64".to_owned())
            })?,
            input_count: u32::try_from(self.input_count).map_err(|_| {
                candle_core::Error::Msg("Metal Boolean scalar input count exceeds u32".to_owned())
            })?,
            list_input_count: u32::try_from(self.list_input_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar list input count exceeds u32".to_owned(),
                )
            })?,
            list_input_width: u32::try_from(self.list_input_width).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar list input width exceeds u32".to_owned(),
                )
            })?,
            input_stride: u32::try_from(self.input_stride).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar input row width exceeds u32".to_owned(),
                )
            })?,
            instruction_count: u32::try_from(self.instruction_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar instruction count exceeds u32".to_owned(),
                )
            })?,
            output_count: u32::try_from(self.output_count).map_err(|_| {
                candle_core::Error::Msg("Metal Boolean scalar output count exceeds u32".to_owned())
            })?,
            filter_count: u32::try_from(self.filter_count).map_err(|_| {
                candle_core::Error::Msg("Metal Boolean scalar filter count exceeds u32".to_owned())
            })?,
            scalar_cell_count: u32::try_from(self.scalar_cell_count).map_err(|_| {
                candle_core::Error::Msg("Metal Boolean scalar cell count exceeds u32".to_owned())
            })?,
            map_entry_count: u32::try_from(self.map_entry_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar map entry count exceeds u32".to_owned(),
                )
            })?,
            scalar_list_entry_count: u32::try_from(self.scalar_list_entry_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar list entry count exceeds u32".to_owned(),
                )
            })?,
            scalar_predicate_count: u32::try_from(self.scalar_predicate_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar predicate count exceeds u32".to_owned(),
                )
            })?,
            scalar_expression_count: u32::try_from(self.scalar_expression_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar expression count exceeds u32".to_owned(),
                )
            })?,
            scalar_expression_instruction_count: u32::try_from(
                self.scalar_expression_instruction_count,
            )
            .map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar expression instruction count exceeds u32".to_owned(),
                )
            })?,
            reduction_count: u32::try_from(self.reduction_count).map_err(|_| {
                candle_core::Error::Msg(
                    "Metal Boolean scalar reduction count exceeds u32".to_owned(),
                )
            })?,
            reduction_register_count: u32::try_from(self.reduction_register_count).map_err(
                |_| {
                    candle_core::Error::Msg(
                        "Metal Boolean scalar reduction register count exceeds u32".to_owned(),
                    )
                },
            )?,
        };
        let device = inputs.device();
        let pipelines = metal_sort_pipelines(device)?;
        let output = device
            .new_buffer_builder()
            .with_size_for(output_len, DType::U8)
            .with_label("irongraph Boolean scalar output")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&pipelines.boolean_program);
        encoder.set_input_buffer(
            0,
            Some(inputs.buffer()),
            inputs_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(code.buffer()),
            code_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(output_and_filters.buffer()),
            output_and_filters_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(3, Some(&output), 0);
        encoder.set_bytes(4, &arguments);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: self.row_count.div_ceil(METAL_SORT_THREADS),
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), output_len, DType::U8),
            Shape::from(output_len),
        ))
    }
}

