#[derive(Clone, Debug)]
struct MetalResidentRowEvaluate {
    arguments: MetalResidentRowEvaluateArgs,
    property_storage_words: usize,
    node_string_offsets: Tensor,
    node_string_bytes: Tensor,
    edge_string_offsets: Tensor,
    edge_string_bytes: Tensor,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp2 for MetalResidentRowEvaluate {
    fn name(&self) -> &'static str {
        "irongraph-metal-resident-row-evaluate"
    }

    fn cpu_fwd(
        &self,
        _properties: &CpuStorage,
        _properties_layout: &Layout,
        _metadata: &CpuStorage,
        _metadata_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal resident row evaluation cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        properties: &MetalStorage,
        properties_layout: &Layout,
        metadata: &MetalStorage,
        metadata_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let args = self.arguments;
        let (node_offsets_storage, node_offsets_layout) =
            self.node_string_offsets.storage_and_layout();
        let Storage::Metal(node_offsets) = &*node_offsets_storage else {
            return Err(candle_core::Error::Msg(
                "row node-string offsets moved to a non-Metal device".to_owned(),
            ));
        };
        let (node_bytes_storage, node_bytes_layout) = self.node_string_bytes.storage_and_layout();
        let Storage::Metal(node_bytes) = &*node_bytes_storage else {
            return Err(candle_core::Error::Msg(
                "row node-string bytes moved to a non-Metal device".to_owned(),
            ));
        };
        let (edge_offsets_storage, edge_offsets_layout) =
            self.edge_string_offsets.storage_and_layout();
        let Storage::Metal(edge_offsets) = &*edge_offsets_storage else {
            return Err(candle_core::Error::Msg(
                "row edge-string offsets moved to a non-Metal device".to_owned(),
            ));
        };
        let (edge_bytes_storage, edge_bytes_layout) = self.edge_string_bytes.storage_and_layout();
        let Storage::Metal(edge_bytes) = &*edge_bytes_storage else {
            return Err(candle_core::Error::Msg(
                "row edge-string bytes moved to a non-Metal device".to_owned(),
            ));
        };
        let row_count = usize::try_from(args.row_count)
            .map_err(|_| candle_core::Error::Msg("Metal row count exceeds usize".into()))?;
        let instruction_count = args.instruction_count as usize;
        let property_load_count = args.property_load_count as usize;
        let fixed_property_words = row_count
            .checked_mul(property_load_count)
            .and_then(|words| words.checked_mul(2))
            .ok_or_else(|| candle_core::Error::Msg("Metal row property shape overflow".into()))?;
        let fixed_output_words = row_count
            .checked_mul(instruction_count)
            .and_then(|words| words.checked_mul(2))
            .and_then(|words| words.checked_add(1))
            .and_then(|words| words.checked_add(row_count))
            .ok_or_else(|| candle_core::Error::Msg("Metal row output shape overflow".into()))?;
        let output_words = usize::try_from(args.output_word_count)
            .map_err(|_| candle_core::Error::Msg("Metal row output exceeds usize".into()))?;
        let metadata_words = usize::try_from(args.metadata_word_count)
            .map_err(|_| candle_core::Error::Msg("Metal row metadata exceeds usize".into()))?;
        let property_words = usize::try_from(args.property_storage_words)
            .map_err(|_| candle_core::Error::Msg("Metal row properties exceed usize".into()))?;
        if properties.dtype() != DType::I64
            || metadata.dtype() != DType::I64
            || self.node_string_offsets.dtype() != DType::U32
            || self.edge_string_offsets.dtype() != DType::U32
            || (args.node_string_byte_count != 0 && self.node_string_bytes.dtype() != DType::U8)
            || (args.edge_string_byte_count != 0 && self.edge_string_bytes.dtype() != DType::U8)
            || !properties_layout.is_contiguous()
            || !metadata_layout.is_contiguous()
            || !node_offsets_layout.is_contiguous()
            || !node_bytes_layout.is_contiguous()
            || !edge_offsets_layout.is_contiguous()
            || !edge_bytes_layout.is_contiguous()
            || properties_layout.dims().len() != 1
            || metadata_layout.dims().len() != 1
            || node_offsets_layout.dims().len() != 1
            || node_bytes_layout.dims().len() != 1
            || edge_offsets_layout.dims().len() != 1
            || edge_bytes_layout.dims().len() != 1
            || node_offsets_layout.shape().elem_count() != args.node_string_entry_count as usize + 1
            || edge_offsets_layout.shape().elem_count() != args.edge_string_entry_count as usize + 1
            || (args.node_string_byte_count != 0
                && node_bytes_layout.shape().elem_count() != args.node_string_byte_count as usize)
            || (args.edge_string_byte_count != 0
                && edge_bytes_layout.shape().elem_count() != args.edge_string_byte_count as usize)
            || properties_layout.shape().elem_count() != self.property_storage_words
            || self.property_storage_words != property_words
            || property_words < fixed_property_words.max(1)
            || metadata_layout.shape().elem_count() != metadata_words
            || metadata_words < instruction_count.saturating_mul(METAL_ROW_INSTRUCTION_WORDS)
            || output_words < fixed_output_words
            || instruction_count == 0
            || instruction_count > super::RESIDENT_ROW_PROGRAM_MAX_REGISTERS
            || args.program_abi_version != METAL_ROW_PROGRAM_ABI_VERSION
            || args.reserved != 0
            || args.dispatch_base != 0
            || args.dispatch_count != 0
        {
            return Err(candle_core::Error::Msg(
                "Metal resident row evaluation tensor contract is invalid".to_owned(),
            ));
        }
        let device = properties.device();
        let pipelines = metal_sort_pipelines(device)?;
        let output = device
            .new_buffer_builder()
            .with_size_for(output_words, DType::I64)
            .with_label("irongraph resident row registers")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&pipelines.row_initialize);
        encoder.set_output_buffer(0, Some(&output), 0);
        encoder.set_bytes(1, &args);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        if row_count != 0 {
            encoder.set_compute_pipeline_state(&pipelines.row_evaluate);
            encoder.set_input_buffer(
                0,
                Some(properties.buffer()),
                properties_layout.start_offset() * DType::I64.size_in_bytes(),
            );
            encoder.set_input_buffer(
                1,
                Some(metadata.buffer()),
                metadata_layout.start_offset() * DType::I64.size_in_bytes(),
            );
            encoder.set_output_buffer(2, Some(&output), 0);
            encoder.set_input_buffer(
                4,
                Some(node_offsets.buffer()),
                node_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            encoder.set_input_buffer(
                5,
                Some(node_bytes.buffer()),
                node_bytes_layout.start_offset() * self.node_string_bytes.dtype().size_in_bytes(),
            );
            encoder.set_input_buffer(
                6,
                Some(edge_offsets.buffer()),
                edge_offsets_layout.start_offset() * DType::U32.size_in_bytes(),
            );
            encoder.set_input_buffer(
                7,
                Some(edge_bytes.buffer()),
                edge_bytes_layout.start_offset() * self.edge_string_bytes.dtype().size_in_bytes(),
            );
            for chunk in metal_logical_dispatch_chunks(args.row_count, METAL_SORT_THREADS)? {
                let mut dispatch_args = args;
                dispatch_args.dispatch_base = chunk.logical_base;
                dispatch_args.dispatch_count = chunk.logical_count;
                encoder.set_bytes(3, &dispatch_args);
                encoder.dispatch_thread_groups(
                    objc2_metal::MTLSize {
                        width: chunk.group_count,
                        height: 1,
                        depth: 1,
                    },
                    objc2_metal::MTLSize {
                        width: METAL_SORT_THREADS,
                        height: 1,
                        depth: 1,
                    },
                );
            }
            encoder.set_compute_pipeline_state(&pipelines.row_reduce_error);
            encoder.set_output_buffer(0, Some(&output), 0);
            encoder.set_bytes(1, &args);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: 1,
                    height: 1,
                    depth: 1,
                },
            );
        }
        Ok((
            MetalStorage::new(output, device.clone(), output_words, DType::I64),
            Shape::from(output_words),
        ))
    }
}

