#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Copy, Debug)]
struct MetalResidentRowFinalize {
    arguments: MetalResidentRowFinalizeArgs,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp3 for MetalResidentRowFinalize {
    fn name(&self) -> &'static str {
        "irongraph-metal-resident-row-finalize"
    }

    fn cpu_fwd(
        &self,
        _evaluated: &CpuStorage,
        _evaluated_layout: &Layout,
        _metadata: &CpuStorage,
        _metadata_layout: &Layout,
        _proof: &CpuStorage,
        _proof_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal resident row finalization cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        evaluated: &MetalStorage,
        evaluated_layout: &Layout,
        metadata: &MetalStorage,
        metadata_layout: &Layout,
        proof: &MetalStorage,
        proof_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        let args = self.arguments;
        let input_rows = usize::try_from(args.input_rows)
            .map_err(|_| candle_core::Error::Msg("Metal row input exceeds usize".into()))?;
        let output_rows = usize::try_from(args.output_rows)
            .map_err(|_| candle_core::Error::Msg("Metal row output exceeds usize".into()))?;
        let instruction_count = args.instruction_count as usize;
        let projection_count = args.projection_count as usize;
        let receipt_count = args.receipt_count as usize;
        let fixed_evaluated = input_rows
            .checked_mul(instruction_count)
            .and_then(|words| words.checked_mul(2))
            .and_then(|words| words.checked_add(1))
            .and_then(|words| words.checked_add(input_rows))
            .ok_or_else(|| candle_core::Error::Msg("Metal row register shape overflow".into()))?;
        let expected_evaluated = usize::try_from(args.evaluated_word_count).map_err(|_| {
            candle_core::Error::Msg("Metal row evaluated image exceeds usize".into())
        })?;
        let projection_words = usize::try_from(args.projection_word_count).map_err(|_| {
            candle_core::Error::Msg("Metal row projection packet exceeds usize".into())
        })?;
        let expected_output = METAL_ROW_PACKET_HEADER_WORDS
            .checked_add(output_rows)
            .and_then(|words| words.checked_add(projection_words))
            .and_then(|words| {
                receipt_count
                    .checked_mul(METAL_ROW_PACKET_RECEIPT_WORDS)
                    .and_then(|receipts| words.checked_add(receipts))
            })
            .ok_or_else(|| candle_core::Error::Msg("Metal row packet shape overflow".into()))?;
        let output_words = usize::try_from(args.output_word_count)
            .map_err(|_| candle_core::Error::Msg("Metal row packet exceeds usize".into()))?;
        let metadata_words = usize::try_from(args.metadata_word_count)
            .map_err(|_| candle_core::Error::Msg("Metal row metadata exceeds usize".into()))?;
        let proof_words = usize::try_from(args.proof_word_count)
            .map_err(|_| candle_core::Error::Msg("Metal row proof exceeds usize".into()))?;
        let expected_proof_words = output_rows
            .max(1)
            .checked_mul(2)
            .and_then(|positions| METAL_ROW_PROOF_HEADER_WORDS.checked_add(positions))
            .ok_or_else(|| candle_core::Error::Msg("Metal row proof shape overflow".into()))?;
        if evaluated.dtype() != DType::I64
            || metadata.dtype() != DType::I64
            || proof.dtype() != DType::U32
            || !evaluated_layout.is_contiguous()
            || !metadata_layout.is_contiguous()
            || !proof_layout.is_contiguous()
            || evaluated_layout.dims().len() != 1
            || metadata_layout.dims().len() != 1
            || proof_layout.dims().len() != 1
            || evaluated_layout.shape().elem_count() != expected_evaluated
            || expected_evaluated < fixed_evaluated
            || metadata_layout.shape().elem_count() != metadata_words
            || proof_layout.shape().elem_count() != expected_proof_words
            || proof_words != expected_proof_words
            || output_words != expected_output
            || projection_words
                < projection_count.saturating_mul(METAL_ROW_PACKET_PROJECTION_HEADER_WORDS)
            || receipt_count != instruction_count.saturating_add(1)
            || args.projection_metadata_offset as usize
                != instruction_count.saturating_mul(METAL_ROW_INSTRUCTION_WORDS)
            || args.receipt_metadata_offset as usize
                != (args.projection_metadata_offset as usize).saturating_add(projection_count)
            || args.proof_sort_key_count as usize > super::RESIDENT_ROW_PROGRAM_MAX_SORT_KEYS
            || args.dispatch_base != 0
            || args.dispatch_count != 0
        {
            return Err(candle_core::Error::Msg(
                "Metal resident row finalization tensor contract is invalid".to_owned(),
            ));
        }
        let device = evaluated.device();
        let output = device
            .new_buffer_builder()
            .with_size_for(output_words, DType::I64)
            .with_label("irongraph resident row result and receipts")
            .build()?;
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&metal_sort_pipelines(device)?.row_finalize);
        encoder.set_input_buffer(
            0,
            Some(evaluated.buffer()),
            evaluated_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(metadata.buffer()),
            metadata_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(proof.buffer()),
            proof_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(3, Some(&output), 0);
        for chunk in metal_logical_dispatch_chunks(args.output_word_count, METAL_SORT_THREADS)? {
            let mut dispatch_args = args;
            dispatch_args.dispatch_base = chunk.logical_base;
            dispatch_args.dispatch_count = chunk.logical_count;
            encoder.set_bytes(4, &dispatch_args);
            encoder.dispatch_thread_groups(
                objc2_metal::MTLSize {
                    width: chunk.group_count,
                    height: 1,
                    depth: 1,
                },
                objc2_metal::MTLSize {
                    width: METAL_SORT_THREADS,
                    height: 1,
                    depth: 1,
                },
            );
        }
        Ok((
            MetalStorage::new(output, device.clone(), output_words, DType::I64),
            Shape::from(output_words),
        ))
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[repr(C)]
#[derive(Clone, Copy, Debug)]
struct MetalStableRadixArgs {
    row_count: u64,
    block_count: u64,
    digit_pass: u32,
    descending: u32,
    nullable: u32,
    nulls_first: u32,
    value_type: u32,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
