#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp3 for MetalIntegerGroupSummary {
    fn name(&self) -> &'static str {
        "irongraph-metal-integer-group-summary"
    }

    fn cpu_fwd(
        &self,
        _values: &CpuStorage,
        _values_layout: &Layout,
        _validity: &CpuStorage,
        _validity_layout: &Layout,
        _group_starts: &CpuStorage,
        _group_starts_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal integer group summary cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        values: &MetalStorage,
        values_layout: &Layout,
        validity: &MetalStorage,
        validity_layout: &Layout,
        group_starts: &MetalStorage,
        group_starts_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        if self.row_count == 0
            || self.group_count == 0
            || values.dtype() != DType::I64
            || validity.dtype() != DType::U8
            || group_starts.dtype() != DType::U32
            || !values_layout.is_contiguous()
            || !validity_layout.is_contiguous()
            || !group_starts_layout.is_contiguous()
            || values_layout.dims().len() != 1
            || validity_layout.dims().len() != 1
            || group_starts_layout.dims().len() != 1
            || values_layout.shape().elem_count() != self.row_count
            || validity_layout.shape().elem_count() != self.row_count
            || group_starts_layout.shape().elem_count() != self.group_count
        {
            return Err(candle_core::Error::Msg(
                "Metal integer group summary tensor contract is invalid".to_owned(),
            ));
        }
        let output_count = self.group_count.checked_mul(4).ok_or_else(|| {
            candle_core::Error::Msg("Metal integer group summary size overflow".to_owned())
        })?;
        let device = values.device();
        let output = device
            .new_buffer_builder()
            .with_size_for(output_count, DType::I64)
            .with_label("irongraph integer group summaries")
            .build()?;
        let arguments = MetalIntegerGroupSummaryArgs {
            row_count: self.row_count as u64,
            group_count: self.group_count as u64,
        };
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&metal_sort_pipelines(device)?.integer_group_summary);
        encoder.set_input_buffer(
            0,
            Some(values.buffer()),
            values_layout.start_offset() * DType::I64.size_in_bytes(),
        );
        encoder.set_input_buffer(
            1,
            Some(validity.buffer()),
            validity_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(
            2,
            Some(group_starts.buffer()),
            group_starts_layout.start_offset() * DType::U32.size_in_bytes(),
        );
        encoder.set_output_buffer(3, Some(&output), 0);
        encoder.set_bytes(4, &arguments);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: self.group_count,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
        Ok((
            MetalStorage::new(output, device.clone(), output_count, DType::I64),
            Shape::from(output_count),
        ))
    }
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[derive(Clone, Copy, Debug)]
struct MetalStableSelection {
    row_count: usize,
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
impl CustomOp1 for MetalStableSelection {
    fn name(&self) -> &'static str {
        "irongraph-metal-stable-selection"
    }

    fn cpu_fwd(
        &self,
        _mask: &CpuStorage,
        _mask_layout: &Layout,
    ) -> candle_core::Result<(CpuStorage, Shape)> {
        Err(candle_core::Error::Msg(
            "Metal stable selection cannot execute on CPU".to_owned(),
        ))
    }

    fn metal_fwd(
        &self,
        mask: &MetalStorage,
        mask_layout: &Layout,
    ) -> candle_core::Result<(MetalStorage, Shape)> {
        if self.row_count == 0
            || self.row_count > u32::MAX as usize
            || mask.dtype() != DType::U8
            || !mask_layout.is_contiguous()
            || mask_layout.dims().len() != 1
            || mask_layout.shape().elem_count() != self.row_count
        {
            return Err(candle_core::Error::Msg(
                "Metal stable selection tensor contract is invalid".to_owned(),
            ));
        }
        let block_count = self.row_count.div_ceil(METAL_SORT_THREADS);
        let output_count = self.row_count.checked_add(1).ok_or_else(|| {
            candle_core::Error::Msg("Metal stable selection output shape overflow".to_owned())
        })?;
        let device = mask.device();
        let pipelines = metal_sort_pipelines(device)?;
        let output = device
            .new_buffer_builder()
            .with_size_for(output_count, DType::U32)
            .with_label("irongraph stable selected rows")
            .build()?;
        let local_prefix = device
            .new_buffer_builder()
            .with_size_for(self.row_count, DType::U32)
            .with_label("irongraph stable selection local prefix")
            .build()?;
        let block_offsets = device
            .new_buffer_builder()
            .with_size_for(block_count, DType::U32)
            .with_label("irongraph stable selection block offsets")
            .build()?;
        let arguments = MetalStableSelectionArgs {
            row_count: self.row_count as u64,
            block_count: block_count as u64,
        };
        let encoder = device.command_encoder()?;
        let encoder = encoder.as_ref();
        let groups = objc2_metal::MTLSize {
            width: block_count,
            height: 1,
            depth: 1,
        };
        let threads = objc2_metal::MTLSize {
            width: METAL_SORT_THREADS,
            height: 1,
            depth: 1,
        };

        encoder.set_compute_pipeline_state(&pipelines.selection_local_scan);
        encoder.set_input_buffer(
            0,
            Some(mask.buffer()),
            mask_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_output_buffer(1, Some(&local_prefix), 0);
        encoder.set_output_buffer(2, Some(&block_offsets), 0);
        encoder.set_bytes(3, &arguments);
        encoder.dispatch_thread_groups(groups, threads);
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.selection_block_offsets);
        encoder.set_output_buffer(0, Some(&block_offsets), 0);
        encoder.set_output_buffer(1, Some(&output), 0);
        encoder.set_bytes(2, &arguments);
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: 1,
                height: 1,
                depth: 1,
            },
        );
        encoder.insert_memory_barrier();

        encoder.set_compute_pipeline_state(&pipelines.selection_scatter);
        encoder.set_input_buffer(
            0,
            Some(mask.buffer()),
            mask_layout.start_offset() * DType::U8.size_in_bytes(),
        );
        encoder.set_input_buffer(1, Some(&local_prefix), 0);
        encoder.set_input_buffer(2, Some(&block_offsets), 0);
        encoder.set_output_buffer(3, Some(&output), 0);
        encoder.set_bytes(4, &arguments);
        encoder.dispatch_thread_groups(groups, threads);

        Ok((
            MetalStorage::new(output, device.clone(), output_count, DType::U32),
            Shape::from(output_count),
        ))
    }
}

