/// Quantifier evaluation is a sizeable interpreter and is intentionally compiled only when the
/// sealed command is selected. The default operator library sees the section behind a false
/// preprocessor guard, so unrelated GPU queries do not pay its pipeline cost.
#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_variable_path_contract_defines() -> String {
    format!(
        "#define IG_QUANTIFIER_VARIABLE_PATH_ABI {METAL_VARIABLE_PATH_ABI_WORD:#018x}ul\n\
         #define IG_QUANTIFIER_VARIABLE_PATH_OUTPUT_HEADER_WORDS {METAL_VARIABLE_PATH_OUTPUT_HEADER_WORDS}ul\n\
         #define IG_QUANTIFIER_VARIABLE_PATH_RECEIPT_WORDS {METAL_VARIABLE_PATH_RECEIPT_WORDS}ul"
    )
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_library(
    device: &candle_core::MetalDevice,
) -> candle_core::Result<candle_metal_kernels::metal::Library> {
    static LIBRARY: OnceLock<candle_metal_kernels::metal::Library> = OnceLock::new();
    static INITIALIZE: Mutex<()> = Mutex::new(());
    if let Some(library) = LIBRARY.get() {
        return Ok(library.clone());
    }
    let _initialize = INITIALIZE
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if let Some(library) = LIBRARY.get() {
        return Ok(library.clone());
    }
    const BEGIN: &str = "// IG_QUANTIFIER_PROGRAM_SOURCE_BEGIN";
    const END: &str = "// IG_QUANTIFIER_PROGRAM_SOURCE_END";
    let source = include_str!("../../../kernels/metal/operators.metal");
    let (_, source) = source.split_once(BEGIN).ok_or_else(|| {
        candle_core::Error::Msg("Metal quantifier source start marker is missing".to_owned())
    })?;
    let (source, _) = source.split_once(END).ok_or_else(|| {
        candle_core::Error::Msg("Metal quantifier source end marker is missing".to_owned())
    })?;
    let variable_path_contract = metal_quantifier_variable_path_contract_defines();
    let source = format!(
        "#include <metal_stdlib>\nusing namespace metal;\n#define IG_INCLUDE_QUANTIFIER_PROGRAM 1\n{variable_path_contract}\n{source}"
    );
    let library = device
        .metal_device()
        .new_library_with_source(&source, None)
        .map_err(|error| {
            candle_core::Error::Msg(format!("compiling Metal quantifier kernel failed: {error}"))
        })?;
    let _ = LIBRARY.set(library.clone());
    Ok(LIBRARY.get().cloned().unwrap_or(library))
}

