#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_quantifier_program_pipelines(
    device: &candle_core::MetalDevice,
) -> candle_core::Result<MetalQuantifierProgramPipelines> {
    static PIPELINES: OnceLock<MetalQuantifierProgramPipelines> = OnceLock::new();
    if let Some(pipelines) = PIPELINES.get() {
        return Ok(pipelines.clone());
    }
    let library = metal_quantifier_library(device)?;
    let pipeline = |name: &str| -> candle_core::Result<_> {
        let function = library.get_function(name, None).map_err(|error| {
            candle_core::Error::Msg(format!(
                "loading Metal quantifier kernel {name} failed: {error}"
            ))
        })?;
        let raw = device
            .metal_device()
            .as_ref()
            .newComputePipelineStateWithFunction_error(function.as_ref())
            .map_err(|error| {
                candle_core::Error::Msg(format!(
                    "creating Metal quantifier pipeline {name} failed: {error:?}"
                ))
            })?;
        Ok(candle_metal_kernels::metal::ComputePipeline::new(raw))
    };
    let pipelines = MetalQuantifierProgramPipelines {
        clear: pipeline("ig_quantifier_clear")?,
        initialize: pipeline("ig_quantifier_initialize")?,
        range_source: pipeline("ig_quantifier_range_source")?,
        project: pipeline("ig_quantifier_project_parallel")?,
        unwind_evaluate: pipeline("ig_quantifier_unwind_evaluate")?,
        unwind_prefix_step: pipeline("ig_quantifier_unwind_prefix_step")?,
        unwind_prefix_finalize: pipeline("ig_quantifier_unwind_prefix_finalize")?,
        unwind_prefix_exclusive: pipeline("ig_quantifier_unwind_prefix_exclusive")?,
        unwind_scatter: pipeline("ig_quantifier_unwind_scatter")?,
        unwind_finalize: pipeline("ig_quantifier_unwind_finalize")?,
        filter_evaluate: pipeline("ig_quantifier_filter_evaluate")?,
        filter_prefix: pipeline("ig_quantifier_filter_prefix")?,
        filter_compact: pipeline("ig_quantifier_filter_compact")?,
        filter_finalize: pipeline("ig_quantifier_filter_finalize")?,
        group: pipeline("ig_quantifier_group_serial")?,
        publish: pipeline("ig_quantifier_publish")?,
        bound_value_clear: pipeline("ig_quantifier_bound_value_clear")?,
        bound_value_validate_group_layout: pipeline(
            "ig_quantifier_bound_value_validate_group_layout",
        )?,
        bound_value_validate_packet_header: pipeline(
            "ig_quantifier_bound_value_validate_packet_header",
        )?,
        bound_value_validate_packet_arenas: pipeline(
            "ig_quantifier_bound_value_validate_packet_arenas",
        )?,
        bound_value_validate_root_bounds: pipeline(
            "ig_quantifier_bound_value_validate_root_bounds",
        )?,
        bound_value_validate_columns: pipeline("ig_quantifier_bound_value_validate_columns")?,
        bound_value_build_subtrees: pipeline("ig_quantifier_bound_value_build_subtrees")?,
        bound_value_validate_maps: pipeline("ig_quantifier_bound_value_validate_maps")?,
        bound_value_validate_arenas: pipeline("ig_quantifier_bound_value_validate_arenas")?,
        bound_value_validate_roots: pipeline("ig_quantifier_bound_value_validate_roots")?,
        bound_value_validate_selected: pipeline("ig_quantifier_bound_value_validate_selected")?,
        bound_value_begin: pipeline("ig_quantifier_bound_value_begin_step")?,
        bound_value_probe: pipeline("ig_quantifier_bound_value_probe")?,
        bound_value_compare: pipeline("ig_quantifier_bound_value_compare_one")?,
    };
    let _ = PIPELINES.set(pipelines.clone());
    Ok(PIPELINES.get().cloned().unwrap_or(pipelines))
}

