#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
pub fn prepare_metal_sort_kernels(device: &Device) -> Result<()> {
    let Device::Metal(device) = device else {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal sort kernels require a Metal device",
        ));
    };
    metal_sort_pipelines(device).map_err(candle_error)?;
    Ok(())
}

fn checked_u32(value: usize, name: &str) -> Result<u32> {
    u32::try_from(value).map_err(|_| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            format!("{name} size exceeds u32"),
        )
    })
}

struct MetalSharedAllocation {
    buffer: Arc<MetalBuffer>,
}

// SAFETY: the retained Metal buffer is immutable while canonical graph views exist; its shared
// storage address and byte length remain stable until the final Arc is dropped.
#[allow(unsafe_code)]
unsafe impl crate::graph::SharedAllocation for MetalSharedAllocation {
    fn base_ptr(&self) -> *const u8 {
        self.buffer.contents().cast_const()
    }

    fn byte_len(&self) -> usize {
        self.buffer.length()
    }
}

fn shared_flat_from_metal_buffer<T>(
    buffer: Arc<MetalBuffer>,
    len: usize,
) -> std::result::Result<crate::graph::SharedFlat<T>, &'static str> {
    if buffer.as_ref().as_ref().storageMode() != MTLStorageMode::Shared {
        return Err("canonical Metal allocation is not CPU/GPU shared storage");
    }
    let allocation: Arc<dyn crate::graph::SharedAllocation> =
        Arc::new(MetalSharedAllocation { buffer });
    crate::graph::SharedFlat::new(allocation, 0, len)
}

struct TensorUpload<'a> {
    device: &'a Device,
    tensors: Vec<Tensor>,
    allocated_bytes: usize,
}

impl<'a> TensorUpload<'a> {
    fn new(device: &'a Device) -> Self {
        Self {
            device,
            tensors: Vec::new(),
            allocated_bytes: 0,
        }
    }

    fn optional<T: WithDType>(&mut self, values: &[T]) -> Result<Option<Tensor>> {
        if values.is_empty() {
            return Ok(None);
        }
        let tensor = Tensor::from_slice(values, values.len(), self.device).map_err(candle_error)?;
        self.record_tensor(tensor)
    }

    /// On Metal, allocates one StorageModeShared buffer and returns both its Candle tensor and a
    /// typed immutable CPU view retaining the exact same MTLBuffer. Other backends return `None`
    /// and continue through their ordinary upload path.
    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn metal_shared<T: Send + Sync + 'static>(
        &mut self,
        values: &[T],
        dtype: DType,
    ) -> Result<Option<(Option<Tensor>, crate::graph::SharedFlat<T>)>> {
        let Device::Metal(device) = self.device else {
            return Ok(None);
        };
        if values.is_empty() {
            return Ok(Some((None, crate::graph::SharedFlat::empty())));
        }
        if size_of::<T>() != dtype.size_in_bytes() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "shared Metal column width does not match its tensor dtype",
            ));
        }
        let buffer = device
            .new_buffer_builder()
            .with_data(values)
            .with_label("irongraph shared canonical column")
            .build()
            .map_err(candle_error)?;
        let shared = shared_flat_from_metal_buffer(buffer.clone(), values.len())
            .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
        let storage = Storage::Metal(MetalStorage::new(
            buffer,
            device.clone(),
            values.len(),
            dtype,
        ));
        let tensor = Tensor::from_storage(storage, values.len(), BackpropOp::none(), false);
        self.allocated_bytes = self
            .allocated_bytes
            .saturating_add(values.len().saturating_mul(size_of::<T>()));
        Ok(Some((Some(tensor), shared)))
    }

    /// Allocates a shared column with unused tail capacity while exposing only initialized rows
    /// through both the tensor and canonical host view. Append publication may fill that tail and
    /// create a longer tensor view over the same allocation; pinned older generations retain their
    /// shorter logical shape and therefore cannot observe the appended rows.
    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    #[allow(unsafe_code)]
    fn metal_shared_reserved<T: Copy + Send + Sync + 'static>(
        &mut self,
        values: &[T],
        capacity: usize,
        dtype: DType,
        label: &str,
    ) -> Result<Option<(Option<Tensor>, crate::graph::SharedFlat<T>)>> {
        let Device::Metal(device) = self.device else {
            return Ok(None);
        };
        if values.is_empty() {
            return Ok(Some((None, crate::graph::SharedFlat::empty())));
        }
        if capacity < values.len() || size_of::<T>() != dtype.size_in_bytes() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "reserved shared Metal column shape is invalid",
            ));
        }
        let byte_capacity = capacity.checked_mul(size_of::<T>()).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "reserved shared Metal column capacity overflow",
            )
        })?;
        let buffer = device
            .new_buffer_builder()
            .with_size(byte_capacity)
            .with_label(label)
            .build()
            .map_err(candle_error)?;
        // SAFETY: the shared buffer owns `byte_capacity` writable bytes, `values` is initialized,
        // non-overlapping host memory, and the checked capacity covers the copied prefix.
        unsafe {
            std::ptr::copy_nonoverlapping(
                values.as_ptr().cast::<u8>(),
                buffer.contents().cast::<u8>(),
                values.len() * size_of::<T>(),
            );
        }
        let shared = shared_flat_from_metal_buffer(buffer.clone(), values.len())
            .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
        let storage = Storage::Metal(MetalStorage::new(
            buffer,
            device.clone(),
            values.len(),
            dtype,
        ));
        let tensor = Tensor::from_storage(storage, values.len(), BackpropOp::none(), false);
        self.allocated_bytes = self.allocated_bytes.saturating_add(byte_capacity);
        Ok(Some((Some(tensor), shared)))
    }

    /// Allocates a device-written shared column with geometric tail capacity while keeping both
    /// canonical host access and the returned tensor bounded to the initialized logical prefix.
    /// The append kernel writes only `len` rows; later generations may extend into the unreachable
    /// tail without changing what an older pinned generation can address.
    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn metal_shared_uninitialized_reserved<T: Send + Sync + 'static>(
        &mut self,
        len: usize,
        capacity: usize,
        dtype: DType,
        label: &str,
    ) -> Result<(
        Option<Tensor>,
        crate::graph::SharedFlat<T>,
        Option<Arc<MetalBuffer>>,
    )> {
        let Device::Metal(device) = self.device else {
            return Err(Error::internal(
                "reserved device-generated allocation requested outside Metal",
            ));
        };
        if len == 0 || capacity < len || size_of::<T>() != dtype.size_in_bytes() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "reserved device-generated shared column shape is invalid",
            ));
        }
        let byte_capacity = capacity.checked_mul(size_of::<T>()).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "reserved device-generated shared column capacity overflow",
            )
        })?;
        let buffer = device
            .new_buffer_builder()
            .with_size(byte_capacity)
            .with_label(label)
            .build()
            .map_err(candle_error)?;
        let shared = shared_flat_from_metal_buffer(buffer.clone(), len)
            .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
        let storage = Storage::Metal(MetalStorage::new(
            buffer.clone(),
            device.clone(),
            len,
            dtype,
        ));
        let tensor = Tensor::from_storage(storage, len, BackpropOp::none(), false);
        self.allocated_bytes = self.allocated_bytes.saturating_add(byte_capacity);
        Ok((Some(tensor), shared, Some(buffer)))
    }

    #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
    fn metal_shared<T: Send + Sync + 'static>(
        &mut self,
        _values: &[T],
        _dtype: DType,
    ) -> Result<Option<(Option<Tensor>, crate::graph::SharedFlat<T>)>> {
        Ok(None)
    }

    #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
    fn metal_shared_reserved<T: Copy + Send + Sync + 'static>(
        &mut self,
        _values: &[T],
        _capacity: usize,
        _dtype: DType,
        _label: &str,
    ) -> Result<Option<(Option<Tensor>, crate::graph::SharedFlat<T>)>> {
        Ok(None)
    }

    fn optional_iter<T: WithDType>(
        &mut self,
        values: impl IntoIterator<Item = T>,
    ) -> Result<Option<Tensor>> {
        let mut values = values.into_iter().peekable();
        if values.peek().is_none() {
            return Ok(None);
        }
        let tensor = Tensor::from_iter(values, self.device).map_err(candle_error)?;
        self.record_tensor(tensor)
    }

    #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
    fn is_metal(&self) -> bool {
        matches!(self.device, Device::Metal(_))
    }

    #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
    fn is_metal(&self) -> bool {
        false
    }

    fn record_tensor(&mut self, tensor: Tensor) -> Result<Option<Tensor>> {
        self.allocated_bytes = self.allocated_bytes.saturating_add(
            tensor
                .elem_count()
                .saturating_mul(tensor.dtype().size_in_bytes()),
        );
        self.tensors.push(tensor.clone());
        Ok(Some(tensor))
    }

    fn required<T: WithDType>(&mut self, values: &[T]) -> Result<Tensor> {
        self.optional(values)?.ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "required resident tensor cannot be empty",
            )
        })
    }

    fn u64_bits(&mut self, values: impl IntoIterator<Item = u64>) -> Result<Option<Tensor>> {
        self.optional(
            &values
                .into_iter()
                .map(|value| value as i64)
                .collect::<Vec<_>>(),
        )
    }

    fn u64_order_keys(&mut self, values: impl IntoIterator<Item = u64>) -> Result<Option<Tensor>> {
        self.optional(
            &values
                .into_iter()
                .map(|value| (value ^ (1_u64 << 63)) as i64)
                .collect::<Vec<_>>(),
        )
    }

    fn f64_bits(&mut self, values: impl IntoIterator<Item = f64>) -> Result<Option<Tensor>> {
        self.u64_bits(values.into_iter().map(f64::to_bits))
    }
}

fn ensure_tensor_capacity(
    tensor: &mut Option<Tensor>,
    capacity: usize,
    dtype: DType,
    device: &Device,
) -> Result<()> {
    match tensor {
        Some(current) => ensure_required_capacity(current, capacity, dtype, device),
        None if capacity == 0 => Ok(()),
        None => {
            *tensor = Some(Tensor::zeros(capacity, dtype, device).map_err(candle_error)?);
            Ok(())
        }
    }
}

fn copy_optional_tensor(tensor: &mut Option<Tensor>) -> Result<()> {
    if let Some(current) = tensor {
        *current = current.copy().map_err(candle_error)?;
    }
    Ok(())
}

/// Reconstructs the compact dictionary only while applying a non-shared device delta. This is
/// mutation application, not query evaluation: the query path always compares the canonical
/// device bytes directly. Keeping dictionary IDs append-only preserves every existing property
/// value tensor when a new string first appears in a delta.
fn resident_string_dictionary_entries(dictionary: &StringDictionary) -> Result<Vec<String>> {
    let offsets = dictionary.offsets.to_vec1::<u32>().map_err(candle_error)?;
    let bytes = dictionary
        .bytes
        .as_ref()
        .map(|bytes| bytes.to_vec1::<u8>().map_err(candle_error))
        .transpose()?
        .unwrap_or_default();
    if offsets.first().copied() != Some(0)
        || offsets.last().copied().map(|offset| offset as usize) != Some(bytes.len())
        || offsets.windows(2).any(|pair| pair[0] > pair[1])
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident string dictionary has invalid byte offsets",
        ));
    }
    offsets
        .windows(2)
        .map(|pair| {
            let start = pair[0] as usize;
            let end = pair[1] as usize;
            std::str::from_utf8(&bytes[start..end])
                .map(str::to_owned)
                .map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident string dictionary contains invalid UTF-8",
                    )
                })
        })
        .collect()
}

/// The decoded dictionary, built once and reused while it still describes the resident tensors.
///
/// Validated by entry count rather than trusted. The dictionary is append-only and the only
/// in-place mutator is [`replace_resident_string_dictionary`], which always grows it and republishes
/// this view, so a matching count cannot be describing different content. A mismatch — or a
/// dictionary that arrived by wholesale assignment — falls back to a full decode, which is exactly
/// the old behaviour and never stale.
fn resident_string_dictionary_host(
    dictionary: &mut StringDictionary,
) -> Result<Arc<HostStringDictionary>> {
    let entry_count = dictionary.offsets.elem_count().saturating_sub(1);
    if let Some(cached) = dictionary.host.as_ref()
        && cached.entries.len() == entry_count
    {
        return Ok(Arc::clone(cached));
    }
    let entries = resident_string_dictionary_entries(dictionary)?;
    let mut ids = BTreeMap::new();
    for (position, entry) in entries.iter().enumerate() {
        let id = checked_u32(position, "resident string dictionary ID")?;
        ids.insert(entry.clone(), id);
    }
    let built = Arc::new(HostStringDictionary { entries, ids });
    dictionary.host = Some(Arc::clone(&built));
    Ok(built)
}

/// Resolves only the dictionary IDs a result actually names.
///
/// The read path was calling [`resident_string_dictionary_entries`], which materialises a
/// `Vec<String>` of the **whole** dictionary — every entry allocated and UTF-8 validated — in order
/// to look up a handful of row values. That is O(distinct strings in the project) per query that
/// returns a STRING property, and a mailbox is nothing but high-cardinality strings: message ids,
/// addresses, subjects. It got slower as the graph grew, on a path whose cost should depend only on
/// the rows returned.
///
/// This reads the offsets once, then transfers only the byte span the wanted IDs actually cover and
/// allocates only the strings asked for. An empty request touches the byte tensor not at all, which
/// is the common case for a column that is entirely NULL over the returned rows.
fn resident_string_dictionary_lookup(
    dictionary: &StringDictionary,
    wanted: &BTreeSet<u32>,
) -> Result<BTreeMap<u32, String>> {
    if wanted.is_empty() {
        return Ok(BTreeMap::new());
    }
    let offsets = dictionary.offsets.to_vec1::<u32>().map_err(candle_error)?;
    let entry_count = offsets.len().saturating_sub(1);
    let bounds = |id: u32| -> Result<(usize, usize)> {
        let index = id as usize;
        if index >= entry_count {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident STRING property output names a foreign dictionary ID",
            ));
        }
        let start = offsets[index] as usize;
        let end = offsets[index + 1] as usize;
        if end < start {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident string dictionary has invalid byte offsets",
            ));
        }
        Ok((start, end))
    };

    // One contiguous transfer covering every wanted entry, rather than one readback per ID: each
    // readback is a Metal command buffer, so per-ID transfers would trade an O(N) host allocation
    // for O(rows) device round-trips and lose.
    let mut span_start = usize::MAX;
    let mut span_end = 0_usize;
    for id in wanted {
        let (start, end) = bounds(*id)?;
        span_start = span_start.min(start);
        span_end = span_end.max(end);
    }
    let span_len = span_end.saturating_sub(span_start);
    let span = match (&dictionary.bytes, span_len) {
        (_, 0) => Vec::new(),
        (Some(bytes), _) => bytes
            .narrow(0, span_start, span_len)
            .and_then(|slice| slice.contiguous())
            .and_then(|slice| slice.to_vec1::<u8>())
            .map_err(candle_error)?,
        (None, _) => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident string dictionary has offsets but no bytes",
            ));
        }
    };

    let mut resolved = BTreeMap::new();
    for id in wanted {
        let (start, end) = bounds(*id)?;
        let slice = span
            .get(start - span_start..end - span_start)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident string dictionary entry lies outside its own byte span",
                )
            })?;
        let value = std::str::from_utf8(slice).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident string dictionary contains invalid UTF-8",
            )
        })?;
        resolved.insert(*id, value.to_owned());
    }
    Ok(resolved)
}

/// Builds the rebuildable device rank index for one canonical UTF-8 dictionary. The rank of an
/// ID is its position in exact byte-wise lexicographic order. IDs remain append-only storage
/// locators; this derived column is the only scalar key used by typed-row STRING ordering.
fn resident_string_dictionary_ranks(entries: &[String]) -> Result<Vec<u32>> {
    let mut ordered = (0..entries.len()).collect::<Vec<_>>();
    ordered.sort_unstable_by(|left, right| {
        entries[*left]
            .as_bytes()
            .cmp(entries[*right].as_bytes())
            .then_with(|| left.cmp(right))
    });
    let mut ranks = vec![0_u32; entries.len()];
    for (rank, id) in ordered.into_iter().enumerate() {
        ranks[id] = checked_u32(rank, "resident string dictionary rank")?;
    }
    Ok(ranks)
}

fn replace_resident_string_dictionary(
    dictionary: &mut StringDictionary,
    entries: &[String],
    device: &Device,
) -> Result<BTreeMap<String, u32>> {
    let mut offsets = Vec::with_capacity(entries.len().saturating_add(1));
    let mut bytes = Vec::new();
    let mut ids = BTreeMap::new();
    offsets.push(0_u32);
    let mut maximum_bytes = 0_usize;
    for (position, entry) in entries.iter().enumerate() {
        let id = checked_u32(position, "resident string dictionary ID")?;
        if ids.insert(entry.clone(), id).is_some() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident string dictionary contains a duplicate entry",
            ));
        }
        maximum_bytes = maximum_bytes.max(entry.len());
        bytes.extend_from_slice(entry.as_bytes());
        offsets.push(checked_u32(
            bytes.len(),
            "resident string dictionary bytes",
        )?);
    }
    // The caller already holds exactly the decoded form the delta path wants, so publish it
    // alongside the tensors rather than making the next delta decode it back off the device.
    dictionary.host = Some(Arc::new(HostStringDictionary {
        entries: entries.to_vec(),
        ids: ids.clone(),
    }));
    dictionary.offsets =
        Tensor::from_slice(&offsets, offsets.len(), device).map_err(candle_error)?;
    dictionary.bytes = if bytes.is_empty() {
        None
    } else {
        Some(Tensor::from_slice(&bytes, bytes.len(), device).map_err(candle_error)?)
    };
    let ranks = resident_string_dictionary_ranks(entries)?;
    dictionary.ranks = if ranks.is_empty() {
        None
    } else {
        Some(Tensor::from_slice(&ranks, ranks.len(), device).map_err(candle_error)?)
    };
    dictionary.maximum_bytes = maximum_bytes;
    Ok(ids)
}

fn scatter_rows(destination: &Tensor, rows: &[u32], values: &Tensor) -> Result<()> {
    if values.rank() != 1 || values.elem_count() != rows.len() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "sparse device row update has incompatible values",
        ));
    }
    for (source, destination_row) in rows.iter().copied().enumerate() {
        let destination_row = usize::try_from(destination_row).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "sparse device row exceeds usize",
            )
        })?;
        let value = values.narrow(0, source, 1).map_err(candle_error)?;
        destination
            .slice_set(&value, 0, destination_row)
            .map_err(candle_error)?;
    }
    Ok(())
}

/// The capacity a resident column is grown to when it must hold `capacity` elements.
///
/// **The one definition.** `ensure_required_capacity` allocates to it and
/// `planned_delta_staging_bytes` reserves for it. Two functions independently computing the same
/// capacity is how the estimate and the allocation drift apart, and that drift is exactly why a
/// bulk load could allocate past its own reservation and be killed rather than refused. Anything
/// that needs to know how large a column will become calls this.
const fn resident_growth_target(capacity: usize) -> usize {
    let target = match capacity.checked_next_power_of_two() {
        Some(target) => target,
        // Past the largest power of two the capacity itself is the only honest answer; the
        // allocation will fail on its own rather than being silently rounded to something smaller.
        None => capacity,
    };
    if target > 64 { target } else { 64 }
}

/// `bytes * numerator / denominator`, in u128 so a large resident cannot overflow the scaling.
fn scale_bytes(bytes: usize, numerator: usize, denominator: usize) -> usize {
    if denominator == 0 {
        return bytes;
    }
    let scaled = (bytes as u128)
        .saturating_mul(numerator as u128)
        .saturating_div(denominator as u128);
    usize::try_from(scaled).unwrap_or(usize::MAX)
}

fn ensure_required_capacity(
    tensor: &mut Tensor,
    capacity: usize,
    dtype: DType,
    device: &Device,
) -> Result<()> {
    if tensor.dtype() != dtype {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident tensor dtype changed during sparse apply",
        ));
    }
    if tensor.elem_count() >= capacity {
        return Ok(());
    }
    let growth_target = resident_growth_target(capacity);
    let padding =
        Tensor::zeros(growth_target - tensor.elem_count(), dtype, device).map_err(candle_error)?;
    *tensor = Tensor::cat(&[&*tensor, &padding], 0).map_err(candle_error)?;
    Ok(())
}

fn apply_integer_temporal_delta(
    columns: &mut BTreeMap<(u8, u64, PropertyId), IntegerTemporalColumn>,
    delta: &super::ResidentTemporalDelta,
    device: &Device,
) -> Result<()> {
    let Some(column) =
        columns.get_mut(&(delta.entity_kind as u8, delta.target, delta.sample.property))
    else {
        return Ok(());
    };
    let (value, validity) = match &delta.sample.value {
        ScalarValue::Integer(value) => (*value, 1_u8),
        ScalarValue::Null => (0_i64, 0_u8),
        _ => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "integer temporal column received a non-integer delta",
            ));
        }
    };
    append_resident_tensor(
        &mut column.entity_ids,
        Tensor::from_slice(&[u64_order_key(delta.sample.entity_id)], 1, device)
            .map_err(candle_error)?,
    )?;
    append_resident_tensor(
        &mut column.event_times_nanos,
        Tensor::from_slice(&[delta.sample.event_time_nanos], 1, device).map_err(candle_error)?,
    )?;
    append_resident_tensor(
        &mut column.sequence_indexes,
        Tensor::from_slice(&[u64_order_key(delta.sample.sequence_index)], 1, device)
            .map_err(candle_error)?,
    )?;
    append_resident_tensor(
        &mut column.values,
        Tensor::from_slice(&[value], 1, device).map_err(candle_error)?,
    )?;
    append_resident_tensor(
        &mut column.validity,
        Tensor::from_slice(&[validity], 1, device).map_err(candle_error)?,
    )?;
    column.rows = column.rows.checked_add(1).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident temporal row count overflow",
        )
    })?;
    let cancellation = CancellationToken::new();
    for pass in 0..3 {
        let key = match pass {
            0 => column.sequence_indexes.as_ref(),
            1 => column.event_times_nanos.as_ref(),
            _ => column.entity_ids.as_ref(),
        }
        .ok_or_else(|| Error::internal("resident temporal sort key is absent"))?
        .clone();
        let order = scalable_stable_argsort(&key, true, device, &cancellation)?;
        reorder_integer_temporal_column(column, &order)?;
    }
    Ok(())
}

fn append_resident_tensor(destination: &mut Option<Tensor>, value: Tensor) -> Result<()> {
    *destination = Some(match destination.as_ref() {
        Some(current) => Tensor::cat(&[current, &value], 0).map_err(candle_error)?,
        None => value,
    });
    Ok(())
}

const fn u64_order_key(value: u64) -> i64 {
    (value ^ (1_u64 << 63)) as i64
}

fn reorder_integer_temporal_column(
    column: &mut IntegerTemporalColumn,
    order: &Tensor,
) -> Result<()> {
    for tensor in [
        &mut column.entity_ids,
        &mut column.event_times_nanos,
        &mut column.sequence_indexes,
        &mut column.values,
        &mut column.validity,
    ] {
        let current = tensor
            .as_ref()
            .ok_or_else(|| Error::internal("resident temporal tensor is absent"))?;
        *tensor = Some(current.index_select(order, 0).map_err(candle_error)?);
    }
    Ok(())
}

fn patch_shared_vector_owner_mapping(
    current: &VectorColumn,
    backing: &SharedVectorBacking,
    owner_rows: &PersistentMap<u32>,
    remapped_rows: &BTreeSet<u32>,
    device: &Device,
) -> Result<(Option<Tensor>, Option<Tensor>, Option<Tensor>)> {
    let mut entity_ids = current.entity_ids.clone();
    let mut dense_rows = current.node_rows.clone();
    let mut backed = current.node_backed.clone();
    let rows = backing.entity_ids.len();
    if rows == current.rows && remapped_rows.is_empty() {
        return Ok((entity_ids, dense_rows, backed));
    }
    if rows < current.rows {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "vector owner rows cannot shrink in a sparse delta",
        ));
    }
    // Appending into unused capacity is invisible to the pinned generation's shorter view.
    // Updating an already visible owner requires a private copy of just the mapping lanes.
    if remapped_rows
        .iter()
        .any(|row| (*row as usize) < current.rows)
    {
        copy_optional_tensor(&mut dense_rows)?;
        copy_optional_tensor(&mut backed)?;
    }
    let capacity = rows.checked_next_power_of_two().unwrap_or(rows).max(64);
    ensure_tensor_capacity(&mut entity_ids, capacity, DType::I64, device)?;
    ensure_tensor_capacity(&mut dense_rows, capacity, DType::U32, device)?;
    ensure_tensor_capacity(&mut backed, capacity, DType::U8, device)?;
    let appended = (current.rows..rows)
        .map(|row| {
            u32::try_from(row).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "vector owner row exceeds u32",
                )
            })
        })
        .collect::<Result<Vec<_>>>()?;
    if !appended.is_empty() {
        let ids = appended
            .iter()
            .map(|row| {
                backing
                    .entity_ids
                    .get(*row as usize)
                    .copied()
                    .map(u64_order_key)
                    .ok_or_else(|| Error::internal("appended vector owner is absent"))
            })
            .collect::<Result<Vec<_>>>()?;
        scatter_rows(
            entity_ids
                .as_ref()
                .ok_or_else(|| Error::internal("vector owner IDs are absent"))?,
            &appended,
            &Tensor::from_slice(&ids, ids.len(), device).map_err(candle_error)?,
        )?;
    }
    let changed = appended
        .into_iter()
        .chain(remapped_rows.iter().copied())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let owners = changed
        .iter()
        .map(|row| {
            let id = backing
                .entity_ids
                .get(*row as usize)
                .copied()
                .ok_or_else(|| Error::internal("changed vector owner is absent"))?;
            Ok(stable_id_row(owner_rows, id).copied())
        })
        .collect::<Result<Vec<_>>>()?;
    let dense = owners
        .iter()
        .map(|row| row.unwrap_or(0))
        .collect::<Vec<_>>();
    let live = owners
        .iter()
        .map(|row| u8::from(row.is_some()))
        .collect::<Vec<_>>();
    scatter_rows(
        dense_rows
            .as_ref()
            .ok_or_else(|| Error::internal("vector owner rows are absent"))?,
        &changed,
        &Tensor::from_slice(&dense, dense.len(), device).map_err(candle_error)?,
    )?;
    scatter_rows(
        backed
            .as_ref()
            .ok_or_else(|| Error::internal("vector owner mask is absent"))?,
        &changed,
        &Tensor::from_slice(&live, live.len(), device).map_err(candle_error)?,
    )?;
    Ok((entity_ids, dense_rows, backed))
}

fn apply_shared_vector_mutation(
    backing: &mut SharedVectorBacking,
    rows: &mut PersistentMap<u32>,
    mutation: &ResolvedVectorMutation,
) -> Result<()> {
    let (property, entity, revision) = match mutation {
        ResolvedVectorMutation::Upsert {
            property,
            entity_id,
            revision,
            ..
        }
        | ResolvedVectorMutation::Remove {
            property,
            entity_id,
            revision,
        } => (*property, *entity_id, *revision),
    };
    if property != backing.property {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "shared vector mutation targets the wrong property",
        ));
    }
    let existing = stable_id_row(rows, entity).copied();
    let row = match (mutation, existing) {
        (ResolvedVectorMutation::Remove { .. }, None) => return Ok(()),
        (_, Some(row)) => row as usize,
        (ResolvedVectorMutation::Upsert { .. }, None) => {
            let row = backing.entity_ids.len();
            let encoded = u32::try_from(row).map_err(|_| {
                Error::new(ErrorCode::ResultBudgetExceeded, "vector row exceeds u32")
            })?;
            backing.entity_ids.push(entity);
            for _ in 0..backing.dimension {
                backing.values.push(0);
            }
            backing.versions.push(revision);
            backing.active.push(false);
            rows.insert_cow(stable_id_key(entity), encoded);
            row
        }
    };
    *backing
        .versions
        .get_mut(row)
        .ok_or_else(|| Error::internal("shared vector revision row disappeared"))? = revision;
    match mutation {
        ResolvedVectorMutation::Remove { .. } => {
            *backing
                .active
                .get_mut(row)
                .ok_or_else(|| Error::internal("shared vector active row disappeared"))? = false;
        }
        ResolvedVectorMutation::Upsert { coordinates, .. } => {
            if coordinates.len() != backing.dimension {
                return Err(Error::new(
                    ErrorCode::EmbeddingProfileMismatch,
                    "vector delta dimension differs from the resident profile",
                ));
            }
            let start = row.checked_mul(backing.dimension).ok_or_else(|| {
                Error::new(ErrorCode::ResultBudgetExceeded, "vector offset overflow")
            })?;
            for (offset, coordinate) in coordinates.iter().copied().enumerate() {
                *backing
                    .values
                    .get_mut(start + offset)
                    .ok_or_else(|| Error::internal("shared vector coordinate row disappeared"))? =
                    coordinate;
            }
            *backing
                .active
                .get_mut(row)
                .ok_or_else(|| Error::internal("shared vector active row disappeared"))? = true;
        }
    }
    Ok(())
}

fn shared_vector_squared_norm(
    backing: &SharedVectorBacking,
    mut offsets: std::ops::Range<usize>,
    dtype: EmbeddingDType,
) -> Result<f32> {
    offsets.try_fold(0.0_f32, |sum, offset| {
        let bits = backing.values.get(offset).copied().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "changed vector row is outside canonical coordinates",
            )
        })?;
        let value = match dtype {
            EmbeddingDType::F16 => f16::from_bits(bits).to_f32(),
            EmbeddingDType::Bf16 => bf16::from_bits(bits).to_f32(),
        };
        Ok(sum + value * value)
    })
}

fn apply_vector_delta(
    vectors: &mut BTreeMap<PropertyId, VectorColumn>,
    ann: &mut BTreeMap<PropertyId, AnnIndex>,
    node_id_rows: &PersistentMap<u32>,
    edge_id_rows: &PersistentMap<u32>,
    mutation: &ResolvedVectorMutation,
    device: &Device,
) -> Result<()> {
    let (property, entity, revision) = match mutation {
        ResolvedVectorMutation::Upsert {
            property,
            entity_id,
            revision,
            ..
        }
        | ResolvedVectorMutation::Remove {
            property,
            entity_id,
            revision,
        } => (*property, *entity_id, *revision),
    };
    let column = vectors.get_mut(&property).ok_or_else(|| {
        Error::new(
            ErrorCode::EmbeddingProfileMismatch,
            "vector delta targets a non-resident canonical column",
        )
    })?;
    let existing = stable_id_row(&column.entity_rows, entity).copied();
    let row = match (mutation, existing) {
        (ResolvedVectorMutation::Remove { .. }, None) => return Ok(()),
        (_, Some(row)) => row,
        (ResolvedVectorMutation::Upsert { .. }, None) => {
            let row = u32::try_from(column.rows).map_err(|_| {
                Error::new(ErrorCode::ResultBudgetExceeded, "vector row exceeds u32")
            })?;
            column.entity_rows.insert_cow(stable_id_key(entity), row);
            column.rows += 1;
            row
        }
    };
    let capacity = column
        .rows
        .checked_next_power_of_two()
        .unwrap_or(column.rows)
        .max(64);
    ensure_tensor_capacity(&mut column.entity_ids, capacity, DType::I64, device)?;
    ensure_tensor_capacity(&mut column.node_rows, capacity, DType::U32, device)?;
    ensure_tensor_capacity(&mut column.node_backed, capacity, DType::U8, device)?;
    ensure_tensor_capacity(&mut column.versions, capacity, DType::I64, device)?;
    ensure_tensor_capacity(&mut column.active, capacity, DType::U8, device)?;
    ensure_tensor_capacity(&mut column.squared_norms, capacity, DType::F32, device)?;
    ensure_tensor_capacity(
        &mut column.values,
        capacity.saturating_mul(column.dimension),
        match column.dtype {
            EmbeddingDType::F16 => DType::F16,
            EmbeddingDType::Bf16 => DType::BF16,
        },
        device,
    )?;
    scatter_rows(
        column
            .entity_ids
            .as_ref()
            .ok_or_else(|| Error::internal("vector entity tensor is absent"))?,
        &[row],
        &Tensor::from_slice(&[u64_order_key(entity)], 1, device).map_err(candle_error)?,
    )?;
    let owner_rows = if property == crate::graph::SEMANTIC_RELATIONSHIP_PROPERTY {
        edge_id_rows
    } else {
        node_id_rows
    };
    let (node_row, node_backed) = stable_id_row(owner_rows, entity)
        .copied()
        .map_or((0_u32, 0_u8), |row| (row, 1_u8));
    scatter_rows(
        column
            .node_rows
            .as_ref()
            .ok_or_else(|| Error::internal("vector node-row tensor is absent"))?,
        &[row],
        &Tensor::from_slice(&[node_row], 1, device).map_err(candle_error)?,
    )?;
    scatter_rows(
        column
            .node_backed
            .as_ref()
            .ok_or_else(|| Error::internal("vector node-kind tensor is absent"))?,
        &[row],
        &Tensor::from_slice(&[node_backed], 1, device).map_err(candle_error)?,
    )?;
    scatter_rows(
        column
            .versions
            .as_ref()
            .ok_or_else(|| Error::internal("vector version tensor is absent"))?,
        &[row],
        &Tensor::from_slice(&[revision as i64], 1, device).map_err(candle_error)?,
    )?;
    let active = u8::from(matches!(mutation, ResolvedVectorMutation::Upsert { .. }));
    scatter_rows(
        column
            .active
            .as_ref()
            .ok_or_else(|| Error::internal("vector active tensor is absent"))?,
        &[row],
        &Tensor::from_slice(&[active], 1, device).map_err(candle_error)?,
    )?;
    if let ResolvedVectorMutation::Upsert { coordinates, .. } = mutation {
        if coordinates.len() != column.dimension {
            return Err(Error::new(
                ErrorCode::EmbeddingProfileMismatch,
                "vector delta dimension differs from the resident profile",
            ));
        }
        let start = (row as usize)
            .checked_mul(column.dimension)
            .ok_or_else(|| Error::new(ErrorCode::ResultBudgetExceeded, "vector offset overflow"))?;
        let indexes = (start..start + column.dimension)
            .map(|index| {
                u32::try_from(index).map_err(|_| {
                    Error::new(ErrorCode::ResultBudgetExceeded, "vector offset exceeds u32")
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let indexes = Tensor::from_slice(&indexes, indexes.len(), device).map_err(candle_error)?;
        let values = match column.dtype {
            EmbeddingDType::F16 => Tensor::from_slice(
                &coordinates
                    .iter()
                    .map(|value| f16::from_bits(*value))
                    .collect::<Vec<_>>(),
                coordinates.len(),
                device,
            ),
            EmbeddingDType::Bf16 => Tensor::from_slice(
                &coordinates
                    .iter()
                    .map(|value| bf16::from_bits(*value))
                    .collect::<Vec<_>>(),
                coordinates.len(),
                device,
            ),
        }
        .map_err(candle_error)?;
        column
            .values
            .as_ref()
            .ok_or_else(|| Error::internal("vector value tensor is absent"))?
            .scatter_set(&indexes, &values, 0)
            .map_err(candle_error)?;
        let squared_norm = coordinates
            .iter()
            .map(|bits| match column.dtype {
                EmbeddingDType::F16 => f16::from_bits(*bits).to_f32(),
                EmbeddingDType::Bf16 => bf16::from_bits(*bits).to_f32(),
            })
            .map(|value| value * value)
            .sum::<f32>();
        scatter_rows(
            column
                .squared_norms
                .as_ref()
                .ok_or_else(|| Error::internal("vector squared-norm tensor is absent"))?,
            &[row],
            &Tensor::from_slice(&[squared_norm], 1, device).map_err(candle_error)?,
        )?;
    }
    if let Some(index) = ann.get_mut(&property) {
        let changed = if active == 1 {
            index.stale_row_set.insert(row)
        } else {
            index.stale_row_set.remove(&row)
        };
        if changed {
            index.stale_row_ids = if index.stale_row_set.is_empty() {
                None
            } else {
                Some(
                    Tensor::from_slice(
                        &index.stale_row_set.iter().copied().collect::<Vec<_>>(),
                        index.stale_row_set.len(),
                        device,
                    )
                    .map_err(candle_error)?,
                )
            };
        }
    }
    Ok(())
}

fn upload_label_bitmaps(
    upload: &mut TensorUpload<'_>,
    graph: &crate::graph::GraphSnapshot,
) -> Result<BTreeMap<LabelId, Tensor>> {
    upload_packed_label_bitmaps(upload, graph.node_ids.len(), &graph.node_labels)
}

fn upload_packed_label_bitmaps(
    upload: &mut TensorUpload<'_>,
    node_count: usize,
    labels: &crate::graph::PackedLists<LabelId>,
) -> Result<BTreeMap<LabelId, Tensor>> {
    let mut bitmaps = BTreeMap::<LabelId, Vec<u8>>::new();
    for row in 0..node_count {
        let start = labels.offsets()[row] as usize;
        let end = labels.offsets()[row + 1] as usize;
        for label in labels
            .values()
            .get(start..end)
            .ok_or_else(|| Error::new(ErrorCode::CorruptStorage, "node label range is invalid"))?
        {
            bitmaps.entry(*label).or_insert_with(|| vec![0; node_count])[row] = 1;
        }
    }
    let mut resident = BTreeMap::new();
    for (label, bitmap) in bitmaps {
        if !upload.is_metal() {
            upload.u64_bits([label.0])?;
        }
        let tensor = match upload.metal_shared_reserved(
            &bitmap,
            resident_growth_target(node_count),
            DType::U8,
            "irongraph reserved node label bitmap",
        )? {
            Some((Some(tensor), _shared)) => tensor,
            Some((None, _shared)) => {
                return Err(Error::internal(
                    "non-empty label bitmap allocation is absent",
                ));
            }
            None => upload.required(&bitmap)?,
        };
        resident.insert(label, tensor);
    }
    Ok(resident)
}

fn adjacency_row_views(
    offsets: &[u32],
    neighbors: Option<&Tensor>,
    edges: Option<&Tensor>,
) -> Result<PagedVec<Option<(Tensor, Tensor)>>> {
    let rows = offsets
        .len()
        .checked_sub(1)
        .ok_or_else(|| Error::new(ErrorCode::CorruptStorage, "adjacency offsets are empty"))?;
    if offsets.last().copied().unwrap_or_default() == 0 {
        let mut views = PagedVec::default();
        for _ in 0..rows {
            views.push(None);
        }
        return Ok(views);
    }
    let neighbors = neighbors
        .ok_or_else(|| Error::new(ErrorCode::CorruptStorage, "adjacency neighbors are absent"))?;
    let edges =
        edges.ok_or_else(|| Error::new(ErrorCode::CorruptStorage, "adjacency edges are absent"))?;
    let mut views = PagedVec::default();
    for row in 0..rows {
        let start = offsets[row] as usize;
        let end = offsets[row + 1] as usize;
        if end < start {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "adjacency offsets are not monotonic",
            ));
        }
        if start == end {
            views.push(None);
        } else {
            views.push(Some((
                neighbors
                    .narrow(0, start, end - start)
                    .map_err(candle_error)?,
                edges.narrow(0, start, end - start).map_err(candle_error)?,
            )));
        }
    }
    Ok(views)
}

fn pack_adjacency_rows(
    rows: &PagedVec<Option<(Tensor, Tensor)>>,
    device: &Device,
) -> Result<(Vec<u32>, Tensor, Option<Tensor>, Option<Tensor>)> {
    let mut offsets = Vec::with_capacity(rows.len().saturating_add(1));
    offsets.push(0_u32);
    let mut total = 0_usize;
    let mut neighbor_parts = Vec::new();
    let mut edge_parts = Vec::new();
    for row in rows.iter() {
        if let Some((neighbors, edges)) = row {
            if neighbors.elem_count() != edges.elem_count() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident adjacency row columns have different lengths",
                ));
            }
            total = total.checked_add(neighbors.elem_count()).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident adjacency length overflow",
                )
            })?;
            neighbor_parts.push(neighbors);
            edge_parts.push(edges);
        }
        offsets.push(checked_u32(total, "resident adjacency")?);
    }
    let offset_tensor =
        Tensor::from_slice(&offsets, offsets.len(), device).map_err(candle_error)?;
    if total == 0 {
        return Ok((offsets, offset_tensor, None, None));
    }
    let neighbors = Tensor::cat(&neighbor_parts, 0).map_err(candle_error)?;
    let edges = Tensor::cat(&edge_parts, 0).map_err(candle_error)?;
    Ok((offsets, offset_tensor, Some(neighbors), Some(edges)))
}

fn metal_share_paged<T: Clone + Send + Sync + 'static>(
    upload: &mut TensorUpload<'_>,
    values: &mut crate::graph::PagedVec<T>,
    dtype: DType,
) -> Result<Option<Tensor>> {
    let staged = values.iter().cloned().collect::<Vec<_>>();
    let Some((tensor, shared)) = upload.metal_shared(&staged, dtype)? else {
        return Ok(None);
    };
    values
        .rebase_shared(shared)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    Ok(tensor)
}

fn metal_share_paged_reserved<T: Copy + Send + Sync + 'static>(
    upload: &mut TensorUpload<'_>,
    values: &mut crate::graph::PagedVec<T>,
    capacity: usize,
    dtype: DType,
    label: &str,
) -> Result<Option<Tensor>> {
    let staged = values.iter().copied().collect::<Vec<_>>();
    let Some((tensor, shared)) = upload.metal_shared_reserved(&staged, capacity, dtype, label)?
    else {
        return metal_share_paged(upload, values, dtype);
    };
    values
        .rebase_shared(shared)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    Ok(tensor)
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_tensor_has_capacity(tensor: &Tensor, required: usize) -> bool {
    let (storage, layout) = tensor.storage_and_layout();
    matches!(&*storage, Storage::Metal(storage)
        if layout.is_contiguous()
            && layout.start_offset() == 0
            && storage.buffer().as_ref().storageMode() == MTLStorageMode::Shared
            && storage.buffer().length() / tensor.dtype().size_in_bytes() >= required)
}

fn reserved_adjacency_empty_tail(
    old_count: usize,
    target_count: usize,
    terminal: u32,
) -> Result<Vec<u32>> {
    let appended = target_count.checked_sub(old_count).ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "reserved adjacency logical prefix exceeds its target",
        )
    })?;
    Ok(vec![terminal; appended])
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[allow(unsafe_code)]
#[track_caller]
fn metal_extend_reserved_shared_tensor<T: Copy + Send + Sync + 'static>(
    tensor: &Tensor,
    old_count: usize,
    row_count: usize,
    appended: &[T],
) -> Result<Option<Tensor>> {
    let (storage, layout) = tensor.storage_and_layout();
    let Storage::Metal(storage) = &*storage else {
        return Err(Error::internal(
            "reserved relationship column moved off Metal",
        ));
    };
    let width = tensor.dtype().size_in_bytes();
    if width != size_of::<T>()
        || !layout.is_contiguous()
        || layout.start_offset() != 0
        || layout.shape().elem_count() != old_count
        || old_count.checked_add(appended.len()) != Some(row_count)
        || storage.buffer().as_ref().storageMode() != MTLStorageMode::Shared
    {
        let caller = std::panic::Location::caller();
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            format!(
                "reserved column contract is invalid: caller={}:{} type={} dtype={:?} width={width} type_width={} contiguous={} start_offset={} tensor_count={} old_count={old_count} appended={} row_count={row_count} capacity={} shared={}",
                caller.file(),
                caller.line(),
                std::any::type_name::<T>(),
                tensor.dtype(),
                size_of::<T>(),
                layout.is_contiguous(),
                layout.start_offset(),
                layout.shape().elem_count(),
                appended.len(),
                storage.buffer().length() / width,
                storage.buffer().as_ref().storageMode() == MTLStorageMode::Shared,
            ),
        ));
    }
    let capacity = storage.buffer().length() / width;
    if row_count > capacity {
        return Ok(None);
    }
    let byte_offset = old_count.checked_mul(width).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "reserved relationship tail offset overflow",
        )
    })?;
    // SAFETY: the checked allocation capacity covers the appended tail, which lies strictly
    // beyond the old tensor's logical shape. Existing generations cannot address these bytes.
    unsafe {
        std::ptr::copy_nonoverlapping(
            appended.as_ptr().cast::<u8>(),
            storage.buffer().contents().cast::<u8>().add(byte_offset),
            appended.len() * width,
        );
    }
    let output = Storage::Metal(MetalStorage::new(
        Arc::new(storage.buffer().clone()),
        storage.device().clone(),
        row_count,
        tensor.dtype(),
    ));
    Ok(Some(Tensor::from_storage(
        output,
        row_count,
        BackpropOp::none(),
        false,
    )))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_shared_tensor_prefix<T: Send + Sync + 'static>(
    tensor: &Tensor,
    len: usize,
) -> Result<crate::graph::SharedFlat<T>> {
    let (storage, layout) = tensor.storage_and_layout();
    let Storage::Metal(storage) = &*storage else {
        return Err(Error::internal("shared canonical column moved off Metal"));
    };
    if !layout.is_contiguous()
        || layout.start_offset() != 0
        || tensor.elem_count() != len
        || size_of::<T>() != tensor.dtype().size_in_bytes()
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "shared canonical tensor prefix shape is invalid",
        ));
    }
    shared_flat_from_metal_buffer(Arc::new(storage.buffer().clone()), len)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
#[allow(clippy::too_many_arguments, clippy::type_complexity)]
fn metal_append_shared_edge_columns(
    upload: &mut TensorUpload<'_>,
    backing: &mut GraphSharedBacking,
    old_ids: Option<&Tensor>,
    old_sources: Option<&Tensor>,
    old_targets: Option<&Tensor>,
    old_types: Option<&Tensor>,
    old_layers: Option<&Tensor>,
    old_active: Option<&Tensor>,
    appended: &[crate::graph::EdgeDeviceDelta],
) -> Result<(
    Option<Tensor>,
    Option<Tensor>,
    Option<Tensor>,
    Option<Tensor>,
    Option<Tensor>,
    Option<Tensor>,
)> {
    let old_count = backing.edge_ids.len().saturating_sub(appended.len());
    let row_count = backing.edge_ids.len();
    if appended.is_empty()
        || appended.len() > row_count
        || appended.iter().enumerate().any(|(offset, edge)| {
            edge.dense as usize != old_count + offset
                || edge.source as usize >= backing.node_ids.len()
                || edge.target as usize >= backing.node_ids.len()
        })
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "device relationship append is not contiguous",
        ));
    }
    if old_count != 0
        && [
            old_ids,
            old_sources,
            old_targets,
            old_types,
            old_layers,
            old_active,
        ]
        .iter()
        .any(|tensor| tensor.is_none())
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "device relationship append is missing an old fixed column",
        ));
    }

    let appended_ids = appended
        .iter()
        .map(|edge| edge.id.0 as i64)
        .collect::<Vec<_>>();
    let appended_sources = appended.iter().map(|edge| edge.source).collect::<Vec<_>>();
    let appended_targets = appended.iter().map(|edge| edge.target).collect::<Vec<_>>();
    let appended_types = appended
        .iter()
        .map(|edge| edge.relationship_type.0 as i64)
        .collect::<Vec<_>>();
    let appended_layers = appended
        .iter()
        .map(|edge| edge.layer as u8)
        .collect::<Vec<_>>();
    let appended_active = appended
        .iter()
        .map(|edge| u8::from(edge.active))
        .collect::<Vec<_>>();

    if let (
        Some(old_ids),
        Some(old_sources),
        Some(old_targets),
        Some(old_types),
        Some(old_layers),
        Some(old_active),
    ) = (
        old_ids,
        old_sources,
        old_targets,
        old_types,
        old_layers,
        old_active,
    ) {
        let extended = (
            metal_extend_reserved_shared_tensor(old_ids, old_count, row_count, &appended_ids),
            metal_extend_reserved_shared_tensor(
                old_sources,
                old_count,
                row_count,
                &appended_sources,
            ),
            metal_extend_reserved_shared_tensor(
                old_targets,
                old_count,
                row_count,
                &appended_targets,
            ),
            metal_extend_reserved_shared_tensor(old_types, old_count, row_count, &appended_types),
            metal_extend_reserved_shared_tensor(old_layers, old_count, row_count, &appended_layers),
            metal_extend_reserved_shared_tensor(old_active, old_count, row_count, &appended_active),
        );
        if let (
            Ok(Some(ids)),
            Ok(Some(sources)),
            Ok(Some(targets)),
            Ok(Some(types)),
            Ok(Some(layers)),
            Ok(Some(active)),
        ) = extended
        {
            return Ok((
                Some(ids),
                Some(sources),
                Some(targets),
                Some(types),
                Some(layers),
                Some(active),
            ));
        }
    }
    let transient_start = upload.allocated_bytes;
    let appended_ids = upload.required(&appended_ids)?;
    let appended_sources = upload.required(&appended_sources)?;
    let appended_targets = upload.required(&appended_targets)?;
    let appended_types = upload.required(&appended_types)?;
    let appended_layers = upload.required(&appended_layers)?;
    let appended_active = upload.required(&appended_active)?;
    let transient_ids = [
        appended_ids.id(),
        appended_sources.id(),
        appended_targets.id(),
        appended_types.id(),
        appended_layers.id(),
        appended_active.id(),
    ]
    .into_iter()
    .collect::<HashSet<_>>();
    let transient_bytes = upload.allocated_bytes.saturating_sub(transient_start);

    let old_ids = old_ids.unwrap_or(&appended_ids);
    let old_sources = old_sources.unwrap_or(&appended_sources);
    let old_targets = old_targets.unwrap_or(&appended_targets);
    let old_types = old_types.unwrap_or(&appended_types);
    let old_layers = old_layers.unwrap_or(&appended_layers);
    let old_active = old_active.unwrap_or(&appended_active);
    let (old_ids_storage, old_ids_layout) = old_ids.storage_and_layout();
    let (old_sources_storage, old_sources_layout) = old_sources.storage_and_layout();
    let (old_targets_storage, old_targets_layout) = old_targets.storage_and_layout();
    let (old_types_storage, old_types_layout) = old_types.storage_and_layout();
    let (old_layers_storage, old_layers_layout) = old_layers.storage_and_layout();
    let (old_active_storage, old_active_layout) = old_active.storage_and_layout();
    let (appended_ids_storage, appended_ids_layout) = appended_ids.storage_and_layout();
    let (appended_sources_storage, appended_sources_layout) = appended_sources.storage_and_layout();
    let (appended_targets_storage, appended_targets_layout) = appended_targets.storage_and_layout();
    let (appended_types_storage, appended_types_layout) = appended_types.storage_and_layout();
    let (appended_layers_storage, appended_layers_layout) = appended_layers.storage_and_layout();
    let (appended_active_storage, appended_active_layout) = appended_active.storage_and_layout();
    let (
        Storage::Metal(old_ids_storage),
        Storage::Metal(old_sources_storage),
        Storage::Metal(old_targets_storage),
        Storage::Metal(old_types_storage),
        Storage::Metal(old_layers_storage),
        Storage::Metal(old_active_storage),
        Storage::Metal(appended_ids_storage),
        Storage::Metal(appended_sources_storage),
        Storage::Metal(appended_targets_storage),
        Storage::Metal(appended_types_storage),
        Storage::Metal(appended_layers_storage),
        Storage::Metal(appended_active_storage),
    ) = (
        &*old_ids_storage,
        &*old_sources_storage,
        &*old_targets_storage,
        &*old_types_storage,
        &*old_layers_storage,
        &*old_active_storage,
        &*appended_ids_storage,
        &*appended_sources_storage,
        &*appended_targets_storage,
        &*appended_types_storage,
        &*appended_layers_storage,
        &*appended_active_storage,
    )
    else {
        return Err(Error::internal(
            "device relationship append columns moved off Metal",
        ));
    };

    let reserved_count = resident_growth_target(row_count);
    let (output_ids, shared_ids, output_ids_buffer) = upload
        .metal_shared_uninitialized_reserved::<crate::EdgeId>(
            row_count,
            reserved_count,
            DType::I64,
            "edge ids append",
        )?;
    let (output_sources, shared_sources, output_sources_buffer) = upload
        .metal_shared_uninitialized_reserved::<u32>(
            row_count,
            reserved_count,
            DType::U32,
            "edge sources append",
        )?;
    let (output_targets, shared_targets, output_targets_buffer) = upload
        .metal_shared_uninitialized_reserved::<u32>(
            row_count,
            reserved_count,
            DType::U32,
            "edge targets append",
        )?;
    let (output_types, shared_types, output_types_buffer) = upload
        .metal_shared_uninitialized_reserved::<crate::types::RelationshipTypeId>(
        row_count,
        reserved_count,
        DType::I64,
        "edge types append",
    )?;
    let (output_layers, shared_layers, output_layers_buffer) = upload
        .metal_shared_uninitialized_reserved::<Layer>(
            row_count,
            reserved_count,
            DType::U8,
            "edge layers append",
        )?;
    let (output_active, shared_active, output_active_buffer) = upload
        .metal_shared_uninitialized_reserved::<u8>(
            row_count,
            reserved_count,
            DType::U8,
            "edge active append",
        )?;
    let output_buffers = [
        output_ids_buffer.as_deref(),
        output_sources_buffer.as_deref(),
        output_targets_buffer.as_deref(),
        output_types_buffer.as_deref(),
        output_layers_buffer.as_deref(),
        output_active_buffer.as_deref(),
    ];
    if output_buffers.iter().any(|buffer| buffer.is_none()) {
        return Err(Error::internal(
            "device relationship append output allocation is absent",
        ));
    }
    let Device::Metal(device) = upload.device else {
        return Err(Error::internal(
            "device relationship append requested outside Metal",
        ));
    };
    let pipelines = metal_sort_pipelines(device).map_err(candle_error)?;
    {
        let encoder = device.command_encoder().map_err(candle_error)?;
        let encoder = encoder.as_ref();
        encoder.set_compute_pipeline_state(&pipelines.edge_append);
        let inputs = [
            (old_ids_storage, &old_ids_layout, DType::I64),
            (old_sources_storage, &old_sources_layout, DType::U32),
            (old_targets_storage, &old_targets_layout, DType::U32),
            (old_types_storage, &old_types_layout, DType::I64),
            (old_layers_storage, &old_layers_layout, DType::U8),
            (old_active_storage, &old_active_layout, DType::U8),
            (appended_ids_storage, &appended_ids_layout, DType::I64),
            (
                appended_sources_storage,
                &appended_sources_layout,
                DType::U32,
            ),
            (
                appended_targets_storage,
                &appended_targets_layout,
                DType::U32,
            ),
            (appended_types_storage, &appended_types_layout, DType::I64),
            (appended_layers_storage, &appended_layers_layout, DType::U8),
            (appended_active_storage, &appended_active_layout, DType::U8),
        ];
        for (index, (storage, layout, dtype)) in inputs.into_iter().enumerate() {
            encoder.set_input_buffer(
                index,
                Some(storage.buffer()),
                layout.start_offset() * dtype.size_in_bytes(),
            );
        }
        for (offset, buffer) in output_buffers.into_iter().enumerate() {
            encoder.set_output_buffer(12 + offset, buffer, 0);
        }
        encoder.set_bytes(
            18,
            &MetalEdgeAppendArgs {
                old_count: old_count as u64,
                row_count: row_count as u64,
            },
        );
        encoder.dispatch_thread_groups(
            objc2_metal::MTLSize {
                width: row_count.div_ceil(METAL_SORT_THREADS),
                height: 1,
                depth: 1,
            },
            objc2_metal::MTLSize {
                width: METAL_SORT_THREADS,
                height: 1,
                depth: 1,
            },
        );
    }
    // This branch is the O(total relationship rows) allocation fallback, not the reserved-capacity
    // delta append above. Its newly allocated shared buffers are also the next CPU-readable
    // canonical columns, so the command must finish before publication. Reading and comparing the
    // full output here does not turn the incremental fast path into a full build; it protects only
    // the fallback that already copied every unrelated row.
    device.wait_until_completed().map_err(candle_error)?;
    let fixed_columns_match = shared_ids
        .as_slice()
        .iter()
        .copied()
        .eq(backing.edge_ids.iter().copied())
        && shared_sources
            .as_slice()
            .iter()
            .copied()
            .eq(backing.edge_sources.iter().copied())
        && shared_targets
            .as_slice()
            .iter()
            .copied()
            .eq(backing.edge_targets.iter().copied())
        && shared_types
            .as_slice()
            .iter()
            .copied()
            .eq(backing.edge_types.iter().copied())
        && shared_layers
            .as_slice()
            .iter()
            .copied()
            .eq(backing.edge_layers.iter().copied())
        && shared_active
            .as_slice()
            .iter()
            .copied()
            .eq(backing.edge_active.iter().copied());
    if !fixed_columns_match {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal relationship fixed-column rebuild differed from canonical host rows",
        ));
    }
    upload.allocated_bytes = upload.allocated_bytes.saturating_sub(transient_bytes);
    upload
        .tensors
        .retain(|tensor| !transient_ids.contains(&tensor.id()));
    backing
        .edge_ids
        .rebase_shared(shared_ids)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    backing
        .edge_sources
        .rebase_shared(shared_sources)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    backing
        .edge_targets
        .rebase_shared(shared_targets)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    backing
        .edge_types
        .rebase_shared(shared_types)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    backing
        .edge_layers
        .rebase_shared(shared_layers)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    backing
        .edge_active
        .rebase_shared(shared_active)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    Ok((
        output_ids,
        output_sources,
        output_targets,
        output_types,
        output_layers,
        output_active,
    ))
}

fn metal_shared_paged_from_slice<T: Clone + Send + Sync + 'static>(
    upload: &mut TensorUpload<'_>,
    values: &[T],
    dtype: DType,
) -> Result<Option<(Option<Tensor>, PagedVec<T>)>> {
    let Some((tensor, shared)) = upload.metal_shared(values, dtype)? else {
        return Ok(None);
    };
    let paged = PagedVec::from_shared(shared)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    Ok(Some((tensor, paged)))
}

fn metal_shared_paged_from_slice_reserved<T: Copy + Send + Sync + 'static>(
    upload: &mut TensorUpload<'_>,
    values: &[T],
    capacity: usize,
    dtype: DType,
    label: &str,
) -> Result<Option<(Option<Tensor>, PagedVec<T>)>> {
    let Some((tensor, shared)) = upload.metal_shared_reserved(values, capacity, dtype, label)?
    else {
        return Ok(None);
    };
    let paged = PagedVec::from_shared(shared)
        .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
    Ok(Some((tensor, paged)))
}

fn metal_share_validity(
    upload: &mut TensorUpload<'_>,
    validity: &mut crate::graph::Validity,
) -> Result<()> {
    let words = validity.words().collect::<Vec<_>>();
    if let Some((_tensor, shared)) = upload.metal_shared(&words, DType::I64)? {
        validity.rebase_shared_words(shared)?;
    }
    Ok(())
}

/// Encodes `OrderedFloat<f64>`'s total order into the signed key accepted by the native radix
/// sorter. All NaNs compare equal and after every finite value; `-0.0` and `0.0` compare equal.
/// Every other IEEE-754 bit pattern maps monotonically without floating-point arithmetic.
fn ordered_float_sort_key(value: f64) -> i64 {
    if value.is_nan() {
        return i64::MAX;
    }
    if value == 0.0 {
        return 0;
    }
    let bits = value.to_bits();
    let unsigned = if bits >> 63 == 0 {
        bits ^ (1_u64 << 63)
    } else {
        !bits
    };
    (unsigned ^ (1_u64 << 63)) as i64
}

fn upload_properties(
    upload: &mut TensorUpload<'_>,
    columns: &mut PropertyColumns,
    reserve_rows: bool,
) -> Result<UploadedPropertyColumns> {
    upload_properties_selected(upload, columns, None, true, reserve_rows)
}

fn upload_properties_selected(
    upload: &mut TensorUpload<'_>,
    columns: &mut PropertyColumns,
    selected: Option<&BTreeSet<PropertyId>>,
    upload_dictionary: bool,
    reserve_rows: bool,
) -> Result<UploadedPropertyColumns> {
    let row_capacity = if reserve_rows {
        resident_growth_target(columns.rows())
    } else {
        columns.rows()
    };
    let mut integer = BTreeMap::new();
    let mut boolean = BTreeMap::new();
    let mut float = BTreeMap::new();
    let mut string = BTreeMap::new();
    let mut date = BTreeMap::new();
    let mut local_time = BTreeMap::new();
    let mut zoned_time = BTreeMap::new();
    let mut local_datetime = BTreeMap::new();
    let mut zoned_datetime = BTreeMap::new();
    let mut duration = BTreeMap::new();
    let mut mixed = BTreeMap::new();
    let mut lists = BTreeMap::new();
    let mut maps = BTreeMap::new();
    let mut opaque_validity = BTreeMap::new();
    let mut unsupported = BTreeSet::new();
    let string_dictionary_offsets = columns.string_dictionary().offsets().to_vec();
    let properties = columns
        .property_ids()
        .filter(|property| selected.is_none_or(|selected| selected.contains(property)))
        .collect::<Vec<_>>();
    for property in properties {
        let mixed_column = columns.is_mixed(property);
        if !upload.is_metal() {
            upload.u64_bits([property.0])?;
        }
        let document_is_list = !mixed_column
            && matches!(
                columns
                    .physical_column(property)
                    .ok_or_else(|| Error::internal("property column disappeared during upload"))?,
                TypedColumn::List { .. }
            );
        let validity_mask = columns
            .physical_column(property)
            .ok_or_else(|| Error::internal("property column disappeared during upload"))?
            .validity()
            .to_byte_mask();
        // Presence is queryable independently of value shape. Keep the canonical byte validity
        // lane even for an opaque scalar so the sealed PropertyKeys command never has to inspect
        // or materialize that scalar's payload on the host.
        let validity = match upload.metal_shared_reserved(
            &validity_mask,
            row_capacity,
            DType::U8,
            "irongraph reserved property validity",
        )? {
            Some((tensor, _shared)) => tensor,
            None => upload.optional(&validity_mask)?,
        };
        let column = columns
            .physical_column_mut(property)
            .ok_or_else(|| Error::internal("property column disappeared during upload"))?;
        metal_share_validity(upload, column.validity_mut())?;
        let rows = column.len();
        if mixed_column {
            let TypedColumn::Bytes { values, .. } = column else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "mixed property is not backed by a tagged byte column",
                ));
            };
            let offsets = values.offsets().to_vec();
            let bytes = values.values().to_vec();
            let maximum_string_bytes = values
                .iter()
                .filter_map(|payload| {
                    (payload.first().copied() == Some(MIXED_STRING_TAG))
                        .then_some(payload.len().saturating_sub(1))
                })
                .max()
                .unwrap_or(0);
            let (offsets, bytes) = match (
                upload.metal_shared(&offsets, DType::U32)?,
                upload.metal_shared(&bytes, DType::U8)?,
            ) {
                (
                    Some((Some(offset_tensor), shared_offsets)),
                    Some((byte_tensor, shared_bytes)),
                ) => {
                    values.rebase_shared(shared_offsets, shared_bytes)?;
                    (offset_tensor, byte_tensor)
                }
                (None, None) => (upload.required(&offsets)?, upload.optional(&bytes)?),
                _ => {
                    return Err(Error::internal(
                        "Metal mixed-column allocation mode changed during upload",
                    ));
                }
            };
            mixed.insert(
                property,
                MixedColumn {
                    offsets,
                    bytes,
                    validity,
                    maximum_string_bytes,
                },
            );
            continue;
        }
        match column {
            TypedColumn::Boolean { values, .. } => {
                let values = match metal_share_paged(upload, values, DType::U8)? {
                    Some(values) => Some(values),
                    None => upload.optional(
                        &values
                            .iter()
                            .map(|value| u8::from(*value))
                            .collect::<Vec<_>>(),
                    )?,
                };
                boolean.insert(
                    property,
                    BooleanColumn {
                        values,
                        validity,
                        rows,
                    },
                );
            }
            TypedColumn::Integer { values, .. } => {
                let values = match metal_share_paged_reserved(
                    upload,
                    values,
                    row_capacity,
                    DType::I64,
                    "irongraph reserved integer property",
                )? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(values.iter().copied())?,
                };
                integer.insert(
                    property,
                    IntegerColumn {
                        values,
                        validity,
                        rows,
                    },
                );
            }
            TypedColumn::Float { values, .. } => {
                let raw_values = match metal_share_paged(upload, values, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.u64_bits(values.iter().map(|value| value.0.to_bits()))?,
                };
                let order_keys = upload
                    .optional_iter(values.iter().map(|value| ordered_float_sort_key(value.0)))?;
                float.insert(
                    property,
                    FloatColumn {
                        values: raw_values,
                        order_keys,
                        validity,
                        rows,
                    },
                );
            }
            TypedColumn::String { values, .. } => {
                let maximum_bytes =
                    values
                        .iter()
                        .zip(&validity_mask)
                        .filter_map(|(id, valid)| (*valid != 0).then_some(*id as usize))
                        .map(|id| {
                            let start =
                                string_dictionary_offsets.get(id).copied().ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "resident string property ID is outside its dictionary",
                                    )
                                })?;
                            let end = string_dictionary_offsets.get(id + 1).copied().ok_or_else(
                                || {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "resident string property ID is outside its dictionary",
                                    )
                                },
                            )?;
                            end.checked_sub(start)
                                .map(|width| width as usize)
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "resident string dictionary offsets are not monotonic",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?
                        .into_iter()
                        .max()
                        .unwrap_or(0);
                let values = match metal_share_paged_reserved(
                    upload,
                    values,
                    row_capacity,
                    DType::U32,
                    "irongraph reserved string property",
                )? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(values.iter().copied())?,
                };
                string.insert(
                    property,
                    StringColumn {
                        values,
                        validity,
                        rows,
                        maximum_bytes,
                    },
                );
            }
            TypedColumn::Bytes { values, .. } => {
                unsupported.insert(property);
                opaque_validity.insert(property, validity.clone());
                let offsets = values.offsets().to_vec();
                let bytes = values.values().to_vec();
                match (
                    upload.metal_shared(&offsets, DType::U32)?,
                    upload.metal_shared(&bytes, DType::U8)?,
                ) {
                    (
                        Some((_offset_tensor, shared_offsets)),
                        Some((_bytes_tensor, shared_bytes)),
                    ) => {
                        values.rebase_shared(shared_offsets, shared_bytes)?;
                    }
                    (None, None) => {
                        upload.required(&offsets)?;
                        upload.optional(&bytes)?;
                    }
                    _ => {
                        return Err(Error::internal(
                            "Metal byte-column allocation mode changed during upload",
                        ));
                    }
                }
            }
            TypedColumn::Date { values, .. } => {
                let values = match metal_share_paged(upload, values, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(values.iter().copied())?,
                };
                date.insert(
                    property,
                    IntegerColumn {
                        values,
                        validity,
                        rows,
                    },
                );
            }
            TypedColumn::LocalTime { values, .. } => {
                let values = match metal_share_paged(upload, values, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(values.iter().copied())?,
                };
                local_time.insert(
                    property,
                    IntegerColumn {
                        values,
                        validity,
                        rows,
                    },
                );
            }
            TypedColumn::ZonedTime { nanos, offsets, .. } => {
                let nanos = match metal_share_paged(upload, nanos, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(nanos.iter().copied())?,
                };
                // Candle's Metal backend cannot gather I32 columns. Keep the canonical I32
                // PagedVec untouched and publish one exact resident I64 query tensor; conversion
                // changes only physical width, never the stored offset value or its semantics.
                let offsets =
                    upload.optional_iter(offsets.iter().map(|value| i64::from(*value)))?;
                zoned_time.insert(
                    property,
                    ZonedTimeColumn {
                        nanos,
                        offsets,
                        validity,
                        rows,
                    },
                );
            }
            TypedColumn::LocalDateTime { seconds, nanos, .. } => {
                let seconds = match metal_share_paged(upload, seconds, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(seconds.iter().copied())?,
                };
                let nanos = match metal_share_paged(upload, nanos, DType::U32)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(nanos.iter().copied())?,
                };
                local_datetime.insert(
                    property,
                    LocalDateTimeColumn {
                        seconds,
                        nanos,
                        validity,
                        rows,
                    },
                );
            }
            TypedColumn::ZonedDateTime {
                seconds,
                nanos,
                timezones,
                ..
            } => {
                let maximum_timezone_bytes =
                    timezones
                        .iter()
                        .zip(&validity_mask)
                        .filter_map(|(id, valid)| (*valid != 0).then_some(*id as usize))
                        .map(|id| {
                            let start = string_dictionary_offsets.get(id).copied().ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident zoned-datetime timezone ID is outside its dictionary",
                            )
                        })?;
                            let end = string_dictionary_offsets.get(id + 1).copied().ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident zoned-datetime timezone ID is outside its dictionary",
                            )
                        })?;
                            end.checked_sub(start)
                                .map(|width| width as usize)
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "resident string dictionary offsets are not monotonic",
                                    )
                                })
                        })
                        .collect::<Result<Vec<_>>>()?
                        .into_iter()
                        .max()
                        .unwrap_or(0);
                let seconds = match metal_share_paged(upload, seconds, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(seconds.iter().copied())?,
                };
                let nanos = match metal_share_paged(upload, nanos, DType::U32)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(nanos.iter().copied())?,
                };
                let timezones = match metal_share_paged(upload, timezones, DType::U32)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(timezones.iter().copied())?,
                };
                zoned_datetime.insert(
                    property,
                    ZonedDateTimeColumn {
                        seconds,
                        nanos,
                        timezones,
                        validity,
                        rows,
                        maximum_timezone_bytes,
                    },
                );
            }
            TypedColumn::Duration {
                months,
                days,
                seconds,
                nanos,
                ..
            } => {
                let months = match metal_share_paged(upload, months, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(months.iter().copied())?,
                };
                let days = match metal_share_paged(upload, days, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(days.iter().copied())?,
                };
                let seconds = match metal_share_paged(upload, seconds, DType::I64)? {
                    Some(values) => Some(values),
                    None => upload.optional_iter(seconds.iter().copied())?,
                };
                // The sealed graph packet is one homogeneous i64 address space. Keeping nanos
                // resident as i64 avoids an unsupported query-time Metal i32->i64 cast while the
                // device still range-checks the canonical 0..1e9 component before use.
                let nanos = upload.optional_iter(nanos.iter().map(|value| i64::from(*value)))?;
                duration.insert(
                    property,
                    DurationColumn {
                        months,
                        days,
                        seconds,
                        nanos,
                        validity,
                        rows,
                    },
                );
                // Existing row-property routes still fail closed for DURATION until they own a
                // typed row opcode. The temporal-arithmetic command uses the dedicated map above.
                unsupported.insert(property);
            }
            TypedColumn::List { values, .. } | TypedColumn::Map { values, .. } => {
                unsupported.insert(property);
                let offsets = values.offsets().to_vec();
                let bytes = values.values().to_vec();
                let maximum_bytes = offsets
                    .windows(2)
                    .map(|pair| pair[1].saturating_sub(pair[0]) as usize)
                    .max()
                    .unwrap_or(0);
                let (offsets, bytes) = match (
                    upload.metal_shared(&offsets, DType::U32)?,
                    upload.metal_shared(&bytes, DType::U8)?,
                ) {
                    (
                        Some((Some(offset_tensor), shared_offsets)),
                        Some((byte_tensor, shared_bytes)),
                    ) => {
                        values.rebase_shared(shared_offsets, shared_bytes)?;
                        (offset_tensor, byte_tensor)
                    }
                    (None, None) => (upload.required(&offsets)?, upload.optional(&bytes)?),
                    _ => {
                        return Err(Error::internal(
                            "Metal document allocation mode changed during upload",
                        ));
                    }
                };
                let column = DocumentColumn {
                    offsets,
                    bytes,
                    validity,
                    rows,
                    maximum_bytes,
                };
                if document_is_list {
                    lists.insert(property, column);
                } else {
                    maps.insert(property, column);
                }
            }
        }
    }
    let dictionary = if upload_dictionary {
        let offsets = columns.string_dictionary().offsets().to_vec();
        let bytes = columns.string_dictionary().bytes().to_vec();
        let maximum_bytes = offsets
            .windows(2)
            .map(|pair| (pair[1] - pair[0]) as usize)
            .max()
            .unwrap_or(0);
        let dictionary_entries = offsets
            .windows(2)
            .map(|pair| {
                let start = pair[0] as usize;
                let end = pair[1] as usize;
                std::str::from_utf8(bytes.get(start..end).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident string dictionary offset is out of bounds",
                    )
                })?)
                .map(str::to_owned)
                .map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident string dictionary contains invalid UTF-8",
                    )
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let ranks = resident_string_dictionary_ranks(&dictionary_entries)?;
        let (offsets, bytes) = match (
            upload.metal_shared(&offsets, DType::U32)?,
            upload.metal_shared(&bytes, DType::U8)?,
        ) {
            (Some((Some(offset_tensor), shared_offsets)), Some((byte_tensor, shared_bytes))) => {
                columns
                    .string_dictionary_mut()
                    .rebase_shared(shared_offsets, shared_bytes)?;
                (offset_tensor, byte_tensor)
            }
            (None, None) => (upload.required(&offsets)?, upload.optional(&bytes)?),
            _ => {
                return Err(Error::internal(
                    "Metal string-dictionary allocation mode changed during upload",
                ));
            }
        };
        Some(StringDictionary {
            offsets,
            bytes,
            ranks: upload.optional(&ranks)?,
            maximum_bytes,
            host: None,
        })
    } else {
        None
    };
    Ok(UploadedPropertyColumns {
        integer,
        boolean,
        float,
        string,
        date,
        local_time,
        zoned_time,
        local_datetime,
        zoned_datetime,
        duration,
        mixed,
        lists,
        maps,
        opaque_validity,
        unsupported,
        dictionary,
    })
}

fn shared_null_integer_column(upload: &mut TensorUpload<'_>, rows: usize) -> Result<IntegerColumn> {
    let values = vec![0_i64; rows];
    let validity = vec![0_u8; rows];
    let Some((values, _shared_values)) = upload.metal_shared(&values, DType::I64)? else {
        return Err(Error::internal(
            "shared null temporal column moved to a non-Metal device",
        ));
    };
    let Some((validity, _shared_validity)) = upload.metal_shared(&validity, DType::U8)? else {
        return Err(Error::internal(
            "shared null temporal column moved to a non-Metal device",
        ));
    };
    Ok(IntegerColumn {
        values,
        validity,
        rows,
    })
}

fn upload_shared_temporal(
    upload: &mut TensorUpload<'_>,
    image: &ResidentProjectImage,
) -> Result<(
    BTreeMap<(u8, u64, PropertyId), IntegerTemporalColumn>,
    Vec<TemporalCanonicalColumn>,
)> {
    if image.temporal_canonical.len() != image.temporal.columns.len() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "canonical and device temporal column sets differ",
        ));
    }
    let mut integer = BTreeMap::new();
    let mut shared = Vec::with_capacity(image.temporal_canonical.len());
    for mut canonical in image.temporal_canonical.clone() {
        let device_column = image
            .temporal
            .columns
            .iter()
            .find(|column| {
                column.entity_kind == canonical.entity_kind
                    && column.target == canonical.target
                    && column.property == canonical.property
            })
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "canonical temporal column has no device image",
                )
            })?;
        if canonical.len() != device_column.entity_ids.len()
            || !canonical
                .entity_ids
                .iter()
                .copied()
                .eq(device_column.entity_ids.iter().copied())
            || !canonical
                .event_times_nanos
                .iter()
                .copied()
                .eq(device_column.event_times_nanos.iter().copied())
            || !canonical
                .sequence_indexes
                .iter()
                .copied()
                .eq(device_column.sequence_indexes.iter().copied())
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "canonical temporal order differs from its device image",
            ));
        }
        let _raw_entity_ids = metal_share_paged(upload, &mut canonical.entity_ids, DType::I64)?;
        let event_times_nanos =
            metal_share_paged(upload, &mut canonical.event_times_nanos, DType::I64)?;
        let _raw_sequence = metal_share_paged(upload, &mut canonical.sequence_indexes, DType::I64)?;
        let uploaded = upload_properties(upload, &mut canonical.values, false)?;
        let mut integers = uploaded.integer;
        let booleans = uploaded.boolean;
        if canonical.value_type == TemporalType::Integer {
            let column = match integers.remove(&canonical.property) {
                Some(column) => column,
                None => shared_null_integer_column(upload, canonical.len())?,
            };
            integer.insert(
                (
                    canonical.entity_kind as u8,
                    canonical.target,
                    canonical.property,
                ),
                IntegerTemporalColumn {
                    rows: canonical.len(),
                    entity_ids: upload.u64_order_keys(canonical.entity_ids.iter().copied())?,
                    event_times_nanos,
                    sequence_indexes: upload
                        .u64_order_keys(canonical.sequence_indexes.iter().copied())?,
                    values: column.values,
                    validity: column.validity,
                },
            );
        }
        if !integers.is_empty() || !booleans.is_empty() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "temporal canonical column contains an unrelated integer property",
            ));
        }
        shared.push(canonical);
    }
    upload_temporal_rollups(upload, &image.temporal.rollups)?;
    Ok((integer, shared))
}

fn upload_temporal_rollups(
    upload: &mut TensorUpload<'_>,
    rollups: &[crate::graph::RollupDeviceColumn],
) -> Result<()> {
    for rollup in rollups {
        upload.optional(rollup.name.as_bytes())?;
        upload.u64_bits(rollup.entity_ids.iter().copied())?;
        upload.optional(&rollup.starts_nanos)?;
        upload.optional(&rollup.ends_nanos)?;
        upload.u64_bits(rollup.counts.iter().copied())?;
        upload.f64_bits(rollup.sums.iter().copied())?;
        upload.f64_bits(rollup.minimums.iter().copied())?;
        upload.f64_bits(rollup.maximums.iter().copied())?;
        upload.f64_bits(rollup.averages.iter().copied())?;
        upload.optional(&rollup.aggregate_validity)?;
    }
    Ok(())
}

fn upload_temporal(
    upload: &mut TensorUpload<'_>,
    image: &ResidentProjectImage,
) -> Result<(
    BTreeMap<(u8, u64, PropertyId), IntegerTemporalColumn>,
    Vec<TemporalCanonicalColumn>,
)> {
    if upload.is_metal() {
        return upload_shared_temporal(upload, image);
    }
    let mut integer = BTreeMap::new();
    for column in &image.temporal.columns {
        upload.u64_bits([column.target, column.property.0])?;
        let entity_ids = upload.u64_order_keys(column.entity_ids.iter().copied())?;
        let event_times_nanos = upload.optional(&column.event_times_nanos)?;
        let sequence_indexes = upload.u64_order_keys(column.sequence_indexes.iter().copied())?;
        let validity = upload.optional(&column.validity)?;
        upload.u64_bits(column.current_entity_ids.iter().copied())?;
        upload.optional(&column.current_rows)?;
        match &column.values {
            TemporalDeviceValues::Boolean(values) => upload.optional(values).map(|_| ())?,
            TemporalDeviceValues::Integer(values) | TemporalDeviceValues::LocalTime(values) => {
                let values = upload.optional(values)?;
                if matches!(&column.values, TemporalDeviceValues::Integer(_)) {
                    integer.insert(
                        (column.entity_kind as u8, column.target, column.property),
                        IntegerTemporalColumn {
                            rows: column.entity_ids.len(),
                            entity_ids,
                            event_times_nanos,
                            sequence_indexes,
                            values,
                            validity,
                        },
                    );
                }
            }
            TemporalDeviceValues::FloatBits(values) => {
                upload.u64_bits(values.iter().copied())?;
            }
            TemporalDeviceValues::String { offsets, bytes } => {
                upload.required(offsets)?;
                upload.optional(bytes)?;
            }
            TemporalDeviceValues::Date(values) => upload.optional(values).map(|_| ())?,
            TemporalDeviceValues::ZonedTime { nanos, offsets } => {
                upload.optional(nanos)?;
                upload.optional(offsets)?;
            }
            TemporalDeviceValues::LocalDateTime { seconds, nanos } => {
                upload.optional(seconds)?;
                upload.optional(nanos)?;
            }
            TemporalDeviceValues::ZonedDateTime {
                seconds,
                nanos,
                timezone_offsets,
                timezone_bytes,
            } => {
                upload.optional(seconds)?;
                upload.optional(nanos)?;
                upload.required(timezone_offsets)?;
                upload.optional(timezone_bytes)?;
            }
            TemporalDeviceValues::Duration {
                months,
                days,
                seconds,
                nanos,
            } => {
                upload.optional(months)?;
                upload.optional(days)?;
                upload.optional(seconds)?;
                upload.optional(nanos)?;
            }
        }
    }
    upload_temporal_rollups(upload, &image.temporal.rollups)?;
    Ok((integer, Vec::new()))
}

fn upload_indexes(
    upload: &mut TensorUpload<'_>,
    image: &ResidentProjectImage,
    node_id_rows: &PersistentMap<u32>,
    edge_id_rows: &PersistentMap<u32>,
) -> Result<(
    BTreeMap<PropertyId, VectorColumn>,
    BTreeMap<PropertyId, AnnIndex>,
    Vec<SharedVectorBacking>,
)> {
    if let Some(profile) = &image.indexes.profile {
        profile.validate()?;
        upload.optional(&profile.model_hash)?;
        upload.optional(&profile.tokenizer_hash)?;
        upload.optional(&profile.profile_hash)?;
        upload.optional(&[profile.dimension])?;
    } else if !image.indexes.vectors.is_empty() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "canonical vector columns require one active embedding profile",
        ));
    }
    let mut vectors = BTreeMap::new();
    let mut shared_vectors = Vec::new();
    for vector in &image.indexes.vectors {
        let expected_values = vector
            .entity_ids
            .len()
            .checked_mul(vector.dimension)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "canonical vector image shape overflow",
                )
            })?;
        let profile = image
            .indexes
            .profile
            .as_ref()
            .ok_or_else(|| Error::internal("vector profile disappeared during upload"))?;
        if vector.dimension == 0
            || vector.values.len() != expected_values
            || vector.versions.len() != vector.entity_ids.len()
            || vector.active.len() != vector.entity_ids.len()
            || vector.active.iter().any(|active| *active > 1)
            || profile.dimension as usize != vector.dimension
            || profile.dtype != vector.dtype
            || profile.similarity != vector.similarity
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "canonical vector image is structurally inconsistent with its profile",
            ));
        }
        let mut entity_rows = PersistentMap::default();
        for (row, entity) in vector.entity_ids.iter().copied().enumerate() {
            let row = u32::try_from(row).map_err(|_| {
                Error::new(ErrorCode::ResultBudgetExceeded, "vector row exceeds u32")
            })?;
            entity_rows.insert_cow(stable_id_key(entity), row);
        }
        if entity_rows.len() != vector.entity_ids.len() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "canonical vector image contains duplicate entity IDs",
            ));
        }
        if !upload.is_metal() {
            upload.u64_bits([vector.property.0])?;
        }
        let shared_entity_ids =
            metal_shared_paged_from_slice(upload, &vector.entity_ids, DType::I64)?
                .map(|(_tensor, values)| values);
        let entity_ids = upload.u64_order_keys(vector.entity_ids.iter().copied())?;
        let owner_rows = if vector.property == crate::graph::SEMANTIC_RELATIONSHIP_PROPERTY {
            edge_id_rows
        } else {
            node_id_rows
        };
        let node_rows = upload.optional(
            &vector
                .entity_ids
                .iter()
                .map(|entity| stable_id_row(owner_rows, *entity).copied().unwrap_or(0))
                .collect::<Vec<_>>(),
        )?;
        let node_backed = upload.optional(
            &vector
                .entity_ids
                .iter()
                .map(|entity| u8::from(stable_id_row(owner_rows, *entity).is_some()))
                .collect::<Vec<_>>(),
        )?;
        let vector_dtype = match vector.dtype {
            EmbeddingDType::F16 => DType::F16,
            EmbeddingDType::Bf16 => DType::BF16,
        };
        let (values, shared_values) =
            match metal_shared_paged_from_slice(upload, &vector.values, vector_dtype)? {
                Some((tensor, values)) => (tensor, Some(values)),
                None => (
                    match vector.dtype {
                        EmbeddingDType::F16 => upload.optional(
                            &vector
                                .values
                                .iter()
                                .map(|bits| f16::from_bits(*bits))
                                .collect::<Vec<_>>(),
                        )?,
                        EmbeddingDType::Bf16 => upload.optional(
                            &vector
                                .values
                                .iter()
                                .map(|bits| bf16::from_bits(*bits))
                                .collect::<Vec<_>>(),
                        )?,
                    },
                    None,
                ),
            };
        let squared_norms = upload.optional(
            &vector
                .values
                .chunks_exact(vector.dimension)
                .map(|coordinates| {
                    coordinates
                        .iter()
                        .map(|bits| match vector.dtype {
                            EmbeddingDType::F16 => f16::from_bits(*bits).to_f32(),
                            EmbeddingDType::Bf16 => bf16::from_bits(*bits).to_f32(),
                        })
                        .map(|value| value * value)
                        .sum::<f32>()
                })
                .collect::<Vec<_>>(),
        )?;
        let (versions, shared_versions) =
            match metal_shared_paged_from_slice(upload, &vector.versions, DType::I64)? {
                Some((tensor, versions)) => (tensor, Some(versions)),
                None => (upload.u64_bits(vector.versions.iter().copied())?, None),
            };
        let (active, shared_active) = match upload.metal_shared(&vector.active, DType::U8)? {
            Some((tensor, active)) => {
                let active = active
                    .into_bools()
                    .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
                let active = PagedVec::from_shared(active)
                    .map_err(|message| Error::new(ErrorCode::CorruptStorage, message))?;
                (tensor, Some(active))
            }
            None => (upload.optional(&vector.active)?, None),
        };
        match (
            shared_entity_ids,
            shared_values,
            shared_versions,
            shared_active,
        ) {
            (Some(entity_ids), Some(values), Some(versions), Some(active)) => {
                shared_vectors.push(SharedVectorBacking {
                    property: vector.property,
                    dimension: vector.dimension,
                    entity_ids,
                    values,
                    versions,
                    active,
                });
            }
            (None, None, None, None) => {}
            _ => {
                return Err(Error::internal(
                    "Metal canonical vector allocation was only partially constructed",
                ));
            }
        }
        if vectors
            .insert(
                vector.property,
                VectorColumn {
                    dimension: vector.dimension,
                    similarity: vector.similarity,
                    dtype: vector.dtype,
                    rows: vector.entity_ids.len(),
                    entity_ids,
                    node_rows,
                    node_backed,
                    values,
                    squared_norms,
                    versions,
                    active,
                    entity_rows,
                },
            )
            .is_some()
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident image contains duplicate canonical vector properties",
            ));
        }
    }
    let mut ann = BTreeMap::new();
    for index in &image.indexes.indexes {
        let (property, approximate) = match index {
            DerivedIndexDeviceImage::Equality { name, postings }
            | DerivedIndexDeviceImage::Range { name, postings } => {
                upload.optional(name.as_bytes())?;
                upload.required(&postings.key_offsets)?;
                upload.optional(&postings.key_bytes)?;
                upload.required(&postings.posting_offsets)?;
                upload.optional(&postings.rows)?;
                continue;
            }
            DerivedIndexDeviceImage::Text { name, postings } => {
                upload.optional(name.as_bytes())?;
                upload.required(&postings.term_offsets)?;
                upload.optional(&postings.term_bytes)?;
                upload.required(&postings.posting_offsets)?;
                upload.optional(&postings.rows)?;
                continue;
            }
            DerivedIndexDeviceImage::Vector {
                name,
                property,
                approximate,
            } => {
                upload.optional(name.as_bytes())?;
                let Some(approximate) = approximate else {
                    continue;
                };
                (*property, approximate)
            }
        };
        let vector = image
            .indexes
            .vectors
            .iter()
            .find(|vector| vector.property == property)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "ANN index has no canonical vector column",
                )
            })?;
        if ann
            .insert(property, upload_ann(upload, approximate, vector)?)
            .is_some()
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident image contains duplicate ANN vector properties",
            ));
        }
    }
    Ok((vectors, ann, shared_vectors))
}

fn upload_ann(
    upload: &mut TensorUpload<'_>,
    ann: &AnnDeviceImage,
    vector: &crate::graph::VectorDeviceImage,
) -> Result<AnnIndex> {
    if ann.dimension != vector.dimension
        || ann.similarity != vector.similarity
        || ann.config.size_class_version != crate::graph::IVF_PQ_SIZE_CLASS_VERSION
        || ann.coarse_count == 0
        || ann.config.coarse_centroids != ann.coarse_count
        || ann.config.subquantizers == 0
        || ann.config.subquantizers > ann.dimension
        || ann.config.bits_per_code == 0
        || ann.config.bits_per_code > 8
        || ann.config.probes == 0
        || ann.config.probes > ann.coarse_count
        || ann.config.candidate_budget == 0
        || ann.config.iterations == 0
        || ann.codebook_subspace_offsets.len() != ann.config.subquantizers + 1
        || ann.codes.len()
            != ann
                .rows
                .len()
                .checked_mul(ann.config.subquantizers)
                .ok_or_else(|| {
                    Error::new(ErrorCode::CorruptStorage, "resident PQ code shape overflow")
                })?
        || ann.list_offsets.len() != ann.coarse_count + 1
        || ann.built_versions.len() != ann.rows.len()
        || ann.coarse_values.len() != ann.coarse_count.saturating_mul(ann.dimension)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident IVF-PQ image is structurally inconsistent",
        ));
    }
    let centroid_count = ann.codebook_subspace_offsets.last().copied().unwrap_or(0) as usize;
    if ann.codebook_vector_offsets.len() != centroid_count.saturating_add(1)
        || ann.codebook_vector_offsets.last().copied().unwrap_or(0) as usize
            != ann.codebook_values.len()
        || ann.list_offsets.last().copied().unwrap_or(0) as usize != ann.list_positions.len()
        || ann
            .rows
            .iter()
            .any(|row| *row as usize >= vector.entity_ids.len())
        || ann.rows.windows(2).any(|rows| rows[0] >= rows[1])
        || ann
            .list_positions
            .iter()
            .any(|position| *position as usize >= ann.rows.len())
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident IVF-PQ offsets or row references are invalid",
        ));
    }
    for subspace in 0..ann.config.subquantizers {
        let (coordinate_start, coordinate_end) =
            ann_subspace_bounds(ann.dimension, ann.config.subquantizers, subspace);
        let width = coordinate_end.saturating_sub(coordinate_start);
        let centroid_start = ann.codebook_subspace_offsets[subspace] as usize;
        let centroid_end = ann.codebook_subspace_offsets[subspace + 1] as usize;
        if centroid_start >= centroid_end
            || (centroid_start..centroid_end).any(|centroid| {
                ann.codebook_vector_offsets[centroid + 1]
                    .saturating_sub(ann.codebook_vector_offsets[centroid]) as usize
                    != width
            })
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident PQ codebook has an invalid subspace shape",
            ));
        }
        let centroid_count = centroid_end - centroid_start;
        if ann
            .codes
            .iter()
            .skip(subspace)
            .step_by(ann.config.subquantizers)
            .any(|code| *code as usize >= centroid_count)
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident PQ code references an invalid centroid",
            ));
        }
    }
    let coarse = upload.optional(&ann.coarse_values)?;
    upload.required(&ann.codebook_subspace_offsets)?;
    upload.required(&ann.codebook_vector_offsets)?;
    let codebook_values = upload.optional(&ann.codebook_values)?;
    let rows = upload.optional(&ann.rows)?;
    let built_versions = upload.u64_bits(ann.built_versions.iter().copied())?;
    let codes = upload.optional(&ann.codes)?;
    let list_offsets = upload.required(&ann.list_offsets)?;
    let list_positions = upload.optional(&ann.list_positions)?;
    let mut stale_row_set = (0..vector.entity_ids.len())
        .filter(|row| vector.active.get(*row).copied().unwrap_or(0) != 0)
        .map(|row| {
            u32::try_from(row).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "stale vector row exceeds u32",
                )
            })
        })
        .collect::<Result<BTreeSet<_>>>()?;
    for (position, row) in ann.rows.iter().copied().enumerate() {
        if vector.versions.get(row as usize).copied() == ann.built_versions.get(position).copied() {
            stale_row_set.remove(&row);
        }
    }
    let stale_row_ids = upload.optional(&stale_row_set.iter().copied().collect::<Vec<_>>())?;
    Ok(AnnIndex {
        config: ann.config,
        dimension: ann.dimension,
        coarse_count: ann.coarse_count,
        coarse,
        rows,
        built_versions,
        codes,
        codebook_values,
        list_offsets,
        list_positions,
        subspace_centroid_offsets: ann.codebook_subspace_offsets.clone(),
        codebook_vector_offsets: ann.codebook_vector_offsets.clone(),
        stale_row_ids,
        stale_row_set,
        build_generation: ann.build_generation,
    })
}

fn ann_subspace_bounds(dimension: usize, subquantizers: usize, subspace: usize) -> (usize, usize) {
    let start = dimension.saturating_mul(subspace) / subquantizers;
    let end = dimension.saturating_mul(subspace.saturating_add(1)) / subquantizers;
    (start, end)
}

fn planned_property_bytes(
    columns: &PropertyColumns,
    selected: Option<&BTreeSet<PropertyId>>,
    include_dictionary: bool,
) -> usize {
    let mut bytes = 0_usize;
    for column in columns
        .columns()
        .filter(|(property, _)| selected.is_none_or(|selected| selected.contains(property)))
        .map(|(_, column)| column)
    {
        bytes = bytes
            .saturating_add(size_of::<i64>())
            .saturating_add(column.validity().len())
            .saturating_add(
                column
                    .validity()
                    .len()
                    .div_ceil(u64::BITS as usize)
                    .saturating_mul(size_of::<u64>()),
            );
        bytes = bytes.saturating_add(match column {
            TypedColumn::Boolean { values, .. } => values.len(),
            TypedColumn::Integer { values, .. } | TypedColumn::LocalTime { values, .. } => {
                values.len() * size_of::<i64>()
            }
            // Raw IEEE bits are canonical; a second signed key is the exact resident
            // `OrderedFloat` sort index used by the device pipeline.
            TypedColumn::Float { values, .. } => values.len() * size_of::<i64>() * 2,
            TypedColumn::String { values, .. } => values.len() * size_of::<u32>(),
            TypedColumn::Bytes { values, .. } => {
                (values.len() + 1) * size_of::<u32>()
                    + values.iter().map(|value| value.len()).sum::<usize>()
            }
            TypedColumn::Date { values, .. } => values.len() * size_of::<i64>(),
            TypedColumn::ZonedTime { nanos, offsets, .. } => {
                nanos.len() * size_of::<i64>() + offsets.len() * size_of::<i32>()
            }
            TypedColumn::LocalDateTime { seconds, nanos, .. } => {
                seconds.len() * size_of::<i64>() + nanos.len() * size_of::<u32>()
            }
            TypedColumn::ZonedDateTime {
                seconds,
                nanos,
                timezones,
                ..
            } => {
                seconds.len() * size_of::<i64>()
                    + nanos.len() * size_of::<u32>()
                    + timezones.len() * size_of::<u32>()
            }
            TypedColumn::Duration {
                months,
                days,
                seconds,
                nanos,
                ..
            } => {
                (months.len() + days.len() + seconds.len()) * size_of::<i64>()
                    + nanos.len() * size_of::<i32>()
            }
            TypedColumn::List { values, .. } | TypedColumn::Map { values, .. } => {
                values.offsets().len() * size_of::<u32>() + values.values().len()
            }
        });
    }
    if include_dictionary {
        let dictionary = columns.string_dictionary();
        bytes = bytes
            .saturating_add((dictionary.len() + 1) * size_of::<u32>())
            .saturating_add(dictionary.values().map(str::len).sum::<usize>())
            // Exact lexicographic rank is a resident u32 lane rebuilt with the dictionary.
            .saturating_add(dictionary.len().saturating_mul(size_of::<u32>()));
    }
    bytes
}

fn metal_shared_property_bytes(columns: &PropertyColumns) -> usize {
    // Metal shares canonical payloads directly and omits only host-side property IDs. Every
    // property shape retains its byte-validity lane for device-side presence/keys evaluation.
    let property_ids = columns.columns().count().saturating_mul(size_of::<u64>());
    planned_property_bytes(columns, None, true).saturating_sub(property_ids)
}

fn metal_shared_selected_property_bytes(
    columns: &PropertyColumns,
    selected: &BTreeSet<PropertyId>,
    include_dictionary: bool,
) -> usize {
    let property_ids = selected
        .iter()
        .filter(|property| columns.contains(**property))
        .count()
        .saturating_mul(size_of::<u64>());
    planned_property_bytes(columns, Some(selected), include_dictionary).saturating_sub(property_ids)
}

fn metal_reserved_selected_node_property_spare_bytes(
    columns: &PropertyColumns,
    selected: &BTreeSet<PropertyId>,
) -> usize {
    let spare_rows = resident_growth_target(columns.rows()).saturating_sub(columns.rows());
    selected
        .iter()
        .filter_map(|property| columns.physical_column(*property))
        .map(|column| {
            // Every node property has a reserved byte-validity lane. INTEGER and STRING also keep
            // their fixed-width value lane reserved so contiguous appends touch only delta rows.
            let bytes_per_spare_row = match column {
                TypedColumn::Integer { .. } => size_of::<u8>() + size_of::<i64>(),
                TypedColumn::String { .. } => size_of::<u8>() + size_of::<u32>(),
                _ => size_of::<u8>(),
            };
            spare_rows.saturating_mul(bytes_per_spare_row)
        })
        .fold(0_usize, usize::saturating_add)
}

fn graph_delta_is_property_only(
    backing: &GraphSharedBacking,
    delta: &crate::graph::GraphDeviceDelta,
    adjacency_changed: bool,
) -> bool {
    if adjacency_changed
        || delta.node_capacity != backing.node_ids.len()
        || delta.edge_capacity != backing.edge_ids.len()
        || (delta.nodes.is_empty() && delta.edges.is_empty())
    {
        return false;
    }
    let nodes_are_stable = delta.nodes.iter().all(|node| {
        let row = node.dense as usize;
        backing.node_ids.get(row) == Some(&node.id)
            && backing.node_layers.get(row) == Some(&node.layer)
            && backing.node_active.get(row).copied() == Some(u8::from(node.active))
            && backing.node_labels.get(node.dense) == Some(node.labels.as_slice())
    });
    let edges_are_stable = delta.edges.iter().all(|edge| {
        let row = edge.dense as usize;
        backing.edge_ids.get(row) == Some(&edge.id)
            && backing.edge_sources.get(row).copied() == Some(edge.source)
            && backing.edge_targets.get(row).copied() == Some(edge.target)
            && backing.edge_types.get(row) == Some(&edge.relationship_type)
            && backing.edge_layers.get(row) == Some(&edge.layer)
            && backing.edge_active.get(row).copied() == Some(u8::from(edge.active))
    });
    nodes_are_stable && edges_are_stable
}

fn changed_property_ids<'a>(
    columns: &PropertyColumns,
    rows: impl Iterator<Item = (u32, &'a [(PropertyId, ScalarValue)])>,
) -> BTreeSet<PropertyId> {
    let known = columns.property_ids().collect::<Vec<_>>();
    let mut changed = BTreeSet::new();
    for (row, properties) in rows {
        for property in known
            .iter()
            .copied()
            .chain(properties.iter().map(|(property, _)| *property))
        {
            let current = columns.get(row, property);
            let replacement = properties
                .iter()
                .find(|(candidate, _)| *candidate == property)
                .map(|(_, value)| value);
            if current.as_ref() != replacement {
                changed.insert(property);
            }
        }
    }
    changed
}

fn shared_graph_replaced_bytes(
    backing: &GraphSharedBacking,
    nodes: bool,
    edges: bool,
    adjacency: bool,
) -> usize {
    let mut bytes = 0_usize;
    if nodes {
        let rows = backing.node_ids.len();
        let labels = backing
            .node_labels
            .values()
            .iter()
            .copied()
            .collect::<BTreeSet<_>>()
            .len();
        bytes = bytes
            .saturating_add(rows.saturating_mul(size_of::<u64>() * 3 + 2))
            .saturating_add(
                backing
                    .node_labels
                    .offsets()
                    .len()
                    .saturating_mul(size_of::<u32>()),
            )
            .saturating_add(
                backing
                    .node_labels
                    .values()
                    .len()
                    .saturating_mul(size_of::<LabelId>()),
            )
            .saturating_add(labels.saturating_mul(rows))
            .saturating_add(metal_shared_property_bytes(&backing.node_properties));
    }
    if edges {
        let rows = backing.edge_ids.len();
        bytes = bytes
            .saturating_add(rows.saturating_mul(size_of::<u64>() * 3 + size_of::<u32>() * 2 + 2))
            .saturating_add(metal_shared_property_bytes(&backing.edge_properties));
    }
    if adjacency {
        bytes = bytes.saturating_add(
            (backing.outgoing.offsets().len()
                + backing.outgoing.neighbors().len()
                + backing.outgoing.edges().len()
                + backing.incoming.offsets().len()
                + backing.incoming.neighbors().len()
                + backing.incoming.edges().len())
            .saturating_mul(size_of::<u32>()),
        );
    }
    bytes
}

fn shared_vector_column_bytes(rows: usize, dimension: usize) -> usize {
    rows.saturating_mul(
        size_of::<u64>() * 3
            + size_of::<u32>()
            + size_of::<f32>()
            + 2
            + dimension.saturating_mul(size_of::<u16>()),
    )
}

fn shared_temporal_column_bytes(backing: &TemporalCanonicalColumn) -> usize {
    let integer = backing.value_type == TemporalType::Integer;
    let derived_order_bytes = usize::from(integer)
        .saturating_mul(backing.len())
        .saturating_mul(size_of::<u64>() * 2);
    let null_integer_bytes =
        usize::from(integer && backing.values.column(backing.property).is_none())
            .saturating_mul(backing.len())
            .saturating_mul(size_of::<i64>() + 1);
    backing
        .len()
        .saturating_mul(size_of::<u64>() * 3)
        .saturating_add(derived_order_bytes)
        .saturating_add(null_integer_bytes)
        .saturating_add(metal_shared_property_bytes(&backing.values))
}

pub fn filter_tensor(
    values: &Tensor,
    validity: &Tensor,
    operation: CompareOp,
    operand: i64,
    cancellation: &CancellationToken,
) -> Result<Vec<u32>> {
    ensure_not_cancelled(cancellation)?;
    let predicate = match operation {
        CompareOp::Eq => values.eq(operand),
        CompareOp::NotEq => values.ne(operand),
        CompareOp::Less => values.lt(operand),
        CompareOp::LessOrEqual => values.le(operand),
        CompareOp::Greater => values.gt(operand),
        CompareOp::GreaterOrEqual => values.ge(operand),
    }
    .map_err(candle_error)?;
    let selected = predicate
        .broadcast_mul(&validity.eq(1_u8).map_err(candle_error)?)
        .and_then(|tensor| tensor.to_vec1::<u8>())
        .map_err(candle_error)?;
    ensure_not_cancelled(cancellation)?;
    selected
        .into_iter()
        .enumerate()
        .filter(|(_, selected)| *selected != 0)
        .map(|(row, _)| {
            u32::try_from(row).map_err(|_| {
                Error::new(ErrorCode::ResultBudgetExceeded, "selection row exceeds u32")
            })
        })
        .collect()
}

fn ann_candidate_rows(
    ann: &AnnIndex,
    vector: &VectorColumn,
    visibility: &Tensor,
    limit: usize,
    device: &Device,
    query: &[f32],
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    if ann.dimension != vector.dimension
        || ann.coarse_count == 0
        || visibility.elem_count() != vector.rows
        || ann.list_offsets.elem_count() != ann.coarse_count + 1
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident IVF-PQ query shape is invalid",
        ));
    }
    let coarse = ann
        .coarse
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty ANN image has no coarse tensor"))?
        .reshape((ann.coarse_count, ann.dimension))
        .map_err(candle_error)?;
    let query_tensor =
        Tensor::from_slice(query, (1, ann.dimension), device).map_err(candle_error)?;
    let distances = coarse
        .broadcast_sub(&query_tensor)
        .and_then(|value| value.sqr())
        .and_then(|value| value.sum(1))
        .map_err(candle_error)?;
    let probe_count = ann.config.probes.min(ann.coarse_count);
    if probe_count == 0 {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident IVF-PQ probe count is zero",
        ));
    }
    let probes = scalable_stable_argsort(&distances, true, device, cancellation)?
        .narrow(0, 0, probe_count)
        .map_err(candle_error)?;
    let (ann_positions, probe_ordinals) = ann_probe_positions(ann, &probes, device, cancellation)?;
    let vector_active = vector
        .active
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty vector column has no active tensor"))?
        .narrow(0, 0, vector.rows)
        .and_then(|active| active.eq(1_u8))
        .map_err(candle_error)?;
    let stale_rows = visible_ann_stale_rows(ann, &vector_active, visibility, device, cancellation)?;
    if ann_positions.elem_count() == 0 {
        if stale_rows.elem_count() < limit && probe_count < ann.coarse_count {
            let mut expanded = ann.clone();
            expanded.config.probes = probe_count.saturating_mul(2).min(ann.coarse_count);
            return ann_candidate_rows(
                &expanded,
                vector,
                visibility,
                limit,
                device,
                query,
                cancellation,
            );
        }
        return Ok(stale_rows);
    }
    let all_rows = ann
        .rows
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty ANN image has no source-row tensor"))?;
    if ann.list_positions.as_ref().map_or(0, Tensor::elem_count) != all_rows.elem_count() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident IVF-PQ list postings and source rows have different lengths",
        ));
    }
    let rows = all_rows
        .index_select(&ann_positions, 0)
        .map_err(candle_error)?;
    let visible_ann_rows = visibility.index_select(&rows, 0).map_err(candle_error)?;
    let active_ann_rows = vector_active.index_select(&rows, 0).map_err(candle_error)?;
    let eligible = visible_ann_rows
        .broadcast_mul(&active_ann_rows)
        .and_then(|value| value.gt(0_u8))
        .map_err(candle_error)?;
    let approximate = ann_adc_distances(
        ann,
        &coarse,
        &query_tensor,
        &ann_positions,
        &probes,
        &probe_ordinals,
        cancellation,
    )?;
    let masked = eligible
        .where_cond(
            &approximate,
            &Tensor::full(f32::INFINITY, approximate.elem_count(), device).map_err(candle_error)?,
        )
        .map_err(candle_error)?;
    let candidate_budget = ann
        .config
        .candidate_budget
        .max(limit)
        .min(masked.elem_count());
    if candidate_budget == 0 {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident IVF-PQ candidate budget is zero",
        ));
    }
    let candidate_positions =
        bounded_stable_smallest_positions(&masked, candidate_budget, device, cancellation)?;
    let candidate_rows = rows
        .index_select(&candidate_positions, 0)
        .map_err(candle_error)?;
    let built_versions = ann
        .built_versions
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty ANN image has no built-version tensor"))?
        .index_select(&ann_positions, 0)
        .and_then(|versions| versions.index_select(&candidate_positions, 0))
        .map_err(candle_error)?;
    let current_versions = vector
        .versions
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty vector column has no version tensor"))?
        .narrow(0, 0, vector.rows)
        .and_then(|versions| versions.index_select(&candidate_rows, 0))
        .map_err(candle_error)?;
    let candidate_validity = eligible
        .index_select(&candidate_positions, 0)
        .and_then(|validity| validity.broadcast_mul(&built_versions.eq(&current_versions)?))
        .map_err(candle_error)?;
    let valid_positions = selected_positions(
        &candidate_validity,
        candidate_validity.elem_count(),
        device,
        cancellation,
    )?;
    let candidate_rows = device_index_select(&candidate_rows, &valid_positions, 0)?;
    // Built-version filtering makes these fresh approximate rows disjoint from the compact exact
    // mutable delta.
    ensure_not_cancelled(cancellation)?;
    let candidates = if candidate_rows.elem_count() == 0 {
        stale_rows
    } else if stale_rows.elem_count() == 0 {
        candidate_rows
    } else {
        Tensor::cat(&[&candidate_rows, &stale_rows], 0).map_err(candle_error)?
    };
    // Layer filtering and sparse lists must not turn a requested top-k into an arbitrary
    // short page when more live vectors are available in other lists.
    if candidates.elem_count() < limit && probe_count < ann.coarse_count {
        let mut expanded = ann.clone();
        expanded.config.probes = probe_count.saturating_mul(2).min(ann.coarse_count);
        return ann_candidate_rows(
            &expanded,
            vector,
            visibility,
            limit,
            device,
            query,
            cancellation,
        );
    }
    Ok(candidates)
}

fn visible_ann_stale_rows(
    ann: &AnnIndex,
    vector_active: &Tensor,
    visibility: &Tensor,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    let Some(stale_rows) = ann.stale_row_ids.as_ref() else {
        return Tensor::zeros(0, DType::U32, device).map_err(candle_error);
    };
    if stale_rows.elem_count() == 0 {
        return Tensor::zeros(0, DType::U32, device).map_err(candle_error);
    }
    let visible = visibility
        .index_select(stale_rows, 0)
        .and_then(|visible| visible.broadcast_mul(&vector_active.index_select(stale_rows, 0)?))
        .and_then(|visible| visible.gt(0_u8))
        .map_err(candle_error)?;
    let positions = selected_positions(&visible, stale_rows.elem_count(), device, cancellation)?;
    device_index_select(stale_rows, &positions, 0)
}

fn ann_probe_positions(
    ann: &AnnIndex,
    probes: &Tensor,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<(Tensor, Tensor)> {
    let list_positions = ann
        .list_positions
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty ANN image has no list-position tensor"))?;
    let starts = ann
        .list_offsets
        .index_select(probes, 0)
        .and_then(|values| values.to_dtype(DType::I64))
        .map_err(candle_error)?;
    let next_probes = probes
        .broadcast_add(
            &Tensor::ones(probes.elem_count(), DType::U32, device).map_err(candle_error)?,
        )
        .map_err(candle_error)?;
    let ends = ann
        .list_offsets
        .index_select(&next_probes, 0)
        .and_then(|values| values.to_dtype(DType::I64))
        .map_err(candle_error)?;
    let counts = ends.sub(&starts).map_err(candle_error)?;
    let cumulative = bounded_inclusive_scan_i64(&counts, i64::MAX, device, cancellation)?;
    let total = cumulative
        .narrow(0, cumulative.elem_count() - 1, 1)
        .and_then(|value| value.to_vec1::<i64>())
        .map_err(candle_error)?;
    let total = total
        .first()
        .copied()
        .ok_or_else(|| Error::internal("IVF probed-list row count is absent"))?;
    let total = usize::try_from(total).map_err(|_| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "IVF probed-list row count exceeds host address space",
        )
    })?;
    if total == 0 {
        return Ok((
            Tensor::zeros(0, DType::U32, device).map_err(candle_error)?,
            Tensor::zeros(0, DType::I64, device).map_err(candle_error)?,
        ));
    }
    let output_positions = Tensor::arange(
        0_i64,
        i64::try_from(total).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "IVF probed-list row count exceeds i64",
            )
        })?,
        device,
    )
    .map_err(candle_error)?;
    let probe_rows = sorted_integer_bound(
        &cumulative,
        cumulative.elem_count(),
        &output_positions,
        true,
        device,
        cancellation,
    )?;
    let exclusive = cumulative.sub(&counts).map_err(candle_error)?;
    let output_starts = exclusive
        .index_select(&probe_rows, 0)
        .map_err(candle_error)?;
    let list_starts = starts.index_select(&probe_rows, 0).map_err(candle_error)?;
    let flattened = list_starts
        .add(&output_positions.sub(&output_starts).map_err(candle_error)?)
        // Candle's Metal kernels do not provide I64-indexed selection from U32 pages. IVF list
        // offsets are u32-bounded by admission, so this narrowing is exact and selects the native
        // U32/U32 kernel on every accelerator backend.
        .and_then(|positions| positions.to_dtype(DType::U32))
        .map_err(candle_error)?;
    let positions = list_positions
        .index_select(&flattened, 0)
        .map_err(candle_error)?;
    Ok((positions, probe_rows))
}

fn ann_adc_distances(
    ann: &AnnIndex,
    coarse: &Tensor,
    query: &Tensor,
    positions: &Tensor,
    probes: &Tensor,
    probe_ordinals: &Tensor,
    cancellation: &CancellationToken,
) -> Result<Tensor> {
    let all_rows = ann.rows.as_ref().map_or(0, Tensor::elem_count);
    let rows = positions.elem_count();
    let codes = ann
        .codes
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty ANN image has no PQ code tensor"))?
        .reshape((all_rows, ann.config.subquantizers))
        .and_then(|codes| codes.index_select(positions, 0))
        .map_err(candle_error)?;
    let codebook_values = ann
        .codebook_values
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty ANN image has no PQ codebook tensor"))?;
    if probe_ordinals.elem_count() != rows {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident IVF-PQ probe ordinals and positions differ",
        ));
    }
    let probed_coarse = coarse.index_select(probes, 0).map_err(candle_error)?;
    let mut distances: Option<Tensor> = None;
    for subspace in 0..ann.config.subquantizers {
        ensure_not_cancelled(cancellation)?;
        let (coordinate_start, coordinate_end) =
            ann_subspace_bounds(ann.dimension, ann.config.subquantizers, subspace);
        let width = coordinate_end.saturating_sub(coordinate_start);
        let centroid_start = ann.subspace_centroid_offsets[subspace] as usize;
        let centroid_end = ann.subspace_centroid_offsets[subspace + 1] as usize;
        let centroid_count = centroid_end.saturating_sub(centroid_start);
        let value_start = ann.codebook_vector_offsets[centroid_start] as usize;
        let value_end = ann.codebook_vector_offsets[centroid_end] as usize;
        if width == 0
            || centroid_count == 0
            || value_end.saturating_sub(value_start) != centroid_count.saturating_mul(width)
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident PQ codebook subspace is invalid",
            ));
        }
        let codebook = codebook_values
            .narrow(0, value_start, value_end - value_start)
            .and_then(|values| values.reshape((centroid_count, width)))
            .map_err(candle_error)?;
        let subspace_codes = codes
            .narrow(1, subspace, 1)
            .and_then(|codes| codes.reshape(rows))
            .and_then(|codes| codes.to_dtype(DType::I64))
            .map_err(candle_error)?;
        let query_residuals = query
            .narrow(1, coordinate_start, width)
            .and_then(|query| {
                query.broadcast_sub(&probed_coarse.narrow(1, coordinate_start, width)?)
            })
            .map_err(candle_error)?;
        let lookup = query_residuals
            .unsqueeze(1)
            .and_then(|residuals| residuals.broadcast_sub(&codebook.unsqueeze(0)?))
            .and_then(|delta| delta.sqr())
            .and_then(|distance| distance.sum(2))
            .and_then(|distance| {
                distance.reshape((probes.elem_count().saturating_mul(centroid_count),))
            })
            .map_err(candle_error)?;
        let stride = Tensor::new(
            i64::try_from(centroid_count).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "PQ centroid count exceeds i64",
                )
            })?,
            query.device(),
        )
        .map_err(candle_error)?;
        let lookup_rows = probe_ordinals
            .broadcast_mul(&stride)
            .and_then(|rows| rows.add(&subspace_codes))
            .map_err(candle_error)?;
        let distance = lookup.index_select(&lookup_rows, 0).map_err(candle_error)?;
        distances = Some(match distances {
            Some(total) => total.add(&distance).map_err(candle_error)?,
            None => distance,
        });
    }
    distances.ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "resident PQ codebook has no subspaces",
        )
    })
}

fn score_device_vectors(
    matrix: Option<&Tensor>,
    vector: &VectorColumn,
    query: &[f32],
    limit: usize,
    candidate_rows: Option<&Tensor>,
    device: &Device,
    cancellation: &CancellationToken,
) -> Result<Vec<VectorHit>> {
    if vector.rows == 0 {
        return Ok(Vec::new());
    }
    let full_matrix = matrix
        .ok_or_else(|| Error::internal("non-empty vector column has no value tensor"))?
        .reshape((vector.rows, vector.dimension))
        .map_err(candle_error)?;
    let active = vector
        .active
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty vector column has no active tensor"))?
        .narrow(0, 0, vector.rows)
        .map_err(candle_error)?
        .eq(1_u8)
        .map_err(candle_error)?;
    let candidate_rows = match candidate_rows {
        Some(rows) => {
            if rows.dtype() != DType::U32 {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "vector candidate rows are not compact u32 ordinals",
                ));
            }
            rows.clone()
        }
        None => selected_positions(&active, vector.rows, device, cancellation)?,
    };
    if candidate_rows.elem_count() == 0 {
        return Ok(Vec::new());
    }
    let candidate_active = active
        .index_select(&candidate_rows, 0)
        .map_err(candle_error)?;
    let active_positions = selected_positions(
        &candidate_active,
        candidate_rows.elem_count(),
        device,
        cancellation,
    )?;
    let candidate_rows = device_index_select(&candidate_rows, &active_positions, 0)?;
    let candidate_count = candidate_rows.elem_count();
    if candidate_count == 0 {
        return Ok(Vec::new());
    }
    let matrix = full_matrix
        .index_select(&candidate_rows, 0)
        .map_err(candle_error)?;
    let query_tensor = Tensor::from_slice(query, (vector.dimension, 1), device)
        .and_then(|query| query.to_dtype(matrix.dtype()))
        .map_err(candle_error)?;
    // Canonical coordinates remain resident and execute in their FP16/BF16 dtype. GEMM avoids
    // a rows-by-dimension product temporary; only the row-linear scalar result widens to FP32.
    let dots = matrix
        .matmul(&query_tensor)
        .and_then(|scores| scores.squeeze(1))
        .and_then(|scores| scores.to_dtype(DType::F32))
        .map_err(candle_error)?;
    let scores = match vector.similarity {
        Similarity::Cosine | Similarity::Dot => dots,
        Similarity::Euclidean => {
            let squared_norms = vector
                .squared_norms
                .as_ref()
                .ok_or_else(|| Error::internal("non-empty vector column has no squared norms"))?
                .narrow(0, 0, vector.rows)
                .and_then(|norms| norms.index_select(&candidate_rows, 0))
                .map_err(candle_error)?;
            let query_norm = query.iter().map(|value| value * value).sum::<f32>();
            dots.affine(-2.0, f64::from(query_norm))
                .and_then(|distances| distances.broadcast_add(&squared_norms))
                .and_then(|distances| distances.clamp(0_f32, f32::INFINITY))
                .and_then(|distances| distances.sqrt())
                .map_err(candle_error)?
        }
    };
    let entity_ids = vector
        .entity_ids
        .as_ref()
        .ok_or_else(|| Error::internal("non-empty vector column has no entity tensor"))?
        .narrow(0, 0, vector.rows)
        .and_then(|ids| ids.index_select(&candidate_rows, 0))
        .map_err(candle_error)?;
    // Stable sort by ID first, then by score. The second stable sort preserves unsigned stable-ID
    // order at the score boundary without materializing the candidate set on the host.
    let id_order = scalable_stable_argsort(&entity_ids, true, device, cancellation)?;
    let scores = scores.index_select(&id_order, 0).map_err(candle_error)?;
    let entity_ids = entity_ids
        .index_select(&id_order, 0)
        .map_err(candle_error)?;
    let ascending = vector.similarity == Similarity::Euclidean;
    let result_count = limit.min(candidate_count);
    if result_count == 0 {
        return Ok(Vec::new());
    }
    let rows = scalable_stable_argsort(&scores, ascending, device, cancellation)?
        .narrow(0, 0, result_count)
        .map_err(candle_error)?;
    let final_scores = scores
        .index_select(&rows, 0)
        .and_then(|value| value.to_vec1::<f32>())
        .map_err(candle_error)?;
    let entity_ids = entity_ids
        .index_select(&rows, 0)
        .and_then(|value| value.to_vec1::<i64>())
        .map_err(candle_error)?;
    ensure_not_cancelled(cancellation)?;
    let hits = entity_ids
        .into_iter()
        .zip(final_scores)
        .map(|(entity_id, score)| VectorHit {
            entity_id: (entity_id as u64) ^ (1_u64 << 63),
            score,
        })
        .collect::<Vec<_>>();
    // IVF provides candidates; exact resident reranking determines the public score.
    Ok(hits)
}

pub fn exact_l2(
    device: &Device,
    matrix: &[f32],
    rows: usize,
    dimension: usize,
    query: &[f32],
) -> Result<Vec<f32>> {
    let matrix = Tensor::from_slice(matrix, (rows, dimension), device).map_err(candle_error)?;
    let query = Tensor::from_slice(query, (1, dimension), device).map_err(candle_error)?;
    matrix
        .broadcast_sub(&query)
        .and_then(|value| value.sqr())
        .and_then(|value| value.sum(1))
        .and_then(|value| value.to_vec1::<f32>())
        .map_err(candle_error)
}

/// Device assignment primitive for bounded deterministic IVF-PQ rebuild batches. Distance tiles
/// remain on the selected Metal/CUDA device; only one final assignment per source row returns to
/// the flat-page builder.
pub struct CandleIvfPqBuildKernel<'a> {
    device: &'a Device,
    maximum_distance_tile_bytes: usize,
}

impl<'a> CandleIvfPqBuildKernel<'a> {
    pub fn new(device: &'a Device, maximum_distance_tile_bytes: usize) -> Result<Self> {
        if maximum_distance_tile_bytes < size_of::<f32>() {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "IVF-PQ assignment scratch cannot hold one distance",
            ));
        }
        Ok(Self {
            device,
            maximum_distance_tile_bytes,
        })
    }
}

impl IvfPqBuildKernel for CandleIvfPqBuildKernel<'_> {
    fn assign(
        &mut self,
        vectors: &[f32],
        row_count: usize,
        dimension: usize,
        centroids: &[f32],
        centroid_count: usize,
    ) -> Result<Vec<u32>> {
        let vector_values = row_count.checked_mul(dimension).ok_or_else(|| {
            Error::new(ErrorCode::GpuAdmissionFailure, "IVF vector shape overflow")
        })?;
        let centroid_values = centroid_count.checked_mul(dimension).ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "IVF centroid shape overflow",
            )
        })?;
        if row_count == 0
            || dimension == 0
            || centroid_count == 0
            || vectors.len() != vector_values
            || centroids.len() != centroid_values
            || vectors
                .iter()
                .chain(centroids)
                .any(|value| !value.is_finite())
        {
            return Err(Error::new(
                ErrorCode::IndexUnavailable,
                "IVF-PQ assignment matrices are invalid",
            ));
        }
        let distance_row_bytes = row_count.checked_mul(size_of::<f32>()).ok_or_else(|| {
            Error::new(ErrorCode::GpuAdmissionFailure, "IVF distance row overflow")
        })?;
        let tile_centroids = self
            .maximum_distance_tile_bytes
            .checked_div(distance_row_bytes.max(1))
            .unwrap_or(0)
            .clamp(1, centroid_count);
        let vectors = Tensor::from_slice(vectors, (row_count, dimension), self.device)
            .map_err(candle_error)?;
        let vector_norms = vectors
            .sqr()
            .and_then(|values| values.sum_keepdim(1))
            .map_err(candle_error)?;
        let mut best_distances: Option<Tensor> = None;
        let mut best_centroids: Option<Tensor> = None;
        for start in (0..centroid_count).step_by(tile_centroids) {
            let count = tile_centroids.min(centroid_count - start);
            let coordinate_start = start.checked_mul(dimension).ok_or_else(|| {
                Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "centroid tile offset overflow",
                )
            })?;
            let coordinate_count = count.checked_mul(dimension).ok_or_else(|| {
                Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "centroid tile shape overflow",
                )
            })?;
            let tile = Tensor::from_slice(
                &centroids[coordinate_start..coordinate_start + coordinate_count],
                (count, dimension),
                self.device,
            )
            .map_err(candle_error)?;
            let centroid_norms = tile
                .sqr()
                .and_then(|values| values.sum(1))
                .and_then(|values| values.unsqueeze(0))
                .map_err(candle_error)?;
            let distances = vectors
                .matmul(&tile.t().map_err(candle_error)?)
                .and_then(|dots| dots.affine(-2.0, 0.0))
                .and_then(|distances| distances.broadcast_add(&vector_norms))
                .and_then(|distances| distances.broadcast_add(&centroid_norms))
                .map_err(candle_error)?;
            let tile_distances = distances.min(1).map_err(candle_error)?;
            let centroid_offset = Tensor::full(
                checked_u32(start, "IVF centroid tile")?,
                row_count,
                self.device,
            )
            .map_err(candle_error)?;
            let tile_centroids = distances
                .argmin(1)
                .and_then(|indices| indices.broadcast_add(&centroid_offset))
                .map_err(candle_error)?;
            match (&best_distances, &best_centroids) {
                (Some(current_distances), Some(current_centroids)) => {
                    let replace = tile_distances.lt(current_distances).map_err(candle_error)?;
                    best_distances = Some(
                        replace
                            .where_cond(&tile_distances, current_distances)
                            .map_err(candle_error)?,
                    );
                    best_centroids = Some(
                        replace
                            .where_cond(&tile_centroids, current_centroids)
                            .map_err(candle_error)?,
                    );
                }
                (None, None) => {
                    best_distances = Some(tile_distances);
                    best_centroids = Some(tile_centroids);
                }
                _ => {
                    return Err(Error::internal(
                        "IVF-PQ assignment tile state is inconsistent",
                    ));
                }
            }
        }
        best_centroids
            .ok_or_else(|| Error::internal("IVF-PQ assignment produced no centroid tile"))?
            .to_vec1::<u32>()
            .map_err(candle_error)
    }
}

pub fn candle_error(error: candle_core::Error) -> Error {
    Error::new(ErrorCode::GpuAdmissionFailure, error.to_string())
}

#[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
fn metal_read_u32_words(tensor: &Tensor, offset: usize, count: usize) -> Result<Vec<u32>> {
    let end = offset.checked_add(count).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "Metal control-word read range overflow",
        )
    })?;
    if end > tensor.elem_count() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "Metal control-word read exceeds its workspace",
        ));
    }
    tensor
        .narrow(0, offset, count)
        .and_then(|words| words.copy())
        .and_then(|words| words.to_vec1::<u32>())
        .map_err(candle_error)
}

