    #[test]
    fn reserved_adjacency_tail_tracks_the_actual_cold_prefix_not_canonical_nodes() {
        assert_eq!(
            super::reserved_adjacency_empty_tail(512, 520, 7).expect("valid overlay gap"),
            vec![7; 8]
        );
        let error = super::reserved_adjacency_empty_tail(521, 520, 0)
            .expect_err("a prefix beyond the target must fail");
        assert_eq!(error.code, crate::ErrorCode::CorruptStorage);
    }

    /// Builds a dictionary holding `entries` exactly as the resident image lays one out.
    fn dictionary_of(entries: &[&str]) -> super::StringDictionary {
        let mut bytes = Vec::new();
        let mut offsets = vec![0_u32];
        for entry in entries {
            bytes.extend_from_slice(entry.as_bytes());
            offsets.push(u32::try_from(bytes.len()).expect("test dictionary fits u32"));
        }
        let byte_len = bytes.len();
        super::StringDictionary {
            offsets: Tensor::from_vec(offsets, entries.len() + 1, &Device::Cpu)
                .expect("offsets tensor"),
            bytes: (byte_len > 0)
                .then(|| Tensor::from_vec(bytes, byte_len, &Device::Cpu).expect("bytes tensor")),
            ranks: None,
            maximum_bytes: byte_len,
            host: None,
        }
    }

    #[test]
    fn ordering_by_dictionary_rank_reproduces_byte_lexicographic_order() {
        // STRING `ORDER BY` sorts one gathered integer per row instead of running one radix pass
        // per byte of the widest entry in the dictionary. That substitution is only sound if
        // ordering IDs by rank is indistinguishable from ordering the entries by bytes, so this
        // asserts the equivalence directly rather than asserting the ranks happen to be some
        // permutation.
        //
        // The entries deliberately include the cases the byte-wise radix needed its "byte + 1"
        // sentinel to get right: a string that is a strict prefix of another ("b" before "ba"),
        // the empty string, bytes above ASCII where UTF-8 ordering must follow code-unit order,
        // and one very long entry -- the shape that made this quadratic in the first place, where
        // a single long message body forced thousands of passes over twenty-character names.
        let entries = [
            "gamma",
            "b",
            "",
            "ba",
            "\u{e1}lom",
            "alpha",
            "B",
            "b".repeat(4000).as_str(),
            "zeta",
            "\u{e1}",
        ]
        .into_iter()
        .map(str::to_owned)
        .collect::<Vec<_>>();

        let ranks = super::resident_string_dictionary_ranks(&entries).expect("ranks build");
        assert_eq!(ranks.len(), entries.len());

        // Every rank is used exactly once: a duplicate would silently collapse two distinct
        // strings into one sort position.
        let mut seen = ranks.clone();
        seen.sort_unstable();
        assert_eq!(
            seen,
            (0..u32::try_from(entries.len()).expect("small")).collect::<Vec<_>>(),
            "ranks must be a permutation of 0..n"
        );

        let mut by_rank = (0..entries.len()).collect::<Vec<_>>();
        by_rank.sort_by_key(|id| ranks[*id]);
        let mut by_bytes = (0..entries.len()).collect::<Vec<_>>();
        by_bytes.sort_by(|left, right| entries[*left].as_bytes().cmp(entries[*right].as_bytes()));
        assert_eq!(
            by_rank, by_bytes,
            "ordering by gathered rank must equal ordering by raw bytes"
        );

        // Spot-check the prefix pair explicitly so a regression reads as the real mistake rather
        // than as an opaque vector mismatch.
        let rank_of = |value: &str| {
            ranks[entries
                .iter()
                .position(|entry| entry == value)
                .expect("entry present")]
        };
        assert!(rank_of("") < rank_of("B"), "empty string sorts first");
        assert!(rank_of("B") < rank_of("b"), "uppercase precedes lowercase");
        assert!(
            rank_of("b") < rank_of("ba"),
            "a prefix precedes its extension"
        );
        assert!(
            rank_of("zeta") < rank_of("\u{e1}"),
            "multi-byte follows ASCII"
        );
    }

    #[test]
    fn only_the_named_dictionary_ids_are_resolved() {
        // The point of the targeted lookup: a query returning two strings must not materialise the
        // whole dictionary. Entries are deliberately different lengths so a mistaken offset shows
        // up as wrong text rather than as a panic.
        let dictionary = dictionary_of(&["alpha", "b", "gamma-long", "d"]);
        let wanted = BTreeSet::from([1_u32, 2]);
        let resolved =
            super::resident_string_dictionary_lookup(&dictionary, &wanted).expect("lookup");
        assert_eq!(resolved.len(), 2);
        assert_eq!(resolved.get(&1).map(String::as_str), Some("b"));
        assert_eq!(resolved.get(&2).map(String::as_str), Some("gamma-long"));
    }

    #[test]
    fn every_entry_still_decodes_to_what_it_was_written_as() {
        // Whole-dictionary equivalence with the untargeted decoder it replaced on the read path.
        let entries = ["alpha", "b", "gamma-long", "d", ""];
        let dictionary = dictionary_of(&entries);
        let wanted: BTreeSet<u32> = (0..entries.len() as u32).collect();
        let resolved =
            super::resident_string_dictionary_lookup(&dictionary, &wanted).expect("lookup");
        for (id, expected) in entries.iter().enumerate() {
            assert_eq!(
                resolved.get(&(id as u32)).map(String::as_str),
                Some(*expected),
                "entry {id} decoded wrongly"
            );
        }
    }

    #[test]
    fn an_empty_request_touches_nothing() {
        // A column that is entirely NULL over the returned rows must not transfer bytes at all.
        let dictionary = dictionary_of(&["alpha", "beta"]);
        let resolved = super::resident_string_dictionary_lookup(&dictionary, &BTreeSet::new())
            .expect("lookup");
        assert!(resolved.is_empty());
    }

    #[test]
    fn the_allocator_grows_to_exactly_the_shared_growth_target() {
        // THE anti-drift test. The estimator reserves for `resident_growth_target`; if the
        // allocator ever grows to anything else, the reservation stops covering the allocation and
        // the write path goes back to being killed instead of refused. This pins them together by
        // observing the allocator's real behaviour rather than by reading its source.
        for (start, required) in [(10_usize, 100_usize), (64, 65), (1, 1), (200, 1_000)] {
            let mut tensor =
                Tensor::zeros(start, DType::I64, &Device::Cpu).expect("starting tensor");
            super::ensure_required_capacity(&mut tensor, required, DType::I64, &Device::Cpu)
                .expect("grow");
            // A column that already holds enough is left alone — the allocator early-returns before
            // it ever computes a target, and the estimator's `required <= current_capacity` branch
            // matches that exactly. Getting this wrong in the test is how I learned they agree.
            let expected = if start >= required {
                start
            } else {
                super::resident_growth_target(required)
            };
            assert_eq!(
                tensor.elem_count(),
                expected,
                "growing {start} to hold {required} did not land on the shared growth target"
            );
        }
    }

    #[test]
    fn the_growth_target_is_a_power_of_two_at_or_above_the_floor() {
        assert_eq!(super::resident_growth_target(0), 64);
        assert_eq!(super::resident_growth_target(1), 64);
        assert_eq!(super::resident_growth_target(64), 64);
        assert_eq!(super::resident_growth_target(65), 128);
        assert_eq!(super::resident_growth_target(1_000), 1_024);
        // Written as a shift, not as the expanded decimal: `tests/no_fixed_query_ceiling.rs` scans
        // this directory as TEXT for the removed logical row ceiling, and that ceiling's value is
        // the same power of two. Spelling it out here — in code or in a comment — trips that guard.
        // Deliberately not `next_power_of_two()`, which is the very thing under test.
        assert_eq!(super::resident_growth_target(1_000_000), 1 << 20);
        // Past the largest power of two, the capacity itself rather than a silent smaller value.
        assert_eq!(
            super::resident_growth_target(usize::MAX),
            usize::MAX,
            "an unrepresentable growth target must not be rounded down"
        );
    }

    #[test]
    fn scaling_a_large_resident_saturates_rather_than_wrapping() {
        assert_eq!(super::scale_bytes(1_000, 4, 2), 2_000);
        // Denominator of zero is the "nothing resident yet" case and must not divide.
        assert_eq!(super::scale_bytes(1_000, 4, 0), 1_000);
        // A resident near the address space scaled up must not wrap to something small, which
        // would turn an over-estimate into an under-estimate and defeat the admission check.
        assert_eq!(super::scale_bytes(usize::MAX, 4, 1), usize::MAX);
    }

    #[test]
    fn a_delta_that_adds_no_string_reuses_the_decoded_dictionary() {
        // The ordinary ingest case: re-reading a mailbox re-sees addresses it already holds, and
        // must not pay to decode the whole dictionary again to discover that.
        let mut dictionary = dictionary_of(&["alpha", "beta"]);
        let first = super::resident_string_dictionary_host(&mut dictionary).expect("host");
        let second = super::resident_string_dictionary_host(&mut dictionary).expect("host");
        assert!(
            Arc::ptr_eq(&first, &second),
            "second call rebuilt the dictionary instead of reusing it"
        );
        assert_eq!(first.ids.get("beta"), Some(&1));
    }

    #[test]
    fn growing_the_dictionary_republishes_the_host_view() {
        let mut dictionary = dictionary_of(&["alpha"]);
        let before = super::resident_string_dictionary_host(&mut dictionary).expect("host");
        assert_eq!(before.entries.len(), 1);
        let ids = super::replace_resident_string_dictionary(
            &mut dictionary,
            &["alpha".to_owned(), "beta".to_owned()],
            &Device::Cpu,
        )
        .expect("replace");
        assert_eq!(ids.get("beta"), Some(&1));
        let after = super::resident_string_dictionary_host(&mut dictionary).expect("host");
        assert!(
            !Arc::ptr_eq(&before, &after),
            "stale view served after a grow"
        );
        assert_eq!(after.entries.len(), 2);
        assert_eq!(after.ids.get("beta"), Some(&1));
    }

    #[test]
    fn a_dictionary_swapped_without_republishing_is_decoded_again_not_served_stale() {
        // The entry-count check is the whole safety argument for caching this. If any future path
        // assigns the tensors directly instead of going through the rebuild, the cache must lose
        // rather than hand back strings the device no longer holds.
        let mut dictionary = dictionary_of(&["alpha"]);
        let stale = super::resident_string_dictionary_host(&mut dictionary).expect("host");
        assert_eq!(stale.entries, vec!["alpha".to_owned()]);
        let replacement = dictionary_of(&["one", "two", "three"]);
        dictionary.offsets = replacement.offsets;
        dictionary.bytes = replacement.bytes;
        let fresh = super::resident_string_dictionary_host(&mut dictionary).expect("host");
        assert_eq!(
            fresh.entries,
            vec!["one".to_owned(), "two".to_owned(), "three".to_owned()]
        );
    }

