    #[test]
    fn metal_sparse_derived_delta_shape() -> crate::Result<()> {
        fn vector_backing(rows: usize, dimension: usize) -> SharedVectorBacking {
            let mut entity_ids = PagedVec::default();
            let mut values = PagedVec::default();
            let mut versions = PagedVec::default();
            let mut active = PagedVec::default();
            let one = f16::from_f32(1.0).to_bits();
            for row in 0..rows {
                entity_ids.push(row as u64);
                versions.push(1);
                active.push(true);
                for _ in 0..dimension {
                    values.push(one);
                }
            }
            SharedVectorBacking {
                property: PropertyId(7),
                dimension,
                entity_ids,
                values,
                versions,
                active,
            }
        }

        let dimension = 384;
        let mut small = vector_backing(40, dimension);
        let mut large = vector_backing(40_000, dimension);
        let coordinates = vec![f16::from_f32(2.0).to_bits(); dimension];
        let mutation = ResolvedVectorMutation::Upsert {
            property: PropertyId(7),
            entity_id: 17,
            revision: 2,
            coordinates,
        };
        let mut small_rows = crate::graph::PersistentMap::default();
        let mut large_rows = crate::graph::PersistentMap::default();
        for row in 0..40_000 {
            large_rows.insert_cow(super::stable_id_key(row), row as u32);
            if row < 40 {
                small_rows.insert_cow(super::stable_id_key(row), row as u32);
            }
        }
        super::apply_shared_vector_mutation(&mut small, &mut small_rows, &mutation)?;
        super::apply_shared_vector_mutation(&mut large, &mut large_rows, &mutation)?;
        let range = 17 * dimension..18 * dimension;
        assert_eq!(
            shared_vector_squared_norm(&small, range.clone(), EmbeddingDType::F16)?,
            shared_vector_squared_norm(&large, range, EmbeddingDType::F16)?,
            "norm work for one changed row must not depend on unrelated vector rows"
        );

        let mut temporal = TemporalCanonicalColumn {
            entity_kind: EntityKind::Node,
            target: 1,
            property: PropertyId(9),
            value_type: TemporalType::Integer,
            entity_ids: PagedVec::default(),
            event_times_nanos: PagedVec::default(),
            sequence_indexes: PagedVec::default(),
            values: PropertyColumns::default(),
        };
        let additions = (0..64)
            .map(|row| TemporalSample {
                entity_id: row,
                property: PropertyId(9),
                event_time_nanos: 1_000 - row as i64,
                sequence_index: row + 1,
                value: ScalarValue::Integer(row as i64),
            })
            .collect::<Vec<_>>();
        temporal.extend_and_sort(&additions)?;
        assert_eq!(temporal.len(), additions.len());
        let ordering = (0..temporal.len())
            .map(|row| {
                (
                    *temporal.entity_ids.get(row).expect("entity row"),
                    *temporal.event_times_nanos.get(row).expect("event row"),
                    *temporal.sequence_indexes.get(row).expect("sequence row"),
                )
            })
            .collect::<Vec<_>>();
        assert!(ordering.windows(2).all(|pair| pair[0] <= pair[1]));
        Ok(())
    }

