    #[test]
    fn metal_delete_collected_ordinal_is_sealed_and_gated_on_device() {
        assert_eq!(super::METAL_DELETE_PROGRAM_VERSION, 2);
        assert_eq!(super::METAL_DELETE_OUTPUT_VERSION, 2);
        assert_eq!(
            super::metal_delete_selector(ResidentDeleteTargetSelector::EachSelectedRow),
            (super::METAL_DELETE_SELECTOR_EACH_SELECTED_ROW, 0)
        );
        assert_eq!(
            super::metal_delete_selector(ResidentDeleteTargetSelector::CollectedOrdinal {
                index: 37,
            }),
            (super::METAL_DELETE_SELECTOR_COLLECTED_ORDINAL, 37)
        );

        let metal = include_str!("../../../kernels/metal/operators.metal");
        assert!(metal.contains("IG_DELETE_VERSION = 2ul"));
        let validation = metal
            .split_once("kernel void ig_delete_validate_program_commands(")
            .expect("DELETE command validator disappeared")
            .1
            .split_once("kernel void ig_delete_validate_program_stages(")
            .expect("DELETE command validator boundary disappeared")
            .0;
        for proof in [
            "selector > 1ul",
            "selector == 0ul && selector_index != 0ul",
            "selector_index > IG_DELETE_MAX_DIMENSION",
            "ig_delete_word(program, base + 13ul) != 0ul",
        ] {
            assert!(
                validation.contains(proof),
                "missing selector proof `{proof}`"
            );
        }
        let intents = metal
            .split_once("kernel void ig_delete_explicit_intents(")
            .expect("DELETE explicit-intent kernel disappeared")
            .1
            .split_once("kernel void ig_delete_connectivity(")
            .expect("DELETE explicit-intent kernel boundary disappeared")
            .0;
        let selector_gate = intents
            .find("selector == 1ul && row != selector_index")
            .expect("collected selector gate disappeared");
        let target_binding = intents
            .find("ig_delete_binding_row(")
            .expect("DELETE target binding disappeared");
        assert!(
            selector_gate < target_binding,
            "the collected ordinal must gate target evaluation before intent creation"
        );
    }

