    #[test]
    fn segmented_graph_metal_validation_remains_split_before_materialization() {
        let metal = include_str!("../../../kernels/metal/operators.metal");
        let validation_kernels = [
            "ig_segmented_graph_initialize",
            "ig_segmented_graph_validate_header_shape",
            "ig_segmented_graph_validate_section_layout",
            "ig_segmented_graph_validate_capacity_nullable_header",
            "ig_segmented_graph_validate_bindings_groups",
            "ig_segmented_graph_validate_aggregates_initial",
            "ig_segmented_graph_validate_stages",
            "ig_segmented_graph_validate_expressions_output",
            "ig_segmented_graph_validate_receipts",
        ];
        for name in validation_kernels {
            assert!(
                metal.contains(&format!("kernel void {name}(")),
                "split Metal graph validator `{name}` disappeared"
            );
        }
        assert!(
            !metal.contains("ig_segmented_graph_validate_program("),
            "the monolithic AGX-crashing graph validator returned"
        );

        let source = metal
            .split_once("kernel void ig_segmented_graph_source_program(")
            .expect("Metal graph source kernel disappeared")
            .1
            .split_once("kernel void ig_segmented_graph_finalize_program(")
            .expect("Metal graph finalizer disappeared")
            .0;
        assert!(
            !source.contains("ig_segmented_graph_validate_"),
            "source materialization re-inlined graph contract validation"
        );
        assert!(source.contains("IG_SEGMENTED_GRAPH_VALIDATION_RECEIPTS"));

        let product = metal
            .split_once("inline bool ig_segmented_graph_product(")
            .expect("exact Metal graph product helper disappeared")
            .1
            .split_once("inline bool ig_segmented_graph_advance(")
            .expect("Metal graph product helper boundary disappeared")
            .0;
        assert!(product.contains("uint left_high = uint(left >> 32ul);"));
        assert!(product.contains("return high_product == 0ul;"));
        assert!(
            !product.contains("~0ul / left"),
            "graph product recreated the AGX G_UMULO legalization path"
        );

        let host = include_str!("accelerator.rs");
        let dispatch = host
            .split_once("let dispatch_graph_serial")
            .expect("serial Metal graph dispatcher disappeared")
            .1
            .split_once("let bind_generic")
            .expect("serial Metal graph dispatcher boundary disappeared")
            .0;
        assert!(
            dispatch.contains("encoder.insert_memory_barrier();"),
            "serial Metal graph validation lost its inter-PSO memory barrier"
        );
        let mut cursor = 0usize;
        for name in validation_kernels
            .into_iter()
            .chain(["ig_segmented_graph_source_program"])
        {
            let field = name.strip_prefix("ig_").unwrap_or(name);
            let field = field.strip_suffix("_program").unwrap_or(field);
            let offset = dispatch[cursor..]
                .find(field)
                .unwrap_or_else(|| panic!("Metal graph dispatch omitted or reordered `{field}`"));
            cursor += offset + field.len();
        }
    }

    #[test]
    fn segmented_graph_computed_sources_remain_private_and_padding_safe() {
        let metal = include_str!("../../../kernels/metal/operators.metal");
        let bindings = metal
            .split_once("inline uint ig_segmented_graph_validate_bindings_groups_contract(")
            .expect("segmented binding/group validator disappeared")
            .1
            .split_once("inline uint ig_segmented_graph_validate_aggregates_initial_contract(")
            .expect("segmented binding/group validator boundary disappeared")
            .0;
        for proof in [
            "column != binding_count + property_value_columns + computed_groups",
            "expression_start != expression_cursor",
            "program, expression_start, expression_count, binding_count",
            "source_columns != binding_count + property_value_columns",
            "group_markers + property_value_group_markers != direct_groups",
        ] {
            assert!(
                bindings.contains(proof),
                "missing computed-group proof `{proof}`"
            );
        }

        let aggregates = metal
            .split_once("inline uint ig_segmented_graph_validate_aggregates_initial_contract(")
            .expect("segmented aggregate validator disappeared")
            .1
            .split_once("inline uint ig_segmented_graph_validate_stages_contract(")
            .expect("segmented aggregate validator boundary disappeared")
            .0;
        for proof in [
            "input != binding_count + property_value_columns",
            "+ computed_groups + aggregate",
            "count_all && kind == IG_SEGMENTED_AGGREGATE_COUNT_VALUE",
            "direct_source || computed_source",
            "expression_start == expression_cursor",
            "program, expression_start, expression_count, binding_count",
        ] {
            assert!(
                aggregates.contains(proof),
                "missing computed-reduction proof `{proof}`"
            );
        }

        let source = metal
            .split_once("kernel void ig_segmented_graph_source_program(")
            .expect("segmented graph source kernel disappeared")
            .1
            .split_once("kernel void ig_segmented_graph_finalize_program(")
            .expect("segmented graph source kernel boundary disappeared")
            .0;
        assert!(source.contains("if (encoded_source == ~0ul)"));
        assert!(source.contains("value.tag = IG_SEGMENTED_VALUE_INTEGER;"));
        assert!(source.contains("value.payload = 1ul;"));
        assert!(source.contains("program[descriptor + 1ul]"));
        assert!(source.contains("ig_segmented_graph_evaluate_expression("));
        assert!(source.contains("+ source_columns - 1ul"));

        let padding = source
            .split_once("// Padding duplicates the first real grouping tuple")
            .expect("segmented graph padding block disappeared")
            .1
            .split_once("if (arena_cursor > source_arena_capacity)")
            .expect("segmented graph padding boundary disappeared")
            .0;
        assert!(padding.contains("program[descriptor + 10ul] != 0ul"));
        assert!(padding.contains("source_arena[arena_cursor + byte]"));
        assert!(padding.contains("if ((encoded_group >> 48ul) == 0ul) continue"));
        assert!(padding.contains("ig_segmented_input_cell(source_cells, uint(column))"));
        assert!(
            !padding.contains("for (ulong aggregate"),
            "padding must never populate a reduction shadow"
        );
    }

    #[test]
    fn segmented_graph_property_keys_stays_device_resident_in_one_sealed_command() {
        let host = include_str!("accelerator.rs");
        let executor = host
            .split_once("fn execute_metal_segmented_graph_relation_program(")
            .expect("segmented graph executor disappeared")
            .1
            .split_once("pub fn execute_metal_segmented_aggregation(")
            .expect("segmented graph executor boundary disappeared")
            .0;
        assert_eq!(
            executor
                .matches("execute_metal_segmented_relation_tensor(")
                .count(),
            1,
            "PropertyKeys must enter exactly one segmented CustomOp"
        );
        let nullable_validation = executor
            .split_once("let validated_nullable = if encoded.property_keys.is_some()")
            .expect("PropertyKeys nullable-readback guard disappeared")
            .1
            .split_once("ensure_not_cancelled(cancellation)?;")
            .expect("PropertyKeys nullable-readback guard boundary disappeared")
            .0;
        assert!(nullable_validation.contains("None"));
        assert!(nullable_validation.contains("} else {"));
        assert_eq!(
            nullable_validation
                .matches("nullable.to_vec1::<i64>()")
                .count(),
            1,
            "only the ordinary GraphRelation branch may read back the nullable packet"
        );
        assert!(executor.contains("if let Some(property) = &encoded.property_keys"));
        assert!(executor.contains("property.entity_kind, dependency"));

        let custom_op = host
            .split_once("impl CustomOp3 for MetalSegmentedGraphAggregationProgram")
            .expect("segmented graph CustomOp disappeared")
            .1
            .split_once("struct MetalSegmentedAggregationProgram")
            .expect("segmented graph CustomOp boundary disappeared")
            .0;
        assert_eq!(
            custom_op
                .matches("let encoder = device.command_encoder()?;")
                .count(),
            1,
            "PropertyKeys must use the existing single Metal command encoder"
        );
        assert_eq!(custom_op.matches(".command_encoder()").count(), 1);
        assert!(custom_op.contains("segmented_graph_property_keys_mark"));
        assert!(custom_op.contains("segmented_graph_property_keys_complete"));
        assert!(
            custom_op.contains(
                "encoder.set_compute_pipeline_state(&pipelines.segmented_graph_finalize)"
            )
        );
        assert!(
            !custom_op.contains("wait_until_completed"),
            "the sealed command must not insert an intermediate host synchronization"
        );
    }

    #[test]
    fn segmented_graph_property_keys_kernel_seals_order_cardinality_and_empty_input() {
        let metal = include_str!("../../../kernels/metal/operators.metal");
        let validation = metal
            .split_once("inline uint ig_segmented_graph_validate_bindings_groups_contract(")
            .expect("segmented graph binding validator disappeared")
            .1
            .split_once("inline uint ig_segmented_graph_validate_aggregates_initial_contract(")
            .expect("segmented graph binding validator boundary disappeared")
            .0;
        for proof in [
            "descriptor_count > IG_SEGMENTED_PROPERTY_KEYS_MAX_DESCRIPTORS",
            "program[descriptor - IG_SEGMENTED_PROPERTY_KEYS_DESCRIPTOR_WORDS]",
            "name_offset != name_cursor",
            "!ig_segmented_utf8(",
            "if (equal) return IG_SEGMENTED_GRAPH_STATUS_INVALID_PROGRAM;",
            "observed_maximum != maximum_name_bytes",
        ] {
            assert!(
                validation.contains(proof),
                "missing PropertyKeys proof `{proof}`"
            );
        }

        let mark = metal
            .split_once("kernel void ig_segmented_graph_property_keys_mark(")
            .expect("PropertyKeys presence kernel disappeared")
            .1
            .split_once("kernel void ig_segmented_graph_property_keys_complete(")
            .expect("PropertyKeys presence-kernel boundary disappeared")
            .0;
        for proof in [
            "program[28], descriptor_count, expected_presence",
            "expected_presence == source_capacity",
            "dense != uint(IG_NULLABLE_RELATION_NULL_ROW)",
            "present = property_validity[dense]",
            "presence = row * descriptor_count + descriptor_index",
        ] {
            assert!(
                mark.contains(proof),
                "missing PropertyKeys presence proof `{proof}`"
            );
        }

        let complete = metal
            .split_once("kernel void ig_segmented_graph_property_keys_complete(")
            .expect("PropertyKeys completion kernel disappeared")
            .1
            .split_once("kernel void ig_segmented_graph_finalize_program(")
            .expect("PropertyKeys completion-kernel boundary disappeared")
            .0;
        let emission = complete
            .split_once("ulong emitted_rows = 0ul;")
            .expect("PropertyKeys emission phase disappeared")
            .1;
        let row_loop = emission
            .find("for (ulong row = 0ul; row < entity_rows; ++row)")
            .expect("PropertyKeys row-major loop disappeared");
        let property_loop = emission[row_loop..]
            .find("for (ulong property = 0ul; property < descriptor_count; ++property)")
            .expect("PropertyKeys descriptor-order loop disappeared");
        assert!(
            property_loop > 0,
            "descriptors must remain nested beneath source rows"
        );
        for proof in [
            "if (present == 0u) continue;",
            "count.payload = 1ul;",
            "if (emitted_rows == 0ul) continue;",
            "entity_rows | (entity_rows << 32u)",
            "entity_rows | (emitted_rows << 32u)",
            "emitted_rows | (entity_rows << 32u)",
        ] {
            assert!(
                complete.contains(proof),
                "missing PropertyKeys completion proof `{proof}`"
            );
        }
        let padding = complete
            .split_once("// E=0 deliberately leaves every grouping cell NULL")
            .expect("PropertyKeys empty-input proof disappeared")
            .1
            .split_once("if (source_capacity != 0ul)")
            .expect("PropertyKeys padding boundary disappeared")
            .0;
        assert!(!padding.contains("count.payload"));
    }

    #[test]
    fn resident_active_node_count_tracks_only_changed_rows() -> crate::Result<()> {
        let mut graph = GraphStore::default();
        let label = graph.catalog_mut().intern_label("Vertex")?;
        for id in 1_u64..=4 {
            graph.insert_node(NodeInput {
                id: NodeId(id),
                layer: Layer::Observed,
                revision: 1,
                labels: vec![label],
                properties: Vec::new(),
            })?;
        }
        let device = Device::Cpu;
        let resident = CandleResident::upload(
            ResidentProjectImage::graph_only(Arc::new(graph.snapshot()?)),
            &device,
        )?;
        assert_eq!(resident.active_node_count, 4);

        graph.delete_node(NodeId(2), false, 2)?;
        let staged = resident.stage_delta(
            &ResidentProjectDelta {
                project: ProjectId(uuid::Uuid::nil()),
                bookmark: Bookmark { term: 1, index: 2 },
                graph: graph.device_delta(2)?,
                temporal: Vec::new(),
                vectors: Vec::new(),
                invalidate_derived: false,
            },
            &device,
        )?;
        assert_eq!(staged.active_node_count, 3);

        graph.insert_node(NodeInput {
            id: NodeId(5),
            layer: Layer::Observed,
            revision: 3,
            labels: vec![label],
            properties: Vec::new(),
        })?;
        let staged = staged.stage_delta(
            &ResidentProjectDelta {
                project: ProjectId(uuid::Uuid::nil()),
                bookmark: Bookmark { term: 1, index: 3 },
                graph: graph.device_delta(3)?,
                temporal: Vec::new(),
                vectors: Vec::new(),
                invalidate_derived: false,
            },
            &device,
        )?;
        assert_eq!(staged.active_node_count, 4);
        Ok(())
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn segmented_graph_property_keys_trailer_packs_stable_ids_and_utf8_names() -> crate::Result<()>
    {
        let descriptors = vec![
            crate::ResidentSegmentedPropertyKeyDescriptor {
                property: PropertyId(3),
                name: "a".to_owned(),
            },
            crate::ResidentSegmentedPropertyKeyDescriptor {
                property: PropertyId(9),
                name: "é".to_owned(),
            },
        ];
        let (words, maximum_name_bytes) = super::metal_segmented_property_keys_trailer(
            &descriptors,
            ResidentNullableRelationBindingKind::Relationship,
            0,
            ResidentQuantifierSlot(2),
            ResidentQuantifierSlot(3),
            ResidentQuantifierSlot(4),
            ResidentQuantifierSlot(5),
            ResidentQuantifierSlot(6),
        )?;
        assert_eq!(maximum_name_bytes, 2);
        assert_eq!(words[0], super::METAL_SEGMENTED_PROPERTY_KEYS_MAGIC);
        assert_eq!(words[1], super::METAL_SEGMENTED_PROPERTY_KEYS_VERSION);
        assert_eq!(&words[2..14], &[2, 2, 0, 2, 3, 4, 3, 2, 5, 6, 4, 0]);
        assert_eq!(&words[14..18], &[3, 0, 1, 0]);
        assert_eq!(&words[18..22], &[9, 1, 2, 0]);
        assert_eq!(&words[22].to_le_bytes()[..3], b"a\xc3\xa9");
        assert!(words[22].to_le_bytes()[3..].iter().all(|byte| *byte == 0));

        let mut renamed = descriptors;
        renamed[1].name = "ê".to_owned();
        let (renamed_words, _) = super::metal_segmented_property_keys_trailer(
            &renamed,
            ResidentNullableRelationBindingKind::Relationship,
            0,
            ResidentQuantifierSlot(2),
            ResidentQuantifierSlot(3),
            ResidentQuantifierSlot(4),
            ResidentQuantifierSlot(5),
            ResidentQuantifierSlot(6),
        )?;
        assert_ne!(
            words, renamed_words,
            "descriptor names must remain program-bound"
        );
        Ok(())
    }

