    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn segmented_graph_metal_expression_encodes_every_comparison_opcode() -> crate::Result<()> {
        for (operation, opcode) in [
            (ResidentQuantifierBinary::Equal, 17),
            (ResidentQuantifierBinary::NotEqual, 18),
            (ResidentQuantifierBinary::Less, 19),
            (ResidentQuantifierBinary::LessOrEqual, 20),
            (ResidentQuantifierBinary::Greater, 21),
            (ResidentQuantifierBinary::GreaterOrEqual, 22),
        ] {
            let expression = ResidentQuantifierExpression::Binary {
                left: Box::new(ResidentQuantifierExpression::Slot(ResidentQuantifierSlot(
                    7,
                ))),
                operation,
                right: Box::new(ResidentQuantifierExpression::Literal(
                    ResidentQuantifierValue::Integer(0),
                )),
            };
            let mut instructions = Vec::new();
            let (start, count) =
                super::metal_segmented_graph_expression(&expression, &mut instructions)?;
            assert_eq!((start, count), (0, 3));
            assert_eq!(instructions[0], [1, 7, 0, 0]);
            assert_eq!(instructions[1], [4, 0, 0, 0]);
            assert_eq!(instructions[2], [opcode, 0, 0, 0]);
        }
        Ok(())
    }

