    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn segmented_graph_source_expressions_rewrite_only_proven_binding_slots() -> crate::Result<()> {
        let columns = BTreeMap::from([
            (ResidentQuantifierSlot(7), 1_usize),
            (ResidentQuantifierSlot(9), 0_usize),
        ]);
        let group = ResidentQuantifierExpression::Binary {
            left: Box::new(ResidentQuantifierExpression::Slot(ResidentQuantifierSlot(
                7,
            ))),
            operation: ResidentQuantifierBinary::Modulo,
            right: Box::new(ResidentQuantifierExpression::Literal(
                ResidentQuantifierValue::Integer(3),
            )),
        };
        let reduction = ResidentQuantifierExpression::Binary {
            left: Box::new(ResidentQuantifierExpression::Slot(ResidentQuantifierSlot(
                9,
            ))),
            operation: ResidentQuantifierBinary::Add,
            right: Box::new(ResidentQuantifierExpression::Slot(ResidentQuantifierSlot(
                7,
            ))),
        };
        let mut instructions = Vec::new();
        assert_eq!(
            super::metal_segmented_graph_source_expression(&group, &columns, &mut instructions,)?,
            (0, 3)
        );
        assert_eq!(
            super::metal_segmented_graph_source_expression(
                &reduction,
                &columns,
                &mut instructions,
            )?,
            (3, 3)
        );
        assert_eq!(
            instructions,
            [
                [1, 1, 0, 0],
                [4, 3, 0, 0],
                [14, 0, 0, 0],
                [1, 0, 0, 0],
                [1, 1, 0, 0],
                [10, 0, 0, 0],
            ]
        );

        let missing = ResidentQuantifierExpression::Slot(ResidentQuantifierSlot(8));
        let error =
            super::metal_segmented_graph_source_expression(&missing, &columns, &mut Vec::new())
                .expect_err("an unbound source slot must fail before native dispatch");
        assert_eq!(error.code, ErrorCode::GpuAdmissionFailure);
        Ok(())
    }

