        assert_eq!(super::METAL_SEGMENTED_GRAPH_RECEIPT_SKIP, 5);
        assert_eq!(super::METAL_SEGMENTED_GRAPH_RECEIPT_LIMIT, 6);
        assert_eq!(super::METAL_SEGMENTED_GRAPH_RECEIPT_FILTER, 7);

        let predicate = ResidentQuantifierExpression::Binary {
            left: Box::new(ResidentQuantifierExpression::Slot(ResidentQuantifierSlot(
                9,
            ))),
            operation: ResidentQuantifierBinary::Greater,
            right: Box::new(ResidentQuantifierExpression::Literal(
                ResidentQuantifierValue::Integer(1),
            )),
        };
