        assert!(stage_validation.contains("expected_role = IG_SEGMENTED_GRAPH_RECEIPT_FILTER"));
        assert!(stage_validation.contains("item_start != expression_cursor"));
        assert!(stage_validation.contains("item_count == 0ul"));
        assert!(stage_validation.contains("rows != 0ul"));
        assert!(stage_validation.contains("expression_cursor += item_count"));
        assert!(stage_validation.contains("receipt != expected_receipt"));

        let receipt_validation = metal
            .split_once("inline uint ig_segmented_graph_validate_receipts_contract(")
            .expect("receipt validator disappeared")
            .1
            .split_once("kernel void ig_segmented_graph_initialize(")
            .expect("receipt validator boundary disappeared")
            .0;
