    #[test]
    fn segmented_graph_filter_packed_map_preserves_cycles_subsets_and_consecutive_filters() {
        fn compact<F>(
            rows: &mut [i64],
            order_rows: &mut [u32],
            active_rows: usize,
            keep: F,
        ) -> usize
        where
            F: Fn(i64) -> bool,
        {
            let mut kept_rows = 0_usize;
            for position in 0..active_rows {
                let row = order_rows[position] as usize;
                if keep(rows[row]) {
                    order_rows[kept_rows] = row as u32;
                    kept_rows += 1;
                }
            }
            let mut row_map = (0..rows.len())
                .map(|row| row as u64 | ((row as u64) << 32))
                .collect::<Vec<_>>();
            let set_low = |map: &mut [u64], index: usize, value: usize| {
                map[index] = (map[index] & 0xffff_ffff_0000_0000) | value as u64;
            };
            let set_high = |map: &mut [u64], index: usize, value: usize| {
                map[index] = map[index] as u32 as u64 | ((value as u64) << 32);
            };
            for destination in 0..kept_rows {
                let desired = order_rows[destination] as usize;
                let source = row_map[desired] as u32 as usize;
                let displaced = (row_map[destination] >> 32) as u32 as usize;
                assert!(source >= destination);
                assert_eq!((row_map[source] >> 32) as u32 as usize, desired);
                assert_eq!(row_map[displaced] as u32 as usize, destination);
                if source != destination {
                    rows.swap(source, destination);
                    set_low(&mut row_map, desired, destination);
                    set_low(&mut row_map, displaced, source);
                    set_high(&mut row_map, destination, desired);
                    set_high(&mut row_map, source, displaced);
                }
                order_rows[destination] = destination as u32;
            }
            kept_rows
        }

        for (mut rows, mut order, expected) in [
            (vec![0, 1, 2], vec![2, 0, 1], vec![2, 0, 1]),
            (vec![0, 1, 2, 3], vec![3, 2, 1, 0], vec![3, 2, 1, 0]),
        ] {
            let active = rows.len();
            assert_eq!(compact(&mut rows, &mut order, active, |_| true), active);
            assert_eq!(&rows[..active], expected);
            assert_eq!(&order[..active], (0..active as u32).collect::<Vec<_>>());
        }

        let mut subset_rows = vec![0, 1, 2, 3];
        let mut subset_order = vec![2, 0, 3, 1];
        let kept = compact(&mut subset_rows, &mut subset_order, 4, |value| value != 0);
        assert_eq!(kept, 3);
        assert_eq!(&subset_rows[..kept], &[2, 3, 1]);

        let mut zero_rows = vec![4, 5, 6];
        let mut zero_order = vec![2, 1, 0];
        assert_eq!(compact(&mut zero_rows, &mut zero_order, 3, |_| false), 0);

        let mut consecutive_rows = vec![5, 1, 4, 2, 3];
        let mut consecutive_order = vec![4, 3, 2, 1, 0];
        let first = compact(&mut consecutive_rows, &mut consecutive_order, 5, |value| {
            value % 2 != 0
        });
        assert_eq!(&consecutive_rows[..first], &[3, 1, 5]);
        let second = compact(
            &mut consecutive_rows,
            &mut consecutive_order,
            first,
            |value| value > 1,
        );
        assert_eq!(&consecutive_rows[..second], &[3, 5]);

        // ORDER -> FILTER -> PROJECT keeps the sorted logical order after dense compaction.
        let projected = consecutive_rows[..second]
            .iter()
            .map(|value| value * 10)
            .collect::<Vec<_>>();
        assert_eq!(projected, [30, 50]);

        // FILTER -> ORDER recomputes its permutation over the new dense prefix.
        let mut filter_then_order_rows = vec![4, 1, 3, 2];
        let mut filter_then_order = vec![0, 1, 2, 3];
        let active = compact(
            &mut filter_then_order_rows,
            &mut filter_then_order,
            4,
            |value| value > 1,
        );
        filter_then_order[..active]
            .sort_by_key(|row| std::cmp::Reverse(filter_then_order_rows[*row as usize]));
        assert_eq!(
            filter_then_order[..active]
                .iter()
                .map(|row| filter_then_order_rows[*row as usize])
                .collect::<Vec<_>>(),
            [4, 3, 2]
        );
    }

    #[test]
    fn nullable_relation_packet_scratch_covers_rounded_conversion_cat_and_output_buffers()
    -> crate::Result<()> {
        let graph_words = 4_097_usize;
        let output_words = 8_193_usize;
        let admitted =
            super::metal_nullable_relation_packet_private_bytes(graph_words, output_words)?;
        let graph_upper = graph_words * 4 * std::mem::size_of::<i64>();
        let output_logical = output_words * std::mem::size_of::<i64>();
        let output_allocated = output_logical.next_power_of_two();
        assert_eq!(admitted, graph_upper + 2 * output_allocated);
        assert!(graph_upper >= 2 * graph_words * std::mem::size_of::<i64>());
        assert!(output_allocated >= output_logical);
        Ok(())
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn segmented_graph_scratch_covers_high_reduction_string_shadows_and_every_buffer()
    -> crate::Result<()> {
        const SOURCE_CAPACITY: usize = 4_096;
        const BINDINGS: usize = 2;
        const REDUCTIONS: usize = 64;
        const GROUPS: usize = 1;
        const MAXIMUM_GROUPS: usize = 4_096;
        const SLOTS: usize = 96;
        const PROJECTION_WIDTH: usize = 24;
        const ORDER_WIDTH: usize = 32;
        const STAGES: usize = 4;
        const BINDING_STRING_BYTES: usize = 16;
        const REDUCTION_STRING_BYTES: usize = REDUCTIONS * BINDING_STRING_BYTES;

        let source_arena = SOURCE_CAPACITY
            .checked_mul(BINDING_STRING_BYTES + REDUCTION_STRING_BYTES)
            .ok_or_else(|| Error::internal("scratch fixture source arena overflow"))?;
        let old_unshadowed_arena = SOURCE_CAPACITY * BINDING_STRING_BYTES;
        assert!(source_arena > old_unshadowed_arena * REDUCTIONS);

        let final_cells = MAXIMUM_GROUPS * 4;
        let dependency_records = SOURCE_CAPACITY * BINDINGS;
        let receipt_count = 2 + REDUCTIONS + STAGES;
        let output_layout = super::metal_segmented_graph_output_layout(
            final_cells,
            7,
            dependency_records,
            receipt_count,
        )?;
        assert_eq!(output_layout.arena_storage_bytes, 8);

        let generic = super::MetalSegmentedAggregationArgs {
            input_row_count: SOURCE_CAPACITY as u32,
            input_column_count: (BINDINGS + REDUCTIONS + 1) as u32,
            input_cell_count: (SOURCE_CAPACITY * (BINDINGS + REDUCTIONS + 1)) as u32,
            input_arena_bytes: source_arena as u32,
            grouping_column_count: GROUPS as u32,
            aggregate_count: REDUCTIONS as u32,
            receipt_count: (REDUCTIONS + 1) as u32,
            maximum_output_groups: MAXIMUM_GROUPS as u32,
            maximum_output_cells: (MAXIMUM_GROUPS * (GROUPS + REDUCTIONS)) as u32,
            maximum_output_arena_bytes: (MAXIMUM_GROUPS * BINDING_STRING_BYTES) as u32,
            row_group_capacity: SOURCE_CAPACITY as u32,
            group_first_capacity: MAXIMUM_GROUPS as u32,
            reduction_state_capacity: (MAXIMUM_GROUPS * REDUCTIONS) as u32,
            output_cell_capacity: (MAXIMUM_GROUPS * (GROUPS + REDUCTIONS)) as u32,
            output_arena_capacity: (MAXIMUM_GROUPS * BINDING_STRING_BYTES) as u32,
            receipt_record_capacity: (REDUCTIONS + 1) as u32,
            flags: 0,
            reserved: 0,
        };
        let arguments = super::MetalSegmentedGraphArgs {
            nullable_words: 1,
            node_id_storage_elems: 1,
            edge_id_storage_elems: 1,
            program_words: 2_048,
            source_header_words: super::METAL_SEGMENTED_AGGREGATION_HEADER_WORDS as u64,
            source_cell_words: (SOURCE_CAPACITY
                * (BINDINGS + REDUCTIONS + 1)
                * super::METAL_SEGMENTED_AGGREGATION_CELL_WORDS)
                as u64,
            source_arena_storage_bytes: source_arena as u64,
            generic_receipt_words: ((REDUCTIONS + 1)
                * super::METAL_SEGMENTED_AGGREGATION_RECEIPT_WORDS)
                as u64,
            aggregate_header_words: super::METAL_SEGMENTED_AGGREGATION_HEADER_WORDS as u64,
            aggregate_cell_words: (MAXIMUM_GROUPS
                * (GROUPS + REDUCTIONS)
                * super::METAL_SEGMENTED_AGGREGATION_CELL_WORDS)
                as u64,
            aggregate_arena_storage_bytes: (MAXIMUM_GROUPS * BINDING_STRING_BYTES) as u64,
            slot_cell_words: (MAXIMUM_GROUPS
                * SLOTS
                * super::METAL_SEGMENTED_AGGREGATION_CELL_WORDS)
                as u64,
            projection_result_cell_words: super::metal_segmented_graph_projection_scratch_words(
                MAXIMUM_GROUPS,
                PROJECTION_WIDTH,
                STAGES,
            )? as u64,
            order_row_elems: MAXIMUM_GROUPS as u64,
            order_key_cell_words: (MAXIMUM_GROUPS
                * ORDER_WIDTH
                * super::METAL_SEGMENTED_AGGREGATION_CELL_WORDS)
                as u64,
            output_header_words: super::METAL_SEGMENTED_GRAPH_OUTPUT_HEADER_WORDS as u64,
            output_cell_words: (final_cells * super::METAL_SEGMENTED_AGGREGATION_CELL_WORDS) as u64,
            output_arena_storage_bytes: output_layout.arena_storage_bytes as u64,
            dependency_words: (dependency_records * super::METAL_SEGMENTED_GRAPH_DEPENDENCY_WORDS)
                as u64,
            outer_receipt_words: (receipt_count * super::METAL_SEGMENTED_GRAPH_RECEIPT_WORDS)
                as u64,
            property_presence_bytes: 0,
        };
        let private_logical =
            super::metal_segmented_graph_private_logical_bytes(arguments, generic, output_layout)?;
        assert_eq!(
            arguments.projection_result_cell_words as usize,
            MAXIMUM_GROUPS * PROJECTION_WIDTH * super::METAL_SEGMENTED_AGGREGATION_CELL_WORDS
                + MAXIMUM_GROUPS
                + STAGES
        );
        assert_eq!(
            super::metal_segmented_graph_projection_scratch_words(7, 0, 2)?,
            9,
            "a zero-width projection still owns its row map and stage ledger"
        );
        let required = super::metal_segmented_graph_projection_scratch_words(3, 1, 2)?;
        assert_eq!(required, 14);
        assert!(
            required - 1 < required,
            "one missing map/ledger word must fail capacity"
        );
        assert_eq!(
            private_logical[super::METAL_SEGMENTED_GRAPH_SOURCE_ARENA_ALLOCATION],
            source_arena
        );
        let retained = [
            8 * 1_024 * 1_024,
            arguments.program_words as usize * std::mem::size_of::<u64>(),
            GROUPS.max(1) * std::mem::size_of::<u32>(),
            REDUCTIONS
                * super::METAL_SEGMENTED_AGGREGATION_AGGREGATE_WORDS
                * std::mem::size_of::<u32>(),
            std::mem::size_of::<i64>(),
            std::mem::size_of::<i64>(),
            private_logical[0].next_power_of_two(),
        ];
        let layout = super::MetalSegmentedGraphScratchLayout::build(retained, private_logical)?;
        assert_eq!(layout.retained_bytes[1], 2_048 * std::mem::size_of::<u64>());
        assert_eq!(
            layout.retained_bytes[2],
            GROUPS * std::mem::size_of::<u32>()
        );
        assert_eq!(
            super::METAL_SEGMENTED_AGGREGATION_AGGREGATE_WORDS,
            5,
            "each reduction descriptor retains kind, input, DISTINCT, and both percentile words"
        );
        assert_eq!(
            layout.retained_bytes[3],
            REDUCTIONS * 5 * std::mem::size_of::<u32>()
        );
        assert_eq!(
            layout.retained_bytes[6], layout.private_allocated_bytes[0],
            "Graph output and its shared readback staging use the same rounded size"
        );
        for (logical, allocated) in layout
            .private_logical_bytes
            .iter()
            .zip(layout.private_allocated_bytes)
        {
            assert!(allocated >= *logical);
            assert!(allocated.is_power_of_two());
        }
        let exact_sum = layout
            .retained_bytes
            .into_iter()
            .chain(layout.private_allocated_bytes)
            .sum::<usize>();
        assert_eq!(layout.total_bytes, exact_sum);
        assert!(
            layout
                .retained_bytes
                .into_iter()
                .chain(layout.private_allocated_bytes)
                .all(|allocation| layout.total_bytes >= allocation)
        );
        Ok(())
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn logical_dispatch_chunks_have_no_fixed_row_or_u32_grid_ceiling() -> crate::Result<()> {
        assert!(
            metal_row_mutation_dispatch_chunks(0, 256)
                .map_err(super::candle_error)?
                .is_empty()
        );
        let former_limit_plus_one = (1_usize << 20) + 1;
        let ordinary = metal_row_mutation_dispatch_chunks(former_limit_plus_one, 256)
            .map_err(super::candle_error)?;
        assert_eq!(ordinary.len(), 1);
        assert_eq!(ordinary[0].logical_base, 0);
        assert_eq!(ordinary[0].logical_count, former_limit_plus_one as u64);
        assert_eq!(ordinary[0].group_count, former_limit_plus_one.div_ceil(256));

        let beyond_one_u32_grid = u64::from(u32::MAX) + 17;
        let chunked =
            metal_logical_dispatch_chunks(beyond_one_u32_grid, 256).map_err(super::candle_error)?;
        assert_eq!(chunked.len(), 2);
        assert_eq!(chunked[0].logical_base, 0);
        assert_eq!(chunked[0].logical_count, 4_294_967_040);
        assert_eq!(chunked[0].group_count, 16_777_215);
        assert_eq!(chunked[1].logical_base, 4_294_967_040);
        assert_eq!(chunked[1].logical_count, 272);
        assert_eq!(chunked[1].group_count, 2);
        assert!(metal_row_mutation_dispatch_chunks(1, 0).is_err());
        Ok(())
    }

