    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn quantifier_to_string_admits_scalar_conversions_and_rejects_structural_shapes()
    -> crate::Result<()> {
        let expression = ResidentQuantifierExpression::Function {
            function: crate::ResidentQuantifierFunction::ToString,
            arguments: vec![ResidentQuantifierExpression::Slot(ResidentQuantifierSlot(
                0,
            ))],
        };
        let mut slots = vec![Some(super::MetalQuantifierShape {
            types: super::METAL_QUANTIFIER_TYPE_STRING | super::METAL_QUANTIFIER_TYPE_NULL,
            cells: 1,
            bytes: 32,
            ..super::MetalQuantifierShape::default()
        })];
        let bound = super::metal_quantifier_analyze_expression(&expression, &mut slots, 8)?;
        assert_eq!(
            bound.shape.types,
            super::METAL_QUANTIFIER_TYPE_STRING | super::METAL_QUANTIFIER_TYPE_NULL
        );
        assert_eq!(
            (bound.shape.cells, bound.shape.items, bound.shape.bytes),
            (1, 0, 32)
        );
        assert_eq!(
            (
                bound.allocation.cells,
                bound.allocation.items,
                bound.allocation.bytes,
            ),
            (0, 0, 0),
            "identity conversion must not reserve a second device value"
        );

        for (value, expected_bytes) in [
            (ResidentQuantifierValue::Boolean(true), 5),
            (ResidentQuantifierValue::Integer(1), 20),
            (ResidentQuantifierValue::Float(1.5_f64.to_bits()), 327),
        ] {
            let expression = ResidentQuantifierExpression::Function {
                function: crate::ResidentQuantifierFunction::ToString,
                arguments: vec![ResidentQuantifierExpression::Literal(value)],
            };
            let bound = super::metal_quantifier_analyze_expression(&expression, &mut [], 8)?;
            assert_eq!(bound.shape.types, super::METAL_QUANTIFIER_TYPE_STRING);
            assert_eq!(
                (bound.shape.cells, bound.shape.items, bound.shape.bytes),
                (1, 0, expected_bytes)
            );
            assert_eq!(
                (
                    bound.allocation.cells,
                    bound.allocation.items,
                    bound.allocation.bytes,
                ),
                (1, 0, expected_bytes)
            );
        }

        for value in [
            ResidentQuantifierValue::List(vec![ResidentQuantifierValue::String("text".to_owned())]),
            ResidentQuantifierValue::Map(vec![(
                "key".to_owned(),
                ResidentQuantifierValue::String("value".to_owned()),
            )]),
        ] {
            let expression = ResidentQuantifierExpression::Function {
                function: crate::ResidentQuantifierFunction::ToString,
                arguments: vec![ResidentQuantifierExpression::Literal(value)],
            };
            let error = super::metal_quantifier_analyze_expression(&expression, &mut [], 8)
                .expect_err("structural device conversion must fail static admission");
            assert_eq!(error.code, ErrorCode::GpuAdmissionFailure);
            assert_eq!(
                error.message,
                "Metal toString() has a statically possible structural or entity input type"
            );
        }
        Ok(())
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn quantifier_nested_literal_items_point_to_direct_children() -> crate::Result<()> {
        fn cell(
            encoder: &super::MetalQuantifierEncoder,
            handle: u64,
        ) -> [u64; super::METAL_QUANTIFIER_VALUE_WORDS] {
            assert_ne!(
                handle & super::METAL_QUANTIFIER_IMMUTABLE_HANDLE,
                0,
                "literal child must use the immutable handle namespace"
            );
            encoder.immutable_cells[(handle & !super::METAL_QUANTIFIER_IMMUTABLE_HANDLE) as usize]
        }

        let literal = ResidentQuantifierValue::List(vec![
            ResidentQuantifierValue::List(vec![ResidentQuantifierValue::Integer(2)]),
            ResidentQuantifierValue::Map(vec![(
                "nested".to_owned(),
                ResidentQuantifierValue::List(vec![ResidentQuantifierValue::Integer(-2)]),
            )]),
        ]);
        let mut encoder = super::MetalQuantifierEncoder::default();
        let outer_handle = encoder.encode_value(&literal)?;
        let outer = cell(&encoder, outer_handle);
        assert_eq!([outer[0], outer[2], outer[3]], [5, 2, 0]);
        let outer_base = outer[1] as usize;
        let outer_items = &encoder.immutable_items[outer_base..outer_base + 2];
        assert_eq!(
            outer_items
                .iter()
                .map(|handle| cell(&encoder, *handle)[0])
                .collect::<Vec<_>>(),
            vec![5, 6],
            "an outer list must address its direct list/map children, not their flattened items"
        );

        let inner_list = cell(&encoder, outer_items[0]);
        let inner_list_base = inner_list[1] as usize;
        assert_eq!(
            cell(&encoder, encoder.immutable_items[inner_list_base])[0],
            2
        );

        let map = cell(&encoder, outer_items[1]);
        assert_eq!([map[0], map[2], map[3]], [6, 1, 0]);
        let map_base = map[1] as usize;
        let map_items = &encoder.immutable_items[map_base..map_base + 2];
        assert_eq!(
            map_items
                .iter()
                .map(|handle| cell(&encoder, *handle)[0])
                .collect::<Vec<_>>(),
            vec![4, 5],
            "a map must address its direct key/value pair, not nested value items"
        );
        let nested_list = cell(&encoder, map_items[1]);
        let nested_list_base = nested_list[1] as usize;
        assert_eq!(
            cell(&encoder, encoder.immutable_items[nested_list_base])[0],
            2
        );
        Ok(())
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn quantifier_scratch_uses_reachable_rows_instead_of_the_global_row_budget() -> crate::Result<()>
    {
        use crate::{
            ResidentQuantifierExpression as Expr, ResidentQuantifierGeneration,
            ResidentQuantifierOutput, ResidentQuantifierProgram, ResidentQuantifierProgramRequest,
            ResidentQuantifierProjection, ResidentQuantifierSlot, ResidentQuantifierStage,
            ResidentQuantifierValue as Value,
        };

        let list = |output: u16| ResidentQuantifierStage::Project {
            keep_scope: output != 0,
            bindings: vec![ResidentQuantifierProjection {
                output: ResidentQuantifierSlot(output),
                expression: Expr::List(
                    (0..13)
                        .map(|value| Expr::Literal(Value::Integer(value)))
                        .collect(),
                ),
            }],
        };
        let unwind = |source: u16, output: u16| ResidentQuantifierStage::Unwind {
            expression: Expr::Slot(ResidentQuantifierSlot(source)),
            output: ResidentQuantifierSlot(output),
        };
        let program = ResidentQuantifierProgram {
            slot_count: 6,
            stages: vec![
                list(0),
                unwind(0, 1),
                list(2),
                unwind(2, 3),
                list(4),
                unwind(4, 5),
            ],
            outputs: vec![ResidentQuantifierOutput {
                name: "value".to_owned(),
                source: ResidentQuantifierSlot(5),
            }],
        };
        let graph = GraphStore::default();
        let resident = CandleResident::upload(
            ResidentProjectImage::graph_only(Arc::new(graph.snapshot()?)),
            &Device::Cpu,
        )?;
        let request = ResidentQuantifierProgramRequest::build(
            ResidentQuantifierGeneration {
                project: resident.project,
                bookmark: resident.bookmark,
                graph_revision: resident.revision,
                layout_version: resident.layout_version,
                catalog_generation: [0; 32],
            },
            ResidentExecutionId { high: 1, low: 2 },
            program,
            100_000,
            13,
            3,
        )?;

        let capacity = metal_quantifier_capacity(&request)?;
        assert_eq!(capacity.stage_row_bounds, vec![1, 1, 13, 13, 169, 169]);
        assert_eq!(capacity.final_row_bound, 2_197);
        assert_ne!(capacity.final_row_bound, request.max_rows);

        let plan = MetalQuantifierPlan::build(&resident, &request)?;
        let frame_capacity = plan.expression_count.saturating_add(1).max(2);
        assert_eq!(
            plan.scratch.compare_frame_base - plan.scratch.eval_frame_base,
            capacity.final_row_bound * frame_capacity * METAL_QUANTIFIER_EVAL_FRAME_WORDS,
        );
        assert_eq!(
            plan.scratch.filter_flag_base - plan.scratch.compare_frame_base,
            frame_capacity * METAL_QUANTIFIER_COMPARE_FRAME_WORDS,
        );
        assert_eq!(
            plan.scratch.filter_rank_base - plan.scratch.filter_flag_base,
            capacity.final_row_bound,
        );
        assert_eq!(
            plan.scratch.control_base - plan.scratch.filter_rank_base,
            capacity.final_row_bound,
        );
        let expected_words = 2 * request.max_rows * usize::from(request.program.slot_count)
            + 2 * request.max_rows
            + capacity.dynamic.cells.max(1) * METAL_QUANTIFIER_VALUE_WORDS
            + capacity.dynamic.items.max(1)
            + capacity.dynamic.bytes.max(1).div_ceil(8)
            + capacity.final_row_bound * frame_capacity * METAL_QUANTIFIER_EVAL_FRAME_WORDS
            + frame_capacity * METAL_QUANTIFIER_COMPARE_FRAME_WORDS
            + 2 * capacity.final_row_bound
            + METAL_QUANTIFIER_SCRATCH_CONTROL_WORDS;
        assert_eq!(plan.scratch.words, expected_words);
        Ok(())
    }

