    #[test]
    fn nullable_mixed_string_graph_packet_seals_raw_offsets_and_storage_metadata()
    -> crate::Result<()> {
        let mut graph = GraphStore::default();
        let property = graph.catalog_mut().intern_property("var")?;
        graph.insert_node(NodeInput {
            id: NodeId(1),
            layer: Layer::Observed,
            revision: 1,
            labels: Vec::new(),
            properties: vec![(property, ScalarValue::String(Arc::from("text")))],
        })?;
        graph.insert_node(NodeInput {
            id: NodeId(2),
            layer: Layer::Observed,
            revision: 2,
            labels: Vec::new(),
            properties: vec![(property, ScalarValue::Integer(7))],
        })?;
        let resident = CandleResident::upload(
            ResidentProjectImage::graph_only(Arc::new(graph.snapshot()?)),
            &Device::Cpu,
        )?;
        let encoded = super::EncodedMetalNullableRelation {
            words: Vec::new(),
            label_lanes: Vec::new(),
            property_lanes: vec![crate::ResidentNullableRelationPropertyLane {
                kind: ResidentNullableRelationBindingKind::Node,
                property,
                shape: crate::ResidentNullableRelationPropertyShape::String,
            }],
            candidate_filters_by_stage: Vec::new(),
            candidate_filters_by_group: Vec::new(),
            relation_filters_after: Vec::new(),
            optional_groups: Vec::new(),
            final_columns: Vec::new(),
        };
        let layout = super::metal_nullable_relation_graph_layout(&resident, &encoded)?;
        let descriptors =
            super::metal_nullable_relation_graph_property_lane_words(&resident, &encoded, &layout)?;
        let mixed = resident
            .mixed_nodes
            .get(&property)
            .ok_or_else(|| Error::internal("mixed nullable test property was not resident"))?;
        let mixed_base = layout
            .edge_string_byte_base
            .checked_add(layout.edge_string_byte_count)
            .ok_or_else(|| Error::internal("mixed nullable test layout overflowed"))?;
        let byte_base = mixed_base + resident.node_count + 1;
        let byte_count = mixed.bytes.as_ref().map_or(0, Tensor::elem_count);
        assert_eq!(
            descriptors,
            vec![
                1,
                2,
                property.0,
                0,
                super::METAL_NULLABLE_STRING_STORAGE_MIXED,
                mixed_base as u64,
                byte_base as u64,
                byte_count as u64,
            ]
        );
        assert_eq!(layout.property_descriptor_base, byte_base + byte_count);

        let packet =
            resident.metal_nullable_relation_graph_packet(&Device::Cpu, &encoded, layout)?;
        let words = packet.to_vec1::<i64>().map_err(super::candle_error)?;
        assert_eq!(words.len(), layout.word_count);
        assert_eq!(
            words[layout.property_descriptor_base..],
            descriptors
                .iter()
                .map(|word| *word as i64)
                .collect::<Vec<_>>()
        );
        let offsets = words[mixed_base..byte_base]
            .iter()
            .map(|word| *word as u64)
            .collect::<Vec<_>>();
        assert_eq!(offsets.len(), resident.node_count + 1);
        assert_eq!(offsets[0], 0);
        assert_eq!(offsets[resident.node_count], byte_count as u64);
        assert_eq!(
            words[byte_base] as u64,
            u64::from(crate::graph::MIXED_STRING_TAG)
        );
        assert_ne!(
            words[byte_base + offsets[1] as usize] as u64,
            u64::from(crate::graph::MIXED_STRING_TAG)
        );
        Ok(())
    }

    #[test]
    fn nullable_relationship_type_layout_is_twelve_bytes_and_preserves_u64_tokens()
    -> crate::Result<()> {
        let maximum_rows = 3;
        let final_base = 5;
        let final_byte_count =
            maximum_rows * (std::mem::size_of::<u32>() + std::mem::size_of::<u64>());
        let layouts = super::metal_nullable_relation_final_column_layouts(
            &[ResidentNullableRelationOutputSource::RelationshipType {
                slot: ResidentNullableRelationSlot(7),
            }],
            maximum_rows,
            final_base,
            final_byte_count,
        )?;
        let layout = layouts[0];
        assert_eq!(super::METAL_NULLABLE_OUTPUT_RELATIONSHIP_TYPE, 5);
        assert_eq!(
            layout.source_rows_base,
            final_base * std::mem::size_of::<u64>()
        );
        assert_eq!(
            layout.values_or_offsets_base,
            Some(layout.source_rows_base + 12)
        );
        assert_eq!(layout.bytes_base, None);
        assert_eq!(layout.validity_base, None);
        assert_eq!(layout.end, final_base * std::mem::size_of::<u64>() + 36);

        let values_base = layout
            .values_or_offsets_base
            .ok_or_else(|| Error::internal("relationship-type layout omitted its token lane"))?;
        let tokens = [0_u64, 0x8000_0000_0000_0001, u64::MAX];
        let padded_end =
            layout.end.div_ceil(std::mem::size_of::<u64>()) * std::mem::size_of::<u64>();
        let mut bytes = vec![0_u8; padded_end];
        for (row, token) in tokens.into_iter().enumerate() {
            let start = values_base + row * std::mem::size_of::<u64>();
            bytes[start..start + std::mem::size_of::<u64>()].copy_from_slice(&token.to_le_bytes());
        }
        let words = bytes
            .chunks_exact(std::mem::size_of::<u64>())
            .map(|bytes| i64::from_le_bytes(bytes.try_into().expect("exact u64 word")))
            .collect::<Vec<_>>();
        for (row, token) in tokens.into_iter().enumerate() {
            assert_eq!(
                super::metal_nullable_relation_packet_u64(
                    &words,
                    values_base + row * std::mem::size_of::<u64>(),
                )?,
                token,
            );
        }
        Ok(())
    }

