    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    /// Delegates to the crate-wide Metal guard so every Metal test — in this module and in
    /// `graph_louvain`, `graph_paths`, `graph_components_metrics`, `accelerator_row_proof_tests`,
    /// and the local-model tests — contends for the *same* lock. Two separate mutexes would
    /// provide no mutual exclusion at all, which is precisely the bug this fixes.
    fn metal_sort_test_guard() -> std::sync::MutexGuard<'static, ()> {
        crate::metal_test_guard()
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    fn expected_nullable_i64_order(
        values: &[i64],
        validity: &[u8],
        descending: bool,
        nulls_first: bool,
        limit: usize,
    ) -> Vec<u32> {
        let mut positions = (0..values.len()).collect::<Vec<_>>();
        positions.sort_by(|left, right| {
            let order = match (validity[*left] != 0, validity[*right] != 0) {
                (false, false) => std::cmp::Ordering::Equal,
                (false, true) => {
                    if nulls_first {
                        std::cmp::Ordering::Less
                    } else {
                        std::cmp::Ordering::Greater
                    }
                }
                (true, false) => {
                    if nulls_first {
                        std::cmp::Ordering::Greater
                    } else {
                        std::cmp::Ordering::Less
                    }
                }
                (true, true) => {
                    let order = values[*left].cmp(&values[*right]);
                    if descending { order.reverse() } else { order }
                }
            };
            order.then_with(|| left.cmp(right))
        });
        positions.truncate(limit.min(positions.len()));
        positions
            .into_iter()
            .map(|position| position as u32)
            .collect()
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn metal_stable_selection_matches_cpu_across_partial_blocks() -> crate::Result<()> {
        let _guard = metal_sort_test_guard();
        let Some(device) = crate::metal_test_device() else {
            return Ok(());
        };
        const ROWS: usize = 65_791;
        let mask = (0..ROWS)
            .map(|row| u8::from(row % 251 == 0 || row % 997 == 3 || row + 1 == ROWS))
            .collect::<Vec<_>>();
        let expected = mask
            .iter()
            .enumerate()
            .filter_map(|(row, selected)| (*selected != 0).then_some(row as u32))
            .collect::<Vec<_>>();
        let mask = Tensor::from_slice(&mask, ROWS, &device).map_err(super::candle_error)?;
        let selected = selected_positions(&mask, ROWS, &device, &CancellationToken::new())?
            .to_vec1::<u32>()
            .map_err(super::candle_error)?;
        assert_eq!(selected, expected);

        for value in [0_u8, 1_u8] {
            let mask = Tensor::full(value, ROWS, &device).map_err(super::candle_error)?;
            let selected = selected_positions(&mask, ROWS, &device, &CancellationToken::new())?
                .to_vec1::<u32>()
                .map_err(super::candle_error)?;
            assert_eq!(selected.len(), if value == 0 { 0 } else { ROWS });
            assert!(selected.windows(2).all(|rows| rows[1] == rows[0] + 1));
        }
        Ok(())
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn metal_integer_bounds_match_signed_duplicate_cpu_order() -> crate::Result<()> {
        let _guard = metal_sort_test_guard();
        let Some(device) = crate::metal_test_device() else {
            return Ok(());
        };
        let sorted_values = [i64::MIN, -5, -1, -1, 0, 7, i64::MAX];
        let needle_values = [i64::MIN, -6, -1, 1, i64::MAX];
        let sorted = Tensor::from_slice(&sorted_values, sorted_values.len(), &device)
            .map_err(super::candle_error)?;
        let needles = Tensor::from_slice(&needle_values, needle_values.len(), &device)
            .map_err(super::candle_error)?;
        let lower = super::sorted_integer_bound(
            &sorted,
            sorted_values.len(),
            &needles,
            false,
            &device,
            &CancellationToken::new(),
        )?
        .to_vec1::<i64>()
        .map_err(super::candle_error)?;
        let upper = super::sorted_integer_bound(
            &sorted,
            sorted_values.len(),
            &needles,
            true,
            &device,
            &CancellationToken::new(),
        )?
        .to_vec1::<i64>()
        .map_err(super::candle_error)?;
        assert_eq!(lower, [0, 1, 2, 5, 6]);
        assert_eq!(upper, [1, 1, 4, 5, 7]);
        let initial_low =
            Tensor::from_slice(&[0_i64, 0, 1, 4, 6], 5, &device).map_err(super::candle_error)?;
        let initial_high =
            Tensor::from_slice(&[1_i64, 4, 5, 6, 7], 5, &device).map_err(super::candle_error)?;
        let ranged_lower = super::sorted_integer_bound_ranges(
            &sorted,
            &initial_low,
            &initial_high,
            &needles,
            false,
            &device,
            &CancellationToken::new(),
        )?
        .to_vec1::<i64>()
        .map_err(super::candle_error)?;
        let ranged_upper = super::sorted_integer_bound_ranges(
            &sorted,
            &initial_low,
            &initial_high,
            &needles,
            true,
            &device,
            &CancellationToken::new(),
        )?
        .to_vec1::<i64>()
        .map_err(super::candle_error)?;
        assert_eq!(ranged_lower, [0, 1, 2, 5, 6]);
        assert_eq!(ranged_upper, [1, 1, 4, 5, 7]);
        Ok(())
    }

