    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn metal_radix_sort_and_bounded_top_k_match_adversarial_cpu_order() -> crate::Result<()> {
        let _guard = metal_sort_test_guard();
        const ROWS: usize = 16_411;
        let values = (0..ROWS)
            .map(|position| match position % 17 {
                0 => i64::MIN,
                1 => i64::MAX,
                2..=8 => 7,
                _ => ((position as i64).wrapping_mul(6_364_136_223_846_793_005_i64) >> 19) % 4093,
            })
            .collect::<Vec<_>>();
        let validity = (0..ROWS)
            .map(|position| u8::from(position % 31 != 0 && position % 997 != 0))
            .collect::<Vec<_>>();
        let Some(device) = crate::metal_test_device() else {
            return Ok(());
        };
        let values_tensor =
            Tensor::from_slice(&values, ROWS, &device).map_err(super::candle_error)?;
        let validity_tensor =
            Tensor::from_slice(&validity, ROWS, &device).map_err(super::candle_error)?;
        for (descending, nulls_first) in
            [(false, false), (false, true), (true, false), (true, true)]
        {
            let full = stable_nullable_integer_order(
                &values_tensor,
                &validity_tensor,
                descending,
                nulls_first,
                None,
                &device,
                &CancellationToken::new(),
            )?
            .to_dtype(DType::U32)
            .map_err(super::candle_error)?
            .to_vec1::<u32>()
            .map_err(super::candle_error)?;
            assert_eq!(
                full,
                expected_nullable_i64_order(&values, &validity, descending, nulls_first, ROWS,)
            );

            let top_k = stable_nullable_integer_order(
                &values_tensor,
                &validity_tensor,
                descending,
                nulls_first,
                Some(73),
                &device,
                &CancellationToken::new(),
            )?
            .to_dtype(DType::U32)
            .map_err(super::candle_error)?
            .to_vec1::<u32>()
            .map_err(super::candle_error)?;
            assert_eq!(
                top_k,
                expected_nullable_i64_order(&values, &validity, descending, nulls_first, 73,)
            );
        }

        let cancellation = CancellationToken::new();
        cancellation.cancel();
        let error = stable_nullable_integer_order(
            &values_tensor,
            &validity_tensor,
            false,
            false,
            Some(73),
            &device,
            &cancellation,
        )
        .expect_err("cancelled Metal top-k must not dispatch");
        assert_eq!(error.code, ErrorCode::Cancelled);
        Ok(())
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    fn encoded_test_column(values: &[ResultValue]) -> crate::Result<ResidentOrderColumn> {
        let mut offsets = Vec::with_capacity(values.len() + 1);
        let mut digits = Vec::new();
        let mut validity = Vec::with_capacity(values.len());
        offsets.push(0);
        for value in values {
            digits.extend_from_slice(&encode_total_order_key(value)?);
            offsets.push(u32::try_from(digits.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "encoded test column exceeds u32",
                )
            })?);
            validity.push(u8::from(!matches!(
                value,
                ResultValue::Scalar(ScalarValue::Null)
            )));
        }
        Ok(ResidentOrderColumn {
            offsets,
            digits,
            validity,
        })
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    fn compare_test_key(
        values: &[ResultValue],
        left: usize,
        right: usize,
        descending: bool,
        nulls_first: bool,
    ) -> std::cmp::Ordering {
        let left_null = matches!(values[left], ResultValue::Scalar(ScalarValue::Null));
        let right_null = matches!(values[right], ResultValue::Scalar(ScalarValue::Null));
        match (left_null, right_null) {
            (true, true) => std::cmp::Ordering::Equal,
            (true, false) => {
                if nulls_first {
                    std::cmp::Ordering::Less
                } else {
                    std::cmp::Ordering::Greater
                }
            }
            (false, true) => {
                if nulls_first {
                    std::cmp::Ordering::Greater
                } else {
                    std::cmp::Ordering::Less
                }
            }
            (false, false) => {
                let order = total_compare(&values[left], &values[right]);
                if descending { order.reverse() } else { order }
            }
        }
    }

    #[cfg(all(feature = "accelerator", target_os = "macos"))]
    #[test]
    fn metal_encoded_multikey_radix_matches_total_value_order() -> crate::Result<()> {
        let _guard = metal_sort_test_guard();
        const ROWS: usize = 4_099;
        let primary = (0..ROWS)
            .map(|position| match position % 11 {
                0 => ResultValue::Scalar(ScalarValue::Null),
                1 => ResultValue::Scalar(ScalarValue::Float(OrderedFloat(f64::NEG_INFINITY))),
                2 => ResultValue::Scalar(ScalarValue::Integer((position % 37) as i64 - 18)),
                3 => ResultValue::Scalar(ScalarValue::Float(OrderedFloat(-0.0))),
                4 => ResultValue::Scalar(ScalarValue::String(
                    format!("group\0{:03}", position % 97).into(),
                )),
                5 => ResultValue::Scalar(ScalarValue::Bytes(
                    vec![0, 0xff, (position % 251) as u8].into(),
                )),
                6 => ResultValue::Scalar(ScalarValue::Date((position % 29) as i64 - 14)),
                7 => ResultValue::Scalar(ScalarValue::LocalDateTime {
                    seconds: (position % 31) as i64 - 15,
                    nanos: (position % 1_000) as u32,
                }),
                8 => ResultValue::Scalar(ScalarValue::Duration {
                    months: (position % 7) as i64 - 3,
                    days: (position % 13) as i64 - 6,
                    seconds: position as i64,
                    nanos: (position % 999) as i32,
                }),
                9 => ResultValue::Vector(vec![(position % 17) as f32, -0.0]),
                _ => ResultValue::List(vec![ResultValue::Scalar(ScalarValue::Integer(
                    (position % 23) as i64,
                ))]),
            })
            .collect::<Vec<_>>();
        let secondary = (0..ROWS)
            .map(|position| {
                ResultValue::Scalar(ScalarValue::Integer(((position * 37) % 101) as i64))
            })
            .collect::<Vec<_>>();
        let primary_column = encoded_test_column(&primary)?;
        let secondary_column = encoded_test_column(&secondary)?;
        let Some(device) = crate::metal_test_device() else {
            return Ok(());
        };
        let positions = metal_stable_encoded_argsort(
            &secondary_column,
            None,
            false,
            false,
            &device,
            &CancellationToken::new(),
        )?;
        let actual = metal_stable_encoded_argsort(
            &primary_column,
            Some(positions),
            true,
            true,
            &device,
            &CancellationToken::new(),
        )?
        .to_dtype(DType::U32)
        .map_err(super::candle_error)?
        .to_vec1::<u32>()
        .map_err(super::candle_error)?;

        let mut expected = (0..ROWS).collect::<Vec<_>>();
        expected.sort_by(|left, right| {
            compare_test_key(&primary, *left, *right, true, true)
                .then_with(|| compare_test_key(&secondary, *left, *right, false, false))
                .then_with(|| left.cmp(right))
        });
        assert_eq!(
            actual,
            expected
                .into_iter()
                .map(|position| position as u32)
                .collect::<Vec<_>>()
        );
        Ok(())
    }

